    private static string? OperationCostTemporaryWithdrawal(CardDatabase db)
    {
        using var probes = InstallOperationCostMutationProbes();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int sourceId in new[] { 20, 9999 })
        foreach (int? temporary in new int?[] { null, -3, 0, 2 })
        foreach (int permanent in new[] { 0, 1, 2 })
        foreach (bool otherField in new[] { false, true })
        foreach (bool skip in new[] { false, true })
        foreach (bool skiplog in new[] { false, true })
        foreach (int request in new[] { -7, 0, 105 })
        foreach (bool suppressed in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_t_34", side, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId("card_unit_arado_ar_196", side, 60, side.HqOf(), 1);
            var observer = state.CreateWithId("card_unit_arado_ar_196", side, 70, side.HqOf(), 2);
            foreach (var card in new[] { target, observer }) { card.Keywords.Clear(); SetOperationCostRegistrations(card, true, true); }
            if (suppressed) target.Keywords.Add(Keyword.Suppressed);
            CardBuff? permanentBuff = permanent == 0 ? null : new CardBuff {
                SourceCardId = sourceId, OperationCost = permanent == 1 ? 4 : -1,
                OperationCostSetsAbsoluteValue = permanent == 2 };
            if (permanentBuff is not null) target.BuffsBySource[(sourceId, false)] = permanentBuff;
            if (temporary.HasValue || otherField) target.BuffsBySource[(sourceId, true)] = new CardBuff {
                SourceCardId = sourceId, Temporary = true, OperationCost = temporary ?? 0, Attack = otherField ? 2 : 0 };
            var foreign = new CardBuff { SourceCardId = 30, OperationCost = 6, Attack = 1 };
            target.BuffsBySource[(30, false)] = foreign;
            source.CardsBuffedByThisCard.AddRange(new[] { 888, 60 });
            int removed = -(temporary ?? 0);
            bool changed = removed != 0, notify = changed && !skip;
            int ActionCount() => state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionChangeOperationCost");
            var callbacks = new List<string>(); string? fault = null; var created = state.CardCreated;
            state.CardCreated = spawned => {
                created?.Invoke(spawned);
                if (spawned.Name != "card_unit_routed_troops" || spawned.Location != CardLocation.DeckRight) return;
                var actor = new[] { target, observer }.Single(c => c.BlueprintVariables.GetValueOrDefault("_auditCostActive") is string);
                string phase = (string)actor.BlueprintVariables["_auditCostActive"]!; actor.BlueprintVariables.Remove("_auditCostActive");
                if (ActionCount() != (notify ? 1 : 0)) fault = "通知未先于回调";
                if (!Equals(actor.BlueprintVariables.GetValueOrDefault("_auditCostSource"), sourceId)) fault = "来源ID参数丢失";
                callbacks.Add(phase + ":" + actor.CardId);
            };
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            engine.Api.InvokeByName("ChangeOperationCost", target,
                new object?[] { target, sourceId, request, 4, true, skip, skiplog }, ctx, out bool handled);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionChangeOperationCost").ToArray();
            var expectedCallbacks = changed ? (suppressed ? new[] { "changed:70" } : new[] { "own:60", "changed:70" }) : Array.Empty<string>();
            if (!handled || fault is not null || !callbacks.SequenceEqual(expectedCallbacks)
                || actions.Length != (notify ? 1 : 0)
                || (notify && !actions[0].Values.SequenceEqual(new[] {
                    ActionValue2.Int("cardID", 60), ActionValue2.Int("instigatorID", sourceId), ActionValue2.Int("amount", removed),
                    ActionValue2.Str("changeType", "tempBuffRemove"), ActionValue2.Bool("skipAddToBattlelog", skiplog) })))
                return $"mode4通知/回调错误 source={sourceId},temp={temporary},perm={permanent},other={otherField},skip={skip},log={skiplog},request={request},suppressed={suppressed}: {fault}";
            if (target.BuffsBySource.ContainsKey((sourceId, true)) != otherField
                || (otherField && (target.BuffsBySource[(sourceId, true)].Attack != 2 || target.BuffsBySource[(sourceId, true)].OperationCost != 0))
                || target.BuffsBySource.ContainsKey((sourceId, false)) != (permanent != 0)
                || (permanentBuff is not null && (!ReferenceEquals(target.BuffsBySource[(sourceId, false)], permanentBuff)
                    || permanentBuff.OperationCost != (permanent == 1 ? 4 : -1) || permanentBuff.OperationCostSetsAbsoluteValue != (permanent == 2)))
                || !ReferenceEquals(target.BuffsBySource[(30, false)], foreign) || foreign.OperationCost != 6 || foreign.Attack != 1
                || (sourceId == 20 && !source.CardsBuffedByThisCard.SequenceEqual(permanent != 0 || otherField ? new[] { 888, 60 } : new[] { 888 })))
                return $"mode4误删其他账本或反向名单 source={sourceId},temp={temporary},perm={permanent},other={otherField}";
            // A repeated removal cannot fall back to permanent or emit again.
            engine.Api.InvokeByName("ChangeOperationCost", target,
                new object?[] { target, sourceId, 999, 4, false, false, false }, ctx, out _);
            if (ActionCount() != (notify ? 1 : 0) || !callbacks.SequenceEqual(expectedCallbacks)
                || (permanentBuff is not null && !ReferenceEquals(target.BuffsBySource[(sourceId, false)], permanentBuff)))
                return "重复mode4不得删除永久项或再次通知/回调";
        }
        return null;
    }

    private static string? OperationCostOrdinaryZeroNoOp(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int mode in new[] { 0, 1 })
        foreach (int sourceId in new[] { -1, 0, 20, 9999 })
        foreach (int shape in Enumerable.Range(0, 6))
        foreach (int raw in new[] { -3, 0, 105 })
        foreach (bool relation in new[] { false, true })
        foreach (int flags in Enumerable.Range(0, 8))
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(PlainUnit, side, 60, side.HandOf(), 0);
            var key = (sourceId, mode == 0);
            if (shape != 0) {
                var buff = new CardBuff { SourceCardId = sourceId, Temporary = mode == 0 };
                if (shape == 1) buff.OperationCost = 2;
                if (shape == 2) { buff.OperationCost = -5; buff.OperationCostSetsAbsoluteValue = true; }
                if (shape == 3) buff.AttackSetValue = 0;
                target.BuffsBySource[shape == 4 ? (sourceId, mode != 0) : key] = buff;
            }
            target.OperationCost = raw; target.KreditCost = -9;
            target.Keywords.Add(Keyword.HeavyArmor); // zero request must not recalc unrelated fields either
            source.CardsBuffedByThisCard.Add(888); if (relation) source.CardsBuffedByThisCard.Add(60);
            var original = target.BuffsBySource.ToDictionary(kv => kv.Key, kv => kv.Value);
            string before = state.SnapshotJson(); var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            engine.Api.InvokeByName("ChangeOperationCost", target,
                new object?[] { target, sourceId, 0, mode, (flags & 1) != 0, (flags & 2) != 0, (flags & 4) != 0 },
                new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out bool handled);
            if (!handled || before != state.SnapshotJson() || target.OperationCost != raw || target.KreditCost != -9
                || !target.Keywords.Contains(Keyword.HeavyArmor) || trace.Count != 0 || state.ActionLog.SelectMany(x => x.SubActions).Any()
                || target.BuffsBySource.Count != original.Count || original.Any(kv => !target.BuffsBySource.TryGetValue(kv.Key, out var value) || !ReferenceEquals(value, kv.Value))
                || (shape == 2 && (original[key].OperationCost != -5 || !original[key].OperationCostSetsAbsoluteValue))
                || !source.CardsBuffedByThisCard.SequenceEqual(relation ? new[] { 888, 60 } : new[] { 888 }))
                return $"普通零行动费必须完全不变 side={side},mode={mode},source={sourceId},shape={shape},raw={raw},relation={relation},flags={flags}";
        }
        return null;
    }

    private static string? OperationCostOrdinaryCancellation(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int mode in new[] { 0, 1 })
        foreach (int sourceId in new[] { 20, 9999 })
        foreach (int previous in new[] { -3, 2 })
        foreach (int otherField in Enumerable.Range(0, 4))
        foreach (bool oppositeSlot in new[] { false, true })
        foreach (bool skip in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(PlainUnit, side, 60, side.HandOf(), 0);
            var key = (sourceId, mode == 0);
            var chosen = new CardBuff { SourceCardId = sourceId, Temporary = mode == 0, OperationCost = previous,
                AttackSetValue = otherField == 1 ? 0 : null, HeavyArmor = otherField == 2 ? 2 : 0, KreditCost = otherField == 3 ? -2 : 0 };
            target.BuffsBySource[key] = chosen;
            var opposite = new CardBuff { SourceCardId = sourceId, Temporary = mode != 0, OperationCost = 4, Attack = 1 };
            if (oppositeSlot) target.BuffsBySource[(sourceId, mode != 0)] = opposite;
            var foreign = new CardBuff { SourceCardId = 30, OperationCost = 2 };
            target.BuffsBySource[(30, false)] = foreign;
            source.CardsBuffedByThisCard.AddRange(new[] { 888, 60 });
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            engine.Api.InvokeByName("ChangeOperationCost", target,
                new object?[] { target, sourceId, -previous, mode, false, skip, false }, ctx, out bool handled);
            bool retained = otherField != 0;
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionChangeOperationCost").ToArray();
            if (!handled || target.BuffsBySource.ContainsKey(key) != retained || chosen.OperationCost != 0
                || (retained && (!ReferenceEquals(target.BuffsBySource[key], chosen)
                    || chosen.AttackSetValue != (otherField == 1 ? 0 : null) || chosen.HeavyArmor != (otherField == 2 ? 2 : 0) || chosen.KreditCost != (otherField == 3 ? -2 : 0)))
                || (oppositeSlot && (!ReferenceEquals(target.BuffsBySource[(sourceId, mode != 0)], opposite) || opposite.OperationCost != 4 || opposite.Attack != 1))
                || !ReferenceEquals(target.BuffsBySource[(30, false)], foreign) || foreign.OperationCost != 2
                || (sourceId == 20 && !source.CardsBuffedByThisCard.SequenceEqual(retained || oppositeSlot ? new[] { 888, 60 } : new[] { 888 }))
                || actions.Length != (skip ? 0 : 1)
                || (!skip && !actions[0].Values.SequenceEqual(new[] { ActionValue2.Int("cardID", 60), ActionValue2.Int("instigatorID", sourceId),
                    ActionValue2.Int("amount", -previous), ActionValue2.Str("changeType", mode == 0 ? "tempBuffGive" : "permBuff"), ActionValue2.Bool("skipAddToBattlelog", false) })))
                return $"普通行动费抵消错误 side={side},mode={mode},source={sourceId},old={previous},other={otherField},opposite={oppositeSlot},skip={skip}";
            string after = state.SnapshotJson(); int count = target.BuffsBySource.Count;
            engine.Api.InvokeByName("ChangeOperationCost", target, new object?[] { target, sourceId, 0, mode, false, false, false }, ctx, out _);
            if (after != state.SnapshotJson() || target.BuffsBySource.Count != count)
                return "抵消后的零请求不得重建账本";
        }
        return null;
    }

    private static string? OperationCostPublicEntry(CardDatabase db)
    {
        using var probes = InstallOperationCostMutationProbes();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int variant in Enumerable.Range(0, 7))
        foreach (int zone in Enumerable.Range(0, 6))
        foreach (int delta in new[] { -3, 0, 2, 105 })
        foreach (int raw in new[] { 0, 99 })
        foreach (bool covert in new[] { false, true })
        foreach (bool revealed in new[] { false, true })
        foreach (bool suppressed in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 20, CardLocation.Discard, 0);
            var detached = state.CreateWithId(PlainUnit, side, 9999, CardLocation.Discard, 0); state.Remove(detached);
            var locations = new[] { CardLocation.NotAvailable, side.DeckOf(), side.HandOf(), side.HqOf(), CardLocation.BoardFrontline, CardLocation.Discard };
            var target = state.CreateWithId("card_unit_arado_ar_196", side, 60, locations[zone], 1);
            var observer = state.CreateWithId("card_unit_arado_ar_196", side, 70, side.HqOf(), 2);
            foreach (var card in new[] { target, observer }) { card.Keywords.Clear(); SetOperationCostRegistrations(card, true, true); }
            if (covert) target.Keywords.Add(Keyword.Covert); target.IsRevealed = revealed;
            if (suppressed) target.Keywords.Add(Keyword.Suppressed);
            target.OperationCost = raw;
            source.CardsBuffedByThisCard.Add(888); detached.CardsBuffedByThisCard.Add(888);
            int id = variant switch { 0 => -7, 1 or 4 => 0, 2 or 5 => 20, _ => 9999 };
            bool changed = id > 0 && (!covert || revealed) && delta != 0;
            var callbacks = new List<string>(); string? fault = null; var created = state.CardCreated;
            state.CardCreated = spawned => {
                created?.Invoke(spawned);
                if (spawned.Name != "card_unit_routed_troops" || spawned.Location != CardLocation.DeckRight) return;
                var actor = new[] { target, observer }.Single(c => c.BlueprintVariables.GetValueOrDefault("_auditCostActive") is string);
                string phase = (string)actor.BlueprintVariables["_auditCostActive"]!; actor.BlueprintVariables.Remove("_auditCostActive");
                if (!Equals(actor.BlueprintVariables.GetValueOrDefault("_auditCostSource"), id)) fault = "来源ID丢失";
                if (state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionChangeOperationCost") != 1) fault = "通知未先于回调";
                callbacks.Add(phase + ":" + actor.CardId);
            };
            string before = state.SnapshotJson();
            if (variant < 4) engine.Api.ChangeOperationCost(target, delta, id);
            else engine.Api.ChangeOperationCost(target, delta, variant == 4 ? null : variant == 5 ? source : detached);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionChangeOperationCost").ToArray();
            var expected = changed ? (suppressed ? new[] { "changed:70" } : new[] { "own:60", "changed:70" }) : Array.Empty<string>();
            if (fault is not null || !callbacks.SequenceEqual(expected) || actions.Length != (changed ? 1 : 0)
                || (!changed && (before != state.SnapshotJson() || target.OperationCost != raw || target.BuffsBySource.Count != 0))
                || (changed && (!actions[0].Values.SequenceEqual(new[] { ActionValue2.Int("cardID", 60), ActionValue2.Int("instigatorID", id),
                    ActionValue2.Int("amount", delta), ActionValue2.Str("changeType", "permBuff"), ActionValue2.Bool("skipAddToBattlelog", false) })
                    || !target.BuffsBySource.TryGetValue((id, false), out var buff) || buff.OperationCost != delta))
                || !source.CardsBuffedByThisCard.SequenceEqual(changed && id == 20 ? new[] { 888, 60 } : new[] { 888 })
                || !detached.CardsBuffedByThisCard.SequenceEqual(new[] { 888 }))
                return $"公开行动费入口错误 variant={variant},side={side},zone={zone},delta={delta},raw={raw},covert={covert},revealed={revealed},suppressed={suppressed}: {fault}";
        }
        return null;
    }

    private static string? OperationCostPublicLedgerLifecycle(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool objectOverload in new[] { false, true })
        foreach (int amount in new[] { -3, 2 })
        foreach (bool otherField in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(PlainUnit, side, 60, side.HandOf(), 0);
            source.CardsBuffedByThisCard.Add(888);
            if (otherField) target.BuffsBySource[(20, false)] = new CardBuff { SourceCardId = 20, AttackSetValue = 0 };
            void Apply(int delta) { if (objectOverload) engine.Api.ChangeOperationCost(target, delta, source); else engine.Api.ChangeOperationCost(target, delta, 20); }
            Apply(amount); Apply(-amount);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionChangeOperationCost").ToArray();
            if (target.BuffsBySource.ContainsKey((20, false)) != otherField
                || (otherField && (target.BuffsBySource[(20, false)].AttackSetValue != 0 || target.BuffsBySource[(20, false)].OperationCost != 0))
                || !source.CardsBuffedByThisCard.SequenceEqual(otherField ? new[] { 888, 60 } : new[] { 888 })
                || actions.Length != 2 || actions[0].Values[2] != ActionValue2.Int("amount", amount) || actions[1].Values[2] != ActionValue2.Int("amount", -amount))
                return $"公开行动费累计/抵消错误 side={side},object={objectOverload},amount={amount},other={otherField}";
            string before = state.SnapshotJson(); target.OperationCost = 105; before = state.SnapshotJson(); Apply(0);
            if (state.SnapshotJson() != before || target.OperationCost != 105)
                return "公开行动费抵消后的零请求不得重建来源或重算";
        }
        return null;
    }

    private static string? OperationCostSplitNumericReference(CardDatabase db)
    {
        using var doc = System.Text.Json.JsonDocument.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,
            "Fixtures", "operation-cost-numeric-reference-20261023.json")));
        var get = typeof(KismetVm).GetMethod("GetMember", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic)!;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (var row in doc.RootElement.EnumerateArray())
        {
            var inputs = row.GetProperty("inputs").EnumerateArray().Select(x => x.GetInt32()).ToArray();
            int basis = inputs[0], temp = inputs[1], request = inputs[2], mode = inputs[3], removed = inputs[4];
            int expectedBase = row.GetProperty("base").GetInt32(), expectedTemp = row.GetProperty("temp").GetInt32();
            int expectedTotal = row.GetProperty("total").GetInt32(); bool changed = row.GetProperty("changed").GetBoolean();
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(PlainUnit, side, 60, side.HandOf(), 0);
            source.Definition = new CardDefinition { Name = source.Name, Type = "infantry" };
            target.Definition = new CardDefinition { Name = target.Name, Type = "infantry", OperationCost = 17 };
            target.Keywords.Clear(); target.Keywords.Add(Keyword.Suppressed);
            target.BaseOperationCost = basis; target.TemporaryOperationCost = temp;
            if (mode == 4) target.BuffsBySource[(20, true)] = new CardBuff { SourceCardId = 20, Temporary = true, OperationCost = -removed, Attack = 1 };
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            engine.Api.InvokeByName("ChangeOperationCost", target, new object?[] { target, 20, request, mode, false, false, false }, ctx, out bool handled);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionChangeOperationCost").ToArray();
            if (!handled || target.BaseOperationCost != expectedBase || target.TemporaryOperationCost != expectedTemp
                || target.TotalOperationCost != expectedTotal || actions.Length != (changed ? 1 : 0)
                || (changed && actions[0].Values[2] != ActionValue2.Int("amount", mode == 4 ? removed : request))
                || !Equals(get.Invoke(null, new object?[] { target, "operationCost" }), expectedBase)
                || !Equals(get.Invoke(null, new object?[] { target, "operationCostBuff" }), expectedTemp))
                return $"行动费原生参考不符 side={side},input={string.Join(',', inputs)} actual={target.BaseOperationCost}/{target.TemporaryOperationCost}/{target.TotalOperationCost}";
            var snap = target.Snapshot();
            if (snap.BaseOperationCost != expectedBase || snap.TemporaryOperationCost != expectedTemp)
                return "行动费快照丢失原始分量";
            // Native numeric fields cannot be reconstructed from remaining keys.
            target.BuffsBySource[(888, false)] = new CardBuff { SourceCardId = 888, OperationCost = 77 };
            target.RecalculateStats();
            if (target.BaseOperationCost != expectedBase || target.TemporaryOperationCost != expectedTemp || target.TotalOperationCost != expectedTotal)
                return "无关重算覆盖独立行动费字段";
        }
        return null;
    }

