        foreach (int temp in new[] { int.MinValue, -4, 0, 7, int.MaxValue })
        foreach (int templateTemp in new[] { -4, 0, 7 })
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId(PlainUnit, side, 60, side.HandOf(), 0);
            if (card.BaseOperationCost != card.Definition.OperationCost || card.TemporaryOperationCost != card.Definition.OperationCostBuff)
                return "建卡行动费分量初始化错误";
            card.Definition = new CardDefinition { Name = card.Name, Type = "infantry", OperationCost = 17, OperationCostBuff = templateTemp };
            card.InitializeFromDefinition();
            if (card.BaseOperationCost != 17 || card.TemporaryOperationCost != templateTemp)
                return "初始化不得丢失非零模板临时行动费";
            card.BaseOperationCost = basis; card.TemporaryOperationCost = temp;
            var duplicate = (CardInstance)copy.Invoke(null, new object[] { card })!;
            if (duplicate.BaseOperationCost != basis || duplicate.TemporaryOperationCost != temp || duplicate.TotalOperationCost != card.TotalOperationCost)
                return "复制行动费时压平原始分量";
            duplicate.RecalculateStats();
            if (duplicate.BaseOperationCost != basis || duplicate.TemporaryOperationCost != temp)
                return "复制后重算覆盖行动费分量";
            duplicate.BaseOperationCost = 12;
            if (card.BaseOperationCost != basis) return "复制行动费数值并非独立字段";
            card.ResetAttributes();
            if (card.BaseOperationCost != card.Definition.OperationCost || card.TemporaryOperationCost != templateTemp)
                return "重置未分别复制模板基础/临时行动费";
        }
        return null;
    }

    private static string? OperationCostAbsoluteLedgerMatrix(CardDatabase db)
    {
        var zero = new CardBuff { SourceCardId = 20, OperationCostSetValue = 0 };
        if (zero.IsEmpty || zero.Clone().OperationCostSetValue != 0) return "SetValue零键的存在/Clone丢失";
        zero.OperationCostSetValue = null;
        if (!zero.IsEmpty) return "SetValue缺失不得伪造键存在";
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int cm in Enumerable.Range(0, 32))
        foreach (int om in Enumerable.Range(0, 32))
        foreach (int mode in new[] { 2, 3, 5 })
        foreach (int request in new[] { -3, 0, 105 })
        foreach (int id in new[] { 20, 9999 })
        foreach (bool equal in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 20, CardLocation.Discard, 0);
            var foreign = state.CreateWithId(PlainUnit, side, 30, CardLocation.Discard, 0);
            var target = state.CreateWithId(PlainUnit, side, 60, side.HandOf(), 0);
            foreach (var card in new[] { source, foreign, target }) card.Definition = new CardDefinition { Name = card.Name, Type = "infantry" };
            target.Keywords.Clear(); target.Keywords.Add(Keyword.Suppressed);
            void Seed(int sourceId, int mask) {
                if ((mask & 27) != 0) target.BuffsBySource[(sourceId, false)] = new CardBuff { SourceCardId = sourceId,
                    OperationCost = (mask & 1) != 0 ? 2 : 0, OperationCostSetValue = (mask & 2) != 0 ? 0 : null,
                    AttackSetValue = (mask & 8) != 0 ? 0 : null, HasSuppressLedgerEntry = (mask & 16) != 0 };
                if ((mask & 4) != 0) target.BuffsBySource[(sourceId, true)] = new CardBuff { SourceCardId = sourceId, Temporary = true, OperationCost = 3 };
            }
            Seed(id, cm); Seed(30, om);
            var unrelated = new CardBuff { SourceCardId = 99, DefenseSetValue = 0 };
            target.BuffsBySource[(99, false)] = unrelated;
            source.CardsBuffedByThisCard.AddRange(new[] { 888, 60 }); foreign.CardsBuffedByThisCard.AddRange(new[] { 60, 60, 888 });
            target.BaseOperationCost = equal ? request : 5; target.TemporaryOperationCost = -4;
            engine.Api.InvokeByName("ChangeOperationCost", target, new object?[] { target, id, request, mode, false, false, false },
                new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out bool handled);
            bool currentPerm = mode != 5 || (cm & 24) != 0;
            bool foreignPerm = (om & 8) != 0 || (mode != 3 && (om & 16) != 0);
            int? currentSet = mode == 2 ? request : mode == 3 && (cm & 2) != 0 ? 0 : null;
            bool currentSuppress = mode == 3 || (cm & 16) != 0;
            bool currentRelation = currentPerm || (cm & 4) != 0;
            int? Field(CardBuff? b) => b?.OperationCostSetValue;
            target.BuffsBySource.TryGetValue((id, false), out var current);
            target.BuffsBySource.TryGetValue((30, false), out var other);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionChangeOperationCost").ToArray();
            var snap = target.Snapshot();
            if (!handled || (current is not null) != currentPerm || (other is not null) != foreignPerm
                || (current is not null && (current.OperationCost != (mode != 5 && (cm & 1) != 0 ? 2 : 0)
                    || Field(current) != currentSet || current.HasSuppressLedgerEntry != currentSuppress
                    || current.AttackSetValue != ((cm & 8) != 0 ? 0 : null) || current.OperationCostSetsAbsoluteValue))
                || (other is not null && (other.OperationCost != 0 || Field(other).HasValue
                    || other.HasSuppressLedgerEntry != (mode != 3 && (om & 16) != 0) || other.AttackSetValue != ((om & 8) != 0 ? 0 : null)))
                || target.BuffsBySource.ContainsKey((id, true)) != ((cm & 4) != 0)
                || ((cm & 4) != 0 && target.BuffsBySource[(id, true)].OperationCost != 3)
                || target.BuffsBySource.ContainsKey((30, true)) != ((om & 4) != 0)
                || ((om & 4) != 0 && target.BuffsBySource[(30, true)].OperationCost != 3)
                || target.BuffsBySource.Count != 1 + (currentPerm ? 1 : 0) + (foreignPerm ? 1 : 0) + ((cm & 4) != 0 ? 1 : 0) + ((om & 4) != 0 ? 1 : 0)
                || !ReferenceEquals(target.BuffsBySource[(99, false)], unrelated) || unrelated.DefenseSetValue != 0
                || !source.CardsBuffedByThisCard.SequenceEqual(id != 20 || currentRelation ? new[] { 888, 60 } : new[] { 888 })
                || !foreign.CardsBuffedByThisCard.SequenceEqual(new[] { 60, 60, 888 })
                || snap.OperationCostSetValuesBySource.Count != (currentSet.HasValue ? 1 : 0)
                || (currentSet.HasValue && snap.OperationCostSetValuesBySource.GetValueOrDefault($"{id}/False", int.MinValue) != currentSet)
                || target.BaseOperationCost != (equal ? request : Math.Clamp(request, 0, 99)) || target.TemporaryOperationCost != -4
                || actions.Length != (equal ? 0 : 1))
                return $"行动费绝对账本矩阵错误 side={side},cm={cm},om={om},mode={mode},request={request},source={id},equal={equal}";
        }
        return null;
    }

    private static string? OperationCostTypedCoexistence(CardDatabase db)
    {
        var copy = typeof(CardApi).GetMethod("CopyForStealSide", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic)!;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int id in new[] { 20, 9999 })
        foreach (bool otherField in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(PlainUnit, side, 60, side.HandOf(), 0);
            foreach (var card in new[] { source, target }) card.Definition = new CardDefinition { Name = card.Name, Type = "infantry" };
            target.Keywords.Clear(); target.Keywords.Add(Keyword.Suppressed);
            target.BaseOperationCost = 5; target.TemporaryOperationCost = 3;
            target.BuffsBySource[(id, false)] = new CardBuff { SourceCardId = id, OperationCost = 2, AttackSetValue = otherField ? 0 : null };
            target.BuffsBySource[(id, true)] = new CardBuff { SourceCardId = id, Temporary = true, OperationCost = 3 };
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            void Apply(int amount, int mode) => engine.Api.InvokeByName("ChangeOperationCost", target,
                new object?[] { target, id, amount, mode, false, true, false }, ctx, out _);
            Apply(0, 2);
            if (target.BaseOperationCost != 0 || target.TemporaryOperationCost != 3
                || target.BuffsBySource[(id, false)].OperationCost != 2 || target.BuffsBySource[(id, false)].OperationCostSetValue != 0)
                return "绝对设值必须保留缓存来源普通键和临时数值";
            Apply(-2, 1);
            if (target.BaseOperationCost != 0 || target.BuffsBySource[(id, false)].OperationCost != 0
                || target.BuffsBySource[(id, false)].OperationCostSetValue != 0 || target.BuffsBySource[(id, false)].IsEmpty)
                return "普通抵消不得删除SetValue零键";
            Apply(2, 1); Apply(999, 4);
            if (target.BaseOperationCost != 2 || target.TemporaryOperationCost != 0 || target.TotalOperationCost != 2
                || target.BuffsBySource[(id, false)].OperationCost != 2 || target.BuffsBySource[(id, false)].OperationCostSetValue != 0
                || target.BuffsBySource.ContainsKey((id, true))) return "临时撤销不得重算基础或删独立SetValue";
            var duplicate = (CardInstance)copy.Invoke(null, new object[] { target })!;
            if (ReferenceEquals(duplicate.BuffsBySource[(id, false)], target.BuffsBySource[(id, false)])
                || duplicate.BuffsBySource[(id, false)].OperationCostSetValue != 0) return "复制未隔离SetValue键";
            duplicate.BuffsBySource[(id, false)].OperationCostSetValue = 7;
            if (target.BuffsBySource[(id, false)].OperationCostSetValue != 0) return "复制SetValue修改污染原卡";
            Apply(5, 5);
            if (target.BaseOperationCost != 5 || target.TemporaryOperationCost != 0 || target.BuffsBySource.ContainsKey((id, false)) != otherField
                || (otherField && (target.BuffsBySource[(id, false)].OperationCost != 0 || target.BuffsBySource[(id, false)].OperationCostSetValue.HasValue
                    || target.BuffsBySource[(id, false)].OperationCostSetsAbsoluteValue || target.BuffsBySource[(id, false)].AttackSetValue != 0))
                || (id == 20 && source.CardsBuffedByThisCard.Contains(60) != otherField))
                return "mode5必须只清理账本、不创建老兵设值键";
        }
        return null;
    }

    private static string? SuppressionOperationPhaseBoundary(CardDatabase db)
    {
        var method = typeof(CardApi).GetMethod("ApplySuppressionOperationCostPhase", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int basis in new[] { -3, 0, 5, 99, 105 })
        foreach (int temp in new[] { -4, 0, 6 })
        foreach (int template in new[] { -3, 0, 5, 105 })
        foreach (int id in new[] { -1, 0, 20, 9999 })
        foreach (bool covert in new[] { false, true })
        foreach (bool discarded in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 20, CardLocation.Discard, 0);
            var foreign = state.CreateWithId(PlainUnit, side, 30, CardLocation.Discard, 0);
            var target = state.CreateWithId(PlainUnit, side, 60, discarded ? CardLocation.Discard : side.HqOf(), 1);
            foreach (var card in new[] { source, foreign, target }) card.Definition = new CardDefinition { Name = card.Name, Type = "infantry", OperationCost = 99 };
            target.Keywords.Clear(); target.Keywords.Add(Keyword.Suppressed); if (covert) target.Keywords.Add(Keyword.Covert);
            target.IsRevealed = false; target.BaseOperationCost = basis; target.TemporaryOperationCost = temp;
            target.BuffsBySource[(20, false)] = new CardBuff { SourceCardId = 20, OperationCost = 2, OperationCostSetValue = 0, AttackSetValue = 0, HasSuppressLedgerEntry = true };
            target.BuffsBySource[(20, true)] = new CardBuff { SourceCardId = 20, Temporary = true, OperationCost = 3 };
            target.BuffsBySource[(30, false)] = new CardBuff { SourceCardId = 30, OperationCost = 4, OperationCostSetValue = 7, AttackSetValue = 0, HasSuppressLedgerEntry = true };
            target.BuffsBySource[(30, true)] = new CardBuff { SourceCardId = 30, Temporary = true, OperationCost = 6 };
            source.CardsBuffedByThisCard.AddRange(new[] { 888, 60 }); foreign.CardsBuffedByThisCard.AddRange(new[] { 60, 60, 888 });
            string before = state.SnapshotJson(); method.Invoke(engine.Api, new object[] { target, template, id });
            bool eligible = id > 0 && !covert, changed = eligible && basis != template;
            var own = target.BuffsBySource[(20, false)]; var other = target.BuffsBySource[(30, false)];
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionChangeOperationCost").ToArray();
            if (target.BaseOperationCost != (changed ? Math.Clamp(template, 0, 99) : basis) || target.TemporaryOperationCost != temp
                || own.OperationCost != (eligible && id != 20 ? 0 : 2) || own.OperationCostSetValue != (eligible && id != 20 ? null : 0)
                || own.HasSuppressLedgerEntry != (!eligible || id == 20) || own.AttackSetValue != 0
                || other.OperationCost != (eligible ? 0 : 4) || other.OperationCostSetValue != (eligible ? null : 7)
                || other.HasSuppressLedgerEntry == eligible || other.AttackSetValue != 0
                || target.BuffsBySource[(20, true)].OperationCost != 3 || target.BuffsBySource[(30, true)].OperationCost != 6
                || target.BuffsBySource.ContainsKey((9999, false)) != (eligible && id == 9999)
                || (eligible && id == 9999 && !target.BuffsBySource[(9999, false)].HasSuppressLedgerEntry)
                || !source.CardsBuffedByThisCard.SequenceEqual(new[] { 888, 60 }) || !foreign.CardsBuffedByThisCard.SequenceEqual(new[] { 60, 60, 888 })
                || (!eligible && before != state.SnapshotJson()) || actions.Length != (changed ? 1 : 0)
                || (changed && !actions[0].Values.SequenceEqual(new[] { ActionValue2.Int("cardID", 60), ActionValue2.Int("instigatorID", id),
                    ActionValue2.Int("amount", template), ActionValue2.Str("changeType", "Suppress"), ActionValue2.Bool("skipAddToBattlelog", false) })))
                return $"压制行动费阶段错误 side={side},base={basis},temp={temp},template={template},source={id},covert={covert},discard={discarded}";
        }
        return null;
    }

    private static string? SuppressionOperationIntegration(CardDatabase db)
    {
        using var probes = InstallOperationCostMutationProbes();
        foreach (var side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side.Opposite(), 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(PlainUnit, side, 60, side.HqOf(), 1);
            var observer = state.CreateWithId("card_unit_arado_ar_196", side, 70, side.HqOf(), 2);
            source.Definition = new CardDefinition { Name = source.Name, Type = "infantry" };
            target.Definition = new CardDefinition { Name = target.Name, Type = "infantry", Attack = 2, Defense = 4, OperationCost = 4 };
            target.Keywords.Clear(); observer.Keywords.Clear(); SetOperationCostRegistrations(observer, true, true);
            target.BaseAttack = target.MaxAttack = 3; target.TemporaryAttack = 0; target.Defense = target.MaxDefense = 6;
            target.BaseOperationCost = 7; target.TemporaryOperationCost = 3;
            target.BuffsBySource[(20, false)] = new CardBuff { SourceCardId = 20, OperationCost = 2, OperationCostSetValue = 0 };
            target.BuffsBySource[(20, true)] = new CardBuff { SourceCardId = 20, Temporary = true, OperationCost = 3 };
            var phases = new List<string>(); string? fault = null; var created = state.CardCreated;
            state.CardCreated = spawned => {
                created?.Invoke(spawned);
                if (spawned.Name != "card_unit_routed_troops" || spawned.Location != CardLocation.DeckRight) return;
                if (observer.BlueprintVariables.GetValueOrDefault("_auditCostActive") is not string phase) return;
                observer.BlueprintVariables.Remove("_auditCostActive"); phases.Add(phase);
                if (!Equals(observer.BlueprintVariables.GetValueOrDefault("_auditCostSource"), 20)) fault = "压制来源被改写";
                var log = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
                if (log.Count(x => x.Name == "ZActionChangeOperationCost") != 1) fault = "行动费通知没有先于自身回调链";
                if (phase == "changed") {
                    if (target.BaseOperationCost != 4 || target.TemporaryOperationCost != 3) fault = "T10未看到基础复位及保留临时值";
                    target.TemporaryOperationCost = 7;
                    target.Definition = new CardDefinition { Name = target.Name, Type = "infantry", Attack = 2, Defense = 4, OperationCost = 99 };
                } else if (phase == "reset") {
                    if (target.BaseOperationCost != 4 || target.TemporaryOperationCost != 7) fault = "T9未看到T10数值修改";
                    target.BaseOperationCost = 8;
                }
            };
            engine.Api.SuppressUnit(target, 20);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            int attack = Array.FindIndex(actions, x => x.Name == "ZActionGainAttack"), defense = Array.FindIndex(actions, x => x.Name == "ZActionGainDefense");
            int cost = Array.FindIndex(actions, x => x.Name == "ZActionChangeOperationCost");
            if (fault is not null || !phases.SequenceEqual(new[] { "changed", "reset" })
                || attack < 0 || defense <= attack || cost <= defense
                || target.BaseOperationCost != 8 || target.TemporaryOperationCost != 7 || target.TotalOperationCost != 15
                || target.BuffsBySource[(20, false)].OperationCost != 2 || target.BuffsBySource[(20, false)].OperationCostSetValue != 0
                || target.BuffsBySource[(20, true)].OperationCost != 3 || !target.IsSuppressed
                || !actions[cost].Values.SequenceEqual(new[] { ActionValue2.Int("cardID", 60), ActionValue2.Int("instigatorID", 20),
                    ActionValue2.Int("amount", 4), ActionValue2.Str("changeType", "Suppress"), ActionValue2.Bool("skipAddToBattlelog", false) }))
                return $"压制行动费整合顺序/数值被后续覆盖 side={side}: {fault},phases={string.Join(',', phases)},idx={attack}/{defense}/{cost},raw={target.BaseOperationCost}/{target.TemporaryOperationCost}";
        }
        return null;
    }

    private static string? KreditTemporaryMissingNoPermanentFallback(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int raw in new[] { -3, 0, 7, 105 })
        foreach (int permanent in new[] { -5, 0, 3 })
        foreach (bool otherTemp in new[] { false, true })
        foreach (bool opaqueSet in new[] { false, true })
        foreach (int sourceId in new[] { 20, 60, 9999 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(PlainUnit, side, 60, side.HqOf(), 1);
            target.Definition = new CardDefinition { Name = target.Name, Type = "infantry", Kredits = 3 };
            target.Keywords.Clear(); target.KreditCost = raw; target.PublicKreditCost = 37; target.PublicKreditCostBuff = -9;
            var kept = new CardBuff { SourceCardId = sourceId, KreditCost = permanent, AttackSetValue = 0, KreditCostSetsAbsoluteValue = opaqueSet };
            var temporaryOther = new CardBuff { SourceCardId = sourceId, Temporary = true, Attack = 2 };
            var foreign = new CardBuff { SourceCardId = 30, Temporary = true, KreditCost = 5, DefenseSetValue = 0 };
            target.BuffsBySource[(sourceId, false)] = kept;
            if (otherTemp) target.BuffsBySource[(sourceId, true)] = temporaryOther;
            target.BuffsBySource[(30, true)] = foreign;
            source.CardsBuffedByThisCard.Add(888); target.CardsBuffedByThisCard.Add(888);
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            engine.Api.InvokeByName("ChangeKreditCost", null, new object?[] { target, sourceId, 123, 4, false, null }, ctx, out _);
            var actualSource = state.ById(sourceId);
            if (target.KreditCost != raw || target.PublicKreditCost != 37 || target.PublicKreditCostBuff != -9
                || target.BuffsBySource.Count != (otherTemp ? 3 : 2) || !ReferenceEquals(target.BuffsBySource[(sourceId, false)], kept)
                || kept.KreditCost != permanent || kept.AttackSetValue != 0 || kept.KreditCostSetsAbsoluteValue != opaqueSet
                || !ReferenceEquals(target.BuffsBySource[(30, true)], foreign) || foreign.KreditCost != 5 || foreign.DefenseSetValue != 0
                || (otherTemp && (!ReferenceEquals(target.BuffsBySource[(sourceId, true)], temporaryOther) || temporaryOther.Attack != 2 || temporaryOther.KreditCost != 0))
                || (actualSource is not null && !actualSource.CardsBuffedByThisCard.SequenceEqual(new[] { 888, 60 }))
                || trace.Count != 0 || state.ActionLog.SelectMany(x => x.SubActions).Any())
                return $"临时费用缺项不能撤永久/重算 {side}/{raw}/{permanent}/{otherTemp}/{opaqueSet}/{sourceId}";
        }
        return null;
    }

    private static string? KreditTemporaryPresentCompatibility(CardDatabase db)
    {
        // Positive control for the retained legacy path only: do not certify
        // its independent native numeric fields (mode4 events covered separately).
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int amount in new[] { -2, 2 })
        {
            var (engine, state) = EmptyBoard(db);
            var target = state.CreateWithId(PlainUnit, side, 60, side.HqOf(), 1);
            target.Definition = new CardDefinition { Name = target.Name, Type = "infantry", Kredits = 3 };
            var permanent = new CardBuff { SourceCardId = 20, KreditCost = 2, AttackSetValue = 0 };
            var temporary = new CardBuff { SourceCardId = 20, Temporary = true, KreditCost = amount, Attack = 1 };
            target.BuffsBySource[(20, false)] = permanent; target.BuffsBySource[(20, true)] = temporary;
            target.RecalculateStats();
            var ctx = new EffectContext { Engine = engine, State = state, Controller = side };
            engine.Api.InvokeByName("ChangeKreditCost", null, new object?[] { target, 20, 123, 4, true, null }, ctx, out _);
            if (!ReferenceEquals(target.BuffsBySource[(20, false)], permanent) || permanent.KreditCost != 2
                || !ReferenceEquals(target.BuffsBySource[(20, true)], temporary) || temporary.KreditCost != 0 || temporary.Attack != 1)
                return "新缺项守卫不应屏蔽存在的临时费用或删除永久/其他字段";
        }
        return null;
    }

    private static string? PublicKreditFieldLifecycle(CardDatabase db)
    {
        var copyMethod = typeof(CardApi).GetMethod("CopyForStealSide", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic)!;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int template in new[] { -3, 0, 7, 105 })
        foreach (int buff in new[] { -4, 0, 6 })
        foreach (bool salvaged in new[] { false, true })
        foreach (int current in new[] { -7, 0, 99, 123 })
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId(PlainUnit, side, 60, side.HqOf(), 1);
            card.Definition = new CardDefinition { Name = card.Name, Type = "infantry", Kredits = template, KreditsBuff = buff };
            card.Keywords.Clear(); card.IsSalvaged = salvaged; card.InitializeFromDefinition();
            int expected = salvaged ? Math.Min(3, template) : template;
            if (card.PublicKreditCost != expected || card.PublicKreditCostBuff != buff) return "初始化公开费用没有保留模板字段";
            card.PublicKreditCost = 37; card.PublicKreditCostBuff = -9; card.KreditCost = current;
            card.BuffsBySource[(20, false)] = new CardBuff { SourceCardId = 20, KreditCost = 2 };
            card.RecalculateStats();
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            engine.Api.InvokeByName("ChangeKreditCost", null, new object?[] { card, 9999, 1, 1, true, null }, ctx, out _);
            if (card.PublicKreditCost != 37 || card.PublicKreditCostBuff != -9) return "普通重算/改费不得覆盖公开字段";
            var copy = (CardInstance)copyMethod.Invoke(null, new object[] { card })!;
            var snapshot = card.Snapshot(); string fingerprint = state.SnapshotJson();
            if (copy.PublicKreditCost != 37 || copy.PublicKreditCostBuff != -9 || copy.KreditCost != card.KreditCost
                || snapshot.PublicKreditCost != 37 || snapshot.PublicKreditCostBuff != -9) return "复制/快照丢失公开费用";
            copy.PublicKreditCost++; copy.PublicKreditCostBuff++;
            if (card.PublicKreditCost != 37 || card.PublicKreditCostBuff != -9) return "公开费用复制不应共享存储";
            card.PublicKreditCost++; card.PublicKreditCostBuff++;
            if (state.SnapshotJson() == fingerprint || snapshot.PublicKreditCost != 37 || snapshot.PublicKreditCostBuff != -9) return "公开费用应改变指纹，旧快照保持不变";
            card.ResetAttributes();
            if (card.PublicKreditCost != expected || card.PublicKreditCostBuff != buff) return "重置应按模板/打捞恢复公开费用并复制公开buff";
            var synthetic = new CardInstance { CardId = 9999, Name = card.Name, Owner = side, Definition = card.Definition, KreditCost = 17 };
            if (synthetic.PublicKreditCost != template || synthetic.PublicKreditCostBuff != buff) return "未初始化静态/合成包装应回退模板而非当前费用";
        }
        return null;
    }

    private static string? PublicKreditVmMembers(CardDatabase db)
    {
        var get = typeof(KismetVm).GetMethod("GetMember", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public)!;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int value in new[] { int.MinValue, -3, 0, 7, int.MaxValue })
        foreach (int buff in new[] { -4, 0, 9 })
        foreach (int current in new[] { -7, 0, 123 })
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId(PlainUnit, side, 60, side.HqOf(), 1);
            card.PublicKreditCost = value; card.PublicKreditCostBuff = buff; card.KreditCost = current;
            if (!Equals(get.Invoke(null, new object[] { card, "kredits" }), value)
                || !Equals(get.Invoke(null, new object[] { card, "kreditsBuff" }), buff)) return "反射成员混入当前费用";
            int next = unchecked(value + 1), nextBuff = buff - 1;
            card.BlueprintVariables["kredits"] = 999; card.BlueprintVariables["kreditsBuff"] = 999;
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            var steps = new[] {
                new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Int = next }, null, -1, "kredits", null) { DestinationScope = "instance" },
                new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Int = nextBuff }, null, -1, "kreditsBuff", null) { DestinationScope = "instance" },
                new KismetStep(2, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = "kredits", Scope = "instance" }, null, -1, "cost", null),
                new KismetStep(3, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = "kreditsBuff", Scope = "instance" }, null, -1, "buff", null),
                new KismetStep(4, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) };
            var result = engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0), ctx, null, "cost", "buff");
            if (card.PublicKreditCost != next || card.PublicKreditCostBuff != nextBuff || card.KreditCost != current
                || card.BlueprintVariables.ContainsKey("kredits") || card.BlueprintVariables.ContainsKey("kreditsBuff")
                || !Equals(result.GetValueOrDefault("cost"), next) || !Equals(result.GetValueOrDefault("buff"), nextBuff))
                return $"VM公开费用写入混用/影子冲突 {side}/{value}/{buff}/{current}";
        }
        return null;
    }

    private static string? TemporaryKreditGetterDispatchAndVm(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int basis in new[] { -3, 0, 99, 105 })
        foreach (int temp in new[] { -105, -3, 0, 3, 105, int.MinValue, int.MaxValue })
        foreach (int contribution in new[] { -7, 0, 11 })
        foreach (bool explicitReceiver in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var other = state.CreateWithId(PlainUnit, side.Opposite(), 20, side.Opposite().HandOf(), 0); other.TemporaryKreditCost = 23;
            var target = state.CreateWithId(PlainUnit, side, 60, CardLocation.Discard, 0);
            target.BaseKreditCost = basis; target.TemporaryKreditCost = temp; target.PublicKreditCost = 37; target.PublicKreditCostBuff = -9;
            target.BuffsBySource[(20, true)] = new CardBuff { SourceCardId = 20, Temporary = true, KreditCost = contribution, HasZeroKreditCostEntry = contribution == 0 };
            target.BuffsBySource[(20, false)] = new CardBuff { SourceCardId = 20, KreditCost = 7, KreditCostSetValue = 0 };
            var ctx = new EffectContext { Engine = engine, State = state, Self = explicitReceiver ? other : target, Controller = side.Opposite() };
            string before = state.SnapshotJson(); int faults = engine.Api.Vm.FaultedPrograms, unsupported = engine.Api.Vm.UnsupportedInstructions;
            int missing = state.UnimplementedCalls.Values.Sum(); long random = state.Random.ConsumedCount;
            object? raw = engine.Api.InvokeByName("getAndDecryptKreditBuff", explicitReceiver ? target : null, new object?[] { null }, ctx, out bool handled);
            var step = new KismetStep(0, "call", "getAndDecryptKreditBuff", new[] { new KismetExpr { Var = "__temp", Scope = "local" } }, new[] { 0 }, null, null, -1, null, null)
                { Receiver = explicitReceiver ? new KismetExpr { Var = "__receiver", Scope = "local" } : null };
            var output = engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(new[] { step,
                new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) }, 0), ctx,
                new Dictionary<string, object?> { ["__receiver"] = target, ["__temp"] = 65432 }, "__temp");
            if (!handled || !Equals(raw, temp) || !Equals(output.GetValueOrDefault("__temp"), temp) || before != state.SnapshotJson()
                || state.UnimplementedCalls.Values.Sum() != missing || engine.Api.Vm.FaultedPrograms != faults || engine.Api.Vm.UnsupportedInstructions != unsupported
                || state.Random.ConsumedCount != random)
                return $"临时费用 getter 必须纯读原始字段并写回输出槽 {side}/{basis}/{temp}/{contribution}/{explicitReceiver}: handled={handled}, raw={raw}, vm={output.GetValueOrDefault("__temp")}";
        }
        return null;
    }

    private static string? TemporaryKreditGetterAfterMutation(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int basis in new[] { -3, 99 })
        foreach (int temp in new[] { -4, 0, 5 })
        foreach (int request in new[] { -2, 0, 2 })
        foreach (int mode in new[] { 0, 1, 4 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(PlainUnit, side, 60, side.HandOf(), 0);
            target.BaseKreditCost = basis; target.TemporaryKreditCost = temp; target.PublicKreditCost = 37; target.PublicKreditCostBuff = -9;
            target.BuffsBySource[(20, true)] = new CardBuff { SourceCardId = 20, Temporary = true, KreditCost = 2 };
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            var program = new KismetProgram(new[] { new KismetStep(0, "call", "getAndDecryptKreditBuff",
                new[] { new KismetExpr { Var = "__temp", Scope = "local" } }, new[] { 0 }, null, null, -1, null, null)
                { Receiver = new KismetExpr { Var = "__receiver", Scope = "local" } },
                new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) }, 0);
            var seed = new Dictionary<string, object?> { ["__receiver"] = target, ["__temp"] = 65432 };
            var before = engine.Api.Vm.RunLocalProgramMulti(program, ctx, seed, "__temp");
            engine.Api.InvokeByName("ChangeKreditCost", null, new object?[] { target, 20, request, mode, true, null }, ctx, out _);
            var after = engine.Api.Vm.RunLocalProgramMulti(program, ctx, seed, "__temp");
            int expected = mode == 0 ? temp + request : mode == 4 ? temp - 2 : temp;
            if (!Equals(before.GetValueOrDefault("__temp"), temp) || !Equals(after.GetValueOrDefault("__temp"), expected)
                || target.TemporaryKreditCost != expected || target.PublicKreditCost != 37 || target.PublicKreditCostBuff != -9)
                return $"临时费用 getter 不得缓存旧值/改读基础费或公开字段 {side}/{basis}/{temp}/{request}/{mode}";
        }
        return null;
    }

    private static string? GotchaReceiptStoresTotalKredit(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int basis in new[] { -3, 0, 99, 105, int.MaxValue, int.MinValue })
        foreach (int temp in new[] { -4, 0, 5, 1, -1 })
        foreach (int activation in new[] { -2, 0, 7 })
        foreach (int? oldPaid in new int?[] { null, -7, 9 })
        foreach (bool leaveHand in new[] { false, true })
        foreach (bool directly in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); state.SetKredits(side, 10);
            var other = state.CreateWithId("card_event_interception", side, 20, CardLocation.Discard, 0); other.GotchaActivated = 11;
            var card = state.CreateWithId(other.Name, side, 60, side.HandOf(), 0); card.GotchaActivated = activation;
            if (oldPaid is int paid) engine.Api.JsonSetInt(card, "kreditsPayed", paid); else card.CustomJson.Remove("kreditsPayed");
            engine.Api.JsonSetInt(card, "_auditKeep", 17);
            if (directly) engine.PlayCardDirectlyFromHand(card, false, 9004, -1);
            else { state.AddAutoPlayCards(card.CardId); engine.ExecuteAutoPlayCards(); }
            int activationBeforeReceipt = card.GotchaActivated, resources = state.Kredits(side);
            bool hadPaid = card.CustomJson.ContainsKey("kreditsPayed"); int paidBefore = engine.Api.JsonGetInt(card, "kreditsPayed");
            if (leaveHand) state.Move(card, CardLocation.Discard, notifyMoved: false);
            // The receiver must read this pair now, rather than the one at notification time.
            card.BaseKreditCost = basis; card.TemporaryKreditCost = temp; card.PublicKreditCost = 37; card.PublicKreditCostBuff = -9;
            var frozen = card.Snapshot();
            bool writesPaid = !directly && activationBeforeReceipt <= 0;
            int expectedPaid = writesPaid ? Math.Clamp(unchecked(basis + temp), 0, 99) : paidBefore;
            int expectedActivation = directly ? activationBeforeReceipt : activationBeforeReceipt > 0 ? 0 : 12;
            engine.ApplyPendingGotchaPlayReceipts();
            if (card.CustomJson.ContainsKey("kreditsPayed") != (writesPaid || hadPaid) || engine.Api.JsonGetInt(card, "kreditsPayed") != expectedPaid
                || engine.Api.JsonGetInt(card, "_auditKeep") != 17 || card.GotchaActivated != expectedActivation || state.Kredits(side) != resources
                || card.BaseKreditCost != basis || card.TemporaryKreditCost != temp || card.PublicKreditCost != 37 || card.PublicKreditCostBuff != -9
                || card.Location != (leaveHand ? CardLocation.Discard : side.HandOf()) || frozen.BaseKreditCost != basis || frozen.TemporaryKreditCost != temp)
                return $"反制接收应记录当前限幅总费且保留跳过门 {side}/{basis}/{temp}/{activation}/{oldPaid}/{leaveHand}/{directly}: {engine.Api.JsonGetInt(card, "kreditsPayed")}/{expectedPaid}";
            engine.ApplyPendingGotchaPlayReceipts();
            if (card.GotchaActivated != expectedActivation || engine.Api.JsonGetInt(card, "kreditsPayed") != expectedPaid)
                return "反制接收队列排空后不得再次切换或重写已付费用";
        }
        return null;
    }

    private static string? GotchaRefundUsesRecordedTotalKredit(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int basis in new[] { -3, 0, 99, 105, int.MaxValue, int.MinValue })
        foreach (int temp in new[] { -4, 0, 5, 1, -1 })
        {
            var (engine, state) = EmptyBoard(db); state.SetKredits(side, 10);
            var card = state.CreateWithId("card_event_interception", side, 60, side.HandOf(), 0);
            state.AddAutoPlayCards(card.CardId); engine.ExecuteAutoPlayCards();
            card.BaseKreditCost = basis; card.TemporaryKreditCost = temp;
            engine.ApplyPendingGotchaPlayReceipts();
            int paid = Math.Clamp(unchecked(basis + temp), 0, 99);
            if (card.GotchaActivated <= 0 || engine.Api.JsonGetInt(card, "kreditsPayed") != paid) return "反制激活接收没有记录当前总费";
            state.SetKredits(side, 0); card.BaseKreditCost = 17; card.TemporaryKreditCost = -4;
            state.AddAutoPlayCards(card.CardId); engine.ExecuteAutoPlayCards();
            if (state.Kredits(side) != Math.Clamp(paid, 0, MatchEngine.MaxKreditCap)) return "反制撤销应按接收时记录费用退费，而非之后的当前费用";
            engine.ApplyPendingGotchaPlayReceipts();
            if (card.GotchaActivated != 0 || engine.Api.JsonGetInt(card, "kreditsPayed") != paid || card.BaseKreditCost != 17 || card.TemporaryKreditCost != -4)
                return "反制撤销接收不得覆盖记录费用或当前独立费用字段";
        }
        return null;
    }

    private static CardDatabase SpawnCheckFixtureDatabase(CardDatabase db, IEnumerable<CardDefinition> candidates)
    {
        string[] names = { "card_location_berlin", "card_event_red_banner", "card_event_ural_factories", "card_event_refit", "card_event_stand_together_brothers" };
        var definitions = names.ToDictionary(x => x, x => db.Require(x), StringComparer.Ordinal);
        foreach (var card in candidates) definitions[card.Name] = card;
        return (CardDatabase)typeof(CardDatabase).GetConstructors(System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).Single()
            .Invoke(new object[] { definitions, new Dictionary<string, string>(StringComparer.Ordinal) });
    }

    private static string? SpawnCheckUsesBaseKredit(CardDatabase db)
    {
        foreach (var (name, delta, tank) in new[] { ("card_event_red_banner", 2, false), ("card_event_ural_factories", 1, false),
                     ("card_event_refit", 3, true), ("card_event_stand_together_brothers", 0, true) })
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int basis in new[] { -3, 0, 5, 99 })
        foreach (int temp in new[] { -4, 0, 5 })
        foreach (int offset in new[] { -1, 0, 1 })
        foreach (int candidateTemp in new[] { -4, 0, 5 })
        foreach (bool factionMatch in new[] { false, true })
        foreach (bool typeMatch in new[] { false, true })
        {
            var candidate = new CardDefinition { Name = PlainUnit, Type = typeMatch ? "tank" : tank ? "infantry" : "order",
                FactionId = factionMatch ? 4 : 5, CardSet = db.Require(PlainUnit).CardSet, Kredits = basis + delta + offset, KreditsBuff = candidateTemp };
            var fixtureDb = SpawnCheckFixtureDatabase(db, new[] { candidate });
            var (engine, state) = EmptyBoard(fixtureDb);
            // Match the native model's explicitly unreserved candidate pool;
            // production rotation data is independent of this cost predicate.
            state.CardReservations = new CardReservationPolicy(new[] { new CardReservationChange(1,
                Array.Empty<string>(), state.Database.All.Select(x => x.Name)) }, 1);
            var source = state.CreateWithId(name, side, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(PlainUnit, side, 60, side.HqOf(), 1);
            target.Definition = new CardDefinition { Name = PlainUnit, Type = "tank", FactionId = 4, Kredits = 37, KreditsBuff = -9 };
            target.BaseKreditCost = basis; target.TemporaryKreditCost = temp;
            target.PublicKreditCost = 37; target.PublicKreditCostBuff = -9;
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            object? actual = engine.Api.InvokeByName("CheckHasUnitToSpawn", null, new object?[] { target, null }, ctx, out bool handled);
            bool expected = offset == 0 && factionMatch && typeMatch;
            var program = KismetLibrary.Default!.FindProgram(name, "CheckHasUnitToSpawn")!;
            var local = engine.Api.Vm.RunLocalProgramMulti(program, ctx,
                new Dictionary<string, object?> { ["Card"] = target }, "HasUnitToSpawn");
            if (!handled || !Equals(actual, expected) || !Equals(local.GetValueOrDefault("HasUnitToSpawn"), expected) || target.BaseKreditCost != basis || target.TemporaryKreditCost != temp
                || target.PublicKreditCost != 37 || target.PublicKreditCostBuff != -9 || fixtureDb.Require(PlainUnit) != candidate)
                return $"生成候选应比较目标/候选基础费 {name}/{side}/{basis}/{temp}/{offset}/{candidateTemp}/{factionMatch}/{typeMatch}: {actual}";
        }
        return null;
    }

    private static string? SpawnCheckBaseKreditPoolOrder(CardDatabase db)
    {
        foreach (var (name, delta) in new[] { ("card_event_red_banner", 2), ("card_event_ural_factories", 1),
                     ("card_event_refit", 3), ("card_event_stand_together_brothers", 0) })
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int shape in new[] { 0, 1, 2 })
        {
            // Static pools sort by name; swap identities so the match is
            // actually after/before the wrong candidate, not just insertion order.
            var match = new CardDefinition { Name = shape == 1 ? "card_unit_t_34" : "card_unit_bt_7", Type = "tank", FactionId = 4, CardSet = db.Require(PlainUnit).CardSet, Kredits = 5 + delta, KreditsBuff = -4 };
            var wrong = new CardDefinition { Name = shape == 1 ? "card_unit_bt_7" : "card_unit_t_34", Type = "tank", FactionId = 4, CardSet = match.CardSet, Kredits = 6 + delta, KreditsBuff = -1 };
            var candidates = shape == 0 ? Array.Empty<CardDefinition>() : shape == 1 ? new[] { wrong, match } : new[] { match, wrong };
            var (engine, state) = EmptyBoard(SpawnCheckFixtureDatabase(db, candidates));
            // Match the native model's explicitly unreserved candidate pool;
            // production rotation data is independent of this cost predicate.
            state.CardReservations = new CardReservationPolicy(new[] { new CardReservationChange(1,
                Array.Empty<string>(), state.Database.All.Select(x => x.Name)) }, 1);
            var source = state.CreateWithId(name, side, 20, CardLocation.Discard, 0);
            var target = new CardInstance { CardId = 60, Name = PlainUnit, Owner = side, Definition = new CardDefinition { Name = PlainUnit, Type = "tank", FactionId = 4 }, BaseKreditCost = 5, TemporaryKreditCost = 5 };
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            object? actual = engine.Api.InvokeByName("CheckHasUnitToSpawn", null, new object?[] { target, null }, ctx, out bool handled);
            if (!handled || !Equals(actual, shape != 0)) return $"生成候选空池/顺序错误 {name}/{side}/{shape}: {actual}";
        }
        return null;
    }

    private static string? InitializeKreditPairFromDefinition(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int basis in new[] { -3, 0, 3, 105 })
        foreach (int temp in new[] { -4, 0, 5, 99 })
        foreach (bool salvaged in new[] { false, true })
        foreach (bool dirty in new[] { false, true })
        {
            var card = new CardInstance { CardId = 60, Name = PlainUnit, Owner = side, IsSalvaged = salvaged,
                Definition = new CardDefinition { Name = PlainUnit, Type = "infantry", Kredits = basis, KreditsBuff = temp, Attack = 1, Defense = 5 } };
            card.BaseKreditCost = dirty ? 99 : 17; card.TemporaryKreditCost = dirty ? -9 : 2;
            card.PublicKreditCost = 37; card.PublicKreditCostBuff = -11;
            var frozen = card.Snapshot();
            card.InitializeFromDefinition();
            int expected = salvaged ? Math.Min(3, basis) : basis;
            if (card.BaseKreditCost != expected || card.TemporaryKreditCost != temp || card.TotalKreditCost != Math.Clamp(expected + temp, 0, 99)
                || card.PublicKreditCost != expected || card.PublicKreditCostBuff != temp || frozen.BaseKreditCost != (dirty ? 99 : 17)
                || frozen.TemporaryKreditCost != (dirty ? -9 : 2))
                return $"初始化费用必须从模板公开两字段重建 {side}/{basis}/{temp}/{salvaged}/{dirty}";
        }
        return null;
    }

    private static string? CreationCallbacksSeeKreditPair(CardDatabase db)
    {
        var ctor = typeof(CardDatabase).GetConstructors(System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).Single();
        foreach (int basis in new[] { -3, 0, 3, 105 })
        foreach (int temp in new[] { -4, 0, 5, 99 })
        {
            // Private fixture database; never mutate shared production definitions.
            var definitions = db.All.ToDictionary(x => x.Name, StringComparer.Ordinal);
            definitions[PlainUnit] = new CardDefinition { Name = PlainUnit, Type = "infantry", Kredits = basis, KreditsBuff = temp, Attack = 1, Defense = 5 };
            var fixtureDb = (CardDatabase)ctor.Invoke(new object[] { definitions, db.DeckCodeIds.ToDictionary(x => x.Key, x => x.Value, StringComparer.Ordinal) });
            foreach (var side in new[] { Side.Left, Side.Right })
            foreach (bool salvaged in new[] { false, true })
            foreach (bool explicitId in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(fixtureDb); int created = 0, modifiers = 0; string? fault = null;
                int expected = salvaged ? Math.Min(3, basis) : basis;
                bool Correct(CardInstance card) => card.BaseKreditCost == expected && card.TemporaryKreditCost == temp
                    && card.PublicKreditCost == expected && card.PublicKreditCostBuff == temp && card.TotalKreditCost == Math.Clamp(expected + temp, 0, 99);
                var priorCreated = state.CardCreated; var priorModifiers = state.CardCreationModifiers;
                state.CardCreated = card => { if (card.Name == PlainUnit) { created++; if (!Correct(card)) fault = "创建回调前费用尚未初始化"; } priorCreated?.Invoke(card); };
                state.CardCreationModifiers = card => { if (card.Name == PlainUnit) { modifiers++; if (!Correct(card) || created != 1) fault = "创建修正前应已初始化且先经历创建回调"; } priorModifiers?.Invoke(card); };
                var card = explicitId ? state.CreateWithId(PlainUnit, side, 60, side.HandOf(), 0, isSalvaged: salvaged)
                    : state.Create(PlainUnit, side, side.HandOf(), 0, isSalvaged: salvaged);
                if (fault is not null || created != 1 || modifiers != 1 || !Correct(card))
                    return $"建卡入口费用观察时序错误 {basis}/{temp}/{side}/{salvaged}/{explicitId}: {fault}";
            }
        }
        return null;
    }

    private static string? DirectPlayPreservesTemporaryKredit(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int basis in new[] { -3, 0, 3, 105 })
        foreach (int temp in new[] { -4, 0, 5, 99, 123 })
        foreach (bool salvaged in new[] { false, true })
        foreach (bool frontline in new[] { false, true })
        foreach (bool mutateOnMove in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId(PlainUnit, side, 60, side.HandOf(), 0);
            card.Definition = new CardDefinition { Name = card.Name, Type = "infantry", Kredits = basis, KreditsBuff = -17, Attack = 1, Defense = 5 };
            card.Keywords.Clear(); card.IsSalvaged = salvaged;
            card.BaseKreditCost = 17; card.TemporaryKreditCost = temp;
            card.PublicKreditCost = 37; card.PublicKreditCostBuff = -9;
            var permanent = new CardBuff { SourceCardId = 20, KreditCost = 2, KreditCostSetValue = 0 };
            var temporary = new CardBuff { SourceCardId = 20, Temporary = true, KreditCost = -2, KreditCostEmptyDetail = 0 };
            card.BuffsBySource[(20, false)] = permanent; card.BuffsBySource[(20, true)] = temporary;
            var frozen = card.Snapshot(); int moved = 0; var priorMove = state.CardMoved;
            state.CardMoved = (moving, oldLocation, newLocation, skip, reason) => {
                priorMove?.Invoke(moving, oldLocation, newLocation, skip, reason);
                if (moving != card || reason != CardMoveReason.PlayCardForce) return;
                moved++;
                if (mutateOnMove) { card.BaseKreditCost = 11; card.TemporaryKreditCost = temp + 2; }
            };
            bool result = engine.PlayCardDirectlyFromHand(card, frontline, 9004, -1);
            int expectedBase = salvaged ? Math.Min(3, basis) : basis, expectedTemp = temp + (mutateOnMove ? 2 : 0);
            if (!result || moved != 1 || card.BaseKreditCost != expectedBase || card.TemporaryKreditCost != expectedTemp
                || card.TotalKreditCost != Math.Clamp(expectedBase + expectedTemp, 0, 99) || card.PublicKreditCost != 37 || card.PublicKreditCostBuff != -9
                || !ReferenceEquals(card.BuffsBySource[(20, false)], permanent) || permanent.KreditCost != 2 || permanent.KreditCostSetValue != 0
                || !ReferenceEquals(card.BuffsBySource[(20, true)], temporary) || temporary.KreditCost != -2 || temporary.KreditCostEmptyDetail != 0
                || frozen.BaseKreditCost != 17 || frozen.TemporaryKreditCost != temp
                || card.Location != (frontline ? CardLocation.BoardFrontline : side.HqOf())
                || state.ActionLog.SelectMany(x => x.SubActions).Any(x => x.Name == "ZActionSetKreditCost"))
                return $"直接出牌基础费 setter 不得覆盖临时值、公开值或账本 {side}/{basis}/{temp}/{salvaged}/{frontline}/{mutateOnMove}";
        }
        return null;
    }

