    private static string? KreditDefaultByteModesNoOp(CardDatabase db)
    {
        static (int Cost, int? Set, int? AttackSet, bool Suppress, int? OperationSet) Payload(CardBuff b)
            => (b.KreditCost, b.KreditCostSetValue, b.AttackSetValue, b.HasSuppressLedgerEntry, b.OperationCostSetValue);
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int mode in Enumerable.Range(9, 247))
        foreach (int sourceId in new[] { 20, 60, 9999 })
        foreach (bool currentMap in new[] { false, true })
        foreach (int request in new[] { -3, 0, 105 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 20, CardLocation.Discard, 0);
            var foreign = state.CreateWithId(PlainUnit, side, 30, CardLocation.Discard, 1);
            var target = state.CreateWithId(PlainUnit, side, 60, side.HqOf(), 1);
            target.Keywords.Clear(); target.BaseKreditCost = 105; target.TemporaryKreditCost = -4;
            target.PublicKreditCost = 37; target.PublicKreditCostBuff = -9;
            foreach (int id in currentMap ? new[] { sourceId, 30 } : new[] { 30 })
            {
                target.BuffsBySource[(id, false)] = new CardBuff { SourceCardId = id, KreditCost = 2,
                    KreditCostSetValue = 0, AttackSetValue = 0, HasSuppressLedgerEntry = true, OperationCostSetValue = 0 };
                target.BuffsBySource[(id, true)] = new CardBuff { SourceCardId = id, Temporary = true, KreditCost = -4 };
            }
            var old = target.BuffsBySource.ToDictionary(x => x.Key, x => (Reference: x.Value, Data: Payload(x.Value)));
            source.CardsBuffedByThisCard.Add(888); target.CardsBuffedByThisCard.Add(888); foreign.CardsBuffedByThisCard.AddRange(new[] { 777, 60 });
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            var ctx = new EffectContext { Engine = engine, State = state, Controller = side };
            engine.Api.InvokeByName("ChangeKreditCost", null, new object?[] { target, sourceId, request, mode, true, null }, ctx, out bool handled);
            if (!handled || target.BaseKreditCost != 105 || target.TemporaryKreditCost != -4
                || target.PublicKreditCost != 37 || target.PublicKreditCostBuff != -9 || target.BuffsBySource.Count != old.Count
                || old.Any(x => !target.BuffsBySource.TryGetValue(x.Key, out var b) || !ReferenceEquals(b, x.Value.Reference) || Payload(b) != x.Value.Data)
                || (state.ById(sourceId) is { } actualSource && !actualSource.CardsBuffedByThisCard.SequenceEqual(new[] { 888 }))
                || !foreign.CardsBuffedByThisCard.SequenceEqual(new[] { 777, 60 }) || trace.Count != 0 || state.ActionLog.SelectMany(x => x.SubActions).Any())
                return $"费用默认字节模式不应改动状态 {side}/{mode}/{sourceId}/{currentMap}/{request}";
        }
        return null;
    }

