            target.Definition = new CardDefinition { Name = target.Name, Type = "infantry", Attack = target.BaseAttack, Defense = target.Defense, OperationCost = target.BaseOperationCost };
            var alias = new CardInstance { CardId = 60, Name = PlainUnit, Owner = side.Opposite(), Definition = target.Definition };
            engine.Api.SuppressUnit(alias, 20);
            var batches = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionSuppressMultipleUnits").ToArray();
            if (!target.IsSuppressed || alias.IsSuppressed || batches.Length != 1 || batches[0].Values[0] != ActionValue2.Str("cardsToSuppress", "60"))
                return "公共对象包装未按ID查找当前对象";
        }
        return null;
    }

    private static string? SuppressionBatchLookupMutation(CardDatabase db)
    {
        using var probes = InstallOperationCostMutationProbes();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool replace in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 20, CardLocation.Discard, 0);
            var first = state.CreateWithId(PlainUnit, side, 60, side.HqOf(), 1);
            var old = state.CreateWithId(PlainUnit, side, 70, side.HqOf(), 2);
            var observer = state.CreateWithId("card_unit_arado_ar_196", side, 90, side.HqOf(), 3);
            foreach (var card in new[] { first, old }) {
                card.Definition = new CardDefinition { Name = card.Name, Type = "infantry", Attack = 2, Defense = 4, OperationCost = 4 };
                card.BaseAttack = card.MaxAttack = 2; card.Defense = card.MaxDefense = 4;
                card.BaseOperationCost = 7; card.TemporaryOperationCost = 0; card.Keywords.Clear();
            }
            observer.Keywords.Clear(); SetOperationCostRegistrations(observer, true, false);
            CardInstance? replacement = null; var seen = new List<int>(); string? fault = null;
            var created = state.CardCreated;
            state.CardCreated = spawned => {
                created?.Invoke(spawned);
                if (spawned.Name != "card_unit_routed_troops" || spawned.Location != CardLocation.DeckRight
                    || !Equals(observer.BlueprintVariables.GetValueOrDefault("_auditCostActive"), "changed")) return;
                observer.BlueprintVariables.Remove("_auditCostActive");
                int id = Convert.ToInt32(observer.BlueprintVariables["_auditCostTarget"]); seen.Add(id);
                var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
                if (actions[0].Name != "ZActionSuppressMultipleUnits" || actions.Count(x => x.Name == "ZActionSuppressMultipleUnits") != 1
                    || actions[0].Values[0] != ActionValue2.Str("cardsToSuppress", "60;70")
                    || !Equals(observer.BlueprintVariables.GetValueOrDefault("_auditCostSource"), 20)) fault = "批量通知未前置或来源改变";
                if (id != 60) return;
                old.Location = side.HandOf();
                if (replace) {
                    state.Remove(old);
                    replacement = state.CreateWithId(PlainUnit, side, 70, side.HqOf(), 2);
                    replacement.Definition = first.Definition;
                    replacement.BaseAttack = replacement.MaxAttack = 2; replacement.Defense = replacement.MaxDefense = 4;
                    replacement.BaseOperationCost = 7; replacement.TemporaryOperationCost = 0; replacement.Keywords.Clear();
                }
            };
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            engine.Api.InvokeByName("SuppressMultipleUnits", null, new object?[] { new[] { 60, 70 }, 20, null }, ctx, out _);
            if (fault is not null || old.IsSuppressed || !first.IsSuppressed || replacement?.IsSuppressed != (replace ? true : null)
                || !seen.SequenceEqual(replace ? new[] { 60, 70 } : new[] { 60 }))
                return $"逐项ID查找错误 side={side},replace={replace},seen={string.Join(',',seen)}: {fault}";
        }
        return null;
    }

    private static string? OperationCostNotificationPayload(CardDatabase db)
    {
        var method = typeof(CardApi).GetMethod("NotifyOperationCostChanged", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!;
        string[] names = { "tempBuffGive", "permBuff", "SetValue", "Suppress", "tempBuffRemove", "veteranSet", "customAdd", "customRemove", "combatModify", "notUsed", "EChangeType_MAX" };
        foreach (int cardId in new[] { -1, 60 })
        foreach (int source in new[] { -7, 0, 20, 9999 })
        foreach (int amount in new[] { -3, 0, 2, 105 })
        foreach (int mode in Enumerable.Range(0, 11))
        foreach (bool skiplog in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            method.Invoke(engine.Api, new object[] { cardId, source, amount, mode, skiplog });
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            if (actions.Length != 1 || actions[0].Name != "ZActionChangeOperationCost" || !actions[0].Values.SequenceEqual(new[] {
                ActionValue2.Int("cardID", cardId), ActionValue2.Int("instigatorID", source), ActionValue2.Int("amount", amount),
                ActionValue2.Str("changeType", names[mode]), ActionValue2.Bool("skipAddToBattlelog", skiplog) }))
                return $"行动费五字段编码错误 card={cardId},source={source},amount={amount},mode={mode},skiplog={skiplog}";
        }
        return null;
    }

    private static string? OperationCostNotificationRouting(CardDatabase db)
    {
        string Name(int mode) => mode switch { 0 => "tempBuffGive", 1 => "permBuff", 2 => "SetValue", 3 => "Suppress", _ => "veteranSet" };
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int mode in new[] { 0, 1, 2, 3, 5 })
        foreach (int before in new[] { 0, 2, 99, 105 })
        foreach (int requested in new[] { -3, 0, 2, 105 })
        foreach (bool isBuff in new[] { false, true })
        foreach (bool skip in new[] { false, true })
        foreach (bool skiplog in new[] { false, true })
        foreach (bool deck in new[] { false, true })
        foreach (bool suppressed in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_t_34", side, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId("card_unit_t_34", side, 60, deck ? side.DeckOf() : side.HqOf(), 1);
            target.Keywords.Clear(); if (suppressed) target.Keywords.Add(Keyword.Suppressed);
            target.OperationCost = before;
            engine.Api.InvokeByName("ChangeOperationCost", target, new object?[] { target, 20, requested, mode, isBuff, skip, skiplog },
                new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out bool handled);
            bool changed = mode is 2 or 3 or 5 ? before != requested : requested != 0;
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionChangeOperationCost").ToArray();
            if (!handled || actions.Length != (changed && !skip ? 1 : 0) || (actions.Length == 1 && !actions[0].Values.SequenceEqual(new[] {
                ActionValue2.Int("cardID", 60), ActionValue2.Int("instigatorID", 20), ActionValue2.Int("amount", requested),
                ActionValue2.Str("changeType", Name(mode)), ActionValue2.Bool("skipAddToBattlelog", skiplog) })))
                return $"行动费通知路由错误 mode={mode},before={before},request={requested},isBuff={isBuff},skip={skip},skiplog={skiplog},deck={deck},suppressed={suppressed}";
        }
        return null;
    }

    private static string? OperationCostSkipKeepsCallbacks(CardDatabase db)
    {
        const string name = "card_unit_arado_ar_196", own = "OnAfterOperationCostChanged", other = "OnAfterOtherCardOperactionCostChanged";
        using var ownProbe = InstallSelectionDrawProbe(name, own);
        using var otherProbe = InstallSelectionDrawProbe(name, other);
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int mode in new[] { 0, 1 })
        foreach (bool skip in new[] { false, true })
        foreach (bool suppressed in new[] { false, true })
        foreach (int sourceId in new[] { 20, 9999 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_t_34", side, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(name, side, 60, side.HqOf(), 1);
            var observer = state.CreateWithId(name, side, 70, side.HqOf(), 2);
            foreach (var card in new[] { target, observer }) { card.Keywords.Clear(); card.Definition = new CardDefinition { Name = name, Type = "fighter", UsedTriggers = new[] { other } }; }
            if (suppressed) target.Keywords.Add(Keyword.Suppressed);
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            engine.Api.InvokeByName("ChangeOperationCost", target, new object?[] { target, sourceId, 1, mode, false, skip, false },
                new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out _);
            if (state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionChangeOperationCost") != (skip ? 0 : 1)
                || trace.Count(x => x.StartsWith(own + " →", StringComparison.Ordinal)) != (suppressed ? 0 : 1)
                || trace.Count(x => x.StartsWith(other + " → " + name + "#70", StringComparison.Ordinal)) != 1)
                return $"skipAction不得吞已有回调 mode={mode},skip={skip},suppressed={suppressed},source={sourceId}";
        }
        return null;
    }

    private static string? OperationCostEntryGuards(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int location in Enumerable.Range(0, 10))
        foreach (bool covert in new[] { false, true })
        foreach (bool revealed in new[] { false, true })
        foreach (int sourceId in new[] { -7, 0, 20, 9999 })
        foreach (int mode in Enumerable.Range(0, 6))
        foreach (bool hasSelf in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_t_34", side, 20, CardLocation.Discard, 0);
            var self = state.CreateWithId("card_unit_t_34", side, 40, CardLocation.Discard, 0);
            var target = state.CreateWithId("card_unit_t_34", side, 60, (CardLocation)location, 1);
            target.Keywords.Clear(); if (covert) target.Keywords.Add(Keyword.Covert); target.IsRevealed = revealed;
            target.OperationCost = 7;
            if (mode == 4) target.BuffsBySource[(sourceId, true)] = new CardBuff { SourceCardId = sourceId, Temporary = true, OperationCost = 1, Attack = 1 };
            string before = state.SnapshotJson();
            engine.Api.InvokeByName("ChangeOperationCost", target, new object?[] { target, sourceId, 2, mode, false, false, false },
                new EffectContext { Engine = engine, State = state, Self = hasSelf ? self : null, Controller = side }, out bool handled);
            bool allowed = sourceId > 0 && (!covert || revealed);
            if (!handled || (!allowed && (before != state.SnapshotJson() || state.ActionLog.SelectMany(x => x.SubActions).Any())))
                return $"行动费入口拒绝须无副作用 location={location},covert={covert},revealed={revealed},source={sourceId},mode={mode},self={hasSelf}";
            if (allowed) {
                bool temporary = mode is 0 or 4;
                bool hasBuff = target.BuffsBySource.TryGetValue((sourceId, temporary), out var buff);
                if (before == state.SnapshotJson() || hasBuff != (mode != 5)
                    || (mode == 4 && buff!.OperationCost != 0)
                    || target.BuffsBySource.Keys.Any(k => k.SourceCardId == 40)
                    || (sourceId == 9999 && source.CardsBuffedByThisCard.Contains(60)))
                    return $"行动费正来源不得用Self替代或要求来源对象存在 source={sourceId},mode={mode},location={location}";
            }
        }
        return null;
    }

    private static string? SuppressionDefenseOutput(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int defense in new[] { -3, 0, 3 })
        foreach (int requested in new[] { -4, 3, 105 })
        foreach (int sourceId in new[] { -1, 0, 20, 9999 })
        foreach (bool skip in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_t_34", side, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId("card_unit_t_34", side, 60, side.HqOf(), 1); target.Defense = defense;
            var steps = new[] {
                new KismetStep(0, "call", "ChangeDefense", new[] {
                    new KismetExpr { Var = "__target", Scope = "local" }, new KismetExpr { Int = sourceId },
                    new KismetExpr { Int = requested }, new KismetExpr { Int = 3 }, new KismetExpr { Bool = skip },
                    new KismetExpr { Var = "__q", Scope = "local" } }, new[] { 5 }, null, null, -1, null, null),
                new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) };
            var result = engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0),
                new EffectContext { Engine = engine, State = state, Self = source, Controller = side },
                new Dictionary<string, object?> { ["__target"] = target, ["__q"] = true }, "__q");
            if (!Equals(result.GetValueOrDefault("__q"), false))
                return $"ChangeDefense3未覆盖qqq旧true defense={defense},request={requested},source={sourceId},skip={skip}";
        }
        return null;
    }

    private static string? SuppressionDefenseLedgerMatrix(CardDatabase db)
    {
        var method = typeof(CardApi).GetMethod("ApplySuppressionDefensePhase", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int cm in Enumerable.Range(0, 32))
        foreach (int om in Enumerable.Range(0, 32))
        foreach (int sourceId in new[] { -1, 0, 20, 9999 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_t_34", side, 20, CardLocation.Discard, 0);
            var foreign = state.CreateWithId("card_unit_t_34", side, 30, CardLocation.Discard, 0);
            var target = state.CreateWithId("card_unit_t_34", side, 60, side.HqOf(), 1);
            var reverse = (cm % 2) == 0 ? new[] { 888 } : new[] { 60, 60, 888 };
            source.CardsBuffedByThisCard.AddRange(reverse); foreign.CardsBuffedByThisCard.AddRange(new[] { 60, 60, 888 });
            void Seed(int id, int mask) {
                if ((mask & 27) != 0) target.BuffsBySource[(id, false)] = new CardBuff { SourceCardId = id,
                    Defense = (mask & 1) != 0 ? 2 : 0, DefenseSetValue = (mask & 2) != 0 ? 0 : null,
                    AttackSetValue = (mask & 8) != 0 ? 0 : null, HasSuppressLedgerEntry = (mask & 16) != 0 };
                if ((mask & 4) != 0) target.BuffsBySource[(id, true)] = new CardBuff { SourceCardId = id, Temporary = true, Defense = 3 };
            }
            Seed(sourceId, cm); Seed(30, om);
            var unrelated = new CardBuff { SourceCardId = 99, Attack = 1 };
            target.BuffsBySource[(99, false)] = unrelated;
            target.Defense = 1; target.MaxDefense = 123;
            method.Invoke(engine.Api, new object[] { target, 5, sourceId });
            var current = target.BuffsBySource[(sourceId, false)]; bool foreignPresent = (om & 8) != 0;
            if (target.Defense != 1 || target.MaxDefense != 5 || !current.HasSuppressLedgerEntry
                || current.Defense != ((cm & 1) != 0 ? 2 : 0) || current.DefenseSetValue != ((cm & 2) != 0 ? 0 : null)
                || current.AttackSetValue != ((cm & 8) != 0 ? 0 : null) || current.IsEmpty
                || target.BuffsBySource.Count != 2 + ((cm & 4) != 0 ? 1 : 0) + ((om & 4) != 0 ? 1 : 0) + (foreignPresent ? 1 : 0)
                || target.BuffsBySource.ContainsKey((30, false)) != foreignPresent
                || (foreignPresent && (target.BuffsBySource[(30, false)].Defense != 0 || target.BuffsBySource[(30, false)].DefenseSetValue.HasValue
                    || target.BuffsBySource[(30, false)].HasSuppressLedgerEntry || target.BuffsBySource[(30, false)].AttackSetValue != 0))
                || ((cm & 4) != 0 && target.BuffsBySource[(sourceId, true)].Defense != 3)
                || ((om & 4) != 0 && target.BuffsBySource[(30, true)].Defense != 3)
                || !ReferenceEquals(target.BuffsBySource[(99, false)], unrelated)
                || !source.CardsBuffedByThisCard.SequenceEqual(sourceId == 20 && !reverse.Contains(60) ? reverse.Append(60) : reverse)
                || !foreign.CardsBuffedByThisCard.SequenceEqual(new[] { 60, 60, 888 })
                || state.ActionLog.SelectMany(x => x.SubActions).Any())
                return $"压制防御账本矩阵错误 cm={cm},om={om},source={sourceId}";
        }
        return null;
    }

    private static string? SuppressionDefensePhaseBoundary(CardDatabase db)
    {
        var method = typeof(CardApi).GetMethod("ApplySuppressionDefensePhase", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int defense in new[] { -100, 0, 1, 4, 5, 6, 99, 100, 105 })
        foreach (int template in new[] { 0, 1, 5, 99 })
        foreach (int sourceId in new[] { -1, 0, 20, 9999 })
        foreach (bool buffable in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_t_34", side, 20, CardLocation.Discard, 0);
            var foreign = state.CreateWithId("card_unit_t_34", side, 30, CardLocation.Discard, 0);
            var target = state.CreateWithId("card_unit_t_34", side, 60, side.HqOf(), 1);
            target.Keywords.Clear(); target.Keywords.Add(Keyword.Suppressed); if (!buffable) target.Keywords.Add(Keyword.Covert);
            target.Defense = defense; target.MaxDefense = 123;
            target.BuffsBySource[(20, false)] = new CardBuff { SourceCardId = 20, Defense = 2, DefenseSetValue = 0, Attack = 3, HasSuppressLedgerEntry = true };
