                || calls.Length != expected.Count || !calls.Zip(expected).All(x => x.First.StartsWith(x.Second, StringComparison.Ordinal))
                || (!suppressed && !Payload(target)) || (suppressed && target.BlueprintVariables.ContainsKey("_auditAttack_changedAmount"))
                || (receives && (!Payload(watcher) || !ReferenceEquals(watcher.BlueprintVariables.GetValueOrDefault("_auditAttack_cardChanged"), target))))
                return $"攻击撤销载荷/事件错误 side={side}, suppressed={suppressed}, watcherSuppressed={watcherSuppressed}, exception={exception}, where={where}, previous={previous}, buff={buffAmount}";
        }
        return null;
    }

    private static string? TemporaryAttackEventSnapshot(CardDatabase db)
    {
        const string name = "card_unit_arado_ar_196", own = "OnAfterChangeAttack", other = "OnAfterOtherCardChangeAttack";
        using var programs = InstallAttackChangeProbes();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool suppressed in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            CardDefinition Definition(bool registered) => new() { Name = name, Type = "fighter", UsedTriggers = registered ? new[] { other } : Array.Empty<string>() };
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(name, side, 60, side.HqOf(), 1);
            var first = state.CreateWithId(name, Side.Left, 30, CardLocation.Discard, 0);
            var later = state.CreateWithId(name, Side.Left, 70, CardLocation.Discard, 1);
            foreach (var card in new[] { target, first, later }) { card.Keywords.Clear(); card.Definition = Definition(card != first || suppressed); }
            if (suppressed) target.Keywords.Add(Keyword.Suppressed);
            target.Attack = 14;
            target.BuffsBySource[(20, true)] = new CardBuff { SourceCardId = 20, Temporary = true, Attack = 4, Defense = 3 };
            source.CardsBuffedByThisCard.Add(60);
            for (int i = 0; i < 5; i++) state.CreateWithId("card_unit_51e_regiment", Side.Left, 100 + i, CardLocation.DeckLeft, i);
            state.CreateWithId("card_unit_51e_regiment", Side.Right, 110, CardLocation.DeckRight, 0);
            int stage = 0; bool stateAtEvent = true; CardInstance? beforeQuery = null, late = null;
            using var draw = InstallDrawReentryProbe(state, () => {
                stage++; stateAtEvent &= target.Attack == 10 && target.BuffsBySource[(20, true)].Attack == 0
                    && target.BuffsBySource[(20, true)].Defense == 3
                    && state.ActionLog.SelectMany(x => x.SubActions).Any(x => x.Name == "ZActionGainAttack" && x.Values.Count == 7);
                if (!suppressed && stage == 1) {
                    first.Definition = Definition(true);
                    beforeQuery = state.CreateWithId(name, Side.Left, 65, CardLocation.Discard, 0);
                    beforeQuery.Keywords.Clear(); beforeQuery.Definition = Definition(true);
                }
                else if (stage == (suppressed ? 1 : 2)) {
                    later.Keywords.Add(Keyword.Suppressed); later.Definition = Definition(false);
                    state.Move(later, CardLocation.NotAvailable, 0, notifyMoved: false);
                    late = state.CreateWithId(name, Side.Left, 90, CardLocation.Discard, 0);
                    late.Keywords.Clear(); late.Definition = Definition(true);
                }
            });
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            state.AddBuffsToRemoveEndOfTurn(0, 20);
            engine.Api.RemoveTemporaryBuffs();
            var calls = trace.Where(x => x.StartsWith(own + " → ") || x.StartsWith(other + " → ")).ToArray();
            var expected = new List<string>();
            if (!suppressed) expected.Add($"{own} → {name}#60");
            expected.Add($"{other} → {name}#30");
            if (!suppressed) expected.Add($"{other} → {name}#65");
            expected.Add($"{other} → {name}#70");
            if (!stateAtEvent || stage != expected.Count || calls.Length != expected.Count
                || !calls.Zip(expected).All(x => x.First.StartsWith(x.Second, StringComparison.Ordinal))
                || (!suppressed && beforeQuery is null) || late is null
                || !ReferenceEquals(later.BlueprintVariables.GetValueOrDefault("_auditAttack_cardChanged"), target)
                || late.BlueprintVariables.ContainsKey("_auditAttack_cardChanged"))
                return $"攻击撤销须自身后查询T5并保存接收对象 side={side}, suppressed={suppressed}, stage={stage}";
        }
        return null;
    }

    private static string? TemporaryCleanupAttackOnly(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int mask in Enumerable.Range(0, 32))
        foreach (int amount in new[] { -3, 4 })
        foreach (bool suppressed in new[] { false, true })
        foreach (bool permanent in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId("card_unit_arado_ar_196", side, 60, side.HqOf(), 1);
            target.Keywords.Clear(); if (suppressed) target.Keywords.Add(Keyword.Suppressed);
            target.Attack = 10 + amount; target.Defense = 13; target.MaxDefense = 17;
            int kredit = target.KreditCost, operation = target.OperationCost;
            var buff = new CardBuff { SourceCardId = 20, Temporary = true, Attack = amount,
                Defense = (mask & 1) != 0 ? 3 : 0, KreditCost = (mask & 2) != 0 ? -1 : 0,
                OperationCost = (mask & 4) != 0 ? 2 : 0, HeavyArmor = (mask & 8) != 0 ? 1 : 0,
                HasNonOrdinaryDefenseEntry = (mask & 16) != 0 };
            var expected = buff.Clone(); expected.Attack = 0;
            target.BuffsBySource[(20, true)] = buff; source.CardsBuffedByThisCard.Add(60);
            if (permanent) target.BuffsBySource[(20, false)] = new CardBuff { SourceCardId = 20, Defense = 2 };
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            state.AddBuffsToRemoveEndOfTurn(0, 20);
            engine.Api.RemoveTemporaryBuffs();
            bool retained = !expected.IsEmpty;
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            if (target.Attack != 10 || target.Defense != 13 || target.MaxDefense != 17
                || target.KreditCost != kredit || target.OperationCost != operation
                || target.BuffsBySource.ContainsKey((20, true)) != retained
                || source.CardsBuffedByThisCard.Contains(60) != (retained || permanent)
                || target.BuffsBySource.ContainsKey((20, false)) != permanent
                || (retained && System.Text.Json.JsonSerializer.Serialize(target.BuffsBySource[(20, true)])
                    != System.Text.Json.JsonSerializer.Serialize(expected))
                || actions.Length != 1 || actions[0].Name != "ZActionGainAttack"
                || actions[0].Values.Single(x => x.Name == "gained").Value != -amount
                || trace.Any(x => x.StartsWith("OnAfterOtherCardOperactionCost")))
                return $"只撤攻击应保留混合字段 side={side}, mask={mask}, amount={amount}, suppressed={suppressed}, permanent={permanent}";
        }
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int mask in Enumerable.Range(1, 31))
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId("card_unit_arado_ar_196", side, 60, side.HqOf(), 1);
            var buff = new CardBuff { SourceCardId = 20, Temporary = true,
                Defense = (mask & 1) != 0 ? 3 : 0, KreditCost = (mask & 2) != 0 ? -1 : 0,
                OperationCost = (mask & 4) != 0 ? 2 : 0, HeavyArmor = (mask & 8) != 0 ? 1 : 0,
                HasNonOrdinaryDefenseEntry = (mask & 16) != 0 };
            target.BuffsBySource[(20, true)] = buff; source.CardsBuffedByThisCard.Add(60);
            string before = System.Text.Json.JsonSerializer.Serialize(new { target.Attack, target.Defense, target.MaxDefense, Buff = buff });
            state.AddBuffsToRemoveEndOfTurn(0, 20);
            engine.Api.RemoveTemporaryBuffs();
            string after = System.Text.Json.JsonSerializer.Serialize(new { target.Attack, target.Defense, target.MaxDefense, Buff = buff });
            if (before != after || !ReferenceEquals(target.BuffsBySource.GetValueOrDefault((20, true)), buff)
                || !source.CardsBuffedByThisCard.Contains(60) || state.ActionLog.SelectMany(x => x.SubActions).Any())
                return "无攻击量的临时槽不得被统一清除或产生零量攻击通知";
        }
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int amount in new[] { -3, 4 })
        foreach (int previous in new[] { 0, 1 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId("card_unit_arado_ar_196", side, 60, side.HqOf(), 1);
            target.Attack = previous;
            target.BuffsBySource[(20, true)] = new CardBuff { SourceCardId = 20, Temporary = true, Attack = amount };
            source.CardsBuffedByThisCard.Add(60);
            state.AddBuffsToRemoveEndOfTurn(0, 20);
            engine.Api.RemoveTemporaryBuffs();
            int expected = Math.Max(0, previous - amount);
            var gain = state.ActionLog.SelectMany(x => x.SubActions).Single(x => x.Name == "ZActionGainAttack");
            if (target.Attack != expected || gain.Values.Single(x => x.Name == "gained").Value != expected - previous)
                return "攻击撤销的通知应使用实际变化量，不能直接使用账本逆量";
        }
        return null;
    }

    private static string? TemporaryCleanupBoardGate(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (var location in new[] { side.HqOf(), CardLocation.BoardFrontline, side.HandOf(), side.DeckOf(), CardLocation.Discard, CardLocation.NotAvailable })
        foreach (bool suppressed in new[] { false, true })
        foreach (int amount in new[] { -2, 3 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId("card_unit_arado_ar_196", side, 60, location, 1);
            target.Definition = new CardDefinition { Name = target.Name, Type = "fighter", Attack = 10, Defense = 10 };
            target.Keywords.Clear(); if (suppressed) target.Keywords.Add(Keyword.Suppressed);
            target.Attack = 10 + amount; target.Defense = target.MaxDefense = 10;
            target.BuffsBySource[(20, true)] = new CardBuff { SourceCardId = 20, Temporary = true, Attack = amount };
            source.CardsBuffedByThisCard.Add(60);
            // Ordinary source slot must survive temporary-attack withdrawal.
            target.BuffsBySource[(20, false)] = new CardBuff { SourceCardId = 20, Defense = 2 };
            state.AddBuffsToRemoveEndOfTurn(0, 20);
            engine.Api.RemoveTemporaryBuffs();
            bool board = location.IsBoard();
            if (target.Attack != (board ? 10 : 10 + amount) || target.Defense != 10 || target.MaxDefense != 10
                || target.Location != location || target.BuffsBySource.ContainsKey((20, true)) == board
                || target.BuffsBySource[(20, false)].Defense != 2 || !source.CardsBuffedByThisCard.Contains(60)
                || state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionGainAttack") != (board ? 1 : 0))
                return $"回合末撤销应检查当前在场位置 side={side}, location={location}, suppressed={suppressed}, amount={amount}";
        }
        // Mixed non-attack records must remain entirely untouched off board.
        foreach (var location in new[] { CardLocation.HandLeft, CardLocation.DeckLeft, CardLocation.Discard, CardLocation.NotAvailable })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId("card_unit_arado_ar_196", Side.Left, 60, location, 1);
            target.Attack = 12; target.Defense = 13; target.MaxDefense = 15;
            var buff = new CardBuff { SourceCardId = 20, Temporary = true, Attack = 2, Defense = 3,
                KreditCost = -1, OperationCost = 2, HeavyArmor = 1, HasNonOrdinaryDefenseEntry = true };
            target.BuffsBySource[(20, true)] = buff; source.CardsBuffedByThisCard.Add(60);
            string before = System.Text.Json.JsonSerializer.Serialize(new { target.Attack, target.Defense, target.MaxDefense, Buff = buff });
            state.AddBuffsToRemoveEndOfTurn(0, 20);
            engine.Api.RemoveTemporaryBuffs();
            string after = System.Text.Json.JsonSerializer.Serialize(new { target.Attack, target.Defense, target.MaxDefense, Buff = buff });
            if (before != after || !ReferenceEquals(target.BuffsBySource.GetValueOrDefault((20, true)), buff)
                || !source.CardsBuffedByThisCard.Contains(60) || state.ActionLog.SelectMany(x => x.SubActions).Any())
                return "离场混合临时槽不得被回合末扫描移除、逆算或发送通知";
        }
        return null;
    }

    private static string? DefenseSetSkipInvariant(CardDatabase db)
    {
        const string probe = "card_unit_arado_ar_196", own = "OnAfterDefenseIsSet", other = "OnAfterOtherCardDefenseIsSet";
        using var programs = InstallDefenseSetEventProbes();
        // This fixture measures set callbacks without drawing a deck-resident
        // target out of the very location whose behavior is under test.
        var locals = (IDictionary<string, IReadOnlyList<KismetStep>>)KismetLibrary.Default!.Find(probe)!.Locals;
        foreach (string hook in new[] { own, other })
            locals[hook] = locals[hook].Where(step => step.Function != "DrawCardsFromDeckBySide")
                .Select((step, i) => step with { Index = i }).ToArray();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int location in new[] { 0, 1, 2 })
        foreach (bool sourceExists in new[] { false, true })
        foreach (bool suppressed in new[] { false, true })
        foreach (int requested in new[] { -7, 0, 1, 10, 150 })
        {
            string? normal = null;
            foreach (bool skip in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var source = sourceExists ? state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0) : null;
                int sourceId = sourceExists ? 20 : 9999;
                var initial = location switch { 1 => side.HandOf(), 2 => side.DeckOf(), _ => side.HqOf() };
                var target = state.CreateWithId(probe, side, 60, initial, 0);
                var observer = state.CreateWithId(probe, Side.Left, 30, CardLocation.Discard, 0);
                foreach (var card in new[] { target, observer }) {
                    card.Definition = new CardDefinition { Name = probe, Type = "fighter", UsedTriggers = new[] { other } };
                    card.Keywords.Clear();
                }
                if (suppressed) target.Keywords.Add(Keyword.Suppressed);
                target.Defense = 10; target.MaxDefense = 30;
                var trace = new List<string>(); engine.Api.TriggerTrace = trace;
                engine.Api.InvokeByName("ChangeDefense", target, new object?[] { target, sourceId, requested, 2, skip, null },
                    new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out _);
                int value = Math.Clamp(requested, 0, 99);
                var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
                var gains = actions.Where(x => x.Name == "ZActionGainDefense").ToArray();
                var destroys = actions.Where(x => x.Name == "ZActionDestroyUnit").ToArray();
                var calls = trace.Where(x => x.StartsWith(own + " → ") || x.StartsWith(other + " → ")).ToArray();
                if (target.Defense != value || target.MaxDefense != value || target.Location != (value == 0 ? CardLocation.Discard : initial)
                    || gains.Length != 1 || destroys.Length != (value == 0 ? 1 : 0)
                    || gains[0].Values.Single(x => x.Name == "gained").Value != requested
                    || gains[0].Values.Single(x => x.Name == "newDefenseValue").Value != value
                    || gains[0].Values.Single(x => x.Name == "instigatorID").Value != sourceId
                    || calls.Length != 2 || !calls[0].StartsWith($"{own} → {probe}#60") || !calls[1].StartsWith($"{other} → {probe}#30")
                    || !ReferenceEquals(observer.BlueprintVariables.GetValueOrDefault("_auditDefenseSetSubject"), target)
                    || (value == 0 && (destroys[0].Values.Single(x => x.Name == "destroyerCardID").Value != (sourceExists ? 20 : 0)
                        || Array.IndexOf(actions, gains[0]) >= Array.IndexOf(actions, destroys[0]))))
                    return $"设值skip须无影响 side={side}, location={location}, source={sourceExists}, suppressed={suppressed}, requested={requested}, skip={skip}";
                string signature = System.Text.Json.JsonSerializer.Serialize(new {
                    target.Defense, target.MaxDefense, target.Location, Calls = calls,
                    Actions = actions.Select(x => new { x.Name, x.Values }), Buff = target.BuffsBySource[(sourceId, false)]
                });
                if (skip && signature != normal) return "设值skip true/false产生不同状态、通知或回调";
                normal = signature;
            }
        }
        return null;
    }

    private static string? DefenseDecreaseSkipNotification(CardDatabase db)
    {
        const string probe = "card_unit_arado_ar_196";
        using var beforePrograms = InstallDefenseChainProbes();
        using var afterPrograms = InstallDefenseAfterGainProbes();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int location in new[] { 0, 1, 2 })
        foreach (bool skip in new[] { false, true })
        foreach (bool sourceExists in new[] { false, true })
        foreach (bool suppressed in new[] { false, true })
        foreach (int maximum in new[] { 5, 30 })
        foreach (int delta in new[] { -1, -10, -20 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = sourceExists ? state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0) : null;
            int sourceId = sourceExists ? 20 : 9999;
            var initial = location switch { 1 => side.HandOf(), 2 => side.DeckOf(), _ => side.HqOf() };
            var target = state.CreateWithId(probe, side, 60, initial, 0);
            target.Definition = new CardDefinition { Name = probe, Type = "fighter" };
            target.Keywords.Clear(); if (suppressed) target.Keywords.Add(Keyword.Suppressed);
            target.Defense = 10; target.MaxDefense = maximum;
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            engine.Api.InvokeByName("ChangeDefense", target, new object?[] { target, sourceId, delta, 1, skip, null },
                new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out _);
            bool lethal = 10 + delta <= 0;
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            var gains = actions.Where(x => x.Name == "ZActionGainDefense").ToArray();
            var destroys = actions.Where(x => x.Name == "ZActionDestroyUnit").ToArray();
            if (target.Defense != 10 + delta || target.MaxDefense != (lethal ? maximum : maximum + delta)
                || target.Location != (lethal ? CardLocation.Discard : initial)
                || target.BuffsBySource[(sourceId, false)].Defense != delta
                || gains.Length != (skip ? 0 : 1) || destroys.Length != (lethal ? 1 : 0)
                || trace.Any(x => x.StartsWith("OnBeforeGainDefense") || x.StartsWith("OnBeforeOtherCardGainDefense")
                    || x.StartsWith("OnAfterGainDefense") || x.StartsWith("OnAfterOtherCardGainDefense")))
                return $"减防skip错误 side={side}, location={location}, skip={skip}, source={sourceExists}, suppressed={suppressed}, max={maximum}, delta={delta}";
            if (!skip && (gains[0].Values.Single(x => x.Name == "gained").Value != delta
                || gains[0].Values.Single(x => x.Name == "newDefenseValue").Value != 10 + delta
                || gains[0].Values.Single(x => x.Name == "instigatorID").Value != sourceId))
                return "减防通知须保留负请求、新防御及原始来源ID";
            if (lethal && (destroys[0].Values.Single(x => x.Name == "destroyerCardID").Value != (sourceExists ? 20 : 0)
                || (!skip && Array.IndexOf(actions, destroys[0]) >= Array.IndexOf(actions, gains[0]))))
                return "减防skip不得省略销毁，未skip时销毁须早于通知";
        }
        return null;
    }

    private static string? DefenseDecreaseSkipDestroyCallbacks(CardDatabase db)
    {
        const string probe = "card_unit_arado_ar_196";
        using var beforeDestroyed = InstallSelectionDrawProbe(probe, "OnBeforeDestroyed");
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool skip in new[] { false, true })
        foreach (bool sourceExists in new[] { false, true })
        foreach (int rewrittenDefense in new[] { -5, 7 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = sourceExists ? state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0) : null;
            int sourceId = sourceExists ? 20 : 9999;
            var target = state.CreateWithId(probe, side, 60, side.HqOf(), 0);
            target.Definition = new CardDefinition { Name = probe, Type = "fighter" };
            target.Keywords.Clear(); target.Defense = 10; target.MaxDefense = 30;
            state.CreateWithId("card_unit_51e_regiment", side, 100, side.DeckOf(), 0);
            int calls = 0; bool sawLethal = true;
            using var draw = InstallDrawReentryProbe(state, () => {
                calls++; sawLethal &= target.Defense == -10 && target.MaxDefense == 30
                    && target.BuffsBySource[(sourceId, false)].Defense == -20;
                target.Defense = rewrittenDefense;
            });
            engine.Api.ChangeDefense(target, -20, source, instigatorId: sourceId, skipAction: skip);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            var gains = actions.Where(x => x.Name == "ZActionGainDefense").ToArray();
            var destroys = actions.Where(x => x.Name == "ZActionDestroyUnit").ToArray();
            if (calls != 1 || !sawLethal || target.Location != CardLocation.Discard || target.Defense != rewrittenDefense
                || destroys.Length != 1 || gains.Length != (skip ? 0 : 1)
                || destroys[0].Values.Single(x => x.Name == "destroyerCardID").Value != (sourceExists ? 20 : 0)
                || (!skip && (gains[0].Values.Single(x => x.Name == "newDefenseValue").Value != rewrittenDefense
                    || Array.IndexOf(actions, destroys[0]) >= Array.IndexOf(actions, gains[0]))))
                return $"致死减防skip须在销毁回调后决定通知 side={side}, skip={skip}, source={sourceExists}, current={rewrittenDefense}, calls={calls}";
        }
        return null;
    }

    private static string? DefenseGainSkipAndDeck(CardDatabase db)
    {
        const string probe = "card_unit_arado_ar_196", before = "OnBeforeOtherCardGainDefense", after = "OnAfterOtherCardGainDefense";
        using var beforeProgram = InstallDefenseBeforeLedgerProbe(before);
        using var afterPrograms = InstallDefenseAfterGainProbes();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool inDeck in new[] { false, true })
        foreach (bool skip in new[] { false, true })
        foreach (int move in new[] { 0, 1, 2, 3 })
        foreach (int amount in new[] { 2, 100 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(probe, side, 60, inDeck ? side.DeckOf() : side.HqOf(), 99);
            target.Definition = new CardDefinition { Name = probe, Type = "fighter" };
            target.Keywords.Clear(); target.Keywords.Add(Keyword.Suppressed); target.Defense = target.MaxDefense = 10;
            var observer = state.CreateWithId(probe, Side.Left, 30, CardLocation.Discard, 0);
            observer.Definition = new CardDefinition { Name = probe, Type = "fighter", UsedTriggers = new[] { before, after } };
            observer.Keywords.Clear(); observer.BlueprintVariables["_auditRewriteDefense"] = 5;
            observer.BlueprintVariables["_auditStopDefense"] = false;
            for (int i = 0; i < 3; i++) state.CreateWithId("card_unit_51e_regiment", Side.Left, 100 + i, CardLocation.DeckLeft, i);
            int calls = 0; bool original = true;
            var initialLocation = target.Location;
            var requestedLocation = move switch { 1 => side.DeckOf(), 2 => side.HandOf(), 3 => side.HqOf(), _ => initialLocation };
            using var draw = InstallDrawReentryProbe(state, () => {
                calls++;
                if (calls == 1) {
                    original &= target.Defense == 10 && target.BuffsBySource[(20, false)].Defense == amount;
                    if (move != 0) state.Move(target, requestedLocation, 99, notifyMoved: false);
                }
            });
            engine.Api.InvokeByName("ChangeDefense", target, new object?[] { target, 20, amount, 1, skip, null },
                new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out _);
            var finalLocation = skip ? initialLocation : requestedLocation;
            bool notified = !skip && finalLocation != CardLocation.DeckLeft && finalLocation != CardLocation.DeckRight;
            int applied = skip ? amount : 5;
            var gains = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionGainDefense").ToArray();
            if (!original || calls != (skip ? 0 : notified ? 2 : 1) || target.Location != finalLocation
                || target.Defense != Math.Clamp(10 + applied, 1, 99) || target.MaxDefense != target.Defense
                || target.BuffsBySource[(20, false)].Defense != amount || gains.Length != (notified ? 1 : 0)
                || observer.BlueprintVariables.ContainsKey("_auditGainSubject") != notified
                || (notified && (gains[0].Values.Single(x => x.Name == "gained").Value != 5
                    || !Equals(observer.BlueprintVariables.GetValueOrDefault("_auditGainAmount"), 5))))
                return $"skip/牌库门错误 side={side}, deck={inDeck}, skip={skip}, move={move}, amount={amount}, calls={calls}, def={target.Defense}, gain={gains.Length}";
        }
        return null;
    }

    private static string? DefenseGainSkipBeforeChain(CardDatabase db)
    {
        const string probe = "card_unit_arado_ar_196";
        using var beforePrograms = InstallDefenseChainProbes();
        using var afterPrograms = InstallDefenseAfterGainProbes();
        // Reentry markers are spawned in the right deck. Draw measurement cards
        // from the left deck so two right-side own hooks cannot draw a marker.
        var locals = (IDictionary<string, IReadOnlyList<KismetStep>>)KismetLibrary.Default!.Find(probe)!.Locals;
        foreach (string hook in new[] { "OnBeforeGainDefense", "OnAfterGainDefense" })
            locals[hook] = locals[hook].Select(step => step.Op == "call" && step.Function == "DrawCardsFromDeckBySide"
                ? step with { Args = step.Args.Select((arg, i) => i == 1 ? new KismetExpr { Int = (int)Side.Left } : arg).ToArray() }
                : step).ToArray();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool inDeck in new[] { false, true })
        foreach (bool skip in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(probe, side, 60, inDeck ? side.DeckOf() : side.HqOf(), 99);
            target.Definition = new CardDefinition { Name = probe, Type = "fighter" };
            target.Keywords.Clear(); target.Defense = target.MaxDefense = 10;
            var observer = state.CreateWithId(probe, Side.Left, 30, CardLocation.Discard, 0);
            observer.Definition = new CardDefinition { Name = probe, Type = "fighter", UsedTriggers = new[] {
                "OnBeforeOtherCardGainDefense", "OnBeforeOtherCardGainDefenseAfterAdd", "OnAfterOtherCardGainDefense" } };
            observer.Keywords.Clear(); observer.BlueprintVariables["_auditChainDelta"] = 3;
            for (int i = 0; i < 6; i++) state.CreateWithId("card_unit_51e_regiment", Side.Left, 100 + i, CardLocation.DeckLeft, i);
            for (int i = 0; i < 2; i++) state.CreateWithId("card_unit_51e_regiment", Side.Right, 110 + i, CardLocation.DeckRight, i);
            int calls = 0;
            using var draw = InstallDrawReentryProbe(state, () => calls++);
            engine.Api.ChangeDefense(target, 2, source, skipAction: skip);
            if (calls != (skip ? 0 : inDeck ? 3 : 5) || target.Defense != (skip ? 12 : 15)
                || target.BuffsBySource[(20, false)].Defense != 2
                || state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionGainDefense") != (!skip && !inDeck ? 1 : 0))
                return $"skip须跳过自身和16/17前链 side={side}, deck={inDeck}, skip={skip}, calls={calls}, def={target.Defense}";
        }
        return null;
    }

    private static string? DefenseGainNoTrailingDeathCheck(CardDatabase db)
    {
        const string probe = "card_unit_arado_ar_196", other = "OnAfterOtherCardGainDefense";
        using var programs = InstallDefenseAfterGainProbes();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int mutationStage in new[] { 1, 2 })
        foreach (int defense in new[] { -3, 0, 1 })
        foreach (int move in new[] { 0, 1, 2, 3 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(probe, side, 60, side.HqOf(), 1);
            var first = state.CreateWithId(probe, Side.Left, 30, CardLocation.HandLeft, 0);
            var later = state.CreateWithId(probe, Side.Left, 70, CardLocation.HandLeft, 1);
            foreach (var card in new[] { target, first, later }) {
                card.Keywords.Clear(); card.Definition = new CardDefinition { Name = probe, Type = "fighter", UsedTriggers = new[] { other } };
            }
            target.Defense = target.MaxDefense = 10;
            for (int i = 0; i < 4; i++) state.CreateWithId("card_unit_51e_regiment", Side.Left, 100 + i, CardLocation.DeckLeft, i);
            state.CreateWithId("card_unit_51e_regiment", Side.Right, 110, CardLocation.DeckRight, 0);
            int stage = 0;
            var expectedLocation = move switch { 1 => side.HandOf(), 2 => CardLocation.Discard, 3 => CardLocation.NotAvailable, _ => side.HqOf() };
            using var draw = InstallDrawReentryProbe(state, () => {
                stage++;
                if (stage == mutationStage) {
                    target.Defense = defense;
                    if (move != 0) state.Move(target, expectedLocation, 0, notifyMoved: false);
                }
            });
            engine.Api.ChangeDefense(target, 2, source);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            if (stage != 3 || target.Defense != defense || target.Location != expectedLocation
                || actions.Any(x => x.Name == "ZActionDestroyUnit")
                || actions.Count(x => x.Name == "ZActionGainDefense") != 1
                || target.BuffsBySource[(20, false)].Defense != 2
                || !ReferenceEquals(later.BlueprintVariables.GetValueOrDefault("_auditGainSubject"), target))
                return $"增防返回不应追加销毁 side={side}, stage={mutationStage}, defense={defense}, move={move}, actual={target.Location}/{target.Defense}, calls={stage}";
            // Compatibility check for the existing separate sweep, not certification
            // of the client's global death scheduling or destroyer policy.
            engine.CheckDeaths();
            var destroys = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionDestroyUnit").ToArray();
            bool swept = move == 0 && defense <= 0;
            if (destroys.Length != (swept ? 1 : 0)
                || (swept && (target.Location != CardLocation.Discard
                    || destroys[0].Values.Single(x => x.Name == "destroyerCardID").Value != 0)))
                return "独立CheckDeaths的既有行为被增防修复改变";
        }
        return null;
    }

