    private static IDisposable InstallDefenseAfterGainProbes()
    {
        const string name = "card_unit_arado_ar_196", own = "OnAfterGainDefense", other = "OnAfterOtherCardGainDefense";
        var first = InstallSelectionDrawProbe(name, own);
        try
        {
            var second = InstallSelectionDrawProbe(name, other);
            var locals = (IDictionary<string, IReadOnlyList<KismetStep>>)KismetLibrary.Default!.Find(name)!.Locals;
            foreach (string hook in new[] { own, other })
            {
                var markers = new List<KismetStep> {
                    new(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                        new KismetExpr { Var = "K2Node_Event_defenseGained", Scope = "local" }, null, -1, "_auditGainAmount", null) { DestinationScope = "instance" },
                };
                if (hook == other) markers.Add(new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "K2Node_Event_cardGainingDefense", Scope = "local" }, null, -1, "_auditGainSubject", null) { DestinationScope = "instance" });
                locals[hook] = markers.Concat(locals[hook].Select(x => x with { Index = x.Index + markers.Count })).ToArray();
            }
            return new AuditProbeCleanup(() => { second.Dispose(); first.Dispose(); });
        }
        catch { first.Dispose(); throw; }
    }

    private static string? DefenseAfterGainDispatch(CardDatabase db)
    {
        const string probe = "card_unit_arado_ar_196", own = "OnAfterGainDefense", other = "OnAfterOtherCardGainDefense";
        using var programs = InstallDefenseAfterGainProbes();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool suppressed in new[] { false, true })
        foreach (bool observerSuppressed in new[] { false, true })
        foreach (bool exception in new[] { false, true })
        foreach (var location in new[] { CardLocation.HandLeft, CardLocation.Discard, CardLocation.NotAvailable })
        foreach (int amount in new[] { 1, 100 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(probe, side, 60, side.HqOf(), 1);
            var observer = state.CreateWithId(probe, Side.Left, 30, location, 0);
            foreach (var card in new[] { target, observer }) {
                card.Definition = new CardDefinition { Name = probe, Type = "fighter", UsedTriggers = new[] { other } };
                card.Keywords.Clear(); card.SuppressionExceptionTriggers.Clear();
            }
            if (suppressed) target.Keywords.Add(Keyword.Suppressed);
            if (observerSuppressed) observer.Keywords.Add(Keyword.Suppressed);
            if (exception) observer.SuppressionExceptionTriggers.Add(other);
            target.Defense = target.MaxDefense = 98;
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            engine.Api.ChangeDefense(target, amount, source);
            bool receives = !observerSuppressed || exception;
            var calls = trace.Where(x => x.StartsWith(own + " → ") || x.StartsWith(other + " → ")).ToArray();
            var expected = new List<string>();
            if (!suppressed) expected.Add($"{own} → {probe}#60");
            if (receives) expected.Add($"{other} → {probe}#30");
            if (calls.Length != expected.Count || !calls.Zip(expected).All(x => x.First.StartsWith(x.Second, StringComparison.Ordinal))
                || (!suppressed && !Equals(target.BlueprintVariables.GetValueOrDefault("_auditGainAmount"), amount))
                || (suppressed && target.BlueprintVariables.ContainsKey("_auditGainAmount"))
                || (receives && (!Equals(observer.BlueprintVariables.GetValueOrDefault("_auditGainAmount"), amount)
                    || !ReferenceEquals(observer.BlueprintVariables.GetValueOrDefault("_auditGainSubject"), target))))
                return $"增防后派发错误 side={side}, suppressed={suppressed}, observerSuppressed={observerSuppressed}, exception={exception}, location={location}, amount={amount}";
        }
        return null;
    }

    private static string? DefenseAfterGainSnapshot(CardDatabase db)
    {
        const string probe = "card_unit_arado_ar_196", own = "OnAfterGainDefense", other = "OnAfterOtherCardGainDefense";
        using var programs = InstallDefenseAfterGainProbes();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool suppressed in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            CardDefinition Definition(bool registered) => new() { Name = probe, Type = "fighter", UsedTriggers = registered ? new[] { other } : Array.Empty<string>() };
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var target = state.CreateWithId(probe, side, 60, side.HqOf(), 1);
            var first = state.CreateWithId(probe, Side.Left, 30, CardLocation.Discard, 0);
            var later = state.CreateWithId(probe, Side.Left, 70, CardLocation.Discard, 1);
            foreach (var card in new[] { target, first, later }) { card.Keywords.Clear(); card.Definition = Definition(card != first || suppressed); }
            if (suppressed) target.Keywords.Add(Keyword.Suppressed);
            target.Defense = target.MaxDefense = 98;
            for (int i = 0; i < 5; i++) state.CreateWithId("card_unit_51e_regiment", Side.Left, 100 + i, CardLocation.DeckLeft, i);
            state.CreateWithId("card_unit_51e_regiment", Side.Right, 110, CardLocation.DeckRight, 0);
            int stage = 0; CardInstance? beforeQuery = null, afterQuery = null; bool stateAtEvent = true;
            using var draw = InstallDrawReentryProbe(state, () => {
                stage++;
                stateAtEvent &= target.Defense == 99 && target.MaxDefense == 99 && target.BuffsBySource[(20, false)].Defense == 5
                    && state.ActionLog.SelectMany(x => x.SubActions).Any(x => x.Name == "ZActionGainDefense");
                if (!suppressed && stage == 1) {
                    first.Definition = Definition(true);
                    beforeQuery = state.CreateWithId(probe, Side.Left, 65, CardLocation.Discard, 0);
                    beforeQuery.Keywords.Clear(); beforeQuery.Definition = Definition(true);
                }
                else if (stage == (suppressed ? 1 : 2)) {
                    later.Definition = Definition(false); later.Keywords.Add(Keyword.Suppressed);
                    state.Move(later, CardLocation.NotAvailable, 0, notifyMoved: false);
                    afterQuery = state.CreateWithId(probe, Side.Left, 90, CardLocation.Discard, 0);
                    afterQuery.Keywords.Clear(); afterQuery.Definition = Definition(true);
                }
            });
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            engine.Api.ChangeDefense(target, 5, source);
            var calls = trace.Where(x => x.StartsWith(own + " → ") || x.StartsWith(other + " → ")).ToArray();
            var expected = new List<string>();
            if (!suppressed) expected.Add($"{own} → {probe}#60");
            expected.Add($"{other} → {probe}#30");
            if (!suppressed) expected.Add($"{other} → {probe}#65");
            expected.Add($"{other} → {probe}#70");
            if (!stateAtEvent || stage != expected.Count || calls.Length != expected.Count
                || !calls.Zip(expected).All(x => x.First.StartsWith(x.Second, StringComparison.Ordinal))
                || (!suppressed && beforeQuery is null) || afterQuery is null
                || !ReferenceEquals(later.BlueprintVariables.GetValueOrDefault("_auditGainSubject"), target)
                || !Equals(later.BlueprintVariables.GetValueOrDefault("_auditGainAmount"), 5)
                || afterQuery.BlueprintVariables.ContainsKey("_auditGainSubject"))
                return $"增防后须自身后取快照，组内变化不重筛/补入 side={side}, suppressed={suppressed}, stage={stage}, calls={string.Join(";", calls)}, state={stateAtEvent}";
        }
        return null;
    }

    private static string? DefenseGainClampAfterCallbacks(CardDatabase db)
    {
        const string hook = "OnBeforeOtherCardGainDefense";
        using var program = InstallDefenseBeforeLedgerProbe(hook);
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int old in new[] { 1, 10, 98, 99, 105 })
        foreach (int rewritten in new[] { 1, 5, 100 })
        foreach (int? current in new int?[] { null, -20, 0, 1, 98, 99, 150 })
        foreach (int maximum in new[] { 1, 99, 150 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var observer = state.CreateWithId("card_unit_arado_ar_196", Side.Left, 30, CardLocation.Discard, 0);
            observer.Definition = new CardDefinition { Name = observer.Name, Type = "fighter", UsedTriggers = new[] { hook } };
            observer.Keywords.Clear(); observer.BlueprintVariables["_auditRewriteDefense"] = rewritten;
            observer.BlueprintVariables["_auditStopDefense"] = false;
            var target = state.CreateWithId("card_unit_arado_ar_196", side, 60, side.HqOf(), 1);
            target.Definition = new CardDefinition { Name = target.Name, Type = "fighter" };
            target.Keywords.Clear(); target.Keywords.Add(Keyword.Suppressed);
            target.Defense = old; target.MaxDefense = maximum;
            state.CreateWithId("card_unit_51e_regiment", Side.Left, 100, CardLocation.DeckLeft, 0);
            int calls = 0; bool original = true;
            using var draw = InstallDrawReentryProbe(state, () => {
                calls++; original &= target.Defense == old && target.BuffsBySource[(20, false)].Defense == 2;
                if (current.HasValue) target.Defense = current.Value;
            });
            engine.Api.ChangeDefense(target, 2, source, instigatorId: 20);
            int expected = Math.Clamp((current ?? old) + rewritten, 1, 99);
            var gains = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionGainDefense").ToArray();
            if (calls != 1 || !original || target.Defense != expected || target.MaxDefense != Math.Max(maximum, expected)
                || target.BuffsBySource[(20, false)].Defense != 2 || gains.Length != 1
                || gains[0].Values.Single(x => x.Name == "gained").Value != rewritten
                || gains[0].Values.Single(x => x.Name == "newDefenseValue").Value != expected)
                return $"正增防夹取错误 side={side}, old={old}, rewrite={rewritten}, current={current}, max={maximum}, actual={target.Defense}/{target.MaxDefense}, calls={calls}";
        }
        return null;
    }

    private static IDisposable InstallDefenseChainProbes()
    {
        const string name = "card_unit_arado_ar_196";
        var cleanups = new List<IDisposable>();
        try
        {
            foreach (string hook in new[] { "OnBeforeGainDefense", "OnBeforeOtherCardGainDefense", "OnBeforeOtherCardGainDefenseAfterAdd" })
            {
                cleanups.Add(InstallSelectionDrawProbe(name, hook));
                var locals = (IDictionary<string, IReadOnlyList<KismetStep>>)KismetLibrary.Default!.Find(name)!.Locals;
                var steps = new List<KismetStep>();
                bool own = hook == "OnBeforeGainDefense", rewrite = hook == "OnBeforeOtherCardGainDefense";
                string input = rewrite ? "defenseToAdd" : "defenseGaining";
                if (!own) steps.Add(new KismetStep(steps.Count, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = input, Scope = "local" }, null, -1, "_auditChainInput", null) { DestinationScope = "instance" });
                steps.Add(locals[hook][0] with { Index = steps.Count });
                if (rewrite) steps.Add(new KismetStep(steps.Count, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Math = "Add_IntInt", Args = new[] { new KismetExpr { Var = input, Scope = "local" },
                        new KismetExpr { Var = "_auditChainDelta", Scope = "instance" } } }, null, -1, "newDefenseToAdd", null));
                steps.Add(new KismetStep(steps.Count, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "_auditChainStop", Scope = "instance" }, null, -1, "stopAction", null));
                steps.Add(new KismetStep(steps.Count, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null));
                locals[hook] = steps;
            }
            return new AuditProbeCleanup(() => { foreach (var item in cleanups) item.Dispose(); });
        }
        catch { foreach (var item in cleanups) item.Dispose(); throw; }
    }

    private static string? DefenseBeforeChainOrder(CardDatabase db)
    {
        const string probe = "card_unit_arado_ar_196", own = "OnBeforeGainDefense", t16 = "OnBeforeOtherCardGainDefense", t17 = "OnBeforeOtherCardGainDefenseAfterAdd";
        using var programs = InstallDefenseChainProbes();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool suppressed in new[] { false, true })
        foreach (bool ownStop in new[] { false, true })
        foreach (int stopAt in Enumerable.Range(0, 5))
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            CardInstance Make(int id, string trigger, int delta, bool stop) {
                var card = state.CreateWithId(probe, Side.Left, id, CardLocation.Discard, id);
                card.Definition = new CardDefinition { Name = probe, Type = "fighter", UsedTriggers = new[] { trigger } };
                card.Keywords.Clear(); card.BlueprintVariables["_auditChainDelta"] = delta; card.BlueprintVariables["_auditChainStop"] = stop; return card;
            }
            var first = Make(30, t16, 1, stopAt == 1); var second = Make(40, t16, 2, stopAt == 2);
            var afterFirst = Make(50, t17, 0, stopAt == 3); var afterSecond = Make(70, t17, 0, stopAt == 4);
            var target = state.CreateWithId(probe, side, 60, side.HqOf(), 1);
            target.Definition = new CardDefinition { Name = probe, Type = "fighter", UsedTriggers = new[] { t16, t17 } };
            target.Keywords.Clear(); if (suppressed) target.Keywords.Add(Keyword.Suppressed);
            target.BlueprintVariables["_auditChainStop"] = ownStop; target.Defense = target.MaxDefense = 10;
            for (int i = 0; i < 6; i++) state.CreateWithId("card_unit_51e_regiment", Side.Left, 100 + i, CardLocation.DeckLeft, i);
            state.CreateWithId("card_unit_51e_regiment", Side.Right, 110, CardLocation.DeckRight, 0);
            int count = 0; bool beforeNumeric = true;
            using var draw = InstallDrawReentryProbe(state, () => { count++; beforeNumeric &= target.Defense == 10
                && target.MaxDefense == 10 && target.BuffsBySource[(20, false)].Defense == 2; });
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            engine.Api.ChangeDefense(target, 2, source, instigatorId: 20);
            bool stoppedOwn = !suppressed && ownStop;
            var expected = new List<(string Hook, int Id)>();
            if (!suppressed) expected.Add((own, 60));
            if (!stoppedOwn) {
                expected.Add((t16, 30));
                if (stopAt != 1) {
                    expected.Add((t16, 40));
                    if (stopAt != 2) { expected.Add((t17, 50)); if (stopAt != 3) expected.Add((t17, 70)); }
                }
            }
            var calls = trace.Where(x => x.StartsWith(own + "(out", StringComparison.Ordinal)
                || x.StartsWith(t16 + "(out", StringComparison.Ordinal) || x.StartsWith(t17 + "(out", StringComparison.Ordinal)).ToArray();
            bool applied = !stoppedOwn && stopAt == 0;
            if (calls.Length != expected.Count || !calls.Zip(expected).All(x => x.First.StartsWith(x.Second.Hook + "(out", StringComparison.Ordinal)
                    && x.First.Contains($"{probe}#{x.Second.Id}（", StringComparison.Ordinal))
                || count != expected.Count || !beforeNumeric || target.Defense != (applied ? 15 : 10)
                || target.MaxDefense != (applied ? 15 : 10) || target.BuffsBySource[(20, false)].Defense != 2
                || (!stoppedOwn && Convert.ToInt32(first.BlueprintVariables["_auditChainInput"]) != 2)
                || (!stoppedOwn && stopAt != 1 && Convert.ToInt32(second.BlueprintVariables["_auditChainInput"]) != 3)
                || (!stoppedOwn && stopAt != 1 && stopAt != 2 && Convert.ToInt32(afterFirst.BlueprintVariables["_auditChainInput"]) != 5)
                || state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionGainDefense") != (applied ? 1 : 0))
                return $"防御回调链错误 side={side}, suppressed={suppressed}, ownStop={ownStop}, stopAt={stopAt}";
        }
        return null;
    }

    private static string? DefenseBeforeChainSnapshots(CardDatabase db)
    {
        const string probe = "card_unit_arado_ar_196", own = "OnBeforeGainDefense", t16 = "OnBeforeOtherCardGainDefense", t17 = "OnBeforeOtherCardGainDefenseAfterAdd";
        using var programs = InstallDefenseChainProbes();
        var (engine, state) = EmptyBoard(db);
        var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
        CardInstance Make(int id, string trigger, int delta) {
            var card = state.CreateWithId(probe, Side.Left, id, CardLocation.Discard, id);
            card.Definition = new CardDefinition { Name = probe, Type = "fighter", UsedTriggers = new[] { trigger } };
            card.Keywords.Clear(); card.BlueprintVariables["_auditChainDelta"] = delta; card.BlueprintVariables["_auditChainStop"] = false; return card;
        }
        var first = Make(30, t16, 1); var second = Make(40, t16, 2);
        var afterFirst = Make(50, t17, 0); var afterLast = Make(70, t17, 0);
        var target = state.CreateWithId(probe, Side.Left, 60, CardLocation.BoardHqLeft, 1);
        target.Definition = new CardDefinition { Name = probe, Type = "fighter" }; target.Keywords.Clear();
        target.BlueprintVariables["_auditChainStop"] = false; target.Defense = target.MaxDefense = 10;
        for (int i = 0; i < 8; i++) state.CreateWithId("card_unit_51e_regiment", Side.Left, 100 + i, CardLocation.DeckLeft, i);
        int stage = 0; CardInstance? late16 = null, late17 = null;
        using var draw = InstallDrawReentryProbe(state, () => {
            stage++;
            if (stage == 1) Make(45, t16, 3); // Own callback precedes T16 query.
            if (stage == 2) {
                second.Definition = new CardDefinition { Name = probe }; second.Keywords.Add(Keyword.Suppressed);
                state.Move(second, CardLocation.NotAvailable, 0, notifyMoved: false);
                late16 = Make(35, t16, 10); Make(55, t17, 0); // T16 query frozen; T17 not queried yet.
            }
            if (stage == 5) {
                afterLast.Definition = new CardDefinition { Name = probe }; afterLast.Keywords.Add(Keyword.Suppressed);
                state.Move(afterLast, CardLocation.NotAvailable, 0, notifyMoved: false);
                late17 = Make(75, t17, 0);
            }
        });
        var trace = new List<string>(); engine.Api.TriggerTrace = trace;
        engine.Api.ChangeDefense(target, 2, source, instigatorId: 20);
        var calls = trace.Where(x => x.StartsWith(own + "(out", StringComparison.Ordinal)
            || x.StartsWith(t16 + "(out", StringComparison.Ordinal) || x.StartsWith(t17 + "(out", StringComparison.Ordinal)).ToArray();
        var expected = new[] { (own, 60), (t16, 30), (t16, 40), (t16, 45), (t17, 50), (t17, 55), (t17, 70) };
        if (calls.Length != expected.Length || !calls.Zip(expected).All(x => x.First.StartsWith(x.Second.Item1 + "(out", StringComparison.Ordinal)
                && x.First.Contains($"{probe}#{x.Second.Item2}（", StringComparison.Ordinal))
            || stage != 7 || target.Defense != 18 || target.BuffsBySource[(20, false)].Defense != 2
            || Convert.ToInt32(second.BlueprintVariables["_auditChainInput"]) != 3
            || Convert.ToInt32(afterLast.BlueprintVariables["_auditChainInput"]) != 8
            || late16 is null || late17 is null || late16.BlueprintVariables.ContainsKey("_auditChainInput")
            || late17.BlueprintVariables.ContainsKey("_auditChainInput"))
            return "各组须在其起点查询；自身/上一组新增可见，组内移除/抑制不重筛，组内新增不补入"
                + $" stage={stage}, def={target.Defense}, late16={late16?.BlueprintVariables.ContainsKey("_auditChainInput")}, late17={late17?.BlueprintVariables.ContainsKey("_auditChainInput")}; " + string.Join(" | ", calls);
        return null;
    }

    private static IDisposable InstallDefenseBeforeLedgerProbe(string hook)
    {
        const string name = "card_unit_arado_ar_196";
        var cleanup = InstallSelectionDrawProbe(name, hook);
        var locals = (IDictionary<string, IReadOnlyList<KismetStep>>)KismetLibrary.Default!.Find(name)!.Locals;
        var draw = locals[hook][0];
        locals[hook] = new[] {
            draw,
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "_auditRewriteDefense", Scope = "instance" }, null, -1, "newDefenseToAdd", null),
            new KismetStep(2, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "_auditStopDefense", Scope = "instance" }, null, -1, "stopAction", null),
            new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        return cleanup;
    }

    private static string? DefenseBuffBeforeGainTiming(CardDatabase db)
    {
        foreach (string hook in new[] { "OnBeforeOtherCardGainDefense", "OnBeforeOtherCardGainDefenseAfterAdd" })
        {
            using var hookProbe = InstallDefenseBeforeLedgerProbe(hook);
            foreach (var side in new[] { Side.Left, Side.Right })
            foreach (bool sourceExists in new[] { false, true })
            foreach (int previous in new[] { -2, 0, 3 })
            foreach (bool stop in new[] { false, true })
            foreach (int rewrite in new[] { -2, 0, 4 })
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
                var observer = state.CreateWithId("card_unit_arado_ar_196", Side.Left, 30, CardLocation.HandLeft, 0);
                observer.Definition = new CardDefinition { Name = observer.Name, Type = "fighter", UsedTriggers = new[] { hook } };
                observer.Keywords.Clear(); observer.BlueprintVariables["_auditRewriteDefense"] = rewrite;
                observer.BlueprintVariables["_auditStopDefense"] = stop;
                var target = state.CreateWithId("card_unit_arado_ar_196", side, 60, side.HqOf(), 1);
                target.Definition = new CardDefinition { Name = target.Name, Type = "fighter" };
                target.Keywords.Clear(); target.Keywords.Add(Keyword.Suppressed);
                target.Defense = target.MaxDefense = 10;
                int id = sourceExists ? 20 : 9999;
                target.BuffsBySource[(id, false)] = new CardBuff { SourceCardId = id, Defense = previous };
                if (sourceExists) source.CardsBuffedByThisCard.Add(60);
                state.CreateWithId("card_unit_51e_regiment", Side.Left, 100, CardLocation.DeckLeft, 0);
                int calls = 0; bool observed = true;
                using var draw = InstallDrawReentryProbe(state, () => {
                    calls++;
                    bool exists = target.BuffsBySource.TryGetValue((id, false), out var ledger);
                    observed &= target.Defense == 10 && target.MaxDefense == 10
                        && exists == (previous + 2 != 0) && (!exists || ledger!.Defense == previous + 2)
                        && source.CardsBuffedByThisCard.Contains(60) == (sourceExists && exists);
                });
                engine.Api.InvokeByName("ChangeDefense", target, new object?[] { target, id, 2, 1, false, null },
                    new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out _);
                int modified = hook == "OnBeforeOtherCardGainDefense" ? rewrite : 2;
                int applied = stop || modified <= 0 ? 0 : modified;
                var gains = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionGainDefense").ToArray();
                bool remains = target.BuffsBySource.TryGetValue((id, false), out var final);
                if (calls != 1 || !observed || target.Defense != 10 + applied || target.MaxDefense != 10 + applied
                    || remains != (previous + 2 != 0) || (remains && final!.Defense != previous + 2)
                    || gains.Length != (applied > 0 ? 1 : 0)
                    || (applied > 0 && gains[0].Values.Single(x => x.Name == "gained").Value != applied))
                    return $"增益前账本时序错误 hook={hook}, side={side}, source={sourceExists}, previous={previous}, stop={stop}, rewrite={rewrite}";
            }
        }
        return null;
    }

    private static string? DefenseBuffBeforeGainReentry(CardDatabase db)
    {
        const string hook = "OnBeforeOtherCardGainDefense";
        using var hookProbe = InstallDefenseBeforeLedgerProbe(hook);
        foreach (bool stop in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var observer = state.CreateWithId("card_unit_arado_ar_196", Side.Left, 30, CardLocation.HandLeft, 0);
            observer.Definition = new CardDefinition { Name = observer.Name, Type = "fighter", UsedTriggers = new[] { hook } };
            observer.Keywords.Clear(); observer.BlueprintVariables["_auditRewriteDefense"] = 4;
            observer.BlueprintVariables["_auditStopDefense"] = stop;
            var target = state.CreateWithId("card_unit_arado_ar_196", Side.Left, 60, CardLocation.BoardHqLeft, 1);
            target.Definition = new CardDefinition { Name = target.Name, Type = "fighter" };
            target.Keywords.Clear(); target.Keywords.Add(Keyword.Suppressed); target.Defense = target.MaxDefense = 10;
            state.CreateWithId("card_unit_51e_regiment", Side.Left, 100, CardLocation.DeckLeft, 0);
            bool sawOriginal = false; int calls = 0;
            using var draw = InstallDrawReentryProbe(state, () => {
                calls++; sawOriginal = target.BuffsBySource[(20, false)].Defense == 2;
                engine.Api.ChangeDefense(target, -1, source, instigatorId: 20);
            });
            engine.Api.ChangeDefense(target, 2, source, instigatorId: 20);
            var gains = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionGainDefense").ToArray();
            if (calls != 1 || !sawOriginal || target.BuffsBySource[(20, false)].Defense != 1
                || target.Defense != (stop ? 9 : 13) || target.MaxDefense != (stop ? 9 : 13)
                || gains.Length != (stop ? 1 : 2) || gains[0].Values.Single(x => x.Name == "gained").Value != -1
                || (!stop && gains[1].Values.Single(x => x.Name == "gained").Value != 4))
                return "嵌套减防须叠加在原始请求账本上，外层改量或中止后不得重复记账/回滚";
        }
        return null;
    }

    private static string? DefenseBuffZeroCleanup(CardDatabase db)
    {
        Action<CardBuff>[] payloads = {
            b => { }, b => b.Attack = 3, b => b.KreditCost = -1, b => b.OperationCost = -1,
            b => b.HeavyArmor = 1, b => b.Fury = 1, b => b.Blitz = 1, b => b.Smokescreen = 1,
            b => b.Guard = 1, b => b.Destruction = 1, b => b.Pinned = 1,
            b => b.CustomAbilityDetails.Add("audit-presence"), b => b.KreditCostSetsAbsoluteValue = true,
            b => b.OperationCostSetsAbsoluteValue = true, b => b.HasNonOrdinaryDefenseEntry = true,
            b => b.DefenseSetValue = 0,
        };
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool sourceExists in new[] { false, true })
        foreach (bool otherSlot in new[] { false, true })
        foreach (int reverseCase in new[] { 0, 1, 2 })
        foreach (int payload in Enumerable.Range(0, payloads.Length))
        {
            var (engine, state) = EmptyBoard(db);
            var self = state.CreateWithId("card_unit_51e_regiment", side, 20, side.HqOf(), 1);
            var target = state.CreateWithId("card_unit_arado_ar_196", side, 60, side.HqOf(), 2);
            target.Keywords.Clear(); target.Keywords.Add(Keyword.Suppressed);
            target.Defense = target.MaxDefense = 10;
            int id = sourceExists ? 20 : 9999;
            void Change(int amount) => engine.Api.InvokeByName("ChangeDefense", target,
                new object?[] { target, id, amount, 1, false, null },
                new EffectContext { Engine = engine, State = state, Self = self, Controller = side }, out _);
            Change(2);
            var buff = target.BuffsBySource[(id, false)]; payloads[payload](buff); buff.Duration = 5;
            if (otherSlot) target.BuffsBySource[(id, true)] = new CardBuff { SourceCardId = id, Temporary = true, Defense = 1 };
            var unrelated = new CardBuff { SourceCardId = 99, Defense = 7 };
            target.BuffsBySource[(99, false)] = unrelated;
            self.CardsBuffedByThisCard.Clear();
            var before = reverseCase switch { 0 => Array.Empty<int>(), 1 => new[] { 888 }, _ => new[] { 60, 60, 888 } };
            self.CardsBuffedByThisCard.AddRange(before);
            int actionsBefore = state.ActionLog.SelectMany(x => x.SubActions).Count();
            Change(-2);
            bool retainSlot = payload != 0, retainSource = retainSlot || otherSlot;
            var expectedReverse = !sourceExists ? before
                : retainSource ? (before.Contains(60) ? before : before.Append(60).ToArray())
                : before.Where(x => x != 60).ToArray();
            if (target.Defense != 10 || target.MaxDefense != 10
                || target.BuffsBySource.ContainsKey((id, false)) != retainSlot
                || (retainSlot && (buff.Defense != 0 || !ReferenceEquals(target.BuffsBySource[(id, false)], buff)))
                || target.BuffsBySource.ContainsKey((id, true)) != otherSlot
                || !ReferenceEquals(target.BuffsBySource[(99, false)], unrelated)
                || !self.CardsBuffedByThisCard.SequenceEqual(expectedReverse)
                || state.ActionLog.SelectMany(x => x.SubActions).Count() != actionsBefore + 1)
                return $"防御buff归零清理错误 side={side}, source={sourceExists}, otherSlot={otherSlot}, reverse={reverseCase}, payload={payload}";
        }
        return null;
    }

    private static string? DefenseBuffMixedPresence(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", side, 20, side.HqOf(), 1);
            var target = state.CreateWithId("card_unit_arado_ar_196", side, 60, side.HqOf(), 2);
            target.Keywords.Clear(); target.Keywords.Add(Keyword.Suppressed); target.Defense = target.MaxDefense = 3;
            engine.Api.SetDefenseValue(target, 5, source);
            engine.Api.ChangeDefense(target, -2, source);
            if (!target.BuffsBySource.TryGetValue((20, false), out var buff) || buff.Defense != -2
                || buff.DefenseSetValue != 5 || buff.HasNonOrdinaryDefenseEntry || buff.IsEmpty || buff.Clone().DefenseSetValue != 5
                || buff.Clone().IsEmpty || !source.CardsBuffedByThisCard.Contains(60) || target.Defense != 3)
                return "设防条目须与普通减防分开，克隆保留原始设值";
            engine.Api.ChangeDefense(target, 2, source);
            if (!target.BuffsBySource.TryGetValue((20, false), out buff) || buff.Defense != 0 || buff.DefenseSetValue != 5
                || buff.IsEmpty || !source.CardsBuffedByThisCard.Contains(60) || target.Defense != 5)
                return "普通防御量归零不能抹掉独立设值项或来源关系";
        }
        return null;
    }

    private static string? DefenseSourceIdentityAndEntry(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool selfPresent in new[] { false, true })
        foreach (int instigator in new[] { -7, 0, 20, 40, 9999 })
        foreach (int oldDefense in new[] { -3, 0, 3 })
        foreach (var operation in new[] { (Type: 1, Value: 2), (Type: 1, Value: -5), (Type: 2, Value: 4), (Type: 2, Value: 0) })
        {
            var (engine, state) = EmptyBoard(db);
            var self = state.CreateWithId("card_unit_51e_regiment", side, 20, side.HqOf(), 1);
            var realSource = state.CreateWithId("card_unit_51e_regiment", side.Opposite(), 40, CardLocation.Discard, 0);
            var target = state.CreateWithId("card_unit_arado_ar_196", side, 60, side.HqOf(), 2);
            target.Definition = new CardDefinition { Name = target.Name, Type = "fighter" };
            target.Keywords.Clear(); target.Keywords.Add(Keyword.Suppressed);
            target.Defense = oldDefense; target.MaxDefense = 8;
            engine.Api.InvokeByName("ChangeDefense", target,
                new object?[] { target, instigator, operation.Value, operation.Type, false, null },
                new EffectContext { Engine = engine, State = state, Self = selfPresent ? self : null, Controller = side }, out bool handled);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            bool allowed = instigator > 0 && oldDefense > 0;
            if (!handled) return "显式防御来源派发未处理";
            if (!allowed)
            {
                if (target.Defense != oldDefense || target.MaxDefense != 8 || target.Location == CardLocation.Discard
                    || target.BuffsBySource.Count != 0 || actions.Length != 0)
                    return $"非法入口不应变化 self={selfPresent}, source={instigator}, defense={oldDefense}";
                continue;
            }
            int expected = operation.Type == 2 ? operation.Value : oldDefense + operation.Value;
            bool dies = expected <= 0;
            var gains = actions.Where(x => x.Name == "ZActionGainDefense").ToArray();
            var destroys = actions.Where(x => x.Name == "ZActionDestroyUnit").ToArray();
            int destroyer = instigator is 20 or 40 ? instigator : 0;
            if (target.Defense != expected || (target.Location == CardLocation.Discard) != dies
                || gains.Length != 1 || gains[0].Values.Single(x => x.Name == "instigatorID").Value != instigator
                || destroys.Length != (dies ? 1 : 0)
                || (dies && destroys[0].Values.Single(x => x.Name == "destroyerCardID").Value != destroyer))
                return $"防御变化或致死来源错误 self={selfPresent}, source={instigator}, type={operation.Type}, value={operation.Value}";
            // The simple ordinary increment must use the raw source key even when
            // lookup is absent. SetValue ledger cleanup is audited separately.
            if (!dies && operation.Type == 1 && (target.BuffsBySource.Count != 1
                || !target.BuffsBySource.TryGetValue((instigator, false), out var buff) || buff.Defense != operation.Value))
                return "普通增量buff必须记在显式来源ID上，不能回退到执行卡或目标";
        }
        return null;
    }

    private static IDisposable InstallDefenseSetEventProbes()
    {
        const string probe = "card_unit_arado_ar_196", trigger = "OnAfterOtherCardDefenseIsSet";
        var own = InstallSelectionDrawProbe(probe, "OnAfterDefenseIsSet");
        try
        {
            var other = InstallSelectionDrawProbe(probe, trigger);
            var locals = (IDictionary<string, IReadOnlyList<KismetStep>>)KismetLibrary.Default!.Find(probe)!.Locals;
            var marker = new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "cardDefenseSet", Scope = "local" }, null, -1, "_auditDefenseSetSubject", null)
                { DestinationScope = "instance" };
            locals[trigger] = new[] { marker }.Concat(locals[trigger].Select(x => x with { Index = x.Index + 1 })).ToArray();
            return new AuditProbeCleanup(() => { other.Dispose(); own.Dispose(); });
        }
        catch { own.Dispose(); throw; }
    }

    private static string? DefenseSetOwnAndObserverOrder(CardDatabase db)
    {
        const string probe = "card_unit_arado_ar_196", own = "OnAfterDefenseIsSet", other = "OnAfterOtherCardDefenseIsSet";
        using var programs = InstallDefenseSetEventProbes();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool lethal in new[] { false, true })
        foreach (bool suppressed in new[] { false, true })
        foreach (var where in new[] { side.HandOf(), CardLocation.Discard, CardLocation.NotAvailable })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", side, 20, side.HqOf(), 1);
            var observer = state.CreateWithId(probe, side.Opposite(), 30, where, 0);
            var target = state.CreateWithId(probe, side, 60, side.HqOf(), 2);
            foreach (var card in new[] { observer, target })
            {
                card.Keywords.Clear();
                card.Definition = new CardDefinition { Name = probe, Type = "fighter", UsedTriggers = new[] { other } };
            }
            if (suppressed) target.Keywords.Add(Keyword.Suppressed);
            target.Defense = target.MaxDefense = 3;
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            engine.Api.SetDefenseValue(target, lethal ? 0 : 4, source);
            var calls = trace.Where(x => x.StartsWith(own + " → ", StringComparison.Ordinal)
                || x.StartsWith(other + " → ", StringComparison.Ordinal)).ToArray();
            if (calls.Length != 2 || !calls[0].StartsWith($"{own} → {probe}#60", StringComparison.Ordinal)
                || !calls[1].StartsWith($"{other} → {probe}#30", StringComparison.Ordinal)
                || !ReferenceEquals(observer.BlueprintVariables.GetValueOrDefault("_auditDefenseSetSubject"), target)
                || (target.Location == CardLocation.Discard) != lethal)
                return $"设值事件自身/旁观顺序或致死主体丢失 side={side}, lethal={lethal}, suppressed={suppressed}, observer={where}";
        }
        return null;
    }

    private static string? DefenseSetObserverSnapshot(CardDatabase db)
    {
        const string probe = "card_unit_arado_ar_196", own = "OnAfterDefenseIsSet", other = "OnAfterOtherCardDefenseIsSet";
        using var programs = InstallDefenseSetEventProbes();
        foreach (bool lethal in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            CardDefinition Definition(bool registered) => new() { Name = probe, Type = "fighter",
                UsedTriggers = registered ? new[] { other } : Array.Empty<string>() };
            var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.BoardHqLeft, 1);
            var first = state.CreateWithId(probe, Side.Left, 30, CardLocation.Discard, 0);
            var target = state.CreateWithId(probe, Side.Left, 60, CardLocation.BoardHqLeft, 2);
            var later = state.CreateWithId(probe, Side.Left, 70, CardLocation.HandLeft, 0);
            foreach (var card in new[] { first, target, later }) { card.Keywords.Clear(); card.Definition = Definition(card != first); }
            target.Defense = target.MaxDefense = 3;
            for (int i = 0; i < 4; i++) state.CreateWithId("card_unit_51e_regiment", Side.Left, 100 + i, CardLocation.DeckLeft, i);
            int stage = 0; CardInstance? beforeQuery = null, afterQuery = null;
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            using var draw = InstallDrawReentryProbe(state, () => {
                stage++;
                if (stage == 1)
                {
                    first.Definition = Definition(true);
                    beforeQuery = state.CreateWithId(probe, Side.Left, 65, CardLocation.Discard, 1);
                    beforeQuery.Keywords.Clear(); beforeQuery.Definition = Definition(true);
                }
                else if (stage == 2)
                {
                    later.Keywords.Add(Keyword.Suppressed); later.Definition = Definition(false);
                    state.Move(later, CardLocation.NotAvailable, 0, notifyMoved: false);
                    afterQuery = state.CreateWithId(probe, Side.Left, 90, CardLocation.Discard, 2);
                    afterQuery.Keywords.Clear(); afterQuery.Definition = Definition(true);
                }
            });
            engine.Api.SetDefenseValue(target, lethal ? 0 : 4, source);
            var calls = trace.Where(x => x.StartsWith(own + " → ", StringComparison.Ordinal)
                || x.StartsWith(other + " → ", StringComparison.Ordinal)).ToArray();
            var expected = new[] { $"{own} → {probe}#60", $"{other} → {probe}#30", $"{other} → {probe}#65", $"{other} → {probe}#70" };
            if (calls.Length != expected.Length || !calls.Zip(expected).All(x => x.First.StartsWith(x.Second, StringComparison.Ordinal))
                || stage != 4 || beforeQuery is null || afterQuery is null
                || !ReferenceEquals(later.BlueprintVariables.GetValueOrDefault("_auditDefenseSetSubject"), target)
                || afterQuery.BlueprintVariables.ContainsKey("_auditDefenseSetSubject"))
                return "设值事件须在自身回调后取快照：查询前新注册/新建接收，查询后变化不重筛也不补新卡";
        }
        return null;
    }

    private static string? DefenseSetAbsoluteValues(CardDatabase db)
    {
        using var setProbe = InstallSelectionDrawProbe("card_unit_arado_ar_196", "OnAfterDefenseIsSet");
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int maximum in new[] { 3, 8 })
        foreach (int requested in new[] { -4, 0, 3, 4, 100, 115 })
        foreach (bool dispatch in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", side, 20, side.HqOf(), 1);
            var target = state.CreateWithId("card_unit_arado_ar_196", side, 30, side.HqOf(), 2);
            source.Keywords.Clear(); target.Keywords.Clear(); source.Keywords.Add(Keyword.Suppressed);
            target.Defense = 3; target.MaxDefense = maximum;
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            if (dispatch)
            {
                engine.Api.InvokeByName("ChangeDefense", target,
                    new object?[] { target, source.CardId, requested, 2, false, null },
                    new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out bool handled);
                if (!handled) return "ChangeDefense设值派发未处理";
            }
            else engine.Api.SetDefenseValue(target, requested, source);
            int value = Math.Clamp(requested, 0, 99);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            var gain = actions.Where(x => x.Name == "ZActionGainDefense").ToArray();
            var expected = new[] { ActionValue2.Int("cardID", 30), ActionValue2.Int("gained", requested),
                ActionValue2.Int("newDefenseValue", value), ActionValue2.Int("instigatorID", 20),
                ActionValue2.Str("changeType", "SetValue") };
            if (target.Defense != value || target.MaxDefense != value
                || gain.Length != 1 || !gain[0].Values.SequenceEqual(expected)
                || (target.Location == CardLocation.Discard) != (value == 0)
                || actions.Count(x => x.Name == "ZActionDestroyUnit") != (value == 0 ? 1 : 0)
                || trace.Any(x => x.Contains("OnAfterGainDefense", StringComparison.Ordinal)))
                return $"设值错误 side={side}, max={maximum}, requested={requested}, dispatch={dispatch}";
            if (value == 0 && Array.FindIndex(actions, x => x.Name == "ZActionGainDefense")
                >= Array.FindIndex(actions, x => x.Name == "ZActionDestroyUnit"))
                return "设值致死应先通知设值，后进行摧毁（与普通减防分支不同）";
            if (value > 0 && !trace.Any(x => x.Contains("OnAfterDefenseIsSet", StringComparison.Ordinal)))
                return "存活的零差值设值也应触发设值事件";
        }
        return null;
    }

    private static string? DefenseNotificationFields(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int delta in new[] { -1, 2 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", side, 20, side.HqOf(), 1);
            var target = state.CreateWithId("card_unit_arado_ar_196", side, 30, side.HqOf(), 2);
            source.Keywords.Clear(); target.Keywords.Clear(); source.Keywords.Add(Keyword.Suppressed);
            target.Keywords.Add(Keyword.Suppressed); target.Defense = target.MaxDefense = 3;
            engine.Api.InvokeByName("ChangeDefense", target,
                new object?[] { target, source.CardId, delta, 1, false, null },
                new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out bool handled);
            var gain = state.ActionLog.SelectMany(x => x.SubActions).Single(x => x.Name == "ZActionGainDefense");
            var expected = new[] { ActionValue2.Int("cardID", 30), ActionValue2.Int("gained", delta),
                ActionValue2.Int("newDefenseValue", 3 + delta), ActionValue2.Int("instigatorID", 20),
                ActionValue2.Str("changeType", "permBuff") };
            if (!handled || !gain.Values.SequenceEqual(expected)) return "普通增量通知须保留目标、来源、负增量和permBuff文本";
        }
        return null;
    }

    // Synthetic fixtures test the shared additive branch, not a real card effect.
    private static string? DefenseDecreaseDeathOrder(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool sourcePresent in new[] { false, true })
        foreach (int maximum in new[] { 3, 8 })
        foreach (int delta in new[] { -1, -3, -5 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", side, 20, side.HqOf(), 1);
            var victim = state.CreateWithId("card_unit_arado_ar_196", side, 30, side.HqOf(), 2);
            source.Keywords.Clear(); victim.Keywords.Clear();
            source.Keywords.Add(Keyword.Suppressed);
            victim.Keywords.Add(Keyword.Suppressed);
            victim.Defense = 3; victim.MaxDefense = maximum;
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            engine.Api.ChangeDefense(victim, delta, sourcePresent ? source : null);
            bool dies = 3 + delta <= 0;
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            int destroy = Array.FindIndex(actions, x => x.Name == "ZActionDestroyUnit");
            int gain = Array.FindIndex(actions, x => x.Name == "ZActionGainDefense");
            if (victim.Defense != 3 + delta || victim.MaxDefense != (dies ? maximum : maximum + delta)
                || (victim.Location == CardLocation.Discard) != dies
                || actions.Count(x => x.Name == "ZActionDestroyUnit") != (dies ? 1 : 0)
                || actions.Count(x => x.Name == "ZActionGainDefense") != 1
                || (dies && (destroy < 0 || gain <= destroy))
                || state.DestroyedCardIdsAll.Count != (dies ? 1 : 0)
                || trace.Any(x => x.Contains("OnAfterGainDefense", StringComparison.Ordinal)))
                return $"减防分支不一致 side={side}, source={sourcePresent}, max={maximum}, delta={delta}";
        }
        return null;
    }

    private static string? DefenseDecreaseCallbackTiming(CardDatabase db)
    {
        const string name = "card_unit_arado_ar_196";
        using var beforeProbe = InstallSelectionDrawProbe(name, "OnBeforeDestroyed");
        var (engine, state) = EmptyBoard(db);
        var source = state.CreateWithId("card_unit_51e_regiment", Side.Left, 20, CardLocation.BoardHqLeft, 1);
        var victim = state.CreateWithId(name, Side.Left, 30, CardLocation.BoardHqLeft, 2);
        victim.Keywords.Clear(); victim.Defense = 3; victim.MaxDefense = 8;
        state.CreateWithId("card_unit_51e_regiment", Side.Left, 50, CardLocation.DeckLeft, 0);
        bool called = false, earlyGain = false; int observedMax = -1;
        using var drawProbe = InstallDrawReentryProbe(state, () => {
            called = true; observedMax = victim.MaxDefense;
            earlyGain = state.ActionLog.SelectMany(x => x.SubActions).Any(x => x.Name == "ZActionGainDefense");
            victim.Defense = 9;
        });
        engine.Api.ChangeDefense(victim, -5, source);
        var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
        var gain = actions.Single(x => x.Name == "ZActionGainDefense");
        if (!called || earlyGain || observedMax != 8 || victim.Location != CardLocation.Discard
            || gain.Values.Single(x => x.Name == "newDefenseValue").Value != 9
            || actions.Count(x => x.Name == "ZActionDestroyUnit") != 1
            || !state.DestroyedCardIdsAll.SequenceEqual(new[] { 30 }))
            return "减防致死须先完成摧毁回调/移除，通知再读取最新防御；回调恢复不取消已开始摧毁";
        return null;
    }

    private static string? ChangeDefenseBeforeOtherCardGainDefense(CardDatabase db)
    {
        const string sourceName = "card_unit_t_34";
        const string bonusName = "card_unit_111th_indian_brigade";
        const string vetoName = "card_unit_kagoshima_regiment";
        foreach (string name in new[] { sourceName, bonusName, vetoName })
        {
            if (db.Find(name) is null)
            {
                return $"卡库里缺 {name}";
            }
        }

        // 111th Indian Brigade changes the running amount by +1 for its own HQ.
        {
            var (engine, state) = EmptyBoard(db);
            var hq = state.Hq(Side.Left);
            var source = state.CreateWithId(sourceName, Side.Left, 71, CardLocation.BoardFrontline, 0);
            state.CreateWithId(bonusName, Side.Left, 72, CardLocation.BoardFrontline, 1);
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            int before = hq.Defense;

            engine.Api.ChangeDefense(hq, 2, source);

            if (hq.Defense != before + 3)
            {
                return $"111th Indian Brigade 应把 HQ 的 +2 改为 +3，实际变化 {hq.Defense - before}"
                     + $"\n       派发记录：{string.Join(" | ", trace)}";
            }
        }

        // Kagoshima Regiment sets the amount to zero and stops the change for HQs.
        {
            var (engine, state) = EmptyBoard(db);
            var hq = state.Hq(Side.Left);
            var source = state.CreateWithId(sourceName, Side.Left, 74, CardLocation.BoardFrontline, 0);
            state.CreateWithId(vetoName, Side.Right, 75, CardLocation.BoardFrontline, 0);
            int before = hq.Defense;

            engine.Api.ChangeDefense(hq, 2, source);

            if (hq.Defense != before)
            {
                return $"Kagoshima Regiment 应中止 HQ 防御增益，实际变化 {hq.Defense - before}";
            }
        }

        return null;
    }

