    /// <summary>
    /// `card_event_committed_crew` —— "Until end of turn, Spitfires cost 0 to deploy
    /// and get +3+3 when deployed."
    ///
    /// 断言两段（都是逐行读 `ref/kards-sim/.../card_event_committed_crew.g.cs` 得到的行为）：
    /// 1. 打出这张指令（`OnPlayedFromHand` → 遍历所有卡 `ApplyTheBuff()`）之后，
    ///    手牌里的 Spitfire 费用变 0（changeType=1，**允许到 0**，不受 1 费下限约束）
    /// 2. Spitfire 部署时它的 `OnOtherCardPlayedFromHand` 给它 +3+3
    ///
    /// ⚠️ **不做**"回合结束后 +3+3 消失"这条断言 —— 因为卡自己的实现里
    ///    `ChangeAttack(卡, cardID, 3, 1, false, out)` 的 changeType 是 **1（普通加法）**，
    ///    不是 `AddAttackUntilEndOfTurn` 那条"到回合末失效"的路径。
    ///    也就是说"这份实现里 +3+3 是永久的"；要断言它消失，得先实现客户端的
    ///    **临时 buff 回合末重置**机制（`OnAfterOtherCardOperactionCostBuffsReset`
    ///    那一族），目前没有实现 —— 见 klink bot/docs/内核补全队列.md 的已知缺口。
    ///    宁可不写这条断言，也不要写一条"猜"的。
    /// </summary>
    private static string? CommittedCrewAura(CardDatabase db)
    {
        const string crew = "card_event_committed_crew";
        const string spitfire = "card_unit_spitfire";
        if (db.Find(crew) is null || db.Find(spitfire) is null)
        {
            return $"卡库里缺 {crew} 或 {spitfire}";
        }

        var (engine, state) = EmptyBoard(db);
        state.SetKredits(Side.Left, 12);
        state.SetMaxKredits(Side.Left, 12);
        state.ActiveSide = Side.Left;

        var plane = state.CreateWithId(spitfire, Side.Left, 2, CardLocation.HandLeft, 0);
        int planeBaseCost = plane.KreditCost;
        int planeBaseAttack = plane.Attack;
        int planeBaseDefense = plane.Defense;
        if (planeBaseCost <= 0)
        {
            return $"前置不成立：{spitfire} 的卡面费用是 {planeBaseCost}，测不出「归零」";
        }

        // 1) 打出敢死队
        var crewCard = state.CreateWithId(crew, Side.Left, 3, CardLocation.HandLeft, 1);
        if (!engine.PlayCard(crewCard))
        {
            return "敢死队打不出来";
        }

        if (plane.KreditCost != 0)
        {
            return $"Spitfire 费用应为 0，实际 {plane.KreditCost}"
                 + Dump(state, ("未实现", Unimpl(state)));
        }

        // 2) 部署 Spitfire —— 0 费应该打得出来，并且吃到 +3+3
        if (!engine.PlayCard(plane))
        {
            return $"0 费的 Spitfire 应该能打出（费用={plane.KreditCost}，"
                 + $"kredits={state.Kredits(Side.Left)}）";
        }

        if (plane.Attack != planeBaseAttack + 3 || plane.Defense != planeBaseDefense + 3)
        {
            return $"Spitfire 部署后应为 {planeBaseAttack + 3}/{planeBaseDefense + 3}，"
                 + $"实际 {plane.Attack}/{plane.Defense}"
                 + Dump(state, ("未实现", Unimpl(state)));
        }

        return null;
    }

    /// <summary>
    /// 当前客户端已移除自身 OnAfterAttack/OnMoveToFrontline，只保留其他卡攻击/移动。
    /// 此处通过真实攻击验证排除自身，同时保留友方德国与异阵营的对照。
    /// </summary>
    private static string? PanzergrenadierFactionGate(CardDatabase db)
    {
        const string gren = "card_unit_3_panzergrenadier";
        const string german = "card_unit_arado_ar_196";     // Germany
        const string american = "card_unit_m2a4";           // USA
        // ⚠️ 肉盾 `card_unit_85_pioneer_company` **自带 `Smokescreen`**（CardInnateTable）。
        //    P1 把烟幕的「不能被攻击」（CanAttack si=3637/3793）接上之后，
        //    这条用例的第一枪就被新规则正确地拒了 —— 不是回归，是新规则生效。
        //    这里显式摘掉烟幕，让这条用例只管它自己要守的阵营判定；
        //    烟幕本身另有专门用例（`SmokescreenRules`）。
        const string victim = "card_unit_85_pioneer_company";
        if (db.Find(gren) is null || db.Find(german) is null || db.Find(american) is null)
        {
            return $"卡库里缺 {gren} / {german} / {american}";
        }

        if (db.Find(german)!.FactionId != 1 || db.Find(american)!.FactionId != 5)
        {
            return $"阵营枚举对不上：{german}.FactionId={db.Find(german)!.FactionId}（应 1=Germany），"
                 + $"{american}.FactionId={db.Find(american)!.FactionId}（应 5=USA）";
        }

        var (engine, state) = EmptyBoard(db);
        state.SetKredits(Side.Left, 12);
        state.SetMaxKredits(Side.Left, 12);
        state.ActiveSide = Side.Left;

        var grenadier = state.CreateWithId(gren, Side.Left, 2, CardLocation.BoardFrontline, 0);
        var germanUnit = state.CreateWithId(german, Side.Left, 3, CardLocation.BoardFrontline, 1);
        var usaUnit = state.CreateWithId(american, Side.Left, 4, CardLocation.BoardFrontline, 2);
        int baseAttack = grenadier.Attack;
        int baseDefense = grenadier.Defense;

        // 打三枪，每次换一个攻击者（都是自己这边的单位，打对面那个肉盾）。
        // 每一步都要把「本回合已攻击」清掉，否则第二枪起会被拒。
        int expected = 0;
        foreach (var attacker in new[] { grenadier, germanUnit, usaUnit })
        {
            attacker.HasAttackedThisTurn = false;
            state.SetKredits(Side.Left, 12);
            var foe = state.Create($"{victim}", Side.Right, CardLocation.BoardFrontline,
                                   state.NextLocationNumber(Side.Right, CardLocation.BoardFrontline));
            foe.Defense = 99;
            foe.Attack = 0; // 隔离成长规则，不让反击伤害污染防御增量断言。
            engine.Api.RemoveKeyword(foe, Keyword.Smokescreen);   // 见上面关于烟幕的注释

            // 当前版本只响应其他友方德国单位，自身行动不再提供加成。
            bool counts = !ReferenceEquals(attacker, grenadier)
                          && attacker.Definition.FactionId == 1;
            int before = grenadier.Attack;
            if (!engine.Attack(attacker, foe))
            {
                return $"{attacker.Name} 打不出（kredits={state.Kredits(Side.Left)}，"
                     + $"行动费={attacker.OperationCost}）";
            }

            expected += counts ? 1 : 0;
            if (grenadier.Attack != baseAttack + expected)
            {
                return $"{attacker.Name}（faction={attacker.Definition.FactionId}）出手后，"
                     + $"掷弹兵攻击力应为 {baseAttack + expected}，实际 {grenadier.Attack}"
                     + $"（本次{(counts ? "应" : "不应")}计入）"
                     + Dump(state, ("未实现", Unimpl(state)));
            }

            if (grenadier.Attack - before != (counts ? 1 : 0))
            {
                return $"{attacker.Name} 这一次让掷弹兵涨了 {grenadier.Attack - before}，"
                     + $"应为 {(counts ? 1 : 0)}";
            }
        }

        if (grenadier.Defense != baseDefense + expected)
        {
            return $"攻防涨幅不一致：攻 +{grenadier.Attack - baseAttack}，"
                 + $"防 +{grenadier.Defense - baseDefense}（应都是 +{expected}）";
        }

        return null;
    }

    private static string? PanzergrenadierMoveGate(CardDatabase db)
    {
        const string name = "card_unit_3_panzergrenadier";
        foreach (bool effectMove in new[] { false, true })
        foreach (string scenario in new[] { "self", "friendlyGerman", "friendlyAmerican",
                                           "enemyGerman", "suppressed", "offBoard" })
        {
            var (engine, state) = EmptyBoard(db);
            var watcher = state.CreateWithId(name, Side.Left, 2,
                scenario == "offBoard" ? CardLocation.HandLeft : CardLocation.BoardHqLeft, 0);
            Side owner = scenario == "enemyGerman" ? Side.Right : Side.Left;
            var actor = scenario == "self" ? watcher : state.CreateWithId(
                scenario == "friendlyAmerican" ? "card_unit_m2a4" : "card_unit_arado_ar_196",
                owner, 3, owner == Side.Left ? CardLocation.BoardHqLeft : CardLocation.BoardHqRight, 1);
            if (scenario == "suppressed") watcher.Keywords.Add(Keyword.Suppressed);
            actor.EnteredPlayOnTurn = state.Turn - 1;
            state.ActiveSide = owner;
            state.SetMaxKredits(owner, 20);
            state.SetKredits(owner, 20);
            int attack = watcher.Attack, defense = watcher.Defense;
            bool moved = effectMove
                ? engine.MoveUnitFromSupportToFrontLine(actor, actor.CardId, out string reason)
                : engine.MoveUnit(actor, 0, out reason);
            if (!moved) return $"{scenario}/effect={effectMove} 移动失败：{reason}";
            int gain = scenario == "friendlyGerman" ? 1 : 0;
            if (watcher.Attack != attack + gain || watcher.Defense != defense + gain)
            {
                return $"{scenario}/effect={effectMove} 成长应为 +{gain}+{gain}，"
                     + $"实际 +{watcher.Attack - attack}+{watcher.Defense - defense}"
                     + Dump(state, ("未实现", Unimpl(state)));
            }
        }
        return null;
    }

    /// <summary>
    /// 「攻击一个已经进弃牌堆的目标」必须被拒。
    ///
    /// `Attack` 原先对防御者一个字都不校验，完全靠调用方给对目标。
    /// 这条断言把它变成内核自己的责任 —— 否则一个过期引用就能凭空多打一次
    /// （扣行动费、加攻防 buff、触发 OnAfterAttack 全都会发生）。
    /// </summary>
    private static string? AttackRejectsDeadTarget(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        state.SetKredits(Side.Left, 12);
        state.SetMaxKredits(Side.Left, 12);
        state.ActiveSide = Side.Left;

        var attacker = state.CreateWithId("card_unit_arado_ar_196", Side.Left, 2, CardLocation.BoardFrontline, 0);
        var victim = state.CreateWithId("card_unit_85_pioneer_company", Side.Right, 42, CardLocation.BoardFrontline, 0);

        // 直接把它送进弃牌堆（模拟"决策与结算之间夹了别的效果"）
        state.Move(victim, CardLocation.Discard);
        int hqBefore = state.HqDefense(Side.Right);
        int kreditsBefore = state.Kredits(Side.Left);

        if (engine.Attack(attacker, victim))
        {
            return "攻击一个已在弃牌堆的目标竟然成功了";
        }

        if (state.Kredits(Side.Left) != kreditsBefore)
        {
            return $"被拒的攻击不该扣行动费：{kreditsBefore} → {state.Kredits(Side.Left)}";
        }

        if (state.HqDefense(Side.Right) != hqBefore)
        {
            return "被拒的攻击不该改 HQ";
        }

        return null;
    }

    /// <summary>
    /// T31 没有 entrypoint，20 张卡的实现都在 locals。Merchant Navy 是最小的
    /// 可观测探针：收到敌方单位攻击后返回 <c>AttackedAndStopped=true</c>，
    /// 触发 gotcha 并把攻击者撤回，攻击伤害本身不应结算。
    /// </summary>
    private static string? OtherCardAttacksStopsAttack(CardDatabase db)
    {
        const string attackerName = "card_unit_arado_ar_196";
        const string defenderName = "card_unit_85_pioneer_company";
        const string merchantName = "card_event_merchant_navy";
        foreach (var name in new[] { attackerName, defenderName, merchantName })
        {
            if (db.Find(name) is null)
            {
                return $"卡库里缺 {name}";
            }
        }

        var (engine, state) = EmptyBoard(db);
        state.ActiveSide = Side.Right;
        state.SetKredits(Side.Right, 12);
        state.SetMaxKredits(Side.Right, 12);

        var attacker = state.CreateWithId(attackerName, Side.Right, 200, CardLocation.BoardFrontline, 0);
        var defender = state.CreateWithId(defenderName, Side.Left, 201, CardLocation.BoardFrontline, 0);
        var merchant = state.CreateWithId(merchantName, Side.Left, 202, CardLocation.HandLeft, 1);
        merchant.GotchaActivated = 1;
        attacker.EnteredPlayOnTurn = -1;
        defender.EnteredPlayOnTurn = -1;
        merchant.EnteredPlayOnTurn = -1;
        engine.Api.RemoveKeyword(defender, Keyword.Smokescreen);

        int defenderBefore = defender.Defense;
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        if (!engine.Attack(attacker, defender, out string reason))
        {
            return $"带 Merchant Navy 的攻击没有进入攻击结算：{reason}";
        }

        if (!trace.Any(x => x.StartsWith("OnOtherCardAttacks", StringComparison.Ordinal)
                         && x.Contains(merchantName, StringComparison.Ordinal)))
        {
            return "T31 locals 没有派发到 Merchant Navy"
                 + $"\n       实际派发记录：{string.Join(" | ", trace)}";
        }

        if (defender.Defense != defenderBefore)
        {
            return $"Merchant Navy 已中止攻击，但目标仍受到伤害：{defenderBefore} → {defender.Defense}";
        }

        if (attacker.Location != CardLocation.BoardHqRight)
        {
            return $"Merchant Navy 已中止攻击，但攻击者没有撤回到支援线：位置={attacker.Location}";
        }

        if (merchant.Location != CardLocation.Discard)
        {
            return $"触发后的 Merchant Navy 应进入弃牌堆，实际位置={merchant.Location}";
        }

        return null;
    }

    /// <summary>
    /// `ExecuteStoppedAttack` 必须在 T31 中止攻击后仍执行攻击者自己的
    /// `OnAttackStopped`。Meteor 的卡面清理挂在这个事件上；若漏派，
    /// 被 Merchant Navy 中止的攻击会错误地让 Meteor 留在场上。
    /// </summary>
    private static string? AttackStoppedTriggersSelfEvent(CardDatabase db)
    {
        const string attackerName = "card_unit_meteor";
        const string defenderName = "card_unit_85_pioneer_company";
        const string merchantName = "card_event_merchant_navy";
        foreach (var name in new[] { attackerName, defenderName, merchantName })
        {
            if (db.Find(name) is null)
            {
                return $"卡库里缺 {name}";
            }
        }

        var (engine, state) = EmptyBoard(db);
        state.ActiveSide = Side.Right;
        state.SetKredits(Side.Right, 12);
        state.SetMaxKredits(Side.Right, 12);

        var attacker = state.CreateWithId(attackerName, Side.Right, 200,
            CardLocation.BoardFrontline, 0);
        var defender = state.CreateWithId(defenderName, Side.Left, 201,
            CardLocation.BoardFrontline, 0);
        var merchant = state.CreateWithId(merchantName, Side.Left, 202,
            CardLocation.HandLeft, 1);
        merchant.GotchaActivated = 1;
        attacker.EnteredPlayOnTurn = state.Turn - 1;
        defender.EnteredPlayOnTurn = state.Turn - 1;
        merchant.EnteredPlayOnTurn = state.Turn - 1;
        engine.Api.RemoveKeyword(defender, Keyword.Smokescreen);

        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        if (!engine.Attack(attacker, defender, out string reason))
        {
            return $"Merchant Navy 中止 Meteor 攻击失败：{reason}";
        }

        if (!trace.Any(x => x.StartsWith($"OnAttackStopped → {attacker.Name}#{attacker.CardId}",
                                           StringComparison.Ordinal)))
        {
            return "攻击被中止后没有派发攻击者 OnAttackStopped"
                   + $"\n       实际派发记录：{string.Join(" | ", trace)}";
        }

        if (!attacker.HasEverAttacked) return "中止但消耗额度的攻击没有记录曾攻击标记";

        if (attacker.Location.IsBoard())
        {
            return $"Meteor 收到 OnAttackStopped 后应离场，实际位置={attacker.Location}";
        }

        if (!state.Deck(Side.Right).Any(c => c.Name == attackerName
                                             && c.Attack == 2 && c.Defense == 2))
        {
            return "Meteor 的 OnAttackStopped 应生成一张 2/2 牌库副本";
        }

        return null;
    }

    /// <summary>
    /// T30 的两个订阅者都在卡片 locals 中。Cold Trap 应在攻击伤害结算前
    /// 生成 SISSI 并把目标改成它；原目标不应承受这次攻击。
    /// </summary>
    private static string? OtherCardAttackSwitchesTarget(CardDatabase db)
    {
        const string attackerName = "card_unit_arado_ar_196";
        const string defenderName = "card_unit_85_pioneer_company";
        const string trapName = "card_event_cold_trap";
        const string replacementName = "card_unit_sissi";
        foreach (var name in new[] { attackerName, defenderName, trapName, replacementName })
        {
            if (db.Find(name) is null)
            {
                return $"卡库里缺 {name}";
            }
        }

        var (engine, state) = EmptyBoard(db);
        state.ActiveSide = Side.Right;
        state.SetKredits(Side.Right, 12);
        state.SetMaxKredits(Side.Right, 12);

        var attacker = state.CreateWithId(attackerName, Side.Right, 210,
            CardLocation.BoardFrontline, 0);
        var defender = state.CreateWithId(defenderName, Side.Left, 211,
            CardLocation.BoardFrontline, 0);
        var trap = state.CreateWithId(trapName, Side.Left, 212,
            CardLocation.HandLeft, 1);
        trap.GotchaActivated = 1;
        attacker.EnteredPlayOnTurn = -1;
        defender.EnteredPlayOnTurn = -1;
        trap.EnteredPlayOnTurn = -1;
        engine.Api.RemoveKeyword(defender, Keyword.Smokescreen);

        int defenderBefore = defender.Defense;
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        if (!engine.Attack(attacker, defender, out string reason))
        {
            return $"带 Cold Trap 的攻击没有进入攻击结算：{reason}";
        }

        if (!trace.Any(x => x.StartsWith("OnOtherCardAttackSwitchTarget", StringComparison.Ordinal)
                         && x.Contains(trapName, StringComparison.Ordinal)))
        {
            return "T30 locals 没有派发到 Cold Trap"
                 + $"\n       实际派发记录：{string.Join(" | ", trace)}";
        }

        if (defender.Defense != defenderBefore)
        {
            return $"Cold Trap 已改目标，但原目标仍受到伤害：{defenderBefore} → {defender.Defense}"
                 + $"\n       trace={string.Join(" | ", trace)}"
                 + $"\n       cards={string.Join(" | ", state.AllCards.Where(c => c.Name == replacementName).Select(c => $"{c.CardId}@{c.Location}/{c.Defense}"))}";
        }

        var sissi = state.AllCards.FirstOrDefault(c => c.Name == replacementName);
        if (sissi is null)
        {
            return "Cold Trap 没有生成 SISSI";
        }

        if (sissi.Location != CardLocation.Discard)
        {
            return $"攻击应落到 SISSI 并摧毁它，实际位置={sissi.Location} 防御={sissi.Defense}";
        }

        return null;
    }

    // ==================================================================
    //  §①.9 三条基本规则
    // ==================================================================

    /// <summary>
    /// 部署落点 = **自己半场**（`Side.HqOf()`，即 5/6），**不是前线**。
    ///
    /// 真实数据：250 条快照里**前线为空的占 83%**（207/250）—— 单位绝大多数待在底线。
    /// 出厂口 `BP_Logic::CanPlayCardFromHand` i=959 判的也是
    /// `IsLocationFull(SupplyLineLocationFromSide(side))`，只查半场。
    ///
    /// 同时守容量：半场 **5 格含 HQ**（`FetchCardsByLocation` case 5,6 → MaxQty=5，
    /// 计数循环只按 location 过滤、不排除 HQ）⇒ 每边最多 **4 个单位**。
    /// </summary>
    private static string? HalfBoardDeploymentAndCapacity(CardDatabase db)
    {
        const string unit = "card_unit_arado_ar_196";
        if (db.Find(unit) is null)
        {
            return $"卡库里缺 {unit}";
        }

        var (engine, state) = EmptyBoard(db);
        state.ActiveSide = Side.Left;

        // 逐个打出，直到半场满
        int played = 0;
        for (int i = 0; i < 6; i++)
        {
            state.SetKredits(Side.Left, 12);
            state.SetMaxKredits(Side.Left, 12);
            var c = state.Create($"{unit}", Side.Left, CardLocation.HandLeft,
                                 state.NextLocationNumber(Side.Left, CardLocation.HandLeft));
            if (engine.PlayCard(c))
            {
                played++;
                continue;
            }

            // 打不出来 → 必须是因为半场满（不是别的原因）
            if (!engine.CanPlay(c, out string why))
            {
                if (why != "半场已满")
                {
                    return $"第 {i + 1} 个单位的拒绝原因不是「半场已满」而是「{why}」";
                }

                break;
            }
        }

        if (played != 4)
        {
            return $"半场应能放 4 个单位（5 格 − HQ 1 格），实际放下 {played} 个"
                 + Dump(state, ("未实现", Unimpl(state)));
        }

        foreach (var u in state.Board(Side.Left))
        {
            if (u.Location != CardLocation.BoardHqLeft)
            {
                return $"单位应部署到自己的半场 BoardHqLeft，实际 {u.Location}（{u.Name}）";
            }
        }

        // 半场里的第 0 格是 HQ —— 所以单位占的是 1..4
        var hq = state.Hq(Side.Left);
        if (hq.LocationNumber != 0 || !hq.IsHq)
        {
            return $"HQ 应占半场第 0 格，实际 #{hq.LocationNumber} IsHq={hq.IsHq}";
        }

        if (state.Cards(Side.Left, CardLocation.BoardHqLeft).Count != 5)
        {
            return $"半场总格数应为 5（HQ + 4 单位），实际 {state.Cards(Side.Left, CardLocation.BoardHqLeft).Count}";
        }

        return null;
    }

    /// <summary>
    /// 召唤失调：`enterPlayOnTurn == currentTurn &amp;&amp; !getHasBlitz()` ⇒ 当回合
    /// **攻击和移动都被挡**（`BP_Logic::CanCardDoAnything` i=1352-1568 在两条检查之前；
    /// `cardsCheckFunctions::CanAttack` i=2087-2167 写 `failReason="deployment_sickness"`）。
    ///
    /// ⚠️ 这条断言同时也守「卡面自带 Blitz 已加载」——
    /// `cards.live.json` 里没有 `hasBlitz`，不额外加载的话 Blitz 例外根本判不出来。
    /// </summary>
    private static string? DeploymentSickness(CardDatabase db)
    {
        const string plain = "card_unit_arado_ar_196";      // 无 Blitz
        const string blitz = "card_unit_m20_scout_car";     // CDO hasBlitz = True
        if (db.Find(plain) is null || db.Find(blitz) is null)
        {
            return $"卡库里缺 {plain} 或 {blitz}";
        }

        if (!db.Find(blitz)!.Keywords.Contains(Keyword.Blitz, StringComparer.Ordinal))
        {
            return $"{blitz} 的卡面 Blitz 没被加载（CardDefinition.Keywords 里没有 Blitz）";
        }

        var (engine, state) = EmptyBoard(db);
        state.SetKredits(Side.Left, 12);
        state.SetMaxKredits(Side.Left, 12);
        state.ActiveSide = Side.Left;

        var foot = state.CreateWithId(plain, Side.Left, 2, CardLocation.HandLeft, 0);
        var fast = state.CreateWithId(blitz, Side.Left, 3, CardLocation.HandLeft, 1);
        if (!engine.PlayCard(foot) || !engine.PlayCard(fast))
        {
            return "单位打不出来";
        }

        // 同回合：非 Blitz 不能动，Blitz 能
        if (foot.CanOperateThisTurn(state))
        {
            return $"非 Blitz 单位 {plain} 在部署当回合不应该能攻击";
        }

        if (foot.CanMoveThisTurn(state))
        {
            return $"非 Blitz 单位 {plain} 在部署当回合不应该能移动";
        }

        if (!fast.CanOperateThisTurn(state))
        {
            return $"Blitz 单位 {blitz} 在部署当回合**应该**能攻击（召唤失调的例外）";
        }

        if (engine.Attack(foot, state.Hq(Side.Right)))
        {
            return $"非 Blitz 单位 {plain} 部署当回合的攻击竟然成功了";
        }

        // 下一回合就能动了（把进场回合改成上一回合）
        foot.EnteredPlayOnTurn = state.Turn - 1;
        if (!foot.CanOperateThisTurn(state))
        {
            return "过了部署回合之后应该能攻击";
        }

        if (!engine.Attack(foot, state.Hq(Side.Right)))
        {
            return "过了部署回合之后攻击应该成功";
        }

        return null;
    }

    /// <summary>
    /// **奋战（Fury）**：一回合可以攻击两次 —— 回归对局 `389594` 的 ⑤b。
    ///
    /// ## 修的是什么
    /// `CardInstance.CanOperateThisTurn` 原先用 `!HasAttackedThisTurn`（布尔）当攻击门，
    /// 于是**第一次攻击之后**这个单位本回合再也攻击不了。奋战单位因此永远只打一次。
    ///
    /// ## 蓝图判据（不是规则表口述）
    /// <list type="bullet">
    /// <item>回合开始把额度设成 `getHasFury() ? 2 : 1`：
    ///   `DoOnStartOfTurn`（`ref/kards-sim/.../_deps/BP_Logic.g.cs:3104/3110/3124`）。</item>
    /// <item>攻击一次额度 -1：`SetAttackerHasAttacked`
    ///   （`.../BP_CardFunctions.g.cs:33930-33942`）。</item>
    /// <item>`CanAttack` 的门是 `HasAttackLeft(attackerCard)`
    ///   （`.../_deps/cardsCheckFunctions.g.cs:761-805`）。</item>
    /// </list>
    ///
    /// ## 这条为什么必须断言「第三次被拒」
    /// 把门从布尔改成"额度 &gt; 0"时，最容易犯的错是**忘了减额度**
    /// （那样就变成无限次攻击）。所以正反两面都要钉：
    /// 奋战 = 恰好 2 次、无奋战 = 恰好 1 次、第三次必须拒。
    /// </summary>
    private static string? FuryAllowsSecondAttack(CardDatabase db)
    {
        const string fury = "card_unit_111th_indian_brigade";   // 卡面 Fury，步兵
        const string plain = "card_unit_arado_ar_196";          // 无 Fury
        if (db.Find(fury) is null || db.Find(plain) is null)
        {
            return $"卡库里缺 {fury} 或 {plain}";
        }

        var (engine, state) = EmptyBoard(db);
        state.SetKredits(Side.Left, 12);
        state.SetMaxKredits(Side.Left, 12);
        state.ActiveSide = Side.Left;

        // 直接放到**前线**：这样 `CanReachAcrossFrontline` 的射程判据不会插手
        // （步兵 range=1，站半场时够不着对面 HQ，会把攻击失败的原因搅在一起）。
        var a = state.CreateWithId(fury, Side.Left, 2, CardLocation.BoardFrontline, 0);
        var b = state.CreateWithId(plain, Side.Left, 3, CardLocation.BoardFrontline, 1);
        foreach (var u in new[] { a, b })
        {
            u.EnteredPlayOnTurn = state.Turn - 1;   // 免召唤失调
            u.HasAttackedThisTurn = false;
            u.HasMovedThisTurn = false;
            u.AttacksThisTurn = 0;
        }

        if (!a.Keywords.Contains(Keyword.Fury, StringComparer.Ordinal))
        {
            return $"{fury} 的卡面 Fury 没被加载（CardInnateTable → Keywords）";
        }

        if (a.MaxAttacksThisTurn != 2 || b.MaxAttacksThisTurn != 1)
        {
            return $"额度上限错：奋战={a.MaxAttacksThisTurn}（应 2）、无奋战={b.MaxAttacksThisTurn}（应 1）";
        }

        // ---- 奋战：第一次 ----
        if (!engine.Attack(a, state.Hq(Side.Right)))
        {
            return $"奋战单位 {fury} 的**第一次**攻击就被拒了"
                 + Dump(state, ("未实现", Unimpl(state)));
        }

        if (!a.HasAttackLeft)
        {
            return $"奋战单位打完一次之后额度就该还剩 1（AttacksThisTurn={a.AttacksThisTurn}/" +
                   $"{a.MaxAttacksThisTurn}）";
        }

        // ---- 奋战：第二次（**修复前就死在这一条**）----
        if (!engine.Attack(a, state.Hq(Side.Right)))
        {
            return $"奋战单位 {fury} 的**第二次**攻击被拒了 —— Fury 的多次攻击没建模"
                 + Dump(state, ("已攻击次数", $"{a.AttacksThisTurn}/{a.MaxAttacksThisTurn}"),
                        ("HasAttackedThisTurn", a.HasAttackedThisTurn.ToString()));
        }

        // ---- 奋战：第三次必须拒（防止"只放行、不减额度"）----
        if (a.HasAttackLeft)
        {
            return $"奋战单位打完两次之后额度就该是 0（AttacksThisTurn={a.AttacksThisTurn}）";
        }

        if (engine.Attack(a, state.Hq(Side.Right)))
        {
            return $"奋战**只能**攻击两次，第三次竟然放行了（额度没被扣）";
        }

        // ---- 无奋战：恰好一次 ----
        if (!engine.Attack(b, state.Hq(Side.Right)))
        {
            return $"无奋战单位 {plain} 的第一次攻击被拒了（门收得太紧）";
        }

        if (engine.Attack(b, state.Hq(Side.Right)))
        {
            return $"无奋战单位 {plain} 不该能攻击两次";
        }

        return null;
    }

    /// <summary>
    /// **METEOR 的"攻击后留一张攻防翻倍的副本"** —— 回归对局 `389594` 的 ④（那 1 点 HQ 差）。
    ///
    /// 卡面（`cards.live.json`）：
    /// <c>Remove after this unit attacks. Add a copy to your deck with double attack and defense.</c>
    ///
    /// IR（`klink bot/docs/card-ir.json` → `card_unit_meteor`）：
    /// <code>
    /// OnAfterAttack i=745   IsLocatedOnBoard → 不在场直接返回
    ///              i=774   attTotal = getTotalAttack()
    ///              i=820   defTotal = getTotalDefense()
    ///              i=866   RemoveCardFromBoard(cardID)
    ///              i=929   SpawnCardInDeckBySide(…, "card_unit_meteor", …, out spawnedCardIDs)
    ///              i=1017  → 循环头 i=717/689/577
    ///              i=577   Array_Length(spawnedCardIDs)          ← ★ 出参不是数组时恒 0
    ///              i=636   Less_IntInt(计数, 长度) → popFlowIfNot  ⇒ 长度 0 = 整段跳过
    ///              i=47    attTotal * 2
    ///              i=89    Array_Get(spawnedCardIDs, idx)
    ///              i=148   GetCardFromID(item)
    ///              i=202   ChangeAttack(那张卡, cardID, attTotal*2, changeType=2 /*SetValue*/)
    ///              i=432   ChangeDefense(那张卡, cardID, defTotal*2, changeType=2)
    /// </code>
    ///
    /// 两处都要对，缺一不可：
    /// <list type="number">
    /// <item>出参必须是**数组**（`TArray&lt;int32&gt; spawnedCardIDs`，
    ///   签名 `_index.g.cs:4336`）—— 否则循环一次都不跑。</item>
    /// <item>`changeType=2` 是 **SetValue（总量赋成该值）**，不是"加"：
    ///   `ChangeAttack` 的 L_0357 分支 `setAndEncryptAttack(Clamp(amount,0,99))`
    ///   （`BP_CardFunctions.g.cs` 的 `ChangeAttack`，函数起始 `:6491`）。
    ///   按"加"算，1/1 的副本会变成 1+2=**3** 攻。</item>
    /// </list>
    ///
    /// 实测后果（修之前）：t7 生成的 `#7001` 是 1/1（客户端 2/2），
    /// t15 用它打右 HQ 只扣 1（客户端扣 2）⇒ `#73` 起 HQ 校验和差 1、闸门触发。
    /// </summary>
    private static string? MeteorCopyDoublesStats(CardDatabase db)
    {
        const string meteor = "card_unit_meteor";
        if (db.Find(meteor) is null)
        {
            return $"卡库里没有 {meteor}";
        }

        if (KismetLibrary.Default?.FindProgram(meteor, "OnAfterAttack") is null)
        {
            return $"IR 里没有 {meteor} 的 OnAfterAttack（card-ir.json 是否加载？）";
        }

        var (engine, state) = EmptyBoard(db);
        state.SetKredits(Side.Left, 12);
        state.SetMaxKredits(Side.Left, 12);
        state.ActiveSide = Side.Left;

        var m = state.CreateWithId(meteor, Side.Left, 2, CardLocation.BoardFrontline, 0);
        m.EnteredPlayOnTurn = state.Turn - 1;
        m.HasAttackedThisTurn = false;
        m.HasMovedThisTurn = false;
        m.AttacksThisTurn = 0;

        int atk = m.Attack, def = m.Defense;
        int hqBefore = state.HqDefense(Side.Right);
        if (!engine.Attack(m, state.Hq(Side.Right)))
        {
            return $"{meteor} 攻击被拒" + Dump(state, ("未实现", Unimpl(state)));
        }

        // 前置条件自检：原体必须是 1/1，否则"翻倍"这条断言就不是 2/2 了
        if (atk != 1 || def != 1)
        {
            return $"前提变了：{meteor} 卡面应为 1/1，实际 {atk}/{def}（本用例的期望值要跟着改）";
        }

        if (state.HqDefense(Side.Right) != hqBefore - atk)
        {
            return $"打 HQ 的伤害应是 {atk}，实际扣了 {hqBefore - state.HqDefense(Side.Right)}";
        }

        // ---- 原体必须被移出棋盘（卡面 "Remove after this unit attacks"）----
        if (m.Location.IsBoard())
        {
            return $"{meteor} 攻击之后必须离开棋盘，实际还在 {m.Location}";
        }

        // ---- 副本必须出现在牌库里，且是 2/2 ----
        var copies = state.Deck(Side.Left).Where(c => c.Name == meteor).ToList();
        if (copies.Count != 1)
        {
            return $"牌库里应当正好有 1 张生成的 {meteor} 副本，实际 {copies.Count} 张"
                 + Dump(state, ("牌库", string.Join("  ", state.Deck(Side.Left).Select(c => c.Name))),
                        ("未实现", Unimpl(state)));
        }

        var copy = copies[0];
        if (copy.Attack != atk * 2 || copy.Defense != def * 2)
        {
            return $"副本的攻/防应当是原值×2 = {atk * 2}/{def * 2}，实际 {copy.Attack}/{copy.Defense}"
                 + "（出参不是数组 ⇒ 循环没跑；或 changeType=2 被当成加法）";
        }

        // ---- 副本是**新的一张卡**，不能是原体本身换了个位置 ----
        if (copy.CardId == m.CardId)
        {
            return "生成的副本必须是新卡（新 cardID），不能复用原体的号";
        }

        return null;
    }

    /// <summary>
    /// 前线互斥（`BP_CardFunctions::MoveUnitFromSupportToFrontLine` i=281-543）：
    /// 对面占着前线 ⇒ 推不进去；我方占着且满（5）⇒ 也推不进去。
    /// **没有"把对面挤回半场"这条规则。**
    /// </summary>
    private static string? FrontlineMutualExclusion(CardDatabase db)
    {
        const string unit = "card_unit_arado_ar_196";
        var (engine, state) = EmptyBoard(db);
        state.SetKredits(Side.Left, 12);
        state.SetMaxKredits(Side.Left, 12);
        state.SetKredits(Side.Right, 12);
        state.SetMaxKredits(Side.Right, 12);

        // 左方推一个上去
        state.ActiveSide = Side.Left;
        var left1 = state.CreateWithId(unit, Side.Left, 2, CardLocation.HandLeft, 0);
        engine.PlayCard(left1);
        left1.HasMovedThisTurn = false;
        left1.EnteredPlayOnTurn = state.Turn - 1;   // 免召唤失调
        if (!engine.MoveUnit(left1, 0))
        {
            return "空前线居然推不上去"
                 + Dump(state, ("未实现", Unimpl(state)),
                        ("前线归属", state.FrontlineOwner.ToString()));
        }

        if (state.FrontlineOwner != Side.Left)
        {
            return $"推上去之后前线归属应为 Left，实际 {state.FrontlineOwner}";
        }

        // 右方再推 → 必须被拒（对面占着）
        state.ActiveSide = Side.Right;
        var right1 = state.CreateWithId(unit, Side.Right, 42, CardLocation.HandRight, 0);
        engine.PlayCard(right1);
        right1.HasMovedThisTurn = false;
        right1.EnteredPlayOnTurn = state.Turn - 1;
        if (engine.MoveUnit(right1, 0))
        {
            return "对面占着前线时竟然推得进去（蓝图 i=333 应该拒绝）";
        }

        if (right1.Location == CardLocation.BoardFrontline)
        {
            return "被拒的推进不应该改变位置";
        }

        // 左方把前线填满（容量 5）→ 第 6 个必须被拒
        state.ActiveSide = Side.Left;
        for (int i = 0; i < 4; i++)
        {
            var u = state.CreateWithId(unit, Side.Left, 10 + i, CardLocation.HandLeft, i);
            engine.PlayCard(u);
            u.HasMovedThisTurn = false;
            u.EnteredPlayOnTurn = state.Turn - 1;
            engine.MoveUnit(u, i + 1);
        }

        int count = state.Cards(Side.Left, CardLocation.BoardFrontline).Count;
        if (count != GameState.DefaultFrontlineCapacity)
        {
            return $"前线应能站满 {GameState.DefaultFrontlineCapacity} 个，实际 {count}";
        }

        var extra = state.CreateWithId(unit, Side.Left, 20, CardLocation.HandLeft, 0);
        engine.PlayCard(extra);
        extra.HasMovedThisTurn = false;
        extra.EnteredPlayOnTurn = state.Turn - 1;
        if (engine.MoveUnit(extra, 0))
        {
            return "前线已满时竟然还推得进去（蓝图 i=543 应该拒绝）";
        }

        return null;
    }

    // ==================================================================
    //  前线归属残留（2026-10-01，用户实测 replay-214436）
    // ==================================================================

    /// <summary>
    /// 摆一个「左方在前线站着 1 个 1 防单位、右方**半场**有一门 range=2 的炮兵」的局面。
    ///
    /// 两个关键设计：
    /// <list type="bullet">
    /// <item>杀手放在**半场**而不是前线 —— 否则它自己就把前线占了，
    ///   归属永远不会变成 <c>NotAvailable</c>，测不到这个 bug。</item>
    /// <item>杀手的 <c>Attack</c> 抬到 9、被杀者 <c>Defense=1</c>，保证**真的一击致死**
    ///   （而不是把 <c>Defense</c> 设成 0 假装死了 —— 那只是"待销毁"，
    ///   真正的死亡发生在 <c>CheckDeaths()</c> 里，见 `DeadUnitCannotMoveOrAttack` 的注释）。</item>
    /// </list>
    /// </summary>
    private static (MatchEngine Engine, GameState State, CardInstance Victim, CardInstance Killer)?
        FrontlineDeathSetup(CardDatabase db)
    {
        if (db.Find(InfRange1) is null || db.Find(ArtRange2) is null)
        {
            return null;
        }

        var (engine, state) = EmptyBoard(db);
        foreach (var side in new[] { Side.Left, Side.Right })
        {
            state.SetKredits(side, 20);
            state.SetMaxKredits(side, 20);
        }

        // 左方：先落在**自己半场**，再走真实路径 `MoveUnit` 推进前线
        // （直接 Create 到前线不会经过 `State.Move`，也就测不到钩子）。
        state.ActiveSide = Side.Left;
        var victim = state.CreateWithId(InfRange1, Side.Left, 2, CardLocation.BoardHqLeft, 1);
        victim.Attack = 0;               // 别让它反击把炮兵换掉，局面才好断言
        victim.Defense = 1;
        victim.MaxDefense = 1;
        victim.EnteredPlayOnTurn = -99;

        if (!engine.MoveUnit(victim, 0))
        {
            return null;
        }

        if (state.FrontlineOwner != Side.Left)
        {
            return null;
        }

        // 右方：半场槽 1 上的炮兵（range=2 ⇒ 够得着前线；自己**不**进前线）
        var killer = state.CreateWithId(ArtRange2, Side.Right, 42, CardLocation.BoardHqRight, 1);
        killer.Attack = 9;
        killer.Defense = 9;
        killer.MaxDefense = 9;
        killer.EnteredPlayOnTurn = -99;

        if (db.Find(ArtRange2)!.Range < 2)
        {
            return null;
        }

        return (engine, state, victim, killer);
    }

    /// <summary>
    /// **前线最后一个单位死亡后，`FrontlineOwner` 必须回到 `NotAvailable`。**
    ///
    /// 旧代码这条必挂：`Destroy` 里的 `State.Move(card, CardLocation.Discard)`
    /// 把卡搬出前线，却没有任何人重算归属 ⇒ 归属残留在 `Side.Left`。
    /// </summary>
    private static string? FrontlineOwnerResetOnLastUnitDeath(CardDatabase db)
    {
        var made = FrontlineDeathSetup(db);
        if (made is null)
        {
            return $"造不出局面（缺 {InfRange1} / {ArtRange2} 或推进被拒）—— 本测试前提不成立";
        }

        var (engine, state, victim, killer) = made.Value;

        if (state.FrontlineOwner != Side.Left)
        {
            return $"推进后前线归属应为 Left，实际 {state.FrontlineOwner}（前置不成立）";
        }

        // 右方开炮（半场 range=2 → 前线）
        state.ActiveSide = Side.Right;
        if (!engine.Attack(killer, victim))
        {
            return $"半场炮兵(range=2) 打不到前线单位 —— 本测试前提不成立"
                 + Dump(state, ("未实现", Unimpl(state)), ("前线归属", state.FrontlineOwner.ToString()));
        }

        if (victim.Location != CardLocation.Discard)
        {
            return $"1 防单位挨了 9 点伤害却没进弃牌堆（Location={victim.Location}，"
                 + $"Defense={victim.Defense}）—— 判死链路有问题";
        }

        if (state.FrontlineOwner != Side.NotAvailable)
        {
            return $"**前线最后一个单位已死，归属却仍是 {state.FrontlineOwner}**"
                 + $"（前线现有 {state.Cards(Side.Left, CardLocation.BoardFrontline).Count()}"
                 + $"+{state.Cards(Side.Right, CardLocation.BoardFrontline).Count()} 张）"
                 + " —— `Destroy` 把卡搬出前线却没重算归属，"
                 + "旧代码就是这样把 AI 的推进永久堵死的";
        }

        return null;
    }

    /// <summary>
    /// **归属残留的杀伤力：死者的对面必须能重新推进前线。**
    ///
    /// 这条是"症状复现"：旧代码里前线明明空了，`MoveUnit` 却因为
    /// `FrontlineOwner` 残留在 Left 而走 `<frontline-blocked-by-opponent>` 分支被拒
    /// —— 而 `MoveUnit` 的互斥门本身是**对的**（蓝图 i=281/333），
    /// 错的是没人清归属。所以这里断言的是**端到端可达性**，不是那道门。
    /// </summary>
    private static string? FrontlineRetakeableAfterOwnerDied(CardDatabase db)
    {
        var made = FrontlineDeathSetup(db);
        if (made is null)
        {
            return $"造不出局面（缺 {InfRange1} / {ArtRange2} 或推进被拒）—— 本测试前提不成立";
        }

        var (engine, state, victim, killer) = made.Value;

        // 右方先在半场备一个能推进的单位（半场槽 2）
        var mover = state.CreateWithId(InfRange1, Side.Right, 43, CardLocation.BoardHqRight, 2);
        mover.Attack = 1;
        mover.Defense = 3;
        mover.MaxDefense = 3;
        mover.EnteredPlayOnTurn = -99;

        // ① 归属还挂在 Left 时，右方推进**必须被拒**（互斥门 i=281/333 是对的，别动它）
        state.ActiveSide = Side.Right;
        if (engine.MoveUnit(mover, 0))
        {
            return "对面（Left）占着前线时右方竟然推得进去 —— 互斥门坏了";
        }

        int blocked = state.UnimplementedCalls.GetValueOrDefault("<frontline-blocked-by-opponent>");

        // ② 打死左方前线的最后一个单位
        if (!engine.Attack(killer, victim))
        {
            return $"半场炮兵(range=2) 打不到前线单位 —— 本测试前提不成立"
                 + Dump(state, ("未实现", Unimpl(state)));
        }

        if (state.FrontlineOwner != Side.NotAvailable)
        {
            return $"单位已死但归属仍是 {state.FrontlineOwner} —— 见上一条用例";
        }

        // ③ 现在前线真空了 ⇒ 右方**必须**推得进去（旧代码在这里被误拒）
        mover.HasMovedThisTurn = false;
        mover.HasAttackedThisTurn = false;
        state.ActiveSide = Side.Right;
        if (!engine.MoveUnit(mover, 0))
        {
            int blockedAfter = state.UnimplementedCalls.GetValueOrDefault("<frontline-blocked-by-opponent>");
            return "**前线已空，右方却推不进去**"
                 + $"（`<frontline-blocked-by-opponent>` 计数 {blocked}→{blockedAfter}，"
                 + $"前线归属={state.FrontlineOwner}）—— 这正是「AI 只能空过」的症状"
                 + Dump(state, ("未实现", Unimpl(state)));
        }

        if (state.FrontlineOwner != Side.Right)
        {
            return $"右方推进后归属应为 Right，实际 {state.FrontlineOwner}";
        }

        return null;
    }

    /// <summary>
    /// `card_event_fog_of_war`（英国 4 费指令，卡面：
    /// 「Remove target unit from the battlefield. Put two copies on top of owner's deck.」）
    /// —— 对局 `773639` `#45 t9 ML` 的根因用例。
    ///
    /// ## 现场证据（`out/_server-replays/replay-773639.actions.json`）
    ///
    /// <code>
    /// #25 t7 R ML {"0":"60", "1":"0"}       ; bot 把 card_unit_1st_airborne#60 推上前线
    /// #29 t7 L PC {"0":"19", "2":"60"}      ; 人类打 19=card_event_fog_of_war，目标正是 #60
    /// #45 t9 L ML {"0":"21", "1":"0"}       ; 人类推 card_unit_no_46_commando#21 上前线
    /// </code>
    ///
    /// 客户端里 `#60` 在 `#29` 就被移出战场了，所以 `#45` 的推进是合法的；
    /// 我们这边 `#60` 一直待在前线（审计 ① 直到 `#64 t13` 才报它离场），
    /// `FrontlineOwner` 仍是 `Right` ⇒ `#45` 被 `MoveUnit` 的互斥门拒
    /// （审计 ⑤b：`移动被拒：前线被对面占着（前线归属=Right，本单位=Left）`）。
    ///
    /// ## IR（`klink bot/docs/card-ir.json` → `card_event_fog_of_war`）
    ///
    /// <code>
    /// entrypoints: { "OnPlayedFromHand": 10 }
    /// i=10   RemoveCardFromBoard(cardID@targetCard, cardID@self, out qqq)
    /// i=95   SpawnCardInDeckBySide(originalSide, name, cardID@self, 2, salvageFaction, …)
    /// i=252  return
    /// </code>
    /// 只有两条语句，所以**不可能是** `MaxStepsPerProgram` 截断（那个坑见
    /// `AtlanticConvoyBoardAndHand`）。
    ///
    /// ## 断言口径（直接断言中间状态，不靠"连打 N 局看结果"）
    ///
    /// 1. 目标必须**离开战场**（`Location.IsBoard()` 为假）
    /// 2. `FrontlineOwner` 必须回到 `NotAvailable`（这是 `#45` 被误拒的直接原因）
    /// 3. 目标所有者的牌库必须多出 **2 张**同名卡（i=95 的 `SpawnCardInDeckBySide(…, 2, …)`）
    /// </summary>
    private static string? FogOfWarRemovesTargetFromBattlefield(CardDatabase db)
    {
        const string Card = "card_event_fog_of_war";

        if (db.Find(Card) is null)
        {
            return $"卡库里缺 {Card}";
        }

        if (KismetLibrary.Default?.FindProgram(Card, "OnPlayedFromHand") is null)
        {
            return $"IR 里没有 {Card} 的 OnPlayedFromHand（card-ir.json 是否加载？）";
        }

        var (engine, state) = EmptyBoard(db);
        foreach (var side in new[] { Side.Left, Side.Right })
        {
            state.SetKredits(side, 20);
            state.SetMaxKredits(side, 20);
        }

        // 右方一个单位在**前线**：走真实路径 `MoveUnit`，这样 `FrontlineOwner`
        // 才会被算成 `Right`（直接 Create 到前线不经过换区钩子，见 `FrontlineDeathSetup`）。
        state.ActiveSide = Side.Right;
        var victim = state.CreateWithId(InfRange1, Side.Right, 42, CardLocation.BoardHqRight, 1);
        victim.EnteredPlayOnTurn = -99;

        if (!engine.MoveUnit(victim, 0, out string mvWhy))
        {
            return $"前置不成立：右方推不进空前线（{mvWhy}）";
        }

        if (state.FrontlineOwner != Side.Right)
        {
            return $"前置不成立：推上去之后前线归属应为 Right，实际 {state.FrontlineOwner}";
        }

        // 左方从手牌打出雾战，目标是那个前线单位。
        state.ActiveSide = Side.Left;
        var order = state.CreateWithId(Card, Side.Left, 2, CardLocation.HandLeft, 0);
        order.EnteredPlayOnTurn = -99;

        if (!engine.CanPlay(order, out string why))
        {
            return $"前置不成立：雾战打不出（{why}）";
        }

        int deckBefore = state.Deck(Side.Right).Count;
        int leftDeckBefore = state.Deck(Side.Left).Count;
        int unimplBefore = state.UnimplementedCalls.Count;
        engine.PlayCard(order, victim);

        if (victim.Location.IsBoard())
        {
            return $"**雾战没有把目标移出战场**（目标仍在 {victim.Location}#{victim.LocationNumber}）"
                 + " —— IR i=10 `RemoveCardFromBoard` 这一路没生效"
                 + Dump(state, ("未实现", Unimpl(state)),
                        ("前线归属", state.FrontlineOwner.ToString()));
        }

        if (state.FrontlineOwner != Side.NotAvailable)
        {
            return $"目标已离场，但 `FrontlineOwner` 仍是 {state.FrontlineOwner}"
                 + " —— 前线归属没跟着释放，对面会被互斥门误拒（773639 #45 的症状）"
                 + Dump(state, ("未实现", Unimpl(state)));
        }

        int spawned = state.Deck(Side.Right).Count - deckBefore;
        if (spawned != 2)
        {
            return $"i=95 `SpawnCardInDeckBySide(…, 2, …)` 应该往**目标所有者**（Right）的牌库塞 2 张，" +
                   $"实际 {spawned} 张（左方牌库变化 {state.Deck(Side.Left).Count - leftDeckBefore}）" +
                   " —— `originalSide` 没被认出来时 `SideArg` 会退回施法者"
                 + Dump(state, ("未实现", Unimpl(state)));
        }

        if (state.UnimplementedCalls.Count > unimplBefore)
        {
            return "雾战执行期间撞到了新的未实现原语"
                 + Dump(state, ("未实现", Unimpl(state)));
        }

        return null;
    }

    private static string? SpawnCardInDeckHonorsBottom(CardDatabase db)
    {
        const string sourceName = "card_event_confusion";
        const string existingName = "card_unit_arado_ar_196";
        const string spawnedName = "card_unit_1st_infantry_regiment_us";
        foreach (string name in new[] { sourceName, existingName, spawnedName })
        {
            if (db.Find(name) is null)
            {
                return $"卡库里缺 {name}";
            }
        }

        var (engine, state) = EmptyBoard(db);
        var source = state.CreateWithId(sourceName, Side.Left, 2, CardLocation.Discard, 0);
        var first = state.CreateWithId(existingName, Side.Right, 42, CardLocation.DeckRight, 0);
        var second = state.CreateWithId(existingName, Side.Right, 43, CardLocation.DeckRight, 1);
        var ctx = new EffectContext
        {
            Engine = engine,
            State = state,
            Self = source,
            Controller = Side.Left,
        };

        // side=Right is the integer 2; it must not override bottom=true.
        object? bottomResult = engine.Api.InvokeByName("SpawnCardInDeckBySide", source,
            new object?[] { (int)Side.Right, spawnedName, source.CardId, 1, "", false,
                true, false, false, false, null }, ctx, out bool bottomHandled);
        if (!bottomHandled || bottomResult is not System.Collections.IEnumerable)
        {
            return "SpawnCardInDeckBySide(bottom=true) 未接入派发表";
        }

        var deck = state.Deck(Side.Right);
        if (deck.Count != 3 || !ReferenceEquals(deck[0], first) || !ReferenceEquals(deck[1], second)
            || deck[2].Name != spawnedName)
        {
            return $"bottom=true 应把新卡放到牌库底，实际顺序：{string.Join(",", deck.Select(x => x.Name))}";
        }

        object? topResult = engine.Api.InvokeByName("SpawnCardInDeckBySide", source,
            new object?[] { (int)Side.Right, spawnedName, source.CardId, 1, "", false,
                false, false, false, false, null }, ctx, out bool topHandled);
        if (!topHandled || topResult is not System.Collections.IEnumerable)
        {
            return "SpawnCardInDeckBySide(bottom=false) 未接入派发表";
        }

        deck = state.Deck(Side.Right);
        if (deck.Count != 4 || deck[0].Name != spawnedName || !ReferenceEquals(deck[1], first)
            || !ReferenceEquals(deck[2], second))
        {
            return $"bottom=false 应把新卡放到牌库顶，实际顺序：{string.Join(",", deck.Select(x => x.Name))}";
        }

        return null;
    }

    private static string? SpawnCardInDeckRandomInsertion(CardDatabase db)
    {
        const string sourceName = "card_event_confusion";
        const string existingName = "card_unit_arado_ar_196";
        const string spawnedName = "card_unit_1st_infantry_regiment_us";
        foreach (string name in new[] { sourceName, existingName, spawnedName })
        {
            if (db.Find(name) is null)
            {
                return $"卡库里缺 {name}";
            }
        }

        var (engine, state) = EmptyBoard(db);
        var source = state.CreateWithId(sourceName, Side.Left, 2, CardLocation.Discard, 0);
        var first = state.CreateWithId(existingName, Side.Right, 42, CardLocation.DeckRight, 0);
        var second = state.CreateWithId(existingName, Side.Right, 43, CardLocation.DeckRight, 1);
        var ctx = new EffectContext
        {
            Engine = engine,
            State = state,
            Self = source,
            Controller = Side.Left,
        };

        var expectedRandom = new UeRandomStream(1);
        int firstIndex = NativeRandomDrawOracle(expectedRandom, 0, 3);
        int secondIndex = NativeRandomDrawOracle(expectedRandom, 0, 4);
        object? result = engine.Api.InvokeByName("SpawnCardInDeckBySide", source,
            new object?[] { (int)Side.Right, spawnedName, source.CardId, 2, "", false,
                true, false, false, true, null }, ctx, out bool handled);
        if (!handled || result is not System.Collections.IEnumerable)
        {
            return "SpawnCardInDeckBySide(RandomWithoutShuffle=true) 未接入派发表";
        }

        var spawnedIds = (result as System.Collections.IEnumerable)!
            .Cast<int>().ToList();
        if (spawnedIds.Count != 2 || state.Random.ConsumedCount != expectedRandom.ConsumedCount || state.Random.Seed != expectedRandom.Seed)
        {
            return $"随机模式应生成 2 张且逐张执行完整辅助函数，实际生成 {spawnedIds.Count} 张、消费 {state.Random.ConsumedCount} 次";
        }

        var expected = new List<int> { first.CardId, second.CardId };
        expected.Insert(Math.Min(firstIndex, expected.Count), spawnedIds[0]);
        expected.Insert(Math.Min(secondIndex, expected.Count), spawnedIds[1]);
        var actual = state.Deck(Side.Right).Select(card => card.CardId).ToList();
        if (!actual.SequenceEqual(expected))
        {
            return $"随机模式应按索引插入（first={firstIndex}, second={secondIndex}），实际顺序：" +
                   string.Join(",", actual) + "，期望：" + string.Join(",", expected);
        }

        return null;
    }

    private static string? SpawnCardInDeckShuffle(CardDatabase db)
    {
        const string sourceName = "card_event_confusion";
        const string existingName = "card_unit_arado_ar_196";
        const string spawnedName = "card_unit_1st_infantry_regiment_us";
        foreach (string name in new[] { sourceName, existingName, spawnedName })
        {
            if (db.Find(name) is null)
            {
                return $"卡库里缺 {name}";
            }
        }

        var (engine, state) = EmptyBoard(db);
        var source = state.CreateWithId(sourceName, Side.Left, 2, CardLocation.Discard, 0);
        var first = state.CreateWithId(existingName, Side.Right, 42, CardLocation.DeckRight, 0);
        var second = state.CreateWithId(existingName, Side.Right, 43, CardLocation.DeckRight, 1);
        var ctx = new EffectContext
        {
            Engine = engine,
            State = state,
            Self = source,
            Controller = Side.Left,
        };

        object? result = engine.Api.InvokeByName("SpawnCardInDeckBySide", source,
            new object?[] { (int)Side.Right, spawnedName, source.CardId, 1, "", false,
                true, true, false, false, null }, ctx, out bool handled);
        if (!handled || result is not System.Collections.IEnumerable)
        {
            return "SpawnCardInDeckBySide(shuffle=true) 未接入派发表";
        }

        var spawnedIds = (result as System.Collections.IEnumerable)!
            .Cast<int>().ToList();
        if (spawnedIds.Count != 1)
        {
            return $"shuffle=true 应返回 1 个新卡 ID，实际 {spawnedIds.Count} 个";
        }

        var expectedRandom = new UeRandomStream(1);
        NativeRandomDrawOracle(expectedRandom, 0, 3); // helper executes even when RandomWithoutShuffle=false
        var expected = new List<int> { first.CardId, second.CardId, spawnedIds[0] };
        expectedRandom.Shuffle(expected);

        var actual = state.Deck(Side.Right).Select(card => card.CardId).ToList();
        if (!actual.SequenceEqual(expected))
        {
            return "shuffle=true 应按蓝图随机流洗牌，实际顺序：" + string.Join(",", actual) +
                   "，期望：" + string.Join(",", expected);
        }

        if (state.Random.ConsumedCount != expectedRandom.ConsumedCount || state.Random.Seed != expectedRandom.Seed)
        {
            return $"生成应先执行完整辅助函数，再用原始流洗牌，实际 {state.Random.ConsumedCount} 次";
        }

        return null;
    }

    // ⚠️ 2026-10-02：`KreditSlotsGrowEveryTurn`（断言"kredit 槽位每回合双方各 +1"）
    // **永久撤下，不要恢复** —— 它断言的模型是**错的**。
    //
    // 定案：槽位 = **自己第几个回合**（+ 卡牌效果的额外槽），即 `StartTurn` 里现成那段。
    // 证据：真人玩家的规则描述（"对面也变成1 / 我第2回合变成2 / 战争机器+1→3 /
    // 我的下个回合自然增长→4"）。
    //
    // 上一轮之所以会怀疑它，是拿 **`cards.live.json` 的卡面费用**当花费反推槽位 ——
    // 而**卡面费用 ≠ 实际支付**，偏差两个方向都有：PAMS 开发出来的牌客户端当 0 费
    // （`card_event_pams` IR i=348 `ChangeKreditCost(卡,自己,0,changeType=2)`）会被**高估**；
    // 回合内的 `iron_from_the_north`（+3 kredit）/ `war_bonds`（+2 槽）会被**低估**。
    // 换成实际支付重算（`tools/ServerBridgeTest --kredit-table`）后，
    // 4 局 / 60 个人类回合里 self 模型**违反 0 条**，原先那"5 条违反"全部消失。
    //
    // ⚠️ 那张表**不能**反过来当"全局回合号"的证据：global 槽位恒 ≥ self 槽位，
    // 「花费 ≤ 槽位」只能证伪 self、永远证伪不了 global，是**单侧弱约束**。
    // 完整说明在 `MatchEngine.StartTurn` 的「已定案」注释里。

    /// <summary>
    /// **直接生成到前线（不是推进）也必须更新 `FrontlineOwner`。**
    ///
    /// 为什么单独一条：`CardApi.SpawnOnBattlefield` 的落点是
    /// `State.Create(name, side, BoardFrontline, 0)`，紧接着
    /// `State.Move(card, BoardFrontline, slot)` —— 这是**同区移动**，
    /// `GameState.Move` 里 `moved == false` ⇒ **换区钩子不发** ⇒ 归属不会更新。
    ///
    /// 蓝图在 `SpawnCardToBoard` 里是**显式**补这一句的
    /// （`ref/kards-sim/KardsSim/Generated/BP_CardFunctions.g.cs`）：
    /// <code>
    ///   L_03D3  EqualEqual_ByteByte(location, 7)
    ///   L_03F2  JumpIfNot L_0417
    ///   L_0400  UpdateFrontlineIfNeeded(spawnedID)     ← ★ 显式，不靠换区钩子
    /// </code>
    /// 走这条路的真实入口是 `SpawnCardInFrontline`（108 调用点 / 29 张卡，
    /// 例 `card_event_airdrop` i=219）。
    ///
    /// ## 断言口径
    ///
    /// 第一条断言中间状态（`FrontlineOwner` 变成生成方）；
    /// 第二条断言**后果** —— 不修的话互斥门形同虚设，对面能推进到**已经被占**的前线。
    /// </summary>
    /// <summary>
    /// `JSON_Clear(card, variableName, out found)` —— 蓝图 `BP_CardFunctions.g.cs:24383-24395`：
    /// 先 `JsonHasField` 查，**只删指定的那一个键**，并把 `found = existed` 写出去。
    /// 旧实现 `card.CustomJson.Clear()` 会**清空整张表**、忽略键名、且 `found` 从不写入。
    /// </summary>
    private static string? JsonClearRemovesOnlyNamedKey(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        var card = engine.Api.SpawnOnBattlefield(Side.Left, InfRange1, frontline: false);

        engine.Api.JsonSetInt(card, "keep", 7);
        engine.Api.JsonSetInt(card, "drop", 9);

        bool found = engine.Api.JsonClear(card, "drop");
        if (!found)
        {
            return "**`JsonClear` 对**存在**的键回报 false**（应 true）"
                 + Dump(state, ("customJson", string.Join(",", card.CustomJson.Select(kv => $"{kv.Key}={kv.Value}"))));
        }

        if (card.CustomJson.ContainsKey("drop"))
        {
            return "**`JsonClear` 没有删掉指定的键**"
                 + Dump(state, ("customJson", string.Join(",", card.CustomJson.Select(kv => $"{kv.Key}={kv.Value}"))));
        }

        if (engine.Api.JsonGetInt(card, "keep") != 7)
        {
            return "**`JsonClear` 把**别的**键也删了** —— 旧实现是 `CustomJson.Clear()` 清空整张表，"
                 + "蓝图只 `JsonRemoveField(…, variableName)`"
                 + Dump(state, ("customJson", string.Join(",", card.CustomJson.Select(kv => $"{kv.Key}={kv.Value}"))));
        }

        if (engine.Api.JsonClear(card, "nope"))
        {
            return "**`JsonClear` 对**不存在**的键回报 true**（应 false）";
        }

        return null;
    }

    private static string? JsonRemoveFromIntArray(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        var card = engine.Api.SpawnOnBattlefield(Side.Left, InfRange1, frontline: false);
        engine.Api.JsonSetInt(card, "keep", 7);
        engine.Api.JsonSetIntArray(card, "values", new[] { 4, 7, 4, 9 });
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = card, Controller = Side.Left,
        };

        object? removed = engine.Api.InvokeByName("JSON_RemoveFromIntArray", card,
            new object?[] { card, "values", 4, null }, ctx, out bool handled);
        if (!handled || removed is not true
            || !engine.Api.JsonGetIntArray(card, "values").SequenceEqual(new[] { 7, 4, 9 }))
        {
            return $"应只移除第一个匹配值并返回 found=true（handled={handled}, result={removed ?? "null"}, "
                 + $"values={string.Join(",", engine.Api.JsonGetIntArray(card, "values"))}）";
        }

        if (engine.Api.JsonGetInt(card, "keep") != 7)
        {
            return "移除数组元素不应影响同卡其他 JSON 字段";
        }

        object? absent = engine.Api.InvokeByName("JSON_RemoveFromIntArray", card,
            new object?[] { card, "values", 5, null }, ctx, out bool absentHandled);
        if (!absentHandled || absent is not false
            || !engine.Api.JsonGetIntArray(card, "values").SequenceEqual(new[] { 7, 4, 9 }))
        {
            return "移除不存在的值应返回 found=false 且保持数组不变";
        }

        object? missing = engine.Api.InvokeByName("JSON_RemoveFromIntArray", card,
            new object?[] { card, "missing", 1, null }, ctx, out bool missingHandled);
        if (!missingHandled || missing is not false || card.CustomJson.ContainsKey("missing"))
        {
            return "缺少 JSON 数组字段时应返回 found=false，且不能新建字段";
        }

        return null;
    }

    private static string? CustomGameplayTagDispatch(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        var source = engine.Api.SpawnOnBattlefield(Side.Left, InfRange1, frontline: false);
        var target = engine.Api.SpawnOnBattlefield(Side.Left, InfRange1, frontline: false);
        engine.Api.JsonSetInt(target, "keep", 7);
        engine.Api.CustomAbilityAdd(target, "destruction", source);
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = source, Target = target, Controller = Side.Left,
        };

        object? added = engine.Api.InvokeByName("AddCustomGameplayTag", source,
            new object?[] { new List<string> { "Subtype.Navy" }, target.CardId, source.CardId, null },
            ctx, out bool addHandled);
        if (!addHandled || added is not null || !engine.Api.HasCustomGameplayTag(target, "subtype.navy"))
        {
            return $"AddCustomGameplayTag 未按目标 cardID 生效（handled={addHandled}, tag={engine.Api.HasCustomGameplayTag(target, "subtype.navy")})";
        }

        engine.Api.InvokeByName("AddCustomGameplayTag", source,
            new object?[] { new List<string> { "subtype.navy" }, target.CardId, source.CardId, null }, ctx, out _);
        if (target.CustomJson.GetValueOrDefault("__customGameplayTags") != "subtype.navy")
        {
            return "重复添加 GameplayTag 不应产生重复存储";
        }

        if (!engine.Api.HasCustomGameplayTag(target, "subtype.navy")
            || !engine.Api.HasCustomAbility(target, "destruction")
            || engine.Api.JsonGetInt(target, "keep") != 7)
        {
            return "动态 GameplayTag 不应污染 CustomAbility 或其他 JSON 字段";
        }

        object? removed = engine.Api.InvokeByName("RemoveCustomGameplayTag", source,
            new object?[] { new List<string> { "SUBTYPE.NAVY" }, target.CardId, source.CardId, false, null },
            ctx, out bool removeHandled);
        if (!removeHandled || removed is not null || engine.Api.HasCustomGameplayTag(target, "subtype.navy")
            || target.CustomJson.ContainsKey("__customGameplayTags"))
        {
            return "RemoveCustomGameplayTag 未正确删除动态标签";
        }

        var staticNavy = db.Find("card_event_hms_belfast");
        if (staticNavy is not null)
        {
            var staticCard = engine.Api.SpawnOnBattlefield(Side.Left, staticNavy.Name, frontline: false);
            var staticCtx = new EffectContext
            {
                Engine = engine, State = state, Self = staticCard, Controller = Side.Left,
            };
            object? result = engine.Api.InvokeByName("getHasGameplayTag", staticCard,
                new object?[] { new List<string> { "subtype.navy" }, null }, staticCtx, out bool handled);
            if (!handled || result is not true)
            {
                return "删除动态标签不应影响卡面静态 GameplayTag 查询";
            }
        }

        return null;
    }

    private static string? SpawnToFrontlineUpdatesOwner(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        foreach (var side in new[] { Side.Left, Side.Right })
        {
            state.SetKredits(side, 20);
            state.SetMaxKredits(side, 20);
        }

        if (state.FrontlineOwner != Side.NotAvailable)
        {
            return $"前置不成立：开局前线应为空，实际归属 {state.FrontlineOwner}";
        }

        // 左方**直接生成**到前线 —— 不是 `MoveUnit` 推进
        var spawned = engine.Api.SpawnOnBattlefield(Side.Left, InfRange1, frontline: true);
        if (spawned.Location != CardLocation.BoardFrontline)
        {
            return $"前置不成立：`SpawnOnBattlefield(frontline: true)` 没落到前线（{spawned.Location}）";
        }

        if (state.FrontlineOwner != Side.Left)
        {
            return $"**直接生成到前线之后 `FrontlineOwner` 仍是 {state.FrontlineOwner}**（应为 Left）"
                 + " —— `Create` 到前线 + `Move` 到同一区 ⇒ 换区钩子不发 ⇒ 归属没重算"
                 + Dump(state, ("前线归属", state.FrontlineOwner.ToString()));
        }

        // 后果断言：右方推进必须被互斥门拒（不修的话这里会推得进去）
        state.ActiveSide = Side.Right;
        var mover = state.CreateWithId(InfRange1, Side.Right, 42, CardLocation.BoardHqRight, 1);
        mover.EnteredPlayOnTurn = -99;

        if (engine.MoveUnit(mover, 0, out string why))
        {
            return "对面**直接生成**到前线之后，右方竟然还推得进去 —— 互斥门失效"
                 + Dump(state, ("前线归属", state.FrontlineOwner.ToString()));
        }

        if (!why.Contains("对面占着", StringComparison.Ordinal))
        {
            return $"被拒原因应是「前线被对面占着」，实际：{why}";
        }

        return null;
    }

    /// <summary>
    /// **归属真的变化时 `OnFrontlineOwnershipChange` 必须被派发；没变时一次都不许发。**
    ///
    /// 断言口径：读 `CardApi.TriggerTrace`（现成的派发诊断记录），而不是看某张卡的
    /// 效果 —— 探针卡用真实卡 `card_unit_panzer_35t_commander`，它自己就订阅了
    /// `OnFrontlineOwnershipChange`（`klink bot/docs/card-ir.json` i=463）。
    ///
    /// ⚠️ **必须让探针卡自己当事件主体**（由它本人推进前线）。原因是 `FireTrigger`
    /// 的派发约定：`OnFrontlineOwnershipChange` 不以 `OnOther` 开头 ⇒ 走"只有主体
    /// 自己"那一路（`CardApi.cs:227-252`），非主体的订阅者只会在
    /// `OnOtherFrontlineOwnershipChange` 那一路被派发 —— 而全卡池里
    /// **`OnOtherFrontlineOwnershipChange` 的订阅者是 0 张**、`OnFrontlineOwnershipChange`
    /// 是 28 张（`card-ir.json` 全量扫描）。也就是说这个事件的"广播"其实到不了那 28 张卡，
    /// 那是**另一个**（派发层的）bug，已单独记录在报告里，不在这条用例的断言范围。
    ///
    /// 四个子断言，正好覆盖蓝图 `UpdateFrontlineIfNeeded` 的两条门
    /// （si=352 判等后返回 / si=186 空且本来就没归属时返回）：
    /// <list type="number">
    /// <item>空前线 → 推进：归属 NotAvailable→Left **必须发**</item>
    /// <item>已有归属 → 再推进（挪槽位）：归属没变 **不许发**</item>
    /// <item>杀掉"多出来的"那个：归属仍没变 **不许发**</item>
    /// <item>杀掉最后一个：归属 Left→NotAvailable **必须发**（本 bug 的主战场）</item>
    /// </list>
    /// </summary>
    private static string? FrontlineOwnershipTriggerDispatched(CardDatabase db)
    {
        const string probe = "card_unit_panzer_35t_commander";
        if (db.Find(probe) is null) return $"卡库里缺 {probe}";
        if (db.Find(InfRange1) is null) return $"卡库里缺 {InfRange1}";
        if (db.Find(ArtRange2) is null) return $"卡库里缺 {ArtRange2}";

        var (engine, state) = EmptyBoard(db);
        state.SetKredits(Side.Left, 20);
        state.SetMaxKredits(Side.Left, 20);
        state.SetKredits(Side.Right, 20);
        state.SetMaxKredits(Side.Right, 20);
        state.ActiveSide = Side.Left;

        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;

        bool OwnershipFired() => trace.Any(t => t.StartsWith("OnFrontlineOwnershipChange", StringComparison.Ordinal));

        // ---- ① 空前线推进 ⇒ 归属变了 ⇒ 必须发 ----
        var probeCard = state.CreateWithId(probe, Side.Left, 5, CardLocation.BoardHqLeft, 1);
        probeCard.Attack = 2;
        probeCard.Defense = 2;
        probeCard.MaxDefense = 2;
        probeCard.EnteredPlayOnTurn = -99;

        if (state.FrontlineOwner != Side.NotAvailable)
        {
            return $"开局归属应为 NotAvailable，实际 {state.FrontlineOwner}";
        }

        if (!engine.MoveUnit(probeCard, 0))
        {
            return "空前线居然推不上去（前置不成立）" + Dump(state, ("未实现", Unimpl(state)));
        }

        if (state.FrontlineOwner != Side.Left)
        {
            return $"推进后归属应为 Left，实际 {state.FrontlineOwner}";
        }

        if (!OwnershipFired())
        {
            return $"归属 NotAvailable→Left 真的变了，`OnFrontlineOwnershipChange` 却没派发到订阅卡 {probe}"
                 + Dump(state, ("未实现", Unimpl(state)),
                        ("前线归属", state.FrontlineOwner.ToString()),
                        ("派发记录", trace.Count == 0 ? "（空）" : string.Join(" | ", trace.Take(8))));
        }

        // ---- ② 归属没变（Left 仍占着）⇒ 不许发 ----
        trace.Clear();
        var second = state.CreateWithId(InfRange1, Side.Left, 6, CardLocation.BoardHqLeft, 2);
        second.Attack = 1;
        second.Defense = 1;
        second.MaxDefense = 1;
        second.EnteredPlayOnTurn = -99;

        if (!engine.MoveUnit(second, 1))
        {
            return "已占前线时第二个单位推不上去（前置不成立）"
                 + Dump(state, ("未实现", Unimpl(state)), ("前线归属", state.FrontlineOwner.ToString()));
        }

        if (state.FrontlineOwner != Side.Left)
        {
            return $"第二个单位推进后归属仍应为 Left，实际 {state.FrontlineOwner}";
        }

        if (OwnershipFired())
        {
            return "归属**没变**却又发了一次 `OnFrontlineOwnershipChange`"
                 + "（蓝图 si=352 `EnumCompareSide(old, FirstCard.side)` 相等 ⇒ 直接返回）";
        }

        // ---- ③ 杀掉"多出来的"那个：前线还有人 ⇒ 归属没变 ⇒ 不许发 ----
        var killerA = state.CreateWithId(ArtRange2, Side.Right, 42, CardLocation.BoardHqRight, 1);
        killerA.Attack = 9; killerA.Defense = 9; killerA.MaxDefense = 9; killerA.EnteredPlayOnTurn = -99;
        state.ActiveSide = Side.Right;
        if (!engine.Attack(killerA, second))
        {
            return "半场炮兵(range=2) 打不到前线单位（前置不成立）" + Dump(state, ("未实现", Unimpl(state)));
        }

        if (state.FrontlineOwner != Side.Left)
        {
            return $"前线还剩 {probe} 时归属应保持 Left，实际 {state.FrontlineOwner}";
        }

        if (OwnershipFired())
        {
            return "前线还剩单位（归属没变）却又发了一次 `OnFrontlineOwnershipChange`";
        }

        // ---- ④ 杀掉最后一个 ⇒ 归属 Left→NotAvailable ⇒ 必须发（本 bug 的主战场）----
        trace.Clear();
        var killerB = state.CreateWithId(ArtRange2, Side.Right, 43, CardLocation.BoardHqRight, 2);
        killerB.Attack = 9; killerB.Defense = 9; killerB.MaxDefense = 9; killerB.EnteredPlayOnTurn = -99;
        state.ActiveSide = Side.Right;
        if (!engine.Attack(killerB, probeCard))
        {
            return "半场炮兵(range=2) 打不到前线单位（前置不成立）" + Dump(state, ("未实现", Unimpl(state)));
        }

        if (probeCard.Location != CardLocation.Discard)
        {
            return $"{probe} 挨了 9 点伤害却没进弃牌堆（Location={probeCard.Location}）";
        }

        if (state.FrontlineOwner != Side.NotAvailable)
        {
            return $"**前线最后一个单位已死，归属却仍是 {state.FrontlineOwner}** —— 见上一条用例";
        }

        if (!OwnershipFired())
        {
            return "归属 Left→NotAvailable 真的变了（单位死在 `Destroy` 的 `State.Move` 里），"
                 + "`OnFrontlineOwnershipChange` 却没派发 —— 旧代码就是连这一步都没有"
                 + Dump(state, ("未实现", Unimpl(state)),
                        ("派发记录", trace.Count == 0 ? "（空）" : string.Join(" | ", trace.Take(8))));
        }

        return null;
    }

    private static string? FrontlineOwnershipTriggerReachesHand(CardDatabase db)
    {
        const string probe = "card_unit_panzer_35t_commander";
        if (db.Find(probe) is null) return $"卡库里缺 {probe}";

        var (engine, state) = EmptyBoard(db);
        state.SetKredits(Side.Left, 20);
        state.SetMaxKredits(Side.Left, 20);
        state.ActiveSide = Side.Left;

        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;

        var handProbe = state.CreateWithId(probe, Side.Left, 500, CardLocation.HandLeft, 0);
        var mover = state.CreateWithId(InfRange1, Side.Left, 501, CardLocation.BoardHqLeft, 1);
        mover.EnteredPlayOnTurn = -99;

        if (!engine.MoveUnit(mover, 0, out string reason))
        {
            return $"前线归属变化前置失败：{reason}";
        }

        if (handProbe.Location != CardLocation.BoardFrontline)
        {
            return $"手牌 Pz 未响应 OnFrontlineOwnershipChange：位置={handProbe.Location}，"
                 + Dump(state, ("派发记录", trace.Count == 0 ? "（空）" : string.Join(" | ", trace.Take(12))));
        }

        if (!trace.Any(x => x.StartsWith($"OnFrontlineOwnershipChange → {probe}#",
                                          StringComparison.Ordinal)))
        {
            return "手牌 Pz 已上前线但没有对应触发记录，事件载荷/诊断口径不完整";
        }

        return null;
    }

    /// <summary>
    /// 卡面自带关键字要真的加载进 `CardInstance.Keywords`。
    ///
    /// ⚠️ `cards.live.json` 里**只有 `hasGuard`**，`hasBlitz` 等全缺 ——
    /// 不额外加载的话所有卡的 `Keywords` 建出来都是空集（实测），
    /// 于是 205 张 Blitz、128 张 Guard 全部不生效。
    /// </summary>
    private static string? InnateKeywordsLoaded(CardDatabase db)
    {
        var (_, state) = EmptyBoard(db);
        int blitz = 0, guard = 0, checkedCards = 0;
        foreach (var def in db.All)
        {
            var c = state.Create(def.Name, Side.Left, CardLocation.DeckLeft,
                                 state.NextLocationNumber(Side.Left, CardLocation.DeckLeft));
            checkedCards++;
            if (c.Keywords.Contains(Keyword.Blitz, StringComparer.Ordinal))
            {
                blitz++;
            }

            if (c.Keywords.Contains(Keyword.Guard, StringComparer.Ordinal))
            {
                guard++;
            }
        }

        // 期望值来自 pak CDO（gen-card-keywords.py 的输出）：Blitz 205 / Guard 128。
        // 这里只做**下界**断言，避免表重新生成后数字微调就假失败。
        if (blitz < 200)
        {
            return $"带 Blitz 的卡只有 {blitz} 张（CDO 里是 205）—— 卡面关键字没加载全";
        }

        if (guard < 120)
        {
            return $"带 Guard 的卡只有 {guard} 张（CDO 里是 128）";
        }

        return null;
    }

    // ==================================================================
    //  跨前线射程（蓝图定案）
    // ==================================================================

    // 卡池实测射程（klink bot/docs/cards.live.json）：
    //   infantry 567 张 range=1（另有 1 张 range=2）
    //   tank     154 张 range=1
    //   artillery 60 张 range=2
    //   fighter  144 张 range=2
    //   bomber    97 张 range=2（另有 1 张 range=4）
    // 所以「只有炮兵/战斗机/轰炸机能跨前线」是 range≥2 的**数据后果**。
    private const string InfRange1  = "card_unit_16th_infantry_brigade";   // infantry range=1
    private const string TankRange1 = "card_unit_valentine_mk_iii";        // tank     range=1
    private const string ArtRange2  = "card_unit_25_pounder";              // artillery range=2
    private const string FtrRange2  = "card_unit_typhoon_mk_ib";           // fighter  range=2
    private const string BmbRange2  = "card_unit_hampden";                 // bomber   range=2

    /// <summary>摆一个「左方攻击者在 <paramref name="attackerLoc"/>、右方步兵在
    /// <paramref name="defenderLoc"/>」的干净局面。左右 HQ 各 20 防。</summary>
    private static (MatchEngine Engine, GameState State, CardInstance Attacker, CardInstance Defender)
        RangeSetup(CardDatabase db, string attackerCard, CardLocation attackerLoc, CardLocation defenderLoc)
    {
        var (engine, state) = EmptyBoard(db);
        state.SetKredits(Side.Left, 12);
        state.SetMaxKredits(Side.Left, 12);
        state.ActiveSide = Side.Left;

        var attacker = state.CreateWithId(attackerCard, Side.Left, 2, attackerLoc, 1);
        var defender = state.CreateWithId(InfRange1, Side.Right, 42, defenderLoc, 1);
        return (engine, state, attacker, defender);
    }

    /// <summary>
    /// 半场（<c>BoardHqLeft</c>，即 5）的 **infantry / tank（range=1）**：
    /// 既不能打对方 HQ，也不能打对方半场单位 —— 因为双方都不在前线，
    /// 距离 2 &gt; range 1。
    ///
    /// 出处：<c>cardsCheckFunctions::CanAttack</c> i=90-99
    /// （<c>not_enough_range</c>）；反编译产物 <c>out/xr-cardscheck.bpasm</c> 行 467-544。
    /// </summary>
    private static string? CrossFrontlineInfantryBlocked(CardDatabase db)
    {
        foreach (var (card, label) in new[] { (InfRange1, "infantry"), (TankRange1, "tank") })
        {
            if (db.Find(card) is null)
            {
                return $"卡库里缺 {card}";
            }

            if (db.Find(card)!.Range != 1)
            {
                return $"{card} 的 range 应为 1，实际 {db.Find(card)!.Range}（测试前提变了）";
            }

            // (a) 打对方 HQ
            var (e1, s1, a1, _) = RangeSetup(db, card, CardLocation.BoardHqLeft, CardLocation.BoardHqRight);
            int hqBefore = s1.HqDefense(Side.Right);
            int krBefore = s1.Kredits(Side.Left);
            if (e1.Attack(a1, s1.Hq(Side.Right)))
            {
                return $"{label}({card}) 在半场竟然打到了对方 HQ（蓝图 i=90-99 应拒）";
            }

            if (s1.HqDefense(Side.Right) != hqBefore || s1.Kredits(Side.Left) != krBefore)
            {
                return $"{label} 被拒的跨前线攻击改了状态：HQ {hqBefore}→{s1.HqDefense(Side.Right)}"
                     + $"，kredit {krBefore}→{s1.Kredits(Side.Left)}";
            }

            // (b) 打对方半场单位
            var (e2, s2, a2, d2) = RangeSetup(db, card, CardLocation.BoardHqLeft, CardLocation.BoardHqRight);
            if (e2.Attack(a2, d2))
            {
                return $"{label}({card}) 在半场竟然打到了对方半场单位 {d2.Name}（蓝图 i=90-99 应拒）";
            }

            // (c) LegalTargets 也不能把它列出来
            var targets = e2.LegalTargets(a2).Select(t => t.CardId).ToHashSet();
            if (targets.Contains(d2.CardId) || targets.Contains(s2.Hq(Side.Right).CardId))
            {
                return $"{label} 在半场时 LegalTargets 仍列出了打不到的目标："
                     + $"{string.Join(",", targets)}";
            }

            if (e1.OutOfRangeAttacksRejected != 1 || e2.OutOfRangeAttacksRejected != 1)
            {
                return $"{label} 每次越界攻击都应记一次射程拒绝，实际 HQ 那次 {e1.OutOfRangeAttacksRejected}、"
                     + $"半场单位那次 {e2.OutOfRangeAttacksRejected}";
            }
        }

        return null;
    }

    /// <summary>
    /// 半场（5）的 **artillery（range=2）**：能跨前线打对方 HQ 和对方半场单位。
    /// 出处同上（<c>attacker.range &lt; 2</c> 不成立 ⇒ 不拒绝）。
    /// </summary>
    private static string? CrossFrontlineArtilleryAllowed(CardDatabase db)
    {
        if (db.Find(ArtRange2) is null)
        {
            return $"卡库里缺 {ArtRange2}";
        }

        if (db.Find(ArtRange2)!.Range != 2)
        {
            return $"{ArtRange2} 的 range 应为 2，实际 {db.Find(ArtRange2)!.Range}";
        }

        // (a) 打对方 HQ
        var (e1, s1, a1, _) = RangeSetup(db, ArtRange2, CardLocation.BoardHqLeft, CardLocation.BoardHqRight);
        int hqBefore = s1.HqDefense(Side.Right);
        if (!e1.Attack(a1, s1.Hq(Side.Right)))
        {
            return $"半场炮兵(range=2) 应该能跨前线打对方 HQ，却被拒了"
                 + Dump(s1, ("未实现", Unimpl(s1)));
        }

        if (s1.HqDefense(Side.Right) != hqBefore - a1.Attack)
        {
            return $"炮兵打 HQ 的伤害不对：期望 {hqBefore - a1.Attack}，实际 {s1.HqDefense(Side.Right)}";
        }

        if (e1.OutOfRangeAttacksRejected != 0)
        {
            return $"炮兵不该被射程拒绝，实际拒了 {e1.OutOfRangeAttacksRejected} 次";
        }

        // (b) 打对方半场单位
        var (e2, s2, a2, d2) = RangeSetup(db, ArtRange2, CardLocation.BoardHqLeft, CardLocation.BoardHqRight);
        if (!e2.Attack(a2, d2))
        {
            return $"半场炮兵应该能跨前线打对方半场单位 {d2.Name}，却被拒了";
        }

        if (d2.Defense >= db.Find(InfRange1)!.Defense)
        {
            return $"炮兵打对方半场单位没有生效（防御仍是 {d2.Defense}）";
        }

        return null;
    }

    /// <summary>
    /// 半场（5）的 **fighter / bomber（range=2）**：能跨前线打对方 HQ。
    /// 出处同上。注意 <c>CanAttack</c> 里**没有</c> <c>IsFighter</c>，
    /// <c>IsArtillery</c>/<c>IsBomber</c> 只出现在 <c>isBeingGuarded</c> 分支
    /// （i=100-104），与射程无关 —— 所以判据是射程，不是类型。
    /// </summary>
    private static string? CrossFrontlineFighterBomberAllowed(CardDatabase db)
    {
        foreach (var (card, label) in new[] { (FtrRange2, "fighter"), (BmbRange2, "bomber") })
        {
            if (db.Find(card) is null)
            {
                return $"卡库里缺 {card}";
            }

            if (db.Find(card)!.Range != 2)
            {
                return $"{card} 的 range 应为 2，实际 {db.Find(card)!.Range}";
            }

            var (engine, state, attacker, _) =
                RangeSetup(db, card, CardLocation.BoardHqLeft, CardLocation.BoardHqRight);
            int hqBefore = state.HqDefense(Side.Right);
            if (!engine.Attack(attacker, state.Hq(Side.Right)))
            {
                return $"半场 {label}({card}, range=2) 应该能跨前线打对方 HQ，却被拒了"
                     + Dump(state, ("未实现", Unimpl(state)));
            }

            if (state.HqDefense(Side.Right) != hqBefore - attacker.Attack)
            {
                return $"{label} 打 HQ 的伤害不对：期望 {hqBefore - attacker.Attack}，"
                     + $"实际 {state.HqDefense(Side.Right)}";
            }

            if (engine.OutOfRangeAttacksRejected != 0)
            {
                return $"{label} 不该被射程拒绝，实际拒了 {engine.OutOfRangeAttacksRejected} 次";
            }
        }

        return null;
    }

    /// <summary>
    /// **任一方在前线（7）⇒ 距离 ≤ 1 ⇒ 任何射程都够得着。**
    ///
    /// 覆盖三种布局：
    /// (a) 攻击者在前线 → 能打对方 HQ / 对方半场单位
    /// (b) 攻击者在半场、目标在前线 → 能打（range=1 也行）
    /// 出处：<c>CanAttack</c> i=90/91 的两个 <c>location != 7</c> 用 AND 连起来 ——
    /// 只要有一个等于 7，整个条件就是假，射程检查根本不触发。
    /// </summary>
    private static string? FrontlineAlwaysInRange(CardDatabase db)
    {
        // (a) 前线的 infantry(range=1) 打对方 HQ
        var (e1, s1, a1, _) = RangeSetup(db, InfRange1, CardLocation.BoardFrontline, CardLocation.BoardHqRight);
        int hqBefore = s1.HqDefense(Side.Right);
        if (!e1.Attack(a1, s1.Hq(Side.Right)))
        {
            return "前线步兵(range=1) 应该能打对方 HQ，却被拒了"
                 + Dump(s1, ("未实现", Unimpl(s1)));
        }

        if (s1.HqDefense(Side.Right) != hqBefore - a1.Attack)
        {
            return $"前线步兵打 HQ 的伤害不对：期望 {hqBefore - a1.Attack}，实际 {s1.HqDefense(Side.Right)}";
        }

        // (b) 前线的 infantry 打对方半场单位
        var (e2, s2, a2, d2) = RangeSetup(db, InfRange1, CardLocation.BoardFrontline, CardLocation.BoardHqRight);
        if (!e2.Attack(a2, d2))
        {
            return "前线步兵应该能打对方半场单位，却被拒了";
        }

        // (c) 半场的 infantry(range=1) 打**对方前线**单位 —— 目标在前线，距离 1，够得着
        var (e3, s3, a3, d3) = RangeSetup(db, InfRange1, CardLocation.BoardHqLeft, CardLocation.BoardFrontline);
        if (!e3.Attack(a3, d3))
        {
            return "半场步兵应该能打对方**前线**单位（距离 1），却被拒了";
        }

        // (d) 上面三种都不该记射程拒绝
        foreach (var (e, label) in new[] { (e1, "a"), (e2, "b"), (e3, "c") })
        {
            if (e.OutOfRangeAttacksRejected != 0)
            {
                return $"布局 {label} 不该被射程拒绝，实际拒了 {e.OutOfRangeAttacksRejected} 次";
            }
        }

        return null;
    }

    /// <summary>
    /// <see cref="MatchEngine.CanReachAcrossFrontline"/> 的真值表 ——
    /// 把「距离」和「射程」两个维度都钉死，防止实现被放宽或收窄。
    ///
    /// 距离：支援线↔支援线 = 2，支援线↔前线 = 1，前线↔任意 = 1。
    /// 规则：<c>range ≥ 距离</c>。等价于蓝图那条
    /// <c>attacker.location != 7 &amp;&amp; defender.location != 7 &amp;&amp; attacker.range &lt; 2 ⇒ 拒</c>。
    /// </summary>
    private static string? CrossFrontlineTruthTable(CardDatabase db)
    {
        var (_, state) = EmptyBoard(db);
        var left1 = state.CreateWithId(InfRange1, Side.Left, 2, CardLocation.HandLeft, 0);
        var left2 = state.CreateWithId(ArtRange2, Side.Left, 3, CardLocation.HandLeft, 0);
        var right = state.CreateWithId(InfRange1, Side.Right, 42, CardLocation.HandRight, 0);

        // (攻击者位置, 目标位置, 攻击者, 期望)
        var table = new (CardLocation A, CardLocation D, CardInstance Card, bool Expect, string Why)[]
        {
            (CardLocation.BoardHqLeft, CardLocation.BoardHqRight, left1, false, "半场→半场 距离2，range1 不够"),
            (CardLocation.BoardHqLeft, CardLocation.BoardHqRight, left2, true,  "半场→半场 距离2，range2 够"),
            (CardLocation.BoardHqLeft, CardLocation.BoardFrontline, left1, true, "半场→前线 距离1，range1 够"),
            (CardLocation.BoardHqLeft, CardLocation.BoardFrontline, left2, true, "半场→前线 距离1，range2 够"),
            (CardLocation.BoardFrontline, CardLocation.BoardHqRight, left1, true, "前线→半场 距离1，range1 够"),
            (CardLocation.BoardFrontline, CardLocation.BoardHqRight, left2, true, "前线→半场 距离1，range2 够"),
            (CardLocation.BoardFrontline, CardLocation.BoardFrontline, left1, true, "前线→前线 距离1，range1 够"),
        };

        foreach (var (a, d, card, expect, why) in table)
        {
            card.Location = a;
            right.Location = d;
            bool got = MatchEngine.CanReachAcrossFrontline(card, right);
            if (got != expect)
            {
                return $"{why}：{a}→{d}（range={card.Definition.Range}）期望 {expect}，实际 {got}";
            }
        }

        // 射程 0（非单位卡，比如 order/location）也必须按「不够」处理
        var order = state.CreateWithId("card_event_merchant_navy", Side.Left, 4, CardLocation.HandLeft, 0);
        order.Location = CardLocation.BoardHqLeft;
        right.Location = CardLocation.BoardHqRight;
        if (MatchEngine.CanReachAcrossFrontline(order, right))
        {
            return $"range=0 的卡不该够得着（实际 range={order.Definition.Range}）";
        }

        return null;
    }

    /// <summary>
    /// `CanAttack` 没有“前线嘲讽”分支；敌方前线存在时，range=2 的攻击者
    /// 仍可选择敌方半场/HQ，range=1 则只会被射程门过滤掉后方目标。
    /// </summary>
    private static string? FrontlineDoesNotBlockRangedTargets(CardDatabase db)
    {
        var (rangedEngine, rangedState, ranged, rangedFront) =
            RangeSetup(db, ArtRange2, CardLocation.BoardHqLeft, CardLocation.BoardFrontline);
        var rangedBack = rangedState.CreateWithId(InfRange1, Side.Right, 43, CardLocation.BoardHqRight, 1);
        var rangedTargets = rangedEngine.LegalTargets(ranged).Select(c => c.CardId).ToHashSet();
        if (!rangedTargets.Contains(rangedFront.CardId) || !rangedTargets.Contains(rangedBack.CardId)
            || !rangedTargets.Contains(rangedState.Hq(Side.Right).CardId))
        {
            return "敌方前线存在时，range=2 攻击者应仍能列出前线、后方单位和 HQ";
        }

        var (shortEngine, shortState, shortRangeAttacker, shortFront) =
            RangeSetup(db, InfRange1, CardLocation.BoardHqLeft, CardLocation.BoardFrontline);
        var shortBack = shortState.CreateWithId(InfRange1, Side.Right, 43, CardLocation.BoardHqRight, 1);
        var shortTargets = shortEngine.LegalTargets(shortRangeAttacker).Select(c => c.CardId).ToHashSet();
        if (!shortTargets.Contains(shortFront.CardId)
            || shortTargets.Contains(shortBack.CardId)
            || shortTargets.Contains(shortState.Hq(Side.Right).CardId))
        {
            return "敌方前线存在时，range=1 攻击者只能保留前线目标";
        }

        return null;
    }

    // ==================================================================
    //  P0 第 1 族：事件层派发的自测（2026-09-27）
    // ==================================================================

    /// <summary>
    /// 建一个空局 + 放一张探针卡 + 记下 TriggerTrace。
    /// <paramref name="fire"/> 返回"应当收到**自己那一路**事件"的那张卡
    /// （多数情况就是探针本身；`OnCreateCard` / `OnCardSpawnedInHand` 是新建出来的那张）。
    /// </summary>
    private static (List<string> Trace, CardInstance Card, string? Error) Probe(
        CardDatabase db, string probeName, CardLocation where,
        Func<MatchEngine, GameState, CardInstance, CardInstance> fire)
    {
        if (db.Find(probeName) is null)
        {
            return (new List<string>(), null!, $"卡库里缺 {probeName}");
        }

        var (engine, state) = EmptyBoard(db);
        state.ActiveSide = Side.Left;
        state.SetKredits(Side.Left, 12);
        state.SetMaxKredits(Side.Left, 12);
        var probe = state.CreateWithId(probeName, Side.Left, 20, where, 1);
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        try
        {
            var subject = fire(engine, state, probe);
            return (trace, subject, null);
        }
        catch (Exception ex)
        {
            return (trace, probe, $"{ex.GetType().Name}: {ex.Message}");
        }
    }

    /// <summary>TriggerTrace 里有没有「事件名 → 卡名#ID」这一条。</summary>
    private static bool Reached(List<string> trace, string ev, CardInstance card)
        => trace.Any(t => t.StartsWith($"{ev} → {card.Name}#{card.CardId}", StringComparison.Ordinal));

    private static string? EventLayerSelfEvents(CardDatabase db)
    {
        // (事件, 探针卡, 探针放在哪, 怎么触发)
        var table = new (string Event, string Card, CardLocation Where,
                         Func<MatchEngine, GameState, CardInstance, CardInstance> Fire)[]
        {
            ("OnCardReset", "card_unit_raaf_walrus", CardLocation.BoardHqLeft,
                (e, s, p) => { e.Api.ResetCardInBattle(p); return p; }),
            ("OnSuppressed", "card_unit_raaf_walrus", CardLocation.BoardHqLeft,
                (e, s, p) => { e.Api.SuppressUnit(p); return p; }),
            ("OnBecomingVeteran", "card_unit_7th_brigade_anzac", CardLocation.BoardHqLeft,
                (e, s, p) => { e.Api.MakeVeteran(p); return p; }),
            ("OnCardLocationMoved", "card_unit_spitfire_mk_ii", CardLocation.BoardHqLeft,
                (e, s, p) => { s.Move(p, CardLocation.BoardFrontline, 0); return p; }),
            ("OnAfterLeaveBoard", "card_unit_royal_west_kents", CardLocation.BoardHqLeft,
                (e, s, p) => { e.Destroy(p); return p; }),
            ("OnAfterGainDefense", "card_unit_kyushu_j7w3", CardLocation.BoardHqLeft,
                (e, s, p) => { e.Api.ChangeDefense(p, 1, null); return p; }),
            ("OnFullyRepaired", "card_unit_kyushu_j7w3", CardLocation.BoardHqLeft,
                (e, s, p) => { p.Defense = Math.Max(1, p.MaxDefense - 1); e.Api.HealCard(p, 9); return p; }),
            ("OnBeforeStartOfTurn", "card_unit_cedar_division", CardLocation.BoardHqLeft,
                (e, s, p) => { e.StartTurn(Side.Left, draw: false); return p; }),
            ("OnCardDrawnFromDeck", "card_unit_13e_dragons", CardLocation.DeckLeft,
                (e, s, p) => e.DrawCard(Side.Left) ?? p),
            ("OnCreateCard", "card_unit_185th_folgore_cov", CardLocation.NotAvailable,
                (e, s, p) => s.Create("card_unit_185th_folgore_cov", Side.Left, CardLocation.DeckLeft, 0)),
            ("OnOtherCardCreatedAlterCard", "card_unit_67th_baranovichi", CardLocation.BoardHqLeft,
                (e, s, p) => { s.Create("card_unit_185th_folgore_cov", Side.Left, CardLocation.DeckLeft, 0); return p; }),
            ("OnCardSpawnedInHand", "card_unit_13e_dragons", CardLocation.NotAvailable,
                (e, s, p) => e.Api.SpawnCardInHand(Side.Left, "card_unit_13e_dragons")),
        };

        foreach (var (ev, card, where, fire) in table)
        {
            var (trace, subject, err) = Probe(db, card, where, fire);
            if (err is not null)
            {
                return $"{ev}（探针 {card}）出错了：{err}";
            }

            if (!Reached(trace, ev, subject))
            {
                string diag = "";
                if (KismetLibrary.Default is { } lib)
                {
                    diag = $"；FindProgram({card}, {ev}) = {(lib.FindProgram(card, ev) is null ? "null" : "有")}";
                }

                return $"{ev} 没有派发到主体 {subject.Name}#{subject.CardId}（探针 {card}）；"
                     + $"主体位置={subject.Location}{diag}"
                     + $"\n       实际派发记录：{string.Join(" | ", trace.Take(6))}";
            }
        }

        return null;
    }

    private static string? EventLayerOtherEvents(CardDatabase db)
    {
        const string victim = "card_unit_arado_ar_196";
        var table = new (string Event, string Card, Func<MatchEngine, GameState, CardInstance, CardInstance> Fire)[]
        {
            ("OnOtherCardReset", "card_unit_coastwatchers",
                (e, s, p) => { e.Api.ResetCardInBattle(Plain(s, victim, 60)); return p; }),
            ("OnOtherCardSuppressed", "card_unit_kings_own_scottish",
                (e, s, p) => { e.Api.SuppressUnit(Plain(s, victim, 61)); return p; }),
            ("OnAfterOtherCardSuppressed", "card_unit_adler_command_vehicle",
                (e, s, p) => { e.Api.SuppressUnit(Plain(s, victim, 62)); return p; }),
            ("OnOtherCardBecomingVeteran", "card_unit_6th_brigade_nz",
                (e, s, p) => { e.Api.MakeVeteran(Plain(s, victim, 63)); return p; }),
            ("OnOtherCardAbilitiesChanged", "card_unit_royal_west_kents",
                (e, s, p) => { e.Api.GiveKeyword(Plain(s, victim, 64), Keyword.Blitz); return p; }),
            ("OnOtherCardLoseSmokescreen", "card_unit_hirosaki_regiment",
                (e, s, p) =>
                {
                    var changed = s.CreateWithId(victim, Side.Left, 73, CardLocation.BoardHqLeft, 2);
                    e.Api.GiveKeyword(changed, Keyword.Smokescreen);
                    e.Api.RemoveKeyword(changed, Keyword.Smokescreen);
                    return p;
                }),
            ("OnOtherCardKreditCostChanged", "card_unit_the_silent_seventh",
                (e, s, p) => { e.Api.ChangeKreditCost(Plain(s, victim, 66), 1, p); return p; }),
            ("OnOtherCardDealDamage", "card_unit_blenheim_mk_i",
                (e, s, p) =>
                {
                    var src = Plain(s, victim, 65);
                    var dst = Plain(s, victim, 66);
                    dst.Defense = 20;
                    e.Api.DealDamage(dst, 1, src);
                    return p;
                }),
            ("OnOtherCardLocationMoved", "card_unit_spitfire_mk_ii",
                (e, s, p) => { s.Move(Plain(s, victim, 67), CardLocation.BoardFrontline, 0); return p; }),
            ("OnOtherCardMoveFromFrontline", "card_unit_raaf_walrus",
                (e, s, p) => { var moved = Plain(s, victim, 68); s.Move(moved, CardLocation.BoardFrontline, 0); s.Move(moved, CardLocation.BoardHqLeft, 0); return p; }),
            ("OnDeckShuffled", "card_unit_110e_regiment_motorize",
                (e, s, p) =>
                {
                    // Plain creates a right-owned unit; merely moving it to
                    // DeckLeft does not put it in the left owner's deck model.
                    s.CreateWithId(victim, Side.Left, 72, CardLocation.DeckLeft, 0);
                    e.Api.InvokeByName("ShuffleDeckBySide", p,
                        new object?[] { (int)Side.Left, false, 0, null },
                        new EffectContext { Engine = e, State = s, Self = p, Controller = Side.Left }, out _);
                    return p;
                }),
            ("OnOtherCardDestroyed", "card_unit_hudson",
                (e, s, p) => { e.Destroy(Plain(s, victim, 69)); return p; }),
            ("OnBeforeOtherCardDestroyed", "card_unit_marder_iii_h",
                (e, s, p) => { e.Destroy(Plain(s, victim, 70)); return p; }),
            ("OnOtherCardDiscarded", "card_unit_7th_brigade_anzac",
                (e, s, p) => { e.Api.DiscardCard(s.CreateWithId(victim, Side.Right, 71, CardLocation.HandRight, 0)); return p; }),
            ("OnAfterExtraKreditSlotGain", "card_unit_144th_infantry_regiment",
                (e, s, p) => { e.Api.GainKreditSlot(Side.Left, 1); return p; }),
            ("OnBeforeOtherCardPlayedFromHand", "card_unit_flaming_matilda_anzac",
                (e, s, p) =>
                {
                    var c = s.CreateWithId(victim, Side.Left, 71, CardLocation.HandLeft, 2);
                    if (!e.PlayCard(c))
                    {
                        throw new InvalidOperationException($"打不出 {victim}（测试布景问题）");
                    }

                    return p;
                }),
        };

        foreach (var (ev, card, fire) in table)
        {
            var (trace, subject, err) = Probe(db, card, CardLocation.BoardHqLeft, fire);
            if (err is not null)
            {
                return $"{ev}（探针 {card}）出错了：{err}";
            }

            if (!Reached(trace, ev, subject))
            {
                return $"{ev} 没有广播到旁观探针 {subject.Name}#{subject.CardId}"
                     + $"\n       实际派发记录：{string.Join(" | ", trace.Take(6))}";
            }
        }

        return null;

        // 敌方一张普通单位（没有订阅任何东西），当"事件的受害者"
        static CardInstance Plain(GameState s, string name, int id)
            => s.CreateWithId(name, Side.Right, id, CardLocation.BoardHqRight, id - 59);
    }

    /// <summary>
    /// `OnOtherCardReset` 的两个槽位不能靠事件主体兜底：
    /// `cardReset` 是被重置的卡对象，`resetCardID` 是同一张卡的 ID。
    ///
    /// Coastwatchers 的真实蓝图会读取 `resetCardID`，通过 `GetCardFromID`
    /// 找回重置的手牌天气牌，再把它的费用降低 1。若载荷缺失，VM 会把
    /// 事件主体/当前接收者当成 ID，真实效果就会静默跳过。
    /// </summary>
    private static string? ResetEventCarriesPayload(CardDatabase db)
    {
        const string watcherName = "card_unit_coastwatchers";
        const string weatherName = "card_event_rain2_deluge";
        if (db.Find(watcherName) is null || db.Find(weatherName) is null)
        {
            return $"卡库里缺 {watcherName} 或 {weatherName}";
        }

        var (engine, state) = EmptyBoard(db);
        state.ActiveSide = Side.Left;
        var watcher = state.CreateWithId(watcherName, Side.Left, 20,
            CardLocation.BoardHqLeft, 1);
        var weather = state.CreateWithId(weatherName, Side.Left, 60,
            CardLocation.HandLeft, 1);
        int before = weather.EffectiveKreditCost;
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;

        try
        {
            engine.Api.ResetCardInBattle(weather);
        }
        catch (Exception ex)
        {
            return $"ResetCardInBattle 抛出 {ex.GetType().Name}: {ex.Message}";
        }

        string prefix = $"OnOtherCardReset → {watcher.Name}#{watcher.CardId}";
        if (!trace.Any(t => t.StartsWith(prefix, StringComparison.Ordinal)
                         && t.Contains($"eventCard={weather.Name}#{weather.CardId}", StringComparison.Ordinal)))
        {
            return "OnOtherCardReset 没有把被重置的天气牌作为事件主体传给 Coastwatchers";
        }

        int after = weather.EffectiveKreditCost;
        if (after != Math.Max(CardInstance.MinKreditCost, before - 1))
        {
            return $"Coastwatchers 没有按 resetCardID 给天气牌减费：重置前={before}，重置后={after}";
        }

        return null;
    }

    // Synthetic own callbacks detect execution past the Blueprint victory return.
    private static string? BatchHqVictoryBoundary(CardDatabase db)
    {
        const string name = "card_unit_51e_regiment";
        string[] hooks = { "OnAfterLeaveBoard", "OnDestroyed" };
        var library = KismetLibrary.Default!;
        if (library.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || hooks.Any(h => library.FindProgram(name, h) is not null)) return "无法安全安装 HQ 胜负边界探针";
        var cache = (Dictionary<string, Dictionary<string, KismetProgram>>)typeof(KismetLibrary)
            .GetField("_localCache", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!
            .GetValue(library)!;
        cache.TryGetValue(name, out var oldCache);
        var saved = hooks.ToDictionary(h => h, h => oldCache?.GetValueOrDefault(h));
        foreach (string hook in hooks) oldCache?.Remove(hook);
        try
        {
            for (int i = 0; i < hooks.Length; i++)
                locals.Add(hooks[i], new[] {
                    new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Bool = true }, null, -1,
                        i == 0 ? "_auditHqAfter" : "_auditHqDeath", null) { DestinationScope = "instance" },
                    new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null)
                });
            var dispatch = typeof(CardApi).GetMethod("DealDamageMultiple",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!;
            var failures = new List<string>();
            foreach (Side client in new[] { Side.Left, Side.Right })
            foreach (Side active in new[] { Side.Left, Side.Right })
            foreach (bool reverse in new[] { false, true })
            foreach (bool finishedBefore in new[] { false, true })
            foreach (int mode in Enumerable.Range(0, 6))
            {
                var (engine, state) = EmptyBoard(db); state.SetupSidesInBattle(client); state.ActiveSide = active;
                var clientHq = state.Hq(client); var opponentHq = state.Hq(client.Opposite());
                clientHq.Keywords.Clear(); opponentHq.Keywords.Clear();
                clientHq.Defense = mode is 1 or 3 ? 1 : 8;
                opponentHq.Defense = mode is 2 or 3 ? 1 : 8;
                if (mode == 4) clientHq.Location = CardLocation.Discard;
                if (mode == 5) opponentHq.Location = CardLocation.Discard;
                var unit = state.CreateWithId(name, client, 60, client.HqOf(), 10);
                unit.Definition = new CardDefinition { Name = name, Type = "infantry" };
                unit.Keywords.Clear(); unit.Keywords.Add(Keyword.Destruction); unit.Defense = 1;
                var survivor = state.CreateWithId(name, client, 70, client.HqOf(), 20);
                survivor.Definition = new CardDefinition { Name = name, Type = "infantry" };
                survivor.Keywords.Clear(); survivor.Keywords.Add(Keyword.Mobilize); survivor.IsBeingGuarded = true; survivor.Defense = 9;
                var source = state.CreateWithId("card_event_honorifics", client.Opposite(), 90, CardLocation.Discard, 0);
                source.Definition = new CardDefinition { Name = source.Name, Type = "order" }; source.Keywords.Clear();
                var targets = new List<CardInstance>();
                if (mode < 4) { targets.Add(state.Hq(Side.Left)); targets.Add(state.Hq(Side.Right)); }
                targets.Add(unit); targets.Add(survivor); if (reverse) targets.Reverse();
                if (finishedBefore) state.Finish(client, "preexisting");
                var ids = (IReadOnlyList<int>)dispatch.Invoke(engine.Api, [targets, 1, source])!;
                bool victory = mode != 0;
                Side winner = finishedBefore ? client : !victory ? Side.NotAvailable
                    : mode is 1 or 3 or 4 ? client.Opposite() : client;
                string reason = finishedBefore ? "preexisting" : victory ? "Victory_DestroyHQ" : "";
                int[] expectedIds = victory ? Array.Empty<int>() : new[] { 60 };
                CardLocation clientPlace = mode is 1 or 3 or 4 ? CardLocation.Discard : client.HqOf();
                CardLocation opponentPlace = mode is 2 or 3 or 5 ? CardLocation.Discard : client.Opposite().HqOf();
                if (!ids.SequenceEqual(expectedIds) || !state.DestroyedCardIdsAll.SequenceEqual(expectedIds)
                    || state.IsFinished != (finishedBefore || victory) || state.Winner != winner || state.WinnerReason != reason
                    || clientHq.Location != clientPlace || opponentHq.Location != opponentPlace || unit.Location != CardLocation.Discard
                    || unit.BlueprintVariables.ContainsKey("_auditHqAfter") != !victory
                    || unit.BlueprintVariables.ContainsKey("_auditHqDeath") != !victory
                    || survivor.LocationNumber != (victory ? 20 : 1) || survivor.IsBeingGuarded != victory
                    || survivor.Keywords.Contains(Keyword.Mobilize) != victory || survivor.Defense != 8
                    || clientHq.Defense != (mode is 1 or 3 ? 0 : mode < 4 ? 7 : 8)
                    || opponentHq.Defense != (mode is 2 or 3 ? 0 : mode < 4 ? 7 : 8)
                    || state.ActionLog.SelectMany(a => a.SubActions).Count(a => a.Name == "ZActionDamageMultipleCards") != 1)
                    failures.Add($"{client}/{active}/{reverse}/{finishedBefore}/{mode}: winner={state.Winner}/{state.WinnerReason}, hq={clientHq.Location}/{opponentHq.Location}, ids={string.Join(',', ids)}, history={string.Join(',', state.DestroyedCardIdsAll)}, after={unit.BlueprintVariables.ContainsKey("_auditHqAfter")}, death={unit.BlueprintVariables.ContainsKey("_auditHqDeath")}, survivor={survivor.LocationNumber}/{survivor.IsBeingGuarded}/{survivor.Keywords.Contains(Keyword.Mobilize)}");
            }
            return failures.Count == 0 ? null : $"{failures.Count}/96 场景失败：" + string.Join(" | ", failures.Take(8));
        }
        finally
        {
            foreach (string hook in hooks)
            {
                locals.Remove(hook);
                if (cache.TryGetValue(name, out var perCard))
                {
                    perCard.Remove(hook);
                    if (saved[hook] is { } old) perCard[hook] = old;
                }
            }
            if (oldCache is null && cache.TryGetValue(name, out var added) && added.Count == 0) cache.Remove(name);
        }
    }

    // Test common batch phases with controlled callbacks, without real card semantics.
    private static string? MultiDamagePhaseBoundaries(CardDatabase db)
    {
        const string name = "card_event_honorifics";
        string[] hooks = { "OnCardDealDamage", "OnLeaveBoardOrOwner", "OnAfterLeaveBoard" };
        var library = KismetLibrary.Default!;
        if (library.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || hooks.Any(h => library.FindProgram(name, h) is not null)) return "无法安全安装多目标伤害边界探针";
        var cache = (Dictionary<string, Dictionary<string, KismetProgram>>)typeof(KismetLibrary)
            .GetField("_localCache", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!
            .GetValue(library)!;
        cache.TryGetValue(name, out var oldCache);
        var saved = hooks.ToDictionary(h => h, h => oldCache?.GetValueOrDefault(h));
        foreach (string hook in hooks) oldCache?.Remove(hook);
        try
        {
            for (int kind = 1; kind <= 3; kind++)
            {
                var steps = new List<KismetStep>();
                void Set(string key, KismetExpr value) => steps.Add(new KismetStep(steps.Count, "set", null,
                    Array.Empty<KismetExpr>(), Array.Empty<int>(), value, null, -1, key, null) { DestinationScope = "instance" });
                Set("_auditMultiSerial", new KismetExpr { Math = "Add_IntInt", Args = new[] {
                    new KismetExpr { Var = "_auditMultiSerial", Scope = "instance" }, new KismetExpr { Int = 1 } } });
                Set("_auditMultiStage", new KismetExpr { Int = kind });
                Set("_auditMultiTarget", new KismetExpr { Var = "toCard", Scope = "local" });
                steps.Add(new KismetStep(steps.Count, "call", "SpawnCardInDeckBySide", new[] {
                    new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                    new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
                }, Array.Empty<int>(), null, null, -1, null, null));
                steps.Add(new KismetStep(steps.Count, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null));
                locals.Add(hooks[kind - 1], steps);
            }
            var failures = new List<string>();
            var dispatch = typeof(CardApi).GetMethod("DealDamageMultiple",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!;
            IReadOnlyList<int> Run(MatchEngine engine, IReadOnlyList<CardInstance> cards, int amount, CardInstance source)
                => (IReadOnlyList<int>)dispatch.Invoke(engine.Api, [cards, amount, source])!;
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int mode in Enumerable.Range(0, 5))
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, side, 50, CardLocation.Discard, 0);
                source.Definition = new CardDefinition { Name = name, Type = "order" }; source.Keywords.Clear();
                var cards = new List<CardInstance>();
                if (mode != 0)
                    foreach (int id in new[] { 60, 61 })
                    {
                        var card = state.CreateWithId(name, side.Opposite(), id, side.Opposite().HqOf(), id);
                        card.Definition = new CardDefinition { Name = name, Type = "infantry" };
                        card.Keywords.Clear(); card.Defense = 9;
                        if (mode == 2 || mode == 4 && id == 60) card.Keywords.Add(Keyword.Immune);
                        cards.Add(card);
                    }
                state.FrontlineOwner = side; // Isolate whether this helper requests an unrelated refresh.
                var ids = Run(engine, cards, mode == 1 ? 0 : 1, source);
                int notices = state.ActionLog.SelectMany(a => a.SubActions).Count(a => a.Name == "ZActionDamageMultipleCards");
                if (ids.Count != 0 || notices != (mode >= 3 ? 1 : 0) || state.FrontlineOwner != side
                    || state.DestroyedCardIdsAll.Count != 0 || cards.Any(c => c.Defense != (mode >= 3 && !c.Keywords.Contains(Keyword.Immune) ? 8 : 9)))
                    failures.Add($"{side}/zero-mode={mode}: 通知={notices}, 前线={state.FrontlineOwner}, 销毁={string.Join(',', ids)}");
            }
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool frontline in new[] { false, true })
            foreach (int phase in new[] { 1, 2 }) // first deal callback / first leave callback
            foreach (int mask in Enumerable.Range(0, 4))
            {
                var (engine, state) = EmptyBoard(db);
                CardLocation zone = frontline ? CardLocation.BoardFrontline : side.HqOf();
                var source = state.CreateWithId(name, side, 50, CardLocation.Discard, 0);
                source.Definition = new CardDefinition { Name = name, Type = "order" }; source.Keywords.Clear();
                var first = state.CreateWithId(name, side, 60, zone, 10);
                var last = state.CreateWithId(name, side.Opposite(), 61, side.Opposite().HqOf(), 10);
                foreach (var card in new[] { first, last })
                {
                    card.Definition = new CardDefinition { Name = name, Type = "infantry" };
                    card.Keywords.Clear(); card.Defense = 1;
                }
                var survivor = state.CreateWithId(PlainUnit, side, 70, zone, 20);
                survivor.Definition = new CardDefinition { Name = PlainUnit, Type = "infantry" };
                survivor.Keywords.Clear(); survivor.IsBeingGuarded = true;
                state.FrontlineOwner = side;
                var events = new List<string>(); var serial = new Dictionary<int, int>(); bool mutated = false;
                var prior = state.CardCreated;
                state.CardCreated = made => {
                    prior?.Invoke(made);
                    if (made.Name != "card_unit_routed_troops") return;
                    var current = new[] { source, first, last }.Single(c => Convert.ToInt32(c.BlueprintVariables.GetValueOrDefault("_auditMultiSerial")) > serial.GetValueOrDefault(c.CardId));
                    serial[current.CardId] = Convert.ToInt32(current.BlueprintVariables["_auditMultiSerial"]);
                    int stage = Convert.ToInt32(current.BlueprintVariables["_auditMultiStage"]);
                    var target = current.BlueprintVariables.GetValueOrDefault("_auditMultiTarget") as CardInstance;
                    events.Add($"{stage}:{(stage == 1 ? target?.CardId : current.CardId)}");
                    if (!mutated && stage == phase)
                    {
                        mutated = true;
                        if ((mask & 1) != 0) first.Location = CardLocation.Discard;
                        if ((mask & 2) != 0) last.Location = CardLocation.Discard;
                    }
                };
                var ids = Run(engine, new[] { first, last }, 1, source);
                var wantedIds = new[] { 60, 61 }.Where(id => (mask & (id == 60 ? 1 : 2)) == 0).ToArray();
                var wantedEvents = new List<string> { "1:60", "1:61" };
                if (phase == 2 || (mask & 1) == 0) wantedEvents.Add("2:60");
                if ((mask & 2) == 0) wantedEvents.Add("2:61");
                wantedEvents.AddRange(wantedIds.Select(id => $"3:{id}"));
                bool refreshed = wantedIds.Length > 0;
                if (!ids.SequenceEqual(wantedIds) || !state.DestroyedCardIdsAll.SequenceEqual(wantedIds)
                    || !events.SequenceEqual(wantedEvents) || first.Location != CardLocation.Discard || last.Location != CardLocation.Discard
                    || survivor.LocationNumber != (refreshed ? frontline ? 0 : 1 : 20) || survivor.IsBeingGuarded != !refreshed
                    || state.FrontlineOwner != side)
                    failures.Add($"{side}/{frontline}/{phase}/{mask}: ids={string.Join(',', ids)}, history={string.Join(',', state.DestroyedCardIdsAll)}, events={string.Join(',', events)}, survivor={survivor.LocationNumber}/{survivor.IsBeingGuarded}, frontline={state.FrontlineOwner}");
            }
            return failures.Count == 0 ? null : $"{failures.Count}/42 场景失败：" + string.Join(" | ", failures.Take(8));
        }
        finally
        {
            foreach (string hook in hooks)
            {
                locals.Remove(hook);
                if (cache.TryGetValue(name, out var perCard))
                {
                    perCard.Remove(hook);
                    if (saved[hook] is { } old) perCard[hook] = old;
                }
            }
            if (oldCache is null && cache.TryGetValue(name, out var added) && added.Count == 0) cache.Remove(name);
        }
    }

    // Synthetic receive/deal hooks exercise the common ApplyDamageToCard path only.
    private static string? EffectDamagePositiveBranch(CardDatabase db)
    {
        const string name = "card_event_honorifics";
        string[] hooks = { "OnReceiveDamage", "OnCardDealDamage" };
        var library = KismetLibrary.Default!;
        if (library.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || hooks.Any(h => library.FindProgram(name, h) is not null)) return "无法安全安装效果伤害落地探针";
        var cache = (Dictionary<string, Dictionary<string, KismetProgram>>)typeof(KismetLibrary)
            .GetField("_localCache", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!
            .GetValue(library)!;
        cache.TryGetValue(name, out var oldCache);
        var saved = hooks.ToDictionary(h => h, h => oldCache?.GetValueOrDefault(h));
        foreach (string hook in hooks) oldCache?.Remove(hook);
        try
        {
            for (int kind = 1; kind <= 2; kind++)
            {
                var steps = new List<KismetStep>();
                void Set(string key, KismetExpr value) => steps.Add(new KismetStep(steps.Count, "set", null,
                    Array.Empty<KismetExpr>(), Array.Empty<int>(), value, null, -1, key, null) { DestinationScope = "instance" });
                Set("_auditEffectSerial", new KismetExpr { Math = "Add_IntInt", Args = new[] {
                    new KismetExpr { Var = "_auditEffectSerial", Scope = "instance" }, new KismetExpr { Int = 1 } } });
                Set("_auditEffectKind", new KismetExpr { Int = kind });
                foreach (string key in new[] { "toCard", "Damage", "isCombatDamage", "CounterDamage" })
                    Set("_auditEffect_" + key, new KismetExpr { Var = key, Scope = "local" });
                steps.Add(new KismetStep(steps.Count, "call", "SpawnCardInDeckBySide", new[] {
                    new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                    new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
                }, Array.Empty<int>(), null, null, -1, null, null));
                steps.Add(new KismetStep(steps.Count, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null));
                locals.Add(hooks[kind - 1], steps);
            }
            var cases = new List<(Side Side, int Incoming, int ReceiveDefense, bool Unit, bool Heal)>();
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int incoming in new[] { -3, 0, 4 })
            foreach (int defense in new[] { -2, 0, 2, 7 })
            foreach (bool unit in new[] { false, true }) cases.Add((side, incoming, defense, unit, false));
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int defense in new[] { -2, 0, 2 }) cases.Add((side, 4, defense, false, true));
            var dispatch = typeof(CardApi).GetMethod("ApplyCalculatedDamage",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!;
            var failures = new List<string>();
            foreach (var row in cases)
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, row.Side, 50, CardLocation.Discard, 0);
                source.Definition = new CardDefinition { Name = name, Type = row.Unit ? "infantry" : "order" };
                source.Keywords.Clear(); source.CustomAbility = "excess";
                var victim = state.CreateWithId(name, row.Side.Opposite(), 60, row.Side.Opposite().HqOf(), 1);
                victim.Definition = new CardDefinition { Name = name, Type = "infantry" };
                victim.Keywords.Clear(); victim.Keywords.Add(Keyword.Mobilize); victim.Defense = 9;
                var hq = state.Hq(victim.Owner); hq.Defense = 20;
                bool positive = row.Incoming > 0;
                int spilled = positive && !row.Unit && row.Incoming > row.ReceiveDefense ? row.Incoming - row.ReceiveDefense : 0;
                int finalDamage = spilled > 0 ? row.ReceiveDefense : positive ? row.Incoming : 0;
                int rawDefense = positive ? row.ReceiveDefense - finalDamage : 9;
                bool destroyed = positive && rawDefense <= 0;
                int finalDefense = row.Heal && spilled > 0 ? 9 : rawDefense;
                var events = new List<string>(); var serial = new Dictionary<int, int>(); string? payloadError = null;
                var prior = state.CardCreated;
                state.CardCreated = made => {
                    prior?.Invoke(made);
                    if (made.Name != "card_unit_routed_troops") return;
                    var current = new[] { source, victim }.Single(c => Convert.ToInt32(c.BlueprintVariables.GetValueOrDefault("_auditEffectSerial")) > serial.GetValueOrDefault(c.CardId));
                    serial[current.CardId] = Convert.ToInt32(current.BlueprintVariables["_auditEffectSerial"]);
                    if (current == victim)
                    {
                        events.Add("receive"); victim.Defense = row.ReceiveDefense;
                    }
                    else
                    {
                        var target = current.BlueprintVariables.GetValueOrDefault("_auditEffect_toCard") as CardInstance;
                        int damage = Convert.ToInt32(current.BlueprintVariables.GetValueOrDefault("_auditEffect_Damage"));
                        events.Add($"deal:{target?.CardId}:{damage}");
                        if (Convert.ToBoolean(current.BlueprintVariables.GetValueOrDefault("_auditEffect_CounterDamage"))
                            || Convert.ToBoolean(current.BlueprintVariables.GetValueOrDefault("_auditEffect_isCombatDamage"))) payloadError = "效果伤害标志错误";
                        if (target == hq && row.Heal) victim.Defense = 9;
                    }
                };
                dispatch.Invoke(engine.Api, [victim, row.Incoming, source, false, false, false, null, false, null, false]);
                var expected = new List<string>();
                if (positive)
                {
                    expected.Add("receive");
                    if (spilled > 0) expected.Add($"deal:{hq.CardId}:{spilled}");
                    expected.Add($"deal:60:{finalDamage}");
                }
                var notices = state.ActionLog.SelectMany(a => a.SubActions).Where(a => a.Name == "ZActionDamageCard").ToArray();
                bool noticesOk = notices.Length == (spilled > 0 ? 2 : 1);
                if (noticesOk)
                {
                    var notice = notices[0].Values.ToDictionary(v => v.Name);
                    noticesOk = notice["cardID"].Value == 60 && notice["damage"].Value == finalDamage
                        && notice["oldDefense"].Value == (positive ? row.ReceiveDefense : 9)
                        && notice["destroyed"].Value == (destroyed ? 1 : 0) && notice["attackerCardID"].Value == 50;
                    if (spilled > 0)
                    {
                        var spill = notices[1].Values.ToDictionary(v => v.Name);
                        noticesOk &= spill["cardID"].Value == hq.CardId && spill["damage"].Value == spilled;
                    }
                }
                if (!events.SequenceEqual(expected) || !noticesOk || victim.Defense != finalDefense
                    || (victim.Location == CardLocation.Discard) != destroyed || hq.Defense != 20 - spilled
                    || state.GetHQDamagedAmountThisTurn(victim.Owner) != spilled || payloadError is not null
                    || !destroyed && victim.Keywords.Contains(Keyword.Mobilize) != !positive)
                    failures.Add($"{row}: 事件 {string.Join(',', events)} 期望 {string.Join(',', expected)}; 防御={victim.Defense}/{finalDefense},位置={victim.Location},通知={notices.Length}; {payloadError}");
            }
            return failures.Count == 0 ? null : $"{failures.Count}/54 场景失败：" + string.Join(" | ", failures.Take(8));
        }
        finally
        {
            foreach (string hook in hooks)
            {
                locals.Remove(hook);
                if (cache.TryGetValue(name, out var perCard))
                {
                    perCard.Remove(hook);
                    if (saved[hook] is { } old) perCard[hook] = old;
                }
            }
            if (oldCache is null && cache.TryGetValue(name, out var added) && added.Count == 0) cache.Remove(name);
        }
    }

    // Synthetic callbacks validate common dispatch boundaries only.
    private static string? DamageBeforeDispatchSnapshot(CardDatabase db)
    {
        const string own = "OnReceiveDamage", other = "OnOtherCardReceiveDamage";
        var installed = new List<(IDictionary<string, IReadOnlyList<KismetStep>> Locals, string Trigger)>();
        foreach (string name in new[] { "card_event_honorifics", "card_unit_51e_regiment" })
        foreach (string trigger in new[] { own, other })
        {
            if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
                || KismetLibrary.Default.FindProgram(name, trigger) is not null)
            {
                foreach (var item in installed) item.Locals.Remove(item.Trigger);
                return "无法安全安装受伤前派发探针";
            }
            var steps = new List<KismetStep>();
            void Save(string key, KismetExpr value) => steps.Add(new KismetStep(steps.Count, "set", null,
                Array.Empty<KismetExpr>(), Array.Empty<int>(), value, null, -1, key, null)
                { DestinationScope = "instance" });
            Save("_auditBeforeKind", new KismetExpr { Int = trigger == own ? 1 : 2 });
            foreach (string key in new[] { "fromCard", "toCard", "Damage", "fromAttack" })
                Save("_auditBefore_" + key, new KismetExpr { Var = key, Scope = "local" });
            steps.Add(new KismetStep(steps.Count, "call", "SpawnCardInDeckBySide", new[] {
                new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
            }, Array.Empty<int>(), null, null, -1, null, null));
            steps.Add(new KismetStep(steps.Count, "return", null, Array.Empty<KismetExpr>(),
                Array.Empty<int>(), null, null, -1, null, null));
            locals.Add(trigger, steps); installed.Add((locals, trigger));
        }
        try
        {
            var failures = new List<string>();
            var dispatch = typeof(CardApi).GetMethod("ExecuteBeforeReceiveDamage",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!;
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int mode in Enumerable.Range(0, 16))
            {
                var (engine, state) = EmptyBoard(db);
                var target = state.CreateWithId("card_event_honorifics", side, 50, side.HqOf(), 0);
                var first = state.CreateWithId("card_unit_51e_regiment", side, 20, side.HqOf(), 1);
                var last = state.CreateWithId("card_unit_51e_regiment", side, 21, side.HqOf(), 2);
                foreach (var card in new[] { target, first, last })
                    card.Definition = new CardDefinition { Name = card.Name, UsedTriggers = new[] { other } };
                CardInstance? source = mode == 14 ? null
                    : state.CreateWithId(PlainUnit, side.Opposite(), 60, side.Opposite().HqOf(), 0);
                if (mode is 1 or 2 or 7) last.Keywords.Add(Keyword.Suppressed);
                if (mode == 2) last.SuppressionExceptionTriggers.Add(other);
                if (mode == 3) target.Location = CardLocation.NotAvailable;
                if (mode == 4) last.Location = CardLocation.NotAvailable;
                if (mode == 8) state.StopFurtherActions = true;
                if (mode is 11 or 15) target.Keywords.Add(Keyword.Suppressed);
                if (mode == 15) { target.SuppressionExceptionTriggers.Add(own); target.SuppressionExceptionTriggers.Add(other); }
                var cards = new List<CardInstance> { target, first, last };
                var called = new List<(int Id, int Kind)>(); string? payloadError = null;
                bool combat = (mode & 1) != 0;
                int amount = new[] { -4, 0, 7, int.MaxValue }[mode % 4];
                int Value(object? v) => v is CardInstance card ? card.CardId : Convert.ToInt32(v);
                var created = state.CardCreated;
                state.CardCreated = made => {
                    created?.Invoke(made);
                    if (made.Name != "card_unit_routed_troops") return;
                    var current = cards.Single(x => x.BlueprintVariables.TryGetValue("_auditBeforeKind", out var kind)
                        && !called.Contains((x.CardId, Convert.ToInt32(kind))));
                    int tag = Convert.ToInt32(current.BlueprintVariables["_auditBeforeKind"]);
                    called.Add((current.CardId, tag));
                    var want = new Dictionary<string, int> {
                        ["fromCard"] = source?.CardId ?? 0, ["toCard"] = target.CardId,
                        ["Damage"] = amount, ["fromAttack"] = combat ? 1 : 0,
                    };
                    foreach (var pair in want)
                        if (!current.BlueprintVariables.TryGetValue("_auditBefore_" + pair.Key, out var value)
                            || Value(value) != pair.Value) payloadError = $"{current.CardId}/{pair.Key} 载荷错误";
                    void AddLate()
                    {
                        var late = state.CreateWithId("card_unit_51e_regiment", side, 9004, side.HqOf(), 3);
                        late.Definition = new CardDefinition { Name = late.Name, UsedTriggers = new[] { other } };
                        cards.Add(late);
                    }
                    if (current == target)
                    {
                        if (mode == 9) state.StopFurtherActions = true;
                        if (mode == 12) AddLate();
                    }
                    if (current == first)
                    {
                        if (mode == 5) { last.Keywords.Add(Keyword.Suppressed); last.Location = CardLocation.NotAvailable; }
                        if (mode == 6) last.Definition = new CardDefinition { Name = last.Name };
                        if (mode == 7) last.Keywords.Remove(Keyword.Suppressed);
                        if (mode == 10) state.StopFurtherActions = true;
                        if (mode == 13) AddLate();
                    }
                };
                dispatch.Invoke(engine.Api, [target, source, amount, combat]);
                var expected = new List<(int Id, int Kind)>();
                if (mode is not (11 or 15)) expected.Add((50, 1));
                expected.Add((20, 2));
                if (mode is not (1 or 7)) expected.Add((21, 2));
                if (mode == 12) expected.Add((9004, 2));
                if (!called.SequenceEqual(expected) || payloadError is not null)
                    failures.Add($"{side}/mode={mode}: 实际 {string.Join(",", called)}，期望 {string.Join(",", expected)} {payloadError}");
            }
            return failures.Count == 0 ? null : $"{failures.Count}/32 场景失败：" + string.Join(" | ", failures.Take(10));
        }
        finally { foreach (var item in installed) item.Locals.Remove(item.Trigger); }
    }

    // Synthetic programs probe only the common dispatcher, not these live cards' rules.
    private static string? DamageAfterDispatchSnapshot(CardDatabase db)
    {
        const string own = "OnCardDealDamage", other = "OnOtherCardDealDamage";
        var installed = new List<(IDictionary<string, IReadOnlyList<KismetStep>> Locals, string Trigger)>();
        foreach (string name in new[] { "card_unit_typhoon_mk_ib", "card_event_honorifics", "card_unit_51e_regiment" })
        foreach (string trigger in new[] { own, other })
        {
            if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
                || KismetLibrary.Default.FindProgram(name, trigger) is not null)
            {
                foreach (var item in installed) item.Locals.Remove(item.Trigger);
                return "无法安全安装伤害后派发探针";
            }
            var steps = new List<KismetStep>();
            void Save(string key, KismetExpr value) => steps.Add(new KismetStep(steps.Count, "set", null,
                Array.Empty<KismetExpr>(), Array.Empty<int>(), value, null, -1, key, null)
                { DestinationScope = "instance" });
            Save("_auditDamageKind", new KismetExpr { Int = trigger == own ? 1 : 2 });
            foreach (string key in new[] { "cardDealingDamage", "toCard", "Damage", "isCombatDamage", "CounterDamage", "isRedirected" })
                Save("_auditDamage_" + key, new KismetExpr { Var = key, Scope = "local" });
            steps.Add(new KismetStep(steps.Count, "call", "SpawnCardInDeckBySide", new[] {
                new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
            }, Array.Empty<int>(), null, null, -1, null, null));
            steps.Add(new KismetStep(steps.Count, "return", null, Array.Empty<KismetExpr>(),
                Array.Empty<int>(), null, null, -1, null, null));
            locals.Add(trigger, steps); installed.Add((locals, trigger));
        }
        try
        {
            var failures = new List<string>();
            var dispatch = typeof(CardApi).GetMethod("ExecuteOnCardDealDamageEffects",
                System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!;
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int mode in Enumerable.Range(0, 17))
            {
                var (engine, state) = EmptyBoard(db);
                var gotcha = state.CreateWithId("card_event_honorifics", side, 10, side.DeckOf(), 0);
                gotcha.Definition = new CardDefinition { Name = gotcha.Name, Type = "gotcha", UsedTriggers = new[] { other } };
                gotcha.GotchaActivated = 1;
                CardInstance? source = mode == 13 ? null : mode == 15 ? gotcha
                    : state.CreateWithId("card_unit_typhoon_mk_ib", side, 50, side.HqOf(), 0);
                if (source is not null && source != gotcha)
                    source.Definition = new CardDefinition { Name = source.Name, UsedTriggers = new[] { other } };
                var first = state.CreateWithId("card_unit_51e_regiment", side, 20, side.HqOf(), 1);
                var last = state.CreateWithId("card_unit_51e_regiment", side, 21, side.HqOf(), 2);
                foreach (var card in new[] { first, last })
                    card.Definition = new CardDefinition { Name = card.Name, UsedTriggers = new[] { other } };
                var target = state.CreateWithId(PlainUnit, side.Opposite(), 60, side.Opposite().HqOf(), 0);
                if (mode is 1 or 2 or 6) last.Keywords.Add(Keyword.Suppressed);
                if (mode == 2) last.SuppressionExceptionTriggers.Add(other);
                if (mode == 3) last.Location = CardLocation.NotAvailable;
                if (mode == 7) state.StopFurtherActions = true;
                if (mode == 11) { source!.Keywords.Add(Keyword.Suppressed); source.SuppressionExceptionTriggers.Add(other); }
                if (mode == 12) source!.Location = CardLocation.NotAvailable;
                if (mode == 14) { gotcha.Keywords.Add(Keyword.Suppressed); gotcha.Location = CardLocation.NotAvailable; }
                var cards = new[] { gotcha, source, first, last }.Where(x => x is not null).Cast<CardInstance>().Distinct().ToList();
                var called = new List<(int Id, int Kind)>(); string? payloadError = null;
                bool combat = (mode & 1) != 0, counter = (mode & 2) != 0, redirected = (mode & 4) != 0;
                int amount = new[] { -4, 0, 7, int.MaxValue }[mode % 4];
                int Value(object? v) => v is CardInstance card ? card.CardId : Convert.ToInt32(v);
                var created = state.CardCreated;
                state.CardCreated = made => {
                    created?.Invoke(made);
                    if (made.Name != "card_unit_routed_troops") return;
                    var current = cards.Single(x => x.BlueprintVariables.TryGetValue("_auditDamageKind", out var kind)
                        && !called.Contains((x.CardId, Convert.ToInt32(kind))));
                    int tag = Convert.ToInt32(current.BlueprintVariables["_auditDamageKind"]);
                    called.Add((current.CardId, tag));
                    var want = new Dictionary<string, int> {
                        ["cardDealingDamage"] = source?.CardId ?? 0, ["toCard"] = target.CardId,
                        ["Damage"] = amount, ["isCombatDamage"] = combat ? 1 : 0,
                        ["CounterDamage"] = counter ? 1 : 0, ["isRedirected"] = redirected ? 1 : 0,
                    };
                    foreach (var pair in want)
                        if (!current.BlueprintVariables.TryGetValue("_auditDamage_" + pair.Key, out var value)
                            || Value(value) != pair.Value) payloadError = $"{current.CardId}/{pair.Key} 载荷错误";
                    if (current == first)
                    {
                        if (mode == 4) { last.Keywords.Add(Keyword.Suppressed); last.Location = CardLocation.NotAvailable; }
                        if (mode == 5) last.Definition = new CardDefinition { Name = last.Name };
                        if (mode == 6) last.Keywords.Remove(Keyword.Suppressed);
                        if (mode == 10) state.StopFurtherActions = true;
                    }
                    if (current == gotcha && tag == 2 && mode == 8) state.StopFurtherActions = true;
                    if (current == source && tag == 1)
                    {
                        if (mode == 9) state.StopFurtherActions = true;
                        if (mode == 16)
                        {
                            var late = state.CreateWithId("card_unit_51e_regiment", side, 9004, CardLocation.NotAvailable, 0);
                            late.Definition = new CardDefinition { Name = late.Name, UsedTriggers = new[] { other } };
                            cards.Add(late);
                        }
                    }
                };
                dispatch.Invoke(engine.Api, [target, source, amount, combat, counter, redirected]);
                var expected = new List<(int Id, int Kind)>();
                if (mode != 7)
                {
                    expected.Add((10, 2));
                    if (mode != 8)
                    {
                        if (source is not null && mode != 11) expected.Add((source.CardId, 1));
                        if (mode != 9)
                        {
                            expected.Add((20, 2));
                            if (mode is not (1 or 6 or 10)) expected.Add((21, 2));
                            if (mode == 16) expected.Add((9004, 2));
                        }
                    }
                }
                if (!called.SequenceEqual(expected) || payloadError is not null)
                    failures.Add($"{side}/mode={mode}: 实际 {string.Join(",", called)}，期望 {string.Join(",", expected)} {payloadError}");
            }
            return failures.Count == 0 ? null : $"{failures.Count}/34 场景失败：" + string.Join(" | ", failures.Take(10));
        }
        finally { foreach (var item in installed) item.Locals.Remove(item.Trigger); }
    }

    /// <summary>
    /// `OnOtherCardDealDamage` 的六个事件参数必须传给真实订阅程序：
    /// 15th RECCE 读取 `cardDealingDamage`，只在带有 `targetAbility` 的伤害来源
    /// 造成伤害时给自己 +1/+1 并获得 Guard。仅验证 TriggerTrace 不能证明
    /// 来源卡槽位被正确填充，因为缺载荷时事件仍然会留下广播记录。
    /// </summary>
    private static string? DealDamageEventCarriesPayload(CardDatabase db)
    {
        const string watcherName = "card_unit_15th_recon_regiment";
        const string sourceName = PlainUnit;
        const string victimName = PlainUnit;
        if (db.Find(watcherName) is null || db.Find(sourceName) is null)
        {
            return $"卡库里缺 {watcherName} 或 {sourceName}";
        }

        var (engine, state) = EmptyBoard(db);
        var watcher = PutOnBoard(state, watcherName, Side.Left, 20, 1);
        var source = PutOnBoard(state, sourceName, Side.Left, 21, 2);
        var victim = PutOnBoard(state, victimName, Side.Right, 60, 1);
        engine.Api.CustomAbilityAdd(source, "targetAbility", watcher);
        victim.Defense = 20;

        int attack = watcher.Attack;
        int defense = watcher.Defense;
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        try
        {
            engine.Api.DealDamage(victim, 1, source);
        }
        catch (Exception ex)
        {
            return $"DealDamage 抛出 {ex.GetType().Name}: {ex.Message}";
        }

        string prefix = $"OnOtherCardDealDamage → {watcher.Name}#{watcher.CardId}";
        if (!trace.Any(t => t.StartsWith(prefix, StringComparison.Ordinal)
                         && t.Contains($"eventCard={source.Name}#{source.CardId}", StringComparison.Ordinal)))
        {
            return "OnOtherCardDealDamage 没有把伤害来源作为事件主体传给 15th RECCE"
                 + $"\n       实际派发记录：{string.Join(" | ", trace)}";
        }

        if (watcher.Attack != attack + 1 || watcher.Defense != defense + 1)
        {
            return $"15th RECCE 未消费 cardDealingDamage=source：期望攻防={attack + 1}/{defense + 1}，"
                 + $"实际={watcher.Attack}/{watcher.Defense}（来源 CustomAbility={source.CustomAbility}）";
        }

        if (!watcher.Keywords.Contains(Keyword.Guard, StringComparer.Ordinal))
        {
            return "15th RECCE 收到伤害事件后应获得 Guard，但关键字没有写入";
        }

        return null;
    }

    private static string? CustomDamageEventEntrypoints(CardDatabase db)
    {
        const string riflesName = "card_unit_220th_rifles";
        const string kyushuName = "card_unit_kyushu_j7w3";
        const string suName = "card_unit_su_100";
        if (db.Find(riflesName) is null || db.Find(kyushuName) is null || db.Find(suName) is null)
        {
            return $"卡库里缺 {riflesName} / {kyushuName} / {suName}";
        }

        // 220th Rifles: the wrapper calls CustomEventOnCardDealDamage, which
        // must count a damaged unit and apply the live +2 attack buff.
        var (engine, state) = EmptyBoard(db);
        var rifles = PutOnBoard(state, riflesName, Side.Left, 300, 1);
        var damaged = PutOnBoard(state, PlainUnit, Side.Left, 301, 2);
        damaged.Defense = Math.Max(0, damaged.MaxDefense - 1);
        int riflesAttack = rifles.Attack;
        FireSelfDamageEvent(engine, rifles, damaged);
        if (rifles.Attack != riflesAttack + 2)
        {
            return $"220th Rifles 自定义伤害事件未执行：期望攻击 {riflesAttack + 2}，实际 {rifles.Attack}";
        }

        // Kyushu J7W3: its own damage event removes the one-time +2/Fury buff
        // after the unit becomes damaged.
        var (kyushuEngine, kyushuState) = EmptyBoard(db);
        var kyushu = PutOnBoard(kyushuState, kyushuName, Side.Left, 310, 1);
        kyushuEngine.Api.FireTrigger("OnEnterPlay", kyushu, Side.Left,
            eventSubject: kyushu);
        kyushu.Defense = Math.Max(0, kyushu.MaxDefense - 1);
        int kyushuAttack = kyushu.Attack;
        if (!kyushu.HasFury || kyushuAttack <= kyushu.Definition.Attack)
        {
            return $"Kyushu 入场 buff 未建立：期望基础攻击 {kyushu.Definition.Attack} 以上且带 Fury，"
                 + $"实际={kyushuAttack}/{kyushu.HasFury}";
        }
        if (kyushu.Keywords.Contains(Keyword.Fury)
            || !kyushu.ReceivedAbilitiesFromCards["fury"].SequenceEqual(new[] { 310 })
            || kyushu.BuffsBySource[(310, false)].Fury != 1)
            return "Kyushu应由自身来源给予Fury，不应改写原始标志";
        FireSelfDamageEvent(kyushuEngine, kyushu, kyushu);
        if (kyushu.Attack != kyushuAttack - 2 || kyushu.HasFury)
        {
            return $"Kyushu 自定义伤害事件未执行：期望攻击/Fury={kyushuAttack - 2}/false，"
                 + $"实际={kyushu.Attack}/{kyushu.HasFury}";
        }

        // SU-100: a damaged source dealing damage runs SelfCustomEventOnCardDealDamage
        // and receives its +4 attack buff.
        var (suEngine, suState) = EmptyBoard(db);
        var su = PutOnBoard(suState, suName, Side.Left, 320, 1);
        var suTarget = PutOnBoard(suState, PlainUnit, Side.Right, 321, 1);
        su.Defense = Math.Max(0, su.MaxDefense - 1);
        int suAttack = su.Attack;
        FireSelfDamageEvent(suEngine, su, suTarget);
        return su.Attack == suAttack + 4
            ? null
            : $"SU-100 自定义伤害事件未执行：期望攻击 {suAttack + 4}，实际 {su.Attack}";
    }

    private static void FireSelfDamageEvent(MatchEngine engine, CardInstance source, CardInstance target)
    {
        var named = new Dictionary<string, object?>(StringComparer.Ordinal)
        {
            ["cardDealingDamage"] = source,
            ["toCard"] = target,
            ["Damage"] = 1,
            ["damage"] = 1,
            ["isCombatDamage"] = false,
            ["CounterDamage"] = false,
            ["isRedirected"] = false,
        };
        engine.Api.FireTrigger("OnCardDealDamage", source, source.Owner,
            eventArgs: new object?[] { source, target, 1, false, false, false },
            eventSubject: source, namedArgs: named);
    }

    /// <summary>
    /// 48th Armored Infantry 的事件 38 订阅：最终伤害每有一个相邻单位减少 2。
    /// 这条必须在统一 DealDamage 漏斗中验证，单独调用私有函数无法证明事件已接通。
    /// </summary>
    private static string? DealDamageAfterCalcAdjacentDefense(CardDatabase db)
    {
        const string armoredName = "card_unit_48th_armored_infantry";
        const string unitName = PlainUnit;
        if (db.Find(armoredName) is null || db.Find(unitName) is null)
        {
            return $"卡库里缺 {armoredName} 或 {unitName}";
        }

        var (engine, state) = EmptyBoard(db);
        var left = PutOnBoard(state, armoredName, Side.Left, 20, 2);
        PutOnBoard(state, unitName, Side.Left, 21, 1);
        PutOnBoard(state, unitName, Side.Left, 22, 3);
        var source = PutOnBoard(state, unitName, Side.Right, 60, 1);
        int before = left.Defense;
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = left, Controller = Side.Left,
        };
        object? adjacent = engine.Api.InvokeByName("GetDefenseBuffFromAdjacentUnits", null,
            new object?[] { null }, ctx, out bool handled);
        if (!handled || adjacent is not int amount || amount != 4)
        {
            return $"两个相邻单位应提供 4 点防御修正，handled={handled}, result={adjacent}";
        }

        engine.Api.DealDamage(left, 5, source, isCombatDamage: true);
        if (left.Defense != before - 1)
        {
            return $"事件 38 应将 5 点伤害减为 1 点，实际防御 {before} → {left.Defense}"
                 + Dump(state, ("目标", left.ToString()));
        }

        return null;
    }

    /// <summary>
    /// 天气候选池的正版蓝图只按 subtype.rain/storm/sunny 筛选活动静态卡；
    /// `ability.forecast` 是触发 Forecast 的能力标签，不能混作天气卡判据。
    /// </summary>
    private static string? ForecastCardPrimitives(CardDatabase db)
    {
        const string weatherName = "card_event_rain2_deluge";
        if (db.Find(weatherName) is null || db.Find(PlainUnit) is null)
        {
            return $"卡库里缺 {weatherName} 或 {PlainUnit}";
        }

        var (engine, state) = EmptyBoard(db);
        var weather = PutOnBoard(state, weatherName, Side.Left, 20, 1);
        var unit = PutOnBoard(state, PlainUnit, Side.Left, 21, 2);
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = weather, Controller = Side.Left,
        };

        object? weatherResult = engine.Api.InvokeByName("IsForecastCard", null,
            new object?[] { null }, ctx, out bool weatherHandled);
        if (!weatherHandled || weatherResult is not bool isWeather || !isWeather)
        {
            return $"天气卡应被 IsForecastCard 判真，handled={weatherHandled}, result={weatherResult}";
        }

        ctx.Self = unit;
        object? unitResult = engine.Api.InvokeByName("IsForecastCard", null,
            new object?[] { null }, ctx, out bool unitHandled);
        if (!unitHandled || unitResult is not bool isUnit || isUnit)
        {
            return $"普通单位不应被判为天气卡，handled={unitHandled}, result={unitResult}";
        }

        ctx.Self = weather;
        object? candidates = engine.Api.InvokeByName("GetAllForecastCards", null,
            new object?[] { true, false, null }, ctx, out bool poolHandled);
        if (!poolHandled || candidates is not IEnumerable<CardInstance> pool)
        {
            return $"GetAllForecastCards 未返回候选池，handled={poolHandled}, result={candidates}";
        }

        var list = pool.ToList();
        if (list.Count == 0 || list.Any(card => !card.Definition.IsOrder)
            || list.All(card => !string.Equals(card.Name, weatherName, StringComparison.Ordinal)))
        {
            return $"天气候选池应包含天气模板且排除普通卡，数量={list.Count}";
        }

        return null;
    }

    private static string? WeatherCardPerTurn(CardDatabase db)
    {
        const string weatherName = "card_event_rain2_deluge";
        const string ordinaryOrderName = "card_event_forward_observers";
        if (db.Find(weatherName) is null || db.Find(ordinaryOrderName) is null)
        {
            return $"卡库里缺 {weatherName} 或 {ordinaryOrderName}";
        }

        var (engine, state) = EmptyBoard(db);
        state.ActiveSide = Side.Left;
        state.SetKredits(Side.Left, 40);
        state.SetMaxKredits(Side.Left, 40);

        var firstWeather = state.Create(weatherName, Side.Left, CardLocation.HandLeft, 0);
        var secondWeather = state.Create(weatherName, Side.Left, CardLocation.HandLeft, 1);
        var ordinaryOrder = state.Create(ordinaryOrderName, Side.Left, CardLocation.HandLeft, 2);

        if (!engine.CanPlay(firstWeather, out string firstReason))
        {
            return $"第一张天气牌不应被拒绝：{firstReason}";
        }

        if (!engine.PlayCard(firstWeather))
        {
            return "第一张天气牌实际打出失败";
        }

        if (!state.HasPlayedWeatherCardThisTurn)
        {
            return "打出天气牌后未设置本回合标志";
        }

        if (engine.CanPlay(secondWeather, out string secondReason))
        {
            return "同一回合第二张天气牌未被拒绝";
        }

        if (!engine.CanPlay(ordinaryOrder, out string ordinaryReason))
        {
            return $"天气限制错误地拒绝普通指令：{ordinaryReason}";
        }

        engine.StartTurn(Side.Left, draw: false);
        if (state.HasPlayedWeatherCardThisTurn)
        {
            return "开始新回合后天气标志未清零";
        }

        if (!engine.CanPlay(secondWeather, out string resetReason))
        {
            return $"天气标志清零后第二张天气牌仍被拒绝：{resetReason}";
        }

        return null;
    }

    /// <summary>
    /// Forecast is a client-facing selection primitive in the Blueprint, but
    /// these two real subscribers only consume the completed event payload:
    /// Kawanishi H8K draws one card and 2nd Pioneers buffs every other friendly
    /// unit.  Headless resolution accepts the forecast synchronously, so this
    /// checks that the newly created weather card is the event subject. The
    /// selecting H8K remains a recipient, as in DevelopAndForecastCheck.
    /// </summary>
    private static string? ForecastBroadcastGameplay(CardDatabase db)
    {
        const string h8kName = "card_unit_kawanishi_h8k";
        const string pioneersName = "card_unit_2_2nd_pioneers";
        foreach (string name in new[] { h8kName, pioneersName, PlainUnit })
        {
            if (db.Find(name) is null)
            {
                return $"卡库里缺 {name}";
            }
        }

        var (engine, state) = EmptyBoard(db);
        var trigger = PutOnBoard(state, h8kName, Side.Left, 20, 1);
        var h8k = PutOnBoard(state, h8kName, Side.Left, 21, 2);
        var pioneers = PutOnBoard(state, pioneersName, Side.Left, 22, 3);
        var otherUnit = PutOnBoard(state, PlainUnit, Side.Left, 23, 4);
        state.CreateWithId(PlainUnit, Side.Left, 30, CardLocation.DeckLeft, 0);
        state.CreateWithId(PlainUnit, Side.Left, 31, CardLocation.DeckLeft, 1);
        engine.ChooseSpawnCard = (_, candidates) => candidates[0];

        int h8kAttack = h8k.Attack;
        int h8kDefense = h8k.Defense;
        int otherAttack = otherUnit.Attack;
        int otherDefense = otherUnit.Defense;
        int pioneersAttack = pioneers.Attack;
        int pioneersDefense = pioneers.Defense;
        var ctx = new EffectContext
        {
            Engine = engine,
            State = state,
            Self = trigger,
            Controller = Side.Left,
        };

        object? result = engine.Api.InvokeByName("Forecast", trigger,
            new object?[] { null }, ctx, out bool handled);
        if (!handled)
        {
            return "Forecast 未接入派发表";
        }

        if (result is not int resultCode || resultCode != 0)
        {
            return $"Forecast 应同步返回 0，实际 result={result ?? "null"}";
        }

        if (state.Hand(Side.Left).Count != 3
            || state.Hand(Side.Left).Count(x => x.Name == PlainUnit) != 2
            || state.Hand(Side.Left).Count(x => x.Name == "card_event_sunny1_blue_sky") != 1)
        {
            return "选择应生成天气牌，并使两张 H8K 各抽一张牌，"
                 + $"实际手牌={state.Hand(Side.Left).Count}";
        }

        if (h8k.Attack != h8kAttack + 1 || h8k.Defense != h8kDefense + 1
            || otherUnit.Attack != otherAttack + 1 || otherUnit.Defense != otherDefense + 1)
        {
            return "2nd Pioneers 应给其它友军各 +1/+1，实际 "
                 + $"H8K={h8k.Attack}/{h8k.Defense}（原 {h8kAttack}/{h8kDefense}），"
                 + $"普通单位={otherUnit.Attack}/{otherUnit.Defense}（原 {otherAttack}/{otherDefense}）";
        }

        if (pioneers.Attack != pioneersAttack || pioneers.Defense != pioneersDefense)
        {
            return "2nd Pioneers 自身不应被 OnOtherCardForecasted 增益："
                 + $"Pioneers={pioneers.Attack}/{pioneers.Defense}（原 {pioneersAttack}/{pioneersDefense}）";
        }

        return null;
    }

    /// <summary>
    /// `card_unit_511th_regiment` keeps a source-specific +2 attack buff in
    /// sync with its private Blueprint predicate.  Exercise both transitions
    /// directly through the dispatch table so the no-op fallback cannot hide a
    /// stale aura.
    /// </summary>
    private static string? FiveEleventhRegimentVeteranBuff(CardDatabase db)
    {
        const string sourceName = "card_unit_511th_regiment";
        const string targetName = "card_unit_16th_infantry_brigade";
        if (db.Find(sourceName) is null || db.Find(targetName) is null)
        {
            return $"卡库里缺 {sourceName} 或 {targetName}";
        }

        var (engine, state) = EmptyBoard(db);
        var source = PutOnBoard(state, sourceName, Side.Left, 20, 1);
        var target = PutOnBoard(state, targetName, Side.Left, 21, 2);
        if (target.Keywords.Contains(Keyword.Veteran)
            || !string.Equals(target.Definition.Type, "infantry", StringComparison.OrdinalIgnoreCase))
        {
            return $"测试目标必须是普通步兵，实际 keywords=[{string.Join(',', target.Keywords)}] type={target.Definition.Type}";
        }

        // The live database stores the veteran as a separate `_vet` definition;
        // the gameplay predicate itself consumes the runtime Veteran keyword.
        engine.Api.MakeVeteran(target);
        if (!target.Keywords.Contains(Keyword.Veteran))
        {
            return "MakeVeteran 未将普通步兵目标转换为老兵";
        }

        int baseAttack = target.Attack;
        target.Defense = 1;
        var ctx = new EffectContext
        {
            Engine = engine,
            State = state,
            Self = source,
            Controller = Side.Left,
        };

        engine.Api.InvokeByName("checkAndUpdateBuffOnCard", null,
            new object?[] { target }, ctx, out bool handled);
        if (!handled || target.Attack != baseAttack + 2
            || !target.BuffsBySource.TryGetValue((source.CardId, false), out var buff)
            || buff.Attack != 2)
        {
            return $"1 防御老兵步兵应得到来源 {source.CardId} 的 +2 攻击，"
                 + $"handled={handled} attack={target.Attack} base={baseAttack}";
        }

        target.Defense = 2;
        engine.Api.InvokeByName("checkAndUpdateBuffOnCard", null,
            new object?[] { target }, ctx, out bool removeHandled);
        if (!removeHandled || target.Attack != baseAttack
            || target.BuffsBySource.ContainsKey((source.CardId, false)))
        {
            return $"防御离开 1 后应撤回 511th 增益，handled={removeHandled} "
                 + $"attack={target.Attack} base={baseAttack} buffCount={target.BuffsBySource.Count}";
        }

        return null;
    }

    /// <summary>
    /// Veteran upgrade queries use the explicit `_vet` card definitions rather
    /// than the database's variant fallback.  Cards without a distinct variant
    /// still return their base static definition for attack/defense lookups.
    /// </summary>
    private static string? VeteranUpgradeQueries(CardDatabase db)
    {
        const string upgradeCard = "card_unit_266th_guards_rifles";
        const string noUpgradeCard = "card_unit_37mm_m1_aa_gun";
        if (db.Find(upgradeCard) is null || db.Find(upgradeCard + "_vet") is null
            || db.Find(noUpgradeCard) is null)
        {
            return $"卡库里缺 {upgradeCard}(_vet) 或 {noUpgradeCard}";
        }

        var (engine, state) = EmptyBoard(db);
        var source = state.CreateWithId("card_event_battle_valor", Side.Left, 20,
            CardLocation.BoardHqLeft, 1);
        var target = state.CreateWithId(upgradeCard, Side.Left, 21,
            CardLocation.BoardHqLeft, 2);
        var plain = state.CreateWithId(noUpgradeCard, Side.Left, 22,
            CardLocation.BoardHqLeft, 3);
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = source, Controller = Side.Left,
        };

        object? hasUpgrade = engine.Api.InvokeByName("getHasVeteranUpgrade", target,
            new object?[] { null }, ctx, out bool upgradeHandled);
        if (!upgradeHandled || hasUpgrade is not bool canUpgrade || !canUpgrade)
        {
            return $"{upgradeCard} 应识别为有 `_vet` 变体，handled={upgradeHandled}, result={hasUpgrade}";
        }

        object? noUpgrade = engine.Api.InvokeByName("getHasVeteranUpgrade", plain,
            new object?[] { null }, ctx, out bool plainHandled);
        if (!plainHandled || noUpgrade is not bool hasNoUpgrade || hasNoUpgrade)
        {
            return $"{noUpgradeCard} 不应伪造 `_vet` 升级，handled={plainHandled}, result={noUpgrade}";
        }

        object? veteran = engine.Api.InvokeByName("getStaticVeteranUpgrade", target,
            new object?[] { null }, ctx, out bool staticHandled);
        if (!staticHandled || veteran is not CardInstance veteranCard
            || veteranCard.Name != upgradeCard + "_vet")
        {
            return $"静态老兵模板应为 {upgradeCard}_vet，handled={staticHandled}, result={veteran}";
        }

        object? baseStatic = engine.Api.InvokeByName("getStaticVeteranUpgrade", plain,
            new object?[] { null }, ctx, out bool baseHandled);
        if (!baseHandled || baseStatic is not CardInstance baseCard
            || baseCard.Name != noUpgradeCard)
        {
            return $"无升级卡应回退基础静态模板，handled={baseHandled}, result={baseStatic}";
        }

        return null;
    }

    /// <summary>
    /// `OnOtherCardCreatedAlterCard` 的 `cardPlayed` 载荷必须指向实际新建的卡。
    /// 67th BARANOVICHI 的真实蓝图据此给同阵营 `card_unit_light_infantry`
    /// 授予 Alpine，并拒绝敌方同名单位。
    /// </summary>
    private static string? CreatedAlterEventCarriesPayload(CardDatabase db)
    {
        const string watcherName = "card_unit_67th_baranovichi";
        const string lightInfantry = "card_unit_light_infantry";
        if (db.Find(watcherName) is null || db.Find(lightInfantry) is null)
        {
            return $"卡库里缺 {watcherName} 或 {lightInfantry}";
        }

        var (engine, state) = EmptyBoard(db);
        var watcher = state.CreateWithId(watcherName, Side.Left, 20,
            CardLocation.BoardHqLeft, 1);
        var enemy = state.CreateWithId(lightInfantry, Side.Right, 61,
            CardLocation.BoardHqRight, 1);
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        var ally = state.CreateWithId(lightInfantry, Side.Left, 62,
            CardLocation.BoardHqLeft, 2);

        if (!ally.Keywords.Contains(Keyword.Alpine, StringComparer.Ordinal))
        {
            return "67th BARANOVICHI 没有按 cardPlayed 载荷给己方 light infantry 授予 Alpine";
        }

        if (enemy.Keywords.Contains(Keyword.Alpine, StringComparer.Ordinal))
        {
            return "OnOtherCardCreatedAlterCard 错把敌方 light infantry 当成己方目标并授予 Alpine";
        }

        if (!trace.Any(t => t.StartsWith($"OnOtherCardCreatedAlterCard → {watcher.Name}#{watcher.CardId}",
                                         StringComparison.Ordinal)
                         && t.Contains($"eventCard={ally.Name}#{ally.CardId}", StringComparison.Ordinal)))
        {
            return "OnOtherCardCreatedAlterCard 没有记录实际创建的 cardPlayed 事件主体";
        }

        return null;
    }

    /// <summary>
    /// `OnOtherCardLocationMoved` 的事件主体必须是实际换区的卡，并且新位置参数
    /// 要能让真实 35th INFANTRY REGIMENT 蓝图识别「敌方单位进入前线」。
    /// 该效果随后只给己方场上单位 +1/+1，敌方单位不得被误 buff。
    /// </summary>
    private static string? LocationMovedEventCarriesPayload(CardDatabase db)
    {
        const string watcherName = "card_unit_35th_infantry_regiment";
        const string allyName = PlainUnit;
        const string enemyName = PlainUnit;
        if (db.Find(watcherName) is null || db.Find(allyName) is null)
        {
            return $"卡库里缺 {watcherName} 或 {allyName}";
        }

        var (engine, state) = EmptyBoard(db);
        state.ActiveSide = Side.Right;
        var watcher = state.CreateWithId(watcherName, Side.Left, 20,
            CardLocation.BoardHqLeft, 1);
        var ally = state.CreateWithId(allyName, Side.Left, 21,
            CardLocation.BoardHqLeft, 2);
        var enemy = state.CreateWithId(enemyName, Side.Right, 60,
            CardLocation.BoardHqRight, 1);
        int allyAttack = ally.Attack;
        int allyDefense = ally.Defense;
        int enemyAttack = enemy.Attack;
        int enemyDefense = enemy.Defense;
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;

        try
        {
            state.Move(enemy, CardLocation.BoardFrontline, 0, moveReason: CardMoveReason.AdvanceForce);
        }
        catch (Exception ex)
        {
            return $"移动敌方单位到前线抛出 {ex.GetType().Name}: {ex.Message}";
        }

        string prefix = $"OnOtherCardLocationMoved → {watcher.Name}#{watcher.CardId}";
        if (!trace.Any(t => t.StartsWith(prefix, StringComparison.Ordinal)
                         && t.Contains($"eventCard={enemy.Name}#{enemy.CardId}", StringComparison.Ordinal)))
        {
            return "OnOtherCardLocationMoved 没有把实际推进的敌方单位作为事件主体传给 35th INFANTRY REGIMENT"
                 + $"\n       实际派发记录：{string.Join(" | ", trace)}";
        }

        if (enemy.Location != CardLocation.BoardFrontline)
        {
            return $"测试布景失败：敌方单位未进入前线（实际位置={enemy.Location}）";
        }

        if (ally.Attack != allyAttack + 1 || ally.Defense != allyDefense + 1)
        {
            return $"35th INFANTRY REGIMENT 未给己方单位 +1/+1：期望={allyAttack + 1}/{allyDefense + 1}，"
                 + $"实际={ally.Attack}/{ally.Defense}";
        }

        if (enemy.Attack != enemyAttack || enemy.Defense != enemyDefense)
        {
            return $"35th INFANTRY REGIMENT 错给敌方单位加 buff：期望={enemyAttack}/{enemyDefense}，"
                 + $"实际={enemy.Attack}/{enemy.Defense}";
        }

        return null;
    }

    /// <summary>
    /// `OnOtherCardDiscarded` 的事件主体必须是实际被弃掉的卡。
    /// NAKAJIMA B5N 据此对敌方场上单位造成 1 点伤害；友方单位不应被波及。
    /// </summary>
    private static string? DiscardedEventCarriesPayload(CardDatabase db)
    {
        const string watcherName = "card_unit_nakajima_b5n";
        const string discardedName = PlainUnit;
        if (db.Find(watcherName) is null || db.Find(discardedName) is null)
        {
            return $"卡库里缺 {watcherName} 或 {discardedName}";
        }

        var (engine, state) = EmptyBoard(db);
        state.ActiveSide = Side.Left;
        var watcher = state.CreateWithId(watcherName, Side.Left, 20,
            CardLocation.BoardHqLeft, 1);
        var ally = state.CreateWithId(discardedName, Side.Left, 21,
            CardLocation.BoardHqLeft, 2);
        var enemy = state.CreateWithId(discardedName, Side.Right, 60,
            CardLocation.BoardHqRight, 1);
        var discarded = state.CreateWithId(discardedName, Side.Left, 61,
            CardLocation.HandLeft, 3);
        int allyDefense = ally.Defense;
        int enemyDefense = enemy.Defense;
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;

        try
        {
            engine.Api.DiscardCard(discarded, watcher);
        }
        catch (Exception ex)
        {
            return $"DiscardCard 抛出 {ex.GetType().Name}: {ex.Message}";
        }

        string prefix = $"OnOtherCardDiscarded → {watcher.Name}#{watcher.CardId}";
        if (!trace.Any(t => t.StartsWith(prefix, StringComparison.Ordinal)
                         && t.Contains($"eventCard={discarded.Name}#{discarded.CardId}", StringComparison.Ordinal)))
        {
            return "OnOtherCardDiscarded 没有把实际被弃掉的卡作为事件主体传给 NAKAJIMA B5N"
                 + $"\n       实际派发记录：{string.Join(" | ", trace)}";
        }

        if (discarded.Location != CardLocation.Discard)
        {
            return $"测试布景失败：被弃卡没有进入弃牌堆（实际位置={discarded.Location}）";
        }

        if (enemy.Defense != enemyDefense - 1)
        {
            return $"NAKAJIMA B5N 未对敌方单位造成 1 点伤害：期望防御={enemyDefense - 1}，实际={enemy.Defense}";
        }

        if (ally.Defense != allyDefense)
        {
            return $"NAKAJIMA B5N 错误伤害己方单位：期望防御={allyDefense}，实际={ally.Defense}";
        }

        return null;
    }

    private static string? SuccessfulHandDiscardEffects(CardDatabase db)
    {
        const string sallyName = "card_unit_sally";
        const string observerName = "card_unit_211th_basargino";
        const string drawName = "card_unit_t_34_85";
        if (db.Find(sallyName) is null || db.Find(observerName) is null || db.Find(drawName) is null)
        {
            return $"卡库缺少测试卡 {sallyName}、{observerName} 或 {drawName}";
        }

        var (engine, state) = EmptyBoard(db);
        var sally = state.CreateWithId(sallyName, Side.Left, 830,
            CardLocation.HandLeft, 0);
        state.CreateWithId(drawName, Side.Left, 831, CardLocation.DeckLeft, 0);
        state.CreateWithId(drawName, Side.Left, 832, CardLocation.DeckLeft, 1);
        engine.Api.DiscardCard(sally);

        if (sally.Location != CardLocation.Discard
            || state.Hand(Side.Left).Count != 2
            || state.Deck(Side.Left).Count != 0)
        {
            return $"未压制的 Sally 从手牌成功弃掉后应抽 2 张，实际位置={sally.Location}、手牌={state.Hand(Side.Left).Count}、牌库={state.Deck(Side.Left).Count}";
        }

        var (suppressedEngine, suppressedState) = EmptyBoard(db);
        var watcher = suppressedState.CreateWithId(observerName, Side.Left, 833,
            CardLocation.BoardHqLeft, 1);
        var suppressedSally = suppressedState.CreateWithId(sallyName, Side.Left, 834,
            CardLocation.HandLeft, 0);
        suppressedSally.Keywords.Add(Keyword.Suppressed);
        int watcherAttack = watcher.Attack;
        suppressedEngine.Api.DiscardCard(suppressedSally);

        if (suppressedSally.Location != CardLocation.Discard
            || suppressedState.Hand(Side.Left).Count != 0
            || watcher.Attack != watcherAttack + 2)
        {
            return $"压制应只跳过 Sally 自身抽牌、仍让 211th 响应弃牌；实际 Sally={suppressedSally.Location}、手牌={suppressedState.Hand(Side.Left).Count}、211th 攻击={watcher.Attack}（原 {watcherAttack}）";
        }

        return null;
    }

    /// <summary>
    /// HIROSAKI REGIMENT 读取 `cardLostSmokescreen`，为同阵营目标 +1/+1 并降低 1 点行动费。
    /// </summary>
    private static string? LoseSmokescreenEventCarriesPayload(CardDatabase db)
    {
        const string watcherName = "card_unit_hirosaki_regiment";
        const string targetName = PlainUnit;
        if (db.Find(watcherName) is null || db.Find(targetName) is null)
        {
            return $"卡库里缺 {watcherName} 或 {targetName}";
        }

        var (engine, state) = EmptyBoard(db);
        var watcher = state.CreateWithId(watcherName, Side.Left, 20,
            CardLocation.BoardHqLeft, 1);
        var target = state.CreateWithId(targetName, Side.Left, 21,
            CardLocation.BoardHqLeft, 2);
        engine.Api.GiveKeyword(target, Keyword.Smokescreen);
        int attack = target.Attack;
        int defense = target.Defense;
        int operationCost = target.OperationCost;
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;

        try
        {
            engine.Api.RemoveKeyword(target, Keyword.Smokescreen);
        }
        catch (Exception ex)
        {
            return $"RemoveKeyword(Smokescreen) 抛出 {ex.GetType().Name}: {ex.Message}";
        }

        string prefix = $"OnOtherCardLoseSmokescreen → {watcher.Name}#{watcher.CardId}";
        if (!trace.Any(t => t.StartsWith(prefix, StringComparison.Ordinal)
                         && t.Contains($"eventCard={target.Name}#{target.CardId}", StringComparison.Ordinal)))
        {
            return "OnOtherCardLoseSmokescreen 没有把失去烟幕的实际目标作为事件主体传给 HIROSAKI REGIMENT"
                 + $"\n       实际派发记录：{string.Join(" | ", trace)}";
        }

        if (target.Keywords.Contains(Keyword.Smokescreen, StringComparer.Ordinal))
        {
            return "测试布景失败：目标仍保留 Smokescreen";
        }

        if (target.Attack != attack + 1 || target.Defense != defense + 1)
        {
            return $"HIROSAKI REGIMENT 未给目标 +1/+1：期望={attack + 1}/{defense + 1}，"
                 + $"实际={target.Attack}/{target.Defense}";
        }

        if (target.OperationCost != Math.Max(0, operationCost - 1))
        {
            return $"HIROSAKI REGIMENT 未降低目标行动费：期望={Math.Max(0, operationCost - 1)}，"
                 + $"实际={target.OperationCost}";
        }

        return null;
    }

    /// <summary>
    /// 110e REGIMENT MOTORIZE 读取 deckSide/instigatorCard：己方首次洗牌时，
    /// 其它己方单位获得 +1/+1，敌方单位不应被影响。
    /// </summary>
    private static string? DeckShuffledEventCarriesPayload(CardDatabase db)
    {
        const string watcherName = "card_unit_110e_regiment_motorize";
        const string unitName = PlainUnit;
        if (db.Find(watcherName) is null || db.Find(unitName) is null)
        {
            return $"卡库里缺 {watcherName} 或 {unitName}";
        }

        var (engine, state) = EmptyBoard(db);
        var watcher = state.CreateWithId(watcherName, Side.Left, 20,
            CardLocation.BoardHqLeft, 1);
        var ally = state.CreateWithId(unitName, Side.Left, 21,
            CardLocation.BoardHqLeft, 2);
        var enemy = state.CreateWithId(unitName, Side.Right, 60,
            CardLocation.BoardHqRight, 1);
        var deckCard = state.CreateWithId(unitName, Side.Left, 72,
            CardLocation.DeckLeft, 0);
        int allyAttack = ally.Attack;
        int allyDefense = ally.Defense;
        int enemyAttack = enemy.Attack;
        int enemyDefense = enemy.Defense;
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;

        try
        {
            engine.Api.InvokeByName("ShuffleDeckBySide", watcher,
                new object?[] { (int)Side.Left, false, watcher.CardId, null },
                new EffectContext
                {
                    Engine = engine,
                    State = state,
                    Self = watcher,
                    Controller = Side.Left,
                }, out _);
        }
        catch (Exception ex)
        {
            return $"ShuffleDeckBySide 抛出 {ex.GetType().Name}: {ex.Message}";
        }

        string prefix = $"OnDeckShuffled → {watcher.Name}#{watcher.CardId}";
        if (!trace.Any(t => t.StartsWith(prefix, StringComparison.Ordinal)
                         && t.Contains($"eventCard={watcher.Name}#{watcher.CardId}", StringComparison.Ordinal)))
        {
            return "OnDeckShuffled 没有把实际施动卡作为事件主体传给 110e REGIMENT MOTORIZE"
                 + $"\n       实际派发记录：{string.Join(" | ", trace)}";
        }

        if (deckCard.Location != CardLocation.DeckLeft)
        {
            return $"测试布景失败：牌库卡位置被错误改变（实际位置={deckCard.Location}）";
        }

        if (ally.Attack != allyAttack + 1 || ally.Defense != allyDefense + 1)
        {
            return $"110e REGIMENT MOTORIZE 未给己方单位 +1/+1：期望={allyAttack + 1}/{allyDefense + 1}，"
                 + $"实际={ally.Attack}/{ally.Defense}";
        }

        if (enemy.Attack != enemyAttack || enemy.Defense != enemyDefense)
        {
            return $"110e REGIMENT MOTORIZE 错误给敌方单位加 buff：期望={enemyAttack}/{enemyDefense}，"
                 + $"实际={enemy.Attack}/{enemy.Defense}";
        }

        return null;
    }

    /// <summary>
    /// PANZER III L 的真实订阅程序只应给己方带 Blitz 的其它坦克 +2 攻击，
    /// 并在 Blitz 移除时撤销该来源的增益。
    /// </summary>
    private static string? BlitzChangedEventCarriesPayload(CardDatabase db)
    {
        const string watcherName = "card_unit_panzer_iii_l";
        const string targetName = "card_unit_t_34_85";
        if (db.Find(watcherName) is null || db.Find(targetName) is null)
        {
            return $"卡库里缺 {watcherName} 或 {targetName}";
        }

        var (engine, state) = EmptyBoard(db);
        var watcher = state.CreateWithId(watcherName, Side.Left, 20,
            CardLocation.BoardHqLeft, 1);
        var ally = state.CreateWithId(targetName, Side.Left, 21,
            CardLocation.BoardHqLeft, 2);
        var enemy = state.CreateWithId(targetName, Side.Right, 60,
            CardLocation.BoardHqRight, 1);
        int allyAttack = ally.Attack;
        int enemyAttack = enemy.Attack;
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;

        try
        {
            engine.Api.GiveKeyword(ally, Keyword.Blitz);
        }
        catch (Exception ex)
        {
            return $"GiveKeyword(Blitz) 抛出 {ex.GetType().Name}: {ex.Message}";
        }

        string prefix = $"OnOtherCardAbilitiesChanged → {watcher.Name}#{watcher.CardId}";
        if (!trace.Any(t => t.StartsWith(prefix, StringComparison.Ordinal)
                         && t.Contains($"eventCard={ally.Name}#{ally.CardId}", StringComparison.Ordinal)))
        {
            return "OnOtherCardAbilitiesChanged 没有把实际获得 Blitz 的己方坦克作为事件主体传给 PANZER III L"
                 + $"\n       实际派发记录：{string.Join(" | ", trace)}";
        }

        if (ally.Attack != allyAttack + 2)
        {
            return $"PANZER III L 未给己方 Blitz 坦克 +2 攻击：期望={allyAttack + 2}，实际={ally.Attack}"
                 + $"\n       实际派发记录：{string.Join(" | ", trace)}";
        }

        if (enemy.Attack != enemyAttack)
        {
            return $"PANZER III L 错误给敌方坦克加攻：期望={enemyAttack}，实际={enemy.Attack}";
        }

        trace.Clear();
        try
        {
            engine.Api.RemoveKeyword(ally, Keyword.Blitz);
        }
        catch (Exception ex)
        {
            return $"RemoveKeyword(Blitz) 抛出 {ex.GetType().Name}: {ex.Message}";
        }

        if (trace.Any(t => t.StartsWith("OnOtherCardBlitzChanged →", StringComparison.Ordinal)))
            return "当前CDO没有T33注册者，PANZER III L不可按T29别名收到T33";
        string removePrefix = $"OnOtherCardAbilitiesChanged → {watcher.Name}#{watcher.CardId}";
        if (!trace.Any(t => t.StartsWith(removePrefix, StringComparison.Ordinal)
                         && t.Contains($"eventCard={ally.Name}#{ally.CardId}", StringComparison.Ordinal)))
        {
            return "OnOtherCardAbilitiesChanged 没有把实际失去 Blitz 的己方坦克作为事件主体传给 PANZER III L"
                 + $"\n       实际派发记录：{string.Join(" | ", trace)}";
        }

        if (ally.Attack != allyAttack)
        {
            return $"移除 Blitz 后 PANZER III L 增益未撤销：期望={allyAttack}，实际={ally.Attack}";
        }

        return null;
    }

    /// <summary>
    /// `getCardsBuffedByThisCard` 的蓝图出参是来源卡维护的 int[]。
    /// 这里验证直接 ChangeAttack/ChangeDefense 的两个目标和一个无关来源；
    /// 原生独立数组的完整顺序及生命周期另行审计。
    /// </summary>
    private static string? CardsBuffedByThisCardReturnsIds(CardDatabase db)
    {
        const string sourceName = "card_unit_panzer_iii_l";
        const string targetName = "card_unit_t_34_85";
        if (db.Find(sourceName) is null || db.Find(targetName) is null)
        {
            return $"卡库里缺 {sourceName} 或 {targetName}";
        }

        var (engine, state) = EmptyBoard(db);
        var source = state.CreateWithId(sourceName, Side.Left, 801, CardLocation.BoardHqLeft, 1);
        var attackTarget = state.CreateWithId(targetName, Side.Left, 802, CardLocation.BoardHqLeft, 2);
        var defenseTarget = state.CreateWithId(targetName, Side.Left, 803, CardLocation.BoardHqLeft, 3);
        var unrelatedSource = state.CreateWithId(sourceName, Side.Left, 804, CardLocation.BoardHqLeft, 4);
        var unrelatedTarget = state.CreateWithId(targetName, Side.Left, 805, CardLocation.BoardHqLeft, 5);

        engine.Api.ChangeAttack(attackTarget, 2, source);
        engine.Api.ChangeDefense(defenseTarget, 1, source);
        engine.Api.ChangeAttack(unrelatedTarget, 1, unrelatedSource);

        var ctx = new EffectContext
        {
            Engine = engine,
            State = state,
            Self = source,
            Controller = source.Owner,
        };
        object? raw = engine.Api.InvokeByName("getCardsBuffedByThisCard", null,
            new object?[] { null }, ctx, out bool handled);

        if (!handled)
        {
            return "getCardsBuffedByThisCard 没进派发表";
        }

        if (raw is not System.Collections.IList list)
        {
            return $"getCardsBuffedByThisCard 返回 {raw?.GetType().Name ?? "null"}，应为 int[] 出参";
        }

        var ids = list.Cast<object?>().OfType<int>().ToHashSet();
        if (!ids.Contains(attackTarget.CardId) || !ids.Contains(defenseTarget.CardId))
        {
            return $"来源卡未列出全部增益目标：实际=[{string.Join(",", ids.OrderBy(x => x))}]，"
                 + $"期望包含 {attackTarget.CardId}/{defenseTarget.CardId}";
        }

        if (ids.Contains(unrelatedTarget.CardId) || ids.Contains(unrelatedSource.CardId))
        {
            return $"来源卡错误列出无关卡：实际=[{string.Join(",", ids.OrderBy(x => x))}]";
        }

        return null;
    }

    /// <summary>
    /// `FullyHealCard` 的 out 参数是实际恢复量，而不是目标的最大防御或请求量。
    /// 同时守住满血幂等和弃牌堆目标门，避免静默改变状态。
    /// </summary>
    private static string? FullyHealCardPrimitive(CardDatabase db)
    {
        const string cardName = "card_unit_t_34_85";
        if (db.Find(cardName) is null)
        {
            return $"卡库里缺 {cardName}";
        }

        var (engine, state) = EmptyBoard(db);
        var target = state.CreateWithId(cardName, Side.Left, 806,
            CardLocation.BoardHqLeft, 1);
        var ctx = new EffectContext
        {
            Engine = engine,
            State = state,
            Self = target,
            Controller = target.Owner,
        };

        int max = target.MaxDefense;
        if (max < 2)
        {
            return $"测试卡 {cardName} 的 MaxDefense={max}，不足以构造受伤目标";
        }

        target.Defense = max - 2;
        object? raw = engine.Api.InvokeByName("FullyHealCard", null,
            new object?[] { target }, ctx, out bool handled);
        if (!handled)
        {
            return "FullyHealCard 没进派发表";
        }

        if (raw is not object?[] result || result.Length != 1 || result[0] is not int healed)
        {
            return $"FullyHealCard 返回形状错误：{raw?.GetType().Name ?? "null"}，应为 [int]";
        }

        if (healed != 2 || target.Defense != max)
        {
            return $"受伤目标应恢复 2 点并回到 {max}，实际返回 {healed}、防御 {target.Defense}";
        }

        raw = engine.Api.InvokeByName("FullyHealCard", null,
            new object?[] { target }, ctx, out handled);
        if (!handled || raw is not object?[] fullResult || fullResult.Length != 1
            || fullResult[0] is not int fullHealed || fullHealed != 0
            || target.Defense != max)
        {
            return $"满血目标应返回 0 且保持 {max}，实际返回 {raw ?? "null"}、防御 {target.Defense}";
        }

        target.Location = CardLocation.Discard;
        raw = engine.Api.InvokeByName("FullyHealCard", null,
            new object?[] { target }, ctx, out handled);
        if (!handled || raw is not object?[] deadResult || deadResult.Length != 1
            || deadResult[0] is not int deadHealed || deadHealed != 0
            || target.Defense != max)
        {
            return $"弃牌堆目标应返回 0 且不变更防御，实际返回 {raw ?? "null"}、防御 {target.Defense}";
        }

        return null;
    }

    private static string? OkayamaBlocksUnitFullRepair(CardDatabase db)
    {
        const string observerName = "card_unit_okayama_regiment";
        const string targetName = "card_unit_t_34_85";
        if (db.Find(observerName) is null || db.Find(targetName) is null)
        {
            return $"卡库缺少测试卡 {observerName} 或 {targetName}";
        }

        var (engine, state) = EmptyBoard(db);
        state.CreateWithId(observerName, Side.Left, 812, CardLocation.BoardHqLeft, 1);
        var unit = state.CreateWithId(targetName, Side.Right, 813, CardLocation.BoardHqRight, 1);
        int unitMax = unit.MaxDefense;
        unit.Defense = unitMax - 1;
        var ctx = new EffectContext
        {
            Engine = engine,
            State = state,
            Self = unit,
            Controller = unit.Owner,
        };

        object? raw = engine.Api.InvokeByName("FullyHealCard", null,
            new object?[] { unit }, ctx, out bool handled);
        if (!handled || raw is not object?[] unitResult || unitResult.Length != 1
            || unitResult[0] is not int unitHealed || unitHealed != 0
            || unit.Defense != unitMax - 1)
        {
            return $"Okayama 在场时单位修复应返回 0 并保持 {unitMax - 1} 防御，实际返回 {raw ?? "null"}、防御 {unit.Defense}";
        }

        var hq = state.ById(41)!;
        int hqMax = hq.MaxDefense;
        hq.Defense = hqMax - 1;
        ctx = new EffectContext
        {
            Engine = engine,
            State = state,
            Self = hq,
            Controller = hq.Owner,
        };
        raw = engine.Api.InvokeByName("FullyHealCard", null,
            new object?[] { hq }, ctx, out handled);
        if (!handled || raw is not object?[] hqResult || hqResult.Length != 1
            || hqResult[0] is not int hqHealed || hqHealed != 1
            || hq.Defense != hqMax)
        {
            return $"Okayama 不应阻止 HQ 修复 1 点，实际返回 {raw ?? "null"}、防御 {hq.Defense}";
        }

        return null;
    }

    private static string? GetAllCardsInFrontlinePrimitive(CardDatabase db)
    {
        const string cardName = "card_unit_t_34_85";
        if (db.Find(cardName) is null)
        {
            return $"卡库里缺 {cardName}";
        }

        var (engine, state) = EmptyBoard(db);
        var leftFront = state.CreateWithId(cardName, Side.Left, 807,
            CardLocation.BoardFrontline, 0);
        var rightFront = state.CreateWithId(cardName, Side.Right, 808,
            CardLocation.BoardFrontline, 0);
        var leftSupport = state.CreateWithId(cardName, Side.Left, 809,
            CardLocation.BoardHqLeft, 1);
        var ctx = new EffectContext
        {
            Engine = engine,
            State = state,
            Self = leftSupport,
            Controller = leftSupport.Owner,
        };

        object? raw = engine.Api.InvokeByName("GetAllCardsInFrontline", null,
            Array.Empty<object?>(), ctx, out bool handled);
        if (!handled)
        {
            return "GetAllCardsInFrontline 没进派发表";
        }

        if (raw is not System.Collections.IList list)
        {
            return $"GetAllCardsInFrontline 返回 {raw?.GetType().Name ?? "null"}，应为卡数组";
        }

        var ids = list.Cast<object?>().OfType<CardInstance>().Select(card => card.CardId).ToHashSet();
        if (!ids.SetEquals(new[] { leftFront.CardId, rightFront.CardId }))
        {
            return $"前线查询应只返回双方前线卡 {leftFront.CardId}/{rightFront.CardId}，实际=[{string.Join(",", ids.OrderBy(x => x))}]";
        }

        return null;
    }

    private static string? PinnedEventLayer(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        state.ActiveSide = Side.Left;
        var watcher = state.CreateWithId("card_unit_cromwell_mk_iv", Side.Left, 20,
            CardLocation.BoardHqLeft, 1);
        var target = state.CreateWithId("card_unit_arado_ar_196", Side.Right, 60,
            CardLocation.BoardFrontline, 1);
        var unpinWatcher = state.CreateWithId("card_event_creeping_barrage", Side.Left, 21,
            CardLocation.Discard, 0);
        engine.Api.JsonSetInt(unpinWatcher, "affectedCard", target.CardId);

        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;

        engine.Api.PinUnit(target);
        if (!target.Keywords.Contains(Keyword.Pinned))
        {
            return "PinUnit 没有写入 Pinned";
        }

        string pinTrace = $"OnOtherUnitPinned → {watcher.Name}#{watcher.CardId}";
        if (!trace.Any(t => t.StartsWith(pinTrace, StringComparison.Ordinal)
                         && t.Contains($"eventCard={target.Name}#{target.CardId}", StringComparison.Ordinal)))
        {
            return "OnOtherUnitPinned 没有把被钉目标作为事件参数传给 Cromwell";
        }

        if (!target.IsSuppressed)
        {
            return "Cromwell 收到 OnOtherUnitPinned 后没有抑制被钉目标";
        }

        engine.Api.RemoveKeyword(target, Keyword.Pinned);
        string unpinTrace = $"OnOtherUnitUnpinned → {unpinWatcher.Name}#{unpinWatcher.CardId}";
        if (!trace.Any(t => t.StartsWith(unpinTrace, StringComparison.Ordinal)
                         && t.Contains($"eventCard={target.Name}#{target.CardId}", StringComparison.Ordinal)))
        {
            return "OnOtherUnitUnpinned 没有把解除钉住的目标作为事件参数传给订阅卡";
        }

        if (target.Keywords.Contains(Keyword.Pinned) || target.Location != CardLocation.BoardHqRight)
        {
            return $"解除钉住后的订阅效果未执行：pinned={target.Keywords.Contains(Keyword.Pinned)}，位置={target.Location}";
        }

        return null;
    }

    private static string? PanzergrenadierPinnedOverrideLocalPredicate(CardDatabase db)
    {
        const string sourceName = "card_unit_14_panzergrenadier";
        const string targetName = "card_unit_arado_ar_196";
        if (db.Find(sourceName) is null) return $"卡库里缺 {sourceName}";
        if (db.Find(targetName) is null) return $"卡库里缺 {targetName}";
        var (engine, state) = EmptyBoard(db);
        var source = state.CreateWithId(sourceName, Side.Left, 20,
            CardLocation.BoardHqLeft, 1);
        var target = state.CreateWithId(targetName, Side.Left, 21,
            CardLocation.BoardHqRight, 2);
        engine.Api.PinUnit(target);
        if (engine.Api.HasCustomAbility(target, "canOperateWhilePinned"))
        {
            return "非老兵的 14th Panzergrenadier 不应授予钉住行动能力";
        }
        var tankDef = db.All.First(c => c.IsUnit && c.Type == "tank" && c.Kredits <= 6);
        var tank = state.CreateWithId(tankDef.Name, Side.Left, 22, CardLocation.HandLeft, 0);
        state.ActiveSide = Side.Left;
        state.SetKredits(Side.Left, 20);
        state.SetMaxKredits(Side.Left, 20);
        if (!engine.PlayCard(tank) || !source.Keywords.Contains(Keyword.Veteran))
        {
            return "己方部署坦克后 14th Panzergrenadier 应成为老兵";
        }
        if (!engine.Api.HasCustomAbilityFromCard(target, "canOperateWhilePinned", source.CardId))
        {
            return "当前老兵光环未向友军授予有来源的钉住行动能力";
        }
        engine.Api.CustomAbilityAdd(target, "otherAbility", tank);
        engine.Api.FireTrigger("OnLeaveBoardOrOwner", source, Side.Left);
        if (engine.Api.HasCustomAbilityFromCard(target, "canOperateWhilePinned", source.CardId)
            || !engine.Api.HasCustomAbilityFromCard(target, "otherAbility", tank.CardId))
        {
            return "离场光环应只撤销自身授予的能力，保留其它能力";
        }

        return null;
    }

    private static string? Regiment152PlayGate(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        state.ActiveSide = Side.Left;
        state.SetKredits(Side.Left, 20);
        var card = state.CreateWithId("card_unit_152e_regiment", Side.Left, 20, CardLocation.HandLeft, 0);
        state.SetMaxKredits(Side.Left, 5);
        if (engine.CanPlay(card, out var reason) || reason != "must_have_min_kredit_slots"
            || engine.PlayCard(card) || card.Location != CardLocation.HandLeft)
            return "5 槽位时必须拒绝出牌，并保留手牌";
        state.SetMaxKredits(Side.Left, 6);
        if (!engine.CanPlay(card, out _) || !engine.PlayCard(card) || !engine.Api.IsLocatedOnBoard(card))
            return "6 槽位时应允许正常部署";
        return null;
    }

    private static string? CardConstructionPublicationOrder(CardDatabase db)
    {
        const string cardName = "card_unit_panzer_iii_e";
        var state = new GameState(db, 1);
        bool visibleDuringOwn = false, duplicateRejected = false;
        int childId = -1;
        state.CardCreated = card =>
        {
            if (card.CardId != 2) return;
            visibleDuringOwn = ReferenceEquals(state.ById(2), card)
                && state.AllCardsInBattleOrder.Contains(card);
            try { state.CreateWithId(cardName, Side.Left, 2, CardLocation.DeckLeft, 0); }
            catch (InvalidOperationException) { duplicateRejected = true; }
            childId = state.Create(cardName, Side.Left, CardLocation.DeckLeft, 1, sequentialId: true).CardId;
        };
        state.CreateWithId(cardName, Side.Left, 2, CardLocation.DeckLeft, 0);
        if (!visibleDuringOwn) return "OnCreateCard 应在加入 AllCardsInBattle 后执行";
        if (!duplicateRejected || childId != 3) return "重入创建没有跳过已占用 cardID";
        if (!state.AllCardsInBattleOrder.Select(c => c.CardId).SequenceEqual(new[] { 2, 3 }))
            return "重入创建的入表顺序应先父卡、再子卡";
        if (!state.Snapshot().BattleCardOrder.SequenceEqual(new[] { 2, 3 }))
            return "状态快照丢失入表顺序";
        return null;
    }

    private static string? BattleMapAndLocationOrder(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        const string cardName = "card_unit_432_infantry_regiment";
        var first = state.CreateWithId(cardName, Side.Left, 99, CardLocation.BoardFrontline, 7);
        var second = state.CreateWithId(cardName, Side.Right, 10, CardLocation.BoardFrontline, 7);
        var ids = engine.Api.GetAllCards().Where(c => c == first || c == second).Select(c => c.CardId);
        if (!ids.SequenceEqual(new[] { 99, 10 })) return "GetAllCards 用 cardID 排序替代了入表顺序";
        engine.Api.RearrangeLocation(CardLocation.BoardFrontline);
        if (first.LocationNumber != 0 || second.LocationNumber != 1)
            return "相同 locationNumber 未按 AllCardsInBattle 的稳定顺序重排";
        return null;
    }

    private static string? ExtraKreditSlotDispatch(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        const string name = "card_unit_47th_infantry_regiment_vet";
        const string trigger = "OnAfterExtraKreditSlotGain";
        var first = state.CreateWithId(name, Side.Left, 99, CardLocation.BoardHqLeft, 1);
        var second = state.CreateWithId(name, Side.Left, 10, CardLocation.BoardHqLeft, 2);
        var unavailable = state.CreateWithId(name, Side.Left, 55, CardLocation.NotAvailable, 0);
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        int a = first.Attack, b = second.Attack;
        engine.Api.GainKreditSlot(Side.Left, 1);
        if (first.Attack != a + 4 || second.Attack != b + 4)
            return "获得额外槽位应使两个在场的老兵各增加 4 攻击";
        var hits = trace.Where(x => x.StartsWith(trigger + " → " + name, StringComparison.Ordinal)).ToArray();
        if (hits.Length != 3 || !hits[0].Contains("#99（") || !hits[1].Contains("#10（") || !hits[2].Contains("#55（"))
            return "直接全局广播未保留入表顺序或遗漏 NotAvailable 对象：" + string.Join(" | ", hits);
        second.Keywords.Add(Keyword.Suppressed);
        second.SuppressionExceptionTriggers.Add(trigger);
        trace.Clear();
        b = second.Attack;
        engine.Api.GainKreditSlot(Side.Left, 1);
        if (second.Attack != b || trace.Any(x => x.StartsWith(trigger + " → " + name + "#10（", StringComparison.Ordinal)))
            return "直接抑制门不得因 suppressionExceptionTriggers 放行";
        trace.Clear();
        var ctx = new EffectContext { Engine = engine, State = state, Self = first, Controller = Side.Left };
        a = first.Attack;
        engine.Api.InvokeByName("LoseKreditSlot", first, new object?[] { (int)Side.Left }, ctx, out bool handled);
        if (!handled || first.Attack != a || trace.Count(x => x.StartsWith(trigger + " → " + name, StringComparison.Ordinal)) != 2)
            return "失去槽位也应直接广播到未抑制对象，但不得触发正增长加攻";
        return null;
    }

    private static string? CreatedCardReceivesOwnT35(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        state.SetMaxKredits(Side.Left, 4);
        var source = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 90, CardLocation.BoardHqLeft, 1);
        var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Left };
        for (int i = 0; i < 2; i++)
            engine.Api.InvokeByName("LoseKreditSlot", source, new object?[] { (int)Side.Left }, ctx, out _);
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        int id = 91;
        foreach (var location in new[] { CardLocation.DeckLeft, CardLocation.HandLeft, CardLocation.BoardHqLeft, CardLocation.NotAvailable })
        {
            var card = state.CreateWithId("card_unit_144th_infantry_regiment", Side.Left, id++, location, 2);
            if (card.CustomJson.GetValueOrDefault("slots_lost") != "2")
                return $"新建 144 步兵团在 {location} 未继承历史槽位损失 2：" + card.CustomJson.GetValueOrDefault("slots_lost");
            if (!trace.Any(x => x.StartsWith($"OnOtherCardCreatedAlterCard → {card.Name}#{card.CardId}（", StringComparison.Ordinal)
                && x.Contains($"eventCard={card.Name}#{card.CardId}）", StringComparison.Ordinal)))
                return "T35 没有派发给新卡自身";
        }
        var enemy = state.CreateWithId("card_unit_144th_infantry_regiment", Side.Right, 96, CardLocation.HandRight, 0);
        if (enemy.CustomJson.GetValueOrDefault("slots_lost") != "0") return "历史槽位损失串到另一方";
        var board = state.ById(93)!;
        int hp = state.HqDefense(Side.Right);
        engine.Destroy(board);
        if (state.HqDefense(Side.Right) != hp - 2) return "创建前的两次槽位损失未计入 144 步兵团摧毁伤害";
        return null;
    }

    private static string? OperationEventControlFlow(CardDatabase db)
    {
        foreach (bool suppressOperated in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.ActiveSide = Side.Left;
            state.SetKredits(Side.Left, 9);
            const string name = "card_unit_182_landwehr";
            var operated = state.CreateWithId(name, Side.Left, 101, CardLocation.BoardHqLeft, 1);
            var watcher = state.CreateWithId(name, Side.Left, 102, CardLocation.BoardHqLeft, 2);
            var suppressedWatcher = state.CreateWithId(name, Side.Left, 103, CardLocation.BoardHqLeft, 3);
            operated.EnteredPlayOnTurn = state.Turn - 1;
            engine.Api.MakeVeteran(watcher);
            engine.Api.MakeVeteran(suppressedWatcher);
            suppressedWatcher.Keywords.Add(Keyword.Suppressed);
            suppressedWatcher.SuppressionExceptionTriggers.Add("OnOtherCardOperationKreditsSpent");
            if (suppressOperated) operated.Keywords.Add(Keyword.Suppressed);
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            if (!engine.MoveUnit(operated, 0, out string reason)) return reason;
            var events = trace.Where(x => x.StartsWith("OnOperationKreditsSpent →", StringComparison.Ordinal)
                || x.StartsWith("OnOtherCardOperationKreditsSpent →", StringComparison.Ordinal)).ToArray();
            if (state.Kredits(Side.Left) != 9) return "旁观老兵应返还行动费，包括操作者被抑制时";
            if (suppressOperated)
            {
                if (events.Length != 1 || !events[0].Contains("#102（"))
                    return "抑制操作者只跳过自身回调；未抑制旁观者仍应收到事件";
            }
            else if (events.Length != 2 || !events[0].StartsWith("OnOperationKreditsSpent →", StringComparison.Ordinal)
                || !events[0].Contains("#101（") || !events[1].Contains("#102（"))
                return "行动费事件应先自身、再旁观，直接抑制门不得接受旁观者例外：" + string.Join(" | ", events);
        }
        return null;
    }

    private static string? DeploymentQuerySnapshot(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        const string name = "card_unit_b_26_marauder";
        const string trigger = "OnDeploymentEffectTriggered";
        var first = state.CreateWithId(name, Side.Left, 20, CardLocation.BoardHqLeft, 1);
        var initiallySuppressed = state.CreateWithId(name, Side.Left, 21, CardLocation.BoardHqLeft, 2);
        var laterSuppressed = state.CreateWithId(name, Side.Left, 22, CardLocation.BoardHqLeft, 3);
        var unavailable = state.CreateWithId(name, Side.Left, 23, CardLocation.NotAvailable, 0);
        initiallySuppressed.Keywords.Add(Keyword.Suppressed);
        var selected = engine.Api.CaptureRegisteredTriggerSnapshot(trigger);
        var seed = new Dictionary<string, object?> { ["cardTriggered"] = first, ["instigatorID"] = first.CardId };
        var hits = engine.Api.BroadcastWithOutParams(trigger, first, Side.Left, new[] { "TriggerMultiple" },
            seed: seed, namedArgs: seed, only: selected, recipientsAlreadyFiltered: true,
            seedFactory: receiver =>
            {
                if (ReferenceEquals(receiver, first))
                {
                    initiallySuppressed.Keywords.Remove(Keyword.Suppressed);
                    laterSuppressed.Keywords.Add(Keyword.Suppressed);
                }
                return seed;
            });
        if (!hits.Select(x => x.Card.CardId).SequenceEqual(new[] { 20, 22, 23 }))
            return "T23 应保持查询时对象数组，不补入后来解除抑制者或漏掉后来被抑制者/NotAvailable："
                + string.Join(",", hits.Select(x => x.Card.CardId));
        if (hits.Take(2).Any(x => x.Outs.GetValueOrDefault("TriggerMultiple") is not int value || value != 1)
            || hits[2].Outs.GetValueOrDefault("TriggerMultiple") is not int zero || zero != 0)
            return "实际 B-26 的在场门或倍数出参结果错误";
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        int multiple = engine.Api.SumDeploymentTriggerMultiple(first);
        if (multiple != 2 || !trace.Any(x => x.Contains(name + "#23（", StringComparison.Ordinal)))
            return "正式部署倍数入口未使用完整注册查询快照";
        return null;
    }

    private static string? DeploymentCancelShortCircuit(CardDatabase db)
    {
        foreach (bool blockerFirst in new[] { true, false })
        {
            var (engine, state) = DeploymentBoard(db);
            var source = state.CreateWithId("card_unit_10_5_cm_lefh", Side.Left, 100, CardLocation.HandLeft, 0);
            var blocker = state.CreateWithId("card_unit_petlyakov_pe_2ft", Side.Left,
                blockerFirst ? 20 : 21, CardLocation.BoardHqLeft, 1);
            var buffs = state.CreateWithId("card_unit_buffs", Side.Left,
                blockerFirst ? 21 : 20, CardLocation.BoardHqLeft, 2);
            state.CreateWithId("card_unit_petlyakov_pe_2ft", Side.Right, 22, CardLocation.BoardHqRight, 1);
            source.CurrentTarget = buffs;
            int attack = buffs.Attack, defense = buffs.Defense;
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            if (!engine.Api.FireDeploymentCancelHook(source)) return "在场 Pe-2FT 应取消部署效果";
            int bonus = blockerFirst ? 0 : 1;
            if (buffs.Attack != attack + bonus || buffs.Defense != defense + bonus)
                return "首个取消回调之后不能再给 BUFFS 加攻防；之前的 false 回调仍应保留增益";
            var hits = trace.Where(x => x.StartsWith("OnBeforeOtherCardDeploymentTrigger(out", StringComparison.Ordinal)).ToArray();
            if (hits.Length != (blockerFirst ? 1 : 2) || hits.Any(x => x.Contains("#22（", StringComparison.Ordinal)))
                return "返回 true 后仍执行了后续取消订阅者：" + string.Join(" | ", hits);
            // Also exercise a legal untargeted deployment through PlayCard.
            trace.Clear();
            int hp = state.HqDefense(Side.Right);
            if (!engine.PlayCard(source) || state.HqDefense(Side.Right) != hp)
                return "正常打出 lefh 时应落场但取消部署伤害";
            if (trace.Any(x => x.StartsWith("OnBeforeOtherCardDeploymentTrigger(out", StringComparison.Ordinal)
                && x.Contains("#22（", StringComparison.Ordinal)))
                return "正式打出入口在首个取消之后仍执行后续订阅者";
        }
        return null;
    }

    private static string? DamageModifierQueryLocation(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        state.Turn = 3;
        var source = state.CreateWithId("card_event_bombing_raid", Side.Left, 20, CardLocation.Discard, 0);
        var decree = state.CreateWithId("card_event_imperial_decree", Side.Left, 21, CardLocation.NotAvailable, 0);
        decree.EnteredPlayOnTurn = state.Turn;
        int Damage() => engine.Api.ExecuteOnDealDamageAddDamage(source, state.Hq(Side.Right), 2, false, false, false);
        if (Damage() != 3) return "全局表中的当回合 Imperial Decree 应为己方指令伤害 +1，T37 没有位置门";
        decree.CustomJson.Set("affectedCardID", source.CardId.ToString(), CardJsonType.Number);
        if (Damage() != 3) return "匹配 affectedCardID 时应加伤";
        decree.CustomJson.Set("affectedCardID", "999", CardJsonType.Number);
        if (Damage() != 2) return "affectedCardID 不匹配时不应加伤";
        decree.CustomJson.Remove("affectedCardID");
        decree.Keywords.Add(Keyword.Suppressed);
        if (Damage() != 2) return "查询时被抑制的 Imperial Decree 应排除";
        decree.Keywords.Remove(Keyword.Suppressed);
        state.Turn++;
        if (Damage() != 2) return "生效回合已过时不应加伤";
        return null;
    }

    private static string? DamageAfterCalcDelayedCollection(CardDatabase db)
    {
        foreach (bool nfsFirst in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.ActiveSide = Side.Right;
            CardInstance nfs;
            if (nfsFirst)
            {
                nfs = state.CreateWithId("card_event_national_fire_service", Side.Left, 20, CardLocation.HandLeft, 0);
                state.CreateWithId("card_unit_m26_pershing", Side.Left, 21, CardLocation.BoardFrontline, 0);
            }
            else
            {
                state.CreateWithId("card_unit_m26_pershing", Side.Left, 20, CardLocation.BoardFrontline, 0);
                nfs = state.CreateWithId("card_event_national_fire_service", Side.Left, 21, CardLocation.HandLeft, 0);
            }
            nfs.GotchaActivated = 1;
            var source = state.CreateWithId("card_event_bombing_raid", Side.Right, 60, CardLocation.Discard, 0);
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            int damage = engine.Api.ExecuteOnDealDamageAddDamageAfterCalc(source, state.Hq(Side.Left), 25, false, false, false);
            if (damage != (nfsFirst ? 1 : 19))
                return $"NFS 位于停止接收者{(nfsFirst ? "之前" : "之后")}时，伤害应为 {(nfsFirst ? 1 : 19)}，实际 {damage}";
            bool visited = trace.Any(x => x.StartsWith("OnOtherCardDealDamageAddDamageAfterCalc(out", StringComparison.Ordinal)
                && x.Contains($"card_event_national_fire_service#{nfs.CardId}（", StringComparison.Ordinal));
            if (visited != nfsFirst || nfs.GotchaActivated != (nfsFirst ? 0 : 1))
                return "未遇到的 NFS 不得延后执行/消耗，已入列的 NFS 应读取 Pershing 修正后的伤害";
        }
        return null;
    }

    private static string? BatchDamageModifierArguments(CardDatabase db)
    {
        for (int mode = 0; mode < 4; mode++)
        {
            var (engine, state) = EmptyBoard(db);
            state.ActiveSide = Side.Right;
            CardInstance? nfs = null;
            if (mode == 3) nfs = state.CreateWithId("card_event_national_fire_service", Side.Left, 20, CardLocation.HandLeft, 0);
            var pershing = state.CreateWithId("card_unit_m26_pershing", Side.Left, mode == 3 ? 21 : 20, CardLocation.BoardFrontline, 0);
            if (mode == 1) pershing.Keywords.Add(Keyword.Suppressed);
            if (mode == 2) nfs = state.CreateWithId("card_event_national_fire_service", Side.Left, 21, CardLocation.HandLeft, 0);
            if (nfs is not null) nfs.GotchaActivated = 1;
            var unit = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 30, CardLocation.BoardHqLeft, 1);
            unit.Defense = 30;
            var source = state.CreateWithId("card_event_bombing_raid", Side.Right, 60, CardLocation.Discard, 0);
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Right };
            engine.Api.InvokeByName("DamageMultipleCards", null,
                new object?[] { new List<CardInstance> { state.Hq(Side.Left), unit }, 25, source.CardId, null }, ctx, out bool handled);
            int expectedDamage = mode == 1 ? 25 : mode == 3 ? 1 : 19;
            if (!handled || state.HqDefense(Side.Left) != 20 - expectedDamage || unit.Defense != 5)
                return $"批量模式 {mode}：HQ 应受 {expectedDamage}，独立单位应受 25；实际 HQ={state.HqDefense(Side.Left)}，单位={unit.Defense}";
            if (state.IsFinished != (mode == 1)) return "抑制 Pershing 后致命批量伤害应结束对局";
            if (nfs is not null && nfs.GotchaActivated != (mode == 3 ? 0 : 1))
                return "批量路径应直接遍历 NFS；Pershing 停止后的 NFS 不应触发";
        }
        return null;
    }

    private static string? BatchDeathLocationRefresh(CardDatabase db)
    {
        foreach (bool frontline in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            const string name = "card_unit_432_infantry_regiment";
            var location = frontline ? CardLocation.BoardFrontline : CardLocation.BoardHqLeft;
            var first = state.CreateWithId(name, Side.Left, 20, location, frontline ? 0 : 1);
            var dead1 = state.CreateWithId(name, Side.Left, 21, location, frontline ? 1 : 2);
            var dead2 = state.CreateWithId(name, frontline ? Side.Right : Side.Left, 22, location, frontline ? 2 : 3);
            var last = state.CreateWithId(name, frontline ? Side.Right : Side.Left, 23, location, frontline ? 3 : 4);
            dead1.Defense = dead2.Defense = 1;
            var source = state.CreateWithId("card_event_bombing_raid", Side.Right, 100, CardLocation.Discard, 0);
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Right };
            var destroyed = engine.Api.InvokeByName("DamageMultipleCards", null,
                new object?[] { new List<CardInstance> { dead1, dead2 }, 1, source.CardId, null }, ctx, out bool handled);
            if (!handled || destroyed is not int[] ids || !ids.SequenceEqual(new[] { 21, 22 }))
                return "批量死亡返回的对象 ID 不符";
            if (dead1.Location != CardLocation.Discard || dead2.Location != CardLocation.Discard)
                return "两张死亡卡应全部进入弃牌";
            if (first.LocationNumber != (frontline ? 0 : 1) || last.LocationNumber != (frontline ? 1 : 2))
                return $"{location} 的存活者编号未连续刷新：{first.LocationNumber},{last.LocationNumber}";
            if (first.Location != location || last.Location != location)
                return "刷新编号不应移动存活单位";
        }
        return null;
    }

    private static string? DestructionRecipientSnapshot(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        var victim = state.CreateWithId("card_unit_hayabusa", Side.Left, 20, CardLocation.Discard, 0);
        var watcher = state.CreateWithId("card_unit_matsumoto_regiment", Side.Left, 21, CardLocation.NotAvailable, 0);
        var batch = new[] { victim.CardId, watcher.CardId };
        var selected = engine.Api.CaptureRegisteredTriggerSnapshot("OnDestructionEffectTriggered");
        watcher.Keywords.Add(Keyword.Suppressed); // Change after selection, before callback execution.
        int hp = state.HqDefense(Side.Right);
        engine.Api.FireDestructionEffectTriggered(victim, null, batch, selected);
        if (state.HqDefense(Side.Right) != hp - 1)
            return "已选中的松本联队应凭 SelfAlsoDestroyed 执行，不得再因位置/抑制过滤";
        hp = state.HqDefense(Side.Right);
        engine.Api.FireDestructionEffectTriggered(victim, null, batch);
        if (state.HqDefense(Side.Right) != hp) return "重新查询时已抑制的接收者应排除";
        victim.Keywords.Add(Keyword.Suppressed);
        engine.Api.FireDestructionEffectTriggered(victim, null, batch, selected);
        if (state.HqDefense(Side.Right) != hp) return "触发主体抑制门未生效";
        engine.Api.FireDestructionEffectTriggered(victim, null, batch, selected, skipSuppressCheck: true);
        if (state.HqDefense(Side.Right) != hp - 1) return "skipSuppressCheck 应仅绕过主体抑制门";
        return null;
    }

    private static string? OtherDestroyedSuppressionQuery(CardDatabase db)
    {
        for (int mode = 0; mode < 4; mode++)
        {
            var (engine, state) = EmptyBoard(db);
            var hudson = state.CreateWithId("card_unit_hudson", Side.Left, 20,
                mode == 3 ? CardLocation.NotAvailable : CardLocation.BoardHqLeft, 1);
            var victim = state.CreateWithId("card_unit_432_infantry_regiment", Side.Right, 60, CardLocation.BoardHqRight, 1);
            if (hudson.HasFury) return "Hudson 初始不应已有 Fury";
            if (mode is 1 or 2) hudson.Keywords.Add(Keyword.Suppressed);
            if (mode == 2) hudson.SuppressionExceptionTriggers.Add("OnOtherCardDestroyed");
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            engine.Destroy(victim, hudson);
            bool expected = mode != 1;
            if (mode != 3 && hudson.HasFury != expected)
                return $"Hudson 模式 {mode} 的 Fury 应为 {expected}，T39 查询抑制/位置门不符";
            if (mode != 3 && expected && (hudson.Keywords.Contains(Keyword.Fury)
                || !hudson.ReceivedAbilitiesFromCards["fury"].SequenceEqual(new[] { 20 })
                || hudson.BuffsBySource[(20, false)].Fury != 1))
                return "Hudson击杀Fury应记录自身来源而非原始标志";
            bool received = trace.Any(x => x.StartsWith("OnOtherCardDestroyed → card_unit_hudson#20（", StringComparison.Ordinal));
            if (received != expected) return "T39 接收轨迹与查询结果不符";
        }
        return null;
    }

    private static string? ExternalDestructionProviderRepeat(CardDatabase db)
    {
        foreach (var (doubled, drawProvider) in new[] { (false, false), (true, false), (true, true) })
        {
            var (engine, state) = DeploymentBoard(db);
            var victim = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 20, CardLocation.BoardHqLeft, 1);
            if (doubled)
            {
                state.CreateWithId("card_unit_114th_infantry_regiment", Side.Left, 21, CardLocation.BoardHqLeft, 2);
                state.CreateWithId("card_unit_matsumoto_regiment", Side.Left, 22, CardLocation.BoardHqLeft, 3);
            }
            var provider = state.CreateWithId("card_event_special_attack", Side.Left, 30, CardLocation.HandLeft, 0);
            if (!engine.PlayCard(provider)) return "Special Attack 应可打出";
            if (!engine.Api.HasCustomAbilityFromCard(victim, "destruction", provider.CardId))
                return "实际打出 Special Attack 未为目标记录提供者 destruction 能力";
            CardInstance? greater = null;
            if (drawProvider)
            {
                greater = state.CreateWithId("card_event_greater_purpose", Side.Left, 31, CardLocation.HandLeft, 0);
                if (!engine.PlayCard(greater) || !engine.Api.HasCustomAbilityFromCard(victim, "destruction", greater.CardId))
                    return "第二个真实提供者 Greater Purpose 未正确叠加来源能力";
                state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 70, CardLocation.DeckLeft, 0);
                state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 71, CardLocation.DeckLeft, 1);
            }
            int hand = state.Hand(Side.Left).Count();
            int slots = state.MaxKredits(Side.Left), hp = state.HqDefense(Side.Right);
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            engine.Destroy(victim);
            int repeat = doubled ? 2 : 1;
            if (state.MaxKredits(Side.Left) != slots + repeat)
                return "外部摧毁提供者的 GainKreditSlot 未按 T24 倍数执行";
            int expectedDamage = doubled ? (drawProvider ? 6 : 4) : 1;
            if (state.HqDefense(Side.Right) != hp - expectedDamage)
                return $"外部摧毁和松本通知应合计造成 {expectedDamage}，实际 {hp - state.HqDefense(Side.Right)}";
            int calls = trace.Count(x => x.StartsWith($"OnOtherCardDestroyed → {provider.Name}#{provider.CardId}（", StringComparison.Ordinal));
            if (calls != repeat) return $"提供者应只执行 {repeat} 次，实际 {calls}";
            if (greater is not null)
            {
                int draws = trace.Count(x => x.StartsWith($"OnOtherCardDestroyed → {greater.Name}#{greater.CardId}（", StringComparison.Ordinal));
                if (draws != repeat || state.Hand(Side.Left).Count() != hand + repeat)
                    return "两个提供者共存时 Greater Purpose 应独立执行两次并抽两张牌";
            }
            if (victim.Location != CardLocation.Discard || provider.Location != CardLocation.Discard)
                return "死亡单位和已打出提供者都应留在弃牌堆";
        }
        return null;
    }

    private static string? BeforeDestroyedRecipientQuery(CardDatabase db)
    {
        for (int mode = 0; mode < 5; mode++)
        {
            var (engine, state) = EmptyBoard(db);
            var marder = state.CreateWithId("card_unit_marder_iii_h", Side.Left, 20,
                mode == 0 ? CardLocation.BoardHqLeft : CardLocation.NotAvailable, 1);
            var other = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 21, CardLocation.BoardHqLeft, 2);
            var victim = state.CreateWithId("card_unit_432_infantry_regiment", Side.Right, 60, CardLocation.BoardHqRight, 1);
            var draw = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 70, CardLocation.DeckLeft, 0);
            if (mode >= 3) marder.Keywords.Add(Keyword.Suppressed);
            if (mode == 4) marder.SuppressionExceptionTriggers.Add("OnBeforeOtherCardDestroyed");
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            engine.Destroy(victim, mode is 0 or 2 ? other : marder);
            bool expectedDraw = mode is 0 or 1 or 4;
            if ((draw.Location == CardLocation.HandLeft) != expectedDraw)
                return $"Marder 模式 {mode} 应抽牌={expectedDraw}，实际 {draw.Location}";
            bool received = trace.Any(x => x.StartsWith("OnBeforeOtherCardDestroyed → card_unit_marder_iii_h#20（", StringComparison.Ordinal));
            if (received != (mode != 3)) return "T15 接收轨迹不符合注册/抑制查询结果";
        }
        return null;
    }

    private static string? LeaveMethodPayload(CardDatabase db)
    {
        foreach (int method in new[] { 1, 5, 6, 0, 3 })
        {
            var (engine, state) = EmptyBoard(db);
            state.SetMaxKredits(Side.Left, 12);
            state.SetKredits(Side.Left, 5);
            var watcher = state.CreateWithId("card_unit_dornier_do_17", Side.Left, 20, CardLocation.BoardHqLeft, 1);
            var victim = state.CreateWithId("card_unit_432_infantry_regiment", Side.Right, 60, CardLocation.BoardHqRight, 1);
            var draw = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 70, CardLocation.DeckLeft, 0);
            if (method == 1) engine.Destroy(victim);
            else engine.FireLeaveTrigger(victim, method == 5 ? CardLocation.HandRight : CardLocation.Discard, method);
            bool expected = method is not (1 or 5 or 6);
            if (state.Kredits(Side.Left) != (expected ? 7 : 5)
                || (draw.Location == CardLocation.HandLeft) != expected)
                return $"离场方法 {method} 的 Dornier 奖励应触发={expected}，实际费用={state.Kredits(Side.Left)}，牌位置={draw.Location}";
            // The card's JSON field-presence guard also makes the reward once-only.
            engine.FireLeaveTrigger(victim, CardLocation.Discard, method);
            if (state.Kredits(Side.Left) != (expected ? 7 : 5)) return "Dornier 不应重复发放奖励";
        }
        return null;
    }

    private static string? LeaveObserverQueryBoundary(CardDatabase db)
    {
        for (int mode = 0; mode < 3; mode++)
        {
            var (engine, state) = EmptyBoard(db);
            var before = state.CreateWithId("card_unit_dornier_do_17", Side.Left, 20, CardLocation.NotAvailable, 0);
            var after = state.CreateWithId("card_unit_panzer_iii_e", Side.Left, 21, CardLocation.NotAvailable, 0);
            if (mode != 0)
            {
                before.Keywords.Add(Keyword.Suppressed);
                after.Keywords.Add(Keyword.Suppressed);
            }
            if (mode == 2)
            {
                before.SuppressionExceptionTriggers.Add("OnOtherCardLeaveBoardOrOwner");
                after.SuppressionExceptionTriggers.Add("OnAfterOtherCardLeaveBoardOrOwner");
            }
            var victim = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 60, CardLocation.BoardHqLeft, 1);
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            engine.Destroy(victim);
            bool expected = mode != 1;
            if (trace.Any(x => x.StartsWith("OnOtherCardLeaveBoardOrOwner → card_unit_dornier_do_17#20（", StringComparison.Ordinal)) != expected
                || trace.Any(x => x.StartsWith("OnAfterOtherCardLeaveBoardOrOwner → card_unit_panzer_iii_e#21（", StringComparison.Ordinal)) != expected)
                return $"T46/T8 模式 {mode} 的回调名单不符合无位置门的查询契约";
        }
        return null;
    }

    private static string? SpecificDrawExactMembership(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var requested = state.CreateWithId("card_unit_432_infantry_regiment", side, 60, side.HandOf(), 0);
            var sameName = state.CreateWithId(requested.Name, side, 61, side.DeckOf(), 0);
            int actions = state.ActionLog.Count;
            var context = new EffectContext { Engine = engine, State = state, Self = requested, Controller = side };
            engine.Api.InvokeByName("DrawSpecificCardFromDeckBySide", requested,
                new object?[] { 0, requested.CardId, (int)side, false }, context, out _);
            if (sameName.Location != side.DeckOf() || requested.Location != side.HandOf()
                || state.ActionLog.Count != actions || state.Fatigue(side) != 0)
                return "指定ID不在牌库时不应按名称改抽其它实例或产生动作";
        }
        return null;
    }

    // Synthetic event: draw one card to probe the response phase. It does not
    // assert that the named live card implements this event.
    private static IDisposable InstallSelectionDrawProbe(string name, string trigger)
    {
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(name, trigger) is not null)
            throw new InvalidOperationException("无法安全安装选择回复探针");
        // Local programs are cached; scope cache entries as well as IR so
        // different temporary audit probes cannot execute one another's bodies.
        var cache = (Dictionary<string, Dictionary<string, KismetProgram>>)typeof(KismetLibrary)
            .GetField("_localCache", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic)!
            .GetValue(KismetLibrary.Default)!;
        KismetProgram? previous = null;
        if (cache.TryGetValue(name, out var programs)) programs.Remove(trigger, out previous);
        locals.Add(trigger, new[] {
            new KismetStep(0, "call", "DrawCardsFromDeckBySide", new[] {
                new KismetExpr { Int = 20 }, new KismetExpr { Var = "side", Scope = "instance" },
                new KismetExpr { Int = 1 }, new KismetExpr { Bool = false }, new KismetExpr { Bool = false }
            }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        return new AuditProbeCleanup(() => {
            locals.Remove(trigger);
            if (cache.TryGetValue(name, out var current))
            {
                current.Remove(trigger);
                if (previous is not null) current[trigger] = previous;
            }
        });
    }

    private static string? FuryGrantQuota(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int count in new[] { 0, 1, 2, 3 })
        foreach (int left in new[] { -1, 0, 1, 2, 5 })
        foreach (bool had in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var card = MakeActionQuotaProbe(state, side, "infantry");
            if (had) card.Keywords.Add(Keyword.Fury);
            card.AttacksThisTurn = count; card.SetRemainingAttacks(left);
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            engine.Api.InvokeByName("GiveFury", card, new object?[] { 60, 0 }, ctx, out _);
            int expected = left + (!had && count < 2 && (count == 1 || left > 0) ? 1 : 0);
            int actions = state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionGiveFury");
            if (!card.Keywords.Contains(Keyword.Fury) || card.RemainingAttacks != expected || card.AttacksThisTurn != count
                || actions != (had ? 0 : 1)) return $"GiveFury额度错误：{side} 已有{had} count={count} left={left} 实际={card.RemainingAttacks}";
            engine.Api.InvokeByName("GiveFury", card, new object?[] { 60, 0 }, ctx, out _);
            if (card.RemainingAttacks != expected || state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionGiveFury") != actions)
                return "重复无来源GiveFury应无额外额度或通知";
        }
        return null;
    }

    private static string? FuryRemoveQuota(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int count in new[] { 0, 1, 2 })
        foreach (int left in new[] { -2, 0, 1, 2, 5 })
        foreach (bool skip in new[] { false, true })
        foreach (bool had in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var card = MakeActionQuotaProbe(state, side, "infantry");
            if (had) card.Keywords.Add(Keyword.Fury);
            card.AttacksThisTurn = count; card.SetRemainingAttacks(left);
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            engine.Api.InvokeByName("RemoveFury", card, new object?[] { 60, 0, skip }, ctx, out _);
            int expected = !had ? left : count != 0 ? 0 : Math.Min(left, 1);
            if (card.Keywords.Contains(Keyword.Fury) || card.RemainingAttacks != expected || card.AttacksThisTurn != count
                || state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionRemoveFury") != (had && !skip ? 1 : 0))
                return $"RemoveFury额度错误：{side} 已有{had} skip={skip} count={count} left={left} 实际={card.RemainingAttacks}";
        }
        return null;
    }

    private static string? FuryQuotaBoundaries(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            foreach (var location in new[] { side.HqOf(), side.HandOf(), side.DeckOf(), CardLocation.Discard, CardLocation.NotAvailable })
            {
                var (engine, state) = EmptyBoard(db);
                var card = state.CreateWithId("card_unit_432_infantry_regiment", side, 60, location, 1);
                engine.Api.GiveKeyword(card, Keyword.Fury);
                var action = state.ActionLog.SelectMany(x => x.SubActions).SingleOrDefault(x => x.Name == "ZActionGiveFury");
                if (!card.Keywords.Contains(Keyword.Fury) || card.RemainingAttacks != 2
                    || (action is null) != (location == side.DeckOf())
                    || action is not null && (action.Values.First(x => x.Name == "cardID").Value != 60
                        || action.Values.First(x => x.Name == "giverID").Value != 0))
                    return "GiveFury只按有效对象与可增益门处理，牌库省略给予通知";
            }
            {
                var (engine, state) = EmptyBoard(db); var card = MakeActionQuotaProbe(state, side, "infantry");
                card.Keywords.Add(Keyword.Covert);
                engine.Api.GiveKeyword(card, Keyword.Fury);
                if (card.Keywords.Contains(Keyword.Fury) || card.RemainingAttacks != 1) return "未揭示场上Covert不能获得Fury";
            }
            {
                var (engine, state) = EmptyBoard(db); var card = MakeActionQuotaProbe(state, side, "infantry");
                var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
                engine.Api.InvokeByName("GiveFury", card, new object?[] { 9999, 0 }, ctx, out _);
                card.Keywords.Add(Keyword.Fury); card.SetRemainingAttacks(2);
                engine.Api.InvokeByName("RemoveFury", card, new object?[] { 9999, 0, false }, ctx, out _);
                if (!card.Keywords.Contains(Keyword.Fury) || card.RemainingAttacks != 2 || state.ActionLog.Count != 0)
                    return "无效Fury目标不得回落到施动卡";
            }
            {
                var (engine, state) = EmptyBoard(db); var card = MakeActionQuotaProbe(state, side, "infantry");
                card.Keywords.Add(Keyword.Fury); card.SetRemainingAttacks(2);
                engine.Api.InvokeByName("RemoveFury", card, new object?[] { 60, -7, false },
                    new EffectContext { Engine = engine, State = state, Self = card, Controller = side }, out _);
                var action = state.ActionLog.SelectMany(x => x.SubActions).Single(x => x.Name == "ZActionRemoveFury");
                if (card.RemainingAttacks != 1 || action.Values.First(x => x.Name == "giverID").Value != -7)
                    return "全量RemoveFury必须保留非正原始giverID";
            }
            foreach (var sample in new[] { (0, 2), (0, 0), (1, 1), (1, 0), (2, 0), (2, -1) })
            {
                var (engine, state) = EmptyBoard(db); var card = MakeActionQuotaProbe(state, side, "infantry");
                card.Keywords.Add(Keyword.Fury); card.AttacksThisTurn = sample.Item1; card.SetRemainingAttacks(sample.Item2);
                engine.Api.SuppressUnit(card);
                int expected = sample.Item1 != 0 ? 0 : Math.Min(sample.Item2, 1);
                if (!card.IsSuppressed || card.Keywords.Contains(Keyword.Fury) || card.RemainingAttacks != expected
                    || card.AttacksThisTurn != sample.Item1) return "抑制摘除Fury必须应用同样额度契约";
            }
        }
        return null;
    }

    private static string? FurySourceGrant(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int count in new[] { 0, 1, 2, 3 })
        foreach (int left in new[] { -1, 0, 1, 3 })
        foreach (bool intrinsic in new[] { false, true })
        foreach (int prior in new[] { 0, 71, 72 })
        foreach (int giver in new[] { 71, -7 })
        {
            var (engine, state) = EmptyBoard(db);
            var card = MakeActionQuotaProbe(state, side, "infantry");
            if (intrinsic) card.Keywords.Add(Keyword.Fury);
            if (prior != 0)
            {
                card.ReceivedAbilitiesFromCards["fury"] = new List<int> { prior };
                card.BuffsBySource[(prior, false)] = new CardBuff { SourceCardId = prior, Fury = 1 };
            }
            card.AttacksThisTurn = count; card.SetRemainingAttacks(left);
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            engine.Api.InvokeByName("GiveFury", card, new object?[] { 60, giver }, ctx, out _);
            bool duplicate = prior == giver;
            bool had = intrinsic || prior != 0;
            int expected = left + (!duplicate && !had && count < 2 && (count == 1 || left > 0) ? 1 : 0);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionGiveFury").ToArray();
            if (!card.HasFury || card.Keywords.Contains(Keyword.Fury) != intrinsic
                || card.RemainingAttacks != expected || card.AttacksThisTurn != count
                || !card.ReceivedAbilitiesFromCards["fury"].SequenceEqual(prior == 0 ? new[] { giver }
                    : duplicate ? new[] { prior } : new[] { prior, giver })
                || card.BuffsBySource[(giver, false)].Fury != 1
                || actions.Length != (duplicate ? 0 : 1)
                || actions.Length > 0 && (actions[0].Values.First(x => x.Name == "cardID").Value != 60
                    || actions[0].Values.First(x => x.Name == "giverID").Value != giver))
                return $"来源GiveFury错误：{side} count={count} left={left} intrinsic={intrinsic} prior={prior} giver={giver}";
            engine.Api.InvokeByName("GiveFury", card, new object?[] { 60, giver }, ctx, out _);
            if (card.RemainingAttacks != expected || card.BuffsBySource[(giver, false)].Fury != 1
                || state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionGiveFury") != actions.Length)
                return "重复来源应完全无效";
        }
        return null;
    }

    private static string? FurySourceRemove(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int count in new[] { 0, 1, 2 })
        foreach (int left in new[] { -2, 0, 1, 3 })
        foreach (bool intrinsic in new[] { false, true })
        foreach (bool other in new[] { false, true })
        foreach (bool known in new[] { false, true })
        foreach (bool skip in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var card = MakeActionQuotaProbe(state, side, "infantry");
            if (intrinsic) card.Keywords.Add(Keyword.Fury);
            var sources = new List<int>();
            if (known) sources.Add(71);
            if (other) sources.Add(72);
            card.ReceivedAbilitiesFromCards["fury"] = sources;
            card.BuffsBySource[(71, false)] = new CardBuff { SourceCardId = 71, Fury = known ? 1 : 0, Attack = 4 };
            if (other) card.BuffsBySource[(72, false)] = new CardBuff { SourceCardId = 72, Fury = 1 };
            card.AttacksThisTurn = count; card.SetRemainingAttacks(left);
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            engine.Api.InvokeByName("RemoveFury", card, new object?[] { 60, 71, skip }, ctx, out _);
            bool remains = intrinsic || other;
            int expected = !known || remains ? left : count != 0 ? 0 : Math.Min(left, 1);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionRemoveFury").ToArray();
            if (card.HasFury != remains || card.Keywords.Contains(Keyword.Fury) != intrinsic
                || card.RemainingAttacks != expected || card.AttacksThisTurn != count
                || !card.ReceivedAbilitiesFromCards["fury"].SequenceEqual(other ? new[] { 72 } : Array.Empty<int>())
                || card.BuffsBySource[(71, false)].Fury != 0 || card.BuffsBySource[(71, false)].Attack != 4
                || other && card.BuffsBySource[(72, false)].Fury != 1
                || actions.Length != (known && !skip ? 1 : 0)
                || actions.Length > 0 && (actions[0].Values.First(x => x.Name == "cardID").Value != 60
                    || actions[0].Values.First(x => x.Name == "giverID").Value != 71))
                return $"来源RemoveFury错误：{side} count={count} left={left} intrinsic={intrinsic} other={other} known={known} skip={skip}";
        }
        return null;
    }

    private static string? FurySourceMixed(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int count in new[] { 0, 1, 2 })
        foreach (int left in new[] { 0, 1, 3 })
        {
            var (engine, state) = EmptyBoard(db);
            var card = MakeActionQuotaProbe(state, side, "infantry");
            engine.Api.GiveFury(card, 71);
            card.AttacksThisTurn = count; card.SetRemainingAttacks(left);
            // Raw hasFury remains false even though getHasFury is already true.
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            var steps = new KismetStep[] {
                new(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = "hasFury" }, null, -1, "__probe", null),
                new(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
            };
            var bag = engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0), ctx, null, "__probe");
            var effective = engine.Api.InvokeByName("getHasFury", card, Array.Empty<object?>(), ctx, out _);
            var combat = engine.Api.InvokeByName("GetCombatKeywords", card, Array.Empty<object?>(), ctx, out _);
            if (!Equals(bag.GetValueOrDefault("__probe"), false) || !Equals(effective, true)
                || combat is not object?[] values || values[0] is not List<int> keywords || !keywords.Contains(3))
                return "原始hasFury与有效getHasFury/战斗关键字必须分开读取";
            engine.Api.GiveFury(card); // Intrinsic branch does not capture effective alreadyHadFury.
            int expected = left + (count < 2 && (count == 1 || left > 0) ? 1 : 0);
            if (!card.Keywords.Contains(Keyword.Fury) || card.RemainingAttacks != expected)
                return "先来源后零来源应按原始标志执行给予额度门";
            engine.Api.RemoveFury(card, 71);
            if (!card.HasFury || card.RemainingAttacks != expected || card.BuffsBySource.Count != 0)
                return "撤最后来源不得撤销已经独立给予的固有Fury";
            engine.Api.GiveFury(card, -7);
            engine.Api.GiveFury(card, 72);
            // Removing a nonpositive ID means global removal, not single negative-source removal.
            engine.Api.RemoveFury(card, -7, skipAction: true);
            int capped = count != 0 ? 0 : Math.Min(expected, 1);
            if (card.HasFury || card.Keywords.Contains(Keyword.Fury) || card.RemainingAttacks != capped
                || card.ReceivedAbilitiesFromCards.ContainsKey("fury") || card.BuffsBySource.Count != 0)
                return "全量移除应清原始标志、所有来源及对应Fury增益";
        }
        // Native getter reads the source array, not the independent numeric buff entry.
        {
            var (engine, state) = EmptyBoard(db); var card = MakeActionQuotaProbe(state, Side.Left, "infantry");
            card.BuffsBySource[(71, false)] = new CardBuff { SourceCardId = 71, Fury = 1 };
            if (card.HasFury) return "仅增益账本不能替代来源数组";
            card.ReceivedAbilitiesFromCards["fury"] = new List<int> { 72 };
            if (!card.HasFury) return "来源数组非空即为有效Fury，不要求数值增益同步";
            var snap = card.Snapshot();
            card.ReceivedAbilitiesFromCards["fury"].Clear(); card.BuffsBySource[(71, false)].Fury = 5;
            if (!snap.Keywords.Contains(Keyword.Fury) || snap.IntrinsicFury
                || !snap.ReceivedAbilitiesFromCards["fury"].SequenceEqual(new[] { 72 })
                || snap.FuryBuffsBySource["71/False"] != 1) return "快照必须独立保留原始/有效Fury和来源账本";
        }
        return null;
    }

    private static string? FurySourceBoundaries(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            foreach (var location in new[] { side.HqOf(), side.HandOf(), side.DeckOf(), CardLocation.Discard, CardLocation.NotAvailable })
            {
                var (engine, state) = EmptyBoard(db);
                var card = state.CreateWithId("card_unit_432_infantry_regiment", side, 60, location, 1);
                engine.Api.GiveFury(card, 71);
                int actions = state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionGiveFury");
                if (!card.HasFury || card.Keywords.Contains(Keyword.Fury) || card.RemainingAttacks != 2
                    || actions != (location == side.DeckOf() ? 0 : 1)) return "来源给予的位置/牌库通知门错误";
                engine.Api.RemoveFury(card, 71);
                if (card.HasFury || card.RemainingAttacks != 1 || card.BuffsBySource.Count != 0)
                    return "来源撤销不应受牌库/弃牌/NA位置限制";
            }
            {
                var (engine, state) = EmptyBoard(db); var card = MakeActionQuotaProbe(state, side, "infantry");
                foreach (string keyword in new[] { Keyword.Ambush, Keyword.Blitz, Keyword.Guard,
                    Keyword.HeavyArmor, Keyword.Shock, Keyword.Smokescreen }) card.Keywords.Add(keyword);
                var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
                engine.Api.InvokeByName("GiveRandomCombatKeyword", card, new object?[] { 60, 71, null, null }, ctx, out _);
                if (!card.HasFury || card.Keywords.Contains(Keyword.Fury)
                    || !card.ReceivedAbilitiesFromCards["fury"].SequenceEqual(new[] { 71 }))
                    return "随机给予Fury必须转发instigatorID，不得误走零来源";
                engine.Api.InvokeByName("GiveRandomCombatKeyword", card, new object?[] { 60, 72, null, null }, ctx, out _);
                if (!card.ReceivedAbilitiesFromCards["fury"].SequenceEqual(new[] { 71 })
                    || state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionGiveFury") != 1)
                    return "随机候选应排除来源Fury，不能重新抽到并多记来源";
            }
            {
                var (engine, state) = EmptyBoard(db); var card = MakeActionQuotaProbe(state, side, "infantry");
                card.Keywords.Add(Keyword.Covert); engine.Api.GiveFury(card, 71);
                if (card.HasFury || card.BuffsBySource.Count != 0 || card.ReceivedAbilitiesFromCards.ContainsKey("fury"))
                    return "未揭示Covert不得记录来源";
            }
            {
                var (engine, state) = EmptyBoard(db); var card = MakeActionQuotaProbe(state, side, "infantry");
                var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
                engine.Api.InvokeByName("GiveFury", card, new object?[] { 9999, 71 }, ctx, out _);
                if (card.HasFury) return "来源给予无效目标不得回落Self";
                engine.Api.GiveFury(card, 71);
                engine.Api.InvokeByName("RemoveFury", card, new object?[] { 9999, 71, false }, ctx, out _);
                if (!card.HasFury || card.RemainingAttacks != 2) return "来源撤销无效目标不得回落Self";
                engine.Api.SuppressUnit(card);
                if (card.HasFury || card.ReceivedAbilitiesFromCards.ContainsKey("fury")
                    || card.BuffsBySource.Count != 1 || !card.BuffsBySource[(card.CardId, false)].HasSuppressLedgerEntry
                    || card.BuffsBySource.Values.Any(b => b.Fury != 0) || card.RemainingAttacks != 1) return "抑制必须发现仅由来源给予的Fury并完整摘除";
                card.ResetAttributes();
                engine.Api.GiveFury(card, 72);
                card.ResetAttributes();
                if (card.HasFury || card.ReceivedAbilitiesFromCards.ContainsKey("fury") || card.BuffsBySource.Count != 0)
                    return "重置后不得残留来源Fury";
            }
        }
        return null;
    }

    private static IDisposable InstallAbilitiesChangedProbes()
    {
        const string trigger = "OnOtherCardAbilitiesChanged";
        var installed = new List<IDictionary<string, IReadOnlyList<KismetStep>>>();
        foreach (string name in new[] { "card_unit_typhoon_mk_ib", "card_event_honorifics", "card_unit_51e_regiment" })
        {
            if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
                || KismetLibrary.Default.FindProgram(name, trigger) is not null)
            {
                foreach (var prior in installed) prior.Remove(trigger);
                throw new InvalidOperationException("无法安全安装T29探针：" + name);
            }
            locals.Add(trigger, new[] {
                new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "cardChanging", Scope = "local" }, null, -1, "_auditT29Subject", null) { DestinationScope = "instance" },
                new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Math = "Add_IntInt", Args = new[] {
                        new KismetExpr { Var = "_auditT29Count", Scope = "instance" }, new KismetExpr { Int = 1 }
                    } }, null, -1, "_auditT29Count", null) { DestinationScope = "instance" },
                new KismetStep(2, "call", "SpawnCardInDeckBySide", new[] {
                    new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                    new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
                }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
            installed.Add(locals);
        }
        return new AuditProbeCleanup(() => { foreach (var locals in installed) locals.Remove(trigger); });
    }

    private static string? AbilitiesChangedSnapshot(CardDatabase db)
    {
        using var probes = InstallAbilitiesChangedProbes();
        const string trigger = "OnOtherCardAbilitiesChanged";
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int mode in Enumerable.Range(0, 22))
        {
            var (engine, state) = EmptyBoard(db);
            var first = state.CreateWithId("card_event_honorifics", side.Opposite(), 20,
                mode == 18 ? CardLocation.NotAvailable : side.Opposite().DeckOf(), 1);
            var last = state.CreateWithId("card_unit_51e_regiment", side, 21,
                mode == 6 ? CardLocation.NotAvailable : CardLocation.Discard, 2);
            var subject = state.CreateWithId("card_unit_typhoon_mk_ib", side, 60,
                mode == 19 ? CardLocation.NotAvailable : side.HandOf(), 1);
            var cards = new[] { first, last, subject };
            foreach (var card in cards)
            {
                card.Definition = new CardDefinition { Name = card.Name, UsedTriggers = new[] { trigger } };
                card.BlueprintVariables["_auditT29Count"] = 0;
            }
            if (mode == 1) state.StopFurtherActions = true;
            if (mode is 2 or 3) subject.Keywords.Add(Keyword.Suppressed);
            if (mode == 3) subject.SuppressionExceptionTriggers.Add(trigger);
            if (mode is 4 or 5) first.Keywords.Add(Keyword.Suppressed);
            if (mode == 5) first.SuppressionExceptionTriggers.Add(trigger);
            if (mode is 11 or 12 or 17) last.Keywords.Add(Keyword.Suppressed);
            if (mode is 12 or 17) last.SuppressionExceptionTriggers.Add(trigger);
            if (mode == 15) subject.Definition = new CardDefinition { Name = subject.Name };
            var called = new List<int>(); var created = state.CardCreated;
            var seen = cards.ToDictionary(x => x.CardId, _ => 0);
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name != "card_unit_routed_troops") return;
                var current = cards.Single(x => Convert.ToInt32(x.BlueprintVariables["_auditT29Count"]) > seen[x.CardId]);
                seen[current.CardId]++; called.Add(current.CardId);
                if (current != first) return;
                if (mode == 7) last.Keywords.Add(Keyword.Suppressed);
                if (mode == 8) last.Definition = new CardDefinition { Name = last.Name };
                if (mode == 9) last.Location = CardLocation.NotAvailable;
                if (mode == 10) state.StopFurtherActions = true;
                if (mode is 11 or 12) last.Keywords.Remove(Keyword.Suppressed);
                if (mode == 13)
                {
                    var late = state.CreateWithId(last.Name, side, 22, side.HqOf(), 1);
                    late.Definition = new CardDefinition { Name = late.Name, UsedTriggers = new[] { trigger } };
                    late.BlueprintVariables["_auditT29Count"] = 0;
                }
                if (mode == 14) subject.Definition = new CardDefinition { Name = subject.Name };
                if (mode == 16) subject.Location = CardLocation.NotAvailable;
                if (mode == 17) last.SuppressionExceptionTriggers.Clear();
            };
            CardInstance? changing = mode == 20 ? null : mode == 21
                ? new CardInstance { CardId = 999, Name = subject.Name, Owner = side, Definition = subject.Definition }
                : subject;
            engine.Api.TriggerTrace = new List<string>();
            engine.Api.FireAbilitiesChanged(changing);
            var expected = new List<int>();
            if (mode != 4) expected.Add(20);
            if (mode != 11) expected.Add(21);
            if (mode is not (2 or 15)) expected.Add(60);
            if (!called.SequenceEqual(expected))
                return $"T29快照错误：{side} mode={mode} 期望{string.Join(",", expected)} 实际{string.Join(",", called)}";
            foreach (int id in called)
                if (!ReferenceEquals(cards.Single(x => x.CardId == id).BlueprintVariables["_auditT29Subject"], changing))
                    return "T29必须始终携带同一个实际能力变化对象";
            if (mode == 13 && Convert.ToInt32(state.ById(22)!.BlueprintVariables["_auditT29Count"]) != 0)
                return "T29查询后新增订阅者不得加入当前批次";
            if (mode is 1 or 10 && !state.StopFurtherActions) return "T29不得重置停止标志";
        }
        return null;
    }

    private static string? AbilitiesChangedReentry(CardDatabase db)
    {
        using var probes = InstallAbilitiesChangedProbes();
        const string trigger = "OnOtherCardAbilitiesChanged";
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var first = state.CreateWithId("card_event_honorifics", side, 20, side.HqOf(), 1);
            var last = state.CreateWithId("card_unit_51e_regiment", side, 21, side.HqOf(), 2);
            var subject = state.CreateWithId("card_unit_typhoon_mk_ib", side, 60, side.HqOf(), 3);
            var cards = new[] { first, last, subject };
            foreach (var card in cards)
            {
                card.Definition = new CardDefinition { Name = card.Name, UsedTriggers = new[] { trigger } };
                card.BlueprintVariables["_auditT29Count"] = 0;
            }
            bool nested = false;
            var seen = cards.ToDictionary(x => x.CardId, _ => 0);
            var called = new List<(int Recipient, int Subject)>(); var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name != "card_unit_routed_troops") return;
                var current = cards.Single(x => Convert.ToInt32(x.BlueprintVariables["_auditT29Count"]) > seen[x.CardId]);
                seen[current.CardId]++;
                called.Add((current.CardId, ((CardInstance)current.BlueprintVariables["_auditT29Subject"]!).CardId));
                if (nested) return;
                nested = true;
                last.Keywords.Add(Keyword.Suppressed);
                engine.Api.FireAbilitiesChanged(first);
            };
            engine.Api.FireAbilitiesChanged(subject);
            // Inner query excludes last, outer query retains it. Each frame keeps its payload.
            if (!called.SequenceEqual(new[] { (20, 60), (20, 20), (60, 20), (21, 60), (60, 60) }))
                return "T29重入应分别查询并保存内外接收者/载荷：" + string.Join(",", called);
        }
        return null;
    }

    private static string? FuryAbilitiesChangedIntegration(CardDatabase db)
    {
        using var probes = InstallAbilitiesChangedProbes();
        const string trigger = "OnOtherCardAbilitiesChanged";
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool suppressed in new[] { false, true })
        foreach (bool skip in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var subject = MakeActionQuotaProbe(state, side, "infantry");
            var observer = state.CreateWithId("card_unit_51e_regiment", side.Opposite(), 21, CardLocation.NotAvailable, 1);
            observer.Definition = new CardDefinition { Name = observer.Name, UsedTriggers = new[] { trigger } };
            observer.BlueprintVariables["_auditT29Count"] = 0;
            if (suppressed) subject.Keywords.Add(Keyword.Suppressed);
            int Calls() => Convert.ToInt32(observer.BlueprintVariables["_auditT29Count"]);
            var observed = new List<string>(); var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name != "card_unit_routed_troops") return;
                string sources = string.Join(",", subject.ReceivedAbilitiesFromCards.GetValueOrDefault("fury") ?? new List<int>());
                int gives = state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionGiveFury");
                int removesSoFar = state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionRemoveFury");
                observed.Add($"{subject.HasFury}:{sources}:{gives}:{removesSoFar}");
            };
            engine.Api.GiveFury(subject, 71);
            if (Calls() != 1) return "Fury给予必须在来源写入后执行T29，变化卡抑制不挡广播";
            if (!ReferenceEquals(observer.BlueprintVariables["_auditT29Subject"], subject)
                || !subject.HasFury || subject.BuffsBySource[(71, false)].Fury != 1) return "T29载荷/来源写入不符";
            engine.Api.GiveFury(subject, 71);
            engine.Api.RemoveFury(subject, 999, skip);
            if (Calls() != 1) return "重复Fury来源和未知撤销来源不应广播T29";
            engine.Api.GiveFury(subject, 72);
            engine.Api.RemoveFury(subject, 71, skip);
            if (Calls() != 3 || !subject.HasFury) return "有效Fury不变的新来源给予/撤销仍应广播T29";
            engine.Api.RemoveFury(subject, 72, skip);
            if (Calls() != 4 || subject.HasFury) return "最后来源撤销无论skipAction都应广播T29";
            int removes = state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionRemoveFury");
            if (removes != (skip ? 0 : 2)) return "skipAction只影响移除通知";
            if (!observed.SequenceEqual(new[] { "True:71:1:0", "True:71,72:2:0",
                $"True:72:2:{(skip ? 0 : 1)}", $"False::2:{(skip ? 0 : 2)}" }))
                return "Fury来源字段与通知应在T29回调之前更新：" + string.Join(" | ", observed);
        }
        return null;
    }

    private static string? AbilitiesChangedKv1s(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var aura = state.CreateWithId("card_unit_kv_1s", side, 20, side.HqOf(), 1);
            var ally = state.CreateWithId("card_unit_432_infantry_regiment", side, 21, side.HqOf(), 2);
            var enemy = state.CreateWithId("card_unit_432_infantry_regiment", side.Opposite(), 60, side.Opposite().HqOf(), 1);
            ally.Keywords.Add(Keyword.Blitz); enemy.Keywords.Add(Keyword.Blitz);
            int allyAttack = ally.Attack, enemyAttack = enemy.Attack, auraAttack = aura.Attack;
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            engine.Api.GiveFury(aura, 71);
            if (ally.Attack != allyAttack + 1 || enemy.Attack != enemyAttack || aura.Attack != auraAttack
                || !trace.Any(x => x.StartsWith("OnOtherCardAbilitiesChanged → card_unit_kv_1s#20", StringComparison.Ordinal)))
                return "KV-1S自身变化应收到T29并更新友军关键词加成，不应增益自己或敌军";
            engine.Api.RemoveFury(aura, 71, skipAction: true);
            if (ally.Attack != allyAttack + 1) return "KV-1S重复更新不可累计已经施加的关键字攻击加成";
        }
        return null;
    }

    private static IDisposable InstallBlitzChangedProbes()
    {
        const string trigger = "OnOtherCardBlitzChanged";
        var installed = new List<IDictionary<string, IReadOnlyList<KismetStep>>>();
        foreach (string name in new[] { "card_unit_typhoon_mk_ib", "card_event_honorifics", "card_unit_51e_regiment" })
        {
            if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
                || KismetLibrary.Default.FindProgram(name, trigger) is not null)
                throw new InvalidOperationException("无法安装T33探针：" + name);
            locals.Add(trigger, new[] {
                new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "cardChanged", Scope = "local" }, null, -1, "_auditT33Subject", null) { DestinationScope = "instance" },
                new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Math = "Add_IntInt", Args = new[] {
                        new KismetExpr { Var = "_auditT33Count", Scope = "instance" }, new KismetExpr { Int = 1 }
                    } }, null, -1, "_auditT33Count", null) { DestinationScope = "instance" },
                new KismetStep(2, "call", "SpawnCardInDeckBySide", new[] {
                    new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                    new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
                }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
            installed.Add(locals);
        }
        return new AuditProbeCleanup(() => { foreach (var locals in installed) locals.Remove(trigger); });
    }

    private static string? BlitzGrantSourcesAndPhases(CardDatabase db)
    {
        using var probe = InstallAbilitiesChangedProbes();
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool deck in new[] { false, true })
        foreach (bool intrinsic in new[] { false, true })
        foreach (int prior in new[] { 0, 71, 72 })
        foreach (int giver in new[] { 0, 71, -7 })
        {
            var (engine, state) = EmptyBoard(db);
            var target = MakeActionQuotaProbe(state, side, "infantry");
            target.Location = deck ? side.DeckOf() : side.HqOf(); target.EnteredPlayOnTurn = state.Turn;
            var observer = state.CreateWithId("card_unit_51e_regiment", side.Opposite(), 21, CardLocation.NotAvailable, 1);
            observer.Definition = new CardDefinition { Name = observer.Name, UsedTriggers = new[] { "OnOtherCardAbilitiesChanged" } };
            observer.BlueprintVariables["_auditT29Count"] = 0;
            if (intrinsic) target.Keywords.Add(Keyword.Blitz);
            if (prior != 0)
            {
                target.ReceivedAbilitiesFromCards["blitz"] = new List<int> { prior };
                target.BuffsBySource[(prior, false)] = new CardBuff { SourceCardId = prior, Blitz = 1 };
            }
            var observed = new List<int>(); var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name == "card_unit_routed_troops")
                {
                    if (!target.HasBlitz) throw new InvalidOperationException("T29应在闪击写入后执行");
                    observed.Add(state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionGiveBlitz"));
                }
            };
            var ctx = new EffectContext { Engine = engine, State = state, Self = target, Controller = side };
            engine.Api.InvokeByName("GiveBlitz", target, new object?[] { 60, giver }, ctx, out _);
            bool duplicate = giver == 0 ? intrinsic : prior == giver;
            bool had = intrinsic || prior != 0;
            int notifications = !duplicate && !deck ? 1 : 0;
            int[] expected = duplicate ? Array.Empty<int>() : had ? new[] { notifications } : new[] { 0, notifications };
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionGiveBlitz").ToArray();
            if (!target.HasBlitz || target.Keywords.Contains(Keyword.Blitz) != (intrinsic || giver == 0)
                || !observed.SequenceEqual(expected) || actions.Length != notifications
                || actions.Length > 0 && (actions[0].Values.First(x => x.Name == "cardID").Value != 60
                    || actions[0].Values.First(x => x.Name == "giverID").Value != giver))
                return $"GiveBlitz来源/阶段错误：{side} deck={deck} raw={intrinsic} prior={prior} giver={giver} events={string.Join(",", observed)}";
            var sources = prior == 0 ? new List<int>() : new List<int> { prior };
            if (giver != 0 && !sources.Contains(giver)) sources.Add(giver);
            if (!(target.ReceivedAbilitiesFromCards.GetValueOrDefault("blitz") ?? new List<int>()).SequenceEqual(sources)
                || sources.Any(id => target.BuffsBySource[(id, false)].Blitz != 1)) return "闪击来源数组/数值账本不符";
            if (target.RemainingAttacks != 1 || !deck && target.HasDeploymentSickness(state)) return "来源闪击必须解除召唤失调且不改攻击额度";
            engine.Api.InvokeByName("GiveBlitz", target, new object?[] { 60, giver }, ctx, out _);
            if (!observed.SequenceEqual(expected)) return "重复来源/原始闪击不得多发T29";
        }
        return null;
    }

    private static string? BlitzRemoveSources(CardDatabase db)
    {
        using var p29 = InstallAbilitiesChangedProbes(); using var p33 = InstallBlitzChangedProbes();
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool intrinsic in new[] { false, true })
        foreach (int sourceCount in new[] { 0, 1, 2 })
        foreach (int giver in new[] { 0, -7, 71, 99 })
        foreach (bool skip in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
            var observer = state.CreateWithId("card_unit_51e_regiment", side, 21, CardLocation.NotAvailable, 1);
            observer.Definition = new CardDefinition { Name = observer.Name,
                UsedTriggers = new[] { "OnOtherCardAbilitiesChanged", "OnOtherCardBlitzChange" } };
            observer.BlueprintVariables["_auditT29Count"] = observer.BlueprintVariables["_auditT33Count"] = 0;
            if (intrinsic) target.Keywords.Add(Keyword.Blitz);
            int[] prior = new[] { 71, -7 }.Take(sourceCount).ToArray();
            target.ReceivedAbilitiesFromCards["blitz"] = prior.ToList();
            foreach (int id in prior) target.BuffsBySource[(id, false)] = new CardBuff { SourceCardId = id, Blitz = 1, Attack = 2 };
            bool accepted = giver <= 0 ? intrinsic || sourceCount > 0 : prior.Contains(giver);
            bool raw = intrinsic && !(accepted && giver <= 0);
            int[] remaining = !accepted ? prior : giver <= 0 ? Array.Empty<int>() : prior.Where(x => x != giver).ToArray();
            bool effective = raw || remaining.Length > 0;
            engine.Api.InvokeByName("RemoveBlitz", target, new object?[] { 60, true, giver, skip },
                new EffectContext { Engine = engine, State = state, Self = target, Controller = side }, out _);
            int t29 = Convert.ToInt32(observer.BlueprintVariables["_auditT29Count"]);
            int t33 = Convert.ToInt32(observer.BlueprintVariables["_auditT33Count"]);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionRemoveBlitz").ToArray();
            if (target.HasBlitz != effective || target.Keywords.Contains(Keyword.Blitz) != raw || target.RemainingAttacks != 1
                || t29 != (accepted ? 1 : 0) || t33 != (accepted && !effective ? 1 : 0)
                || actions.Length != (accepted && !skip ? 1 : 0)
                || !(target.ReceivedAbilitiesFromCards.GetValueOrDefault("blitz") ?? new List<int>()).SequenceEqual(remaining)
                || accepted && giver <= 0 && target.ReceivedAbilitiesFromCards.ContainsKey("blitz")
                || prior.Any(id => target.BuffsBySource[(id, false)].Attack != 2
                    || target.BuffsBySource[(id, false)].Blitz != (remaining.Contains(id) ? 1 : 0)))
                return $"RemoveBlitz状态错误：{side} raw={intrinsic} sources={sourceCount} giver={giver} skip={skip}";
        }
        return null;
    }

    private static string? BlitzChangedSnapshots(CardDatabase db)
    {
        using var p29 = InstallAbilitiesChangedProbes(); using var p33 = InstallBlitzChangedProbes();
        const string t33 = "OnOtherCardBlitzChange", t29 = "OnOtherCardAbilitiesChanged";
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool skip in new[] { false, true })
        foreach (int mode in Enumerable.Range(0, 14))
        {
            var (engine, state) = EmptyBoard(db);
            var first = state.CreateWithId("card_event_honorifics", side, 20, CardLocation.NotAvailable, 1);
            var last = state.CreateWithId("card_unit_51e_regiment", side, 21, CardLocation.Discard, 1);
            var target = state.CreateWithId("card_unit_typhoon_mk_ib", side, 60, side.HqOf(), 2);
            var cards = new[] { first, last, target };
            foreach (var card in cards)
            {
                card.Definition = new CardDefinition { Name = card.Name, UsedTriggers = new[] { t33, t29 } };
                card.BlueprintVariables["_auditT29Count"] = card.BlueprintVariables["_auditT33Count"] = 0;
            }
            target.Keywords.Add(Keyword.Blitz);
            if (mode == 1) state.StopFurtherActions = true;
            if (mode is 2 or 3) target.Keywords.Add(Keyword.Suppressed);
            if (mode == 3) target.SuppressionExceptionTriggers.Add(t33);
            if (mode == 4) target.Location = CardLocation.NotAvailable;
            if (mode is 7 or 8) last.Keywords.Add(Keyword.Suppressed);
            if (mode == 8) last.SuppressionExceptionTriggers.Add(t33);
            if (mode == 11) last.Definition = new CardDefinition { Name = last.Name, UsedTriggers = new[] { t29 } };
            if (mode == 12) target.Definition = new CardDefinition { Name = target.Name, UsedTriggers = new[] { t29 } };
            if (mode == 13) first.Definition = new CardDefinition { Name = first.Name, UsedTriggers = new[] { t29 } };
            var seen = cards.ToDictionary(x => x.CardId, _ => (T29: 0, T33: 0));
            var observed = new List<string>(); var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name != "card_unit_routed_troops") return;
                var current = cards.Single(x => Convert.ToInt32(x.BlueprintVariables["_auditT29Count"]) > seen[x.CardId].T29
                    || Convert.ToInt32(x.BlueprintVariables["_auditT33Count"]) > seen[x.CardId].T33);
                var prior = seen[current.CardId];
                bool is33 = Convert.ToInt32(current.BlueprintVariables["_auditT33Count"]) > prior.T33;
                seen[current.CardId] = (Convert.ToInt32(current.BlueprintVariables["_auditT29Count"]), Convert.ToInt32(current.BlueprintVariables["_auditT33Count"]));
                if (!ReferenceEquals(current.BlueprintVariables[is33 ? "_auditT33Subject" : "_auditT29Subject"], target))
                    throw new InvalidOperationException("闪击事件载荷必须保留变化对象");
                int notifications = state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionRemoveBlitz");
                observed.Add($"{(is33 ? 33 : 29)}:{current.CardId}:{notifications}");
                if (!is33 || current != first) return;
                if (mode == 5) last.Keywords.Add(Keyword.Suppressed);
                if (mode == 6) last.Definition = new CardDefinition { Name = last.Name };
                if (mode == 7) last.Keywords.Remove(Keyword.Suppressed);
                if (mode == 8) last.SuppressionExceptionTriggers.Clear();
                if (mode == 9) state.StopFurtherActions = true;
                if (mode == 10) last.Location = CardLocation.NotAvailable;
            };
            engine.Api.RemoveBlitz(target, skipAction: skip);
            var expected = new List<string>();
            if (mode != 13) expected.Add("33:20:0");
            if (mode is not (7 or 11)) expected.Add("33:21:0");
            if (mode is not (2 or 12)) expected.Add("33:60:0");
            expected.Add($"29:20:{(skip ? 0 : 1)}");
            if (mode is not (5 or 6 or 8)) expected.Add($"29:21:{(skip ? 0 : 1)}");
            if (mode is not (2 or 3)) expected.Add($"29:60:{(skip ? 0 : 1)}");
            if (!observed.SequenceEqual(expected)) return $"T33阶段/查询错误：{side} mode={mode} skip={skip} 实际{string.Join(",", observed)}";
            if (mode is 1 or 9 && !state.StopFurtherActions) return "T33不得重置或消费停止标志";
        }
        return null;
    }

    private static string? BlitzGrantReentry(CardDatabase db)
    {
        using var probes = InstallAbilitiesChangedProbes();
        const string trigger = "OnOtherCardAbilitiesChanged";
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int mode in new[] { 0, 1, 2, 3 })
        {
            var (engine, state) = EmptyBoard(db);
            var target = MakeActionQuotaProbe(state, side, "infantry");
            var first = state.CreateWithId("card_event_honorifics", side, 20, side.HqOf(), 1);
            var last = state.CreateWithId("card_unit_51e_regiment", side, 21, side.HqOf(), 2);
            var cards = new[] { first, last };
            foreach (var card in cards)
            {
                card.Definition = new CardDefinition { Name = card.Name, UsedTriggers = new[] { trigger } };
                card.BlueprintVariables["_auditT29Count"] = 0;
            }
            var seen = cards.ToDictionary(x => x.CardId, _ => 0);
            var observed = new List<string>(); var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name != "card_unit_routed_troops") return;
                var current = cards.Single(x => Convert.ToInt32(x.BlueprintVariables["_auditT29Count"]) > seen[x.CardId]);
                seen[current.CardId]++;
                int notifications = state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionGiveBlitz");
                observed.Add($"{current.CardId}:{notifications}");
                if (current != first || seen[20] != 1) return;
                if (mode == 0) last.Keywords.Add(Keyword.Suppressed);
                if (mode == 1) last.Definition = new CardDefinition { Name = last.Name };
                if (mode == 2) target.Location = side.DeckOf();
                if (mode == 3) state.StopFurtherActions = true;
            };
            engine.Api.GiveBlitz(target, 71);
            string[] expected = mode is 0 or 1 ? new[] { "20:0", "21:0", "20:1" }
                : mode == 2 ? new[] { "20:0", "21:0", "20:0", "21:0" } : new[] { "20:0", "21:0", "20:1", "21:1" };
            if (!observed.SequenceEqual(expected)) return "GiveBlitz两次T29必须独立查询并在首次回调后再判断牌库通知：" + string.Join(",", observed);
        }
        return null;
    }

    private static string? BlitzSourceBoundaries(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            {
                var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
                var ctx = new EffectContext { Engine = engine, State = state, Self = target, Controller = side };
                engine.Api.InvokeByName("GiveBlitz", target, new object?[] { 9999, 71 }, ctx, out _);
                if (target.HasBlitz || target.BuffsBySource.Count != 0) return "无效GiveBlitz目标不得回落Self";
                engine.Api.GiveBlitz(target, 71);
                engine.Api.GiveBlitz(target, 72);
                var steps = new KismetStep[] {
                    new(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = "hasBlitz" }, null, -1, "__probe", null),
                    new(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) };
                var bag = engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0), ctx, null, "__probe");
                var effective = engine.Api.InvokeByName("getHasBlitz", target, Array.Empty<object?>(), ctx, out _);
                if (!Equals(bag.GetValueOrDefault("__probe"), false) || !Equals(effective, true))
                    return "原始hasBlitz和有效getter必须分离";
                var snap = target.Snapshot();
                engine.Api.InvokeByName("RemoveBlitz", target, new object?[] { 9999, true, 71, false }, ctx, out _);
                if (!target.ReceivedAbilitiesFromCards["blitz"].SequenceEqual(new[] { 71, 72 })) return "无效RemoveBlitz目标不得回落Self";
                // SDK: cardID, out qqq, giverID, skipAction. qqq=true must not become source ID 1.
                engine.Api.InvokeByName("RemoveBlitz", target, new object?[] { 60, true, 71, true }, ctx, out _);
                if (!target.HasBlitz || !target.ReceivedAbilitiesFromCards["blitz"].SequenceEqual(new[] { 72 })
                    || state.ActionLog.SelectMany(x => x.SubActions).Any(x => x.Name == "ZActionRemoveBlitz"))
                    return "RemoveBlitz必须忽略第2参数输出槽，正确读取第3来源和第4skip";
                if (!snap.Keywords.Contains(Keyword.Blitz) || snap.IntrinsicBlitz
                    || !snap.ReceivedAbilitiesFromCards["blitz"].SequenceEqual(new[] { 71, 72 })
                    || snap.BlitzBuffsBySource["71/False"] != 1) return "闪击快照应独立保留有效/原始状态与两类来源记录";
                engine.Api.SuppressUnit(target);
                if (target.HasBlitz || target.ReceivedAbilitiesFromCards.ContainsKey("blitz")
                    || target.BuffsBySource.Count != 1 || !target.BuffsBySource[(target.CardId, false)].HasSuppressLedgerEntry
                    || target.BuffsBySource.Values.Any(b => b.Blitz != 0))
                    return "抑制必须摘除闪击，同时保留独立Suppress账本标记";
                target.ResetAttributes(); engine.Api.GiveBlitz(target, 72); target.ResetAttributes();
                if (target.HasBlitz || target.BuffsBySource.Count != 0) return "重置不得残留动态闪击来源";
            }
            {
                var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
                target.Keywords.Add(Keyword.Covert); engine.Api.GiveBlitz(target, 71);
                if (target.HasBlitz || target.ReceivedAbilitiesFromCards.ContainsKey("blitz") || target.BuffsBySource.Count != 0)
                    return "未揭示场上Covert不得记录闪击来源";
            }
            {
                var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
                foreach (string keyword in new[] { Keyword.Ambush, Keyword.Fury, Keyword.Guard,
                    Keyword.HeavyArmor, Keyword.Shock, Keyword.Smokescreen }) target.Keywords.Add(keyword);
                var ctx = new EffectContext { Engine = engine, State = state, Self = target, Controller = side };
                engine.Api.InvokeByName("GiveRandomCombatKeyword", target, new object?[] { 60, 71, null, null }, ctx, out _);
                if (!target.HasBlitz || target.Keywords.Contains(Keyword.Blitz)
                    || !target.ReceivedAbilitiesFromCards["blitz"].SequenceEqual(new[] { 71 })) return "随机闪击必须传递来源";
                engine.Api.InvokeByName("GiveRandomCombatKeyword", target, new object?[] { 60, 72, null, null }, ctx, out _);
                if (!target.ReceivedAbilitiesFromCards["blitz"].SequenceEqual(new[] { 71 })) return "随机候选应排除已有来源闪击";
            }
        }
        return null;
    }

    private static readonly (string Card, string Function, string Ability)[] SourceNamePredicates = {
        ("card_event_vanguard_ita", "alreadyHasTheAbility", "fury"),
        ("card_event_greater_purpose", "isAlreadyAffectedByOtherGreater", "destruction"),
        ("card_event_yamato", "isAlreadyAffectedByOtherYamato", "destruction"),
        ("card_event_reckless_assault", "isAlreadyAffectedByOtherReckless", "trigger"),
    };

    private static KismetStep SourceNamePredicateCall(string function, string ability, int index, string output)
    {
        var args = new List<KismetExpr> { new() { Var = "_auditChecked", Scope = "local" } };
        if (function == "alreadyHasTheAbility") args.Add(new KismetExpr { Str = ability });
        args.Add(new KismetExpr { Var = output, Scope = "local" });
        return new KismetStep(index, "call", function, args, new[] { args.Count - 1 }, null, null, -1, null, null)
            { Receiver = new KismetExpr { Self = true } };
    }

    private static string? AbilitySourceNamePredicates(CardDatabase db)
    {
        foreach (var (name, function, ability) in SourceNamePredicates)
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int mode in Enumerable.Range(0, 16))
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(name, side, 20, CardLocation.Discard, 1);
            var same = state.CreateWithId(name, mode == 14 ? side.Opposite() : side, 21,
                mode == 8 ? CardLocation.NotAvailable : side.DeckOf(), 1);
            state.CreateWithId("card_unit_432_infantry_regiment", side, 22, side.HqOf(), 1);
            var target = state.CreateWithId("card_unit_432_infantry_regiment", side, 60, side.HandOf(), 1);
            target.ReceivedAbilitiesFromCards.Clear();
            int[] ids = mode switch {
                0 or 1 => Array.Empty<int>(), 2 or 9 => new[] { 20 }, 4 => new[] { 22 },
                5 => new[] { 9999 }, 6 => new[] { 22, 21 }, 7 => new[] { 21, 22 },
                12 => new[] { 0, -7, 9999, 22, 21 }, 15 => new[] { 60 }, _ => new[] { 21 },
            };
            if (mode != 0)
                target.ReceivedAbilitiesFromCards[mode == 10 ? ability.ToUpperInvariant() : mode == 11 ? "different-key" : ability] = ids.ToList();
            if (mode == 9) source.Keywords.Add(Keyword.Suppressed);
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            object? checkedValue = mode == 13 ? function == "alreadyHasTheAbility" ? null : 9999
                : function == "alreadyHasTheAbility" ? target : target.CardId;
            var seed = new Dictionary<string, object?> { ["_auditChecked"] = checkedValue,
                ["CallFunc_Map_Find_Value"] = new Dictionary<string, object?> { ["cardsGivingAbility"] = new List<object?> { 21 } },
                ["has"] = true, ["isIt"] = true, ["__result"] = true };
            var steps = new KismetStep[] {
                SourceNamePredicateCall(function, ability, 0, "__result"),
                new(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
            };
            string before = System.Text.Json.JsonSerializer.Serialize(target.Snapshot());
            var bag = engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0), ctx, seed, "__result");
            bool expected = mode is 2 or 3 or 6 or 7 or 8 or 9 or 12 or 14;
            if (!Equals(bag.GetValueOrDefault("__result"), expected))
                return $"同名来源谓词不符：{name} {side} mode={mode} 期望{expected} 实际{bag.GetValueOrDefault("__result")}";
            if (before != System.Text.Json.JsonSerializer.Serialize(target.Snapshot()) || state.ActionLog.Count != 0
                || engine.Api.Vm.UnsupportedOps.Count != 0) return "来源查询不应改状态、产生动作或经过未支持节点";
        }
        return null;
    }

    private static string? AbilitySourceNameLifecycle(CardDatabase db)
    {
        foreach (var (name, function, ability) in SourceNamePredicates)
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(name, side, 20, CardLocation.Discard, 1);
            state.CreateWithId(name, side, 21, CardLocation.NotAvailable, 1);
            var target = state.CreateWithId("card_unit_432_infantry_regiment", side, 60, side.HqOf(), 1);
            target.ReceivedAbilitiesFromCards.Clear();
            target.ReceivedAbilitiesFromCards[ability] = new List<int> { 21 };
            int phase = 0; var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name != "card_unit_routed_troops") return;
                phase++;
                if (phase == 1) target.ReceivedAbilitiesFromCards[ability].Clear();
                if (phase == 2) target.ReceivedAbilitiesFromCards[ability].Add(9999);
                if (phase == 3) target.ReceivedAbilitiesFromCards[ability].Add(20);
                if (phase == 4) target.ReceivedAbilitiesFromCards.Remove(ability);
                if (phase == 5) target.ReceivedAbilitiesFromCards[ability] = new List<int> { 21 };
            };
            var steps = new List<KismetStep>();
            for (int mode = 0; mode < 6; mode++)
            {
                steps.Add(SourceNamePredicateCall(function, ability, mode * 3, "__result"));
                steps.Add(new KismetStep(mode * 3 + 1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "__result", Scope = "local" }, null, -1, "r" + mode, null));
                if (mode < 5) steps.Add(new KismetStep(mode * 3 + 2, "call", "SpawnCardInDeckBySide", new[] {
                    new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                    new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
                }, Array.Empty<int>(), null, null, -1, null, null));
            }
            steps.Add(new KismetStep(18, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null));
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            var seed = new Dictionary<string, object?> { ["_auditChecked"] = function == "alreadyHasTheAbility" ? target : target.CardId,
                ["has"] = true, ["isIt"] = true, ["__result"] = true };
            var bag = engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0), ctx, seed,
                Enumerable.Range(0, 6).Select(i => "r" + i).ToArray());
            if (phase != 5 || Enumerable.Range(0, 6).Any(i => !Equals(bag.GetValueOrDefault("r" + i), i is 0 or 3 or 5)))
                return $"同一调用帧不得复用旧来源表或旧输出：{name} {side}";
        }
        return null;
    }

    private static string? VanguardCombatSourceLookup(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool blitz in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_event_vanguard_ita", side, 20, CardLocation.Discard, 1);
            state.CreateWithId(source.Name, side.Opposite(), 21, CardLocation.NotAvailable, 1);
            state.CreateWithId("card_event_greater_purpose", side, 22, CardLocation.Discard, 2);
            var target = MakeActionQuotaProbe(state, side, "infantry");
            string ability = blitz ? "blitz" : "fury";
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            var steps = new KismetStep[] { SourceNamePredicateCall("alreadyHasTheAbility", ability, 0, "__result"),
                new(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) };
            bool Query() => Equals(engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0), ctx,
                new Dictionary<string, object?> { ["_auditChecked"] = target }, "__result").GetValueOrDefault("__result"), true);
            if (blitz) engine.Api.GiveBlitz(target, 22); else engine.Api.GiveFury(target, 22);
            if (Query()) return "有效战斗能力来自其他卡名时，Vanguard同名来源谓词应为false";
            if (blitz) engine.Api.GiveBlitz(target, 21); else engine.Api.GiveFury(target, 21);
            if (!Query()) return "Vanguard应识别NA位置的对方同名副本来源";
            if (blitz) engine.Api.RemoveBlitz(target, 21); else engine.Api.RemoveFury(target, 21);
            if (Query() || !target.HasKeyword(blitz ? Keyword.Blitz : Keyword.Fury))
                return "同名来源撤销后谓词应清除，但其他来源仍保留有效能力";
        }
        return null;
    }

    private static string? CustomAbilityAddContract(CardDatabase db)
    {
        using var probe = InstallAbilitiesChangedProbes();
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (string ability in new[] { "", "trigger", "fury" })
        foreach (int giver in new[] { 0, 71, -7 })
        foreach (bool duplicate in new[] { false, true })
        foreach (bool skipText in new[] { false, true })
        foreach (bool skipSub in new[] { false, true })
        foreach (bool skipLog in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
            var observer = state.CreateWithId("card_unit_51e_regiment", side, 21, CardLocation.NotAvailable, 1);
            observer.Definition = new CardDefinition { Name = observer.Name, UsedTriggers = new[] { "OnOtherCardAbilitiesChanged" } };
            observer.BlueprintVariables["_auditT29Count"] = 0;
            if (giver < 0) target.Keywords.Add(Keyword.Suppressed);
            if (duplicate) target.ReceivedAbilitiesFromCards[ability] = new List<int> { giver };
            target.AttacksThisTurn = 1; target.SetRemainingAttacks(-2);
            var ctx = new EffectContext { Engine = engine, State = state, Self = target, Controller = side };
            var qqq = engine.Api.InvokeByName("CustomAbilityAdd", target,
                new object?[] { ability, 60, giver, skipText, skipSub, skipLog, null }, ctx, out bool handled);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionCustomAbilityAdd").ToArray();
            if (!handled || !Equals(qqq, false) || !target.ReceivedAbilitiesFromCards.TryGetValue(ability, out var sources)
                || !sources.SequenceEqual(new[] { giver }) || target.RemainingAttacks != -2 || target.AttacksThisTurn != 1
                || Convert.ToInt32(observer.BlueprintVariables["_auditT29Count"]) != 0
                || actions.Length != (!duplicate && !skipSub ? 1 : 0))
                return $"CustomAbilityAdd契约错误：{side} key='{ability}' giver={giver} dup={duplicate} flags={skipText}/{skipSub}/{skipLog}";
            if (actions.Length == 1)
            {
                var v = actions[0].Values;
                if (!v.Select(x => x.Name).SequenceEqual(new[] { "cardID", "giverID", "ability", "skipText", "skipAddToBattlelog" })
                    || v[0].Value != 60 || v[1].Value != giver || v[2].Text != ability
                    || v[3].Value != (skipText ? 1 : 0) || v[4].Value != (skipLog ? 1 : 0)) return "CustomAbilityAdd通知字段/顺序不符";
            }
        }
        return null;
    }

    private static string? CustomAbilityRemoveContract(CardDatabase db)
    {
        using var probe = InstallAbilitiesChangedProbes();
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (string ability in new[] { "", "trigger", "fury" })
        foreach (int listMode in new[] { 0, 1, 2, 3 })
        foreach (int giver in new[] { 0, 71, 99 })
        foreach (bool all in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
            var observer = state.CreateWithId("card_unit_51e_regiment", side, 21, CardLocation.NotAvailable, 1);
            observer.Definition = new CardDefinition { Name = observer.Name, UsedTriggers = new[] { "OnOtherCardAbilitiesChanged" } };
            observer.BlueprintVariables["_auditT29Count"] = 0;
            int[] prior = listMode < 2 ? Array.Empty<int>() : listMode == 2 ? new[] { 71 } : new[] { 71, 72, 71 };
            if (listMode != 0) target.ReceivedAbilitiesFromCards[ability] = prior.ToList();
            target.AttacksThisTurn = 1; target.SetRemainingAttacks(3);
            bool known = prior.Contains(giver);
            bool notify = listMode == 0 || all || known;
            bool keyRemains = listMode != 0 && !all && (known ? prior.Any(x => x != giver) : true);
            var remaining = known && !all ? prior.Where(x => x != giver) : prior;
            var result = engine.Api.InvokeByName("CustomAbilityRemove", target, new object?[] { ability, 60, giver, all, null },
                new EffectContext { Engine = engine, State = state, Self = target, Controller = side }, out bool handled);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionCustomAbilityRemove").ToArray();
            if (!handled || !Equals(result, false) || target.ReceivedAbilitiesFromCards.ContainsKey(ability) != keyRemains
                || keyRemains && !target.ReceivedAbilitiesFromCards[ability].SequenceEqual(remaining)
                || target.RemainingAttacks != 3 || target.AttacksThisTurn != 1
                || Convert.ToInt32(observer.BlueprintVariables["_auditT29Count"]) != 0 || actions.Length != (notify ? 1 : 0))
                return $"CustomAbilityRemove契约错误：{side} key='{ability}' list={listMode} giver={giver} all={all}";
            if (actions.Length == 1)
            {
                var v = actions[0].Values;
                if (!v.Select(x => x.Name).SequenceEqual(new[] { "cardID", "giverID", "ability", "RemoveAllGivers" })
                    || v[0].Value != 60 || v[1].Value != giver || v[2].Text != ability || v[3].Value != (all ? 1 : 0))
                    return "CustomAbilityRemove通知字段/顺序不符";
            }
        }
        return null;
    }

    private static string? CustomAbilityWriteBoundaries(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            foreach (var location in new[] { side.HqOf(), side.HandOf(), side.DeckOf(), CardLocation.Discard, CardLocation.NotAvailable })
            {
                var (engine, state) = EmptyBoard(db);
                var target = state.CreateWithId("card_unit_432_infantry_regiment", side, 60, location, 1);
                engine.Api.CustomAbilityAdd(target, "trigger", 0);
                engine.Api.CustomAbilityRemove(target, "trigger", 0, false);
                if (target.ReceivedAbilitiesFromCards.ContainsKey("trigger")
                    || state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name is "ZActionCustomAbilityAdd" or "ZActionCustomAbilityRemove") != 2)
                    return "自定义能力在所有有效普通位置均给予/移除通知，牌库也不省略";
            }
            {
                var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
                target.Keywords.Add(Keyword.Covert);
                if (engine.Api.CustomAbilityAdd(target, "trigger", 71) || target.ReceivedAbilitiesFromCards.ContainsKey("trigger"))
                    return "未揭示场上Covert不能接受自定义能力";
                target.ReceivedAbilitiesFromCards["trigger"] = new List<int> { 71 };
                engine.Api.CustomAbilityRemove(target, "trigger", 71, false);
                if (target.ReceivedAbilitiesFromCards.ContainsKey("trigger")) return "移除能力不受可增益门限制";
            }
            {
                var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
                target.ReceivedAbilitiesFromCards["trigger"] = new List<int> { 71 };
                var ctx = new EffectContext { Engine = engine, State = state, Self = target, Controller = side };
                engine.Api.InvokeByName("CustomAbilityAdd", target, new object?[] { "trigger", 9999, 72, false, false, false, null }, ctx, out _);
                engine.Api.InvokeByName("CustomAbilityRemove", target, new object?[] { "trigger", 9999, 71, true, null }, ctx, out _);
                if (!target.ReceivedAbilitiesFromCards["trigger"].SequenceEqual(new[] { 71 }) || state.ActionLog.Count != 0)
                    return "无效自定义能力目标不能回落到Self或生成动作";
            }
        }
        return null;
    }

    private static bool AuditIsBuffedBy(MatchEngine engine, GameState state, CardInstance target, int giver)
        => engine.Api.InvokeByName("isBuffedByCard", target, new object?[] { giver, null },
            new EffectContext { Engine = engine, State = state, Self = target, Controller = target.Owner }, out _) is true;

    private static string? CustomAbilityLedgerAdd(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (string ability in new[] { "trigger", "destruction", "" })
        foreach (int giver in new[] { 71, 9999, 0, -7 })
        foreach (bool skipText in new[] { false, true })
        foreach (bool skipSub in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
            var source = state.CreateWithId("card_unit_432_infantry_regiment", side, 71, CardLocation.Discard, 1);
            target.BuffsBySource[(88, false)] = new CardBuff { SourceCardId = 88, KreditCost = 1 };
            engine.Api.CustomAbilityAdd(target, ability, giver, skipSub, skipText);
            bool present = target.BuffsBySource.TryGetValue((giver, false), out var buff);
            string expected = giver == 71 ? source.Name : "";
            if (present != !skipText || AuditIsBuffedBy(engine, state, target, giver) != !skipText
                || present && (buff!.IsEmpty || !buff.CustomAbilityDetails.SetEquals(new[] { expected }))
                || !target.ReceivedAbilitiesFromCards[ability].SequenceEqual(new[] { giver }))
                return $"自定义账本新增错误：{side} '{ability}' giver={giver} skipText={skipText} skipSub={skipSub}";
            // A later duplicate call cannot backfill a skipped text record.
            engine.Api.CustomAbilityAdd(target, ability, giver, skipBuffTexts: false);
            if (target.BuffsBySource.ContainsKey((giver, false)) != present) return "重复来源不能补写此前跳过的账本";
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            var reverse = engine.Api.InvokeByName("getCardsBuffedByThisCard", source, new object?[] { null }, ctx, out _);
            if (giver == 71 && (reverse is not List<int> ids || ids.Contains(target.CardId) != !skipText))
                return "自定义零值条目应进入来源卡的反向增益查询";
        }
        return null;
    }

    private static string? CustomAbilityLedgerRemoveAll(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (string ability in new[] { "trigger", "destruction", "custom" })
        foreach (int giver in new[] { 71, 72, 9999 })
        foreach (bool sameName in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
            var first = state.CreateWithId("card_unit_432_infantry_regiment", side, 71, CardLocation.Discard, 1);
            var second = state.CreateWithId(sameName ? first.Name : "card_unit_t_34_85", side.Opposite(), 72, CardLocation.NotAvailable, 1);
            engine.Api.CustomAbilityAdd(target, ability, 71);
            engine.Api.CustomAbilityAdd(target, ability, 72);
            target.BuffsBySource[(71, false)].Attack = 2;
            engine.Api.CustomAbilityRemove(target, ability, giver, true);
            bool firstRemoved = giver != 9999 && (ability == "destruction" || sameName || giver == 71);
            bool secondRemoved = giver != 9999 && (ability == "destruction" || sameName || giver == 72);
            if (target.ReceivedAbilitiesFromCards.ContainsKey(ability)
                || target.BuffsBySource[(71, false)].CustomAbilityDetails.Contains(first.Name) == firstRemoved
                || target.BuffsBySource[(71, false)].Attack != 2
                || AuditIsBuffedBy(engine, state, target, 72) == secondRemoved)
                return $"RemoveAll名称规则错误：{side} {ability} giver={giver} sameName={sameName}";
        }
        return null;
    }

    private static string? CustomAbilityLedgerChooseOne(CardDatabase db)
    {
        if (db.All.Count(x => x.ChooseOneOptionCount != 0) != 51
            || db.All.Where(x => x.ChooseOneOptionCount != 0).Any(x => x.ChooseOneOptionCount != 2))
            return "静态选择卡计数应对应51张、每张2个选项";
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int index in new[] { 0, 1, 7 })
        foreach (bool self in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", side, 71, side.HqOf(), 1);
            var target = self ? source : MakeActionQuotaProbe(state, side, "infantry");
            source.ChooseOne = index;
            string expected = source.Name + (self ? "_" + index : "");
            engine.Api.CustomAbilityAdd(target, "trigger", 71);
            engine.Api.CustomAbilityAdd(target, "lethal", 71);
            if (!target.BuffsBySource[(71, false)].CustomAbilityDetails.SetEquals(new[] { expected }))
                return "自身选择卡按索引后缀记账，多个能力共享同一零值名称条目";
            if (self) source.ChooseOne++;
            engine.Api.CustomAbilityRemove(target, "trigger", 71, false);
            if (AuditIsBuffedBy(engine, state, target, 71) != self)
                return "移除按当前名称/选择索引查条目，不得按能力名回溯旧键";
            source.ChooseOne = index;
            engine.Api.CustomAbilityRemove(target, "lethal", 71, false);
            if (AuditIsBuffedBy(engine, state, target, 71)) return "最后匹配名称移除后零值来源槽应删除";
        }
        return null;
    }

    private static string? CustomAbilityLedgerUnknownRemove(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
            state.CreateWithId("card_unit_432_infantry_regiment", side, 71, CardLocation.Discard, 1);
            state.CreateWithId("card_unit_t_34_85", side, 72, CardLocation.Discard, 2);
            engine.Api.CustomAbilityAdd(target, "custom", 71);
            engine.Api.CustomAbilityAdd(target, "trigger", 72);
            int before = state.ActionLog.SelectMany(x => x.SubActions).Count();
            if (engine.Api.CustomAbilityRemove(target, "trigger", 71, false)
                || AuditIsBuffedBy(engine, state, target, 71)
                || !target.ReceivedAbilitiesFromCards["custom"].SequenceEqual(new[] { 71 })
                || !target.ReceivedAbilitiesFromCards["trigger"].SequenceEqual(new[] { 72 })
                || state.ActionLog.SelectMany(x => x.SubActions).Count() != before)
                return "未知来源的早退位于账本清理之后，保留来源表但可清除同源其他能力共用的名称条目";
        }
        return null;
    }

    private static string? CustomAbilityLedgerLifecycle(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int mode in new[] { 0, 1, 2, 3 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_51e_regiment", side, 71, side.HqOf(), 1);
            var target = mode == 1 ? source : MakeActionQuotaProbe(state, side, "infantry");
            int giver = mode == 2 ? 9999 : 71;
            engine.Api.CustomAbilityAdd(target, "trigger", giver, skipBuffTexts: mode == 3);
            var snapshot = target.Snapshot();
            if (mode != 3)
            {
                var clone = target.BuffsBySource[(giver, false)].Clone();
                clone.CustomAbilityDetails.Clear();
                if (target.BuffsBySource[(giver, false)].CustomAbilityDetails.Count != 1) return "自定义条目Clone不能共享集合";
            }
            engine.Api.SuppressUnit(target);
            bool retained = mode is 1 or 2;
            if (AuditIsBuffedBy(engine, state, target, giver) != retained)
                return $"抑制只清有效来源的未加后缀名称，不应清掉不匹配或未知来源条目：{side} mode={mode}";
            engine.Api.RestoreAfterSuppression(target);
            if (AuditIsBuffedBy(engine, state, target, giver) != (mode != 3)) return "既有解除抑制适配器应恢复被摘除的名称条目";
            target.ResetAttributes();
            if (target.BuffsBySource.Count != 0) return "原生属性重置应清除所有自定义账本";
            if (mode != 3 && snapshot.CustomAbilityBuffDetails[$"{giver}/False"].Length != 1)
                return "快照必须独立保留原自定义名称记录";
        }
        return null;
    }

    private static string? DestructionLedgerPreface(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool raw in new[] { false, true })
        foreach (string ability in new[] { "destruction", "Destruction", "trigger" })
        foreach (int list in new[] { 0, 1, 2 })
        foreach (bool all in new[] { false, true })
        foreach (int giver in new[] { 0, -7, 71, 9999 })
        foreach (int old in new[] { -1, 0, 1 })
        {
            var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
            state.CreateWithId("card_unit_432_infantry_regiment", side, 71, CardLocation.Discard, 1);
            if (raw) target.Keywords.Add(Keyword.Destruction);
            if (list != 0) target.ReceivedAbilitiesFromCards[ability] = list == 1 ? new List<int> { 72 } : new List<int> { 71, 72 };
            target.BuffsBySource[(giver, false)] = new CardBuff { SourceCardId = giver, Attack = 2, Destruction = old };
            target.AttacksThisTurn = 2; target.SetRemainingAttacks(-3);
            engine.Api.TriggerTrace = new List<string>();
            engine.Api.CustomAbilityRemove(target, ability, giver, all);
            int expected = old - (raw && ability == "destruction" ? 1 : 0);
            bool known = list == 2 && giver == 71;
            int actions = state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionCustomAbilityRemove");
            if (target.BuffsBySource[(giver, false)].Destruction != expected
                || target.BuffsBySource[(giver, false)].Attack != 2 || target.Keywords.Contains(Keyword.Destruction) != raw
                || target.RemainingAttacks != -3 || target.AttacksThisTurn != 2
                || actions != (list == 0 || all || known ? 1 : 0)
                || engine.Api.TriggerTrace.Any(x => x.StartsWith("OnOtherCardAbilitiesChanged", StringComparison.Ordinal)))
                return $"destruction前置账本错误：{side} raw={raw} '{ability}' list={list} giver={giver} all={all} old={old}";
        }
        return null;
    }

    private static string? HasCustomAbilityNonemptySources(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (string ability in new[] { "", "trigger", "destruction", "fury" })
        foreach (int mode in new[] { 0, 1, 2, 3 })
        {
            var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
            target.Keywords.Add(Keyword.Destruction);
            if (mode != 0) target.ReceivedAbilitiesFromCards[ability] = mode == 1 ? new List<int>()
                : mode == 2 ? new List<int> { 0 } : new List<int> { -7, 9999 };
            var raw = engine.Api.InvokeByName("HasCustomAbility", target, new object?[] { ability, null },
                new EffectContext { Engine = engine, State = state, Self = target, Controller = side }, out bool handled);
            if (!handled || !Equals(raw, mode >= 2) || engine.Api.HasCustomAbility(target, ability) != (mode >= 2))
                return $"HasCustomAbility应检查来源数组Num：{side} '{ability}' mode={mode}";
        }
        return null;
    }

    private static string? DestructionLedgerLifecycle(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int initial in new[] { -1, 0, 1 })
        foreach (bool other in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); var target = MakeActionQuotaProbe(state, side, "infantry");
            target.Keywords.Add(Keyword.Destruction);
            if (initial != 0 || other) target.BuffsBySource[(0, false)] = new CardBuff { SourceCardId = 0, Destruction = initial, KreditCost = other ? 1 : 0 };
            engine.Api.CustomAbilityRemove(target, "destruction", 0, true);
            int once = initial - 1;
            if (AuditIsBuffedBy(engine, state, target, 0) != (once != 0 || other)
                || target.BuffsBySource.GetValueOrDefault((0, false))?.Destruction != (once != 0 || other ? once : null))
                return "destruction账本过零应只删该字段，外层来源槽按其他字段是否为空决定";
            var snapshot = target.Snapshot();
            engine.Api.CustomAbilityRemove(target, "destruction", 0, true);
            if (target.BuffsBySource[(0, false)].Destruction != initial - 2
                || !target.Keywords.Contains(Keyword.Destruction)) return "缺键重复移除也会继续累积负账本，不能清原始标志";
            var clone = target.BuffsBySource[(0, false)].Clone(); clone.Destruction = 99;
            if (target.BuffsBySource[(0, false)].Destruction == 99
                || once != 0 && snapshot.DestructionBuffsBySource["0/False"] != once) return "destruction克隆/快照应独立";
            target.ResetAttributes();
            if (target.BuffsBySource.Count != 0) return "原生重置应清destruction账本";
        }
        return null;
    }

    private static string? TriggerDestructionRemovalGate(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool remove in new[] { false, true })
        foreach (bool board in new[] { false, true })
        foreach (int sourceMode in new[] { 0, 1, 2, 3 })
        {
            var (engine, state) = EmptyBoard(db);
            var target = state.CreateWithId("card_unit_hayabusa", side, 71, board ? side.HqOf() : CardLocation.Discard, 1);
            state.CreateWithId("card_unit_432_infantry_regiment", side, 72, side.HqOf(), 2);
            if (sourceMode != 0) target.ReceivedAbilitiesFromCards["destruction"] = sourceMode == 1 ? new List<int>()
                : sourceMode == 2 ? new List<int> { 9999 } : new List<int> { 72 };
            int defense = state.Hq(side.Opposite()).Defense;
            engine.Api.TriggerDestruction(target, null, false, remove);
            bool clears = remove && sourceMode >= 2;
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            var trigger = actions.SingleOrDefault(x => x.Name == "ZActionTriggerDestruction");
            var persisted = actions.Where(x => x.Name == "ZActionPersistCustomFields").ToArray();
            if (persisted.Length != (board && remove ? 1 : 0)
                || (persisted.Length == 1 && (persisted[0].Values.Single(x => x.Name == "customName1").Text != "StopDestructionEffect"
                    || Array.IndexOf(actions, persisted[0]) <= Array.FindIndex(actions, x => x.Name == "ZActionTriggerDestruction")
                    || (clears && Array.IndexOf(actions, persisted[0]) <= Array.FindIndex(actions, x => x.Name == "ZActionCustomAbilityRemove")))))
                return "主动亡语应在移除通知后持久化场上目标的StopDestructionEffect";
            int removes = actions.Count(x => x.Name == "ZActionCustomAbilityRemove");
            if (defense - state.Hq(side.Opposite()).Defense != 2 || trigger is null
                || removes != (clears ? 1 : 0) || target.BuffsBySource.GetValueOrDefault((0, false))?.Destruction != (clears ? -1 : null)
                || !target.Keywords.Contains(Keyword.Destruction)
                || CardApi.CustomNameHasAttribute(target, "customName1", "StopDestructionEffect") != (board && remove)
                || target.ReceivedAbilitiesFromCards.ContainsKey("destruction") != (sourceMode != 0 && !clears))
                return $"TriggerDestruction移除门错误：{side} remove={remove} board={board} source={sourceMode}";
            if (!trigger.Values.Select(x => x.Name).SequenceEqual(new[] { "cardID", "instigatorID", "StealSide", "RemoveDestruction" })
                || trigger.Values[0].Value != 71 || trigger.Values[1].Value != 0 || trigger.Values[2].Value != 0 || trigger.Values[3].Value != (remove ? 1 : 0))
                return "主动亡语通知应按权威字段顺序包含目标ID";
            if (clears && Array.FindIndex(actions, x => x.Name == "ZActionTriggerDestruction")
                >= Array.FindIndex(actions, x => x.Name == "ZActionCustomAbilityRemove")) return "主动触发通知必须先于后续能力移除通知";
        }
        return null;
    }

    private static (MatchEngine Engine, GameState State, CardInstance[] Board, CardInstance[] Units, CardInstance[] Front, CardInstance[] All)
        MakeNativeBoardQueryFixture(CardDatabase db, Side primary, int ownerMode)
    {
        var (engine, state) = EmptyBoard(db); Side other = primary.Opposite();
        CardInstance Make(int id, Side owner, CardLocation location, int slot, string type = "infantry", int defense = 20)
        {
            var card = state.CreateWithId(PlainUnit, owner, id, location, slot);
            card.Definition = new CardDefinition { Name = PlainUnit, Type = type, Defense = defense, Attack = 2 };
            card.Keywords.Clear(); card.Defense = card.MaxDefense = defense;
            return card;
        }
        var a = Make(90, other, other.HqOf(), 9);
        var b = Make(10, primary, CardLocation.BoardFrontline, 4); b.Keywords.Add(Keyword.Covert);
        var c = Make(70, other, CardLocation.BoardFrontline, 0, "order");
        var d = Make(20, primary, primary.HqOf(), 2, defense: 0);
        var e = Make(80, other, CardLocation.BoardFrontline, 2, "fighter");
        var f = Make(30, primary, CardLocation.BoardFrontline, 1, defense: -1);
        var g = Make(60, other, other.HandOf(), 0);
        var h = Make(40, primary, primary.DeckOf(), 0);
        var i = Make(100, other, CardLocation.Discard, 0);
        var j = Make(110, primary, primary.HqOf(), 0); j.Keywords.Add(Keyword.Covert); j.IsRevealed = true;
        if (ownerMode is 1 or 3 or 4) state.ChangeOwner(a, primary);
        if (ownerMode is 2 or 4) state.ChangeOwner(b, other);
        if (ownerMode == 3) state.ChangeOwner(a, other);
        var left = state.Hq(Side.Left); var right = state.Hq(Side.Right);
        return (engine, state, new[] { left, right, a, b, c, d, e, f, j }, new[] { a, b, e, j },
            new[] { b, c, e, f }, new[] { left, right, a, b, c, d, e, f, g, h, i, j });
    }

    private static string? NativeGlobalBoardQueryOrder(CardDatabase db)
    {
        foreach (Side primary in new[] { Side.Left, Side.Right })
        foreach (int ownerMode in Enumerable.Range(0, 5))
        foreach (bool include in new[] { false, true })
        {
            var fixture = MakeNativeBoardQueryFixture(db, primary, ownerMode);
            var (engine, state) = (fixture.Engine, fixture.State);
            var ctx = new EffectContext { Engine = engine, State = state, Self = state.Hq(primary), Controller = primary };
            long consumed = state.Random.ConsumedCount;
            foreach (var query in new[] { (Name: "GetAllUnitsOnBoard", Expected: fixture.Units),
                (Name: "GetAllCardsOnBoard", Expected: fixture.Board), (Name: "GetAllCardsInFrontline", Expected: fixture.Front) })
            {
                var expected = query.Expected.Where(x => include || x.CardId != 10).Select(x => x.CardId).ToArray();
                object? raw = engine.Api.InvokeByName(query.Name, ctx.Self, new object?[] { include, null }, ctx, out bool handled);
                var direct = query.Name == "GetAllUnitsOnBoard" ? engine.Api.GetAllUnitsOnBoard(include)
                    : query.Name == "GetAllCardsOnBoard" ? engine.Api.GetAllCardsOnBoard(include) : engine.Api.GetAllCardsInFrontline(include);
                if (!handled || raw is not IEnumerable<CardInstance> list || !list.Select(x => x.CardId).SequenceEqual(expected)
                    || !direct.Select(x => x.CardId).SequenceEqual(expected) || state.Random.ConsumedCount != consumed)
                    return $"全局查询顺序/过滤错误：{primary}/mode={ownerMode}/{query.Name}/covert={include}";
            }
            if (!engine.Api.GetAllCards().Select(x => x.CardId).SequenceEqual(fixture.All.Select(x => x.CardId)))
                return "换主不应改变全局对局卡表";
        }
        return null;
    }

    private static string? NativeOwnerBoardQueryOrder(CardDatabase db)
    {
        foreach (Side primary in new[] { Side.Left, Side.Right })
        foreach (int ownerMode in Enumerable.Range(0, 5))
        {
            var fixture = MakeNativeBoardQueryFixture(db, primary, ownerMode);
            var (engine, state) = (fixture.Engine, fixture.State);
            var ctx = new EffectContext { Engine = engine, State = state, Self = state.Hq(primary), Controller = primary };
            foreach (Side queried in new[] { Side.Left, Side.Right })
            {
                var board = fixture.Board.Where(x => x.Owner == queried).ToArray();
                if (!state.BattleCardsInOrder(queried).SequenceEqual(board)
                    || !state.BoardInBattleOrder(queried).SequenceEqual(board.Where(x => !x.IsHq)))
                    return "阵营查询必须从全局卡表筛选，不能使用换主后追加的阵营索引";
                foreach (bool unitsOnly in new[] { false, true })
                foreach (bool include in new[] { false, true })
                {
                    var expected = (unitsOnly ? fixture.Units : fixture.Board.Where(x => x.CardId is not (20 or 30)))
                        .Where(x => x.Owner == queried && (include || x.CardId != 10));
                    object? raw = engine.Api.InvokeByName("GetCardsOnBoardBySide", ctx.Self,
                        new object?[] { (int)queried, unitsOnly, include, null }, ctx, out bool handled);
                    if (!handled || raw is not IEnumerable<CardInstance> list || !list.SequenceEqual(expected))
                        return $"换主后阵营候选集顺序错误：{primary}/{ownerMode}/{queried}/units={unitsOnly}/covert={include}";
                }
            }
        }
        return null;
    }

    private static string? NativeBoardQueryRandomOrder(CardDatabase db)
    {
        foreach (Side primary in new[] { Side.Left, Side.Right })
        foreach (int ownerMode in Enumerable.Range(0, 5))
        foreach (bool include in new[] { false, true })
        {
            var fixture = MakeNativeBoardQueryFixture(db, primary, ownerMode);
            var (engine, state) = (fixture.Engine, fixture.State);
            var pools = new[] {
                (Actual: engine.Api.GetAllUnitsOnBoard(include).ToArray(), Expected: fixture.Units),
                (Actual: engine.Api.GetAllCardsOnBoard(include).ToArray(), Expected: fixture.Board),
                (Actual: engine.Api.GetAllCardsInFrontline(include).ToArray(), Expected: fixture.Front),
            };
            var oracle = new UeRandomStream(state.Random.Seed);
            foreach (var pool in pools)
            {
                var expected = pool.Expected.Where(x => include || x.CardId != 10).ToArray();
                for (int draw = 0; draw < 6; draw++)
                {
                    long before = state.Random.ConsumedCount;
                    int index = NativeRandomDrawOracle(oracle, 0, expected.Length - 1);
                    var selected = engine.Api.GetRandomCard(pool.Actual);
                    if (selected != expected[index] || state.Random.Seed != oracle.Seed || state.Random.ConsumedCount != oracle.ConsumedCount)
                        return "完整辅助函数抽取必须命中全局顺序中的同一候选并匹配游标";
                }
            }
        }
        return null;
    }

    // Candidate pools now use the pak helper schedule, also checked by fixed vectors.
    // Oracle follows the authoritative Blueprint sequence using raw stream operations.
    private static int NativeRandomDrawOracle(UeRandomStream raw, int lo, int hi)
    {
        int count = raw.RandRange(1, 10);
        for (int i = 1; i <= count; i++) raw.RandRange(0, 1);
        return raw.RandRange(lo, hi);
    }

    private static string? NativeHandCapacityAutoplay(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int quantity in new[] { 8, 9, 10 })
        foreach (int excluded in new[] { 0, 1, 2 })
        foreach (bool oppositeOwner in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            for (int i = 0; i < quantity; i++)
            {
                var card = state.CreateWithId(i < excluded && i % 2 == 0 ? "card_event_resistance_new" : PlainUnit,
                    oppositeOwner ? side.Opposite() : side, 100 + i, side.HandOf(), i * 3);
                if (i < excluded && i % 2 != 0) engine.Api.AddCustomGameplayTag(card, "autoplay");
            }
            var ctx = new EffectContext { Engine = engine, State = state, Controller = side };
            bool Full() => engine.Api.InvokeByName("IsLocationFull", null, new object?[] { (int)side.HandOf(), null }, ctx, out _) is true;
            if (Full() != (quantity - excluded >= 9)) return "容量必须排除autoplay并忽略当前归属及槽位编号";
            if (excluded > 0)
            {
                var first = state.ById(100)!; first.RemovedGameplayTags.Add("autoplay");
                if (Full() != (quantity - excluded + 1 >= 9)) return "容量必须读取已移除的实时静态标签";
            }
            int before = quantity - excluded + (excluded > 0 ? 1 : 0);
            var generated = engine.Api.SpawnCardInHand(side, "card_unit_51e_regiment");
            if (generated.Location != (before >= 9 ? CardLocation.Discard : side.HandOf()))
                return "生成满手快照必须采用排除autoplay后的相同容量";
        }
        return null;
    }

    private static string? NativeSpawnHandFullness(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int quantity in new[] { 8, 9, 10 })
        foreach (bool oppositeOwner in new[] { false, true })
        foreach (int tagMode in Enumerable.Range(0, 4))
        foreach (int modifier in Enumerable.Range(0, 3))
        foreach (int handMutation in Enumerable.Range(0, 3))
        {
            var (engine, state) = EmptyBoard(db);
            string name = tagMode is 1 or 2 ? "card_event_resistance_new" : "card_unit_51e_regiment";
            var source = state.CreateWithId(PlainUnit, side, 30, CardLocation.Discard, 0);
            for (int i = 0; i < quantity; i++)
                state.CreateWithId(PlainUnit, oppositeOwner ? side.Opposite() : side, 100 + i, side.HandOf(), i * 3);
            state.CardCreated += card => {
                if (card.Name != name) return;
                if (tagMode == 2) card.RemovedGameplayTags.Add("autoplay");
                if (tagMode == 3) engine.Api.AddCustomGameplayTag(card, "autoplay");
            };
            int callbacks = 0;
            state.CardCreationModifiers += card => {
                if (card.Name != name) return;
                callbacks++;
                if (modifier == 1) engine.Api.AddCustomGameplayTag(card, "autoplay");
                if (modifier == 2) { engine.Api.RemoveCustomGameplayTag(card, "autoplay"); card.RemovedGameplayTags.Add("autoplay"); }
                if (handMutation == 1) state.ById(100)!.Location = CardLocation.Discard;
                if (handMutation == 2)
                    for (int i = 0; i < 2; i++) state.CreateWithId(PlainUnit, side, 200 + i, side.HandOf(), 50 + i);
            };
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            var result = engine.Api.InvokeByName("SpawnCardInHandBySide", source,
                new object?[] { (int)side, name, 30, false, false, false, "", "", 0, null }, ctx, out bool handled);
            bool tagged = modifier == 1 || modifier == 0 && tagMode is 1 or 3;
            bool burned = quantity >= 9 && !tagged;
            if (!handled || result is not CardInstance spawned || callbacks != 1
                || spawned.Location != (burned ? CardLocation.Discard : side.HandOf())
                || !state.GetAutoPlayCards().SequenceEqual(tagged ? new[] { spawned.CardId } : Array.Empty<int>())
                || state.ById(101)!.LocationNumber != 3 || state.Random.ConsumedCount != 0)
                return $"满手快照/创建修正标签错误：{side}/{quantity}/{oppositeOwner}/{tagMode}/{modifier}/{handMutation}";
        }
        return null;
    }

    private static string? NativeSpawnHandAutoplayEvents(CardDatabase db)
    {
        const string name = "card_unit_51e_regiment", own = "OnCardSpawnedInHand", other = "OnOtherCardSpawnedInHand";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(own) || locals.ContainsKey(other)) return "无法安装手牌自动打出探针";
        var program = new[] {
            new KismetStep(0, "call", "SpawnCardInDeckBySide", new[] {
                new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
            }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        locals[own] = program; locals[other] = program;
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool full in new[] { false, true })
            foreach (bool initiallyTagged in new[] { false, true })
            foreach (int ownMutation in Enumerable.Range(0, 5))
            foreach (int otherMutation in Enumerable.Range(0, 5))
            {
                var (engine, state) = EmptyBoard(db);
                if (full) for (int i = 0; i < 9; i++) state.CreateWithId(PlainUnit, side, 100 + i, side.HandOf(), i);
                state.CreateWithId(PlainUnit, side, 30, CardLocation.Discard, 0);
                var watcher = state.CreateWithId(name, side.Opposite(), 20, CardLocation.Discard, 0);
                watcher.Definition = new CardDefinition { Name = name, Type = "infantry", UsedTriggers = new[] { other } };
                CardInstance? spawned = null;
                state.CardCreationModifiers += card => { if (card.Name == name) { spawned = card; if (initiallyTagged) engine.Api.AddCustomGameplayTag(card, "autoplay"); } };
                CardLocation expectedLocation = full && !initiallyTagged ? CardLocation.Discard : side.HandOf();
                bool expectedTag = initiallyTagged, correct = true; int events = 0;
                state.CardCreated += card => {
                    if (card.Name != "card_unit_routed_troops") return;
                    events++; correct &= spawned is not null && spawned.Location == expectedLocation && state.GetAutoPlayCards().Length == 0;
                    int mode = events == 1 ? ownMutation : otherMutation;
                    if (mode is 1 or 4) { engine.Api.AddCustomGameplayTag(spawned!, "autoplay"); expectedTag = true; }
                    if (mode == 2) { engine.Api.RemoveCustomGameplayTag(spawned!, "autoplay"); expectedTag = false; }
                    if (mode == 3) spawned!.Location = expectedLocation = CardLocation.Discard;
                    if (mode == 4) spawned!.Location = expectedLocation = side.Opposite().HandOf();
                    state.StopFurtherActions = true;
                };
                var result = engine.Api.SpawnCardInHand(side, name);
                bool queue = expectedTag && expectedLocation is CardLocation.HandLeft or CardLocation.HandRight;
                if (!correct || events != 2 || result.Location != expectedLocation
                    || !state.GetAutoPlayCards().SequenceEqual(queue ? new[] { result.CardId } : Array.Empty<int>()))
                    return $"生成后入队门错误：{side}/full={full}/tag={initiallyTagged}/{ownMutation}/{otherMutation}/events={events}";
            }
        }
        finally { locals.Remove(own); locals.Remove(other); }
        return null;
    }

    private static string? NativeSpawnHandEventSnapshot(CardDatabase db)
    {
        const string name = "card_unit_m36_destroyer", own = "OnCardSpawnedInHand", other = "OnOtherCardSpawnedInHand";
        const string marker = "card_unit_routed_troops";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(own) || locals.ContainsKey(other)) return "无法安装手牌生成事件探针";
        KismetStep Store(int index, string variable, string field) => new(index, "set", null,
            Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = variable }, null, -1, field, null) { DestinationScope = "instance" };
        KismetStep Marker(int index) => new(index, "call", "SpawnCardInDeckBySide", new[] {
            new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = marker },
            new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
        }, Array.Empty<int>(), null, null, -1, null, null);
        KismetStep Return(int index) => new(index, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null);
        locals[own] = new[] { Store(0, "K2Node_Event_spawnedSide", "_auditOwnSpawnSide"), Marker(1), Return(2) };
        locals[other] = new[] { Store(0, "K2Node_Event_spawnedCardID", "_auditSpawnId"),
            Store(1, "K2Node_Event_spawnedSide", "_auditSpawnSide"), Marker(2), Return(3) };
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (var location in new[] { side.HandOf(), side.DeckOf(), side.HqOf(), CardLocation.Discard, CardLocation.NotAvailable })
            foreach (bool ownSuppressed in new[] { false, true })
            foreach (bool stop in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                CardDefinition Registered(bool enabled) => new() { Name = name, Type = "infantry", UsedTriggers = enabled ? new[] { other } : Array.Empty<string>() };
                var watchers = Enumerable.Range(1, 8).Select(i => state.CreateWithId(name, side.Opposite(), i * 10, CardLocation.Discard, i)).ToArray();
                foreach (var w in watchers) w.Definition = Registered(true);
                watchers[1].Definition = Registered(false); // own event registers this before the query
                watchers[2].Keywords.Add(Keyword.Suppressed); // own event clears this before the query
                foreach (int i in new[] { 4, 5, 7 }) watchers[i].Keywords.Add(Keyword.Suppressed);
                watchers[6].Definition = Registered(false);
                foreach (int i in new[] { 3, 4, 7 }) watchers[i].SuppressionExceptionTriggers.Add(other);
                CardInstance? spawned = null, late = null;
                int markers = 0;
                state.CardCreationModifiers += card => {
                    if (card.Name != name || card.CardId == 9000) return;
                    spawned = card; card.Location = location; if (ownSuppressed) card.Keywords.Add(Keyword.Suppressed); card.Definition = Registered(true);
                };
                state.CardCreated += card => {
                    if (card.Name != marker) return;
                    markers++;
                    if (markers == 1) { watchers[1].Definition = Registered(true); watchers[2].Keywords.Remove(Keyword.Suppressed); }
                    if (markers == 2) {
                        watchers[1].Definition = Registered(false);
                        watchers[2].Location = CardLocation.NotAvailable;
                        watchers[3].Keywords.Add(Keyword.Suppressed); // exception cannot bypass the per-item gate
                        watchers[4].Keywords.Remove(Keyword.Suppressed); // query exception kept this in the snapshot
                        watchers[5].Keywords.Remove(Keyword.Suppressed); // excluded at query; cannot rejoin
                        watchers[6].Definition = Registered(true); // also excluded at query
                        late = state.CreateWithId(name, side, 9000, CardLocation.Discard, 0); late.Definition = Registered(true);
                        state.StopFurtherActions = stop;
                    }
                };
                var result = engine.Api.SpawnCardInHand(side, name);
                if (spawned != result || !Equals(result.BlueprintVariables.GetValueOrDefault("_auditOwnSpawnSide"), (int)side)
                    || result.BlueprintVariables.ContainsKey("_auditSpawnId") || markers != 5 || late is null || late.BlueprintVariables.ContainsKey("_auditSpawnId"))
                    return $"自身事件/自排除/快照新增门错误：{side}/{location}/suppressed={ownSuppressed}/stop={stop}/markers={markers}";
                for (int i = 0; i < watchers.Length; i++)
                {
                    bool expected = i is 0 or 1 or 2 or 4;
                    bool received = watchers[i].BlueprintVariables.ContainsKey("_auditSpawnId");
                    if (received != expected || received && (!Equals(watchers[i].BlueprintVariables["_auditSpawnId"], result.CardId)
                        || !Equals(watchers[i].BlueprintVariables.GetValueOrDefault("_auditSpawnSide"), (int)side)))
                        return $"T57查询/实时抑制/载荷错误：{side}/{location}/index={i}/received={received}";
                }
            }
            return null;
        }
        finally { locals.Remove(own); locals.Remove(other); }
    }

    private static string? NativeSpawnHandSeenTiming(CardDatabase db)
    {
        const string watcherName = "card_unit_51e_regiment", spawnedName = "card_unit_typhoon_mk_ib";
        const string createdTrigger = "OnOtherCardCreatedAlterCard", spawnedTrigger = "OnCardSpawnedInHand";
        if (KismetLibrary.Default?.Find(watcherName)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> watcherLocals
            || KismetLibrary.Default.Find(spawnedName)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> spawnedLocals
            || watcherLocals.ContainsKey(createdTrigger) || spawnedLocals.ContainsKey(spawnedTrigger)) return "无法安装公开时机探针";
        watcherLocals[createdTrigger] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "cardSeen", Context = new KismetExpr { Var = "cardPlayed" } }, null, -1, "_auditSeenAtT35", null) { DestinationScope = "instance" },
            new(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        spawnedLocals[spawnedTrigger] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = "cardSeen", Scope = "instance" },
                null, -1, "_auditSeenAtSpawn", null) { DestinationScope = "instance" },
            new(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool requested in new[] { false, true })
            foreach (bool ownWrite in new[] { false, true })
            foreach (bool modifierWrite in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(PlainUnit, side, 30, CardLocation.Discard, 0);
                var watcher = state.CreateWithId(watcherName, side, 20, CardLocation.Discard, 0);
                watcher.Definition = new CardDefinition { Name = watcherName, Type = "infantry", UsedTriggers = new[] { createdTrigger } };
                int ownCalls = 0, modifierCalls = 0; bool correct = true;
                state.CardCreated += card => { if (card.Name == spawnedName) { ownCalls++; card.CardSeen = ownWrite; } };
                state.CardCreationModifiers += card => {
                    if (card.Name != spawnedName) return;
                    modifierCalls++;
                    correct &= card.CardSeen == requested && Equals(watcher.BlueprintVariables.GetValueOrDefault("_auditSeenAtT35"), requested);
                    card.CardSeen = modifierWrite;
                };
                var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
                var result = engine.Api.InvokeByName("SpawnCardInHandBySide", source, new object?[] { (int)side,
                    spawnedName, 30, requested, false, false, "", "", 0, null }, ctx, out bool handled);
                if (!handled || result is not CardInstance card || !correct || ownCalls != 1 || modifierCalls != 1
                    || card.CardSeen != modifierWrite || !Equals(card.BlueprintVariables.GetValueOrDefault("_auditSeenAtSpawn"), modifierWrite)
                    || state.Random.ConsumedCount != 0)
                    return $"公开字段阶段不符：{side}/{requested}/own={ownWrite}/T35={modifierWrite}";
            }
        }
        finally { watcherLocals.Remove(createdTrigger); spawnedLocals.Remove(spawnedTrigger); }
        return null;
    }

    private static string? NativeCreationSeenPhase(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool? requested in new bool?[] { null, false, true })
        foreach (bool ownWrite in new[] { false, true })
        foreach (bool skipModifiers in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            int ownCalls = 0, modifierCalls = 0; bool correct = true;
            state.CardCreated += card => { if (card.Name == PlainUnit) { ownCalls++; card.CardSeen = ownWrite; } };
            state.CardCreationModifiers += card => {
                if (card.Name != PlainUnit) return;
                modifierCalls++; correct &= card.CardSeen == (requested ?? ownWrite);
                card.CardSeen = !(requested ?? ownWrite);
            };
            var card = state.Create(PlainUnit, side, side.HandOf(), 0, skipCreationModifiers: skipModifiers, cardSeenBeforeModifiers: requested);
            bool expected = skipModifiers ? requested ?? ownWrite : !(requested ?? ownWrite);
            if (!correct || ownCalls != 1 || modifierCalls != (skipModifiers ? 0 : 1) || card.CardSeen != expected)
                return "中间赋值必须独立于T35跳过开关，null必须保持下层创建语义";
        }
        return null;
    }

    private static string? NativeSpawnHandInitialFields(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (Side contextSide in new[] { Side.Left, Side.Right })
        foreach (bool gold in new[] { false, true })
        foreach (bool sourceSalvage in new[] { false, true })
        foreach (var salvage in new[] { (Id: 0, Faction: (string?)null), (Id: 2, Faction: (string?)"Britain"), (Id: 5, Faction: (string?)"USA") })
        {
            var (engine, state) = EmptyBoard(db);
            var self = state.CreateWithId(PlainUnit, contextSide, 20, CardLocation.Discard, 0); self.IsGold = !gold;
            var source = state.CreateWithId(PlainUnit, side.Opposite(), 30, CardLocation.Discard, 0);
            source.IsGold = gold; source.IsSalvaged = sourceSalvage; source.SalvageFaction = sourceSalvage ? "Germany" : null; source.SalvagedCardId = 999;
            bool correct = true; int created = 0, modifiers = 0;
            bool Matches(CardInstance card) => card.Owner == side && card.IsGold == gold && card.IsSalvaged == (salvage.Id != 0)
                && card.SalvageFaction == salvage.Faction && card.SalvagedCardId == 0;
            state.CardCreated += card => { if (card.Name == "card_unit_routed_troops") { created++; correct &= Matches(card); } };
            state.CardCreationModifiers += card => { if (card.Name == "card_unit_routed_troops") { modifiers++; correct &= Matches(card); } };
            var ctx = new EffectContext { Engine = engine, State = state, Self = self, Controller = contextSide };
            var result = engine.Api.InvokeByName("SpawnCardInHandBySide", self, new object?[] { (int)side,
                "card_unit_routed_troops", 30, false, false, false, "card_unit_432_infantry_regiment", "", salvage.Id, null }, ctx, out bool handled);
            if (!handled || result is not CardInstance card || card.Name != "card_unit_routed_troops" || !Matches(card)
                || !correct || created != 1 || modifiers != 1 || card.Location != side.HandOf() || state.Random.ConsumedCount != 0)
                return $"手牌生成初始字段不符：{side}/{contextSide}/{gold}/{sourceSalvage}/{salvage}";
        }
        return null;
    }

    private static string? NativeSpawnHandSourceGuard(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int sourceId in new[] { -5, -1, 0 })
        foreach (bool explicitOut in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 30, CardLocation.Discard, 0);
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            int count = state.AllCards.Count;
            var direct = engine.Api.InvokeByName("SpawnCardInHandBySide", source, new object?[] { (int)side,
                "card_unit_routed_troops", sourceId, false, false, false, "", "", 0, null }, ctx, out bool handled);
            var args = new[] { new KismetExpr { Int = (int)side }, new KismetExpr { Name = "card_unit_routed_troops" }, new KismetExpr { Int = sourceId },
                new KismetExpr { Bool = false }, new KismetExpr { Bool = false }, new KismetExpr { Bool = false }, new KismetExpr { Str = "" },
                new KismetExpr { Str = "" }, new KismetExpr { Int = 0 }, new KismetExpr { Var = "spawnedID" } };
            var steps = new KismetStep[] {
                new(0, "call", "SpawnCardInHandBySide", args, explicitOut ? new[] { 9 } : Array.Empty<int>(), null, null, -1, null, null),
                new(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
            };
            var output = engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0), ctx, new Dictionary<string, object?> { ["spawnedID"] = 777 }, "spawnedID");
            if (!handled || direct is not null || state.AllCards.Count != count || state.ActionLog.Count != 0
                || state.Random.ConsumedCount != 0 || !Equals(output.GetValueOrDefault("spawnedID"), 777))
                return "非正来源必须提前返回且不伪造默认输出或使用上下文来源";
        }
        return null;
    }

    private static string? NativeSpawnDeckReceipt(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int count in new[] { -2, 0, 1, 3 })
        foreach (int initial in new[] { 0, 2 })
        foreach (bool hidden in new[] { false, true })
        foreach (bool bottom in new[] { false, true })
        foreach (bool shuffle in new[] { false, true })
        foreach (bool randomPosition in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 30, CardLocation.Discard, 0);
            for (int i = 0; i < initial; i++) state.CreateWithId(PlainUnit, side, 90 - i * 10, side.DeckOf(), i);
            var expectedDeck = state.Deck(side).Select(x => x.CardId).ToList();
            var created = new List<int>();
            state.CardCreated += card => { if (card.Name == "card_unit_1st_infantry_regiment_us") created.Add(card.CardId); };
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            var result = engine.Api.InvokeByName("SpawnCardInDeckBySide", source, new object?[] { (int)side,
                "card_unit_1st_infantry_regiment_us", 30, count, 0, hidden, bottom, shuffle, true, randomPosition, null }, ctx, out bool handled);
            var ids = (result as System.Collections.IEnumerable)?.Cast<object?>().Select(Convert.ToInt32).ToArray();
            var oracle = new UeRandomStream(1);
            foreach (int id in created)
            {
                int roll = NativeRandomDrawOracle(oracle, 0, expectedDeck.Count + 1);
                int at = randomPosition ? Math.Clamp(roll, 0, expectedDeck.Count) : (bottom ? expectedDeck.Count : 0);
                expectedDeck.Insert(at, id);
            }
            if (shuffle) oracle.Shuffle(expectedDeck);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionNewDeck").ToArray();
            var values = new List<ActionValue2> { ActionValue2.Str("side", side.ToWire()), ActionValue2.Str("cards", string.Join(";", expectedDeck)),
                ActionValue2.Str("spawnCards", string.Join(";", created)), ActionValue2.Int("deckSpawn", shuffle ? 3 : (bottom ? 1 : 2)) };
            if (hidden) values.Add(ActionValue2.Bool("hideSpawnFromEnemy", true));
            if (shuffle) values.Add(ActionValue2.Bool("shuffle", true));
            if (!handled || ids is null || !ids.SequenceEqual(created) || created.Count != Math.Max(0, count)
                || actions.Length != 1 || !actions[0].Values.SequenceEqual(values)
                || !state.Deck(side).Select(x => x.CardId).SequenceEqual(expectedDeck)
                || state.Random.Seed != oracle.Seed || state.Random.ConsumedCount != oracle.ConsumedCount)
                return $"生成外层通知/随机游标不符：{side}/{count}/{initial}/{hidden}/{bottom}/{shuffle}/{randomPosition}";
        }
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int sourceId in new[] { -1, 0 })
        foreach (bool shuffle in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 30, CardLocation.Discard, 0);
            state.CreateWithId(PlainUnit, side, 60, side.DeckOf(), 0);
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            engine.Api.InvokeByName("SpawnCardInDeckBySide", source, new object?[] { (int)side,
                "card_unit_1st_infantry_regiment_us", sourceId, 2, 0, true, false, shuffle, false, false, null }, ctx, out _);
            if (state.ActionLog.Count != 0 || state.Random.ConsumedCount != 0 || state.Deck(side).Count != 1)
                return "非正来源ID应在洗牌和外层通知之前返回";
        }
        return null;
    }

    private static string? NativeSpawnDeckReceiptTiming(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib", spawnedName = "card_unit_1st_infantry_regiment_us";
        string[] triggers = { "OnAfterDeckChanged", "OnDeckShuffled" };
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || triggers.Any(locals.ContainsKey)) return "无法安装生成通知探针";
        foreach (string trigger in triggers)
            locals[trigger] = new[] {
                new KismetStep(0, "call", "SpawnCardInHandBySide", new[] { new KismetExpr { Int = (int)Side.Right },
                    new KismetExpr { Str = "card_unit_routed_troops" }, new KismetExpr { Int = 30 } }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
            };
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool shuffle in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var observer = state.CreateWithId(name, side, 20, CardLocation.NotAvailable, 0);
                observer.Definition = new CardDefinition { Name = name, Type = "infantry", UsedTriggers = triggers };
                var source = state.CreateWithId(PlainUnit, side, 30, CardLocation.Discard, 0);
                state.CreateWithId(PlainUnit, side, 60, side.DeckOf(), 0);
                var made = new List<CardInstance>(); int phase = 0; bool beforeNotification = true;
                state.CardCreated += card => {
                    if (card.Name == spawnedName) made.Add(card);
                    if (card.Name != "card_unit_routed_troops") return;
                    beforeNotification &= !state.ActionLog.SelectMany(x => x.SubActions).Any(x => x.Name == "ZActionNewDeck");
                    phase++;
                    if (phase == 1) made[0].Location = CardLocation.Discard;
                    if (phase == 2)
                    {
                        var current = state.Deck(side); for (int i = 0; i < current.Count; i++) current[i].LocationNumber = current.Count - i - 1;
                    }
                    if (phase == 4)
                    {
                        foreach (var current in state.Deck(side)) current.Location = CardLocation.Discard;
                        state.CreateWithId(PlainUnit, side, 1000, side.DeckOf(), 0);
                    }
                };
                var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
                var result = engine.Api.InvokeByName("SpawnCardInDeckBySide", source, new object?[] { (int)side,
                    spawnedName, 30, 2, 0, true, false, shuffle, false, false, null }, ctx, out _);
                var ids = (result as System.Collections.IEnumerable)?.Cast<object?>().Select(Convert.ToInt32).ToArray();
                var receipt = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionNewDeck").ToArray();
                var currentIds = state.Deck(side).Select(x => x.CardId).ToArray();
                if (phase != (shuffle ? 4 : 2) || !beforeNotification || receipt.Length != 1 || ids is null
                    || !ids.SequenceEqual(made.Select(x => x.CardId)) || made[0].Location != CardLocation.Discard
                    || receipt[0].Values[1] != ActionValue2.Str("cards", string.Join(";", currentIds))
                    || receipt[0].Values[2] != ActionValue2.Str("spawnCards", string.Join(";", ids))
                    || (shuffle && !currentIds.SequenceEqual(new[] { 1000 })))
                    return "生成通知必须在逐张T3及可选T22之后读取当前牌库，并保留已离开牌库的生成ID";
            }
        }
        finally { foreach (string trigger in triggers) locals.Remove(trigger); }
        return null;
    }

    private static string? NativeShuffleNotification(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (uint seed in new uint[] { 1, 42, 773639 })
        foreach (bool skip in new[] { false, true })
        foreach (int count in new[] { 0, 1, 3, 5 })
        {
            var (engine, state) = EmptyBoard(db); state.Random.Initialize(unchecked((int)seed));
            int[] ids = { 90, 10, 70, 20, 80 };
            var pool = new List<CardInstance>();
            for (int i = 0; i < count; i++) pool.Add(state.CreateWithId(PlainUnit, side, ids[i], side.DeckOf(), count - 1 - i));
            var expected = pool.AsEnumerable().Reverse().ToList(); var oracle = new UeRandomStream(seed); oracle.Shuffle(expected);
            var ctx = new EffectContext { Engine = engine, State = state, Self = state.Hq(side), Controller = side };
            engine.Api.InvokeByName("ShuffleDeckBySide", ctx.Self, new object?[] { (int)side, skip, 0, null }, ctx, out bool handled);
            var records = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionNewDeck").ToArray();
            if (!handled || !state.Deck(side).SequenceEqual(expected) || state.Random.Seed != oracle.Seed || state.Random.ConsumedCount != count
                || records.Length != (count == 0 || skip ? 0 : 1)) return "洗牌顺序/原始流消耗/空牌库/跳过通知不符";
            if (records.Length == 1 && !records[0].Values.SequenceEqual(new[] { ActionValue2.Str("side", side.ToWire()),
                ActionValue2.Str("cards", string.Join(";", expected.Select(x => x.CardId))), ActionValue2.Str("spawnCards", ""), ActionValue2.Bool("shuffle", true) }))
                return "洗牌通知必须为side/cards/spawnCards/shuffle四字段，无deckSpawn/hideSpawnFromEnemy默认字段";
        }
        return null;
    }

    private static string? NativeShuffleNotificationTiming(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib";
        string[] triggers = { "OnAfterDeckChanged", "OnDeckShuffled" };
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || triggers.Any(locals.ContainsKey)) return "无法安装洗牌时序探针";
        foreach (string trigger in triggers)
            locals[trigger] = new[] {
                new KismetStep(0, "call", "SpawnCardInHandBySide", new[] { new KismetExpr { Int = (int)Side.Right },
                    new KismetExpr { Str = "card_unit_routed_troops" }, new KismetExpr { Int = 30 } }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
            };
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool skip in new[] { false, true })
            foreach (int mutation in new[] { 0, 1, 2 })
            {
                var (engine, state) = EmptyBoard(db);
                var def = new CardDefinition { Name = name, Type = "infantry", UsedTriggers = triggers, Defense = 20 };
                var observer = state.CreateWithId(name, side, 60, CardLocation.Discard, 0); observer.Definition = def;
                var initial = new[] { state.CreateWithId(PlainUnit, side, 90, side.DeckOf(), 2),
                    state.CreateWithId(PlainUnit, side, 10, side.DeckOf(), 0), state.CreateWithId(PlainUnit, side, 70, side.DeckOf(), 1) };
                var expected = new List<int> { 10, 70, 90 }; var oracle = new UeRandomStream(state.Random.Seed); oracle.Shuffle(expected);
                int phase = 0; bool correct = true; int[] currentDeck = Array.Empty<int>();
                state.CardCreated += created => {
                    if (created.Name != "card_unit_routed_troops") return;
                    var records = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionNewDeck").ToArray();
                    if (phase++ == 0)
                    {
                        correct &= records.Length == 0; // T3 runs before notifier
                        if (mutation == 1)
                        {
                            initial[0].Location = CardLocation.Discard;
                            initial[1].LocationNumber = 4; initial[2].LocationNumber = 0;
                            state.CreateWithId(PlainUnit, side, 1000, side.DeckOf(), 2);
                        }
                        if (mutation == 2) foreach (var card in initial) card.Location = CardLocation.Discard;
                        currentDeck = state.Deck(side).Select(x => x.CardId).ToArray();
                        var added = state.CreateWithId(name, side, 1100, CardLocation.NotAvailable, 0);
                        added.Definition = new CardDefinition { Name = name, Type = "infantry", UsedTriggers = new[] { triggers[1] } };
                    }
                    else
                    {
                        correct &= records.Length == (skip ? 0 : 1) && state.Deck(side).Select(x => x.CardId).SequenceEqual(currentDeck);
                        if (!skip) correct &= records[0].Values[1] == ActionValue2.Str("cards", string.Join(";", expected));
                    }
                };
                var ctx = new EffectContext { Engine = engine, State = state, Self = observer, Controller = side };
                engine.Api.InvokeByName("ShuffleDeckBySide", observer, new object?[] { (int)side, skip, 60, null }, ctx, out _);
                if (phase != 3 || !correct || state.Random.Seed != oracle.Seed || state.Random.ConsumedCount != 3)
                    return $"T3/通知/T22顺序或保存的整型ID快照不符：{side}/{skip}/{mutation}/phase={phase}";
            }
            // The spawn wrapper calls ShuffleDeckBySide(..., true, ...).
            // Inspect DURING T22; the wrapper's separate outer notification is
            // a different event and must not be prohibited by this test.
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int amount in new[] { 0, 1 })
            {
                var (engine, state) = EmptyBoard(db);
                var observer = state.CreateWithId(name, side, 20, CardLocation.NotAvailable, 0);
                observer.Definition = new CardDefinition { Name = name, Type = "infantry", UsedTriggers = new[] { triggers[1] } };
                var source = state.CreateWithId(PlainUnit, side, 30, CardLocation.Discard, 0);
                state.CreateWithId(PlainUnit, side, 60, side.DeckOf(), 0);
                bool received = false, noInnerNotification = true;
                state.CardCreated += created => {
                    if (created.Name != "card_unit_routed_troops") return;
                    received = true;
                    noInnerNotification &= !state.ActionLog.SelectMany(x => x.SubActions).Any(x => x.Name == "ZActionNewDeck");
                };
                var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
                engine.Api.InvokeByName("SpawnCardInDeckBySide", source, new object?[] {
                    (int)side, PlainUnit, 30, amount, 0, false, false, true, false, false, null }, ctx, out _);
                if (!received || !noInnerNotification) return "生成入口内部洗牌必须跳过本次NewDeck，同时保留T22";
            }
        }
        finally { foreach (string trigger in triggers) locals.Remove(trigger); }
        return null;
    }

    private static string? NativeCardsSeenNotification(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool enemyTurn in new[] { false, true })
        foreach (bool animation in new[] { false, true })
        foreach (int mode in Enumerable.Range(0, 5))
        {
            var (engine, state) = EmptyBoard(db);
            var a = state.CreateWithId(PlainUnit, side, 90, side.HandOf(), 5);
            var b = state.CreateWithId(PlainUnit, side.Opposite(), 10, side.Opposite().HandOf(), 1); b.CardSeen = true;
            var deck = state.CreateWithId(PlainUnit, side, 70, side.DeckOf(), 0);
            var board = state.CreateWithId(PlainUnit, side, 20, side.HqOf(), 1);
            var discard = state.CreateWithId(PlainUnit, side, 30, CardLocation.Discard, 0);
            var weather = state.CreateWithId("card_event_rain2_deluge", side, 40, side.HandOf(), 2);
            var unavailable = state.CreateWithId(PlainUnit, side, 50, CardLocation.NotAvailable, 0);
            a.Keywords.Add(Keyword.Suppressed); a.Defense = 0;
            var input = mode switch {
                0 => new List<CardInstance>(), 1 => new() { a }, 2 => new() { a, deck, b, a, board, discard, weather, unavailable },
                3 => new() { deck, board, discard, unavailable }, _ => new() { b, b },
            };
            var before = input.ToArray();
            string ids = mode switch { 1 => "90", 2 => "90;10;90;40", 4 => "10;10", _ => "" };
            string seen = mode switch { 1 => "1", 2 => "1;1;1;1", 4 => "1;1", _ => "" };
            engine.Api.ApplySetCardsSeenByCipher(input, enemyTurn, animation);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            if (!input.SequenceEqual(before) || actions.Length != 1 || actions[0].Name != "ZActionCardsSeen"
                || !actions[0].Values.SequenceEqual(new[] { ActionValue2.Str("cardIDs", ids), ActionValue2.Str("seenValues", seen),
                    ActionValue2.Bool("showAnimation", animation), ActionValue2.Bool("enemyTurn", enemyTurn) })
                || state.Random.ConsumedCount != 0 || deck.CardSeen || board.CardSeen || discard.CardSeen || unavailable.CardSeen
                || a.CardSeen != (mode is 1 or 2) || weather.CardSeen != (mode == 2) || !b.CardSeen)
                return $"标记通知/原数组/位置门不符：{side}/{enemyTurn}/{animation}/{mode}";
        }
        return null;
    }

    private static string? NativeIntelNotificationBoundary(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int amount in new[] { -3, 0, 1, 9 })
        foreach (bool empty in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 60, side.HqOf(), 1);
            var victim = state.CreateWithId(PlainUnit, side.Opposite(), 70, side.Opposite().HandOf(), 0); victim.CardSeen = empty;
            engine.Api.SetCardsSeenByCipher(amount, source.CardId, side);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            if (actions.Length != (empty ? 0 : 1)) return "没有未见候选时直接退出，有候选而数量零时仍发送空通知";
            if (!empty)
            {
                bool reveal = amount != 0;
                if (victim.CardSeen != reveal || actions[0].Name != "ZActionCardsSeen"
                    || !actions[0].Values.SequenceEqual(new[] { ActionValue2.Str("cardIDs", reveal ? "70" : ""),
                        ActionValue2.Str("seenValues", reveal ? "1" : ""), ActionValue2.Bool("showAnimation", true), ActionValue2.Bool("enemyTurn", false) }))
                    return "情报必须固定showAnimation=true/enemyTurn=false，并区分零数量与负缩容保留";
            }
        }
        return null;
    }

    private static string? NativeConvertedCardsSeen(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (Side active in new[] { Side.Left, Side.Right })
        foreach (bool skip in new[] { false, true })
        foreach (CardLocation location in new[] { side.HandOf(), side.DeckOf(), CardLocation.Discard })
        {
            var (engine, state) = EmptyBoard(db); state.ActiveSide = active;
            var source = state.CreateWithId(PlainUnit, side, 60, location, 0);
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            var output = engine.Api.InvokeByName("ConvertCard", source, new object?[] { new[] { 60 }, 0, "card_unit_routed_troops", 0, skip, null }, ctx, out bool handled);
            var ids = (output as System.Collections.IEnumerable)?.Cast<object?>().Select(Convert.ToInt32).ToArray();
            if (!handled || ids is not { Length: 1 } || state.ById(ids[0]) is not { } replacement) return "转换夹具未生成替代卡";
            var notifications = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionCardsSeen").ToArray();
            bool hand = location != side.DeckOf();
            if (notifications.Length != (hand ? 1 : 0) || replacement.CardSeen != hand) return "只有转换到手牌的分支执行情报标记通知";
            if (hand && !notifications[0].Values.SequenceEqual(new[] { ActionValue2.Str("cardIDs", ids[0].ToString(System.Globalization.CultureInfo.InvariantCulture)),
                ActionValue2.Str("seenValues", "1"), ActionValue2.Bool("showAnimation", false), ActionValue2.Bool("enemyTurn", side != active) }))
                return "转换到手牌时showAnimation=false，enemyTurn取当前执行方，skipAction不跳过此通知";
        }
        return null;
    }

    private static string? NativeNegativeArrayResize(CardDatabase db)
    {
        foreach (int amount in new[] { int.MinValue, -17, -1 })
        foreach (int size in new[] { 0, 1, 4 })
        foreach (int type in Enumerable.Range(0, 4))
        foreach (bool vm in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId(PlainUnit, Side.Left, 60, Side.Left.HandOf(), 0);
            System.Collections.IList array = type switch {
                0 => Enumerable.Range(0, size).Select(i => i + 11).ToList(),
                1 => Enumerable.Range(0, size).Select(i => i % 2 == 0 ? card : null!).ToList(),
                2 => Enumerable.Range(0, size).Select(i => i % 2 == 0 ? (object?)card : "entry").ToList(),
                _ => Enumerable.Range(0, size).Select(i => i % 2 == 0).ToList(),
            };
            var before = array.Cast<object?>().ToArray();
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = Side.Left };
            if (vm)
            {
                var steps = new KismetStep[] {
                    new(0, "call", "Array_Resize", new[] { new KismetExpr { Var = "pool" }, new KismetExpr { Int = amount } }, Array.Empty<int>(), null, null, -1, null, null),
                    new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Int = 123 }, null, -1, "_auditResizeContinued", null) { DestinationScope = "instance" },
                    new(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
                };
                engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0), ctx,
                    new Dictionary<string, object?> { ["pool"] = array }, "pool");
                if (!Equals(card.BlueprintVariables.GetValueOrDefault("_auditResizeContinued"), 123)) return "负缩容不能中止后续VM指令";
            }
            else
            {
                object? result = engine.Api.InvokeByName("Array_Resize", card, new object?[] { array, amount }, ctx, out bool handled);
                if (!handled || result is not null) return "Array_Resize负长度仍应按void操作处理";
            }
            if (!array.Cast<object?>().SequenceEqual(before) || state.Random.ConsumedCount != 0 || state.ActionLog.Count != 0 || state.UnimplementedCalls.Count != 0)
                return $"负缩容不能清空/重排数组或消费随机流：{amount}/{size}/{type}/{vm}";
        }
        return null;
    }

    private static string? NativeIntelHandQuery(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool changedOwner in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var a = state.CreateWithId(PlainUnit, side, 90, side.HandOf(), 8);
            var b = state.CreateWithId(PlainUnit, side, 10, side.Opposite().HandOf(), 1);
            state.CreateWithId("card_event_rain2_deluge", side, 20, side.HandOf(), 0);
            var c = state.CreateWithId(PlainUnit, changedOwner ? side.Opposite() : side, 70, side.HandOf(), 0);
            if (changedOwner) state.ChangeOwner(c, side);
            state.CreateWithId(PlainUnit, side.Opposite(), 30, side.HandOf(), 2);
            state.CreateWithId(PlainUnit, side, 80, side.HqOf(), 1);
            var dynamicWeather = state.CreateWithId(PlainUnit, side, 40, side.HandOf(), 3);
            dynamicWeather.CustomJson["__customGameplayTags"] = "subtype.rain";
            var expected = new[] { a, b, c };
            var ctx = new EffectContext { Engine = engine, State = state, Self = a, Controller = side };
            var actual = engine.Api.InvokeByName("GetCardsInHandBySide", a, new object?[] { (int)side, null }, ctx, out bool handled) as List<CardInstance>;
            if (!handled || actual is null || !actual.SequenceEqual(expected)
                || !engine.Api.GetCardsInHandBySide(side).SequenceEqual(expected) || state.Random.ConsumedCount != 0)
                return "手牌原语必须保留全局次序、按当前Owner筛两种手牌位置并排除静态/动态天气";
        }
        return null;
    }

    private static string? NativeIntelShuffle(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (uint seed in new uint[] { 1, 42, 773639 })
        foreach (int amount in new[] { int.MinValue, -9, -1, 0, 1, 2, 99, int.MaxValue })
        foreach (bool empty in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); state.Random.Initialize(unchecked((int)seed));
            var source = state.CreateWithId(PlainUnit, side, 60, side.HandOf(), 0);
            var enemy = side.Opposite();
            var a = state.CreateWithId(PlainUnit, enemy, 90, enemy.HandOf(), 7);
            var b = state.CreateWithId(PlainUnit, enemy, 10, side.HandOf(), 1);
            var weather = state.CreateWithId("card_event_rain2_deluge", enemy, 20, enemy.HandOf(), 0);
            var c = state.CreateWithId(PlainUnit, side, 70, enemy.HandOf(), 0); state.ChangeOwner(c, enemy);
            var alreadySeen = state.CreateWithId(PlainUnit, enemy, 30, enemy.HandOf(), 2); alreadySeen.CardSeen = true;
            if (empty) { a.CardSeen = true; b.CardSeen = true; c.CardSeen = true; }
            var expected = empty ? new List<CardInstance>() : new() { a, b, c };
            var oracle = new UeRandomStream(seed); oracle.Shuffle(expected);
            var chosen = amount < 0 ? expected.ToArray() : expected.Take(Math.Min(amount, expected.Count)).ToArray();
            engine.Api.SetCardsSeenByCipher(amount, source.CardId, side);
            foreach (var card in new[] { a, b, c })
                if (card.CardSeen != (empty || chosen.Contains(card))) return "情报洗牌必须绑定过滤后的全局顺序";
            if (source.CardSeen || weather.CardSeen || !alreadySeen.CardSeen || state.Random.Seed != oracle.Seed
                || state.Random.ConsumedCount != (empty ? 0 : 3))
                return "情报应先筛未见非天气候选，非空时零数量仍洗完整池，不套用随机辅助空耗";
        }
        return null;
    }

    private static string? NativeIntelSnapshot(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib", trigger = "OnIntelTriggered";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(trigger)) return "无法安装情报探针";
        locals[trigger] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = "intelCard", Scope = "local" }, null, -1, "_auditIntelSource", null) { DestinationScope = "instance" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = "intelValue", Scope = "local" }, null, -1, "_auditIntelValue", null) { DestinationScope = "instance" },
            new KismetStep(2, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Math = "Add_IntInt", Args = new[] {
                new KismetExpr { Var = "_auditIntelCount", Scope = "instance" }, new KismetExpr { Int = 1 } } }, null, -1, "_auditIntelCount", null) { DestinationScope = "instance" },
            new KismetStep(3, "call", "SpawnCardInDeckBySide", new[] { new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(4, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (CardLocation location in new[] { side.HandOf(), side.DeckOf(), CardLocation.Discard, CardLocation.NotAvailable })
            foreach (int amount in new[] { -3, 0, 2 })
            foreach (bool replaceSource in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var def = new CardDefinition { Name = name, Type = "infantry", Defense = 20, UsedTriggers = new[] { trigger } };
                var source = state.CreateWithId(name, side, 60, side.HqOf(), 1); source.Definition = def;
                var later = state.CreateWithId(name, side, 61, location, 2); later.Definition = def;
                var suppressed = state.CreateWithId(name, side, 62, side.HqOf(), 3); suppressed.Definition = def; suppressed.Keywords.Add(Keyword.Suppressed);
                CardInstance currentSource = source; CardInstance? added = null, fresh = null;
                bool first = true; state.StopFurtherActions = true;
                state.CardCreated += created => {
                    if (!first || created.Name != "card_unit_routed_troops") return;
                    first = false;
                    later.Keywords.Add(Keyword.Suppressed); later.Definition = new CardDefinition { Name = name, Type = "infantry" }; later.Location = CardLocation.NotAvailable;
                    added = state.CreateWithId(name, side, 1000, side.HqOf(), 4); added.Definition = def;
                    if (replaceSource) { state.Remove(source); currentSource = state.CreateWithId(PlainUnit, side, 60, side.HqOf(), 1); }
                    fresh = state.CreateWithId(PlainUnit, side.Opposite(), 1100, side.Opposite().HandOf(), 0);
                };
                engine.Api.SetCardsSeenByCipher(amount, 60, side);
                if (first || !Equals(source.BlueprintVariables.GetValueOrDefault("_auditIntelCount"), 1)
                    || !Equals(later.BlueprintVariables.GetValueOrDefault("_auditIntelCount"), 1)
                    || source.BlueprintVariables.GetValueOrDefault("_auditIntelSource") != source
                    || later.BlueprintVariables.GetValueOrDefault("_auditIntelSource") != currentSource
                    || !Equals(later.BlueprintVariables.GetValueOrDefault("_auditIntelValue"), amount)
                    || added is null || added.BlueprintVariables.ContainsKey("_auditIntelCount") || suppressed.BlueprintVariables.ContainsKey("_auditIntelCount")
                    || (fresh is not null && fresh.CardSeen != (amount != 0)))
                    return $"T28快照/原始数量/逐次解析/回调后候选不符：{side}/{location}/{amount}/{replaceSource}";
            }
        }
        finally { locals.Remove(trigger); }
        return null;
    }

    private static string? NativeMatchSeedWidth(CardDatabase db)
    {
        foreach (ulong seed in new ulong[] { 0, 1, 42, 0x7fffffff, 0x80000000, 0xffffffff,
            0x100000000, 0x100000001, 0x123456780000002a, ulong.MaxValue })
        {
            var engine = new MatchEngine(db, Array.Empty<string>(), Array.Empty<string>(), seed);
            var state = engine.State;
            uint truncated = unchecked((uint)seed);
            if (state.Random.Seed != truncated || state.Random.InitialSeed != unchecked((int)truncated)
                || state.Random.ConsumedCount != 0 || state.Seed != seed)
                return $"构造种子应使用int32低位、不消费，原始输入仅作元数据：{seed}";
            var oracle = new UeRandomStream(truncated);
            for (int draw = 0; draw < 4; draw++)
                if (engine.Api.RandomIntFromRangeWithStream(-9, 20) != NativeRandomDrawOracle(oracle, -9, 20)
                    || state.Random.Seed != oracle.Seed || state.Random.ConsumedCount != oracle.ConsumedCount)
                    return "等低32位种子应产生同一规则随机序列";
        }
        return null;
    }

    private static string? NativeMatchSeedContinuity(CardDatabase db)
    {
        foreach (ulong seed in new ulong[] { 0, 1, 42, 0xffffffff, 1000000000, 0x100000001 })
        {
            var engine = new MatchEngine(db, Array.Empty<string>(), Array.Empty<string>(), seed);
            var state = engine.State;
            state.CreateWithId("card_location_berlin", Side.Left, 1, Side.Left.HqOf(), 0);
            state.CreateWithId("card_location_berlin", Side.Right, 41, Side.Right.HqOf(), 0);
            state.SetHqDefense(Side.Left, 20); state.SetHqDefense(Side.Right, 20);
            foreach (Side side in new[] { Side.Left, Side.Right })
                for (int i = 0; i < 4; i++) state.CreateWithId(PlainUnit, side, (int)side * 100 + i, side.DeckOf(), i);
            state.Turn = 1; state.ActiveSide = Side.Left;
            var oracle = new UeRandomStream(seed);
            for (int turn = 0; turn < 4; turn++)
            {
                if (engine.Api.RandomIntFromRangeWithStream(0, 99) != NativeRandomDrawOracle(oracle, 0, 99))
                    return "跨回合抽取未沿用连续流";
                uint before = state.Random.Seed; long count = state.Random.ConsumedCount;
                engine.StartTurn(state.ActiveSide, draw: false);
                engine.EndTurn(state.ActiveSide); // records action ID, switches side and draws a fixed card
                if (state.IsFinished || state.Random.Seed != before || state.Random.ConsumedCount != count
                    || state.Random.InitialSeed != unchecked((int)(uint)seed))
                    return "无随机效果的回合/行动不应重播种或消费规则流";
            }
            var ends = state.ActionLog.Where(x => x.ActionType == "XActionEndOfTurn").ToArray();
            if (ends.Length != 4 || ends.Select(x => x.ActionId).Distinct().Count() != 4 || !ends.Select(x => x.ActionId).SequenceEqual(ends.Select(x => x.ActionId).OrderBy(x => x))
                || state.Random.Seed != oracle.Seed || state.Random.ConsumedCount != oracle.ConsumedCount)
                return "必须真实记录行动并保持跨行动的随机状态";
        }
        return null;
    }

    private static string? NativePaddedRandomVectors(CardDatabase db)
    {
