        }
        return null;
    }

    private static string? NativeRandomPriorityPools(CardDatabase db)
    {
        foreach (uint seed in new uint[] { 0, 1, 42, uint.MaxValue, 1000000000 })
        foreach (int mode in Enumerable.Range(0, 6)) // direct default/false/true, dispatch false/true/default
        foreach (int variant in Enumerable.Range(0, 6))
        {
            var (engine, state) = EmptyBoard(db);
            state.Random.Initialize(unchecked((int)seed));
            var n = state.CreateWithId(PlainUnit, Side.Left, 90, CardLocation.BoardFrontline, 1);
            var p = state.CreateWithId(PlainUnit, Side.Right, 10, CardLocation.Discard, 0);
            var q = state.CreateWithId(PlainUnit, Side.Left, 70, Side.Left.DeckOf(), 0);
            p.CustomJson["customName1"] = "x;alwaysselectedasrandom;;";
            q.CustomJson["customName1"] = "AlwaysSelectedAsRandom;AlwaysSelectedAsRandom";
            p.Keywords.Add(Keyword.Suppressed); p.Defense = 0;
            var pool = variant switch {
                0 => new List<CardInstance>(), 1 => new() { n }, 2 => new() { p },
                3 => new() { n, p }, 4 => new() { q, n, p, q }, _ => new() { n, n },
            };
            var original = pool.ToArray();
            bool skip = mode is 2 or 4;
            var expected = skip ? original : variant switch {
                2 or 3 => new[] { p }, 4 => new[] { q, p, q }, _ => original,
            };
            var ctx = new EffectContext { Engine = engine, State = state, Self = n, Controller = Side.Left };
            var oracle = new UeRandomStream(seed);
            for (int draw = 0; draw < 12; draw++)
            {
                long before = state.Random.ConsumedCount;
                var want = expected.Length == 0 ? null : expected[NativeRandomDrawOracle(oracle, 0, expected.Length - 1)];
                CardInstance? actual;
                if (mode >= 3)
                {
                    actual = engine.Api.InvokeByName("GetRandomCard", n, (mode == 5 ? new object?[] { pool } : new object?[] { pool, skip, null }), ctx, out bool handled) as CardInstance;
                    if (!handled) return "GetRandomCard派发缺失";
                }
                else actual = mode == 0 ? engine.Api.GetRandomCard(pool) : engine.Api.GetRandomCard(pool, skip);
                if (actual != want || !pool.SequenceEqual(original) || state.Random.Seed != oracle.Seed
                    || state.Random.ConsumedCount != oracle.ConsumedCount)
                    return $"优先候选/顺序/输入不变性/现有辅助函数调用不符：seed={seed}/mode={mode}/pool={variant}/draw={draw}";
            }
        }
        return null;
    }

    private static string? NativeRandomPriorityAttributes(CardDatabase db)
    {
        var cases = new (string Name1, string Name2, bool Priority)[] {
            ("AlwaysSelectedAsRandom", "", true), ("ALWAYSSELECTEDASRANDOM", "", true),
            ("x;;AlwaysSelectedAsRandom;y", "", true), ("AlwaysSelectedAsRandom;AlwaysSelectedAsRandom", "", true),
            (" AlwaysSelectedAsRandom", "", false), ("AlwaysSelectedAsRandom ", "", false),
            ("xAlwaysSelectedAsRandom", "", false), ("AlwaysSelectedAsRandomx", "", false),
            ("x,AlwaysSelectedAsRandom", "", false), ("", "AlwaysSelectedAsRandom", false),
            ("None", "", false), ("", "", false),
        };
        foreach (var test in cases)
        {
            var (engine, state) = EmptyBoard(db);
            var n = state.CreateWithId(PlainUnit, Side.Left, 60, Side.Left.HandOf(), 0);
            var candidate = state.CreateWithId(PlainUnit, Side.Right, 70, CardLocation.NotAvailable, 0);
            candidate.CustomJson["customName1"] = test.Name1; candidate.CustomJson["customName2"] = test.Name2;
            var pool = new List<CardInstance> { n, candidate };
            var oracle = new UeRandomStream(state.Random.Seed);
            for (int draw = 0; draw < 16; draw++)
            {
                int index = NativeRandomDrawOracle(oracle, 0, test.Priority ? 0 : 1);
                var want = test.Priority ? candidate : pool[index];
                if (engine.Api.GetRandomCard(pool) != want) return $"名称边界误识别：{test.Name1}/{test.Name2}";
            }
        }
        {
            var (engine, state) = EmptyBoard(db);
            var normal = state.CreateWithId(PlainUnit, Side.Left, 60, Side.Left.HqOf(), 1);
            var royal = state.CreateWithId("card_unit_royal_scots", Side.Right, 70, Side.Right.HandOf(), 0);
            var pool = new List<CardInstance> { normal, royal };
            if (engine.Api.GetRandomCard(pool) != royal) return "Royal Scots静态标记未进入优先池";
            var ctx = new EffectContext { Engine = engine, State = state, Self = royal, Controller = Side.Right };
            engine.Api.InvokeByName("CustomName1Remove", royal, new object?[] { "AlwaysSelectedAsRandom" }, ctx, out bool handled);
            if (!handled || royal.CustomJson.ContainsKey("customName1")) return "真实卡牌优先标记移除失败";
            var oracle = new UeRandomStream(state.Random.Seed);
            for (int draw = 0; draw < 16; draw++)
                if (engine.Api.GetRandomCard(pool) != pool[NativeRandomDrawOracle(oracle, 0, 1)]) return "标记移除后不应按卡名继续强制选中";
            normal.CustomJson["customName1"] = "AlwaysSelectedAsRandom";
            if (engine.Api.GetRandomCard(pool) != normal) return "优先标记新增后应立即生效";
        }
        return null;
    }

    private static string? NativeChangePinnedTurnsContract(CardDatabase db)
    {
        var sums = new (int Before, int Delta, int After)[] { (4, 2, 5), (3, -1, 2), (1, -1, 0), (0, 0, 0),
            (-2, 1, 0), (5, 50, 5), (int.MaxValue, 1, 0), (int.MinValue, -1, 5), (int.MaxValue, int.MaxValue, 0), (0, int.MinValue, 0) };
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (CardLocation location in new[] { side.HqOf(), CardLocation.BoardFrontline, side.HandOf(), side.DeckOf(), CardLocation.Discard, CardLocation.NotAvailable })
        foreach (bool unit in new[] { false, true })
        foreach (var sum in sums)
        foreach (int giver in new[] { 0, -7, 9999 })
        {
            var (engine, state) = EmptyBoard(db);
            var target = state.CreateWithId(PlainUnit, side, 60, location, 1);
            target.Definition = new CardDefinition { Name = PlainUnit, Type = unit ? "infantry" : "order", Defense = 20 };
            target.PinnedTurns = sum.Before;
            target.ReceivedAbilitiesFromCards["pinned"] = new List<int> { 71 };
            target.BuffsBySource[(71, false)] = new CardBuff { SourceCardId = 71, Pinned = 1 };
            state.CreateWithId("card_unit_cromwell_mk_iv", side, 70, side.HqOf(), 2);
            state.CreateWithId("card_event_creeping_barrage", side, 72, CardLocation.Discard, 0);
            state.CreateWithId("card_event_honorifics", side, 73, side.DeckOf(), 0);
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            var ctx = new EffectContext { Engine = engine, State = state, Self = state.Hq(side), Target = target, Controller = side };
            engine.Api.InvokeByName("ChangedPinnedTurns", ctx.Self, new object?[] { 60, giver, sum.Delta, null }, ctx, out bool handled);
            bool valid = location.IsBoard() && unit;
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            if (!handled || target.PinnedTurns != (valid ? sum.After : sum.Before) || target.IsPinned != (target.PinnedTurns > 0)
                || !target.ReceivedAbilitiesFromCards["pinned"].SequenceEqual(new[] { 71 }) || target.BuffsBySource[(71, false)].Pinned != 1
                || actions.Length != (valid ? 1 : 0) || trace.Count != 0)
                return $"ChangedPinnedTurns契约不符：{side}/{location}/unit={unit}/{sum}/giver={giver}";
            if (valid && (actions[0].Name != "ZActionChangePinnedTurns"
                || !actions[0].Values.Select(x => x.Name).SequenceEqual(new[] { "cardID", "instigatorID", "turnsToChange" })
                || actions[0].Values[0].Value != 60 || actions[0].Values[1].Value != giver || actions[0].Values[2].Value != sum.Delta))
                return "时长通知必须保持目标ID、来源和原始增量，不能写入夹值结果";
            engine.Api.InvokeByName("ChangedPinnedTurns", ctx.Self, new object?[] { 99999, giver, sum.Delta, null }, ctx, out _);
            if (target.PinnedTurns != (valid ? sum.After : sum.Before) || state.ActionLog.SelectMany(x => x.SubActions).Count() != actions.Length)
                return "无效时长修改目标不能回退到上下文";
        }
        return null;
    }

    private static string? NativePinExpiryMatrix(CardDatabase db)
    {
        foreach (Side owner in new[] { Side.Left, Side.Right })
        foreach (Side ending in new[] { Side.Left, Side.Right })
        foreach (CardLocation location in new[] { owner.HqOf(), CardLocation.BoardFrontline, owner.HandOf(), owner.DeckOf(), CardLocation.Discard, CardLocation.NotAvailable })
        foreach (bool unit in new[] { false, true })
        foreach (int turns in new[] { -2, 0, 1, 2, 5, int.MaxValue })
        {
            var (engine, state) = EmptyBoard(db); state.ActiveSide = ending;
            var target = state.CreateWithId(PlainUnit, owner, 60, location, 1);
            target.Definition = new CardDefinition { Name = PlainUnit, Type = unit ? "infantry" : "order", Defense = 20 };
            target.PinnedTurns = turns;
            target.Keywords.Add(Keyword.Suppressed); // No suppression gate on decrement/unpin.
            target.ReceivedAbilitiesFromCards["pinned"] = new List<int> { 71 };
            target.BuffsBySource[(71, false)] = new CardBuff { SourceCardId = 71, Pinned = 1 };
            engine.EndTurn(ending);
            bool decrement = turns > 1 && unit && location.IsBoard(), unpin = turns == 1;
            int expected = unpin ? 0 : decrement ? Math.Min(turns - 1, 5) : turns;
            var actions = state.ActionLog.SelectMany(x => x.SubActions)
                .Where(x => x.Name is "ZActionChangePinnedTurns" or "ZActionUnpinUnit").ToArray();
            if (target.PinnedTurns != expected || actions.Length != (unpin || decrement ? 1 : 0)
                || !target.ReceivedAbilitiesFromCards["pinned"].SequenceEqual(new[] { 71 })
                || (target.BuffsBySource.GetValueOrDefault((71, false))?.Pinned ?? 0) != (unpin ? 0 : 1))
                return $"回合末压制位置/时长不符：owner={owner} ending={ending}/{location}/unit={unit}/{turns} 实际{target.PinnedTurns}";
            if (decrement && (actions[0].Name != "ZActionChangePinnedTurns" || actions[0].Values[0].Value != 60
                || actions[0].Values[1].Value != 0 || actions[0].Values[2].Value != -1)) return "回合末递减必须走时长通知且来源为0";
            if (unpin && (actions[0].Name != "ZActionUnpinUnit" || actions[0].Values[0].Value != 60)) return "时长1直接解除，不能先修改到0";
        }
        return null;
    }

    private static string? NativePinExpiryLiveIndex(CardDatabase db)
    {
        const string name = "card_unit_51e_regiment", trigger = "OnOtherUnitUnpinned";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals || locals.ContainsKey(trigger))
            return "无法安装回合末T62探针";
        locals[trigger] = new[] {
            new KismetStep(0, "call", "SpawnCardInDeckBySide", new[] { new KismetExpr { Int = (int)Side.Right },
                new KismetExpr { Str = "card_unit_routed_troops" }, new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            foreach (Side ending in new[] { Side.Left, Side.Right })
            foreach (int mutation in Enumerable.Range(0, 5))
            {
                var (engine, state) = EmptyBoard(db); state.ActiveSide = ending;
                var earlier = state.CreateWithId(PlainUnit, Side.Left, 80, CardLocation.Discard, 0);
                var first = state.CreateWithId(PlainUnit, Side.Right, 90, Side.Right.HqOf(), 1); first.PinnedTurns = 1;
                var later = state.CreateWithId(PlainUnit, Side.Left, 10, Side.Left.HqOf(), 1); later.PinnedTurns = 2;
                var observer = state.CreateWithId(name, Side.Left, 20, Side.Left.HqOf(), 2);
                observer.Definition = new CardDefinition { Name = name, Type = "infantry", Defense = 20, UsedTriggers = new[] { trigger } };
                bool seen = false; CardInstance? added = null;
                state.CardCreated += created => {
                    if (seen || created.Name != "card_unit_routed_troops") return;
                    seen = true; added = created;
                    if (mutation == 0) { state.Move(created, Side.Right.HqOf()); created.PinnedTurns = 2; }
                    if (mutation == 1) state.Remove(first);
                    if (mutation == 2) state.Remove(earlier);
                    if (mutation == 3) state.ChangeOwner(later, Side.Right);
                    if (mutation == 4) state.Move(later, Side.Left.DeckOf());
                };
                engine.EndTurn(ending);
                bool processedLater = mutation is 0 or 3;
                var actions = state.ActionLog.SelectMany(x => x.SubActions)
                    .Where(x => x.Name is "ZActionChangePinnedTurns" or "ZActionUnpinUnit").ToArray();
                int[] expectedIds = mutation == 0 && added is not null ? new[] { 90, 10, added.CardId }
                    : processedLater ? new[] { 90, 10 } : new[] { 90 };
                if (!seen || first.PinnedTurns != 0 || later.PinnedTurns != (processedLater ? 1 : 2)
                    || added is null || added.PinnedTurns != (mutation == 0 ? 1 : 0)
                    || !actions.Select(x => x.Values[0].Value).SequenceEqual(expectedIds))
                    return $"回合末必须按实时对局表索引：ending={ending} mutation={mutation} first={first.PinnedTurns} later={later.PinnedTurns} added={added?.PinnedTurns}";
            }
        }
        finally { locals.Remove(trigger); }
        return null;
    }

    private static string? NativePinSuppressionSources(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (string key in new[] { "trigger", "destruction", "passive", "lethal", "custom", "cantMove", "canOperateWhilePinned", "cantBePinned", "" })
        foreach (bool foreign in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); var card = MakeActionQuotaProbe(state, side, "infantry");
            card.ReceivedAbilitiesFromCards[key] = foreign ? new List<int> { 0, 60, 71, -7, 9999, 71 } : new List<int> { 0, 60 };
            engine.Api.SuppressUnit(card);
            bool keep = foreign && key is not ("trigger" or "destruction" or "passive" or "lethal" or "custom");
            if (card.ReceivedAbilitiesFromCards.ContainsKey(key) != keep
                || (keep && !card.ReceivedAbilitiesFromCards[key].SequenceEqual(new[] { 71, -7, 9999, 71 })))
                return "抑制来源过滤必须保留外部重复/无效ID，排除零及自身：" + key;
        }
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int source in new[] { 0, 60, 71, -7, 9999 })
        {
            var (engine, state) = EmptyBoard(db); var card = MakeActionQuotaProbe(state, side, "infantry");
            engine.Api.PinUnit(card, source);
            engine.Api.SuppressUnit(card);
            bool retained = source != 0 && source != card.CardId;
            if (!card.IsPinned || card.ReceivedAbilitiesFromCards.ContainsKey("pinned") != retained
                || card.BuffsBySource.GetValueOrDefault((source, false))?.Pinned != 1)
                return "抑制只过滤压制的零/自身来源，不应解除回合数或删战斗账本";
            engine.Api.RemovePin(card);
            if ((card.BuffsBySource.GetValueOrDefault((source, false))?.Pinned ?? 0) != (retained ? 0 : 1))
                return "抑制后解除压制应按保留来源递减账本";
        }
        return null;
    }

    private static string? NativePinSources(CardDatabase db)
    {
        using var t29 = InstallAbilitiesChangedProbes();
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool active in new[] { false, true })
        foreach (int turns in new[] { -1, 0, 1, 4 })
        foreach (int mode in Enumerable.Range(0, 4))
        foreach (int giver in new[] { 0, -7, 9999 })
        foreach (int old in new[] { -1, 0, 1 })
        {
            var (engine, state) = EmptyBoard(db);
            var target = MakeActionQuotaProbe(state, side, "infantry");
            state.CreateWithId("card_event_honorifics", side, 70, side.DeckOf(), 0);
            state.ActiveSide = active ? side : side.Opposite();
            target.PinnedTurns = turns;
            target.Keywords.Add(Keyword.Covert); // PinUnit has no CanCardBeBuffed/Covert gate.
            if (mode != 0) target.ReceivedAbilitiesFromCards["pinned"] = mode == 1 ? new List<int>()
                : mode == 2 ? new List<int> { 1234 } : new List<int> { giver };
            target.BuffsBySource[(giver, false)] = new CardBuff { SourceCardId = giver, Attack = 2, Pinned = old };
            var ctx = new EffectContext { Engine = engine, State = state, Self = state.Hq(side), Target = target, Controller = side };
            engine.Api.InvokeByName("PinUnit", ctx.Self, new object?[] { 60, giver }, ctx, out bool handled);
            bool duplicate = mode == 3;
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            var expectedSources = mode == 2 ? new[] { 1234, giver } : new[] { giver };
            if (!handled || !target.ReceivedAbilitiesFromCards["pinned"].SequenceEqual(expectedSources)
                || target.PinnedTurns != (duplicate ? turns : Math.Max(turns, active ? 3 : 2))
                || target.BuffsBySource[(giver, false)].Pinned != old + (duplicate ? 0 : 1)
                || target.BuffsBySource[(giver, false)].Attack != 2 || actions.Length != (duplicate ? 0 : 1))
                return $"压制来源不符：{side}/active={active}/turns={turns}/mode={mode}/giver={giver}/old={old}";
            if (!duplicate && (actions[0].Name != "ZActionPinUnit"
                || !actions[0].Values.Select(x => x.Name).SequenceEqual(new[] { "cardID", "instigatorID" })
                || actions[0].Values[0].Value != 60 || actions[0].Values[1].Value != giver)) return "压制通知丢失来源或字段顺序";
            string before = System.Text.Json.JsonSerializer.Serialize(target.Snapshot());
            engine.Api.InvokeByName("PinUnit", ctx.Self, new object?[] { 99999, giver }, ctx, out _);
            engine.Api.InvokeByName("RemovePin", ctx.Self, new object?[] { 99999, null }, ctx, out _);
            if (before != System.Text.Json.JsonSerializer.Serialize(target.Snapshot()) || state.Hq(side).IsPinned)
                return "无效压制ID不得回退到自身";
        }
        return null;
    }

    private static string? NativeUnpinSources(CardDatabase db)
    {
        using var t29 = InstallAbilitiesChangedProbes();
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (CardLocation location in new[] { side.HqOf(), side.HandOf(), side.DeckOf(), CardLocation.Discard })
        foreach (int mode in Enumerable.Range(0, 5))
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId(PlainUnit, side, 60, location, 1);
            state.CreateWithId("card_event_honorifics", side, 70, side.DeckOf(), 0);
            int[] sources = mode switch { 0 or 1 => Array.Empty<int>(), 2 => new[] { 0 },
                3 => new[] { 71, 71, -7, 9999 }, _ => new[] { 71 } };
            if (mode != 0) card.ReceivedAbilitiesFromCards["pinned"] = sources.ToList();
            card.BuffsBySource[(71, false)] = new CardBuff { SourceCardId = 71, Pinned = 2 };
            card.PinnedTurns = 2;
            engine.Api.RemovePin(card);
            if (card.IsPinned || card.Keywords.Contains(Keyword.Pinned)
                || card.ReceivedAbilitiesFromCards.ContainsKey("pinned") != (mode != 0)
                || (mode != 0 && !card.ReceivedAbilitiesFromCards["pinned"].SequenceEqual(sources))) return "解除不得删除来源表或保留正回合数";
            foreach (int id in new[] { 0, 71, -7, 9999 })
            {
                int expected = (id == 71 ? 2 : 0) - sources.Count(x => x == id);
                if ((card.BuffsBySource.GetValueOrDefault((id, false))?.Pinned ?? 0) != expected)
                    return $"解除账本递减应保留重复条目和无效来源：{mode}/{id}";
                if (expected == 0 && card.BuffsBySource.ContainsKey((id, false))) return "仅有Pinned且过零的账本应删除";
            }
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            if (actions.Length != 1 || actions[0].Name != "ZActionUnpinUnit" || actions[0].Values.Count != 1
                || actions[0].Values[0].Name != "cardID" || actions[0].Values[0].Value != 60) return "解除通知不是原生单字段";
            string before = System.Text.Json.JsonSerializer.Serialize(card.Snapshot());
            engine.Api.RemovePin(card);
            if (before != System.Text.Json.JsonSerializer.Serialize(card.Snapshot()) || state.ActionLog.SelectMany(x => x.SubActions).Count() != 1)
                return "未被压制时重复解除应无副作用";
        }
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db); var card = MakeActionQuotaProbe(state, side, "infantry");
            engine.Api.PinUnit(card, 71);
            if (card.Snapshot().PinnedBuffsBySource.GetValueOrDefault("71/False") != 1
                || card.BuffsBySource[(71, false)].Clone().Pinned != 1) return "压制账本必须进入快照/Clone";
            engine.Api.RemovePin(card);
            int count = state.ActionLog.SelectMany(x => x.SubActions).Count();
            engine.Api.PinUnit(card, 71);
            if (card.IsPinned || state.ActionLog.SelectMany(x => x.SubActions).Count() != count) return "保留来源后同源重复压制必须提前返回";
            engine.Api.PinUnit(card, 72);
            if (!card.IsPinned || !card.ReceivedAbilitiesFromCards["pinned"].SequenceEqual(new[] { 71, 72 })) return "新来源压制必须仍然成功";
            card.ResetAttributes();
            if (card.IsPinned || card.BuffsBySource.Count != 0 || card.ReceivedAbilitiesFromCards.ContainsKey("pinned")) return "重置必须清除压制来源账本";
        }
        return null;
    }

    private static string? NativePinnedPredicate(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int turns in new[] { -2, 0, 1, 4 })
        foreach (bool raw in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); var card = MakeActionQuotaProbe(state, side, "infantry");
            card.PinnedTurns = turns;
            if (raw) card.Keywords.Add(Keyword.Pinned); else card.Keywords.Remove(Keyword.Pinned);
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            object? result = engine.Api.InvokeByName("IsPinned", card, new object?[] { null }, ctx, out bool handled);
            if (!handled || !Equals(result, turns > 0) || card.IsPinned != (turns > 0)) return "IsPinned不能读取独立关键字";
            bool moved = engine.MoveUnit(card, 0, out _);
            if (moved != (turns <= 0)) return "移动门应与原生IsPinned一致";
        }
        return null;
    }

    private static string? NativePinBroadcastSnapshots(CardDatabase db)
    {
        const string cardName = "card_unit_typhoon_mk_ib";
        if (KismetLibrary.Default?.Find(cardName)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals)
            return "无法安装压制快照探针";
        string[] triggers = { "OnOtherUnitPinned", "OnOtherUnitUnpinned" };
        foreach (string trigger in triggers)
        {
            if (locals.ContainsKey(trigger)) return "探针名称冲突";
            locals[trigger] = new[] {
                new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = trigger == triggers[0] ? "cardBeingPinned" : "card", Scope = "local" }, null, -1, "_auditPinSubject", null) { DestinationScope = "instance" },
                new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Math = "Add_IntInt", Args = new[] {
                    new KismetExpr { Var = "_auditPinCount", Scope = "instance" }, new KismetExpr { Int = 1 } } }, null, -1, "_auditPinCount", null) { DestinationScope = "instance" },
                new KismetStep(2, "call", "SpawnCardInDeckBySide", new[] { new KismetExpr { Int = (int)Side.Right },
                    new KismetExpr { Str = "card_unit_routed_troops" }, new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 } }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
            };
        }
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool pin in new[] { false, true })
            foreach (CardLocation location in new[] { side.HandOf(), side.DeckOf(), CardLocation.Discard, CardLocation.NotAvailable })
            {
                var (engine, state) = EmptyBoard(db);
                var def = new CardDefinition { Name = cardName, Type = "infantry", Attack = 2, Defense = 20, UsedTriggers = triggers };
                var subject = state.CreateWithId(cardName, side, 60, side.HqOf(), 1); subject.Definition = def;
                state.ActiveSide = side;
                var later = state.CreateWithId(cardName, side, 61, location, 1); later.Definition = def;
                var initialSuppressed = state.CreateWithId(cardName, side, 62, side.HqOf(), 2); initialSuppressed.Definition = def;
                initialSuppressed.Keywords.Add(Keyword.Suppressed);
                CardInstance? added = null; bool first = true; bool notificationFirst = true;
                state.CardCreated += created => {
                    if (created.Name != "card_unit_routed_troops" || !first) return;
                    first = false;
                    notificationFirst &= state.ActionLog.SelectMany(x => x.SubActions).Any(x => x.Name == (pin ? "ZActionPinUnit" : "ZActionUnpinUnit"));
                    later.Keywords.Add(Keyword.Suppressed); later.Definition = new CardDefinition { Name = cardName, Type = "infantry" };
                    added = state.CreateWithId(cardName, side, 1000, side.HqOf(), 3); added.Definition = def;
                };
                if (pin) engine.Api.PinUnit(subject, 71);
                else { subject.PinnedTurns = 2; engine.Api.RemovePin(subject); }
                foreach (var observer in new[] { subject, later })
                    if (!Equals(observer.BlueprintVariables.GetValueOrDefault("_auditPinCount"), 1)
                        || observer.BlueprintVariables.GetValueOrDefault("_auditPinSubject") is not CardInstance payload || payload != subject)
                        return $"T61/T62不能排除主体、限制位置或在查询后重筛：{side}/{pin}/{location}";
                if (!notificationFirst || first || added is null || added.BlueprintVariables.ContainsKey("_auditPinCount")
                    || initialSuppressed.BlueprintVariables.ContainsKey("_auditPinCount")) return "压制快照应在通知后查询，排除新注册和初始被抑制对象";
            }
        }
        finally { foreach (string trigger in triggers) locals.Remove(trigger); }
        return null;
    }

    private static string? NativeAttackRestrictionPredicates(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (string function in new[] { "HasCantAttack", "HasCantAttackType", "HasCantBeAttackedBy" })
        foreach (int mode in Enumerable.Range(0, 12))
        {
            var (engine, state) = EmptyBoard(db);
            var card = MakeActionQuotaProbe(state, side, "infantry");
            var receiver = state.CreateWithId(PlainUnit, side, 61, side.HqOf(), 2);
            receiver.CustomJson.Clear(); receiver.ReceivedAbilitiesFromCards.Clear();
            string key = function == "HasCantAttack" ? "cantAttack"
                : function == "HasCantAttackType" ? "cantAttack:infantry" : "cantBeAttackedBy:infantry";
            if (mode == 1 || mode == 9) engine.Api.JsonSetString(receiver, "customName1", key);
            if (mode == 2) engine.Api.JsonSetString(receiver, "customName1", key.ToUpperInvariant());
            if (mode == 3) engine.Api.JsonSetString(receiver, "customName1", "prefix;" + key + ";suffix");
            if (mode == 4) engine.Api.JsonSetString(receiver, "customName1", "prefix," + key);
            if (mode is 5 or 6 or 10) receiver.ReceivedAbilitiesFromCards[key] = mode == 6 ? new List<int>() : new List<int> { 0, -7, 9999 };
            if (mode == 7) receiver.ReceivedAbilitiesFromCards[key.ToUpperInvariant()] = new List<int> { 9999 };
            if (mode == 8) engine.Api.JsonSetString(receiver, "customName2", key);
            if (mode == 9) receiver.Keywords.Add(Keyword.Suppressed);
            if (mode == 11) engine.Api.JsonSetString(receiver, "customName1", key + "Extra");
            bool expected = mode is 1 or 2 or 3 or 5 or 9 or 10;
            string before = System.Text.Json.JsonSerializer.Serialize(receiver.Snapshot());
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            var args = function == "HasCantAttack" ? new object?[] { null } : new object?[] { "infantry", null };
            object? actual = engine.Api.InvokeByName(function, receiver, args, ctx, out bool handled);
            var exprs = function == "HasCantAttack" ? new[] { new KismetExpr { Var = "result" } }
                : new[] { new KismetExpr { Str = "infantry" }, new KismetExpr { Var = "result" } };
            var steps = new KismetStep[] {
                new KismetStep(0, "call", function, exprs, new[] { exprs.Length - 1 }, null, null, -1, null, null)
                    { Receiver = new KismetExpr { Var = "receiver" } },
                new(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
            };
            var output = engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0), ctx,
                new Dictionary<string, object?> { ["receiver"] = receiver }, "result");
            if (!handled || !Equals(actual, expected) || !Equals(output.GetValueOrDefault("result"), expected)
                || before != System.Text.Json.JsonSerializer.Serialize(receiver.Snapshot()) || state.ActionLog.Count != 0)
                return $"原生攻击查询不符：{side}/{function}/mode={mode} 期望{expected} 实际{actual}";
        }
        return null;
    }

    private static string? NativeAttackRestrictionMatrix(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (string attackerType in new[] { "infantry", "tank", "artillery", "fighter", "bomber" })
        foreach (string defenderType in new[] { "infantry", "tank", "artillery", "fighter", "bomber", "location" })
        foreach (bool nameSource in new[] { false, true })
        foreach (int mode in Enumerable.Range(0, 14))
        {
            var (engine, state) = EmptyBoard(db);
            var attacker = MakeActionQuotaProbe(state, side, attackerType);
            var defender = defenderType == "location" ? state.Hq(side.Opposite())
                : state.CreateWithId(PlainUnit, side.Opposite(), 61, side.Opposite().HqOf(), 1);
            if (defenderType != "location")
                defender.Definition = new CardDefinition { Name = PlainUnit, Type = defenderType, Attack = 0, Defense = 100 };
            defender.Attack = 0; defender.Defense = defender.MaxDefense = 100;
            attacker.CustomJson.Clear(); attacker.ReceivedAbilitiesFromCards.Clear();
            defender.CustomJson.Clear(); defender.ReceivedAbilitiesFromCards.Clear(); defender.Keywords.Clear();
            string defenderGroup = defenderType is "fighter" or "bomber" ? "air" : defenderType == "location" ? "location" : "ground";
            string attackerGroup = attackerType is "fighter" or "bomber" ? "air" : "ground";
            void Restrict(CardInstance target, string key)
            {
                if (nameSource) engine.Api.JsonSetString(target, "customName1", "other;" + key);
                else target.ReceivedAbilitiesFromCards[key] = new List<int> { 9999 };
            }
            if (mode == 1) Restrict(attacker, "cantAttack");
            if (mode is 2 or 3 or 6 or 10 or 11 or 13) Restrict(attacker, "cantAttack:" + defenderType);
            if (mode is 4 or 5) Restrict(attacker, "cantAttack:" + defenderGroup);
            if (mode is 3 or 11) attacker.ReceivedAbilitiesFromCards["ignoreCantAttack_" + defenderType] = new List<int> { 9999 };
            if (mode is 5 or 10) attacker.ReceivedAbilitiesFromCards["ignoreCantAttack_" + defenderGroup] = new List<int> { 9999 };
            if (mode == 6) attacker.ReceivedAbilitiesFromCards["ignoreCantAttack_" + defenderType] = new List<int>();
            if (mode == 7) Restrict(defender, "cantBeAttackedBy:" + attackerType);
            if (mode == 8) Restrict(defender, "cantBeAttackedBy:" + attackerGroup);
            if (mode == 9) defender.ReceivedAbilitiesFromCards["cantBeAttackedBy:" + attackerType] = new List<int>();
            if (mode == 11) Restrict(attacker, "cantAttack:" + defenderGroup);
            if (mode == 12) engine.Api.JsonSetString(defender, "customName2", "cantBeAttackedBy:" + attackerType);
            if (mode == 13) engine.Api.JsonSetString(attacker, "customName1", "cantAttack:" + defenderType + ";ignoreCantAttack_" + defenderType);
            bool blocked = mode is 1 or 2 or 4 or 6 or 7 or 8 or 13
                || mode is 5 or 10 or 11 && defenderType != "location";
            string expectedReason = mode == 1 ? "unit_cant_attack" : mode is 7 or 8 ? "unit_cant_be_attack_by_unit" : "cant_be_attacked_by_unit";
            bool listed = engine.LegalTargets(attacker).Contains(defender);
            int actionsBefore = state.ActionLog.Count, credits = state.Kredits(side);
            bool attacked = engine.Attack(attacker, defender, out string reason);
            if (listed != !blocked || attacked != !blocked)
                return $"攻击限制枚举/结算：{side}/{attackerType}->{defenderType} name={nameSource} mode={mode} 应拒{blocked} 枚举{listed} 实际{attacked} reason={reason}";
            if (blocked && (reason != expectedReason || state.Kredits(side) != credits || attacker.AttacksThisTurn != 0
                || defender.Defense != 100 || state.ActionLog.Count != actionsBefore))
                return "攻击限制拒绝后的原因或副作用错误：" + mode;
        }
        return null;
    }

    private static string? NativeAttackRestrictionStaticCards(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (string name in new[] { "card_unit_28cm_coasttal_howitzer", "card_unit_75mm_mountain_gun", "card_unit_ki_84_frank", "card_unit_aichi_b7a2", "card_unit_armored_train" })
        {
            var (engine, state) = EmptyBoard(db);
            var attacker = state.CreateWithId(name, side, 60, CardLocation.BoardFrontline, 0);
            state.ActiveSide = side; state.SetKredits(side, 20); attacker.EnteredPlayOnTurn = -99;
            var hq = state.Hq(side.Opposite()); int defense = hq.Defense;
            bool listed = engine.LegalTargets(attacker).Contains(hq);
            if (engine.Attack(attacker, hq, out string reason) || listed || hq.Defense != defense
                || reason != (name == "card_unit_armored_train" ? "unit_cant_attack" : "cant_be_attacked_by_unit")
                || attacker.AttacksThisTurn != 0 || state.Kredits(side) != 20)
                return "真实静态名称攻击限制未执行：" + name + "/" + reason;
        }
        return null;
    }

    private static string? StaticCustomNameCatalogue(CardDatabase db)
    {
        var cards = db.All.OrderBy(x => x.Name, StringComparer.Ordinal).ToArray();
        // Independent digest of all 2,019 pak names, reconciled with saved runtime CDOs.
        string canonical = string.Join("\n", cards.Select(x => x.Name + "\t" + x.CustomName1 + "\t" + x.CustomName2));
        string digest = Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(canonical))).ToLowerInvariant();
        if (cards.Length != 2019 || digest != "4ba8b0ce3153d67183e14813c9ae8fb2f4086671f3f660f43fcf3dee1cd7cdfd")
            return "全卡池静态名称与pak/运行时CDO权威摘要不符：" + digest;
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (_, state) = EmptyBoard(db);
            for (int i = 0; i < cards.Length; i++)
            {
                var definition = cards[i];
                var instance = state.CreateWithId(definition.Name, side, 1000 + i, side.DeckOf(), i);
                var template = CardApi.TemplateInstance(definition, side);
                foreach (var card in new[] { instance, template })
                {
                    if (engineName(card, "customName1") != definition.CustomName1
                        || engineName(card, "customName2") != definition.CustomName2)
                        return $"建卡/模板未载入静态名称：{side}/{definition.Name}";
                }
            }
        }
        return null;
        static string engineName(CardInstance card, string key)
            => card.CustomJson.GetValueOrDefault(key, "None");
    }

    private static string? StaticCustomNameReset(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (string name in new[] { "card_unit_panzergrenadier", "card_event_aerial_reconaissance", "card_event_interception", PlainUnit })
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId(name, side, 60, side.HandOf(), 0);
            engine.Api.JsonSetString(card, "customName1", "temporary;StopDestructionEffect");
            engine.Api.JsonSetString(card, "customName2", "kept;61;61");
            engine.Api.JsonSetInt(card, "unrelated", 17);
            card.ResetAttributes();
            engine.Api.PersistCustomFields(card);
            var payload = state.ActionLog.SelectMany(x => x.SubActions).Last(x => x.Name == "ZActionPersistCustomFields");
            if (payload.Values.Single(x => x.Name == "customName1").Text != card.Definition.CustomName1
                || payload.Values.Single(x => x.Name == "customName2").Text != "kept;61;61"
                || engine.Api.JsonGetInt(card, "unrelated") != 17
                || CardApi.CustomNameHasAttribute(card, "customName1", "StopDestructionEffect"))
                return "重置必须恢复CDO Name1、保留当前Name2与无关JSON：" + name;
            if (name == "card_unit_panzergrenadier" && !card.CanMoveAndAttackInSameTurn)
                return "重置后原始装甲步兵行动例外丢失";
        }
        return null;
    }

    private static string? NativeCustomNameMemberVm(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (string member in new[] { "customName1", "customName2" })
        foreach (string value in new[] { "alpha;alpha;beta", "None" })
        {
            var (engine, state) = EmptyBoard(db);
            var card = MakeActionQuotaProbe(state, side, "infantry");
            engine.Api.JsonSetString(card, member, "old");
            card.BlueprintVariables[member] = "stale-shadow";
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            var steps = new KismetStep[] {
                new(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = member, Scope = "instance" }, null, -1, "before", null),
                new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Name = value }, null, -1, member, null) { DestinationScope = "instance" },
                new(2, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = member, Scope = "instance", Context = new KismetExpr { Self = true } }, null, -1, "after", null),
                new(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
            };
            var output = engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0), ctx, null, "before", "after");
            engine.Api.PersistCustomFields(card);
            var payload = state.ActionLog.SelectMany(x => x.SubActions).Last(x => x.Name == "ZActionPersistCustomFields");
            if (!Equals(output.GetValueOrDefault("before"), "old") || !Equals(output.GetValueOrDefault("after"), value)
                || card.BlueprintVariables.ContainsKey(member)
                || payload.Values.Single(x => x.Name == member).Text != value
                || CardApi.CustomNameHasAttribute(card, member, "alpha") != (value != "None"))
                return $"VM名称成员不能与属性API/持久化分叉：{side}/{member}/{value}";
        }
        return null;
    }

    private static string? NativeCustomNameRealLeave(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (string name in new[] { "card_unit_aichi_d3a", "card_unit_type_92_105mm_field_gun", "card_unit_type_93_cam1", "card_unit_type_97_cam1", "card_unit_soviet_promo1" })
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId(name, side, 60, side.HqOf(), 1);
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            engine.Api.JsonSetString(card, "customName2", "9999");
            var program = KismetLibrary.Default?.FindProgram(name, "OnLeaveBoardOrOwner");
            if (program is null) return "缺少真实离场函数：" + name;
            engine.Api.Vm.Run(program, ctx);
            if (CardApi.CustomNameHasAttribute(card, "customName2", "9999") || card.BlueprintVariables.ContainsKey("customName2")
                || engine.Api.Vm.FaultedPrograms != 0) return "真实离场未清空共享Name2：" + name;
            var persisted = state.ActionLog.SelectMany(x => x.SubActions).LastOrDefault(x => x.Name == "ZActionPersistCustomFields");
            if (persisted is null || persisted.Values.Single(x => x.Name == "customName2").Text != "None")
                return "真实离场持久化仍带旧Name2：" + name;
        }
        return null;
    }

    private static string? NativeCustomNameOperations(CardDatabase db)
    {
        var cases = new (string Before, string Operation, string Argument, string After)[]
        {
            ("", "Add", "alpha", "alpha"),
            ("None", "Add", "alpha", "alpha"),
            ("nOnE", "Add", "alpha", "alpha"),
            ("alpha", "Add", "alpha", "alpha;alpha"),
            ("alpha", "Add", "ALPHA", "alpha;ALPHA"),
            ("alpha", "Add", "", "alpha;"),
            ("alpha", "Add", "beta;gamma", "alpha;beta;gamma"),
            ("alpha", "Add", "beta,gamma", "alpha;beta,gamma"),
            ("", "Add", "None", ""),
            ("alpha;ALPHA;beta", "Remove", "aLpHa", "beta"),
            ("alpha;beta", "Remove", "ALPHA;BETA", ""),
            ("alpha;;beta;", "Remove", "missing", "alpha;beta"),
            ("alpha;;beta;", "Remove", "", "alpha;beta"),
            ("alpha;alpha", "Remove", "alpha", ""),
            ("Alpha,beta;gamma", "Remove", "alpha", "Alpha,beta;gamma"),
            ("None", "Remove", "missing", ""),
            ("É;é;A;a", "Remove", "É", "é;A;a"),
        };
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int member in new[] { 1, 2 })
        {
            var (engine, state) = EmptyBoard(db);
            var card = MakeActionQuotaProbe(state, side, "infantry");
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            string key = "customName" + member, prefix = "CustomName" + member;
            foreach (var test in cases)
            {
                engine.Api.JsonSetString(card, key, test.Before);
                engine.Api.InvokeByName(prefix + test.Operation, card, new object?[] { test.Argument }, ctx, out bool handled);
                string stored = engine.Api.JsonGetString(card, key);
                if (!handled || stored != test.After)
                    return $"名称操作错误：{side}/{member} [{test.Before}] {test.Operation} [{test.Argument}] => [{stored}] 应为[{test.After}]";
            }
            var queries = new (string Value, string Query, bool Expected)[]
            {
                ("", "None", true), ("None", "none", true), ("", "", false),
                ("alpha;beta", "ALPHA", true), ("alpha;beta", "alpha;beta", false),
                ("alpha,beta", "alpha", false), ("alpha,beta", "ALPHA,BETA", true),
                (";alpha;;beta;", "", false), (";alpha;;beta;", "beta", true),
                ("alpha;alpha", "alp", false), ("É", "é", false), ("É", "É", true),
            };
            foreach (var test in queries)
            {
                engine.Api.JsonSetString(card, key, test.Value);
                object? actual = engine.Api.InvokeByName(prefix + "HasAttribute", card, new object?[] { test.Query, null }, ctx, out bool handled);
                if (!handled || actual is not bool result || result != test.Expected
                    || CardApi.CustomNameHasAttribute(card, key, test.Query) != test.Expected)
                    return $"名称查询错误：{side}/{member} [{test.Value}] 查询[{test.Query}]";
            }
            if (member == 2)
            {
                foreach (var test in new (string Value, string[] Expected)[]
                {
                    ("", Array.Empty<string>()), ("None", Array.Empty<string>()),
                    ("nOnE", Array.Empty<string>()), (";a;;A;b;", new[] { "a", "A", "b" }),
                    ("a,b;a,b", new[] { "a,b", "a,b" }),
                })
                {
                    engine.Api.JsonSetString(card, key, test.Value);
                    var actual = engine.Api.InvokeByName("GetCustomName2Attributes", card, new object?[] { null }, ctx, out _);
                    if (actual is not IEnumerable<string> items || !items.SequenceEqual(test.Expected))
                        return $"名称列表不能去重、使用逗号或输出None：[{test.Value}]";
                }
            }
        }
        return null;
    }

    private static string? NativeCustomNameRuleConsumers(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var card = MakeActionQuotaProbe(state, side, "infantry");
            var other = state.CreateWithId("card_unit_hayabusa", side, 61, side.HqOf(), 2);
            var ctx = new EffectContext { Engine = engine, State = state, Self = other, Controller = side };
            engine.Api.InvokeByName("CustomName1Add", card, new object?[] { "61" }, ctx, out _);
            if (!CardApi.CustomNameHasAttribute(card, "customName1", "61")
                || CardApi.CustomNameHasAttribute(other, "customName1", "61")) return "属性字符串不能被当作目标ID";
            engine.Api.JsonSetString(card, "customName1", "unrelated;canmoveandattackinthesameturn;extra");
            if (!card.CanMoveAndAttackInSameTurn) return "原生行动例外必须读取分号属性并忽略ASCII大小写";
            engine.Api.JsonSetString(card, "customName1", "unrelated;ISARMORUNIT");
            if (!card.CanMoveAndAttackInSameTurn) return "装甲标记必须共享原生名称查询";
            engine.Api.JsonSetString(card, "customName1", "unrelated,isArmorUnit");
            if (card.CanMoveAndAttackInSameTurn) return "逗号不是原生属性分隔符";
            engine.Api.JsonSetString(other, "customName1", "unrelated;stopdestructioneffect;extra");
            if (engine.Api.ShouldTriggerDestructionEffect(other)) return "亡语停止标记必须读取分号属性并忽略ASCII大小写";
            engine.Api.InvokeByName("CustomName1Remove", other, new object?[] { "STOPDESTRUCTIONEFFECT" }, ctx, out _);
            if (!engine.Api.ShouldTriggerDestructionEffect(other)) return "忽略大小写移除后应恢复原始亡语";
            engine.Api.InvokeByName("CustomName1Add", other, new object?[] { "again" }, ctx, out _);
            engine.Api.InvokeByName("CustomName1Add", other, new object?[] { "again" }, ctx, out _);
            engine.Api.PersistCustomFields(other);
            var action = state.ActionLog.SelectMany(x => x.SubActions).Last(x => x.Name == "ZActionPersistCustomFields");
            if (action.Values.Single(x => x.Name == "customName1").Text != "unrelated;extra;again;again")
                return "持久化必须保留原生名称顺序、分号和重复";
        }
        return null;
    }

    private static string? PersistCustomFieldsIdentityLookup(CardDatabase db)
    {
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int route in new[] { 0, 1, 2 })
        foreach (bool replaced in new[] { false, true })
        foreach (bool refresh in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var caller = state.CreateWithId(PlainUnit, side, 60, side.HqOf(), 1);
            var original = state.CreateWithId(PlainUnit, side.Opposite(), 70, CardLocation.Discard, 0);
            var argument = original;
            CardInstance mapped;
            if (replaced)
            {
                state.Remove(original);
                mapped = state.CreateWithId(PlainUnit, side.Opposite(), 70, CardLocation.NotAvailable, 0);
            }
            else
            {
                mapped = original;
                argument = new CardInstance { CardId = mapped.CardId, Name = mapped.Name, Owner = mapped.Owner,
                    OriginalOwner = mapped.Owner, Definition = mapped.Definition };
            }
            engine.Api.JsonSetString(argument, "customName1", "stale");
            engine.Api.JsonSetInt(argument, "auditIdentity", 901);
            engine.Api.JsonSetString(mapped, "customName1", "mapped-one");
            engine.Api.JsonSetString(mapped, "customName2", "mapped-two");
            engine.Api.JsonSetInt(mapped, "auditIdentity", 202);
            var ctx = new EffectContext { Engine = engine, State = state, Self = caller, Controller = side };
            if (route == 0) engine.Api.PersistCustomFields(argument);
            else engine.Api.InvokeByName("PersistCustomFields", caller,
                new object?[] { route == 1 ? argument.CardId : argument, refresh }, ctx, out _);
            var notices = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionPersistCustomFields").ToArray();
            if (notices.Length != 1 || notices[0].Values[0].Value != 70
                || notices[0].Values[1].Text != "mapped-one" || notices[0].Values[2].Text != "mapped-two")
                return $"persist identity {side}/{route}/{replaced}/{refresh}: wrong mapped object/names/count";
            string json = notices[0].Values[3].Text.Replace("\\\"", "\"", StringComparison.Ordinal);
            using var doc = System.Text.Json.JsonDocument.Parse(json);
            if (doc.RootElement.GetProperty("auditIdentity").GetInt32() != 202)
                return $"persist identity {side}/{route}/{replaced}/{refresh}: stale JSON";
            cases++;
        }
        return cases == 24 ? null : $"persist identity cases={cases}";
    }

    private static string? PersistCustomFieldsNoCallerFallback(CardDatabase db)
    {
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int receiverKind in new[] { 0, 1, 2 })
        foreach (int targetKind in Enumerable.Range(0, 6))
        {
            var (engine, state) = EmptyBoard(db);
            var caller = state.CreateWithId(PlainUnit, side, 60, side.HqOf(), 1);
            engine.Api.JsonSetString(caller, "customName1", "do-not-leak-caller");
            var zero = state.CreateWithId(PlainUnit, side, 0, CardLocation.Discard, 0);
            var negative = state.CreateWithId(PlainUnit, side, -7, CardLocation.Discard, 1);
            engine.Api.JsonSetInt(zero, "auditNonPositive", 99);
            engine.Api.JsonSetInt(negative, "auditNonPositive", 99);
            var missing = new CardInstance { CardId = 777, Name = caller.Name, Owner = side, OriginalOwner = side, Definition = caller.Definition };
            object?[] args = targetKind switch {
                0 => Array.Empty<object?>(), 1 => new object?[] { null, true },
                2 => new object?[] { 0, false }, 3 => new object?[] { -7, true },
                4 => new object?[] { 777, false }, _ => new object?[] { missing, true } };
            var ctx = new EffectContext { Engine = engine, State = state, Self = caller, Controller = side };
            engine.Api.InvokeByName("PersistCustomFields", receiverKind == 0 ? caller : receiverKind == 1 ? null : missing, args, ctx, out _);
            var notices = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionPersistCustomFields").ToArray();
            // Keep this focused on excluding receiver fallback; the separate
            // missing-object contract below checks the native count/defaults.
            if (notices.Any(x => x.Values[0].Value == caller.CardId
                || x.Values.Any(v => v.Name == "customName1" && v.Text == "do-not-leak-caller")))
                return $"persist missing {side}/{receiverKind}/{targetKind}: leaked caller identity/payload";
            int before = notices.Length;
            engine.Api.PersistCustomFields(targetKind % 2 == 0 ? zero : negative);
            var extra = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionPersistCustomFields").Skip(before).ToArray();
            if (extra.Any(x => x.Values.Any(v => v.Name == "customJson" && v.Text.Contains("auditNonPositive"))))
                return "nonpositive mapped fixture leaked fields";
            cases++;
        }
        return cases == 36 ? null : $"persist no-fallback cases={cases}";
    }

    private static string? PersistMissingObjectPayload(CardDatabase db)
    {
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool refresh in new[] { false, true })
        foreach (int kind in Enumerable.Range(0, 6))
        {
            var (engine, state) = EmptyBoard(db);
            var caller = state.CreateWithId(PlainUnit, side, 60, side.HqOf(), 1);
            engine.Api.JsonSetString(caller, "customName1", "not-default");
            var zero = state.CreateWithId(PlainUnit, side, 0, CardLocation.Discard, 0);
            var negative = state.CreateWithId(PlainUnit, side, -7, CardLocation.Discard, 1);
            engine.Api.JsonSetInt(zero, "notDefault", 99); engine.Api.JsonSetInt(negative, "notDefault", 99);
            var detached = new CardInstance { CardId = 777, Name = caller.Name, Owner = side, OriginalOwner = side, Definition = caller.Definition };
            engine.Api.JsonSetInt(detached, "notDefault", 99);
            int id = kind == 1 ? -7 : kind is 2 or 3 ? 777 : 0;
            object?[] args = kind switch {
                0 => new object?[] { 0, refresh }, 1 => new object?[] { -7, refresh },
                2 => new object?[] { 777, refresh }, 3 => new object?[] { detached, refresh },
                4 => new object?[] { null, refresh }, _ => Array.Empty<object?>() };
            var ctx = new EffectContext { Engine = engine, State = state, Self = caller, Controller = side };
            engine.Api.InvokeByName("PersistCustomFields", caller, args, ctx, out _);
            engine.Api.PersistCustomFields(id);
            var notices = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionPersistCustomFields").ToArray();
            if (notices.Length != 2 || notices.Any(x => x.Values.Count != 4
                || x.Values[0] != ActionValue2.Int("cardID", id)
                || x.Values[1] != ActionValue2.Str("customName1", "None")
                || x.Values[2] != ActionValue2.Str("customName2", "None")
                || x.Values[3] != ActionValue2.Str("customJson", "")))
                return $"missing persistence {side}/{refresh}/{kind}: count/defaults/original ID";
            cases++;
        }
        return cases == 24 ? null : $"missing persistence cases={cases}";
    }

    private static string? PincerMissingObjectNotifications(CardDatabase db)
    {
        using var probe = InstallPincerCallbackProbe();
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int route in new[] { 0, 1, 2 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_typhoon_mk_ib", side, 60, side.HqOf(), 1);
            var target = state.CreateWithId("card_unit_brewster_f2a", side, 70, side.HqOf(), 2);
            var events = new List<(CardInstance, string, CardInstance?)>();
            CapturePincerCallbacks(state, new() { source, target }, (r, k, a) => {
                events.Add((r, k, a));
                if (route == 0 && events.Count == 1) state.Remove(source);
                if (route == 0 && events.Count == 3) state.Remove(target);
            });
            int[] expectedIds;
            if (route == 0)
            {
                engine.Api.ApplyPincerEffects(source, target); expectedIds = new[] { 60, 70 };
                if (events.Count != 4) return "missing Apply maps must preserve held callback objects";
            }
            else
            {
                if (route == 1) engine.Api.JsonSetInt(source, "pincer_receiver", 777);
                else engine.Api.JsonSetIntArray(source, "pincer_givers", new[] { 777, 0, -7, 777 });
                engine.Api.RemovePincerEffects(source);
                expectedIds = route == 1 ? new[] { 0, 60 } : new[] { 777, 0, -7, 777, 60 };
                if (events.Count != (route == 1 ? 2 : 0)) return "missing Remove receivers routed incorrectly";
            }
            var notices = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionPersistCustomFields").ToArray();
            if (!notices.Select(x => x.Values[0].Value).SequenceEqual(expectedIds))
                return $"missing Pincer {side}/{route}: notify ID/count/order";
            foreach (var notice in route == 0 ? notices : notices.Take(notices.Length - 1))
                if (notice.Values[1].Text != "None" || notice.Values[2].Text != "None" || notice.Values[3].Text != "")
                    return $"missing Pincer {side}/{route}: invalid-object default payload";
        }
        return null;
    }

    private static string? NativeStaticPoolRuleState(CardDatabase db)
    {
        int queries = 0;
        foreach (var firstSide in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var left = state.CreateWithId(PlainUnit, Side.Left, 60, CardLocation.Discard, 0);
            var right = state.CreateWithId(PlainUnit, Side.Right, 70, CardLocation.Discard, 0);
            int actions = state.ActionLog.Count;
            foreach (bool includeNotAttainable in new[] { false, true })
            foreach (bool includeReserved in new[] { false, true })
            {
                int count = -1;
                CardInstance? cachedFirst = null;
                foreach (var side in new[] { firstSide, firstSide.Opposite() })
                {
                    var ctx = new EffectContext { Engine = engine, State = state,
                        Self = side == Side.Left ? left : right, Controller = side };
                    var result = engine.Api.InvokeByName("GetAllActiveStaticCards", null,
                        new object?[] { includeNotAttainable, includeReserved }, ctx, out bool handled);
                    if (!handled || result is not List<CardInstance> pool || pool.Count == 0)
                        return "static pool query must return candidates";
                    if (count >= 0 && (pool.Count != count || !ReferenceEquals(pool[0], cachedFirst)))
                        return "clearing returned array or switching controller must preserve cached card references";
                    count = pool.Count; cachedFirst = pool[0];
                    foreach (var card in pool)
                    {
                        if (card.Owner != Side.NotAvailable || card.OriginalOwner != Side.NotAvailable
                            || card.CardId != 0 || card.Location != CardLocation.NotAvailable || card.LocationNumber != 0
                            || card.EnteredPlayOnTurn != 0 || card.MaxDefense != 0
                            || card.RemainingAttacks != 0 || !card.HasMovedThisTurn)
                            return $"static pool raw state {firstSide}/{side}/{includeNotAttainable}/{includeReserved}/{card.Name}";
                    }
                    string? identityError = ProbeObjectOperators(ctx, new() { Var = "candidate" },
                        new() { Math = "GetStaticCard", Args = new[] { new KismetExpr { Name = cachedFirst.Name } } },
                        true, new Dictionary<string, object?> { ["candidate"] = cachedFirst });
                    if (identityError is not null) return $"pool/lookup identity: {identityError}";
                    // Array containers are copied; the cached object identities survive.
                    pool.Clear();
                    queries++;
                }
            }
            if (left.Owner != Side.Left || right.Owner != Side.Right || state.ActionLog.Count != actions)
                return "static pool must not change battle ownership or emit actions";
        }
        return queries == 16 ? null : $"static pool queries={queries}";
    }

    private static string? NativeStaticCardRuleState(CardDatabase db)
    {
        string furyName = db.All.First(x => x.Keywords.Contains(Keyword.Fury)).Name;
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (string name in new[] { PlainUnit, "card_event_barrage", furyName })
        {
            var (engine, state) = EmptyBoard(db);
            var self = state.CreateWithId(PlainUnit, side, 60, CardLocation.Discard, 0);
            var ctx = new EffectContext { Engine = engine, State = state, Self = self, Controller = side };
            var steps = new[] {
                new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Math = "GetStaticCard", Args = new[] { new KismetExpr { Name = name } } },
                    null, -1, "staticCard", null),
                new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
            };
            int actions = state.ActionLog.Count;
            var result = engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0), ctx, null, "staticCard");
            if (result["staticCard"] is not CardInstance card) return $"lookup missing for known {name}";
            if (card.Owner != Side.NotAvailable || card.OriginalOwner != Side.NotAvailable
                || card.CardId != 0 || card.Location != CardLocation.NotAvailable || card.LocationNumber != 0
                || card.EnteredPlayOnTurn != 0 || card.MaxDefense != 0 || card.MaxAttack != 0)
                return $"static raw state {side}/{name}: owner={card.Owner}, enter={card.EnteredPlayOnTurn}, maxDefense={card.MaxDefense}";
            if (engine.Api.InvokeByName("HasAttackLeft", card, Array.Empty<object?>(), ctx, out _) is not false
                || engine.Api.InvokeByName("HasMovementLeft", card, Array.Empty<object?>(), ctx, out _) is not false)
                return $"static quotas {side}/{name}: native static attackLeft/movementLeft must be0";
            // The change must retain the database-backed card attributes and
            // canonical object identity, and must not affect the executing card.
            if (card.Name != name || card.Definition != db.Require(name)
                || card.Attack != card.Definition.Attack || card.Defense != card.Definition.Defense
                || card.KreditCost != card.Definition.Kredits || self.Owner != side || state.ActionLog.Count != actions)
                return $"static lookup data/context regression {side}/{name}";
            string? identityError = ProbeObjectOperators(ctx, new() { Var = "lookedUp" }, new() { Var = "wrapped" }, true,
                new Dictionary<string, object?> { ["lookedUp"] = card, ["wrapped"] = CardApi.TemplateInstance(card.Definition, side) });
            if (identityError is not null) return $"static identity {side}/{name}: {identityError}";
            cases++;
        }
        return cases == 6 ? null : $"static raw state cases={cases}";
    }

    private static string? ProbeObjectOperators(EffectContext ctx, KismetExpr left, KismetExpr right,
        bool expected, IReadOnlyDictionary<string, object?>? seed = null)
    {
        foreach (bool reverse in new[] { false, true })
        foreach (string fn in new[] { "EqualEqual_ObjectObject", "NotEqual_ObjectObject" })
        {
            var args = reverse ? new[] { right, left } : new[] { left, right };
            var steps = new[] {
                new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Math = fn, Args = args }, null, -1, "result", null),
                new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
            };
            var output = ctx.Engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0), ctx, seed, "result");
            bool wanted = fn == "EqualEqual_ObjectObject" ? expected : !expected;
            if (!Equals(output["result"], wanted)) return $"{fn}/reverse={reverse}: expected {wanted}";
        }
        return null;
    }

    private static string? ObjectOperatorBattleIdentity(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int id in new[] { 0, 70, -7 })
        {
            var (engine, state) = EmptyBoard(db);
            var first = state.CreateWithId(PlainUnit, side, id, CardLocation.Discard, 0);
            state.Remove(first);
            var replacement = state.CreateWithId(PlainUnit, side, id, CardLocation.Discard, 0);
            var ctx = new EffectContext { Engine = engine, State = state, Self = first, Controller = side };
            foreach (var (left, right, equal) in new (object?, object?, bool)[] {
                (first, first, true), (first, replacement, false), (replacement, replacement, true),
                (first, null, false), (null, replacement, false), (null, null, true),
            })
            {
                var seed = new Dictionary<string, object?> { ["left"] = left, ["right"] = right };
                var error = ProbeObjectOperators(ctx, new() { Var = "left" }, new() { Var = "right" }, equal, seed);
                if (error is not null) return $"battle {side}/{id}: {error}";
            }
        }
        return null;
    }

    private static string? ObjectOperatorStaticIdentity(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var battle = state.CreateWithId(PlainUnit, side, 0, CardLocation.Discard, 0);
            var ctx = new EffectContext { Engine = engine, State = state, Self = battle, Controller = side };
            var first = CardApi.TemplateInstance(db.Find(PlainUnit)!, side);
            var same = CardApi.TemplateInstance(db.Find(PlainUnit)!, side.Opposite());
            var other = CardApi.TemplateInstance(db.Find("card_unit_432_infantry_regiment")!, side);
            foreach (var (left, right, equal) in new (object?, object?, bool)[] {
                (first, same, true), (first, other, false), (first, battle, false), (first, null, false),
            })
            {
                var seed = new Dictionary<string, object?> { ["left"] = left, ["right"] = right };
                var error = ProbeObjectOperators(ctx, new() { Var = "left" }, new() { Var = "right" }, equal, seed);
                if (error is not null) return $"static wrappers {side}: {error}";
            }
            KismetExpr Lookup(string name) => new() { Math = "GetStaticCard", Args = new[] { new KismetExpr { Str = name } } };
            foreach (bool sameName in new[] { true, false })
            {
                var error = ProbeObjectOperators(ctx, Lookup(PlainUnit),
                    Lookup(sameName ? PlainUnit : "card_unit_432_infantry_regiment"), sameName);
                if (error is not null) return $"actual GetStaticCard expressions {side}/{sameName}: {error}";
            }
            var poolError = ProbeObjectOperators(ctx, Lookup(PlainUnit), new() { Var = "poolCard" }, true,
                new Dictionary<string, object?> { ["poolCard"] = first });
            if (poolError is not null) return $"static pool/lookup {side}: {poolError}";
        }
        return null;
    }

    private static string? StaticTemplateObjectIdentity(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var first = CardApi.TemplateInstance(db.Find(PlainUnit)!, side);
            var same = CardApi.TemplateInstance(db.Find(PlainUnit)!, side.Opposite());
            var other = CardApi.TemplateInstance(db.Find("card_unit_432_infantry_regiment")!, side);
            var battleZero = state.CreateWithId(PlainUnit, side, 0, CardLocation.Discard, 0);
            var ctx = new EffectContext { Engine = engine, State = state, Self = battleZero, Controller = side };
            object? Call(string fn, params object?[] args) => engine.Api.InvokeByName(fn, null, args, ctx, out _);
            var list = new List<CardInstance> { first };
            if (Call("Array_Identical", list, new List<CardInstance> { same }) is not true
                || Call("Array_AddUnique", list, same) is not 0 || list.Count != 1
                || Call("Array_Contains", list, other) is not false || Call("Array_AddUnique", list, other) is not 1
                || Call("Array_Contains", list, battleZero) is not false || Call("Array_AddUnique", list, battleZero) is not 2
                || Call("Array_RemoveItem", list, same) is not true || list.Count != 2
                || !ReferenceEquals(list[0], other) || !ReferenceEquals(list[1], battleZero))
                return $"static template identity {side}: repeated static lookup/different static definition/battle ID0";
            var set = new HashSet<object?> { first };
            Call("Set_Add", set, same); Call("Set_Add", set, other);
            if (set.Count != 2 || Call("Set_Remove", set, same) is not true || set.Count != 1 || !set.Contains(other))
                return $"static template identity {side}: shared comparer set regression";
        }
        return null;
    }

    private static string? ObjectArrayIdentity(CardDatabase db)
    {
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int id in new[] { 0, 70, -7 })
        {
            var (engine, state) = EmptyBoard(db);
            var self = state.CreateWithId(PlainUnit, side, 60, CardLocation.Discard, 0);
            var first = state.CreateWithId(PlainUnit, side, id, CardLocation.Discard, 1);
            state.Remove(first);
            var replacement = state.CreateWithId(PlainUnit, side, id, side.HqOf(), 1);
            var ctx = new EffectContext { Engine = engine, State = state, Self = self, Controller = side };
            object? Call(string fn, params object?[] args) => engine.Api.InvokeByName(fn, null, args, ctx, out _);
            var list = new List<CardInstance?> { first, null, first };
            if (Call("Array_Contains", list, replacement) is not false
                || Call("Array_Identical", new List<CardInstance> { first }, new List<CardInstance> { replacement }) is not false
                || Call("Array_AddUnique", list, replacement) is not 3 || list.Count != 4
                || !ReferenceEquals(list[3], replacement) || Call("Array_AddUnique", list, first) is not 0 || list.Count != 4)
                return $"object array identity {side}/{id}: same-ID distinct objects collapsed";
            if (Call("Array_RemoveItem", list, first) is not true || list.Count != 2 || list[0] is not null
                || !ReferenceEquals(list[1], replacement) || Call("Array_RemoveItem", list, first) is not false
                || Call("Array_RemoveItem", list, replacement) is not true || list.Count != 1
                || Call("Array_Contains", list, null) is not true || Call("Array_RemoveItem", list, null) is not true || list.Count != 0)
                return $"object array removal {side}/{id}: removed the other identity or mishandled null";
            var ids = new List<int> { id, id, id + 1 };
            if (Call("Array_RemoveItem", ids, id) is not true || !ids.SequenceEqual(new[] { id + 1 }))
                return "integer card-ID equality must remain value based";
            cases++;
        }
        return cases == 6 ? null : $"object array identity cases={cases}";
    }

    private static string? ObjectSetIdentity(CardDatabase db)
    {
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int id in new[] { 0, 70, -7 })
        {
            var (engine, state) = EmptyBoard(db);
            var first = state.CreateWithId(PlainUnit, side, id, CardLocation.Discard, 0); state.Remove(first);
            var replacement = state.CreateWithId(PlainUnit, side, id, side.HqOf(), 1);
            var ctx = new EffectContext { Engine = engine, State = state, Self = replacement, Controller = side };
            object? Call(string fn, params object?[] args) => engine.Api.InvokeByName(fn, null, args, ctx, out _);
            var set = new HashSet<object?> { first, null };
            if (Call("Set_Contains", set, replacement) is not false) return $"object set {side}/{id}: false same-ID match";
            Call("Set_Add", set, replacement); Call("Set_Add", set, first);
            if (set.Count != 3 || !set.Contains(first) || !set.Contains(replacement)
                || Call("Set_Remove", set, replacement) is not true || set.Count != 2 || !set.Contains(first))
                return $"object set {side}/{id}: uniqueness/removal collapsed distinct objects";
            Call("Set_RemoveItems", set, new List<object?> { first });
            if (set.Count != 1 || !set.Contains(null) || Call("Set_Remove", set, null) is not true || set.Count != 0)
                return $"object set {side}/{id}: bulk removal/null";
            cases++;
        }
        return cases == 6 ? null : $"object set identity cases={cases}";
    }

    private static string? AkitaDistinctKillerIdentity(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool sameId in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 7; state.Move(state.Hq(side.Opposite()), CardLocation.Discard);
            var source = state.CreateWithId("card_unit_akita_regiment", side, 60, CardLocation.Discard, 0);
            var oldKiller = state.CreateWithId(PlainUnit, side.Opposite(), sameId ? 70 : 71, CardLocation.Discard, 1);
            oldKiller.Defense = oldKiller.MaxDefense = 0; state.Remove(oldKiller);
            var current = state.CreateWithId(PlainUnit, side.Opposite(), 70, side.Opposite().HqOf(), 1);
            current.Definition = new CardDefinition { Name = current.Name, Type = "infantry", Attack = 2, Defense = 10 };
            current.Keywords.Clear(); current.Attack = 2; current.Defense = current.MaxDefense = 10;
            // Actual Akita IR removes the supplied dead killer object from an
            // object-array snapshot. A different current object with the same ID
            // must remain eligible; only one candidate removes RNG ambiguity.
            engine.Api.FireTrigger("OnDestroyed", source, side,
                eventArgs: new object?[] { oldKiller, false }, eventSubject: oldKiller,
                namedArgs: new Dictionary<string, object?> { ["killer"] = oldKiller, ["TriggerNotDestroyed"] = false });
            if (current.Defense != 8)
                return $"Akita distinct killer {side}/{sameId}: current object should receive2 damage, defense={current.Defense}";
        }
        return null;
    }

    private static string? ArrayRemoveUsesIndex(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        var self = state.CreateWithId(PlainUnit, Side.Left, 60, CardLocation.Discard, 0);
        var first = state.CreateWithId(PlainUnit, Side.Left, 70, CardLocation.Discard, 1);
        var second = state.CreateWithId(PlainUnit, Side.Left, 71, CardLocation.Discard, 2);
        var ctx = new EffectContext { Engine = engine, State = state, Self = self, Controller = Side.Left };
        int[][] expectedIndices = { new[] { 0, 1, 2, 3 }, new[] { 1, 2, 3 }, new[] { 0, 2, 3 },
            new[] { 0, 1, 3 }, new[] { 0, 1, 2 }, new[] { 0, 1, 2, 3 }, new[] { 0, 1, 2, 3 } };
        int[] indices = { -1, 0, 1, 2, 3, 4, int.MaxValue };
        int cases = 0;
        foreach (int type in new[] { 0, 1, 2, 3 })
        for (int j = 0; j < indices.Length; j++)
        {
            object[] original = type == 0 ? new object[] { 70, 71, 70, 72 }
                : type == 1 ? new object[] { "A", "B", "A", "C" }
                : type == 2 ? new object[] { true, false, true, false }
                : new object[] { first, second, first, self };
            var list = original.ToList();
            object? result = engine.Api.InvokeByName("Array_Remove", null, new object?[] { list, indices[j] }, ctx, out bool handled);
            if (!handled || result is not null || !list.SequenceEqual(expectedIndices[j].Select(i => original[i])))
                return $"Array_Remove index {type}/{indices[j]}: removed a value or all duplicates instead of one indexed element";
            cases++;
        }
        return cases == 28 ? null : $"Array_Remove index cases={cases}";
    }

    private static string? ArrayRemoveItemAllMatches(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        var self = state.CreateWithId(PlainUnit, Side.Left, 60, CardLocation.Discard, 0);
        var ctx = new EffectContext { Engine = engine, State = state, Self = self, Controller = Side.Left };
        int[][] patterns = { Array.Empty<int>(), new[] { 1, 2 }, new[] { 0 }, new[] { 0, 1, 0, 2, 0 },
            new[] { 1, 0, 0, 2 }, new[] { 0, 0 }, new[] { 0, 0, 1, 1, 0 } };
        int[][] survivors = { Array.Empty<int>(), new[] { 1, 2 }, Array.Empty<int>(), new[] { 1, 2 },
            new[] { 1, 2 }, Array.Empty<int>(), new[] { 1, 1 } };
        int cases = 0;
        foreach (int type in new[] { 0, 1, 2 })
        for (int pattern = 0; pattern < patterns.Length; pattern++)
        {
            object Value(int v) => type == 0 ? v + 70 : type == 1 ? v == 0 ? "match" : v == 1 ? "MATCH" : "other" : v == 0;
            System.Collections.IList list = type == 0 ? patterns[pattern].Select(v => (int)Value(v)).ToList()
                : type == 1 ? patterns[pattern].Select(v => (string)Value(v)).ToList()
                : patterns[pattern].Select(v => (bool)Value(v)).ToList();
            var expected = survivors[pattern].Select(Value).ToArray();
            object? result = engine.Api.InvokeByName("Array_RemoveItem", null, new object?[] { list, Value(0) }, ctx, out bool handled);
            if (!handled || result is not bool removed || removed != (pattern >= 2)
                || !list.Cast<object>().SequenceEqual(expected))
                return $"RemoveItem {type}/{pattern}: result={result ?? "null"}, survivors={list.Count}/{expected.Length}";
            result = engine.Api.InvokeByName("Array_RemoveItem", null, new object?[] { list, Value(0) }, ctx, out handled);
            if (!handled || result is not false || !list.Cast<object>().SequenceEqual(expected))
                return $"RemoveItem {type}/{pattern}: second removal must return false without mutation";
            cases++;
        }
        return cases == 21 ? null : $"RemoveItem cases={cases}";
    }

    private static string? ResetTrackedCardArrayCleanup(CardDatabase db)
    {
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (string name in new[] { "card_unit_me_bf_109_fin", "card_event_prolonged_siege" })
        foreach (int kind in Enumerable.Range(0, 8))
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(name, side, 60, name.StartsWith("card_event", StringComparison.Ordinal) ? CardLocation.Discard : side.HqOf(), 1);
            var reset = state.CreateWithId(PlainUnit, side.Opposite(), 70, side.Opposite().HqOf(), 1);
            string key = name == "card_unit_me_bf_109_fin" ? "stolenCards" : "burncards";
            engine.Api.JsonSetInt(source, "auditKeep", 9);
            int[] initial = kind switch { 3 => new[] { 71, 72 }, 4 => new[] { 70 }, 5 => new[] { 70, 70 },
                6 => new[] { 70, 71, 70, 72, 70 }, 7 => new[] { 0, -7, 70, 70 }, _ => Array.Empty<int>() };
            if (kind == 1) engine.Api.JsonSetString(source, key, "70");
            else if (kind >= 2) engine.Api.JsonSetIntArray(source, key, initial);
            int[] expected = kind switch { 3 or 6 => new[] { 71, 72 }, 7 => new[] { 0, -7 }, _ => Array.Empty<int>() };
            for (int pass = 0; pass < 2; pass++)
            {
                engine.Api.FireTrigger("OnOtherCardReset", source, side, selfProgramName: "OnOtherCardReset",
                    eventArgs: new object?[] { reset, reset.CardId }, eventSubject: reset,
                    namedArgs: new Dictionary<string, object?> { ["cardReset"] = reset, ["resetCardID"] = reset.CardId });
                bool exists = kind is 1 or 2 or 3 or 6 or 7;
                var notices = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionPersistCustomFields").ToArray();
                if (source.CustomJson.ContainsKey(key) != exists || engine.Api.JsonGetInt(source, "auditKeep") != 9
                    || kind == 1 && engine.Api.JsonGetString(source, key) != "70"
                    || kind != 1 && !engine.Api.JsonGetIntArray(source, key).SequenceEqual(expected)
                    || notices.Length != (kind >= 4 ? 1 : 0)
                    || notices.Any(x => x.Values[0].Value != source.CardId))
                    return $"reset array {side}/{name}/{kind}/pass{pass}: typed guard/all-match removal/empty clear/idempotent notification";
            }
            cases++;
        }
        return cases == 32 ? null : $"reset array cases={cases}";
    }

    private static string? PersistCustomFieldsPayload(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool refresh in new[] { false, true })
        foreach (bool populated in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var card = MakeActionQuotaProbe(state, side, "infantry");
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            card.CustomJson.Clear();
            if (populated)
            {
                engine.Api.JsonSetString(card, "customName1", "StopDestructionEffect");
                engine.Api.JsonSetString(card, "customName2", "marker");
                engine.Api.JsonSetString(card, "text", "引号\"/\\/\n");
                engine.Api.JsonSetString(card, "numericText", "007");
                engine.Api.JsonSetInt(card, "number", -17);
                engine.Api.JsonSetBool(card, "flag", true);
                engine.Api.JsonSetIntArray(card, "ids", new[] { 0, -5, 19 });
                engine.Api.JsonSetString(card, "__customGameplayTags", "internal");
            }
            engine.Api.InvokeByName("PersistCustomFields", card, new object?[] { card.CardId, refresh }, ctx, out _);
            var action = state.ActionLog.SelectMany(x => x.SubActions).Last(x => x.Name == "ZActionPersistCustomFields");
            if (!action.Values.Select(x => x.Name).SequenceEqual(new[] { "cardID", "customName1", "customName2", "customJson" })
                || action.Values[0].Value != card.CardId || action.Values.Skip(1).Any(x => x.Value != -1)
                || action.Values[1].Text != (populated ? "StopDestructionEffect" : "None")
                || action.Values[2].Text != (populated ? "marker" : "None")) return "持久化四字段或名称默认值错误";
            string json = action.Values[3].Text.Replace("\\\"", "\"", StringComparison.Ordinal);
            // Undo exactly the notifier's extra replacement, then parse native JSON types.
            using var doc = System.Text.Json.JsonDocument.Parse(json);
            var root = doc.RootElement;
            if (!populated)
            {
                if (root.EnumerateObject().Any()) return "空JSON应保持空对象";
            }
            else if (root.EnumerateObject().Count() != 5
                || root.GetProperty("text").GetString() != "引号\"/\\/\n"
                || root.GetProperty("numericText").GetString() != "007"
                || root.GetProperty("number").GetInt32() != -17 || !root.GetProperty("flag").GetBoolean()
                || !root.GetProperty("ids").EnumerateArray().Select(x => x.GetInt32()).SequenceEqual(new[] { 0, -5, 19 }))
                return "持久化JSON类型或转义损坏，或混入内部字段";
        }
        return null;
    }

    private static string? DestructionLedgerKeepsInnateEffect(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var target = state.CreateWithId("card_unit_hayabusa", side, 71, side.HqOf(), 1);
            engine.Api.CustomAbilityRemove(target, "destruction", 0, true);
            if (!engine.Api.ShouldTriggerDestructionEffect(target) || target.BuffsBySource[(0, false)].Destruction != -1)
                return "负战斗账本不能取代原始亡语标志";
            int defense = state.Hq(side.Opposite()).Defense;
            engine.Destroy(target);
            if (target.Location != CardLocation.Discard || defense - state.Hq(side.Opposite()).Defense != 2)
                return "Hayabusa在自定义能力移除后仍应执行固有2点伤害亡语";
        }
        return null;
    }

    private static CardInstance MakeActionQuotaProbe(GameState state, Side side, string type)
    {
        const string name = "card_unit_432_infantry_regiment";
        var card = state.CreateWithId(name, side, 60, side.HqOf(), 1);
        card.Definition = new CardDefinition { Name = name, Type = type, Attack = 2, Defense = 20, Range = 2 };
        card.Attack = 2; card.Defense = card.MaxDefense = 20; card.OperationCost = 0;
        card.EnteredPlayOnTurn = -99;
        state.ActiveSide = side; state.SetKredits(side, 20);
        return card;
    }

    private static string? NativeArmorActionSequences(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int mode in Enumerable.Range(0, 6))
        foreach (int order in new[] { 0, 1, 2 })
        {
            var (engine, state) = EmptyBoard(db);
            var unit = MakeActionQuotaProbe(state, side, mode == 1 ? "tank" : mode == 2 ? "tankdestroyer" : mode == 5 ? "fighter" : "infantry");
            if (mode == 3) engine.Api.JsonSetString(unit, "customName1", "isArmorUnit");
            if (mode == 4) engine.Api.JsonSetString(unit, "customName1", "CanMoveAndAttackInTheSameTurn");
            bool allowed = mode is not (0 or 5);
            if (unit.CanMoveAndAttackInSameTurn != allowed) return "原生装甲/标记谓词不符";
            bool first = order == 1 ? engine.Attack(unit, state.Hq(side.Opposite()))
                : order == 2 ? engine.MoveUnitFromSupportToFrontLine(unit, 9004, out _) : engine.MoveUnit(unit, 0, out _);
            bool second = order == 1 ? engine.MoveUnit(unit, 0, out _) : engine.Attack(unit, state.Hq(side.Opposite()));
            if (!first || second != allowed || unit.AttacksThisTurn != (order == 1 || allowed ? 1 : 0))
                return $"实际行动顺序错误：{side} mode={mode} 顺序={order} 首={first} 次={second} 攻击次数={unit.AttacksThisTurn}";
        }
        return null;
    }

    private static string? MovementAttackQuotaLifecycle(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int mode in new[] { 0, 1, 2 })
        {
            var (engine, state) = EmptyBoard(db);
            var unit = MakeActionQuotaProbe(state, side, "infantry");
            if (mode == 2) engine.Api.JsonSetString(unit, "customName1", "isArmorUnit");
            if (!engine.MoveUnit(unit, 0, out _)) return "额度生命周期布景移动失败";
            if (unit.AttacksThisTurn != 0 || unit.RemainingAttacks != (mode == 2 ? 1 : 0)
                || unit.Snapshot().AttackQuotaOffset != (mode == 2 ? 0 : -1))
                return "移动清空额度不得伪造实际攻击次数，快照必须保留额度偏移";
            if (mode == 0)
            {
                engine.Api.GiveKeyword(unit, Keyword.Fury);
                if (unit.RemainingAttacks != 0 || engine.Attack(unit, state.Hq(side.Opposite())))
                    return "尚未攻击且额度已清零时，给予Fury不得重开攻击额度";
            }
            else if (mode == 1)
            {
                engine.Api.JsonSetString(unit, "customName1", "CanMoveAndAttackInTheSameTurn");
                if (unit.HasAttackLeft || engine.Attack(unit, state.Hq(side.Opposite())))
                    return "移动后才获同回合行动能力不能恢复此前已清空的额度";
            }
            else
            {
                engine.Api.JsonClear(unit, "customName1");
                if (!engine.Attack(unit, state.Hq(side.Opposite())))
                    return "撤销同回合行动能力不追溯清除已保留额度";
            }
            int previousAttackCount = unit.AttacksThisTurn;
            bool previouslyAttacked = unit.HasAttackedThisTurn;
            engine.Api.InvokeByName("ResetUnitOperations", unit, new object?[] { 60, 9004, null },
                new EffectContext { Engine = engine, State = state, Self = unit, Controller = side }, out _);
            if (unit.AttacksThisTurn != previousAttackCount || unit.HasAttackedThisTurn != previouslyAttacked
                || unit.HasMovedThisTurn || unit.RemainingAttacks != (mode == 0 ? 2 : 1))
                return "重置行动应恢复独立攻击额度并保留攻击历史";
        }
        return null;
    }

    private static IDisposable InstallOperationSpendProbes()
    {
        var installed = new List<(IDictionary<string, IReadOnlyList<KismetStep>> Locals, string Trigger)>();
        foreach (string name in new[] { "card_unit_typhoon_mk_ib", "card_event_honorifics", "card_unit_51e_regiment", "card_unit_t_34_85" })
        foreach (string trigger in new[] { "OnOperationKreditsSpent", "OnOtherCardOperationKreditsSpent" })
        {
            if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
                || KismetLibrary.Default.FindProgram(name, trigger) is not null)
            {
                foreach (var item in installed) item.Locals.Remove(item.Trigger);
                throw new InvalidOperationException("无法安全安装T68探针");
            }
            locals.Add(trigger, new[] {
                new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "kreditsSpent", Scope = "local" }, null, -1, "_auditT68Cost", null) { DestinationScope = "instance" },
                new KismetStep(1, "call", "SpawnCardInDeckBySide", new[] {
                    new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                    new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
                }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
            installed.Add((locals, trigger));
        }
        return new AuditProbeCleanup(() => { foreach (var item in installed) item.Locals.Remove(item.Trigger); });
    }

    private static string? OperationSpendQueryAndExecution(CardDatabase db)
    {
        using var probe = InstallOperationSpendProbes();
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int cost in new[] { 0, 3 })
        foreach (int mode in Enumerable.Range(0, 18))
        {
            const string trigger = "OnOtherCardOperationKreditsSpent";
            var (engine, state) = EmptyBoard(db);
            var subject = state.CreateWithId("card_unit_typhoon_mk_ib", side, 60,
                mode == 2 ? CardLocation.NotAvailable : side.HqOf(), 1);
            var first = state.CreateWithId("card_event_honorifics", side, 20,
                mode == 3 ? CardLocation.NotAvailable : side.HqOf(), 2);
            var last = state.CreateWithId("card_unit_51e_regiment", side, 21, side.HqOf(), 3);
            var cards = new[] { subject, first, last };
            foreach (var card in cards) card.Definition = new CardDefinition { Name = card.Name, UsedTriggers = new[] { trigger } };
            if (mode == 1) subject.Keywords.Add(Keyword.Suppressed);
            if (mode is 4 or 5 or 6) last.Keywords.Add(Keyword.Suppressed);
            if (mode is 5 or 6) last.SuppressionExceptionTriggers.Add(trigger);
            if (mode is 10 or 16 or 17) first.Keywords.Add(Keyword.Suppressed);
            if (mode == 17) first.SuppressionExceptionTriggers.Add(trigger);
            if (mode == 14) state.StopFurtherActions = true;
            var called = new List<int>(); var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name != "card_unit_routed_troops") return;
                var current = cards.Single(x => !called.Contains(x.CardId) && x.BlueprintVariables.ContainsKey("_auditT68Cost"));
                called.Add(current.CardId);
                if (current == subject)
                {
                    if (mode == 9) first.Keywords.Add(Keyword.Suppressed);
                    if (mode == 10) first.Keywords.Remove(Keyword.Suppressed);
                    if (mode == 11) last.Definition = new CardDefinition { Name = last.Name };
                    if (mode == 15) subject.Location = CardLocation.NotAvailable;
                }
                if (current == first)
                {
                    if (mode is 4 or 5) last.Keywords.Remove(Keyword.Suppressed);
                    if (mode == 7) last.Keywords.Add(Keyword.Suppressed);
                    if (mode == 8) last.Location = CardLocation.NotAvailable;
                    if (mode == 12) last.Definition = new CardDefinition { Name = last.Name };
                    if (mode == 13) state.StopFurtherActions = true;
                }
            };
            engine.Api.ExecuteOnOperationKreditsSpent(subject, cost);
            int[] expected = mode == 1 ? new[] { 20, 21 }
                : mode is 4 or 6 or 7 or 11 ? new[] { 60, 20 }
                : mode is 9 or 16 or 17 ? new[] { 60, 21 } : new[] { 60, 20, 21 };
            if (!called.SequenceEqual(expected))
                return $"T68查询/执行门错误：{side} 费用{cost} mode={mode} 期望{string.Join(",", expected)} 实际{string.Join(",", called)}";
            foreach (int id in called)
                if (cards.Single(x => x.CardId == id).BlueprintVariables.GetValueOrDefault("_auditT68Cost") is not int value || value != cost)
                    return "T68必须保留费用整数，包括0";
            if (mode is 13 or 14 && !state.StopFurtherActions) return "T68不得重置停止标志";
        }
        return null;
    }

    private static string? ForceAdvanceUnavailableOperation(CardDatabase db)
    {
        using var probe = InstallOperationSpendProbes();
        const string name = "card_unit_t_34_85", trigger = "OnMoveToFrontline";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(name, trigger) is not null) return "无法安全安装移出可用位置探针";
        locals.Add(trigger, new[] {
            new KismetStep(0, "call", "SpawnCardInDeckBySide", new[] {
                new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
            }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            {
                var (engine, state) = EmptyBoard(db);
                var unit = state.CreateWithId(name, side, 60, side.HqOf(), 1);
                int moveCalls = 0, spendCalls = 0; var created = state.CardCreated;
                state.CardCreated = made => {
                    created?.Invoke(made);
                    if (made.Name != "card_unit_routed_troops") return;
                    if (!unit.BlueprintVariables.ContainsKey("_auditT68Cost")) { moveCalls++; unit.Location = CardLocation.NotAvailable; }
                    else if (unit.BlueprintVariables["_auditT68Cost"] is int value && value == 0) spendCalls++;
                };
                if (!engine.MoveUnitFromSupportToFrontLine(unit, 9004, out _)
                    || unit.Location != CardLocation.NotAvailable || moveCalls != 1 || spendCalls != 1)
                    return "推进事件移出可用位置后，原生仍继续零费自身行动事件";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? ForceAdvanceQuotaAndZeroCost(CardDatabase db)
    {
        const string name = "card_unit_arado_ar_196";
        var installed = new List<(IDictionary<string, IReadOnlyList<KismetStep>> Locals, string Trigger)>();
        foreach (string trigger in new[] { "OnMoveToFrontline", "OnOperationKreditsSpent" })
        {
            if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
                || KismetLibrary.Default.FindProgram(name, trigger) is not null)
            {
                foreach (var item in installed) item.Locals.Remove(item.Trigger);
                return "无法安全安装强制推进额度探针";
            }
            locals.Add(trigger, new[] {
                new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Int = trigger == "OnMoveToFrontline" ? 1 : 2 }, null, -1, "_auditForceStage", null) { DestinationScope = "instance" },
                new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = trigger == "OnMoveToFrontline" ? "moveCost" : "kreditsSpent", Scope = "local" }, null, -1, "_auditForceCost", null) { DestinationScope = "instance" },
                new KismetStep(2, "call", "SpawnCardInDeckBySide", new[] {
                    new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                    new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
                }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
            installed.Add((locals, trigger));
        }
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int mode in Enumerable.Range(0, 6))
            foreach (bool movedBefore in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db); state.ActiveSide = side.Opposite(); state.SetKredits(side, 9);
                var unit = state.CreateWithId(name, side, 60, side.HqOf(), 1);
                string type = mode == 1 ? "tank" : mode == 2 ? "tankdestroyer" : mode == 5 ? "fighter" : "infantry";
                unit.Definition = new CardDefinition { Name = name, Type = type };
                if (mode == 3) engine.Api.JsonSetString(unit, "customName1", "isArmorUnit");
                if (mode == 4) engine.Api.JsonSetString(unit, "customName1", "CanMoveAndAttackInTheSameTurn");
                unit.Keywords.Add(Keyword.Fury); unit.AttacksThisTurn = 1; unit.HasMovedThisTurn = movedBefore;
                var stages = new List<int>(); bool quotaCorrect = true;
                var created = state.CardCreated;
                state.CardCreated = made => {
                    created?.Invoke(made);
                    if (made.Name != "card_unit_routed_troops") return;
                    stages.Add(Convert.ToInt32(unit.BlueprintVariables.GetValueOrDefault("_auditForceStage")));
                    quotaCorrect &= unit.HasMovedThisTurn && unit.AttacksThisTurn == 1 && unit.HasAttackLeft == (mode is not (0 or 5))
                        && unit.BlueprintVariables.GetValueOrDefault("_auditForceCost") is int value && value == 0;
                };
                bool movementSawOldQuota = false; var previous = state.CardMoved;
                state.CardMoved = (card, oldLocation, newLocation, changeOwner, reason) => {
                    if (card == unit) movementSawOldQuota = unit.HasMovedThisTurn == movedBefore && unit.AttacksThisTurn == 1;
                    previous?.Invoke(card, oldLocation, newLocation, changeOwner, reason);
                };
                var program = new KismetProgram(new[] {
                    new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Bool = true }, null, -1, "qqq", null),
                    new KismetStep(1, "call", "MoveUnitFromSupportToFrontLine", new[] {
                        new KismetExpr { Self = true }, new KismetExpr { Int = 9004 }, new KismetExpr { Var = "qqq", Scope = "local" }
                    }, new[] { 2 }, null, null, -1, null, null),
                    new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null)
                }, 0);
                var output = engine.Api.Vm.RunLocalProgramMulti(program,
                    new EffectContext { Engine = engine, State = state, Self = unit, Controller = side }, null, "qqq");
                if (output.GetValueOrDefault("qqq") is not false || unit.Location != CardLocation.BoardFrontline
                    || !movementSawOldQuota || !quotaCorrect || !stages.SequenceEqual(new[] { 1, 2 }) || state.Kredits(side) != 9)
                    return $"强制推进额度/零费/输出错误：{side} mode={mode} 旧移动={movedBefore} 阶段{string.Join(",", stages)}";
            }
            return null;
        }
        finally { foreach (var item in installed) item.Locals.Remove(item.Trigger); }
    }

    private static string? ForceAdvancePlacement(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int mode in new[] { 0, 1, 2 })
        {
            var (engine, state) = EmptyBoard(db);
            var first = state.CreateWithId("card_unit_432_infantry_regiment", side.Opposite(), 100, CardLocation.BoardFrontline, 7);
            var second = state.CreateWithId(first.Name, side, 101, CardLocation.BoardFrontline, 15);
            var unit = state.CreateWithId(first.Name, side, 60, mode == 1 ? CardLocation.BoardFrontline : side.HqOf(), mode == 1 ? 0 : 7);
            var remaining = state.CreateWithId(first.Name, side, 61, side.HqOf(), 15);
            if (mode == 2) for (int i = 0; i < 3; i++) state.CreateWithId(first.Name, side.Opposite(), 110 + i, CardLocation.BoardFrontline, 20 + i);
            state.FrontlineOwner = side; // Probe physical count even with mixed owners.
            int moved = 0; var previous = state.CardMoved;
            state.CardMoved = (card, oldLocation, newLocation, changed, reason) => {
                if (card == unit) moved++;
                previous?.Invoke(card, oldLocation, newLocation, changed, reason);
            };
            int before = state.ActionLog.SelectMany(x => x.SubActions).Count();
            bool success = engine.MoveUnitFromSupportToFrontLine(unit, 9004, out _);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
            if (mode == 2)
            {
                if (success || unit.Location != side.HqOf() || moved != 0 || actions.Length != before)
                    return "强制推进容量应按全部物理前线对象判满";
                continue;
            }
            var notification = actions.SingleOrDefault(x => x.Name == "ZActionMoveCardToNewLocation");
            if (!success || moved != 1 || unit.LocationNumber != (mode == 1 ? 2 : 0)
                || first.LocationNumber != (mode == 1 ? 0 : 1) || second.LocationNumber != (mode == 1 ? 1 : 2)
                || remaining.LocationNumber != (mode == 1 ? 15 : 1) || notification is null
                || notification.Values.First(x => x.Name == "instigatorID").Value != 9004
                || notification.Values.First(x => x.Name == "newLocationNumber").Value != (mode == 1 ? 3 : 2)
                || notification.Values.First(x => x.Name == "movementLeft").Value != 1)
                return $"强制推进物理槽位/同区回调/通知错误：{side} mode={mode}";
        }
        return null;
    }

    private static string? FrontlineEntryStages(CardDatabase db)
    {
        var installed = new List<(IDictionary<string, IReadOnlyList<KismetStep>> Locals, string Trigger)>();
        foreach (string name in new[] { "card_unit_typhoon_mk_ib", "card_event_honorifics", "card_unit_51e_regiment" })
        foreach (string trigger in new[] { "OnMoveToFrontline", "OnOtherCardMoveToFrontline" })
        {
            if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
                || KismetLibrary.Default.FindProgram(name, trigger) is not null)
            {
                foreach (var item in installed) item.Locals.Remove(item.Trigger);
                return "无法安全安装推进事件探针";
            }
            locals.Add(trigger, new[] {
                new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "ForceMove", Scope = "local" }, null, -1, "_auditT50Force", null) { DestinationScope = "instance" },
                new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "moveCost", Scope = "local" }, null, -1, "_auditT50Cost", null) { DestinationScope = "instance" },
                new KismetStep(2, "call", "SpawnCardInDeckBySide", new[] {
                    new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                    new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
                }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
            installed.Add((locals, trigger));
        }
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool force in new[] { false, true })
            foreach (int mode in Enumerable.Range(0, 19))
            {
                const string trigger = "OnOtherCardMoveToFrontline";
                var (engine, state) = EmptyBoard(db);
                state.StopFurtherActions = true; // The helper must reset this at entry.
                var subject = state.CreateWithId("card_unit_typhoon_mk_ib", side, 60,
                    mode == 18 ? side.HqOf() : CardLocation.BoardFrontline, 0);
                var gotcha = state.CreateWithId("card_event_honorifics", side.Opposite(), 30, side.Opposite().HandOf(), 0);
                var first = state.CreateWithId("card_unit_51e_regiment", side, 20, side.HqOf(), 1);
                var last = state.CreateWithId(first.Name, side, 21, mode == 13 ? CardLocation.NotAvailable : side.HqOf(), 2);
                var cards = new List<CardInstance> { subject, gotcha, first, last };
                foreach (var card in cards) card.Definition = new CardDefinition {
                    Name = card.Name, Type = card == gotcha ? "gotcha" : "infantry",
                    UsedTriggers = card == gotcha && mode == 4 ? Array.Empty<string>() : new[] { trigger }
                };
                gotcha.GotchaActivated = 1;
                if (mode == 3) gotcha.Keywords.Add(Keyword.Suppressed);
                if (mode == 5) subject.Keywords.Add(Keyword.Suppressed);
                if (mode is 6 or 7) subject.Keywords.Add(Keyword.Covert);
                if (mode is 16 or 17) first.Keywords.Add(Keyword.Suppressed);
                if (mode == 16) first.SuppressionExceptionTriggers.Add(trigger);
                CardInstance? secondGotcha = null;
                if (mode == 15)
                {
                    secondGotcha = state.CreateWithId(gotcha.Name, gotcha.Owner, 31, gotcha.Owner.HandOf(), 1);
                    secondGotcha.Definition = gotcha.Definition; secondGotcha.GotchaActivated = 2; cards.Add(secondGotcha);
                }
                int cost = force ? 0 : 3;
                var called = new List<int>(); var created = state.CardCreated;
                state.CardCreated = made => {
                    created?.Invoke(made);
                    if (made.Name != "card_unit_routed_troops") return;
                    var current = cards.Single(x => !called.Contains(x.CardId)
                        && x.BlueprintVariables.ContainsKey("_auditT50Cost"));
                    called.Add(current.CardId);
                    if (current == gotcha)
                    {
                        if (mode == 1) state.StopFurtherActions = true;
                        if (mode == 2) subject.Location = CardLocation.Discard;
                        if (mode == 14)
                        {
                            var added = state.CreateWithId(gotcha.Name, gotcha.Owner, 40, gotcha.Owner.HandOf(), 1);
                            added.Definition = gotcha.Definition; added.GotchaActivated = 2; cards.Add(added);
                        }
                        if (mode == 15)
                        {
                            secondGotcha!.GotchaActivated = 0; secondGotcha.Keywords.Add(Keyword.Suppressed);
                            secondGotcha.Location = CardLocation.NotAvailable;
                        }
                    }
                    if (current == subject)
                    {
                        if (mode == 7) subject.IsRevealed = true;
                        if (mode == 8) subject.Location = CardLocation.Discard;
                        if (mode == 9) state.StopFurtherActions = true;
                        if (mode == 10) first.Keywords.Add(Keyword.Suppressed);
                    }
                    if (current == first)
                    {
                        if (mode == 11) state.StopFurtherActions = true;
                        if (mode == 12) { last.Keywords.Add(Keyword.Suppressed); last.Location = CardLocation.NotAvailable; }
                    }
                };
                engine.Api.ExecuteOnMoveToFrontlineCardEffects(subject, force, cost);
                var expected = mode is 1 or 2 or 18 ? new List<int> { 30 }
                    : mode is 6 or 9 ? new List<int> { 30, 60 }
                    : mode == 5 ? new List<int> { 30, 20, 21 }
                    : mode is 10 or 17 ? new List<int> { 30, 60, 21 }
                    : mode == 11 ? new List<int> { 30, 60, 20 }
                    : mode == 14 ? new List<int> { 30, 60, 20, 21, 40 }
                    : mode == 15 ? new List<int> { 30, 31, 60, 20, 21 }
                    : new List<int> { 30, 60, 20, 21 };
                if (!called.SequenceEqual(expected))
                    return $"T50阶段错误：{side} force={force} mode={mode} 期望{string.Join(",", expected)} 实际{string.Join(",", called)}";
                foreach (int id in called)
                {
                    var card = cards.Single(x => x.CardId == id);
                    if (!Equals(card.BlueprintVariables.GetValueOrDefault("_auditT50Force"), force)
                        || Convert.ToInt32(card.BlueprintVariables.GetValueOrDefault("_auditT50Cost")) != cost)
                        return "推进自身/反制/观察者的forceMove与moveCost载荷错误";
                }
            }
            return null;
        }
        finally { foreach (var item in installed) item.Locals.Remove(item.Trigger); }
    }

    private static string? FrontlinePhysicalFirst(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool hq in new[] { false, true })
        foreach (bool unchanged in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var first = hq ? state.Hq(side)
                : state.CreateWithId("card_unit_432_infantry_regiment", side, 90, CardLocation.BoardFrontline, 9);
            first.Location = CardLocation.BoardFrontline; first.LocationNumber = 9;
            var second = state.CreateWithId("card_unit_432_infantry_regiment", side.Opposite(), 20, CardLocation.BoardFrontline, 0);
            state.FrontlineOwner = unchanged ? side : side.Opposite();
            state.CardMoved?.Invoke(second, second.Owner.HqOf(), CardLocation.BoardFrontline, false, CardMoveReason.PlayCardForce);
            if (state.FrontlineOwner != side)
                return $"前线首对象应按物理数组：{side} HQ={hq} 未变化={unchanged} 实际={state.FrontlineOwner}";
        }
        return null;
    }

    private static string? FrontlineObserverSnapshot(CardDatabase db)
    {
        const string trigger = "OnFrontlineOwnershipChange";
        var installed = new List<IDictionary<string, IReadOnlyList<KismetStep>>>();
        foreach (string name in new[] { "card_unit_typhoon_mk_ib", "card_event_honorifics", "card_unit_51e_regiment" })
        {
            if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
                || KismetLibrary.Default.FindProgram(name, trigger) is not null)
            {
                foreach (var item in installed) item.Remove(trigger);
                return "无法安全安装前线归属探针";
            }
            locals.Add(trigger, new[] {
                new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "instigator", Scope = "local" }, null, -1, "_auditFrontlineSource", null) { DestinationScope = "instance" },
                new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "oldSide", Scope = "local" }, null, -1, "_auditFrontlineOld", null) { DestinationScope = "instance" },
                new KismetStep(2, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "newSide", Scope = "local" }, null, -1, "_auditFrontlineNew", null) { DestinationScope = "instance" },
                new KismetStep(3, "call", "SpawnCardInDeckBySide", new[] {
                    new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                    new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
                }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(4, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
            installed.Add(locals);
        }
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int mode in Enumerable.Range(0, 11))
            {
                var (engine, state) = EmptyBoard(db);
                var subject = state.CreateWithId("card_unit_typhoon_mk_ib", side, 60,
                    mode >= 9 ? side.HandOf() : CardLocation.BoardFrontline, 0);
                var first = state.CreateWithId("card_event_honorifics", side, 20, side.HqOf(), 1);
                var last = state.CreateWithId("card_unit_51e_regiment", side, 21,
                    mode == 2 ? CardLocation.NotAvailable : side.HqOf(), 2);
                var cards = new[] { first, last, subject };
                foreach (var card in cards) card.Definition = new CardDefinition { Name = card.Name, UsedTriggers = new[] { trigger } };
                Side old = mode == 9 ? side : mode == 10 ? Side.NotAvailable : mode == 8 ? side : side.Opposite();
                state.FrontlineOwner = old;
                if (mode == 1) state.StopFurtherActions = true;
                if (mode is 4 or 5) first.Keywords.Add(Keyword.Suppressed);
                if (mode == 5) first.SuppressionExceptionTriggers.Add(trigger);
                var called = new List<int>(); var created = state.CardCreated;
                state.CardCreated = made => {
                    created?.Invoke(made);
                    if (made.Name != "card_unit_routed_troops") return;
                    var current = cards.Single(x => !called.Contains(x.CardId)
                        && x.BlueprintVariables.ContainsKey("_auditFrontlineNew"));
                    called.Add(current.CardId);
                    if (current == first)
                    {
                        if (mode == 3) { last.Keywords.Add(Keyword.Suppressed); last.Location = CardLocation.NotAvailable; }
                        if (mode == 6) { state.FrontlineOwner = side.Opposite(); state.StopFurtherActions = true; }
                        if (mode == 7) state.FrontlineOwner = Side.NotAvailable;
                    }
                };
                state.CardMoved?.Invoke(subject, side.HqOf(), CardLocation.BoardFrontline, false, CardMoveReason.PlayCardForce);
                int[] expected = mode is 8 or 10 ? Array.Empty<int>() : mode == 4 ? new[] { 21, 60 } : new[] { 20, 21, 60 };
                if (!called.SequenceEqual(expected))
                    return $"T27快照资格错误：{side} mode={mode} 实际{string.Join(",", called)}";
                foreach (int id in called)
                {
                    var card = cards.Single(x => x.CardId == id);
                    Side expectedNew = mode == 9 || mode == 7 && id != 20 ? Side.NotAvailable
                        : mode == 6 && id != 20 ? side.Opposite() : side;
                    if (Convert.ToInt32(card.BlueprintVariables["_auditFrontlineSource"]) != 60
                        || Convert.ToInt32(card.BlueprintVariables["_auditFrontlineOld"]) != (int)old
                        || Convert.ToInt32(card.BlueprintVariables["_auditFrontlineNew"]) != (int)expectedNew)
                        return $"T27应固定oldSide但逐项读取newSide：{side} mode={mode} 接收者{id}";
                }
            }
            return null;
        }
        finally { foreach (var item in installed) item.Remove(trigger); }
    }

    // Temporary registered definitions and programs probe the dispatcher only;
    // these are not assertions about the named live cards' actual abilities.
    private static IDisposable InstallMovementObserverProbes()
    {
        var installed = new List<(IDictionary<string, IReadOnlyList<KismetStep>> Locals, string Trigger)>();
        foreach (string name in new[] { "card_unit_typhoon_mk_ib", "card_event_honorifics", "card_unit_51e_regiment" })
        foreach (string trigger in new[] { "OnCardLocationMoved", "OnOtherCardLocationMoved", "OnMoveFromFrontline", "OnOtherCardMoveFromFrontline" })
        {
            if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
                || KismetLibrary.Default.FindProgram(name, trigger) is not null)
            {
                foreach (var item in installed) item.Locals.Remove(item.Trigger);
                throw new InvalidOperationException("无法安全安装移动事件探针：" + name + " " + trigger);
            }
            locals.Add(trigger, new[] {
                new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Bool = true }, null, -1, "_auditMovementCalled", null) { DestinationScope = "instance" },
                new KismetStep(1, "call", "SpawnCardInDeckBySide", new[] {
                    new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                    new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
                }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
            installed.Add((locals, trigger));
        }
        return new AuditProbeCleanup(() => { foreach (var item in installed) item.Locals.Remove(item.Trigger); });
    }

    private static string? MovementObserverSnapshots(CardDatabase db)
    {
        using var probes = InstallMovementObserverProbes();
        foreach (bool retreat in new[] { false, true })
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int mode in Enumerable.Range(0, 11))
        {
            var (engine, state) = EmptyBoard(db);
            string trigger = retreat ? "OnOtherCardMoveFromFrontline" : "OnOtherCardLocationMoved";
            var subject = state.CreateWithId("card_unit_typhoon_mk_ib", side, 60, side.HqOf(), 1);
            var first = state.CreateWithId("card_event_honorifics", side, 20, side.HqOf(), 2);
            var last = state.CreateWithId("card_unit_51e_regiment", side, 21, mode == 9 ? CardLocation.NotAvailable : side.HqOf(), 3);
            var cards = new[] { subject, first, last };
            foreach (var card in cards) card.Definition = new CardDefinition { Name = card.Name, UsedTriggers = new[] { trigger } };
            if (mode == 1) state.StopFurtherActions = true;
            if (mode == 5) subject.Keywords.Add(Keyword.Suppressed);
            if (mode is 6 or 7) first.Keywords.Add(Keyword.Suppressed);
            if (mode == 6) first.SuppressionExceptionTriggers.Add(trigger);
            var called = new List<int>(); var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name != "card_unit_routed_troops") return;
                var current = cards.Single(x => !called.Contains(x.CardId)
                    && Equals(x.BlueprintVariables.GetValueOrDefault("_auditMovementCalled"), true));
                called.Add(current.CardId);
                if (current == subject)
                {
                    if (mode == 2) state.StopFurtherActions = true;
                    if (mode == 4) first.Keywords.Add(Keyword.Suppressed);
                    if (mode == 10) subject.Location = CardLocation.NotAvailable;
                }
                if (current == first)
                {
                    if (mode == 3) state.StopFurtherActions = true;
                    if (mode == 8) { last.Keywords.Add(Keyword.Suppressed); last.Location = CardLocation.NotAvailable; }
                }
            };
            if (retreat) engine.ExecuteOnCardMoveFromFrontline(subject);
            else engine.ExecuteOnCardLocationMoved(subject, CardLocation.BoardFrontline, side.HqOf(), true, CardMoveReason.ControlRelease);
            var expected = mode == 5 ? new List<int>() : new List<int> { 60 };
            if (!(retreat && mode is 1 or 2))
            {
                if (mode is not (4 or 7)) expected.Add(20);
                if (!(retreat && mode == 3)) expected.Add(21);
            }
            if (!called.SequenceEqual(expected))
                return $"移动快照错误：T{(retreat ? 49 : 47)} {side} mode={mode} 期望{string.Join(",", expected)} 实际{string.Join(",", called)}";
        }
        return null;
    }

