    private static string? HandDiscardSuccessReentry(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib", trigger = "OnSuccesfulDiscard";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(trigger)) return "无法安全添加成功弃牌探针";
        locals.Add(trigger, new[] {
            new KismetStep(0, "call", "SpawnCardInDeckBySide", new[] {
                new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
            }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "call", "SuppressUnit", new[] { new KismetExpr { Int = 20 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool random in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var card = state.CreateWithId(name, side, 60, side.HandOf(), 7);
                state.CreateWithId("card_unit_211th_basargino", side, 20, side.HqOf(), 1);
                var created = state.CardCreated;
                state.CardCreated = made => {
                    created?.Invoke(made);
                    if (made.Name == "card_unit_routed_troops") card.Location = CardLocation.NotAvailable;
                };
                var trace = new List<string>(); engine.Api.TriggerTrace = trace;
                var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
                var result = engine.Api.InvokeByName(random ? "DiscardRandomCardFromHand" : "DiscardCardFromHand", card,
                    random ? new object?[] { (int)side, 9004, null } : new object?[] { 60, 9004, false, false, null }, context, out _);
                if (!(random ? result is 60 : result is true) || card.Location != CardLocation.NotAvailable
                    || trace.Any(x => x.StartsWith("OnOtherCardDiscarded → card_unit_211th_basargino#20", StringComparison.Ordinal)))
                    return "成功回调改位置不应改变返回值；回调抑制的观察者应在后续T41查询被过滤";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? HandDiscardCancellationFlags(CardDatabase db)
    {
        // Same program as DeckDiscardCancellation: the local-program cache may
        // retain it, so use exactly the same probe body for this shared name.
        const string name = "card_unit_typhoon_mk_ib", trigger = "OnAttemptedDiscard";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(trigger)) return "无法安全添加手牌取消探针";
        locals.Add(trigger, new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "discarderID", Scope = "local" }, null, -1, "_auditDiscarder", null) { DestinationScope = "instance" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Bool = true }, null, -1, "cancelDiscard", null) { DestinationScope = "local" },
            new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int source in new[] { 0, 9004 })
            foreach (bool force in new[] { false, true })
            foreach (bool restricted in new[] { false, true })
            foreach (bool suppressed in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var card = state.CreateWithId(name, side, 60, side.HandOf(), 7);
                if (restricted) state.AddGameplayRestriction(side, GameplayRestrictionType.CannotDiscardAnyCardFromHand, 30, 2);
                if (suppressed) card.Keywords.Add(Keyword.Suppressed);
                var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
                object? result = engine.Api.InvokeByName("DiscardCardFromHand", card,
                    new object?[] { 60, source, false, force, null }, context, out _);
                bool expected = force || suppressed && !restricted;
                bool attempted = !force && !restricted && !suppressed;
                if (!Equals(result, expected) || (card.Location == CardLocation.Discard) != expected
                    || card.BlueprintVariables.ContainsKey("_auditDiscarder") != attempted
                    || attempted && Convert.ToInt32(card.BlueprintVariables["_auditDiscarder"]) != source)
                    return $"手牌取消门错误：{side} 来源{source} 强制{force} 限制{restricted} 抑制{suppressed}";
                var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionDiscardCard").ToArray();
                if (actions.Length != (expected ? 1 : 0)
                    || expected && actions[0].Values.First(x => x.Name == "discarderID").Value != source)
                    return "手牌弃牌必须保留原始来源，包括不存在的正ID";
                if (!expected)
                {
                    object? selected = engine.Api.InvokeByName("DiscardRandomCardFromHand", card,
                        new object?[] { (int)side, source, null }, context, out _);
                    if (selected is not 60 || card.Location != side.HandOf())
                        return "随机弃牌取消后仍应返回选中的卡ID";
                }
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? HandDiscardNotificationBoundary(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool skip in new[] { false, true })
        foreach (bool suppressed in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId("card_unit_sally", side, 60, side.HandOf(), 7);
            var remaining = state.CreateWithId("card_unit_432_infantry_regiment", side, 61, side.HandOf(), 15);
            var oldDiscard = state.CreateWithId(remaining.Name, side, 62, CardLocation.Discard, 17);
            state.CreateWithId(remaining.Name, side, 63, side.DeckOf(), 0);
            state.CreateWithId(remaining.Name, side, 64, side.DeckOf(), 1);
            var observer = state.CreateWithId("card_unit_211th_basargino", side, 20, CardLocation.NotAvailable, 0);
            if (suppressed) card.Keywords.Add(Keyword.Suppressed);
            var trace = new List<string>(); engine.Api.TriggerTrace = trace;
            int moves = 0;
            var previous = state.CardMoved;
            state.CardMoved = (c, oldLocation, newLocation, ownerChange, reason) => {
                if (c == card) moves++;
                previous?.Invoke(c, oldLocation, newLocation, ownerChange, reason);
            };
            var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            var result = engine.Api.InvokeByName("DiscardCardFromHand", card,
                new object?[] { 60, 9004, skip, false, null }, context, out _);
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionDiscardCard").ToArray();
            if (result is not true || card.LocationNumber != 7 || oldDiscard.LocationNumber != 17
                || remaining.LocationNumber != 0 || moves != 0 || actions.Length != (skip ? 0 : 1)
                || state.Hand(side).Count != (suppressed ? 1 : 3)
                || !trace.Any(x => x.StartsWith("OnOtherCardDiscarded → card_unit_211th_basargino#20", StringComparison.Ordinal)))
                return $"手牌弃牌通知边界错误：{side} skip={skip} 抑制={suppressed}";
            if (!skip && (actions[0].Values.First(x => x.Name == "cardID").Value != 60
                || actions[0].Values.First(x => x.Name == "discarderID").Value != 9004
                || actions[0].Values.First(x => x.Name == "oldLocation").Text != (side == Side.Left ? "Hand_Left" : "Hand_Right")))
                return "手牌弃牌通知缺失原始卡/来源/旧位置";
        }
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var wrongOwner = state.CreateWithId("card_unit_432_infantry_regiment", side.Opposite(), 59, side.HandOf(), 0);
            var card = state.CreateWithId(wrongOwner.Name, side, 60, side.HandOf(), 1);
            var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            var result = engine.Api.InvokeByName("DiscardRandomCardFromHand", card,
                new object?[] { (int)side, 9004, null }, context, out _);
            if (result is not 60 || wrongOwner.Location != side.HandOf() || card.Location != CardLocation.Discard)
                return "随机弃牌候选必须同时满足位置和所属方";
        }
        return null;
    }

    private static string? SpawnHandImplicitOutId(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_432_infantry_regiment", side, 60, CardLocation.Discard, 0);
            var steps = new[] {
                new KismetStep(0, "call", "SpawnCardInHandBySide", new[] {
                    new KismetExpr { Int = (int)side }, new KismetExpr { Name = "card_event_supply_chain" },
                    new KismetExpr { Int = source.CardId }, new KismetExpr { Bool = true },
                    new KismetExpr { Bool = false }, new KismetExpr { Bool = false },
                    new KismetExpr { Str = "" }, new KismetExpr { Var = "campaign", Scope = "local" },
                    new KismetExpr { Int = 0 }, new KismetExpr { Var = "spawnedID", Scope = "local" }
                }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Math = "Add_IntInt", Args = new[] {
                        new KismetExpr { Var = "spawnedID", Scope = "local" }, new KismetExpr { Int = 1 }
                    } }, null, -1, "nextID", null),
                new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null)
            };
            var output = engine.Api.Vm.RunLocalProgramMulti(new KismetProgram(steps, 0),
                new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, null, "spawnedID", "nextID");
            var spawned = state.Hand(side).Single(x => x.Name == "card_event_supply_chain");
            if (output.GetValueOrDefault("spawnedID") is not int id || id != spawned.CardId
                || Convert.ToInt32(output.GetValueOrDefault("nextID")) != id + 1 || source.KreditCost != source.Definition.Kredits)
                return "手牌生成调用必须写入整数新ID，不能留下空槽或写入卡对象";
        }
        return null;
    }

    private static string? DirectPlayBlockedDestination(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int mode in new[] { 0, 1, 2, 3 })
        foreach (bool restricted in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.ActiveSide = side.Opposite();
            state.SetKredits(side, 4);
            if (mode == 0)
                for (int i = 0; i < 4; i++) state.CreateWithId("card_unit_432_infantry_regiment", side, 100 + i, side.HqOf(), i + 1);
            if (mode is 1 or 3)
                for (int i = 0; i < state.FrontlineCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", side, 110 + i, CardLocation.BoardFrontline, i);
            if (mode is 2 or 3) state.FrontlineOwner = side.Opposite();
            if (restricted) state.AddGameplayRestriction(side, GameplayRestrictionType.CannotDiscardAnyCardFromHand, 30, 2);
            var card = state.CreateWithId("card_unit_35th_mountain_rifles", side, 60, side.HandOf(), 7);
            var remaining = state.CreateWithId("card_unit_432_infantry_regiment", side, 61, side.HandOf(), 15);
            var discarded = state.CreateWithId(remaining.Name, side, 62, CardLocation.Discard, 17);
            int entered = card.EnteredPlayOnTurn, total = state.AllCards.Count();
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            var moved = state.CardMoved;
            int notifications = 0;
            state.CardMoved = (c, oldLocation, newLocation, ownerChange, reason) =>
            {
                if (c == card) notifications++;
                moved?.Invoke(c, oldLocation, newLocation, ownerChange, reason);
            };
            bool success = engine.PlayCardDirectlyFromHand(card, mode != 0, 9004, 1);
            var action = state.ActionLog.SelectMany(x => x.SubActions).SingleOrDefault(x => x.Name == "ZActionDiscardCard");
            if (success || card.Location != CardLocation.Discard || card.LocationNumber != 7 || discarded.LocationNumber != 17
                || remaining.LocationNumber != 0 || state.Kredits(side) != 4 || notifications != 0
                || card.EnteredPlayOnTurn != entered || state.AllCards.Count() != total || state.CardsPlayedThisTurn.Count != 0
                || action is null || action.Values.First(x => x.Name == "cardID").Value != card.CardId
                || action.Values.First(x => x.Name == "discarderID").Value != 0
                || action.Values.First(x => x.Name == "oldLocation").Text != (side == Side.Left ? "Hand_Left" : "Hand_Right")
                || trace.Any(x => x.StartsWith("OnAttemptedDiscard", StringComparison.Ordinal)))
                return $"直接出牌失败分支错误：方={side} 阻挡={mode} 限制={restricted} 结果={success} 位置={card.Location}";
        }
        return null;
    }

    private static string? DirectPlayForcedDiscardEvents(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool suppressed in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.ActiveSide = side;
            state.CreateWithId("card_unit_nakajima_b5n", side, 20, side.HqOf(), 1);
            for (int i = 0; i < 3; i++) state.CreateWithId("card_unit_432_infantry_regiment", side, 100 + i, side.HqOf(), i + 2);
            state.AddGameplayRestriction(side, GameplayRestrictionType.CannotDiscardAnyCardFromHand, 30, 2);
            var card = state.CreateWithId("card_event_supply_chain", side, 60, side.HandOf(), 7);
            if (suppressed) card.Keywords.Add(Keyword.Suppressed);
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            bool success = engine.PlayCardDirectlyFromHand(card, false, 9004, -1);
            var copies = state.Hand(side).Where(x => x.Name == card.Name).ToArray();
            bool own = trace.Any(x => x.StartsWith("OnSuccesfulDiscard →", StringComparison.Ordinal));
            if (success || card.Location != CardLocation.Discard || own == suppressed
                || copies.Length != (suppressed ? 0 : 2) || copies.Any(x => x.KreditCost != 1)
                || !trace.Any(x => x.StartsWith("OnOtherCardDiscarded → card_unit_nakajima_b5n#20", StringComparison.Ordinal)
                    && x.Contains("card_event_supply_chain#60", StringComparison.Ordinal)))
                return $"强制弃牌应保留成功与观察者事件：方={side} 抑制={suppressed} 副本={copies.Length} 费用={string.Join(",", copies.Select(x => x.KreditCost))} 自身={own}";
        }
        return null;
    }

    private static string? GotchaReceiptReplyIntegration(CardDatabase db)
    {
        foreach (bool handReply in new[] { false, true })
        {
            string name = handReply ? "card_unit_52_k" : "card_unit_m36_destroyer";
            using var probe = InstallSelectionDrawProbe(name, handReply ? "OnHandTargetSelected" : "OnPlayedFromHand");
            foreach (Side side in new[] { Side.Left, Side.Right })
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, side, 20, CardLocation.Discard, 0);
                var target = state.CreateWithId("card_unit_432_infantry_regiment", side, 30, side.HandOf(), 0);
                var first = state.CreateWithId("card_event_interception", side, 60, side.DeckOf(), 0);
                var second = state.CreateWithId(first.Name, side, 61, side.DeckOf(), 1);
                engine.Api.AddCustomGameplayTag(first, "autoplay");
                engine.Api.AddCustomGameplayTag(second, "autoplay");
                if (handReply)
                {
                    engine.PickHandTargetId = (_, _) => target.CardId;
                    engine.Api.InvokeByName("selectTargetFromHand", source, new object?[] { source.CardId },
                        new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out _);
                }
                else
                {
                    source.ExtraPlayTriggers = 1;
                    engine.Api.DrawChosenCardToHand(source, first);
                }
                if (first.GotchaActivated != 1 || first.Location != side.HandOf()
                    || engine.Api.JsonGetInt(first, "kreditsPayed") != 1 || second.GotchaActivated != (handReply ? 0 : 2)
                    || second.Location != (handReply ? side.DeckOf() : side.HandOf())
                    || state.GetAutoPlayCards().Length != 0)
                    return $"选择回复未正确应用本批Gotcha通知：方={side} 手牌回复={handReply}";
            }
        }
        return null;
    }

    private static string? GotchaReceiptActionIntegration(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int route in new[] { 0, 1, 2, 3, 4 })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 2;
            state.ActiveSide = side;
            state.SetMaxKredits(side, 10);
            state.SetKredits(side, 10);
            var unit = state.CreateWithId("card_unit_432_infantry_regiment", side, 20,
                route == 4 ? CardLocation.BoardFrontline : side.HqOf(), route == 4 ? 0 : 1);
            unit.EnteredPlayOnTurn = 0;
            var card = state.CreateWithId("card_event_interception", side, 60,
                route <= 1 ? side.DeckOf() : side.HandOf(), 0);
            int entered = card.EnteredPlayOnTurn;
            engine.Api.AddCustomGameplayTag(card, "autoplay"); // Controlled queue-entry tag.
            state.CreateWithId(unit.Name, side, 61, side.DeckOf(), 1);
            if (route == 2) state.CreateWithId(unit.Name, side.Opposite(), 63, side.Opposite().DeckOf(), 0);
            if (route >= 2) state.AddAutoPlayCards(card.CardId);
            bool success = true;
            if (route == 0) engine.StartTurn(side, draw: true);
            else if (route == 1)
            {
                var order = state.CreateWithId("card_event_convoy_175", side, 70, side.HandOf(), 0);
                success = engine.PlayCard(order);
            }
            else if (route == 2) engine.EndTurn(side);
            else if (route == 3) success = engine.MoveUnit(unit, 0);
            else success = engine.Attack(unit, state.Hq(side.Opposite()));
            if (!success || card.Location != side.HandOf() || card.GotchaActivated != 1
                || engine.Api.JsonGetInt(card, "kreditsPayed") != 1 || card.EnteredPlayOnTurn != entered
                || state.GetAutoPlayCards().Length != 0 || state.CardsPlayedThisTurn.Any(x => x.CardId == card.CardId))
                return $"普通行动未完成Gotcha接收阶段：方={side} 路径={route} 激活={card.GotchaActivated} 位置={card.Location} 已付={engine.Api.JsonGetInt(card, "kreditsPayed")} 进入={card.EnteredPlayOnTurn} 队列={state.GetAutoPlayCards().Length}";
        }
        return null;
    }

