    private static string? HandPlayCurrentTargetBoundary(CardDatabase db)
    {
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool gotcha in new[] { false, true })
        foreach (bool stale in new[] { false, true })
        foreach (int route in new[] { 0, 1, 2 })
        foreach (int targetKind in Enumerable.Range(0, route == 0 ? 5 : 1))
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 7; state.ActiveSide = side;
            state.SetMaxKredits(side, 10); state.SetKredits(side, 10);
            var source = state.CreateWithId(gotcha ? "card_event_interception" : "card_unit_432_infantry_regiment", side, 60, side.HandOf(), 0);
            if (!gotcha)
            {
                source.Definition = new CardDefinition { Name = source.Name, Type = "infantry", Attack = 2, Defense = 5 };
                source.Keywords.Clear(); source.Attack = 2; source.Defense = source.MaxDefense = 5;
            }
            source.KreditCost = 0;
            var target = state.CreateWithId(PlainUnit, side.Opposite(), targetKind == 2 ? 0 : targetKind == 3 ? -7 : 70,
                side.Opposite().HqOf(), 1);
            var previous = state.CreateWithId(PlainUnit, side, 72, CardLocation.Discard, 0);
            var rewrite = state.CreateWithId(PlainUnit, side, 73, CardLocation.Discard, 1);
            source.CurrentTarget = stale ? previous : null;
            CardInstance? requested = targetKind == 0 ? null : targetKind == 4
                ? new CardInstance { CardId = target.CardId, Name = target.Name, Owner = target.Owner,
                    OriginalOwner = target.Owner, Definition = target.Definition, Attack = 2, Defense = 5, MaxDefense = 5 }
                : target;
            CardInstance? expected = route == 0 && (targetKind == 1 || targetKind == 4) ? target : null;
            bool movedOnce = false; string? failure = null;
            var moved = state.CardMoved;
            state.CardMoved = (card, oldLocation, newLocation, ownerChange, reason) => {
                if (card == source && oldLocation == side.HandOf() && newLocation == side.HqOf())
                {
                    movedOnce = true;
                    if (!ReferenceEquals(source.CurrentTarget, expected)) failure = "移动回调未看到本次查号后的目标";
                    source.CurrentTarget = rewrite;
                }
                moved?.Invoke(card, oldLocation, newLocation, ownerChange, reason);
            };
            bool success = true;
            if (route == 0) success = engine.PlayCard(source, requested);
            else
            {
                state.AddAutoPlayCards(source.CardId);
                if (route == 1)
                {
                    engine.ExecuteAutoPlayCards();
                    engine.ApplyPendingLocalRuleReceipts();
                }
                else engine.ExecuteQueuedAutoPlayActions();
            }
            if (!success || failure is not null || movedOnce == gotcha
                || !ReferenceEquals(source.CurrentTarget, gotcha ? expected : rewrite))
                return $"hand target case={cases} {side}/{gotcha}/{stale}/{route}/{targetKind}: {failure ?? "late overwrite or Gotcha stale target"}";
            cases++;
        }
        return cases == 56 ? null : $"hand target boundary cases={cases}";
    }

    private static string? HandPlayInlinePincerBoundary(CardDatabase db)
    {
        using var observerProbe = InstallEntrySubjectObservers(includeSubject: false);
        const string name = "card_unit_typhoon_mk_ib";
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool singleton in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 7; state.ActiveSide = side;
            state.SetMaxKredits(side, 10); state.SetKredits(side, 10);
            var observer = state.CreateWithId("card_unit_brewster_f2a", side, 80, CardLocation.Discard, 0);
            observer.Definition = new CardDefinition { Name = observer.Name, UsedTriggers = new[] { "OnOtherCardEnterPlay" } };
            var source = state.CreateWithId(name, side, 60, side.HandOf(), 0);
            source.Definition = new CardDefinition { Name = name, Type = "infantry", Attack = 2, Defense = 5, WaitForHandTarget = true };
            source.Keywords.Clear(); source.Keywords.Add(Keyword.Pincer); source.KreditCost = 0;
            var target = state.CreateWithId(PlainUnit, side, 70, side.HqOf(), 1);
            if (singleton) state.CreateWithId(PlainUnit, side, 71, side.DeckOf(), 0);
            bool ownReturned = false; int observations = 0; string? failure = null;
            var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name != "card_unit_routed_troops") return;
                observations++;
                if (!ownReturned || engine.Api.JsonGetInt(source, "pincer_receiver") != target.CardId)
                    failure = "旁观者早于自身返回或Pincer完成";
            };
            CardEffectScripts.Register(name, ctx => {
                ctx.Engine.Api.InvokeByName("selectCardToDraw", source, new object?[] { source.CardId, true, false }, ctx, out _);
                if (observations != 0 || source.CustomJson.ContainsKey("pincer_receiver")) failure = "内联回复提前续行";
                ownReturned = true;
            });
            bool played;
            try { played = engine.PlayCard(source, target); }
            finally { CardEffectScripts.Unregister(name); }
            if (!played || observations != 1 || failure is not null)
                return $"inline Pincer {side}/{singleton}: {failure ?? "missing/duplicate continuation"}, observers={observations}";
        }
        return null;
    }

    private static string? HandPlayTargetIdDeploymentGate(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib";
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool wait in new[] { false, true })
        foreach (int kind in Enumerable.Range(0, 5))
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 7; state.ActiveSide = side;
            state.SetMaxKredits(side, 10); state.SetKredits(side, 10);
            PutOnBoard(state, "card_unit_b_26_marauder", side, 80, 1);
            var source = state.CreateWithId(name, side, 60, side.HandOf(), 0);
            source.Definition = new CardDefinition { Name = name, Type = "infantry", Attack = 2, Defense = 5, WaitForHandTarget = wait };
            source.Keywords.Clear(); source.Keywords.Add(Keyword.Deployment);
            source.Attack = 2; source.Defense = source.MaxDefense = 5; source.KreditCost = 0;
            var target = state.CreateWithId(PlainUnit, side, kind == 1 ? 0 : kind == 2 ? -7 : 70, side.HqOf(), 2);
            if (kind == 3) state.Remove(target);
            CardInstance? expected = kind == 4 ? target : null;
            int effects = 0; bool wrongTarget = false;
            CardEffectScripts.Register(name, ctx => { effects++; wrongTarget |= !ReferenceEquals(ctx.Target, expected); });
            bool played;
            try { played = engine.PlayCard(source, kind == 0 ? null : target); }
            finally { CardEffectScripts.Unregister(name); }
            bool zeroId = kind <= 1;
            int expectedEffects = zeroId && !wait ? 2 : 1;
            if (!played || wrongTarget || effects != expectedEffects || source.ExtraPlayTriggers != (zeroId && wait ? 1 : 0))
                return $"target ID gate {side}/{wait}/{kind}: effects={effects}/{expectedEffects}, extra={source.ExtraPlayTriggers}, wrongTarget={wrongTarget}";
            cases++;
        }
        return cases == 20 ? null : $"target ID gate cases={cases}";
    }

    private static string? HandPlayTargetRequery(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib";
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool deployment in new[] { false, true })
        foreach (bool pincer in new[] { false, true })
        foreach (int mutation in Enumerable.Range(0, 8))
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 7; state.ActiveSide = side;
            state.SetMaxKredits(side, 10); state.SetKredits(side, 10);
            var source = state.CreateWithId(name, side, 60, side.HandOf(), 0);
            source.Definition = new CardDefinition { Name = name, Type = "infantry", Attack = 2, Defense = 5 };
            source.Keywords.Clear(); source.Attack = 2; source.Defense = source.MaxDefense = 5; source.KreditCost = 0;
            if (deployment) source.Keywords.Add(Keyword.Deployment);
            if (pincer) source.Keywords.Add(Keyword.Pincer);
            int id = mutation == 4 ? 0 : mutation == 5 ? -7 : 70;
            var original = state.CreateWithId(PlainUnit, side, id, side.HqOf(), 1);
            CardInstance? requested = mutation == 7 ? null : mutation == 3
                ? new CardInstance { CardId = id, Name = original.Name, Owner = side, OriginalOwner = side,
                    Definition = original.Definition, Attack = 2, Defense = 5, MaxDefense = 5 } : original;
            CardInstance? expectedOwn = mutation is 4 or 5 or 6 or 7 ? null : original;
            CardInstance? expectedPincer = null;
            var rewrite = state.CreateWithId(PlainUnit, side, 73, CardLocation.Discard, 1);
            bool movedOnce = false; int effects = 0; string? failure = null;
            var moved = state.CardMoved;
            state.CardMoved = (card, oldLocation, newLocation, ownerChange, reason) => {
                moved?.Invoke(card, oldLocation, newLocation, ownerChange, reason);
                if (card != source || oldLocation != side.HandOf() || newLocation != side.HqOf()) return;
                movedOnce = true; source.CurrentTarget = rewrite;
                if (mutation is 1 or 2 or 6)
                {
                    state.Remove(original);
                    expectedOwn = mutation == 2 ? state.CreateWithId(PlainUnit, side, id, side.HqOf(), 1) : null;
                }
            };
            // Controlled callback replaces the ID map twice: movement -> own
            // effect, then own effect -> Pincer. It is not a real-card claim.
            CardEffectScripts.Register(name, ctx => {
                effects++;
                if (!ReferenceEquals(ctx.Target, expectedOwn)) failure = "自身效果未按ID重新读取目标";
                if (source.CustomJson.ContainsKey("pincer_receiver")) failure = "Pincer早于自身效果";
                if (expectedOwn is not null)
                {
                    state.Remove(expectedOwn);
                    expectedPincer = state.CreateWithId(PlainUnit, side, id, side.HqOf(), 1);
                }
            });
            bool played;
            try { played = engine.PlayCard(source, requested); }
            finally { CardEffectScripts.Unregister(name); }
            bool linked = source.CustomJson.ContainsKey("pincer_receiver");
            bool expectedLinked = pincer && expectedPincer is not null;
            if (!played || !movedOnce || effects != 1 || failure is not null
                || !ReferenceEquals(source.CurrentTarget, rewrite) || linked != expectedLinked
                || expectedLinked && (!expectedPincer!.CustomJson.ContainsKey("pincer_givers")
                    || expectedOwn!.CustomJson.ContainsKey("pincer_givers")))
                return $"target requery case={cases} {side}/{deployment}/{pincer}/{mutation}: {failure ?? "target identity/Pincer timing/currentTarget"}; effects={effects}, linked={linked}/{expectedLinked}";
            cases++;
        }
        return cases == 64 ? null : $"target requery cases={cases}";
    }

    private static string? HandPlayCounterReadsCurrentTarget(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 7; state.ActiveSide = side;
            state.SetMaxKredits(side, 10); state.SetKredits(side, 10);
            // Real BARRAGE and SECRET OPERATIVES IR, with a durable ground
            // target so later BARRAGE damage cannot hide the counter's buff.
            var source = state.CreateWithId("card_event_barrage", side, 60, side.HandOf(), 0);
            source.ChooseOne = Enumerable.Range(0, source.Definition.ChooseOneOptionCount)
                .First(i => source.Definition.ChooseOneSelectTargets[i]);
            var target = state.CreateWithId("card_unit_432_infantry_regiment", side.Opposite(), 70, side.Opposite().HqOf(), 1);
            target.Definition = new CardDefinition { Name = target.Name, Type = "infantry", Attack = 2, Defense = 20 };
            target.Keywords.Clear(); target.Attack = 2; target.Defense = target.MaxDefense = 20;
            var counter = state.CreateWithId("card_event_secret_operatives", side.Opposite(), 80, side.Opposite().HandOf(), 0);
            counter.GotchaActivated = 1;
            bool played = engine.PlayCard(source, target);
            int defenseBuff = target.BuffsBySource.GetValueOrDefault((counter.CardId, false))?.Defense ?? 0;
            if (!played || counter.GotchaActivated != 0 || counter.Location != CardLocation.Discard || defenseBuff != 2)
                return $"counter target {side}: played={played}, active={counter.GotchaActivated}, defense buff={defenseBuff}/2";
        }
        return null;
    }

    private static string? QueuedAutoPlayActionReceipts(CardDatabase db)
    {
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool initiallyLimited in new[] { false, true })
        foreach (int queueMutation in new[] { 0, 1, 2 })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 7; state.ActiveSide = side;
            state.StopAttack = true; state.StopFurtherActions = true;
            if (initiallyLimited) state.FrontlineLimiters.Add(777);
            var first = state.CreateWithId("card_unit_432_infantry_regiment", side, 60, side.HandOf(), 0);
            var second = state.CreateWithId(first.Name, side, 61, side.HandOf(), 1);
            foreach (var card in new[] { first, second })
            {
                card.Definition = new CardDefinition { Name = card.Name, Type = "infantry", Attack = 2, Defense = 5,
                    ChooseOneOptionCount = card == second ? 2 : 0 };
                card.Keywords.Clear(); card.Attack = 2; card.Defense = card.MaxDefense = 5; card.KreditCost = 0;
                card.ChooseOne = 1; // Only second has choices; first must omit the field.
            }
            state.AddAutoPlayCards(first.CardId);
            if (queueMutation == 0) state.AddAutoPlayCards(second.CardId);
            int seenFirst = 0, seenSecond = 0, admitted = 0; string? failure = null;
            var moved = state.CardMoved;
            state.CardMoved = (card, oldLocation, newLocation, ownerChange, reason) => {
                moved?.Invoke(card, oldLocation, newLocation, ownerChange, reason);
                if (newLocation != side.HqOf() || oldLocation != side.HandOf() || card != first && card != second) return;
                bool isFirst = card == first;
                if (isFirst) seenFirst++; else seenSecond++;
                bool expected = isFirst ? initiallyLimited : !initiallyLimited;
                if (state.IsFrontlineLimited != expected) failure = "下一张未看到上一张的接收结果";
                if (state.StopAttack || state.StopFurtherActions) failure = "独立动作开始未清理停止标志";
                var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
                engine.Api.InvokeByName("ChangeFrontlineLimiter", card, new object?[] { 777, expected }, ctx, out _);
                if (state.IsFrontlineLimited != expected) failure = "当前张的通知提前应用";
                if (isFirst && queueMutation != 0)
                {
                    if (queueMutation == 2) state.ClearAutoPlayCards();
                    state.AddAutoPlayCards(second.CardId);
                }
                if (isFirst) { state.StopAttack = true; state.StopFurtherActions = true; }
                if (!isFirst)
                {
                    var result = engine.Api.InvokeByName("SpawnMultipleCardsOnBattlefield", card,
                        new object?[] { (int)side, true, Enumerable.Repeat("card_unit_typhoon_mk_ib", 4).ToList(), card.CardId, false, null, false }, ctx, out _);
                    admitted = result is List<int> ids ? ids.Count : -1;
                }
            };
            engine.ExecuteQueuedAutoPlayActions();
            bool skippedSecond = queueMutation == 2;
            var actions = state.ActionLog.Where(x => x.ActionType == "XActionPlayCardFromHand").ToArray();
            var expectedIds = skippedSecond ? new[] { 60 } : new[] { 60, 61 };
            var notices = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionPlayCardFromHand").ToArray();
            if (failure is not null || seenFirst != 1 || seenSecond != (skippedSecond ? 0 : 1)
                || state.IsFrontlineLimited != (skippedSecond ? !initiallyLimited : initiallyLimited)
                || state.GetAutoPlayCards().Length != 0 || second.Location != (skippedSecond ? side.HandOf() : side.HqOf())
                || !actions.Select(x => Convert.ToInt32(x.ActionData["cardID"])).SequenceEqual(expectedIds)
                || actions.Any(x => Convert.ToInt32(x.ActionData["location"]) != 8)
                || notices.Length != expectedIds.Length
                || notices[0].Values.Any(x => x.Name == "chooseOneIndex")
                || !skippedSecond && (!notices[1].Values.Contains(ActionValue2.Int("chooseOneIndex", 1)) || admitted != (initiallyLimited ? 4 : 2)))
                return $"queued autoplay case={cases} {side}/{initiallyLimited}/{queueMutation}: {failure ?? "queue/receipt/action"}, first={seenFirst}, second={seenSecond}, admitted={admitted}";
            int logCount = state.ActionLog.Count;
            engine.ExecuteQueuedAutoPlayActions();
            if (state.ActionLog.Count != logCount) return "空独立自动出牌队列产生了新动作";
            cases++;
        }
        return cases == 12 ? null : $"queued autoplay cases={cases}";
    }

    private static string? QueuedAutoPlayGotchaReceiptOrder(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool active in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); state.Turn = 7; state.ActiveSide = side;
            state.SetMaxKredits(side, 10); state.SetKredits(side, 10);
            var gotcha = state.CreateWithId("card_event_interception", side, 60, side.HandOf(), 0);
            gotcha.GotchaActivated = active ? 3 : 0;
            engine.Api.JsonSetInt(gotcha, "kreditsPayed", 2);
            var next = state.CreateWithId("card_unit_432_infantry_regiment", side, 61, side.HandOf(), 1);
            next.Definition = new CardDefinition { Name = next.Name, Type = "infantry", Attack = 2, Defense = 5 };
            next.Keywords.Clear(); next.KreditCost = 0;
            state.AddAutoPlayCards(gotcha.CardId); state.AddAutoPlayCards(next.CardId);
            bool reachedNext = false; string? failure = null;
            var moved = state.CardMoved;
            state.CardMoved = (card, oldLocation, newLocation, ownerChange, reason) => {
                moved?.Invoke(card, oldLocation, newLocation, ownerChange, reason);
                if (card == next && newLocation == side.HqOf())
                {
                    reachedNext = true;
                    if (gotcha.GotchaActivated != (active ? 0 : 1)) failure = "上一张Gotcha尚未接收";
                }
            };
            engine.ExecuteQueuedAutoPlayActions();
            if (!reachedNext || failure is not null || gotcha.Location != side.HandOf()
                || gotcha.GotchaActivated != (active ? 0 : 1) || state.GetAutoPlayCards().Length != 0)
                return $"queued Gotcha {side}/{active}: {failure ?? "queue/receipt"}";
        }
        return null;
    }

    private static string? AutoPlaySelectionBeforeExtra(CardDatabase db)
    {
