            else completed = engine.Attack(state.Hq(Side.Left), state.Hq(Side.Right));
            if (completed || resistance.Location != CardLocation.HandLeft || !state.GetAutoPlayCards().SequenceEqual(new[] { 60 }))
                return "被本地合法性检查拒绝的行动不应消费待执行队列";
