            engine.ExecuteAutoPlayCards();
            var plays = state.CardsPlayedThisTurn.Where(x => x.Name == first.Name).Select(x => x.CardId).ToArray();
            if (first.Location != CardLocation.Discard || second.Location != CardLocation.Discard
                || last.Location != side.HandOf() || state.GetAutoPlayCards().Length != 0
                || state.HqDefense(side) != hp - 2 || state.Kredits(side) != 3 || unit.PinnedTurns <= 0
                || !plays.SequenceEqual(new[] { 70, 60 }))
                return $"RESISTANCE连锁消费错误：方={side} HQ={state.HqDefense(side)} 指挥点={state.Kredits(side)} 次数={plays.Length}";
        }
        return null;
    }

    private static string? AutoPlayConsumerGate(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool tagged in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 2;
            state.SetMaxKredits(side, 10);
            state.SetKredits(side, 10);
            var hand = state.CreateWithId("card_unit_432_infantry_regiment", side, 60, side.HandOf(), 0);
            var deck = state.CreateWithId(hand.Name, side, 61, side.DeckOf(), 0);
            var discarded = state.CreateWithId(hand.Name, side, 62, CardLocation.Discard, 0);
            if (tagged) engine.Api.AddCustomGameplayTag(hand, "autoplay");
            int cost = hand.KreditCost;
            foreach (int id in new[] { 9999, deck.CardId, hand.CardId, discarded.CardId }) state.AddAutoPlayCards(id);
            engine.ExecuteAutoPlayCards();
            if (!hand.Location.IsBoard() || deck.Location != side.DeckOf() || discarded.Location != CardLocation.Discard
                || state.GetAutoPlayCards().Length != 0 || state.Kredits(side) != 10 - (tagged ? 0 : cost))
                return $"自动打出消费位置/费用门错误：方={side} 标签={tagged}";
            engine.ExecuteAutoPlayCards(); // Empty queue is a no-op.
            if (state.Kredits(side) != 10 - (tagged ? 0 : cost)) return "空自动打出队列重复执行扣费";
        }
        return null;
    }

    private static string? DrawAutoPlayQueue(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int route in new[] { 0, 1, 2 })
        foreach (bool full in new[] { false, true })
        foreach (int tagMode in new[] { 0, 1, 2, 3 })
        {
            var (engine, state) = EmptyBoard(db);
            Side recipient = route == 1 ? side.Opposite() : side;
            if (full)
                for (int i = 0; i < GameState.HandCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", recipient, 100 + i, recipient.HandOf(), i);
            var card = state.CreateWithId(tagMode <= 1 ? "card_event_resistance_new" : "card_unit_432_infantry_regiment",
                side, 60, side.DeckOf(), 0);
            if (tagMode == 1) card.RemovedGameplayTags.Add("autoplay");
            if (tagMode == 3) engine.Api.AddCustomGameplayTag(card, "autoplay");
            if (route == 2) engine.Api.InvokeByName("DrawSpecificCardFromDeckBySide", card,
                new object?[] { 0, card.CardId, (int)side, false },
                new EffectContext { Engine = engine, State = state, Controller = side }, out _);
            else engine.DrawCard(side, opponentDraw: route == 1);
            int[] expected = !full && tagMode is 0 or 3 ? new[] { 60 } : Array.Empty<int>();
            if (!state.GetAutoPlayCards().SequenceEqual(expected))
                return $"自动打出入队错误：方={side} 路径={route} 满手={full} 标签={tagMode}";
        }
        return null;
    }

    private static string? DrawAutoPlayAfterEvents(CardDatabase db)
    {
        foreach (bool initiallyTagged in new[] { false, true })
        foreach (bool leaveHand in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            string name = initiallyTagged ? "card_event_resistance_new" : "card_unit_51e_regiment";
            var card = state.CreateWithId(name, Side.Left, 30, CardLocation.DeckLeft, 0);
            bool callback = false;
            using var probe = InstallDrawReentryProbe(state, () =>
            {
                callback = true;
                if (initiallyTagged) card.RemovedGameplayTags.Add("autoplay");
                else engine.Api.AddCustomGameplayTag(card, "autoplay");
                if (leaveHand) state.Move(card, CardLocation.Discard, notifyMoved: false);
            }, name);
            engine.DrawCard(Side.Left);
            if (!callback || !state.GetAutoPlayCards().SequenceEqual(initiallyTagged ? Array.Empty<int>() : new[] { 30 }))
                return $"自动打出应读取事件后的标签且不加位置门：原标签={initiallyTagged} 离手={leaveHand}";
        }
        {
            var (_, state) = EmptyBoard(db);
            foreach (int id in new[] { 9, 2, 9, 0, -7, 2 }) state.AddAutoPlayCards(id);
            var copied = state.GetAutoPlayCards();
            var snapshot = state.Snapshot();
            copied[0] = 888;
            if (!state.GetAutoPlayCards().SequenceEqual(new[] { 9, 2, 0, -7 })
                || !snapshot.AutoPlayerCardIds.SequenceEqual(new[] { 9, 2, 0, -7 }))
                return "自动打出队列应保首次插入顺序、去重且返回副本，不自行过滤ID";
            state.ClearAutoPlayCards();
            state.AddAutoPlayCards(2);
            if (!state.GetAutoPlayCards().SequenceEqual(new[] { 2 }) || snapshot.AutoPlayerCardIds.Length != 4)
                return "清空队列不应改写历史快照，清空后ID应可重新入队";
        }
        return null;
    }

    private static string? DrawWithoutLocationMoved(CardDatabase db)
    {
        foreach (Side deckSide in new[] { Side.Left, Side.Right })
        foreach (int route in new[] { 0, 1, 2 })
        foreach (bool full in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            Side recipient = route == 1 ? deckSide.Opposite() : deckSide;
            state.CreateWithId("card_unit_spitfire_mk_ii", deckSide, 20, deckSide.HqOf(), 1);
            if (full)
                for (int i = 0; i < GameState.HandCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", recipient, 100 + i, recipient.HandOf(), i);
            var card = state.CreateWithId("card_unit_13e_dragons", deckSide, 60, deckSide.DeckOf(), 0);
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            var moved = state.CardMoved;
            int notifications = 0;
            state.CardMoved = (c, oldLocation, newLocation, ownerChange, reason) =>
            {
                if (c == card) notifications++;
                moved?.Invoke(c, oldLocation, newLocation, ownerChange, reason);
            };
            if (route == 2) engine.Api.InvokeByName("DrawSpecificCardFromDeckBySide", card,
                new object?[] { 0, card.CardId, (int)deckSide, false },
                new EffectContext { Engine = engine, State = state, Controller = deckSide }, out _);
            else engine.DrawCard(deckSide, opponentDraw: route == 1);
            bool ownDraw = trace.Any(x => x.StartsWith("OnCardDrawnFromDeck →", StringComparison.Ordinal));
            if (notifications != 0 || ownDraw == full
                || trace.Any(x => x.StartsWith("OnCardLocationMoved →", StringComparison.Ordinal)
                    || x.StartsWith("OnOtherCardLocationMoved →", StringComparison.Ordinal)))
                return $"抽牌误发位置事件或漏自身抽牌：方={deckSide} 路径={route} 满手={full} 通知={notifications}";
            // Positive control: a genuine subsequent zone move still dispatches T47.
            trace.Clear();
            state.Move(card, CardLocation.NotAvailable);
            if (notifications != 1 || !trace.Any(x => x.StartsWith("OnOtherCardLocationMoved → card_unit_spitfire_mk_ii#20", StringComparison.Ordinal)))
                return "位置事件正向对照未触发，不能证明抽牌路径的事件隔离";
        }
        return null;
    }

    private static string? InitialScryLiveFiltering(CardDatabase db)
    {
        const string name = "card_unit_41st_infantry_regiment", filter = "FilterCardsToScry", marker = "card_unit_routed_troops";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(filter)) return "无法安装候选展示重入探针";
        locals[filter] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Math = "BooleanAND", Args = new[] {
                new KismetExpr { Var = "_auditOfferValid", Context = new KismetExpr { Var = "card" } },
                new KismetExpr { Var = "_auditOfferAllow", Scope = "instance" }
            } }, null, -1, "isValid", null) { DestinationScope = "local" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "cardID", Context = new KismetExpr { Var = "card" } }, null, -1, "_auditOfferCurrent", null) { DestinationScope = "instance" },
            new KismetStep(2, "call", "SpawnCardInHandBySide", new[] { new KismetExpr { Int = (int)Side.Right },
                new KismetExpr { Str = marker }, new KismetExpr { Int = 30 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool full in new[] { false, true })
            foreach (int mode in Enumerable.Range(0, 8))
            {
                var (engine, state) = EmptyBoard(db);
                var original = state.CreateWithId(name, side, 30, CardLocation.Discard, 0);
                original.BlueprintVariables["_auditOfferAllow"] = true;
                if (full) for (int i = 0; i < 9; i++) state.CreateWithId(PlainUnit, side, 100 + i, side.HandOf(), i);
                for (int i = 0; i < (mode == 0 ? 2 : 6); i++) state.CreateWithId(PlainUnit, side, 60 + i, side.DeckOf(), i * 4)
                    .BlueprintVariables["_auditOfferValid"] = mode == 0 ? i != 1 : mode == 1 ? i is not (2 or 3) : mode == 4 ? i != 1 : true;
                if (mode == 5) for (int i = 0; i < 6; i++) state.CreateWithId(PlainUnit, side.Opposite(), 70 + i, side.Opposite().DeckOf(), i * 4)
                    .BlueprintVariables["_auditOfferValid"] = true;
                var visits = new List<int>(); bool mutated = false; CardInstance? replacement = null;
                state.CardCreated += card => {
                    if (card.Name != marker) return;
                    card.Location = CardLocation.Discard;
                    var receiver = state.ById(30)!;
                    int current = Convert.ToInt32(receiver.BlueprintVariables["_auditOfferCurrent"]); visits.Add(current);
                    if (mutated || current != (mode == 6 ? 60 : 61) || mode == 7) return;
                    mutated = true;
                    if (mode == 0) for (int i = 0; i < 2; i++) state.CreateWithId(PlainUnit, side, 62 + i, side.DeckOf(), 20 + i)
                        .BlueprintVariables["_auditOfferValid"] = true;
                    if (mode == 1) { state.ById(64)!.Location = CardLocation.Discard; state.ById(65)!.Location = CardLocation.Discard; }
                    if (mode == 2) { var a = state.ById(61)!; var b = state.ById(62)!; (a.LocationNumber, b.LocationNumber) = (b.LocationNumber, a.LocationNumber); }
                    if (mode == 3) { state.ById(61)!.Location = CardLocation.Discard; state.CreateWithId(PlainUnit, side, 90, side.DeckOf(), 4).BlueprintVariables["_auditOfferValid"] = false; }
                    if (mode == 4) foreach (var item in state.Deck(side).Where(x => x.CardId != 60)) item.Location = CardLocation.Discard;
                    if (mode == 5) state.ChangeOwner(original, side.Opposite(), normalize: false);
                    if (mode == 6) { state.Remove(original); replacement = state.CreateWithId(name, side, 30, CardLocation.Discard, 0); replacement.BlueprintVariables["_auditOfferAllow"] = false; }
                };
                int[] expectedVisits = mode switch {
                    0 => new[] { 60, 61, 62, 63 }, 1 => new[] { 60, 61, 62, 63 }, 2 => new[] { 60, 61, 61 },
                    5 => new[] { 60, 61, 72 }, 6 => new[] { 60, 61, 62, 63, 64, 65 },
                    4 => new[] { 60, 61 }, _ => new[] { 60, 61, 62 },
                };
                int[] expectedOffers = mode switch {
                    0 => new[] { 60, 62, 63 }, 1 => new[] { 60, 61 }, 2 => new[] { 60, 62, 61 },
                    3 => new[] { 60, 90, 62 }, 5 => new[] { 60, 71, 72 }, 4 or 6 => new[] { 60 }, _ => new[] { 60, 61, 62 },
                };
                var offered = new List<int>(); int replies = 0;
                engine.ChooseSpawnCard = (_, cards) => { replies++; offered.AddRange(cards.Select(x => x.CardId)); return null; };
                engine.Api.InvokeByName("selectCardToDraw", original, new object?[] { 30, true, false, null },
                    new EffectContext { Engine = engine, State = state, Self = original, Controller = side }, out _);
                var draws = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionDrawCardFromDeck").ToArray();
                bool singleton = expectedOffers.Length == 1;
                if (!visits.SequenceEqual(expectedVisits) || replies != (singleton ? 0 : 1)
                    || !singleton && !offered.SequenceEqual(expectedOffers) || draws.Length != (singleton ? 1 : 0)
                    || singleton && (draws[0].Values.First(x => x.Name == "instigatorID").Value != 30
                        || state.ById(60)!.Location != (full ? CardLocation.Discard : side.HandOf()))
                    || state.UnimplementedCalls.Keys.Any(x => x.StartsWith("<selectCardToDraw:", StringComparison.Ordinal)))
                    return $"初次候选重入错误：{side}/full={full}/mode={mode}/visits={string.Join(",", visits)}/offers={string.Join(",", offered)}";
            }
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool removeReceiver in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, side, 30, CardLocation.Discard, 0); source.BlueprintVariables["_auditOfferAllow"] = true;
                for (int i = 0; i < 4; i++) state.CreateWithId(PlainUnit, side, 60 + i, side.DeckOf(), i).BlueprintVariables["_auditOfferValid"] = true;
                state.CardCreated += card => { if (card.Name != marker) return; card.Location = CardLocation.Discard;
                    if (removeReceiver) state.Remove(source); else foreach (var item in state.Deck(side)) item.Location = CardLocation.Discard;
                };
                int replies = 0; engine.ChooseSpawnCard = (_, _) => { replies++; return null; };
                engine.Api.InvokeByName("selectCardToDraw", source, new object?[] { 30, true, false, null },
                    new EffectContext { Engine = engine, State = state, Self = source, Controller = side }, out _);
                string gap = removeReceiver ? "<selectCardToDraw:missing-filter-receiver>" : "<selectCardToDraw:post-filter-index-object-output>";
                if (state.UnimplementedCalls.GetValueOrDefault(gap) != 1 || replies != 0
                    || state.ActionLog.SelectMany(x => x.SubActions).Any(x => x.Name == "ZActionDrawCardFromDeck"))
                    return "不可表示的展示回调缺口应明确记账，不能伪造空候选完成";
            }
            return null;
        }
        finally { locals.Remove(filter); }
    }

    private static string? MultiScryLiveFiltering(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib", filter = "FilterCardsToScry", marker = "card_unit_routed_troops";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(filter)) return "无法安装实时牌库过滤探针";
        locals[filter] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "_auditLiveScryValid", Context = new KismetExpr { Var = "card" } }, null, -1, "isValid", null) { DestinationScope = "local" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "cardID", Context = new KismetExpr { Var = "card" } }, null, -1, "_auditLiveScryCurrent", null) { DestinationScope = "instance" },
            new KismetStep(2, "call", "SpawnCardInHandBySide", new[] { new KismetExpr { Int = (int)Side.Right },
                new KismetExpr { Str = marker }, new KismetExpr { Int = 30 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool full in new[] { false, true })
            foreach (int triggerIndex in new[] { 1, 4 })
            foreach (bool predicate in new[] { false, true })
            foreach (int mutation in Enumerable.Range(0, 4))
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, side, 30, CardLocation.Discard, 0);
                if (full) for (int i = 0; i < 9; i++) state.CreateWithId(PlainUnit, side, 100 + i, side.HandOf(), i);
                var flags = Enumerable.Range(60, 6).ToDictionary(id => id, _ => true);
                int triggerId = 60 + triggerIndex; flags[triggerId] = predicate; flags[90] = !predicate;
                for (int i = 0; i < 6; i++) state.CreateWithId(PlainUnit, side, 60 + i, side.DeckOf(), i * 4)
                    .BlueprintVariables["_auditLiveScryValid"] = flags[60 + i];
                var expectedPhysical = Enumerable.Range(60, 6).ToList();
                if (mutation == 0) { expectedPhysical.Add(90); flags[90] = true; }
                if (mutation == 1) expectedPhysical.Remove(65);
                if (mutation == 2) (expectedPhysical[triggerIndex], expectedPhysical[triggerIndex + 1]) = (expectedPhysical[triggerIndex + 1], expectedPhysical[triggerIndex]);
                if (mutation == 3) expectedPhysical[triggerIndex] = 90;
                var expectedVisits = expectedPhysical.ToArray(); expectedVisits[triggerIndex] = triggerId;
                var expected = new List<int>(); int accepted = 0;
                for (int i = 0; i < expectedPhysical.Count; i++)
                {
                    bool valid = i == triggerIndex ? predicate : flags[expectedVisits[i]];
                    if (valid && accepted < 3) expected.Insert(accepted++, expectedPhysical[i]); else expected.Add(expectedPhysical[i]);
                }
                var displaced = expected.Take(3).Where(id => id != 60).ToArray();
                foreach (int id in displaced) { expected.Remove(id); expected.Add(id); }
                bool mutated = false; var visited = new List<int>();
                state.CardCreated += card => {
                    if (card.Name != marker) return;
                    card.Location = CardLocation.Discard;
                    int current = Convert.ToInt32(source.BlueprintVariables["_auditLiveScryCurrent"]); visited.Add(current);
                    if (current != triggerId || mutated) return;
                    mutated = true;
                    if (mutation == 0) state.CreateWithId(PlainUnit, side, 90, side.DeckOf(), 100).BlueprintVariables["_auditLiveScryValid"] = true;
                    if (mutation == 1) state.ById(65)!.Location = CardLocation.Discard;
                    if (mutation == 2) { var a = state.ById(triggerId)!; var b = state.ById(triggerId + 1)!; (a.LocationNumber, b.LocationNumber) = (b.LocationNumber, a.LocationNumber); }
                    if (mutation == 3) {
                        int number = state.ById(triggerId)!.LocationNumber; state.ById(triggerId)!.Location = CardLocation.Discard;
                        state.CreateWithId(PlainUnit, side, 90, side.DeckOf(), number).BlueprintVariables["_auditLiveScryValid"] = !predicate;
                    }
                };
                var chosen = state.ById(60)!;
                engine.Api.DrawChosenCardToHand(source, chosen);
                var receipt = state.ActionLog.SelectMany(x => x.SubActions).SingleOrDefault(x => x.Name == "ZActionNewDeck");
                if (!mutated || !visited.SequenceEqual(expectedVisits) || receipt?.Values.First(x => x.Name == "cards").Text != string.Join(";", expected)
                    || !state.Deck(side).Select(x => x.CardId).SequenceEqual(expected.Skip(1))
                    || chosen.Location != (full ? CardLocation.Discard : side.HandOf())
                    || state.UnimplementedCalls.Keys.Any(x => x.StartsWith("<ExecuteScryingEffectBySide:", StringComparison.Ordinal)))
                    return $"过滤实时重入错误：{side}/{full}/index={triggerIndex}/valid={predicate}/mutation={mutation}/visits={string.Join(",", visited)}";
            }
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int mode in new[] { 0, 1 })
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, side, 30, CardLocation.Discard, 0);
                for (int i = 0; i < 4; i++) state.CreateWithId(PlainUnit, side, 60 + i, side.DeckOf(), i)
                    .BlueprintVariables["_auditLiveScryValid"] = true;
                bool changed = false;
                state.CardCreated += card => {
                    if (card.Name != marker) return;
                    card.Location = CardLocation.Discard;
                    int current = Convert.ToInt32(source.BlueprintVariables["_auditLiveScryCurrent"]);
                    if (changed || current != (mode == 0 ? 60 : 61)) return;
                    changed = true;
                    if (mode == 0) foreach (var item in state.Deck(side)) item.Location = CardLocation.Discard;
                    else state.ById(60)!.Location = CardLocation.Discard;
                };
                var result = engine.Api.DrawChosenCardToHand(source, state.ById(60));
                string gap = mode == 0 ? "<ExecuteScryingEffectBySide:post-filter-index-default-ID>" : "<ExecuteScryingEffectBySide:independent-ID-array-required>";
                if (!changed || result is not null || state.UnimplementedCalls.GetValueOrDefault(gap) != 1
                    || state.ActionLog.SelectMany(x => x.SubActions).Any(x => x.Name is "ZActionNewDeck" or "ZActionDrawCardFromDeck"))
                    return $"不可表示的原生牌库状态未明确记账：{side}/mode={mode}";
            }
            return null;
        }
        finally { locals.Remove(filter); }
    }

    private static string? MultiScryReplyContract(CardDatabase db)
    {
        const string name = "card_unit_51e_regiment", filter = "FilterCardsToScry", selected = "OnHandTargetSelected";
        const string watcherName = "card_unit_m36_destroyer", changed = "OnAfterDeckChanged", marker = "card_unit_routed_troops";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.Find(watcherName)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> watcherLocals
            || locals.ContainsKey(filter) || locals.ContainsKey(selected) || watcherLocals.ContainsKey(changed)) return "无法安装多候选回复探针";
        KismetStep Store(int index, string variable, string field) => new(index, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
            new KismetExpr { Var = variable }, null, -1, field, null) { DestinationScope = "instance" };
        locals[filter] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Math = "Add_IntInt", Args = new[] {
                new KismetExpr { Var = "_auditScryCalls", Scope = "instance" }, new KismetExpr { Int = 1 }
            } }, null, -1, "_auditScryCalls", null) { DestinationScope = "instance" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "_auditScryValid", Context = new KismetExpr { Var = "card" } }, null, -1, "isValid", null) { DestinationScope = "local" },
            new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        locals[selected] = new[] { Store(0, "K2Node_Event_handTargetCardID", "_auditScryTarget"), Store(1, "K2Node_Event_instigatorID", "_auditScryInstigator"),
            new KismetStep(2, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = "location", Context = new KismetExpr {
                Call = "GetCardFromID", Args = new[] { new KismetExpr { Var = "K2Node_Event_handTargetCardID" } }
            } }, null, -1, "_auditScryLocation", null) { DestinationScope = "instance" },
            new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        watcherLocals[changed] = new[] {
            new KismetStep(0, "call", "SpawnCardInHandBySide", new[] { new KismetExpr { Int = (int)Side.Right },
                new KismetExpr { Str = marker }, new KismetExpr { Int = 30 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            var patterns = new[] { new[] { 60, 61, 62 }, new[] { 61, 63, 65 }, new[] { 61, 64 }, new[] { 64, 65 } };
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool full in new[] { false, true })
            foreach (bool unavailable in new[] { false, true })
            foreach (bool suppressed in new[] { false, true })
            foreach (var valid in patterns)
            foreach (int chosenId in valid)
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, side, 30, unavailable ? CardLocation.NotAvailable : CardLocation.Discard, 0);
                source.BlueprintVariables["_auditScryCalls"] = 0;
                if (suppressed) source.Keywords.Add(Keyword.Suppressed);
                if (full) for (int i = 0; i < 9; i++) state.CreateWithId(PlainUnit, side, 100 + i, side.HandOf(), i);
                for (int i = 0; i < 6; i++) state.CreateWithId(PlainUnit, side, 60 + i, side.DeckOf(), i * 4 + 2)
                    .BlueprintVariables["_auditScryValid"] = valid.Contains(60 + i);
                // Independent imperative oracle follows Insert, then Remove/Add.
                var expected = new List<int>(); int accepted = 0;
                foreach (int id in Enumerable.Range(60, 6)) { if (valid.Contains(id) && accepted < 3) expected.Insert(accepted++, id); else expected.Add(id); }
                var moved = expected.Take(3).Where(id => id != chosenId).ToArray();
                foreach (int id in moved) { expected.Remove(id); expected.Add(id); }
                var chosen = state.ById(chosenId)!;
                engine.Api.DrawChosenCardToHand(source, chosen);
                var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
                var receipt = actions.SingleOrDefault(x => x.Name == "ZActionNewDeck");
                var draw = actions.SingleOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
                if (!state.Deck(side).Select(x => x.CardId).SequenceEqual(expected.Skip(1))
                    || receipt is null || !receipt.Values.Select(x => x.Name).SequenceEqual(new[] { "side", "cards", "spawnCards" })
                    || receipt.Values[0].Text != side.ToWire() || receipt.Values[1].Text != string.Join(";", expected) || receipt.Values[2].Text != ""
                    || draw is null || Array.IndexOf(actions, receipt) >= Array.IndexOf(actions, draw)
                    || draw.Values.First(x => x.Name == "instigatorID").Value != 0
                    || chosen.Location != (full ? CardLocation.Discard : side.HandOf())
                    || !Equals(source.BlueprintVariables.GetValueOrDefault("_auditScryTarget"), chosenId)
                    || !Equals(source.BlueprintVariables.GetValueOrDefault("_auditScryInstigator"), 30)
                    || Convert.ToInt32(source.BlueprintVariables.GetValueOrDefault("_auditScryLocation") ?? -1) != (int)chosen.Location
                    || Convert.ToInt32(source.BlueprintVariables["_auditScryCalls"]) != 6 || state.Random.ConsumedCount != 0)
                    return $"多候选移底/通知/回调错误：{side}/{full}/{unavailable}/{suppressed}/valid={string.Join(",", valid)}/chosen={chosenId}";
            }
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int mode in Enumerable.Range(0, 4))
            {
                var (engine, state) = EmptyBoard(db);
                var source = state.CreateWithId(name, side, 30, CardLocation.Discard, 0);
                source.BlueprintVariables["_auditScryCalls"] = 0;
                var watcher = state.CreateWithId(watcherName, side, 20, CardLocation.Discard, 0);
                watcher.Definition = new CardDefinition { Name = watcherName, Type = "infantry", UsedTriggers = new[] { changed } };
                for (int i = 0; i < 4; i++) state.CreateWithId(PlainUnit, side, 60 + i, side.DeckOf(), i).BlueprintVariables["_auditScryValid"] = true;
                CardInstance? replacement = null; int callbacks = 0; bool order = true;
                state.CardCreated += card => {
                    if (card.Name != marker) return;
                    callbacks++; card.Location = CardLocation.Discard;
                    var actions = state.ActionLog.SelectMany(x => x.SubActions).ToArray();
                    order &= actions.Count(x => x.Name == "ZActionNewDeck") == 1 && !actions.Any(x => x.Name == "ZActionDrawCardFromDeck");
                    if (mode is 1 or 2) state.Remove(source);
                    if (mode == 2) replacement = state.CreateWithId(name, side, 30, CardLocation.NotAvailable, 0);
                    if (mode == 3) source.Location = CardLocation.NotAvailable;
                };
                engine.Api.DrawChosenCardToHand(source, state.ById(61));
                if (!order || callbacks != 1 || !Equals(source.BlueprintVariables.GetValueOrDefault("_auditScryTarget"), 61)
                    || replacement is not null && replacement.BlueprintVariables.ContainsKey("_auditScryTarget"))
                    return $"新牌库/T3/抽牌顺序或原对象回调错误：{side}/mode={mode}/calls={callbacks}";
            }
            return null;
        }
        finally { locals.Remove(filter); locals.Remove(selected); watcherLocals.Remove(changed); }
    }

    private static string? SingletonScryDrawContract(CardDatabase db)
    {
        const string name = "card_unit_m36_destroyer", filter = "FilterCardsToScry", selected = "OnHandTargetSelected", changed = "OnAfterDeckChanged";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || new[] { filter, selected, changed }.Any(locals.ContainsKey)) return "无法安装单候选抽牌探针";
        locals[filter] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Math = "EqualEqual_IntInt", Args = new[] {
                    new KismetExpr { Var = "cardID", Context = new KismetExpr { Var = "card" } }, new KismetExpr { Int = 60 }
                } }, null, -1, "isValid", null) { DestinationScope = "local" },
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        locals[selected] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = "K2Node_Event_handTargetCardID" },
                null, -1, "_auditSingletonTarget", null) { DestinationScope = "instance" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Var = "K2Node_Event_instigatorID" },
                null, -1, "_auditSingletonInstigator", null) { DestinationScope = "instance" },
            new KismetStep(2, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "location", Context = new KismetExpr { Call = "GetCardFromID", Args = new[] { new KismetExpr { Int = 60 } } } },
                null, -1, "_auditSingletonLocation", null) { DestinationScope = "instance" },
            new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        // Same body as the T3 probe in DrawHandCapacityAfterDeckEvents:
        // compiled local programs persist in the test process's library cache.
        locals[changed] = new[] {
            new KismetStep(0, "call", "SpawnCardInHandBySide", new[] {
                new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" }, new KismetExpr { Int = 30 }
            }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool full in new[] { false, true })
            foreach (bool suppressed in new[] { false, true })
            foreach (bool unavailable in new[] { false, true })
            foreach (bool autoplay in new[] { false, true })
            foreach (bool effect in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var selecting = state.CreateWithId(name, side, 30, unavailable ? CardLocation.NotAvailable : CardLocation.Discard, 0);
                selecting.ExtraPlayTriggers = 2;
                if (suppressed) selecting.Keywords.Add(Keyword.Suppressed);
                for (int i = 0; i < (full ? 9 : 8); i++) state.CreateWithId(PlainUnit, side, 100 + i, side.HandOf(), i * 3);
                var first = state.CreateWithId(PlainUnit, side, 61, side.DeckOf(), 2);
                var drawn = state.CreateWithId(PlainUnit, side, 60, side.DeckOf(), 17);
                var last = state.CreateWithId(PlainUnit, side, 62, side.DeckOf(), 29);
                if (autoplay) engine.Api.AddCustomGameplayTag(drawn, "autoplay");
                state.AddAutoPlayCards(0);
                var result = engine.Api.InvokeByName("selectCardToDraw", selecting, new object?[] { 30, true, effect, null },
                    new EffectContext { Engine = engine, State = state, Self = selecting, Controller = side.Opposite() }, out bool handled);
                var action = state.ActionLog.SelectMany(x => x.SubActions).SingleOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
                if (!handled || !Equals(result, 60) || drawn.Location != (full ? CardLocation.Discard : side.HandOf())
                    || drawn.LocationNumber != (full ? 17 : 8) || first.LocationNumber != 2 || last.LocationNumber != 29
                    || !Equals(action?.Values.FirstOrDefault(x => x.Name == "instigatorID")?.Value, 30)
                    || !Equals(action?.Values.FirstOrDefault(x => x.Name == "cardID")?.Value, 60)
                    || !Equals(selecting.BlueprintVariables.GetValueOrDefault("_auditSingletonTarget"), 60)
                    || !Equals(selecting.BlueprintVariables.GetValueOrDefault("_auditSingletonInstigator"), 0)
                    || Convert.ToInt32(selecting.BlueprintVariables.GetValueOrDefault("_auditSingletonLocation") ?? -1) != (int)drawn.Location
                    || selecting.ExtraPlayTriggers != 2 || state.Random.ConsumedCount != 0
                    || !state.GetAutoPlayCards().SequenceEqual(!full && autoplay ? new[] { 0, 60 } : new[] { 0 }))
                    return $"单候选来源/编号/回调/队列错误：{side}/{full}/{suppressed}/{unavailable}/{autoplay}/{effect}";
            }
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int mode in Enumerable.Range(0, 4))
            {
                var (engine, state) = EmptyBoard(db);
                var original = state.CreateWithId(name, side, 30, CardLocation.Discard, 0);
                var watcher = state.CreateWithId(name, side, 20, CardLocation.Discard, 0);
                watcher.Definition = new CardDefinition { Name = name, Type = "infantry", UsedTriggers = new[] { changed } };
                var drawn = state.CreateWithId(PlainUnit, side, 60, side.DeckOf(), 17);
                CardInstance? replacement = null; int callbacks = 0;
                state.CardCreated += card => {
                    if (card.Name != "card_unit_routed_troops") return;
                    callbacks++; card.Location = CardLocation.Discard;
                    if (mode is 1 or 2) state.Remove(original);
                    if (mode == 2) replacement = state.CreateWithId(name, side.Opposite(), 30, CardLocation.NotAvailable, 0);
                    if (mode == 3) { original.Location = CardLocation.NotAvailable; original.Keywords.Add(Keyword.Suppressed); }
                };
                engine.Api.InvokeByName("selectCardToDraw", original, new object?[] { 30, true, false, null },
                    new EffectContext { Engine = engine, State = state, Self = original, Controller = side }, out _);
                if (callbacks != 1 || drawn.Location != side.HandOf()
                    || original.BlueprintVariables.ContainsKey("_auditSingletonTarget") != (mode is 0 or 3)
                    || replacement is not null && !Equals(replacement.BlueprintVariables.GetValueOrDefault("_auditSingletonTarget"), 60))
                    return $"抽后重新解析选择卡错误：{side}/mode={mode}/callbacks={callbacks}";
            }
            return null;
        }
        finally { locals.Remove(filter); locals.Remove(selected); locals.Remove(changed); }
    }

    private static string? SelectionHandCapacityGuard(CardDatabase db)
    {
        const string name = "card_unit_m36_destroyer", function = "GetChooseSpawnCards", field = "_auditSelectionPoolRead";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindLocalProgram(name, function) is not null) return "无法安装选择容量候选查询探针";
        locals[function] = new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), new KismetExpr { Bool = true },
                null, -1, field, null) { DestinationScope = "instance" },
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int quantity in new[] { 8, 9, 10 })
            foreach (int excluded in new[] { 0, 1, 2 })
            foreach (bool oppositeOwner in new[] { false, true })
            foreach (bool fromTop in new[] { false, true })
            foreach (bool effect in new[] { false, true })
            foreach (bool unavailable in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var selecting = state.CreateWithId(name, side, 30, unavailable ? CardLocation.NotAvailable : CardLocation.Discard, 0);
                var decoy = state.CreateWithId(PlainUnit, side.Opposite(), 20, CardLocation.Discard, 0);
                for (int i = 0; i < quantity; i++)
                {
                    var hand = state.CreateWithId(i < excluded && i % 2 == 0 ? "card_event_resistance_new" : PlainUnit,
                        oppositeOwner ? side.Opposite() : side, 100 + i, side.HandOf(), 4 + i * 3);
                    if (i < excluded && i % 2 != 0) engine.Api.AddCustomGameplayTag(hand, "autoplay");
                }
                // The opposite physical hand is independently full. Receiver
                // and Controller point there, but the explicit selecting ID wins.
                for (int i = 0; i < 9; i++) state.CreateWithId(PlainUnit, side.Opposite(), 200 + i, side.Opposite().HandOf(), i);
                var drawn = state.CreateWithId(PlainUnit, side, 60, side.DeckOf(), 7);
                var ctx = new EffectContext { Engine = engine, State = state, Self = selecting, Controller = side.Opposite() };
                int replies = 0;
                engine.ChooseSpawnCard = (_, _) => { replies++; return null; };
                object? result = engine.Api.InvokeByName("selectCardToDraw", decoy,
                    new object?[] { 30, fromTop, effect, null }, ctx, out bool handled);
                bool full = quantity - excluded >= 9;
                bool blocked = !fromTop && !effect && full;
                bool poolRead = selecting.BlueprintVariables.ContainsKey(field);
                var draws = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionDrawCardFromDeck").ToArray();
                if (!handled || poolRead != (!fromTop && !blocked) || replies != 0 || state.Random.ConsumedCount != 0
                    || decoy.BlueprintVariables.ContainsKey(field)
                    || !Equals(result, fromTop ? 60 : 0)
                    || draws.Length != (fromTop ? 1 : 0)
                    || drawn.Location != (!fromTop ? side.DeckOf() : full ? CardLocation.Discard : side.HandOf()))
                    return $"选择守卫分支错误：{side}/{quantity}/{excluded}/{oppositeOwner}/top={fromTop}/effect={effect}/unavailable={unavailable}/pool={poolRead}";
            }
            return null;
        }
        finally { locals.Remove(function); }
    }

    private static string? DrawHandCapacityAutoplay(CardDatabase db)
    {
        foreach (Side deckSide in new[] { Side.Left, Side.Right })
        foreach (int route in Enumerable.Range(0, 3))
        foreach (int quantity in new[] { 0, 8, 9, 10 })
        foreach (int excluded in new[] { 0, 1, 2 })
        foreach (bool oppositeOwner in new[] { false, true })
        foreach (int drawnTag in Enumerable.Range(0, 4))
        {
            if (excluded > quantity) continue;
            var (engine, state) = EmptyBoard(db);
            Side recipient = route == 1 ? deckSide.Opposite() : deckSide;
            for (int i = 0; i < quantity; i++)
            {
                var hand = state.CreateWithId(i < excluded && i % 2 == 0 ? "card_event_resistance_new" : PlainUnit,
                    oppositeOwner ? recipient.Opposite() : recipient, 100 + i, recipient.HandOf(), 5 + i * 3);
                if (i < excluded && i % 2 != 0) engine.Api.AddCustomGameplayTag(hand, "autoplay");
            }
            string name = drawnTag is 1 or 2 ? "card_event_resistance_new" : PlainUnit;
            var first = state.CreateWithId(route == 2 ? PlainUnit : name, deckSide, 60, deckSide.DeckOf(), 7);
            var second = state.CreateWithId(route == 2 ? name : PlainUnit, deckSide, 61, deckSide.DeckOf(), 17);
            var drawn = route == 2 ? second : first;
            if (drawnTag == 2) drawn.RemovedGameplayTags.Add("autoplay");
            if (drawnTag == 3) engine.Api.AddCustomGameplayTag(drawn, "autoplay");
            object? result = route == 2 ? engine.Api.InvokeByName("DrawSpecificCardFromDeckBySide", drawn,
                new object?[] { 30, drawn.CardId, (int)deckSide, false },
                new EffectContext { Engine = engine, State = state, Controller = recipient.Opposite() }, out _)
                : engine.DrawCard(deckSide, instigatorId: 30, opponentDraw: route == 1);
            int expectedCount = quantity - excluded;
            bool full = expectedCount >= 9;
            var action = state.ActionLog.SelectMany(x => x.SubActions).SingleOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
            if (drawn.Location != (full ? CardLocation.Discard : recipient.HandOf())
                || drawn.LocationNumber != (full ? route == 2 ? 17 : 7 : expectedCount)
                || drawn.Owner != (full ? deckSide : recipient) || drawn.OriginalOwner != deckSide
                || !Equals(action?.Values.FirstOrDefault(x => x.Name == "PreQtyInHand")?.Value, expectedCount)
                || !Equals(action?.Values.FirstOrDefault(x => x.Name == "handIsFull")?.Value, full ? 1 : 0)
                || !state.GetAutoPlayCards().SequenceEqual(!full && drawnTag is 1 or 3 ? new[] { drawn.CardId } : Array.Empty<int>())
                || route != 2 && (full ? result is not null : !ReferenceEquals(result, drawn))
                || state.Random.ConsumedCount != 0)
                return $"抽牌容量/编号/通知/入队错误：{deckSide}/{route}/{quantity}/{excluded}/{oppositeOwner}/{drawnTag}";
            for (int i = 0; i < quantity; i++)
                if (state.ById(100 + i)!.LocationNumber != 5 + i * 3) return "抽牌不得压紧已有手牌编号";
            if (!state.Deck(deckSide).Select(x => x.CardId).SequenceEqual(new[] { route == 2 ? 60 : 61 }))
                return "容量分支不得移除其他牌库成员";
        }
        return null;
    }

    private static string? DrawHandCapacityAfterDeckEvents(CardDatabase db)
    {
        const string name = "card_unit_m36_destroyer", trigger = "OnAfterDeckChanged", marker = "card_unit_routed_troops";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(trigger)) return "无法安装抽牌容量T3探针";
        locals[trigger] = new[] {
            new KismetStep(0, "call", "SpawnCardInHandBySide", new[] {
                new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = marker }, new KismetExpr { Int = 30 }
            }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        };
        try
        {
            foreach (Side deckSide in new[] { Side.Left, Side.Right })
            foreach (int route in Enumerable.Range(0, 3))
            foreach (int quantity in new[] { 8, 9 })
            foreach (int mutation in Enumerable.Range(0, 5))
            {
                var (engine, state) = EmptyBoard(db);
                Side recipient = route == 1 ? deckSide.Opposite() : deckSide;
                var watcher = state.CreateWithId(name, deckSide, 20, CardLocation.Discard, 0);
                watcher.Definition = new CardDefinition { Name = name, Type = "infantry", UsedTriggers = new[] { trigger } };
                state.CreateWithId(PlainUnit, deckSide, 30, CardLocation.Discard, 0);
                for (int i = 0; i < quantity; i++) state.CreateWithId(PlainUnit, recipient, 100 + i, recipient.HandOf(), 5 + i * 3);
                var changed = state.ById(100)!;
                if (mutation == 2) engine.Api.AddCustomGameplayTag(changed, "autoplay");
                var incoming = state.CreateWithId(PlainUnit, recipient.Opposite(), 200, CardLocation.Discard, 33);
                var drawn = state.CreateWithId(PlainUnit, deckSide, 60, deckSide.DeckOf(), 17);
                int callbacks = 0; bool correct = true;
                state.CardCreated += card => {
                    if (card.Name != marker) return;
                    callbacks++;
                    // Keep the marker out of either capacity query. This is a
                    // controlled T3 callback, not a claimed real card combo.
                    card.Location = CardLocation.Discard;
                    correct &= drawn.Location == deckSide.DeckOf() && !state.Deck(deckSide).Any(x => x.CardId == drawn.CardId);
                    if (mutation == 1) engine.Api.AddCustomGameplayTag(changed, "autoplay");
                    if (mutation == 2) engine.Api.RemoveCustomGameplayTag(changed, "autoplay");
                    if (mutation == 3) changed.Location = recipient.Opposite().HandOf();
                    if (mutation == 4) incoming.Location = recipient.HandOf();
                };
                if (route == 2) engine.Api.InvokeByName("DrawSpecificCardFromDeckBySide", drawn,
                    new object?[] { 30, 60, (int)deckSide, false }, new EffectContext { Engine = engine, State = state, Controller = recipient }, out _);
                else engine.DrawCard(deckSide, instigatorId: 30, opponentDraw: route == 1);
                int expected = quantity + (mutation == 4 ? 1 : mutation is 1 or 3 ? -1 : 0);
                bool full = expected >= 9;
                var action = state.ActionLog.SelectMany(x => x.SubActions).SingleOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
                if (!correct || callbacks != 1 || drawn.Location != (full ? CardLocation.Discard : recipient.HandOf())
                    || drawn.LocationNumber != (full ? 17 : expected)
                    || !Equals(action?.Values.FirstOrDefault(x => x.Name == "PreQtyInHand")?.Value, expected)
                    || !Equals(action?.Values.FirstOrDefault(x => x.Name == "handIsFull")?.Value, full ? 1 : 0))
                    return $"T3后容量查询错误：{deckSide}/{route}/{quantity}/{mutation}/calls={callbacks}";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? DrawHandNumberAssignment(CardDatabase db)
    {
        foreach (Side deckSide in new[] { Side.Left, Side.Right })
        foreach (bool opponentDraw in new[] { false, true })
        foreach (bool specific in new[] { false, true })
        foreach (bool colliding in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            Side recipient = opponentDraw ? deckSide.Opposite() : deckSide;
            var first = state.CreateWithId("card_unit_432_infantry_regiment", recipient, 100, recipient.HandOf(), 0);
            var second = state.CreateWithId(first.Name, recipient, 101, recipient.HandOf(), colliding ? 2 : 7);
            var drawn = state.CreateWithId(first.Name, deckSide, 60, deckSide.DeckOf(), 15);
            if (specific && opponentDraw) continue; // Native specific wrapper always draws to deckSide.
            if (specific) engine.Api.InvokeByName("DrawSpecificCardFromDeckBySide", drawn,
                new object?[] { 0, drawn.CardId, (int)deckSide, false },
                new EffectContext { Engine = engine, State = state, Controller = deckSide }, out _);
            else engine.DrawCard(deckSide, opponentDraw: opponentDraw);
            if (drawn.Location != recipient.HandOf() || drawn.LocationNumber != 2
                || first.LocationNumber != 0 || second.LocationNumber != (colliding ? 2 : 7))
                return $"抽牌入手编号错误：牌库方={deckSide} 对方抽牌={opponentDraw} 指定={specific} 编号碰撞={colliding}";
        }
        return null;
    }

    private static string? SpecificDrawFieldsAndOrder(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool full in new[] { false, true })
        foreach (bool seen in new[] { false, true })
        foreach (int source in new[] { 0, 30 })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 1;
            var watcher = state.CreateWithId("card_event_betasom", side, 20, CardLocation.Discard, 0);
            watcher.EnteredPlayOnTurn = 1;
            if (full)
                for (int i = 0; i < GameState.HandCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", side, 100 + i, side.HandOf(), i);
            var first = state.CreateWithId("card_unit_432_infantry_regiment", side, 62, side.DeckOf(), 1);
            var target = state.CreateWithId(first.Name, side, 60, side.DeckOf(), 7);
            var last = state.CreateWithId(first.Name, side, 63, side.DeckOf(), 15);
            var context = new EffectContext { Engine = engine, State = state, Self = target, Controller = side.Opposite() };
            engine.Api.InvokeByName("DrawSpecificCardFromDeckBySide", target,
                new object?[] { source, target.CardId, (int)side, seen }, context, out _);
            var action = state.ActionLog.SelectMany(x => x.SubActions).LastOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
            if (target.Location != (full ? CardLocation.Discard : side.HandOf()) || target.CardSeen != seen
                || first.LocationNumber != 1 || last.LocationNumber != 15 || (full && target.LocationNumber != 7)
                || !state.Deck(side).Select(x => x.CardId).SequenceEqual(new[] { 62, 63 })
                || !engine.Api.HasCustomGameplayTag(first, "subtype.navy")
                || action?.Values.FirstOrDefault(x => x.Name == "cardID")?.Value != 60
                || action.Values.FirstOrDefault(x => x.Name == "instigatorID")?.Value != source)
                return $"指定抽牌参数或编号错误：方={side} 满手={full} 公开={seen} 来源={source}";
        }
        return null;
    }

    private static string? OpponentDrawRouting(CardDatabase db)
    {
        const string name = "card_unit_coastwatchers";
        const string trigger = "OnCardDrawnFromDeck";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(name, trigger) is not null) return "无法安全添加对方抽牌参数探针";
        locals.Add(trigger, new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "K2Node_Event_drawnSide", Scope = "local" }, null, -1, "_auditRecipientSide", null) { DestinationScope = "instance" },
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (Side deckSide in new[] { Side.Left, Side.Right })
            foreach (bool recipientFull in new[] { false, true })
            foreach (bool seen in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                state.Turn = 1;
                Side recipient = deckSide.Opposite();
                var watcher = state.CreateWithId("card_event_betasom", deckSide, 20, CardLocation.Discard, 0);
                watcher.EnteredPlayOnTurn = 1;
                Side filled = recipientFull ? recipient : deckSide;
                for (int i = 0; i < GameState.HandCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", filled, 100 + i, filled.HandOf(), i);
                var card = state.CreateWithId(name, deckSide, 60, deckSide.DeckOf(), 0);
                var next = state.CreateWithId("card_unit_432_infantry_regiment", deckSide, 61, deckSide.DeckOf(), 1);
                var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = deckSide };
                engine.Api.InvokeByName("DrawCardsFromDeckBySide", card,
                    new object?[] { 30, (int)deckSide, 1, seen, true, null, 0.4 }, context, out _);
                var action = state.ActionLog.SelectMany(x => x.SubActions).LastOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
                bool ownCalled = card.BlueprintVariables.ContainsKey("_auditRecipientSide");
                if (card.Location != (recipientFull ? CardLocation.Discard : recipient.HandOf())
                    || card.Owner != (recipientFull ? deckSide : recipient) || card.OriginalOwner != deckSide || card.CardSeen != seen
                    || state.Deck(deckSide).Count != 1 || state.Deck(deckSide)[0] != next
                    || !engine.Api.HasCustomGameplayTag(next, "subtype.navy")
                    || ownCalled == recipientFull || (!recipientFull && Convert.ToInt32(card.BlueprintVariables["_auditRecipientSide"]) != (int)recipient)
                    || action?.Values.FirstOrDefault(x => x.Name == "side")?.Text != recipient.ToWire()
                    || action.Values.FirstOrDefault(x => x.Name == "oppSide")?.Value != 1)
                    return $"对方抽牌路由错误：牌库方={deckSide} 收牌方满手={recipientFull} 公开={seen}";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? OpponentDrawFatigue(CardDatabase db)
    {
        foreach (Side deckSide in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            int ownHp = state.HqDefense(deckSide), otherHp = state.HqDefense(deckSide.Opposite());
            var context = new EffectContext { Engine = engine, State = state, Controller = deckSide.Opposite() };
            engine.Api.InvokeByName("DrawCardsFromDeckBySide", null,
                new object?[] { 0, (int)deckSide, 1, false, true, null, 0.4 }, context, out _);
            if (state.Fatigue(deckSide) != 1 || state.Fatigue(deckSide.Opposite()) != 0
                || state.HqDefense(deckSide) != ownHp - 1 || state.HqDefense(deckSide.Opposite()) != otherHp)
                return "对方抽牌空牌库疲劳不应转移给收牌方";
        }
        return null;
    }

    private static string? DrawSeenContract(CardDatabase db)
    {
        const string name = "card_unit_m36_destroyer";
        const string trigger = "OnCardDrawnFromDeck";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(name, trigger) is not null) return "无法安全添加抽牌公开探针";
        locals.Add(trigger, new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "cardSeen", Scope = "instance" }, null, -1, "_auditSeenAtOwn", null) { DestinationScope = "instance" },
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (bool full in new[] { false, true })
            foreach (bool initiallySeen in new[] { false, true })
            foreach (bool markSeen in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                if (full)
                    for (int i = 0; i < GameState.HandCapacity; i++)
                        state.CreateWithId("card_unit_432_infantry_regiment", side, 100 + i, side.HandOf(), i);
                var card = state.CreateWithId(name, side, 60, side.DeckOf(), 0);
                card.CardSeen = initiallySeen;
                var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
                engine.Api.InvokeByName("DrawCardsFromDeckBySide", card,
                    new object?[] { 0, (int)side, 1, markSeen, false, null, 0.4 }, context, out _);
                bool expected = initiallySeen || markSeen;
                bool ownCalled = card.BlueprintVariables.ContainsKey("_auditSeenAtOwn");
                if (card.CardSeen != expected || ownCalled == full
                    || (!full && Convert.ToBoolean(card.BlueprintVariables["_auditSeenAtOwn"]) != initiallySeen))
                    return $"抽牌公开时机错误：方={side} 满手={full} 原公开={initiallySeen} 请求公开={markSeen}";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? DrawNotificationInstigator(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool full in new[] { false, true })
        foreach (int sourceId in new[] { 0, 30 })
        {
            var (engine, state) = EmptyBoard(db);
            var caller = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 20, CardLocation.Discard, 0);
            if (full)
                for (int i = 0; i < GameState.HandCapacity; i++)
                    state.CreateWithId(caller.Name, side, 100 + i, side.HandOf(), i);
            state.CreateWithId(caller.Name, side, 60, side.DeckOf(), 0);
            var context = new EffectContext { Engine = engine, State = state, Self = caller, Controller = Side.Left };
            engine.Api.InvokeByName("DrawCardsFromDeckBySide", caller,
                new object?[] { sourceId, (int)side, 1, false, false, null, 0.4 }, context, out _);
            var action = state.ActionLog.SelectMany(x => x.SubActions).LastOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
            if (action?.Values.FirstOrDefault(x => x.Name == "instigatorID") is not { } source || source.Value != sourceId
                || action.Values.FirstOrDefault(x => x.Name == "cardType") is not { } type || type.Value != -1 || type.Text != caller.Name)
                return $"抽牌通知未保留显式来源{sourceId}或卡名：方={side}，满手={full}";
        }
        return null;
    }

    private static string? DrawNotificationNoFatigue(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool full in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            engine.DrawCard(side); // establish nonzero fatigue before the real draw
            if (full)
                for (int i = 0; i < GameState.HandCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", side, 100 + i, side.HandOf(), i);
            state.CreateWithId("card_unit_432_infantry_regiment", side, 60, side.DeckOf(), 0);
            int actions = state.ActionLog.Count;
            engine.DrawCard(side);
            var draw = state.ActionLog.Skip(actions).SelectMany(x => x.SubActions).LastOrDefault(x => x.Name == "ZActionDrawCardFromDeck");
            if (state.Fatigue(side) <= 0 || draw is null || draw.Values.Any(x => x.Name == "nextFatigueDamage"))
                return $"非空抽牌不应编码疲劳预告：方={side}，满手={full}";
        }
        return null;
    }

    private static string? OwnDrawEventBoundary(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib";
        const string trigger = "OnCardDrawnFromDeck";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(name, trigger) is not null) return "无法安全添加自身抽牌探针";
        // Synthetic own callback records both parameters and suppresses a
        // registered observer before the following T42 query takes place.
        locals.Add(trigger, new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "K2Node_Event_StartOfTurnDraw", Scope = "local" }, null, -1, "_auditOwnStart", null) { DestinationScope = "instance" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "K2Node_Event_drawnSide", Scope = "local" }, null, -1, "_auditOwnSide", null) { DestinationScope = "instance" },
            new KismetStep(2, "call", "SuppressUnit", new[] { new KismetExpr { Int = 21 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (Side side in new[] { Side.Left, Side.Right })
            foreach (int zone in new[] { 0, 1, 2 })
            foreach (bool suppressed in new[] { false, true })
            foreach (bool start in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                var observer = state.CreateWithId("card_unit_67th_baranovichi", side, 21, side.HqOf(), 1);
                var card = state.CreateWithId(name, side, 60,
                    zone == 0 ? side.HandOf() : zone == 1 ? CardLocation.Discard : CardLocation.NotAvailable, 0);
                if (suppressed) card.Keywords.Add(Keyword.Suppressed);
                var trace = new List<string>();
                engine.Api.TriggerTrace = trace;
                engine.FireEnteredHandFromDeckEvents(card, side, start);
                if (!card.BlueprintVariables.ContainsKey("_auditOwnStart")
                    || Convert.ToBoolean(card.BlueprintVariables.GetValueOrDefault("_auditOwnStart")) != start
                    || Convert.ToInt32(card.BlueprintVariables.GetValueOrDefault("_auditOwnSide")) != (int)side
                    || !observer.IsSuppressed
                    || trace.Any(x => x.StartsWith("OnOtherCardDrawnFromDeck → card_unit_67th_baranovichi#21", StringComparison.Ordinal)))
                    return $"自身抽牌派发或查询顺序错误：方={side} 区={zone} 抑制={suppressed} 回合开始={start}";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? DrawObserverSnapshot(CardDatabase db)
    {
        const string probe = "card_unit_41st_infantry_regiment";
        const string trigger = "OnOtherCardDrawnFromDeck";
        if (KismetLibrary.Default?.Find(probe)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(probe, trigger) is not null) return "无法安全添加T42临时接收函数";
        locals.Add(trigger, new[] {
            new KismetStep(0, "call", "SuppressUnit", new[] { new KismetExpr { Int = 21 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (bool initiallySuppressed in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                state.CreateWithId(probe, Side.Left, 20, CardLocation.BoardHqLeft, 1);
                var later = state.CreateWithId("card_unit_67th_baranovichi", Side.Left, 21, CardLocation.BoardHqLeft, 2);
                if (initiallySuppressed) later.Keywords.Add(Keyword.Suppressed);
                var drawn = state.CreateWithId("card_unit_light_infantry", Side.Left, 60, CardLocation.DeckLeft, 0);
                var trace = new List<string>();
                engine.Api.TriggerTrace = trace;
                engine.DrawCard(Side.Left);
                bool received = trace.Any(x => x.StartsWith(trigger + " → card_unit_67th_baranovichi#21", StringComparison.Ordinal));
                // Earlier location/creation phases can already grant Alpine;
                // this probe asserts dispatch eligibility, not its provenance.
                if (!later.IsSuppressed || received != !initiallySuppressed)
                    return $"T42快照错误：查询前抑制={initiallySuppressed}，接收={received}";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? DrawObserverLocationAndSelf(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        state.CreateWithId("card_unit_67th_baranovichi", Side.Left, 20, CardLocation.NotAvailable, 0);
        var drawn = state.CreateWithId("card_event_cross_of_lorraine", Side.Left, 60, CardLocation.DeckLeft, 0);
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        engine.DrawCard(Side.Left, startOfTurnDraw: true);
        return trace.Any(x => x.StartsWith("OnOtherCardDrawnFromDeck → card_unit_67th_baranovichi#20", StringComparison.Ordinal))
            && !trace.Any(x => x.StartsWith("OnOtherCardDrawnFromDeck → " + drawn.Name + "#60", StringComparison.Ordinal))
            ? null : "T42应保留未定位订阅者，同时按抽牌ID排除新抽卡自身";
    }

    private static string? DrawDeckChangeTiming(CardDatabase db)
    {
        foreach (bool full in new[] { false, true })
        foreach (bool hasNext in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 1;
            var watcher = state.CreateWithId("card_event_betasom", Side.Left, 20, CardLocation.Discard, 0);
            watcher.EnteredPlayOnTurn = 1;
            if (full)
                for (int i = 0; i < GameState.HandCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 100 + i, CardLocation.HandLeft, i);
            var card = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 60, CardLocation.DeckLeft, 0);
            var next = hasNext ? state.CreateWithId(card.Name, Side.Left, 61, CardLocation.DeckLeft, 1) : null;
            engine.Api.FireTrigger("OnAfterDeckChanged", null, Side.Left, broadcastName: true,
                eventArgs: new object?[] { (int)Side.Left }, namedArgs: new Dictionary<string, object?> { ["deckSide"] = (int)Side.Left });
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            engine.DrawCard(Side.Left);
            if (card.Location != (full ? CardLocation.Discard : CardLocation.HandLeft)
                || engine.Api.HasCustomGameplayTag(card, "subtype.navy")
                || (next is not null && !engine.Api.HasCustomGameplayTag(next, "subtype.navy"))
                || trace.Count(x => x.StartsWith("OnAfterDeckChanged → card_event_betasom#20", StringComparison.Ordinal)) != 1)
                return $"抽牌T3标签时机错误：满手={full}，有下一张={hasNext}";
        }
        return null;
    }

    private static string? DrawOverflowLocationBoundary(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        {
            var (engine, state) = EmptyBoard(db);
            for (int i = 0; i < GameState.HandCapacity; i++)
                state.CreateWithId("card_unit_432_infantry_regiment", side, 100 + i, side.HandOf(), i);
            var card = state.CreateWithId("card_unit_432_infantry_regiment", side, 60, side.DeckOf(), 0);
            var discarded = state.CreateWithId(card.Name, side, 70, CardLocation.Discard, 17);
            var moved = state.CardMoved;
            int notifications = 0;
            state.CardMoved = (c, oldLocation, newLocation, ownerChange, reason) =>
            {
                if (c == card) notifications++;
                moved?.Invoke(c, oldLocation, newLocation, ownerChange, reason);
            };
            engine.DrawCard(side);
            if (card.Location != CardLocation.Discard || card.LocationNumber != 0 || discarded.LocationNumber != 17 || notifications != 0)
                return $"{side}烧牌误改编号或发移动事件：编号={card.LocationNumber}/{discarded.LocationNumber}，事件={notifications}";
        }
        return null;
    }

    private static string? DeckRemovalViewContract(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        var first = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 60, CardLocation.DeckLeft, 0);
        var next = state.CreateWithId(first.Name, Side.Left, 61, CardLocation.DeckLeft, 1);
        bool observed = false, nested = false, restoredOuter = false;
        state.WithDeckCardRemoved(Side.Left, 60, () =>
        {
            observed = first.Location == CardLocation.DeckLeft && state.Cards(Side.Left, CardLocation.DeckLeft).Contains(first)
                && engine.Api.GetDeckBySide(Side.Left).SequenceEqual(new[] { 61 });
            state.WithDeckCardRemoved(Side.Left, 60, () =>
                state.WithDeckCardRemoved(Side.Left, 61, () => nested = state.Deck(Side.Left).Count == 0));
            restoredOuter = engine.Api.GetDeckBySide(Side.Left).SequenceEqual(new[] { 61 });
        });
        try { state.WithDeckCardRemoved(Side.Left, 60, () => throw new InvalidOperationException("audit probe")); }
        catch (InvalidOperationException) { }
        return observed && nested && restoredOuter && engine.Api.GetDeckBySide(Side.Left).SequenceEqual(new[] { 60, 61 })
            && next.LocationNumber == 1 ? null : "牌库移除视图错误地改变物理位置、提前恢复外层成员或泄漏临时状态";
    }

    private static string? DeckDiscardUpdatesTopCard(CardDatabase db)
    {
        foreach (bool hasNext in new[] { false, true })
        foreach (bool skip in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 1;
            var watcher = state.CreateWithId("card_event_betasom", Side.Left, 20, CardLocation.Discard, 0);
            watcher.EnteredPlayOnTurn = 1;
            var card = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 60, CardLocation.DeckLeft, 0);
            var next = hasNext ? state.CreateWithId(card.Name, Side.Left, 61, CardLocation.DeckLeft, 1) : null;
            engine.Api.FireTrigger("OnAfterDeckChanged", null, Side.Left, broadcastName: true,
                eventArgs: new object?[] { (int)Side.Left }, namedArgs: new Dictionary<string, object?> { ["deckSide"] = (int)Side.Left });
            if (!engine.Api.HasCustomGameplayTag(card, "subtype.navy")) return "Betasom顶牌初始布景失败";
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = Side.Left };
            engine.Api.InvokeByName("DiscardCardFromDeck", card, new object?[] { 60, 0, skip, false, null }, context, out _);
            var expected = next is null ? Array.Empty<int>() : new[] { next.CardId };
            if (card.Location != CardLocation.Discard || !state.Deck(Side.Left).Select(x => x.CardId).SequenceEqual(expected)
                || engine.Api.HasCustomGameplayTag(card, "subtype.navy")
                || (next is not null && !engine.Api.HasCustomGameplayTag(next, "subtype.navy"))
                || trace.Count(x => x.StartsWith("OnAfterDeckChanged → card_event_betasom#20", StringComparison.Ordinal)) != 1)
                return $"牌库移除T3未更新实际顶牌：有后续={hasNext}，skipTriggers={skip}";
        }
        return null;
    }

    private static string? DeckDiscardNotificationBoundary(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        state.CreateWithId("card_unit_nakajima_b5n", Side.Left, 20, CardLocation.BoardHqLeft, 1);
        var enemy = state.CreateWithId("card_unit_432_infantry_regiment", Side.Right, 60, CardLocation.BoardHqRight, 1);
        var card = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 62, CardLocation.DeckLeft, 2);
        var discarded = state.CreateWithId(card.Name, Side.Left, 70, CardLocation.Discard, 17);
        int defense = enemy.Defense, movedCount = 0;
        var moved = state.CardMoved;
        state.CardMoved = (c, oldLocation, newLocation, ownerChange, reason) =>
        {
            if (c == card) movedCount++;
            moved?.Invoke(c, oldLocation, newLocation, ownerChange, reason);
        };
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = Side.Left };
        engine.Api.InvokeByName("DiscardCardFromDeck", card, new object?[] { 62, 0, false, false, null }, context, out _);
        return card.Location == CardLocation.Discard && card.LocationNumber == 2 && discarded.LocationNumber == 17
            && movedCount == 0 && enemy.Defense == defense
            && !trace.Any(x => x.StartsWith("OnOtherCardDiscarded", StringComparison.Ordinal))
            ? null : $"牌库弃牌误发手牌/换区事件或改写弃牌编号：移动={movedCount}，编号={card.LocationNumber}/{discarded.LocationNumber}，敌防御={enemy.Defense}/{defense}";
    }

    private static string? DeckDiscardNotificationPayload(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int source in new[] { 0, 30 })
        foreach (bool skip in new[] { false, true })
        foreach (bool visuals in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId("card_unit_432_infantry_regiment", side, 62, side.DeckOf(), 0);
            var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            engine.Api.InvokeByName("DiscardCardFromDeck", card, new object?[] { 62, source, skip, visuals, null }, context, out _);
            var action = state.ActionLog.SelectMany(x => x.SubActions).LastOrDefault(x => x.Name == "ZActionDiscardCard");
            var names = new List<string> { "cardID", "discarderID", "oldLocation" };
            if (skip) names.Add("skipTriggers");
            if (visuals) names.Add("skipVisuals");
            if (action is null || !action.Values.Select(x => x.Name).SequenceEqual(names)
                || action.Values[0].Value != 62 || action.Values[1].Value != source
                || action.Values[2].Value != -1 || action.Values[2].Text != (side == Side.Left ? "Deck_Left" : "Deck_Right")
                || action.Values.Skip(3).Any(x => x.Value != 1))
                return $"牌库弃牌通知字段错误：方={side} 来源={source} skip={skip} visuals={visuals}";
        }
        return null;
    }

    private static string? DeckDiscardAttemptEffect(CardDatabase db)
    {
        foreach (bool skip in new[] { false, true })
        foreach (bool suppressed in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId("card_unit_35th_mountain_rifles", Side.Left, 60, CardLocation.DeckLeft, 0);
            if (suppressed) card.Keywords.Add(Keyword.Suppressed);
            var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = Side.Left };
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            object? result = engine.Api.InvokeByName("DiscardCardFromDeck", card,
                new object?[] { 60, 0, skip, false, null }, context, out _);
            var copies = state.Board(Side.Left).Where(x => x.Name == card.Name).ToArray();
            bool attempted = trace.Any(x => x.StartsWith("OnAttemptedDiscard(out", StringComparison.Ordinal));
            if (result is not true || card.Location != CardLocation.Discard || copies.Length != (skip ? 0 : 1) || attempted != !skip)
                return $"35th尝试弃牌效果错误：skip={skip}，抑制={suppressed}，副本数={copies.Length}，尝试回调={attempted}";
        }
        return null;
    }

    private static string? DeckDiscardCancellation(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib";
        const string trigger = "OnAttemptedDiscard";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey(trigger)) return "无法安全添加取消弃牌探针";
        locals.Add(trigger, new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "discarderID", Scope = "local" }, null, -1, "_auditDiscarder", null) { DestinationScope = "instance" },
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Bool = true }, null, -1, "cancelDiscard", null) { DestinationScope = "local" },
            new KismetStep(2, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (int source in new[] { 0, 30 })
            {
                var (engine, state) = EmptyBoard(db);
                var card = state.CreateWithId(name, Side.Left, 60, CardLocation.DeckLeft, 0);
                var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = Side.Left };
                int actions = state.ActionLog.Count;
                object? result = engine.Api.InvokeByName("DiscardCardFromDeck", card,
                    new object?[] { 60, source, false, false, null }, context, out _);
                if (result is not false || card.Location != CardLocation.DeckLeft || state.ActionLog.Count != actions
                    || Convert.ToInt32(card.BlueprintVariables.GetValueOrDefault("_auditDiscarder")) != source)
                    return $"尝试取消应保留牌库卡且不发弃牌动作，并传入显式来源{source}";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? CreationModifierSnapshot(CardDatabase db)
    {
        const string probe = "card_event_honorifics";
        const string trigger = "OnOtherCardCreatedAlterCard";
        if (KismetLibrary.Default?.Find(probe)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(probe, trigger) is not null)
            return "无法安全添加T35临时前序接收函数";
        // Synthetic predecessor probes query timing; the later receiver runs
        // the actual 67th Baranovichi Blueprint, not a replacement function.
        locals.Add(trigger, new[] {
            new KismetStep(0, "call", "SuppressUnit", new[] { new KismetExpr { Int = 21 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        try
        {
            foreach (bool initiallySuppressed in new[] { false, true })
            {
                var (engine, state) = EmptyBoard(db);
                // Create the real receiver before adding the predecessor so
                // setup callbacks cannot invoke this probe on a missing ID.
                var later = state.CreateWithId("card_unit_67th_baranovichi", Side.Left, 21, CardLocation.BoardHqLeft, 1);
                state.CreateWithId(probe, Side.Left, 20, CardLocation.Discard, 0);
                if (initiallySuppressed) later.Keywords.Add(Keyword.Suppressed);
                else later.Keywords.Remove(Keyword.Suppressed); // setup probe may have suppressed it
                var trace = new List<string>();
                engine.Api.TriggerTrace = trace;
                var created = state.Create("card_unit_light_infantry", Side.Left, CardLocation.HandLeft, 0);
                bool received = trace.Any(x => x.StartsWith(trigger + " → card_unit_67th_baranovichi#21", StringComparison.Ordinal));
                if (!later.IsSuppressed || received != !initiallySuppressed
                    || created.Keywords.Contains(Keyword.Alpine) != !initiallySuppressed)
                    return $"T35查询快照错误：查询前抑制={initiallySuppressed}，接收={received}，Alpine={created.Keywords.Contains(Keyword.Alpine)}";
            }
            return null;
        }
        finally { locals.Remove(trigger); }
    }

    private static string? ConversionSkipsCreationModifiers(CardDatabase db)
    {
        foreach (var location in new[] { CardLocation.HandLeft, CardLocation.DeckLeft, CardLocation.BoardHqLeft })
        {
            var (engine, state) = EmptyBoard(db);
            state.SetMaxKredits(Side.Left, 4);
            var source = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 30, location, 1);
            var context = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Left };
            for (int i = 0; i < 2; i++)
                engine.Api.InvokeByName("LoseKreditSlot", source, new object?[] { (int)Side.Left }, context, out _);
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            var made = state.CardCreated;
            int objectCreations = 0;
            state.CardCreated = card => { objectCreations++; made?.Invoke(card); };
            var result = engine.Api.InvokeByName("ConvertCard", source,
                new object?[] { new[] { source.CardId }, 0, "card_unit_144th_infantry_regiment", 0, true, null }, context, out _);
            var ids = (result as System.Collections.IEnumerable)?.Cast<object?>().Select(Convert.ToInt32).ToArray();
            if (ids is not { Length: 1 } || state.ById(ids[0]) is not { } replacement || objectCreations != 1)
                return "转换未保留独立对象创建阶段";
            if (trace.Any(x => x.StartsWith("OnOtherCardCreatedAlterCard →", StringComparison.Ordinal))
                || replacement.CustomJson.ContainsKey("slots_lost"))
                return $"{location} 转换skipAction不应发T35或让144步兵团继承槽位损失";
            trace.Clear();
            engine.Api.InvokeByName("SpawnCardInDeckBySide", source,
                new object?[] { (int)Side.Left, replacement.Name, 30, 1, 0, false, false, false, false, false, null }, context, out _);
            if (!trace.Any(x => x.StartsWith("OnOtherCardCreatedAlterCard →", StringComparison.Ordinal))
                || state.Deck(Side.Left)[0].CustomJson.GetValueOrDefault("slots_lost") != "2")
                return "普通生成仍应执行T35并让新144步兵团继承历史槽位损失";
        }
        return null;
    }

    private static string? SpawnDeckNotificationTiming(CardDatabase db)
    {
        foreach (bool shuffle in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 1;
            var betasom = state.CreateWithId("card_event_betasom", Side.Left, 20, CardLocation.Discard, 0);
            betasom.EnteredPlayOnTurn = 1;
            state.CreateWithId("card_unit_110e_regiment_motorize", Side.Left, 21, CardLocation.BoardHqLeft, 1);
            var source = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 30, CardLocation.Discard, 0);
            source.IsGold = true;
            var made = state.CardCreated;
            CardInstance? previous = null;
            int creations = 0;
            bool notifiedBetween = true, goldCorrect = true;
            state.CardCreated = card =>
            {
                if (previous is not null) notifiedBetween &= engine.Api.HasCustomGameplayTag(previous, "subtype.navy");
                goldCorrect &= card.IsGold == (creations == 0);
                creations++;
                previous = card;
                source.IsGold = false;
                made?.Invoke(card);
            };
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            var context = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Left };
            engine.Api.InvokeByName("SpawnCardInDeckBySide", source,
                new object?[] { (int)Side.Left, "card_unit_routed_troops", 30, 3, 0, false, false, shuffle, false, false, null }, context, out _);
            int t3 = trace.Count(x => x.StartsWith("OnAfterDeckChanged → card_event_betasom#20", StringComparison.Ordinal));
            int t22 = trace.FindIndex(x => x.StartsWith("OnDeckShuffled →", StringComparison.Ordinal));
            if (creations != 3 || !notifiedBetween || !goldCorrect || t3 != (shuffle ? 4 : 3)
                || (shuffle ? t22 <= trace.FindLastIndex(x => x.StartsWith("OnAfterDeckChanged →", StringComparison.Ordinal)) : t22 >= 0)
                || !engine.Api.HasCustomGameplayTag(state.Deck(Side.Left)[0], "subtype.navy"))
                return $"生成牌库的逐卡通知/金卡读取顺序错误：洗牌={shuffle}，创建={creations}，T3={t3}，逐卡通知={notifiedBetween}，金卡={goldCorrect}";
        }
        return null;
    }

    private static string? SpawnDeckInputBoundary(CardDatabase db)
    {
        foreach (var input in new[] { (Source: 0, Count: 2), (Source: -1, Count: 2), (Source: 30, Count: 0), (Source: 30, Count: -2) })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 30, CardLocation.Discard, 0);
            int count = state.AllCards.Count;
            long cursor = state.Random.ConsumedCount;
            var context = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Left };
            engine.Api.InvokeByName("SpawnCardInDeckBySide", source,
                new object?[] { (int)Side.Left, "card_unit_routed_troops", input.Source, input.Count, 0, false, false, false, false, false, null }, context, out _);
            if (state.AllCards.Count != count || state.Random.ConsumedCount != cursor)
                return $"非正来源/数量不应生成卡或消费随机数：来源={input.Source}，数量={input.Count}";
        }
        // A valid source with zero creations still reaches the optional shuffle.
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 30, CardLocation.Discard, 0);
            state.CreateWithId("card_unit_110e_regiment_motorize", Side.Left, 20, CardLocation.BoardHqLeft, 1);
            state.CreateWithId(source.Name, Side.Left, 60, CardLocation.DeckLeft, 0);
            int count = state.AllCards.Count;
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            var context = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Left };
            engine.Api.InvokeByName("SpawnCardInDeckBySide", source,
                new object?[] { (int)Side.Left, "card_unit_routed_troops", 30, 0, 0, false, false, true, false, false, null }, context, out _);
            if (state.AllCards.Count != count || !trace.Any(x => x.StartsWith("OnDeckShuffled →", StringComparison.Ordinal)))
                return "有效来源且数量为0时仍应执行请求的非空牌库洗牌，但不创建卡";
        }
        return null;
    }

    private static string? SpawnDeckCreationFields(CardDatabase db)
    {
        foreach (int faction in new[] { 0, 2, 4 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 30, CardLocation.Discard, 0);
            source.IsGold = true;
            var made = state.CardCreated;
            bool correct = false;
            state.CardCreated = card =>
            {
                correct = card.IsGold && card.IsSalvaged == (faction != 0) && card.SalvagedCardId == 0
                    && card.SalvageFaction == (faction == 2 ? "Britain" : faction == 4 ? "Soviet" : null)
                    && card.Attack == (faction != 0 ? 1 : card.Definition.Attack);
                made?.Invoke(card);
            };
            var context = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Left };
            engine.Api.InvokeByName("SpawnCardInDeckBySide", source,
                new object?[] { (int)Side.Left, "card_unit_432_infantry_regiment", 30, 1, faction, false, false, false, false, false, null }, context, out _);
            if (!correct) return $"生成卡创建回调前的金卡/打捞字段错误：阵营={faction}";
        }
        return null;
    }

    private static string? ShuffleDeckChangeOrder(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        state.Turn = 1;
        var betasom = state.CreateWithId("card_event_betasom", Side.Left, 20, CardLocation.Discard, 0);
        betasom.EnteredPlayOnTurn = 1;
        var watcher = state.CreateWithId("card_unit_110e_regiment_motorize", Side.Left, 21, CardLocation.BoardHqLeft, 1);
        for (int i = 0; i < 3; i++)
            state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 60 + i, CardLocation.DeckLeft, i);
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        var context = new EffectContext { Engine = engine, State = state, Self = watcher, Controller = Side.Left };
        engine.Api.InvokeByName("ShuffleDeckBySide", watcher, new object?[] { (int)Side.Left, true, watcher.CardId, null }, context, out _);
        int changed = trace.FindIndex(x => x.StartsWith("OnAfterDeckChanged → card_event_betasom#20", StringComparison.Ordinal));
        int shuffled = trace.FindIndex(x => x.StartsWith("OnDeckShuffled → card_unit_110e_regiment_motorize#21", StringComparison.Ordinal));
        return changed >= 0 && shuffled > changed && engine.Api.HasCustomGameplayTag(state.Deck(Side.Left)[0], "subtype.navy")
            ? null : "洗牌必须先执行T3更新实际顶牌标签，再执行T22；skipSubAction不跳过规则通知";
    }

    private static string? ShuffleEmptyDeck(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        var watcher = state.CreateWithId("card_unit_110e_regiment_motorize", Side.Left, 20, CardLocation.BoardHqLeft, 1);
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        long cursor = state.Random.ConsumedCount;
        int attack = watcher.Attack;
        var context = new EffectContext { Engine = engine, State = state, Self = watcher, Controller = Side.Left };
        engine.Api.InvokeByName("ShuffleDeckBySide", watcher, new object?[] { (int)Side.Left, false, 20, null }, context, out _);
        return state.Random.ConsumedCount == cursor && watcher.Attack == attack
            && !trace.Any(x => x.StartsWith("OnDeckShuffled", StringComparison.Ordinal) || x.StartsWith("OnAfterDeckChanged", StringComparison.Ordinal))
            ? null : "空牌库洗牌应在任何随机消耗或T3/T22派发前返回";
    }

    private static string? ShuffleInstigatorContract(CardDatabase db)
    {
        foreach (int sourceId in new[] { 0, 30 })
        foreach (bool unavailable in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var watcher = state.CreateWithId("card_unit_110e_regiment_motorize", Side.Left, 20,
                unavailable ? CardLocation.NotAvailable : CardLocation.BoardHqLeft, 1);
            var source = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 30, CardLocation.Discard, 0);
            state.CreateWithId(source.Name, Side.Left, 60, CardLocation.DeckLeft, 0);
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            var context = new EffectContext { Engine = engine, State = state, Self = watcher, Controller = Side.Left };
            engine.Api.InvokeByName("ShuffleDeckBySide", watcher, new object?[] { (int)Side.Left, false, sourceId, null }, context, out _);
            string expected = sourceId == 0 ? "eventCard=null#" : $"eventCard={source.Name}#30";
            if (!trace.Any(x => x.StartsWith("OnDeckShuffled → card_unit_110e_regiment_motorize#20", StringComparison.Ordinal)
                && x.Contains(expected, StringComparison.Ordinal)))
                return $"T22未保留显式来源或未定位接收者：来源={sourceId}，未定位={unavailable}";
        }
        return null;
    }

    private static string? DeckChangedQueryBoundary(CardDatabase db)
    {
        foreach (int route in new[] { 0, 1, 2 })
        foreach (Side changedSide in new[] { Side.Left, Side.Right })
        foreach (int mode in new[] { 0, 1, 2, 3 })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 1;
            var watcher = state.CreateWithId("card_event_betasom", Side.Left, 20,
                mode is 0 or 3 ? CardLocation.NotAvailable : CardLocation.Discard, 0);
            watcher.EnteredPlayOnTurn = 1;
            if (mode >= 2) watcher.Keywords.Add(Keyword.Suppressed);
            var card = state.CreateWithId("card_unit_432_infantry_regiment", changedSide, 60,
                route == 2 ? changedSide.HandOf() : changedSide.DeckOf(), 0);
            var trace = new List<string>();
            engine.Api.TriggerTrace = trace;
            var context = new EffectContext { Engine = engine, State = state, Self = card, Controller = changedSide };
            string method = route == 0 ? "AdjustCardPositionInDeck" : route == 1 ? "ConvertCard" : "MoveCardToTopOfOwnersDeck";
            object?[] args = route == 0 ? new object?[] { (int)changedSide, card.CardId, 0, null }
                : route == 1 ? new object?[] { new[] { card.CardId }, 0, "card_unit_routed_troops", 0, true, null }
                : new object?[] { card.CardId, 0, 0 };
            engine.Api.InvokeByName(method, card, args, context, out bool handled);
            bool received = trace.Any(x => x.StartsWith("OnAfterDeckChanged → card_event_betasom#20", StringComparison.Ordinal));
            var top = state.Deck(changedSide).FirstOrDefault();
            bool tagged = top is not null && engine.Api.HasCustomGameplayTag(top, "subtype.navy");
            if (!handled || received != (mode < 2) || tagged != (mode < 2 && changedSide == Side.Left))
                return $"{method} 牌库方={changedSide} 模式={mode} 的T3查询/载荷错误：接收={received}，顶牌海军={tagged}";
        }
        return null;
    }

    // Controlled state/table changes probe lookup timing, not a claimed live
    // card combination. All names and template IDs remain valid at lookup.
    private static string? ConversionTemplateAfterLeave(CardDatabase db)
    {
        foreach (bool replaceObject in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var first = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 62, CardLocation.BoardFrontline, 0);
            var second = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 63, CardLocation.BoardFrontline, 1);
            var template = state.CreateWithId("card_unit_432_infantry_regiment", Side.Right, 70, CardLocation.HandRight, 0);
            var moved = state.CardMoved;
            int changes = 0;
            string[] names = { "card_unit_routed_troops", "card_unit_432_infantry_regiment" };
            state.CardMoved = (card, oldLocation, newLocation, ownerChange, reason) =>
            {
                moved?.Invoke(card, oldLocation, newLocation, ownerChange, reason);
                if (newLocation != CardLocation.Discard || reason != CardMoveReason.Convert
                    || (card != first && card != second)) return;
                string name = names[changes];
                if (replaceObject)
                {
                    state.Remove(template);
                    template = state.CreateWithId(name, Side.Right, 70, CardLocation.HandRight, 0);
                }
                else
                {
                    template.Name = name;
                    template.Definition = db.Require(name);
                }
                template.IsSalvaged = changes == 0;
                template.SalvageFaction = "Britain";
                template.SalvagedCardId = 999;
                card.IsGold = true;
                changes++;
            };
            var context = new EffectContext { Engine = engine, State = state, Self = first, Controller = Side.Left };
            var result = engine.Api.InvokeByName("ConvertCard", first,
                new object?[] { new[] { first.CardId, second.CardId }, 0, "None", 70, true, null }, context, out _);
            var ids = (result as System.Collections.IEnumerable)?.Cast<object?>().Select(Convert.ToInt32).ToArray();
            if (changes != 2 || ids is not { Length: 2 }) return "模板时序探针未完成两次转换";
            for (int i = 0; i < ids.Length; i++)
            {
                var replacement = state.ById(ids[i])!;
                if (replacement.Name != names[i] || !replacement.IsGold || replacement.IsSalvaged != (i == 0)
                    || replacement.SalvageFaction != (i == 0 ? "Britain" : null) || replacement.SalvagedCardId != 0)
                    return $"转换第{i + 1}项未读取离场回调后的模板/旧卡字段（替换模板对象={replaceObject}）";
            }
        }
        return null;
    }

    private static string? ConversionRemovalLocationRefresh(CardDatabase db)
    {
        foreach (var location in new[] { CardLocation.BoardHqLeft, CardLocation.BoardHqRight, CardLocation.BoardFrontline })
        {
            var (engine, state) = EmptyBoard(db);
            Side side = location == CardLocation.BoardHqRight ? Side.Right : Side.Left;
            int slot = location == CardLocation.BoardFrontline ? 0 : 1;
            var unit = state.CreateWithId("card_unit_432_infantry_regiment", side, 62, location, slot);
            var next = state.CreateWithId("card_unit_432_infantry_regiment",
                location == CardLocation.BoardFrontline ? Side.Right : side, 63, location, slot + 1);
            var moved = state.CardMoved;
            var made = state.CardCreated;
            int atMove = -1, atCreate = -1;
            state.CardMoved = (card, oldLocation, newLocation, ownerChange, reason) =>
            {
                if (card == unit && reason == CardMoveReason.Convert) atMove = next.LocationNumber;
                moved?.Invoke(card, oldLocation, newLocation, ownerChange, reason);
            };
            state.CardCreated = card => { atCreate = next.LocationNumber; made?.Invoke(card); };
            var context = new EffectContext { Engine = engine, State = state, Self = unit, Controller = side };
            engine.Api.InvokeByName("ConvertCard", unit,
                new object?[] { new[] { unit.CardId }, 0, "card_unit_routed_troops", 0, true, null }, context, out _);
            if (atMove != slot || atCreate != slot)
                return $"{location} 原区域应在换区事件和创建事件前压紧：预期={slot}，实际={atMove}/{atCreate}";
        }
        return null;
    }

    private static string? ConversionBoardInsertion(CardDatabase db)
    {
        foreach (var location in new[] { CardLocation.BoardHqLeft, CardLocation.BoardHqRight, CardLocation.BoardFrontline })
        foreach (bool reverseIds in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            Side side = location == CardLocation.BoardHqRight ? Side.Right : Side.Left;
            int slot = location == CardLocation.BoardFrontline ? 0 : 1;
            var unit = state.CreateWithId("card_unit_432_infantry_regiment", side, reverseIds ? 70 : 62, location, slot);
            var next = state.CreateWithId("card_unit_432_infantry_regiment",
                location == CardLocation.BoardFrontline ? Side.Right : side, 63, location, slot + 1);
            var context = new EffectContext { Engine = engine, State = state, Self = unit, Controller = side };
            var result = engine.Api.InvokeByName("ConvertCard", unit,
                new object?[] { new[] { unit.CardId }, 0, "card_unit_routed_troops", 0, true, null }, context, out _);
            var ids = (result as System.Collections.IEnumerable)?.Cast<object?>().Select(Convert.ToInt32).ToArray();
            if (ids is not { Length: 1 } || state.ById(ids[0]) is not { } replacement)
                return "转换未生成替代卡";
            var ordered = state.AllCardsInBattleOrder.Where(x => x.Location == location).OrderBy(x => x.LocationNumber).ToArray();
            if (ordered[slot] != replacement || replacement.LocationNumber != slot || next.LocationNumber != slot + 1
                || ordered.Select(x => x.LocationNumber).Where((n, i) => n != i).Any())
                return $"{location} 替代卡未插回原槽位，或邻卡编号未连续（反向ID={reverseIds}）";
        }
        return null;
    }

    private static string? ConversionRepeatedInput(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        var unit = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 62, CardLocation.BoardFrontline, 0);
        var context = new EffectContext { Engine = engine, State = state, Self = unit, Controller = Side.Left };
        var result = engine.Api.InvokeByName("ConvertCard", unit,
            new object?[] { new[] { unit.CardId, unit.CardId }, 0, "card_unit_routed_troops", 0, false, null }, context, out _);
        var ids = (result as System.Collections.IEnumerable)?.Cast<object?>().Select(Convert.ToInt32).ToArray();
        if (ids is not { Length: 2 } || ids[0] == ids[1] || ids.Contains(unit.CardId))
            return "重复输入ID应生成两个独立的新ID，不能预先去重";
        if (state.ById(ids[0])?.Location != CardLocation.BoardFrontline
            || state.ById(ids[1])?.Location != CardLocation.HandLeft || unit.Location != CardLocation.Discard)
            return "第二次转换应读取旧对象已在弃牌堆的状态，替代卡生成于原主手牌";
        return null;
    }

    private static string? ConversionCreationFields(CardDatabase db)
    {
        foreach (bool useTemplate in new[] { false, true })
        foreach (bool gold in new[] { false, true })
        foreach (bool salvaged in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            var unit = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 62, CardLocation.HandLeft, 0);
            unit.IsGold = gold;
            unit.IsSalvaged = true;
            unit.SalvageFaction = "Germany";
            unit.SalvagedCardId = 999;
            unit.Attack = 99;
            var template = state.CreateWithId("card_unit_routed_troops", Side.Right, 63, CardLocation.HandRight, 0);
            template.IsGold = !gold;
            template.IsSalvaged = salvaged;
            template.SalvageFaction = "Britain";
            template.SalvagedCardId = 998;
            template.Attack = 88;
            var context = new EffectContext { Engine = engine, State = state, Self = unit, Controller = Side.Left };
            var result = engine.Api.InvokeByName("ConvertCard", unit,
                new object?[] { new[] { unit.CardId }, 0, template.Name, useTemplate ? template.CardId : 0, true, null }, context, out _);
            var ids = (result as System.Collections.IEnumerable)?.Cast<object?>().Select(Convert.ToInt32).ToArray();
            if (ids is not { Length: 1 } || state.ById(ids[0]) is not { } replacement)
                return "转换未生成替代卡";
            bool expectedSalvaged = useTemplate && salvaged;
            if (replacement.IsGold != gold || replacement.IsSalvaged != expectedSalvaged
                || replacement.SalvageFaction != (expectedSalvaged ? "Britain" : null)
                || replacement.SalvagedCardId != 0 || replacement.Owner != Side.Left
                || replacement.Attack != (expectedSalvaged ? 1 : replacement.Definition.Attack))
                return $"转换创建字段错误：模板={useTemplate} 金卡={gold} 打捞模板={salvaged}";
        }
        return null;
    }

    // Controlled reentry probe: a synthetic own-draw program creates a marker
    // in the other deck. The existing creation callback runs the test mutation.
    // These temporary programs do not claim live card effects; cleanup is deterministic.
    private static IDisposable InstallDrawReentryProbe(GameState state, Action onDraw,
        string probe = "card_unit_51e_regiment")
    {
        const string marker = "card_unit_routed_troops";
        const string trigger = "OnCardDrawnFromDeck";
        if (KismetLibrary.Default?.Find(probe)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(probe, trigger) is not null)
            throw new InvalidOperationException("无法安全安装抽牌重入探针");
        locals.Add(trigger, new[] {
            new KismetStep(0, "call", "SpawnCardInDeckBySide", new[] {
                new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = marker },
                new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
            }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        var created = state.CardCreated;
        state.CardCreated = card =>
        {
            created?.Invoke(card);
            if (card.Name == marker && card.Location == CardLocation.DeckRight) onDraw();
        };
        return new AuditProbeCleanup(() => { state.CardCreated = created; locals.Remove(trigger); });
    }

    private sealed class AuditProbeCleanup(Action cleanup) : IDisposable
    {
        public void Dispose() => cleanup();
    }

    private static string? ConversionObserverSnapshot(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        state.CreateWithId("card_unit_bergmann_battalion", Side.Left, 20, CardLocation.BoardHqLeft, 1);
        var later = state.CreateWithId("card_unit_51st_rifle_brigade", Side.Left, 21, CardLocation.BoardHqLeft, 2);
        var source = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 30, CardLocation.Discard, 0);
        state.CreateWithId("card_unit_51e_regiment", Side.Left, 31, CardLocation.DeckLeft, 0);
        var unit = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 62, CardLocation.BoardFrontline, 0);
        bool changed = false;
        int attack = 0, defense = 0;
        using var drawProbe = InstallDrawReentryProbe(state, () =>
        {
            if (!changed)
            {
                changed = true;
                engine.Api.SuppressUnit(later);
                attack = later.Attack;
                defense = later.Defense;
            }
        });

        var context = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Left };
        var result = engine.Api.InvokeByName("ConvertCard", source,
            new object?[] { new[] { unit }, source.CardId, later.Name, 0, false, null }, context, out _);
        if (!changed || !later.IsSuppressed || later.Attack != attack + 1 || later.Defense != defense + 2)
            return "T34 查询入选的 51st Rifle 在前序 Bergmann 抽牌回调中被抑制后仍应获得+1+2";
        var ids = (result as System.Collections.IEnumerable)?.Cast<object?>().Select(Convert.ToInt32).ToArray();
        if (ids is not { Length: 1 } || state.ById(ids[0]) is not { } replacement
            || replacement.Attack != replacement.Definition.Attack || replacement.Defense != replacement.Definition.Defense)
            return "转换新生成的 51st Rifle 不应响应这次自身转换而获得+1+2";
        return null;
    }

    private static string? ConversionObserverUnavailable(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        state.CreateWithId("card_unit_51st_rifle_brigade", Side.Left, 20, CardLocation.NotAvailable, 0);
        var source = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 30, CardLocation.Discard, 0);
        var unit = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 62, CardLocation.BoardFrontline, 0);
        var trace = new List<string>();
        engine.Api.TriggerTrace = trace;
        var context = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Left };
        engine.Api.InvokeByName("ConvertCard", source,
            new object?[] { new[] { unit }, source.CardId, "card_unit_routed_troops", 0, false, null }, context, out _);
        return trace.Any(x => x.StartsWith("OnOtherCardConverted → card_unit_51st_rifle_brigade#20", StringComparison.Ordinal))
            ? null : "T34 未定位订阅者被额外位置门过滤";
    }

    private static string? RetreatConversionIdentity(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        var source = state.CreateWithId("card_unit_typhoon_mk_ib", Side.Left, 20, CardLocation.BoardHqLeft, 1);
        state.CreateWithId("card_unit_51e_regiment", Side.Left, 30, CardLocation.DeckLeft, 0);
        var unit = state.CreateWithId("card_unit_432_infantry_regiment", Side.Right, 62, CardLocation.BoardFrontline, 0);
        bool changed = false;
        CardInstance? replacement = null;
        var context = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Left };
        using var drawProbe = InstallDrawReentryProbe(state, () =>
        {
            if (!changed)
            {
                changed = true;
                var result = engine.Api.InvokeByName("ConvertCard", source,
                    new object?[] { new[] { unit }, source.CardId, "card_unit_routed_troops", 0, false, null }, context, out _);
                var ids = (result as System.Collections.IEnumerable)?.Cast<object?>().Select(Convert.ToInt32).ToArray();
                if (ids is { Length: 1 }) replacement = state.ById(ids[0]);
            }
        });

        engine.Api.InvokeByName("MakeCardRetreat", source, new object?[] { new[] { unit }, source.CardId }, context, out _);
        return changed && replacement is not null && replacement.CardId != unit.CardId
            && replacement.Location == CardLocation.BoardFrontline && unit.Location == CardLocation.HandRight
            && state.ById(unit.CardId) == unit && unit.Name == "card_unit_432_infantry_regiment"
            ? null : "退却不应将旧ID重定向到转换新卡；旧卡回手、新卡留在前线";
    }

    // Probe the event parameter with a temporary function; it does not claim
    // that this card has an OnLeaveBoardOrOwner override in the live pool.
    private static string? ReturnInitialLeavePayload(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || locals.ContainsKey("OnLeaveBoardOrOwner")) return "离场载荷探针无法安全添加临时函数";
        locals.Add("OnLeaveBoardOrOwner", new[] {
            new KismetStep(0, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "goingToLocation", Scope = "local" }, null, -1, "_auditLeaveDestination", null)
                { DestinationScope = "instance" },
            new KismetStep(1, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                null, null, -1, null, null) });
        try
        {
            foreach (bool full in new[] { false, true })
            foreach (int route in new[] { 0, 1, 2 })
            {
                var (engine, state) = EmptyBoard(db);
                var unit = state.CreateWithId(name, Side.Right, 62, CardLocation.BoardHqRight, 1);
                if (full)
                    for (int i = 0; i < GameState.HandCapacity; i++)
                        state.CreateWithId("card_unit_432_infantry_regiment", Side.Right, 100 + i, CardLocation.HandRight, i);
                var context = new EffectContext { Engine = engine, State = state, Self = unit, Controller = Side.Right };
                string method = route == 0 ? "MoveUnitFromBoardToOwnersHand"
                    : route == 1 ? "MoveCardFromBoardToOwnersHand" : "MakeCardRetreat";
                object?[] args = route == 0 ? new object?[] { unit, 0 }
                    : route == 1 ? new object?[] { unit.CardId, 0, (int)CardLocation.BoardHqRight, (int)CardLocation.HandRight }
                    : new object?[] { new[] { unit }, 0 };
                engine.Api.InvokeByName(method, unit, args, context, out _);
                var value = unit.BlueprintVariables.GetValueOrDefault("_auditLeaveDestination");
                if (value is null || Convert.ToInt32(value) != 0)
                    return $"{method} 满手={full} 离场应收到初始局部值0，实际={value}";
                if (unit.Location != (full ? CardLocation.Discard : CardLocation.HandRight))
                    return "初始离场载荷不能代替之后计算的实际目的地";
            }
            return null;
        }
        finally { locals.Remove("OnLeaveBoardOrOwner"); }
    }

    private static string? ReturnOverflowDiscardPayload(CardDatabase db)
    {
        foreach (int sourceId in new[] { 0, 20 })
        foreach (int route in new[] { 0, 1, 2, 3 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId("card_unit_432_infantry_regiment", Side.Left, 20, CardLocation.Discard, 0);
            var unit = state.CreateWithId("card_unit_432_infantry_regiment", Side.Right, 62, CardLocation.BoardHqRight, 1);
            for (int i = 0; i < GameState.HandCapacity; i++)
                state.CreateWithId("card_unit_432_infantry_regiment", Side.Right, 100 + i, CardLocation.HandRight, i);
            var context = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Left };
            string method = route == 0 ? "MoveUnitFromBoardToOwnersHand"
                : route == 1 ? "MoveCardFromBoardToOwnersHand" : route == 2 ? "MakeCardRetreat" : "ChangeUnitOwnership(release)";
            object?[] args = route == 0 ? new object?[] { unit, sourceId }
                : route == 1 ? new object?[] { unit.CardId, sourceId, (int)CardLocation.BoardHqRight, (int)CardLocation.HandRight }
                : new object?[] { new[] { unit }, sourceId };
            if (route == 3)
            {
                state.ChangeOwner(unit, Side.Left);
                state.Move(unit, CardLocation.BoardHqLeft, notifyMoved: false);
                unit.UnderEnemyControl = true;
                for (int i = 1; i < GameState.HalfBoardCapacity; i++)
                    state.CreateWithId("card_unit_432_infantry_regiment", Side.Right, 200 + i, CardLocation.BoardHqRight, i);
                engine.ChangeUnitOwnership(unit, sourceId, Side.Left, Side.Right, CardLocation.BoardHqRight, true);
            }
            else engine.Api.InvokeByName(method, source, args, context, out _);
            var action = state.ActionLog.SelectMany(x => x.SubActions).LastOrDefault(x => x.Name == "ZActionDiscardCard");
            if (unit.Location != CardLocation.Discard || action is null) return method + " 未执行满手弃牌";
            if (!action.Values.Select(x => x.Name).SequenceEqual(new[] { "cardID", "discarderID", "oldLocation" })
                || action.Values[0].Value != unit.CardId || action.Values[1].Value != (route == 3 ? 0 : sourceId)
                || action.Values[2].Value != -1 || action.Values[2].Text != "Board_HQRight")
                return $"{method} 来源={sourceId} 通知载荷错误：" + string.Join(",", action.Values.Select(x => $"{x.Name}={x.Value}/{x.Text}"));
        }
        return null;
    }

    private static string? ConvertGuardedRefreshTiming(CardDatabase db)
    {
        using var movement=InstallMovementObserverProbes();
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool frontline in new[]{false,true})
        foreach(bool oldGuard in new[]{false,true})
        foreach(int newGuard in Enumerable.Range(0,3))
        foreach(bool hidden in new[]{false,true})
        foreach(bool lastGuard in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);var where=frontline?CardLocation.BoardFrontline:side.HqOf();int start=frontline?0:1;
            state.Hq(side).Keywords.Remove(Keyword.Guard);state.Hq(side.Opposite()).IsBeingGuarded=true;
            var first=state.CreateWithId(PlainUnit,side,70,where,start);first.Keywords.Remove(Keyword.Guard);first.IsBeingGuarded=!lastGuard;
            var old=state.CreateWithId("card_unit_typhoon_mk_ib",side,60,where,start+1);
            old.Definition=new CardDefinition{Name=old.Name,Type="infantry",UsedTriggers=new[]{"OnCardLocationMoved"}};
            old.Keywords.Remove(Keyword.Guard);if(oldGuard)old.Keywords.Add(Keyword.Guard);
            var last=state.CreateWithId(PlainUnit,frontline?side.Opposite():side,71,where,start+2);
            last.Keywords.Remove(Keyword.Guard);if(lastGuard)last.Keywords.Add(Keyword.Guard);last.IsBeingGuarded=true;
            var discarded=state.CreateWithId(PlainUnit,side,200,CardLocation.Discard,77);
            var observer=state.CreateWithId("card_event_honorifics",side,90,side.DeckOf(),0);
            observer.Definition=new CardDefinition{Name=observer.Name,UsedTriggers=new[]{"OnOtherCardLocationMoved"}};
            CardInstance? replacement=null;int removed=0,inserted=0;string? failure=null;var created=state.CardCreated;
            state.CardCreated=made=>{created?.Invoke(made);
                if(made.Name==old.Name&&made.CardId!=old.CardId)
                {
                    if(first.IsBeingGuarded!=lastGuard||last.IsBeingGuarded)failure="替代卡创建前须先刷新移除旧卡后的掩护";
                    replacement=made;made.Definition=new CardDefinition{Name=made.Name,Type="infantry",UsedTriggers=new[]{"OnCardLocationMoved"}};
                    made.Keywords.Remove(Keyword.Guard);made.Keywords.Remove(Keyword.Covert);made.Keywords.Remove(Keyword.Smokescreen);
                    if(newGuard==1)made.Keywords.Add(Keyword.Guard);
                    if(newGuard==2)made.ReceivedAbilitiesFromCards["guard"]=new List<int>{9};
                    if(hidden){made.Keywords.Add(Keyword.Covert);made.IsRevealed=false;}else made.IsRevealed=true;
                    made.IsBeingGuarded=true;
                }
                else if(made.Name=="card_unit_routed_troops")
                {
                    if(replacement is null)
                    {
                        removed++;
                        if(first.LocationNumber!=start||last.LocationNumber!=start+1||first.IsBeingGuarded!=lastGuard||last.IsBeingGuarded)
                            failure="转换旧卡离场的移动回调未看到首次重排/掩护刷新";
                    }
                    else
                    {
                        inserted++;bool rawNew=newGuard==1&&!hidden;
                        bool expectedNew=(newGuard==0||hidden)&&lastGuard;
                        if(first.LocationNumber!=start||replacement.LocationNumber!=start+1||last.LocationNumber!=start+2
                            ||first.IsBeingGuarded!=rawNew||replacement.IsBeingGuarded!=expectedNew||last.IsBeingGuarded!=(!lastGuard&&rawNew))
                            failure="转换新卡插入的移动回调未看到二次重排/掩护刷新";
                    }
                    if(old.Location!=CardLocation.Discard||old.LocationNumber!=start+1||discarded.LocationNumber!=77)
                        failure="转换旧卡进弃牌应保持编号且不重排既有弃牌";
                    if(!state.Hq(side.Opposite()).IsBeingGuarded)failure="转换刷新误改无关位置缓存";
                }
            };
            var result=engine.Api.InvokeByName("ConvertCard",null,new object?[]{new[]{60},60,old.Name,0,true,null},
                new EffectContext{Engine=engine,State=state,Self=old,Controller=side},out bool handled);
            if(!handled||result is not List<int> ids||ids.Count!=1||replacement?.CardId!=ids[0]||removed!=2||inserted!=2||failure is not null)
                return $"{failure??"转换刷新探针次数或输出错误"}：{side}/{frontline}/{oldGuard}/{newGuard}/{hidden}/{lastGuard}, callbacks={removed}/{inserted}";
        }
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(CardLocation location in new[]{side.HandOf(),side.DeckOf(),CardLocation.Discard})
        {
            var(engine,state)=EmptyBoard(db);var old=state.CreateWithId(PlainUnit,side,60,location,7);
            var discarded=state.CreateWithId(PlainUnit,side.Opposite(),200,CardLocation.Discard,77);
            engine.Api.InvokeByName("ConvertCard",null,new object?[]{new[]{60},60,PlainUnit,0,true,null},
                new EffectContext{Engine=engine,State=state,Self=old,Controller=side},out _);
            if(old.Location!=CardLocation.Discard||old.LocationNumber!=7||discarded.LocationNumber!=77)
                return "非棋盘转换同样使用保留弃牌编号的设置位置语义";
        }
        return null;
    }

    private static string? SpawnGuardedRefreshTiming(CardDatabase db)
    {
        using var movement=InstallMovementObserverProbes();
        const string watcher="card_event_honorifics",gain="OnAfterOtherCardGainDefense",spawnName="card_unit_typhoon_mk_ib";
        if(KismetLibrary.Default?.Find(watcher)?.Locals is not IDictionary<string,IReadOnlyList<KismetStep>> locals
            ||KismetLibrary.Default.FindProgram(watcher,gain) is not null)return "无法安全安装生成Alpine时序探针";
        locals.Add(gain,new[]{new KismetStep(0,"call","SpawnCardInDeckBySide",new[]{new KismetExpr{Int=(int)Side.Right},
                new KismetExpr{Str="card_unit_routed_troops"},new KismetExpr{Int=30},new KismetExpr{Int=1}},
                Array.Empty<int>(),null,null,-1,null,null),
            new KismetStep(1,"return",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),null,null,-1,null,null)});
        using var cleanup=new AuditProbeCleanup(()=>locals.Remove(gain));
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool frontline in new[]{false,true})
        foreach(int ownGuard in Enumerable.Range(0,3))
        foreach(bool hidden in new[]{false,true})
        foreach(bool residentGuard in new[]{false,true})
        foreach(bool alpine in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);var where=frontline?CardLocation.BoardFrontline:side.HqOf();
            state.Hq(side).Keywords.Remove(Keyword.Guard);state.Hq(side.Opposite()).IsBeingGuarded=true;
            int offset=frontline?0:1;
            var first=state.CreateWithId(PlainUnit,side,70,where,offset);
            var last=state.CreateWithId(PlainUnit,frontline?side.Opposite():side,71,where,offset+1);
            foreach(var card in new[]{first,last}){card.Keywords.Remove(Keyword.Guard);if(residentGuard)card.Keywords.Add(Keyword.Guard);card.IsBeingGuarded=true;}
            first.Keywords.Add(Keyword.Alpine);
            var observer=state.CreateWithId(watcher,side,90,side.DeckOf(),0);
            observer.Definition=new CardDefinition{Name=watcher,UsedTriggers=new[]{gain,"OnOtherCardLocationMoved"}};
            CardInstance? spawned=null;int before=0,after=0;string? failure=null;var created=state.CardCreated;
            state.CardCreated=made=>{created?.Invoke(made);
                if(made.Name==spawnName&&spawned is null)
                {
                    spawned=made;made.Definition=new CardDefinition{Name=spawnName,Type="infantry",Attack=2,Defense=5,UsedTriggers=new[]{"OnCardLocationMoved"}};
                    made.Attack=2;made.Defense=made.MaxDefense=5;made.IsBeingGuarded=true;
                    made.Keywords.Remove(Keyword.Guard);made.Keywords.Remove(Keyword.Covert);made.Keywords.Remove(Keyword.Alpine);
                    if(ownGuard==1)made.Keywords.Add(Keyword.Guard);
                    if(ownGuard==2)made.ReceivedAbilitiesFromCards["guard"]=new List<int>{9};
                    if(hidden){made.Keywords.Add(Keyword.Covert);made.IsRevealed=false;}else made.IsRevealed=true;
                    if(alpine)made.Keywords.Add(Keyword.Alpine);
                }
                else if(made.Name=="card_unit_routed_troops"&&spawned is not null)
                {
                    bool moving=Equals(spawned.BlueprintVariables.GetValueOrDefault("_auditMovementCalled"),true);
                    if(!moving)
                    {
                        before++;
                        if(!spawned.IsBeingGuarded||!first.IsBeingGuarded||!last.IsBeingGuarded)failure="Alpine加成回调不应提前刷新掩护缓存";
                    }
                    else
                    {
                        after++;
                        bool expected=(ownGuard==0||hidden)&&residentGuard;
                        bool lastExpected=!residentGuard&&ownGuard==1&&!hidden;
                        if(spawned.IsBeingGuarded!=expected||first.IsBeingGuarded||last.IsBeingGuarded!=lastExpected
                            ||!state.Hq(side.Opposite()).IsBeingGuarded)failure="生成移动回调未看到物理位置更新后的掩护缓存";
                        var numbers=state.AllCardsInBattleOrder.Where(c=>c.Location==where).Select(c=>c.LocationNumber).OrderBy(x=>x).ToArray();
                        if(!numbers.SequenceEqual(Enumerable.Range(0,numbers.Length)))failure="生成移动回调前物理编号未压紧";
                        int bonus=alpine&&!hidden?1:0;
                        if(spawned.Attack!=2+bonus||spawned.Defense!=5+bonus)failure="移动回调前Alpine加成应已经完成";
                    }
                }
            };
            var result=engine.Api.SpawnOnBattlefield(side,spawnName,frontline:frontline);
            if(!ReferenceEquals(result,spawned)||before!=(alpine&&!hidden?1:0)||after!=2||failure is not null)
                return $"{failure??"生成时序探针次数错误"}：{side}/{frontline}/{ownGuard}/{hidden}/{residentGuard}/{alpine}, before={before}, after={after}";
        }
        return null;
    }

    private static IDisposable InstallDeathObserverProbe()
    {
        const string name="card_unit_typhoon_mk_ib",trigger="OnDestroyed";
        if(KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string,IReadOnlyList<KismetStep>> locals
            ||KismetLibrary.Default.FindProgram(name,trigger) is not null)throw new InvalidOperationException("无法安全安装亡语缓存探针");
        locals.Add(trigger,new[]{
            new KismetStep(0,"set",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),new KismetExpr{Bool=true},null,-1,"_auditBatchDestroyed",null){DestinationScope="instance"},
            new KismetStep(1,"call","SpawnCardInDeckBySide",new[]{new KismetExpr{Int=(int)Side.Right},new KismetExpr{Str="card_unit_routed_troops"},
                new KismetExpr{Int=30},new KismetExpr{Int=1}},Array.Empty<int>(),null,null,-1,null,null),
            new KismetStep(2,"return",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),null,null,-1,null,null)});
        return new AuditProbeCleanup(()=>locals.Remove(trigger));
    }

    private static string? SameFrontlineCombatPairRefresh(CardDatabase db) => SameFrontlineCombatPairRefresh(db,false);
    private static string? CombatPairOldLocationCapture(CardDatabase db) => SameFrontlineCombatPairRefresh(db,true);

    private static IDisposable InstallCombatPayloadProbes(bool onlyDestroyed = false)
    {
        var installed=new List<(IDictionary<string,IReadOnlyList<KismetStep>> Locals,string Trigger)>();
        foreach(var spec in new[]{
            ("card_unit_typhoon_mk_ib","OnAfterLeaveBoard",new[]{("goingToLocation","New")}),
            ("card_unit_typhoon_mk_ib","OnAfterOtherCardLeaveBoardOrOwner",new[]{("cardLeaving","Card"),("OldLocation","Old")}),
            ("card_unit_typhoon_mk_ib","OnOtherCardDestroyed",new[]{("cardDestroyed","Card"),("destroyedLocation","Old"),
                ("killer","Killer"),("destroyedInCombat","Combat"),("selfIsAlsoGettingDestroyed","Also"),("TriggerNotDestroyed","Repeat")})})
        {
            if(onlyDestroyed&&spec.Item2!="OnOtherCardDestroyed")continue;
            var locals=(IDictionary<string,IReadOnlyList<KismetStep>>)KismetLibrary.Default!.Find(spec.Item1)!.Locals!;
            if(KismetLibrary.Default.FindProgram(spec.Item1,spec.Item2) is not null)
            {
                foreach(var item in installed)item.Locals.Remove(item.Trigger);
                throw new InvalidOperationException("无法安全安装死亡参数探针："+spec.Item1+" "+spec.Item2);
            }
            var steps=new List<KismetStep>();
            void Store(string field,KismetExpr value)=>steps.Add(new KismetStep(steps.Count,"set",null,
                Array.Empty<KismetExpr>(),Array.Empty<int>(),value,null,-1,field,null){DestinationScope="instance"});
            Store("_auditDeathPayloadSerial",new KismetExpr{Math="Add_IntInt",Args=new[]{new KismetExpr{Var="_auditDeathPayloadSerial",Scope="instance"},new KismetExpr{Int=1}}});
            Store("_auditDeathPayloadKind",new KismetExpr{Str=spec.Item2});
            foreach(var field in spec.Item3)Store("_auditPayload"+field.Item2,new KismetExpr{Var="K2Node_Event_"+field.Item1});
            steps.Add(new KismetStep(steps.Count,"call","SpawnCardInDeckBySide",new[]{new KismetExpr{Int=(int)Side.Right},new KismetExpr{Str="card_unit_routed_troops"},
                new KismetExpr{Int=30},new KismetExpr{Int=1}},Array.Empty<int>(),null,null,-1,null,null));
            steps.Add(new KismetStep(steps.Count,"return",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),null,null,-1,null,null));
            locals.Add(spec.Item2,steps);installed.Add((locals,spec.Item2));
        }
        return new AuditProbeCleanup(()=>{foreach(var item in installed)item.Locals.Remove(item.Trigger);});
    }

    private static string? OwnershipLeaveMutation(CardDatabase db)
    {
        const string name="card_unit_m36_destroyer",trigger="OnLeaveBoardOrOwner";
        var locals=(IDictionary<string,IReadOnlyList<KismetStep>>)KismetLibrary.Default!.Find(name)!.Locals!;
        if(KismetLibrary.Default.FindProgram(name,trigger) is not null)return "无法安全安装换主离场探针";
        locals.Add(trigger,new[]{new KismetStep(0,"call","SpawnCardInDeckBySide",new[]{new KismetExpr{Int=(int)Side.Right},new KismetExpr{Str="card_unit_routed_troops"},
            new KismetExpr{Int=30},new KismetExpr{Int=1}},Array.Empty<int>(),null,null,-1,null,null),
            new KismetStep(1,"return",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),null,null,-1,null,null)});
        using var cleanup=new AuditProbeCleanup(()=>locals.Remove(trigger));
        foreach(Side from in new[]{Side.Left,Side.Right})
        foreach(int route in Enumerable.Range(0,3)) // take support / release support / release same frontline
        foreach(int occupancyChange in Enumerable.Range(0,3)) // none / append / remove resident
        foreach(bool ownerAlreadyChanged in new[]{false,true})
        foreach(bool changeNumber in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);Side to=from.Opposite();bool release=route!=0;
            var old=route==2?CardLocation.BoardFrontline:from.HqOf();var destination=route==2?old:to.HqOf();
            var mover=state.CreateWithId(name,from,60,old,route==2?1:20);
            mover.Definition=new CardDefinition{Name=name,Type="infantry",UsedTriggers=new[]{trigger}};mover.Keywords.Clear();
            mover.HasMovedThisTurn=true;mover.HasAttackedThisTurn=true;mover.AttacksThisTurn=1;mover.SetRemainingAttacks(0);
            var a=state.CreateWithId(PlainUnit,to,70,destination,route==2?0:1);
            var b=state.CreateWithId(PlainUnit,to,71,destination,2);a.Keywords.Clear();b.Keywords.Clear();
            state.FrontlineOwner=to;int leaves=0,moves=0;string? failure=null;var created=state.CardCreated;
            state.CardCreated=made=>{created?.Invoke(made);if(made.Name!="card_unit_routed_troops")return;
                leaves++;
                if(occupancyChange==1){var added=state.CreateWithId(PlainUnit,to,72,destination,100);added.Keywords.Clear();}
                if(occupancyChange==2)state.Remove(a);
                if(changeNumber)mover.LocationNumber=77;
                if(ownerAlreadyChanged&&!state.ChangeOwner(mover,to,normalize:false))failure="未制造离场中改主状态";
            };
            var prior=state.CardMoved;
            state.CardMoved=(card,fromLocation,toLocation,changed,reason)=>{
                if(ReferenceEquals(card,mover))
                {
                    moves++;
                    int expectedSlot=route==0?(occupancyChange==2?2:3):0;
                    if(card.Owner!=to||card.Location!=destination||card.LocationNumber!=expectedSlot||fromLocation!=old||toLocation!=destination||!changed)
                        failure="换主离场回调后应继续原位置流程";
                    var owner=state.ActionLog.SelectMany(a=>a.SubActions).SingleOrDefault(a=>a.Name=="ZActionChangeUnitOwnership");
                    var move=state.ActionLog.SelectMany(a=>a.SubActions).SingleOrDefault(a=>a.Name=="ZActionMoveCardToNewLocation");
                    if(owner is null||move is null)failure="离场已改主不能漏掉后续通知";
                    else if(move.Values.First(v=>v.Name=="newLocationNumber").Value!=(route==0?3:0)
                        ||move.Values.First(v=>v.Name=="nonVisualLocationNumber").Value!=(route==0?3:0)
                        ||move.Values.First(v=>v.Name=="movementLeft").Value!=(release?0:1)
                        ||move.Values.First(v=>v.Name=="attackLeft").Value!=(release?0:1)
                        ||owner.Values.First(v=>v.Name=="oldSide").Text!=(from==Side.Left?"left":"right"))
                        failure="占用/卡编号/控制方变化后仍应使用保存插槽及旧阵营，额度依分支处理";
                }
                prior?.Invoke(card,fromLocation,toLocation,changed,reason);
            };
            bool success=engine.ChangeUnitOwnership(mover,9004,from,to,destination,release);
            if(!success||leaves!=1||moves!=1||failure is not null
                ||state.Cards(to,destination).Count(c=>ReferenceEquals(c,mover))!=1||state.Cards(from,old).Any(c=>ReferenceEquals(c,mover)))
                return $"{failure??"离场已改主不应提前失败或破坏阵营索引"}：{from}/{route}/{occupancyChange}/{ownerAlreadyChanged}/{changeNumber}, result={success}, leave={leaves}, move={moves}";
        }
        return null;
    }

    private static string? OwnershipSlotAndMoveNotification(CardDatabase db) => OwnershipSlotAndMoveNotification(db,false);
    private static string? OwnershipNotificationPayload(CardDatabase db) => OwnershipSlotAndMoveNotification(db,true);

    private static string? OwnershipSlotAndMoveNotification(CardDatabase db, bool checkOwnershipPayload)
    {
        foreach(Side from in new[]{Side.Left,Side.Right})
        foreach(int route in Enumerable.Range(0,5)) // take support / release support / lone take front / release front / blocked release front
        foreach(bool sparse in new[]{false,true})
        foreach(bool fury in new[]{false,true})
        foreach(int sourceId in new[]{0,9004})
        {
            var(engine,state)=EmptyBoard(db);Side to=from.Opposite();bool release=route is 1 or 3 or 4;
            var old=route>=2?CardLocation.BoardFrontline:from.HqOf();var dest=route>=2?old:to.HqOf();
            var mover=state.CreateWithId(PlainUnit,from,60,old,sparse?20:1);
            mover.Definition=new CardDefinition{Name=mover.Name,Type="infantry",Attack=2,Defense=5};mover.Keywords.Clear();
            if(fury)mover.Keywords.Add(Keyword.Fury);
            mover.HasMovedThisTurn=true;mover.HasAttackedThisTurn=true;mover.AttacksThisTurn=1;mover.SetRemainingAttacks(0);
            CardInstance? a=null,b=null;
            if(route!=2)
            {
                a=state.CreateWithId(PlainUnit,to,70,dest,sparse?10:route>=3?0:1);
                b=state.CreateWithId(PlainUnit,to,71,dest,sparse?30:2);
                a.Keywords.Clear();b.Keywords.Clear();
            }
            state.FrontlineOwner=route==4?from:to;
            int planned=route==0?3:route==4?(sparse?20:1):0;
            int expectedSlot=route==0?(sparse?1:3):route==4?(sparse?2:1):0;
            int calls=0;string? failure=null;var prior=state.CardMoved;
            state.CardMoved=(card,oldLocation,newLocation,changed,reason)=>{
                if(ReferenceEquals(card,mover)&&reason==(release?CardMoveReason.ControlRelease:CardMoveReason.ControlTake))
                {
                    calls++;
                    if(card.LocationNumber!=expectedSlot||card.Location!=dest||oldLocation!=old||newLocation!=dest||!changed)
                        failure="控制权原生插入位置/同区留空或物理压紧错误";
                    if(route==0&&(state.Hq(to).LocationNumber!=0||a!.LocationNumber!=(sparse?2:1)||b!.LocationNumber!=(sparse?3:2)))failure="夺取应以旧数量插槽注入";
                    if(route==1&&(state.Hq(to).LocationNumber!=1||a!.LocationNumber!=2||b!.LocationNumber!=3))failure="释放应在0号注入且移动总部与住牌";
                    if(route is 3 or 4&&(a!.LocationNumber!=(expectedSlot==0?1:0)||b!.LocationNumber!=(expectedSlot==2?1:2)))failure="同区注入必须先紧排其他卡再留空";
                    var actions=state.ActionLog.SelectMany(x=>x.SubActions).ToArray();
                    if(checkOwnershipPayload)
                    {
                        var owners=actions.Where(x=>x.Name=="ZActionChangeUnitOwnership").ToArray();
                        if(owners.Length!=1||!owners[0].Values.Select(v=>v.Name).SequenceEqual(new[]{"cardID","instigatorID","oldLocation","oldSide","newLocation","newSide","releaseControl"}))
                            failure="换主专用通知须按原生顺序包含cardID等7字段";
                        else
                        {
                            var v=owners[0].Values.ToDictionary(v=>v.Name);
                            string oldText=old==CardLocation.BoardFrontline?"Board_Frontline":from==Side.Left?"Board_HQLeft":"Board_HQRight";
                            string newText=dest==CardLocation.BoardFrontline?"Board_Frontline":to==Side.Left?"Board_HQLeft":"Board_HQRight";
                            if(v["cardID"].Value!=card.CardId||v["instigatorID"].Value!=sourceId||v["releaseControl"].Value!=(release?1:0)
                                ||v["cardID"].Text!=""||v["instigatorID"].Text!=""||v["releaseControl"].Text!=""
                                ||v["oldLocation"].Text!=oldText||v["newLocation"].Text!=newText
                                ||v["oldSide"].Text!=(from==Side.Left?"left":"right")||v["newSide"].Text!=(to==Side.Left?"left":"right")
                                ||new[]{"oldLocation","newLocation","oldSide","newSide"}.Any(key=>v[key].Value!=-1))failure="换主字段编码应为数字ID/布尔与-1加枚举文本";
                        }
                    }
                    var moves=actions.Where(x=>x.Name=="ZActionMoveCardToNewLocation").ToArray();
                    if(moves.Length!=1)failure="控制权须在移动回调前写独立移动通知";
                    else
                    {
                        var v=moves[0].Values.ToDictionary(x=>x.Name);
                        string oldName=old==CardLocation.BoardFrontline?"Board_Frontline":from==Side.Left?"Board_HQLeft":"Board_HQRight";
                        string newName=dest==CardLocation.BoardFrontline?"Board_Frontline":to==Side.Left?"Board_HQLeft":"Board_HQRight";
                        if(v.Count!=9||v["cardID"].Value!=card.CardId||v["instigatorID"].Value!=sourceId
                            ||v["newLocationNumber"].Value!=planned||v["nonVisualLocationNumber"].Value!=planned
                            ||v["movementLeft"].Value!=(release?0:1)||v["attackLeft"].Value!=(release?0:fury?2:1)
                            ||v["oldLocation"].Text!=oldName||v["newLocation"].Text!=newName||v["moveReason"].Text!=(release?"Control_Release":"Control_Take"))failure="控制权移动通知应保留计划编号而非刷新后编号";
                        if(Array.FindIndex(actions,x=>x.Name=="ZActionChangeUnitOwnership")>=Array.FindIndex(actions,x=>x.Name=="ZActionMoveCardToNewLocation"))failure="换主通知必须先于移动通知";
                    }
                }
                prior?.Invoke(card,oldLocation,newLocation,changed,reason);
            };
            if(!engine.ChangeUnitOwnership(mover,sourceId,from,to,dest,release)||calls!=1||failure is not null)
                return $"{failure??"控制权位置回调次数错误"}：{from}/{route}/{sparse}/{fury}/{sourceId}";
            if(route==4&&mover.Location!=to.HqOf())return "受阻前线释放应在恢复位置和进场后退却";
        }
        return null;
    }

    private static string? OwnershipGuardedRefresh(CardDatabase db)
    {
        foreach(Side from in new[]{Side.Left,Side.Right})
        foreach(int route in Enumerable.Range(0,4)) // take support / release support / take lone front / release same front
        foreach(int ownGuard in Enumerable.Range(0,3))
        foreach(bool hidden in new[]{false,true})
        foreach(bool residentGuard in new[]{false,true})
        foreach(bool fury in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);Side to=from.Opposite();bool release=route is 1 or 3;
            var old=route>=2?CardLocation.BoardFrontline:from.HqOf();var dest=route>=2?old:to.HqOf();
            var mover=state.CreateWithId(PlainUnit,from,60,old,20);
            mover.Definition=new CardDefinition{Name=mover.Name,Type="infantry",Attack=2,Defense=5};mover.Keywords.Clear();
            if(ownGuard==1)mover.Keywords.Add(Keyword.Guard);
            if(ownGuard==2)mover.ReceivedAbilitiesFromCards["guard"]=new List<int>{9};
            if(hidden){mover.Keywords.Add(Keyword.Covert);mover.IsRevealed=false;}
            if(fury)mover.Keywords.Add(Keyword.Fury);
            mover.HasMovedThisTurn=true;mover.HasAttackedThisTurn=true;mover.AttacksThisTurn=1;mover.AttackQuotaOffset=-1;mover.IsBeingGuarded=true;int releaseAttacks=mover.RemainingAttacks;
            var oldNeighbors=new List<CardInstance>();
            if(route<2)
                foreach(int id in new[]{50,51})
                {
                    var neighbor=state.CreateWithId(PlainUnit,from,id,old,id==50?10:30);neighbor.Keywords.Clear();neighbor.IsBeingGuarded=true;oldNeighbors.Add(neighbor);
                }
            var residents=new List<CardInstance>();
            if(route!=2)
                foreach(int id in new[]{70,71})
                {
                    var resident=state.CreateWithId(PlainUnit,to,id,dest,(route==3?0:1)+id-70);resident.Keywords.Clear();
                    if(residentGuard)resident.Keywords.Add(Keyword.Guard);resident.IsBeingGuarded=true;residents.Add(resident);
                }
            state.Hq(from).Keywords.Clear();state.Hq(to).Keywords.Clear();state.Hq(from).IsBeingGuarded=true;state.Hq(to).IsBeingGuarded=true;
            state.FrontlineOwner=to;int calls=0;string? failure=null;var prior=state.CardMoved;
            state.CardMoved=(card,fromLocation,toLocation,changed,reason)=>{
                if(ReferenceEquals(card,mover))
                {
                    calls++;bool Near(CardInstance left,CardInstance right)=>Math.Abs(left.LocationNumber-right.LocationNumber)==1;
                    if(card.Owner!=to||card.UnderEnemyControl==release||fromLocation!=old||toLocation!=dest||!changed
                        ||reason!=(release?CardMoveReason.ControlRelease:CardMoveReason.ControlTake))failure="控制权移动上下文错误";
                    if(card.HasMovedThisTurn!=release||card.HasAttackedThisTurn!=release||card.AttacksThisTurn!=(release?1:0)
                        ||card.AttackQuotaOffset!=(release?-1:0)||card.RemainingAttacks!=(release?releaseAttacks:fury?2:1))failure="夺取必须在回调前重置额度，释放必须保持额度";
                    bool expectedMover=(ownGuard==0||hidden)&&residentGuard&&residents.Any(r=>Near(r,card));
                    if(card.IsBeingGuarded!=expectedMover||oldNeighbors.Any(n=>n.IsBeingGuarded))failure="控制权回调读取旧掩护";
                    foreach(var resident in residents)
                        if(resident.IsBeingGuarded!=(!residentGuard&&ownGuard==1&&!hidden&&Near(resident,card)))failure="控制权邻卡raw/source/Covert掩护错误";
                    if(route<2)
                    {
                        bool expectedHq=residentGuard&&residents.Any(r=>Near(r,state.Hq(to)))||ownGuard==1&&!hidden&&Near(card,state.Hq(to));
                        if(state.Hq(from).IsBeingGuarded||state.Hq(to).IsBeingGuarded!=expectedHq)failure="跨区换主应刷新双方支援缓存";
                    }
                    else if(!state.Hq(from).IsBeingGuarded||!state.Hq(to).IsBeingGuarded)failure="同前线换主不得刷新支援缓存";
                    foreach(var zone in new[]{old,dest}.Distinct())
                    {
                        var numbers=state.AllCardsInBattleOrder.Where(c=>c.Location==zone).Select(c=>c.LocationNumber).OrderBy(n=>n).ToArray();
                        if(!numbers.SequenceEqual(Enumerable.Range(0,numbers.Length)))failure="控制权回调前物理区域未压紧";
                    }
                    if(state.ActionLog.SelectMany(a=>a.SubActions).Count(a=>a.Name=="ZActionChangeUnitOwnership")!=1)failure="控制权通知须先于位置回调";
                }
                prior?.Invoke(card,fromLocation,toLocation,changed,reason);
            };
            if(!engine.ChangeUnitOwnership(mover,9004,from,to,dest,release)||calls!=1||failure is not null)
                return $"{failure??"控制权回调次数错误"}：{from}/{route}/{ownGuard}/{hidden}/{residentGuard}/{fury}, callbacks={calls}";
        }
        return null;
    }

    private static string? RetreatGuardedRefresh(CardDatabase db)
    {
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(int ownGuard in Enumerable.Range(0,3))
        foreach(bool hidden in new[]{false,true})
        foreach(bool residentGuard in new[]{false,true})
        foreach(int sourceId in new[]{0,9004})
        {
            var(engine,state)=EmptyBoard(db);var old=CardLocation.BoardFrontline;var destination=side.HqOf();
            var oldA=state.CreateWithId(PlainUnit,side,50,old,10);
            var mover=state.CreateWithId(PlainUnit,side,60,old,20);
            var oldB=state.CreateWithId(PlainUnit,side.Opposite(),51,old,30);
            mover.Definition=new CardDefinition{Name=mover.Name,Type="infantry",Attack=2,Defense=5};mover.Keywords.Clear();
            if(ownGuard==1)mover.Keywords.Add(Keyword.Guard);
            if(ownGuard==2)mover.ReceivedAbilitiesFromCards["guard"]=new List<int>{9};
            if(hidden){mover.Keywords.Add(Keyword.Covert);mover.IsRevealed=false;}
            foreach(var card in new[]{oldA,oldB}){card.Keywords.Clear();card.IsBeingGuarded=true;}
            var a=state.CreateWithId(PlainUnit,side,70,destination,1);
            var b=state.CreateWithId(PlainUnit,side,71,destination,2);
            foreach(var card in new[]{a,b}){card.Keywords.Clear();if(residentGuard)card.Keywords.Add(Keyword.Guard);card.IsBeingGuarded=true;}
            var hq=state.Hq(side);hq.Keywords.Clear();hq.IsBeingGuarded=!residentGuard;
            var otherHq=state.Hq(side.Opposite());otherHq.IsBeingGuarded=true;
            mover.IsBeingGuarded=true;int attacks=mover.RemainingAttacks;int calls=0;string? failure=null;var prior=state.CardMoved;
            string oldName="Board_Frontline",newName=side==Side.Left?"Board_HQLeft":"Board_HQRight",reasonName="Retreat";
            state.CardMoved=(card,from,to,changed,reason)=>{
                if(ReferenceEquals(card,mover))
                {
                    calls++;
                    if(from!=old||to!=destination||changed||reason!=CardMoveReason.Retreat||!card.HasMovedThisTurn)
                        failure="退却移动上下文或额度错误";
                    if(oldA.LocationNumber!=0||oldB.LocationNumber!=1||hq.LocationNumber!=0||a.LocationNumber!=1||mover.LocationNumber!=2||b.LocationNumber!=3)
                        failure="退却回调前新旧物理位置未完成重排";
                    if(oldA.IsBeingGuarded||oldB.IsBeingGuarded||!otherHq.IsBeingGuarded||hq.IsBeingGuarded!=residentGuard
                        ||mover.IsBeingGuarded!=((ownGuard==0||hidden)&&residentGuard)
                        ||a.IsBeingGuarded!=(!residentGuard&&ownGuard==1&&!hidden)||b.IsBeingGuarded!=(!residentGuard&&ownGuard==1&&!hidden))
                        failure="退却回调读取旧掩护缓存或误更新无关区域";
                    var notices=state.ActionLog.SelectMany(x=>x.SubActions).Where(x=>x.Name=="ZActionMoveCardToNewLocation").ToArray();
                    if(notices.Length!=1)failure="退却须在移动回调前写一次移动通知";
                    else
                    {
                        var v=notices[0].Values.ToDictionary(x=>x.Name);
                        if(v.Count!=9||v["cardID"].Value!=mover.CardId||v["instigatorID"].Value!=sourceId
                            ||v["newLocationNumber"].Value!=2||v["nonVisualLocationNumber"].Value!=2||v["movementLeft"].Value!=0||v["attackLeft"].Value!=attacks
                            ||v["oldLocation"].Text!=oldName||v["newLocation"].Text!=newName||v["moveReason"].Text!=reasonName)failure="退却移动通知字段错误";
                    }
                }
                prior?.Invoke(card,from,to,changed,reason);
            };
            engine.Api.InvokeByName("MakeCardRetreat",null,new object?[]{new[]{mover.CardId},sourceId},
                new EffectContext{Engine=engine,State=state,Self=mover,Controller=side},out bool handled);
            if(!handled||calls!=1||failure is not null)return $"{failure??"退却移动未执行"}：{side}/{ownGuard}/{hidden}/{residentGuard}/{sourceId}";
        }
        return null;
    }

    private static IDisposable InstallExternalDeathProbes()
    {
        const string name="card_unit_m36_destroyer",other="OnOtherCardDestroyed",notify="OnDestructionEffectTriggered";
        var locals=(IDictionary<string,IReadOnlyList<KismetStep>>)KismetLibrary.Default!.Find(name)!.Locals!;
        if(KismetLibrary.Default.FindProgram(name,other) is not null||KismetLibrary.Default.FindProgram(name,notify) is not null)throw new InvalidOperationException("无法安全安装外部亡语探针");
        KismetStep Store(int i,string field,KismetExpr value,string scope="instance")=>new(i,"set",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),value,null,-1,field,null){DestinationScope=scope};
        KismetStep Count(string field)=>Store(0,field,new KismetExpr{Math="Add_IntInt",Args=new[]{new KismetExpr{Var=field,Scope="instance"},new KismetExpr{Int=1}}});
        KismetStep Marker(int i)=>new(i,"call","SpawnCardInDeckBySide",new[]{new KismetExpr{Int=(int)Side.Right},new KismetExpr{Str="card_unit_routed_troops"},new KismetExpr{Int=30},new KismetExpr{Int=1}},Array.Empty<int>(),null,null,-1,null,null);
        KismetStep Return(int i)=>new(i,"return",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),null,null,-1,null,null);
        var program=new List<KismetStep>{Count("_auditExternalCount")};
        foreach(var field in new[]{("cardDestroyed","Card"),("killer","Killer"),("TriggerNotDestroyed","Repeat"),
            ("destroyedLocation","Old"),("selfIsAlsoGettingDestroyed","Also"),("destroyedInCombat","Combat")})
            program.Add(Store(program.Count,"_auditExternal"+field.Item2,new KismetExpr{Var="K2Node_Event_"+field.Item1}));
        program.Add(Marker(program.Count));program.Add(Return(program.Count));locals.Add(other,program);
        // Identical notification program to RepeatedDeathHeldRecipient: reuse its cached local safely.
        locals.Add(notify,new[]{Count("_auditRepeatCalls"),Marker(1),Store(2,"TriggerMultiple",new KismetExpr{Var="_auditRepeatOutput",Scope="instance"},"local"),Return(3)});
        return new AuditProbeCleanup(()=>{locals.Remove(other);locals.Remove(notify);});
    }

    private static string? MultipleExternalDeathProviders(CardDatabase db)
    {
        using var probes=InstallExternalDeathProbes();
        const string name="card_unit_m36_destroyer",other="OnOtherCardDestroyed",notify="OnDestructionEffectTriggered";
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool reverseCreate in new[]{false,true})
        foreach(int sourceChange in Enumerable.Range(0,3)) // keep / remove later source / add later source
        foreach(bool suppressed in new[]{false,true})
        foreach(bool duplicates in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);
            var victim=state.CreateWithId(PlainUnit,side,60,side.HqOf(),1);victim.Keywords.Clear();
            if(suppressed)victim.Keywords.Add(Keyword.Suppressed);
            foreach(int id in reverseCreate?new[]{62,61}:new[]{61,62})
            {
                var card=state.CreateWithId(name,id==61?side:side.Opposite(),id,side.DeckOf(),id-61);
                card.Definition=new CardDefinition{Name=name,UsedTriggers=new[]{other}};
            }
            var selected=engine.Api.CaptureRegisteredTriggerSnapshot(other).ToArray();
            if(selected.Length!=2)return "多提供者T39夹具错误";
            var first=selected[0];var later=selected[1];
            var sources=new List<int>{first.CardId};if(sourceChange!=2)sources.Add(later.CardId);
            if(duplicates)sources.AddRange(sources.ToArray());victim.ReceivedAbilitiesFromCards["destruction"]=sources;
            var watcher=state.CreateWithId(name,side.Opposite(),64,side.Opposite().DeckOf(),0);
            watcher.Definition=new CardDefinition{Name=name,UsedTriggers=new[]{notify}};
            watcher.BlueprintVariables["_auditRepeatOutput"]=1;
            var killer=state.CreateWithId(PlainUnit,side.Opposite(),99,CardLocation.Discard,77);
            var seen=new Dictionary<int,int>();var order=new List<string>();CardInstance? late=null;
            int notifications=0;string? failure=null;var prior=state.CardCreated;
            state.CardCreated=made=>{prior?.Invoke(made);if(made.Name!="card_unit_routed_troops")return;
                foreach(var receiver in selected)
                {
                    int count=Convert.ToInt32(receiver.BlueprintVariables.GetValueOrDefault("_auditExternalCount"));
                    if(count<=seen.GetValueOrDefault(receiver.CardId))continue;
                    seen[receiver.CardId]=count;bool initial=count==1;string tag=ReferenceEquals(receiver,first)?"first":"later";
                    order.Add(tag+(initial?":false":":true"));var v=receiver.BlueprintVariables;
                    if(!ReferenceEquals(v.GetValueOrDefault("_auditExternalCard"),victim)||!ReferenceEquals(v.GetValueOrDefault("_auditExternalKiller"),killer)
                        ||!Equals(v.GetValueOrDefault("_auditExternalRepeat"),!initial)||Convert.ToInt32(v.GetValueOrDefault("_auditExternalOld"))!=(int)side.HqOf()
                        ||!Equals(v.GetValueOrDefault("_auditExternalAlso"),false)||!Equals(v.GetValueOrDefault("_auditExternalCombat"),false))failure="多提供者T39参数错误";
                    if(ReferenceEquals(receiver,first)&&initial)
                    {
                        if(sourceChange==1)sources.RemoveAll(id=>id==later.CardId);
                        if(sourceChange==2){sources.Add(later.CardId);if(duplicates)sources.Add(later.CardId);}
                        later.Definition=new CardDefinition{Name=name};later.Keywords.Add(Keyword.Suppressed);
                        state.Move(later,CardLocation.NotAvailable,9,notifyMoved:false,normalizeLocation:false);
                        late=state.CreateWithId(name,side,65,side.DeckOf(),0);
                        late.Definition=new CardDefinition{Name=name,UsedTriggers=new[]{other,notify}};
                        late.BlueprintVariables["_auditRepeatOutput"]=9;sources.Add(late.CardId);
                    }
                    return;
                }
                int countNotify=Convert.ToInt32(watcher.BlueprintVariables.GetValueOrDefault("_auditRepeatCalls"));
                if(countNotify>notifications){notifications=countNotify;order.Add("T24");return;}
                failure="迟注册接收者不得插入已保存的T39或T24数组";
            };
            engine.Destroy(victim,killer);
            var expected=new List<string>{"first:false","T24","first:true"};if(!suppressed)expected.Add("T24");
            expected.Add("later:false");
            if(sourceChange!=1){expected.Add("T24");expected.Add("later:true");if(!suppressed)expected.Add("T24");}
            if(failure is not null||!order.SequenceEqual(expected)||late is null
                ||late.BlueprintVariables.ContainsKey("_auditExternalCount")||late.BlueprintVariables.ContainsKey("_auditRepeatCalls"))
                return $"{failure??"多提供者来源重读/保存名单/去重语义错误"}：{side}/{reverseCreate}/{sourceChange}/{suppressed}/{duplicates}, order={string.Join(",",order)}";
        }
        return null;
    }

    private static string? ExternalDeathRepeatContract(CardDatabase db)
    {
        const string name="card_unit_m36_destroyer",other="OnOtherCardDestroyed",notify="OnDestructionEffectTriggered";
        using var cleanup=InstallExternalDeathProbes();
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(int budget in new[]{0,2})
        foreach(bool suppressed in new[]{false,true})
        foreach(int grantMode in Enumerable.Range(0,3)) // retained / added in first T39 / removed in first T39
        foreach(bool mutateProvider in new[]{false,true})
        foreach(int laterOutput in new[]{-2,7})
        {
            var(engine,state)=EmptyBoard(db);
            var victim=state.CreateWithId(PlainUnit,side,60,side.HqOf(),1);victim.Keywords.Clear();
            if(suppressed)victim.Keywords.Add(Keyword.Suppressed);
            var provider=state.CreateWithId(name,side,61,side.DeckOf(),0);
            provider.Definition=new CardDefinition{Name=name,UsedTriggers=new[]{other}};
            var watcher=state.CreateWithId(name,side.Opposite(),62,side.Opposite().DeckOf(),0);
            watcher.Definition=new CardDefinition{Name=name,UsedTriggers=new[]{notify}};
            var killer=state.CreateWithId(PlainUnit,side.Opposite(),99,CardLocation.Discard,77);
            if(grantMode!=1)victim.ReceivedAbilitiesFromCards["destruction"]=new List<int>{provider.CardId};
            int calls=0,notifications=0;var order=new List<string>();string? failure=null;var prior=state.CardCreated;
            state.CardCreated=made=>{prior?.Invoke(made);if(made.Name!="card_unit_routed_troops")return;
                int count=Convert.ToInt32(provider.BlueprintVariables.GetValueOrDefault("_auditExternalCount"));
                if(count>calls)
                {
                    calls=count;order.Add(calls==1?"other:false":"other:true");var v=provider.BlueprintVariables;
                    if(!ReferenceEquals(v.GetValueOrDefault("_auditExternalCard"),victim)||!ReferenceEquals(v.GetValueOrDefault("_auditExternalKiller"),killer)
                        ||!Equals(v.GetValueOrDefault("_auditExternalRepeat"),calls>1)||Convert.ToInt32(v.GetValueOrDefault("_auditExternalOld"))!=(int)side.HqOf()
                        ||!Equals(v.GetValueOrDefault("_auditExternalAlso"),false)||!Equals(v.GetValueOrDefault("_auditExternalCombat"),false))failure="外部亡语T39参数错误";
                    if(calls==1)
                    {
                        if(grantMode==1)victim.ReceivedAbilitiesFromCards["destruction"]=new List<int>{provider.CardId};
                        if(grantMode==2)victim.ReceivedAbilitiesFromCards.Remove("destruction");
                        if(mutateProvider)
                        {
                            provider.Definition=new CardDefinition{Name=name};provider.Keywords.Add(Keyword.Suppressed);
                            state.Move(provider,CardLocation.NotAvailable,9,notifyMoved:false,normalizeLocation:false);
                        }
                    }
                    else victim.ReceivedAbilitiesFromCards.Remove("destruction");
                }
                else
                {
                    notifications++;order.Add("T24");watcher.BlueprintVariables["_auditRepeatOutput"]=notifications==1?budget:laterOutput;
                    watcher.Definition=new CardDefinition{Name=name};watcher.Keywords.Add(Keyword.Suppressed);
                }
            };
            engine.Destroy(victim,killer);
            bool granted=grantMode!=2;int repeats=granted?budget:0;
            var expected=new List<string>{"other:false"};
            if(granted){expected.Add("T24");for(int i=0;i<repeats;i++){expected.Add("other:true");if(!suppressed)expected.Add("T24");}}
            int expectedNotify=!granted?0:suppressed?1:1+budget;
            if(failure is not null||calls!=1+repeats||notifications!=expectedNotify||!order.SequenceEqual(expected))
                return $"{failure??"外部亡语来源门/固定预算/抑制绕过或保存接收者错误"}：{side}/{budget}/{suppressed}/{grantMode}/{mutateProvider}/{laterOutput}, other={calls}, notify={notifications}";
        }
        return null;
    }

    private static string? RepeatedDeathHeldRecipient(CardDatabase db)
    {
        const string name="card_unit_m36_destroyer",own="OnDestroyed",notify="OnDestructionEffectTriggered",after="OnAfterDestroyed";
        var locals=(IDictionary<string,IReadOnlyList<KismetStep>>)KismetLibrary.Default!.Find(name)!.Locals!;
        if(KismetLibrary.Default.FindProgram(name,own) is not null||KismetLibrary.Default.FindProgram(name,notify) is not null||KismetLibrary.Default.FindProgram(name,after) is not null)
            return "无法安全安装重复亡语探针";
        KismetStep Store(int i,string field,KismetExpr value,string scope="instance")=>new(i,"set",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),value,null,-1,field,null){DestinationScope=scope};
        KismetStep Count()=>Store(0,"_auditRepeatCalls",new KismetExpr{Math="Add_IntInt",Args=new[]{new KismetExpr{Var="_auditRepeatCalls",Scope="instance"},new KismetExpr{Int=1}}});
        KismetStep Marker(int i)=>new(i,"call","SpawnCardInDeckBySide",new[]{new KismetExpr{Int=(int)Side.Right},new KismetExpr{Str="card_unit_routed_troops"},new KismetExpr{Int=30},new KismetExpr{Int=1}},Array.Empty<int>(),null,null,-1,null,null);
        KismetStep Return(int i)=>new(i,"return",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),null,null,-1,null,null);
        locals.Add(own,new[]{Count(),Store(1,"_auditRepeatFlag",new KismetExpr{Var="K2Node_Event_TriggerNotDestroyed"}),
            Store(2,"_auditRepeatKiller",new KismetExpr{Var="K2Node_Event_killer"}),Marker(3),Return(4)});
        locals.Add(notify,new[]{Count(),Marker(1),Store(2,"TriggerMultiple",new KismetExpr{Var="_auditRepeatOutput",Scope="instance"},"local"),Return(3)});
        locals.Add(after,new[]{Store(0,"_auditRepeatAfter",new KismetExpr{Bool=true}),
            Store(1,"_auditRepeatAfterFlag",new KismetExpr{Var="K2Node_Event_TriggerNotDestroyed"}),
            Store(2,"_auditRepeatAfterKiller",new KismetExpr{Var="K2Node_Event_killer"}),Marker(3),Return(4)});
        using var cleanup=new AuditProbeCleanup(()=>{locals.Remove(own);locals.Remove(notify);locals.Remove(after);});
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(int budget in new[]{0,1,3})
        foreach(int mutation in Enumerable.Range(0,4)) // none / suppress / unavailable / both
        foreach(int laterOutput in new[]{-2,7})
        {
            var(engine,state)=EmptyBoard(db);
            var victim=state.CreateWithId(name,side,60,side.HqOf(),1);
            victim.Definition=new CardDefinition{Name=name,Type="infantry",UsedTriggers=new[]{own,after}};
            victim.Keywords.Clear();victim.Keywords.Add(Keyword.Destruction);
            var watcher=state.CreateWithId(name,side.Opposite(),61,side.Opposite().DeckOf(),0);
            watcher.Definition=new CardDefinition{Name=name,UsedTriggers=new[]{notify}};
            var killer=state.CreateWithId(PlainUnit,side.Opposite(),99,CardLocation.Discard,77);
            int selfCalls=0,notifications=0,afterCalls=0;string? failure=null;var order=new List<string>();var prior=state.CardCreated;
            state.CardCreated=made=>{prior?.Invoke(made);if(made.Name!="card_unit_routed_troops")return;
                if(Equals(victim.BlueprintVariables.GetValueOrDefault("_auditRepeatAfter"),true))
                {
                    afterCalls++;order.Add("after");
                    if(!Equals(victim.BlueprintVariables.GetValueOrDefault("_auditRepeatAfterFlag"),false)
                        ||!ReferenceEquals(victim.BlueprintVariables.GetValueOrDefault("_auditRepeatAfterKiller"),killer))failure="亡语尾事件参数错误";
                    return;
                }
                int ownCount=Convert.ToInt32(victim.BlueprintVariables.GetValueOrDefault("_auditRepeatCalls"));
                if(ownCount>selfCalls)
                {
                    selfCalls=ownCount;order.Add(selfCalls==1?"own:false":"own:true");
                    if(!Equals(victim.BlueprintVariables.GetValueOrDefault("_auditRepeatFlag"),selfCalls>1)
                        ||!ReferenceEquals(victim.BlueprintVariables.GetValueOrDefault("_auditRepeatKiller"),killer))failure="重复亡语参数错误";
                    if(selfCalls==2)
                    {
                        if(mutation is 1 or 3)victim.Keywords.Add(Keyword.Suppressed);
                        if(mutation is 2 or 3)state.Move(victim,CardLocation.NotAvailable,9,notifyMoved:false,normalizeLocation:false);
                    }
                }
                else
                {
                    notifications++;order.Add("T24");
                    watcher.BlueprintVariables["_auditRepeatOutput"]=notifications==1?budget:laterOutput;
                    // The caller's saved T24 array must survive later registration/suppression changes.
                    watcher.Definition=new CardDefinition{Name=name};watcher.Keywords.Add(Keyword.Suppressed);
                }
            };
            engine.Destroy(victim,killer);
            int expectedNotifications=budget>0&&mutation is 1 or 3?1:1+budget;
            var expected=new List<string>{"own:false","T24"};
            for(int i=0;i<budget;i++){expected.Add("own:true");if(mutation is 0 or 2)expected.Add("T24");}
            expected.Add("after");
            if(failure is not null||afterCalls!=1||selfCalls!=1+budget||notifications!=expectedNotifications||!order.SequenceEqual(expected))
                return $"{failure??"重复次数应固定且移出局不应截断自身回调"}：{side}/{budget}/{mutation}/{laterOutput}, self={selfCalls}/{1+budget}, notify={notifications}/{expectedNotifications}";
        }
        return null;
    }

    private static string? DestructionSubjectSuppressionPerRecipient(CardDatabase db)
    {
        const string name="card_unit_typhoon_mk_ib",trigger="OnDestructionEffectTriggered";
        var locals=(IDictionary<string,IReadOnlyList<KismetStep>>)KismetLibrary.Default!.Find(name)!.Locals!;
        if(KismetLibrary.Default.FindProgram(name,trigger) is not null)return "无法安全安装T24抑制探针";
        locals.Add(trigger,new[]{
            new KismetStep(0,"set",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),new KismetExpr{Math="Add_IntInt",Args=new[]{
                new KismetExpr{Var="_auditT24Calls",Scope="instance"},new KismetExpr{Int=1}}},null,-1,"_auditT24Calls",null){DestinationScope="instance"},
            new KismetStep(1,"call","SpawnCardInDeckBySide",new[]{new KismetExpr{Int=(int)Side.Right},new KismetExpr{Str="card_unit_routed_troops"},
                new KismetExpr{Int=30},new KismetExpr{Int=1}},Array.Empty<int>(),null,null,-1,null,null),
            new KismetStep(2,"set",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),new KismetExpr{Var="_auditT24Output",Scope="instance"},null,-1,"TriggerMultiple",null),
            new KismetStep(3,"return",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),null,null,-1,null,null)});
        using var cleanup=new AuditProbeCleanup(()=>locals.Remove(trigger));
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool reverse in new[]{false,true})
        foreach(bool initiallySuppressed in new[]{false,true})
        foreach(bool changeInCallback in new[]{false,true})
        foreach(bool skip in new[]{false,true})
        foreach(int secondValue in new[]{-2,0,3})
        {
            var(engine,state)=EmptyBoard(db);
            var victim=state.CreateWithId(PlainUnit,side,50,CardLocation.Discard,20);
            if(initiallySuppressed)victim.Keywords.Add(Keyword.Suppressed);else victim.Keywords.Remove(Keyword.Suppressed);
            var first=state.CreateWithId(name,side,60,side.DeckOf(),0);
            var second=state.CreateWithId(name,side.Opposite(),61,CardLocation.Discard,30);
            foreach(var observer in new[]{first,second})observer.Definition=new CardDefinition{Name=name,UsedTriggers=new[]{trigger}};
            first.BlueprintVariables["_auditT24Output"]=2;second.BlueprintVariables["_auditT24Output"]=secondValue;
            var selected=engine.Api.CaptureRegisteredTriggerSnapshot(trigger).ToArray();
            if(reverse)Array.Reverse(selected);
            if(selected.Length!=2)return "T24接收者夹具错误";
            int callbacks=0;var prior=state.CardCreated;
            state.CardCreated=made=>{prior?.Invoke(made);if(made.Name!="card_unit_routed_troops")return;
                callbacks++;
                if(changeInCallback&&callbacks==1)
                {
                    if(victim.IsSuppressed)victim.Keywords.Remove(Keyword.Suppressed);else victim.Keywords.Add(Keyword.Suppressed);
                }
            };
            int total=engine.Api.FireDestructionEffectTriggered(victim,null,new[]{victim.CardId,first.CardId},selected,skip);
            int expectedCalls=initiallySuppressed&&!skip?0:!skip&&changeInCallback?1:2;
            int expected=selected.Take(expectedCalls).Sum(c=>Convert.ToInt32(c.BlueprintVariables["_auditT24Output"]));
            if(callbacks!=expectedCalls||total!=expected)
                return $"T24须逐项重查主体抑制，已执行输出仍计入：{side}/{reverse}/{initiallySuppressed}/{changeInCallback}/{skip}/{secondValue}, calls={callbacks}/{expectedCalls}, sum={total}/{expected}";
        }
        return null;
    }

    private static string? DeathBatchObserverPayloads(CardDatabase db)
    {
        using var probes=InstallCombatPayloadProbes(onlyDestroyed:true);
        const string name="card_unit_typhoon_mk_ib";
        foreach(int route in Enumerable.Range(0,3)) // real attack / batch destroy / batch damage
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool frontline in new[]{false,true})
        foreach(bool reverse in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);
            var first=state.CreateWithId(name,side,60,frontline?CardLocation.BoardFrontline:side.HqOf(),20);
            var second=state.CreateWithId(name,side.Opposite(),61,side.Opposite().HqOf(),30);
            var external=state.CreateWithId(name,side,62,side.DeckOf(),0);
            foreach(var card in new[]{first,second,external})
            {
                card.Definition=new CardDefinition{Name=name,Type="infantry",Attack=2,Defense=1,Range=2,UsedTriggers=new[]{"OnOtherCardDestroyed"}};
                card.Keywords.Clear();card.Attack=2;card.Defense=card.MaxDefense=1;
                card.EnteredPlayOnTurn=-99;card.OperationCost=0;
            }
            first.Keywords.Add(Keyword.Guard);second.Keywords.Add(Keyword.Guard);
            var source=state.CreateWithId(PlainUnit,side,99,CardLocation.Discard,77);
            var ordered=reverse?new[]{second,first}:new[]{first,second};
            var old=ordered.ToDictionary(c=>c.CardId,c=>(int)c.Location);
            var seen=new Dictionary<int,int>();
            var hits=new List<(int Receiver,int Subject,int Killer,int Old,bool Also,bool Combat,bool Repeat)>();
            string? failure=null;var created=state.CardCreated;
            state.CardCreated=made=>{created?.Invoke(made);if(made.Name!="card_unit_routed_troops")return;
                foreach(var receiver in new[]{first,second,external})
                {
                    var v=receiver.BlueprintVariables;
                    int serial=Convert.ToInt32(v.GetValueOrDefault("_auditDeathPayloadSerial"));
                    if(serial<=seen.GetValueOrDefault(receiver.CardId))continue;
                    seen[receiver.CardId]=serial;
                    if(first.Location!=CardLocation.Discard||second.Location!=CardLocation.Discard)
                        failure="T39开始时批次双方必须已离场";
                    if(!Equals(v.GetValueOrDefault("_auditDeathPayloadKind"),"OnOtherCardDestroyed"))failure="意外的非T39参数探针";
                    if(v.GetValueOrDefault("_auditPayloadAlso") is not bool||v.GetValueOrDefault("_auditPayloadCombat") is not bool
                        ||v.GetValueOrDefault("_auditPayloadRepeat") is not bool)failure="T39布尔载荷不能缺省为null";
                    hits.Add((receiver.CardId,(v.GetValueOrDefault("_auditPayloadCard") as CardInstance)?.CardId??0,
                        (v.GetValueOrDefault("_auditPayloadKiller") as CardInstance)?.CardId??0,
                        Convert.ToInt32(v.GetValueOrDefault("_auditPayloadOld")),
                        Equals(v.GetValueOrDefault("_auditPayloadAlso"),true),Equals(v.GetValueOrDefault("_auditPayloadCombat"),true),
                        !Equals(v.GetValueOrDefault("_auditPayloadRepeat"),false)));
                    return;
                }
                failure="T39探针未找到接收者写入";
            };
            if(route==0)
            {
                state.ActiveSide=ordered[1].Owner;state.SetKredits(state.ActiveSide,20);
                if(!engine.Attack(ordered[1],ordered[0],out string reason))return $"批次旁观者测试攻击被拒：{reason}";
            }
            else if(route==1)engine.DestroyMultiple(ordered,source);
            else
            {
                var result=engine.Api.InvokeByName("DamageMultipleCards",null,new object?[]{ordered.ToList(),1,source.CardId,null},
                    new EffectContext{Engine=engine,State=state,Self=source,Controller=side},out bool handled);
                if(!handled||result is not int[] ids||!ids.SequenceEqual(ordered.Select(c=>c.CardId)))return "批次伤害死亡名单错误";
            }
            if(failure is not null)return failure;
            if(hits.Count!=4||hits.Take(2).Any(h=>h.Subject!=ordered[0].CardId)||hits.Skip(2).Any(h=>h.Subject!=ordered[1].CardId))
                return "同批死亡及外部旁观者应分别收到两轮共4个事件";
            foreach(var hit in hits)
            {
                int other=hit.Subject==first.CardId?second.CardId:first.CardId;
                if(hit.Receiver==hit.Subject||hit.Killer!=(route==0?other:source.CardId)||hit.Old!=old[hit.Subject]
                    ||hit.Also!=(hit.Receiver!=external.CardId)||hit.Combat!=(route==0)||hit.Repeat)
                    return $"T39同批true/外部false、凶手、旧位置或战斗标志错误：route={route}/{side}/{frontline}/{reverse}";
            }
            if(hits.Count(h=>h.Receiver==first.CardId)!=1||hits.Count(h=>h.Receiver==second.CardId)!=1||hits.Count(h=>h.Receiver==external.CardId)!=2)
                return "已离场死亡卡须收到另一张卡的T39且不能收到自身的T39";
        }
        return null;
    }

    private static string? CombatPairEventPayloads(CardDatabase db) => SameFrontlineCombatPairRefresh(db,true,true);

    private static string? SameFrontlineCombatPairRefresh(CardDatabase db, bool relocateDuringDamage, bool checkPayload = false)
    {
        using var movement=InstallMovementObserverProbes();
        using var death=InstallDeathObserverProbe();
        const string name="card_unit_typhoon_mk_ib";
        using var payloadCleanup=checkPayload?InstallCombatPayloadProbes():null;
        IDisposable? receiveCleanup=null;
        if(relocateDuringDamage)
        {
            const string receive="OnReceiveDamage";
            var locals=(IDictionary<string,IReadOnlyList<KismetStep>>)KismetLibrary.Default!.Find(name)!.Locals!;
            if(KismetLibrary.Default.FindProgram(name,receive) is not null)return "无法安全安装受伤搬移探针";
            locals.Add(receive,new[]{
                new KismetStep(0,"call","SpawnCardInDeckBySide",new[]{new KismetExpr{Int=(int)Side.Right},new KismetExpr{Str="card_unit_routed_troops"},
                    new KismetExpr{Int=30},new KismetExpr{Int=1}},Array.Empty<int>(),null,null,-1,null,null),
                new KismetStep(1,"return",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),null,null,-1,null,null)});
            receiveCleanup=new AuditProbeCleanup(()=>locals.Remove(receive));
        }
        using var cleanup=receiveCleanup;
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(int guardMode in Enumerable.Range(0,3))
        foreach(bool hidden in new[]{false,true})
        foreach(bool reverse in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);var zone=CardLocation.BoardFrontline;
            var a=state.CreateWithId(PlainUnit,side,70,zone,10);
            var left=state.CreateWithId(name,side,60,zone,20);
            var right=state.CreateWithId(name,side.Opposite(),61,zone,30);
            var b=state.CreateWithId(PlainUnit,side.Opposite(),71,zone,40);
            a.Keywords.Clear();b.Keywords.Clear();a.IsBeingGuarded=false;b.IsBeingGuarded=false;
            if(guardMode==1)b.Keywords.Add(Keyword.Guard);
            if(guardMode==2)b.ReceivedAbilitiesFromCards["guard"]=new List<int>{9};
            if(hidden){b.Keywords.Add(Keyword.Covert);b.IsRevealed=false;}
            foreach(var victim in new[]{left,right})
            {
                victim.Definition=new CardDefinition{Name=name,Type="infantry",Attack=2,Defense=1,
                    UsedTriggers=relocateDuringDamage?new[]{"OnCardLocationMoved","OnDestroyed","OnReceiveDamage"}:new[]{"OnCardLocationMoved","OnDestroyed"}};
                victim.Keywords.Clear();victim.Keywords.Add(Keyword.Guard);victim.Keywords.Add(Keyword.Destruction);
                victim.Attack=2;victim.Defense=victim.MaxDefense=1;victim.EnteredPlayOnTurn=-99;victim.OperationCost=0;
            }
            if(checkPayload)
                foreach(var victim in new[]{left,right})
                    victim.Definition=new CardDefinition{Name=name,Type="infantry",Attack=2,Defense=1,
                        UsedTriggers=new[]{"OnCardLocationMoved","OnDestroyed","OnReceiveDamage","OnAfterLeaveBoard"}};
            var defender=reverse?right:left;var attacker=reverse?left:right;
            int defenderNumber=relocateDuringDamage?9:reverse?30:20;
            state.ActiveSide=attacker.Owner;state.FrontlineOwner=attacker.Owner;state.SetKredits(attacker.Owner,20);
            state.Hq(Side.Left).IsBeingGuarded=true;state.Hq(Side.Right).IsBeingGuarded=true;
            var discard=state.CreateWithId(PlainUnit,side,200,CardLocation.Discard,77);
            var observer=state.CreateWithId(checkPayload?name:"card_event_honorifics",side,202,side.DeckOf(),0);
            observer.Definition=new CardDefinition{Name=observer.Name,UsedTriggers=new[]{"OnOtherCardLocationMoved"}};
            if(checkPayload)observer.Definition=new CardDefinition{Name=observer.Name,
                UsedTriggers=new[]{"OnOtherCardLocationMoved","OnAfterOtherCardLeaveBoardOrOwner","OnOtherCardDestroyed"}};
            int payloads=0;var seenPayloads=new Dictionary<int,int>();
            int callbacks=0,received=0,moves=0;string? failure=null;var prior=state.CardCreated;
            var priorMoved=state.CardMoved;
            state.CardMoved=(card,from,to,changed,reason)=>{
                if(ReferenceEquals(card,defender)&&to==CardLocation.Discard)
                {
                    moves++;
                    if(from!=zone)failure="双亡移动必须携带ExecuteAttackCard入口保存的旧位置";
                }
                priorMoved?.Invoke(card,from,to,changed,reason);
            };
            bool Marked(CardInstance card,string key)=>Equals(card.BlueprintVariables.GetValueOrDefault(key),true);
            state.CardCreated=made=>{prior?.Invoke(made);if(made.Name!="card_unit_routed_troops")return;
                if(checkPayload)
                {
                    foreach(var receiver in new[]{defender,attacker,observer})
                    {
                        int serial=Convert.ToInt32(receiver.BlueprintVariables.GetValueOrDefault("_auditDeathPayloadSerial"));
                        if(serial<=seenPayloads.GetValueOrDefault(receiver.CardId))continue;
                        seenPayloads[receiver.CardId]=serial;
                        var v=receiver.BlueprintVariables;string kind=Convert.ToString(v.GetValueOrDefault("_auditDeathPayloadKind"))??"";
                        string expected=payloads switch {0 or 2=>"OnAfterLeaveBoard",1 or 3=>"OnAfterOtherCardLeaveBoardOrOwner",_=>"OnOtherCardDestroyed"};
                        var subject=payloads is 0 or 1 or 4?defender:attacker;
                        if(kind!=expected||callbacks!=(payloads<4?4:payloads==4?5:6))failure="双亡参数事件阶段或接收者顺序错误";
                        if(kind=="OnAfterLeaveBoard")
                        {
                            if(!ReferenceEquals(receiver,subject)||Convert.ToInt32(v.GetValueOrDefault("_auditPayloadNew"))!=(int)CardLocation.Discard)
                                failure="自身离场后事件应收到弃牌目的地";
                        }
                        else
                        {
                            if(!ReferenceEquals(v.GetValueOrDefault("_auditPayloadCard"),subject)
                                ||Convert.ToInt32(v.GetValueOrDefault("_auditPayloadOld"))!=(int)zone)
                                failure="旁观离场后/死亡事件应保留原前线及事件主体";
                            if(kind=="OnOtherCardDestroyed"&&(!ReferenceEquals(v.GetValueOrDefault("_auditPayloadKiller"),ReferenceEquals(subject,defender)?attacker:defender)
                                ||!Equals(v.GetValueOrDefault("_auditPayloadCombat"),true)
                                ||!Equals(v.GetValueOrDefault("_auditPayloadAlso"),false)
                                ||!Equals(v.GetValueOrDefault("_auditPayloadRepeat"),false)))
                                failure="死亡旁观者凶手、战斗、同批死亡或重复标志错误";
                        }
                        payloads++;return;
                    }
                }
                if(relocateDuringDamage&&received<2)
                {
                    received++;
                    if(received==1)state.Move(defender,defender.Owner.HqOf(),9,notifyMoved:false,normalizeLocation:false);
                    return;
                }
                callbacks++;
                bool first=callbacks<=2;
                if(defender.Location!=CardLocation.Discard||defender.LocationNumber!=defenderNumber
                    ||attacker.Location!=(first?zone:CardLocation.Discard)||attacker.LocationNumber!=1
                    ||discard.LocationNumber!=77)
                    failure="同前线首张保留旧编号；第二张须先重排为1，随后弃牌仍为1";
                if(a.LocationNumber!=0||b.LocationNumber!=(first?2:1)
                    ||a.IsBeingGuarded!=(first||guardMode==1&&!hidden)
                    ||b.IsBeingGuarded!=(first&&(guardMode==0||hidden)))
                    failure="同前线两阶段编号或原始/来源/隐蔽掩护缓存错误";
                if(!Marked(defender,"_auditMovementCalled")||Marked(attacker,"_auditMovementCalled")==first
                    ||Marked(defender,"_auditBatchDestroyed")!=(callbacks>=5)
                    ||Marked(attacker,"_auditBatchDestroyed")!=(callbacks>=6))
                    failure="双亡回调顺序应为防守方移动、自身及旁观、攻击方移动、自身及旁观，最后双方亡语";
                if(!state.Hq(Side.Left).IsBeingGuarded||!state.Hq(Side.Right).IsBeingGuarded)
                    failure="同前线刷新不得重写无关支援区掩护";
            };
            if(!engine.Attack(attacker,defender,out string reason))return $"同前线测试攻击被拒：{reason}";
            if(callbacks!=6||moves!=1||received!=(relocateDuringDamage?2:0)||payloads!=(checkPayload?6:0)||failure is not null)return $"{failure??"同前线探针次数错误"}：{side}/{guardMode}/{hidden}/{reverse}, callbacks={callbacks}";
        }
        return null;
    }

    private static string? CombatPairGuardedRefresh(CardDatabase db) => BatchDeathGuardedRefresh(db, false, combat:true);

    private static string? SingleDestroyGuardedRefresh(CardDatabase db) => BatchDeathGuardedRefresh(db, false, single:true);

    private static string? BatchDestroyGuardedRefresh(CardDatabase db) => BatchDeathGuardedRefresh(db, false);
    private static string? BatchDamageGuardedRefresh(CardDatabase db)
    {
        if(BatchDeathGuardedRefresh(db,true) is { } failure)return failure;
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool lethal in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);
            var target=state.CreateWithId(PlainUnit,side,60,side.HqOf(),20);target.Defense=lethal?1:3;
            var survivor=state.CreateWithId(PlainUnit,side,61,side.HqOf(),40);survivor.IsBeingGuarded=true;survivor.Keywords.Remove(Keyword.Guard);
            var other=state.CreateWithId(PlainUnit,side.Opposite(),62,side.Opposite().HqOf(),30);other.Defense=3;other.IsBeingGuarded=true;
            var source=state.CreateWithId(PlainUnit,side,99,CardLocation.Discard,77);
            var result=engine.Api.InvokeByName("DamageMultipleCards",null,new object?[]{new List<CardInstance>{target,other},1,99,null},
                new EffectContext{Engine=engine,State=state,Self=source,Controller=side},out _);
            if(result is not int[] ids||!ids.SequenceEqual(lethal?new[]{60}:Array.Empty<int>())||other.Defense!=2)
                return "混合批量伤害死亡名单或存活受伤目标错误";
            if(survivor.LocationNumber!=(lethal?1:40)||survivor.IsBeingGuarded==lethal
                ||other.LocationNumber!=30||!other.IsBeingGuarded||source.LocationNumber!=77)
                return "仅有死亡目标的区域需要刷新；无死亡或仅受伤区域须保持旧编号和缓存";
        }
        return null;
    }

    private static string? BatchDeathGuardedRefresh(CardDatabase db, bool fromDamage, bool single = false, bool combat = false)
    {
        using var movement=InstallMovementObserverProbes();
        using var deathProbe=InstallDeathObserverProbe();
        const string name="card_unit_typhoon_mk_ib",trigger="OnDestroyed";
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool frontline in new[]{false,true})
        foreach(int guardMode in Enumerable.Range(0,3))
        foreach(bool hidden in new[]{false,true})
        foreach(bool reverse in single?new[]{false}:new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);var firstZone=frontline?CardLocation.BoardFrontline:side.HqOf();
            var zones=new[]{firstZone,side.Opposite().HqOf()};var victims=new List<CardInstance>();
            var survivors=new List<(CardInstance First,CardInstance Last,CardLocation Location)>();
            bool expectedGuard=guardMode==1&&!hidden;
            for(int i=0;i<(single?1:2);i++)
            {
                Side owner=i==0?side:side.Opposite();
                var first=state.CreateWithId(PlainUnit,owner,70+i*10,zones[i],10);first.Keywords.Remove(Keyword.Guard);first.IsBeingGuarded=!expectedGuard;
                var victim=state.CreateWithId(name,owner,60+i,zones[i],20);
                victim.Definition=new CardDefinition{Name=name,Type="infantry",UsedTriggers=new[]{"OnCardLocationMoved",trigger}};
                victim.Keywords.Add(Keyword.Destruction);victim.Keywords.Add(Keyword.Guard);victims.Add(victim);
                var last=state.CreateWithId(PlainUnit,frontline&&i==0?owner.Opposite():owner,71+i*10,zones[i],30);
                last.Keywords.Remove(Keyword.Guard);if(guardMode==1)last.Keywords.Add(Keyword.Guard);
                if(guardMode==2)last.ReceivedAbilitiesFromCards["guard"]=new List<int>{9};
                if(hidden){last.Keywords.Add(Keyword.Covert);last.IsRevealed=false;}
                last.IsBeingGuarded=true;survivors.Add((first,last,zones[i]));
            }
            var resident=state.CreateWithId(PlainUnit,side,200,CardLocation.Discard,77);
            var untouched=state.CreateWithId(PlainUnit,side,201,side.HandOf(),91);untouched.IsBeingGuarded=true;
            var observer=state.CreateWithId("card_event_honorifics",side,202,side.DeckOf(),0);
            observer.Definition=new CardDefinition{Name=observer.Name,UsedTriggers=new[]{"OnOtherCardLocationMoved"}};
            string? failure=null;int callbacks=0;var created=state.CardCreated;
            state.CardCreated=made=>{created?.Invoke(made);if(made.Name!="card_unit_routed_troops")return;
                callbacks++;
                var orderedVictims=reverse?victims.AsEnumerable().Reverse().ToArray():victims.ToArray();
                if(combat&&callbacks<=2)
                {
                    if(orderedVictims[0].Location!=CardLocation.Discard||orderedVictims[1].Location==CardLocation.Discard)
                        failure="战斗防守方移动回调必须看到攻击方尚未离场";
                }
                else if(victims.Any(v=>v.Location!=CardLocation.Discard))failure="末次移动及亡语前必须全部离场";
                foreach(var item in survivors)
                {
                    if(combat&&callbacks<=2&&item.Location==orderedVictims[1].Location)
                    {
                        if(item.First.LocationNumber!=10||item.Last.LocationNumber!=30
                            ||item.First.IsBeingGuarded==expectedGuard||!item.Last.IsBeingGuarded)
                            failure="战斗首个移动回调不得提前刷新尚未离场的攻击方区域";
                        continue;
                    }
                    int start=item.Location==CardLocation.BoardFrontline?0:1;
                    if(item.First.LocationNumber!=start||item.Last.LocationNumber!=start+1
                        ||item.First.IsBeingGuarded!=expectedGuard||item.Last.IsBeingGuarded)
                        failure="批量摧毁回调未看到所有受影响物理位置的新编号和掩护缓存";
                }
                if(resident.LocationNumber!=77||victims.Any(v=>v.LocationNumber!=20))failure="批量移入弃牌堆必须保留原编号且不重排现有弃牌";
                if(!untouched.IsBeingGuarded||untouched.LocationNumber!=91)failure="批量刷新不得改写未受影响手牌";
            };
            var ordered=reverse?victims.AsEnumerable().Reverse().ToArray():victims.ToArray();
            if(combat)
            {
                state.ActiveSide=ordered[1].Owner;state.SetKredits(state.ActiveSide,20);
                foreach(var victim in victims)
                {
                    victim.Definition=new CardDefinition{Name=name,Type="infantry",Range=2,Attack=2,Defense=1,
                        UsedTriggers=new[]{"OnCardLocationMoved",trigger}};
                    victim.Keywords.Clear();victim.Keywords.Add(Keyword.Destruction);victim.Keywords.Add(Keyword.Guard);
                    victim.Attack=2;victim.Defense=victim.MaxDefense=1;
                    victim.EnteredPlayOnTurn=-99;victim.OperationCost=0;
                }
                if(!engine.Attack(ordered[1],ordered[0],out string reason))return $"双亡刷新测试攻击被拒：{reason}";
            }
            else if(fromDamage)
            {
                foreach(var victim in victims)victim.Defense=1;
                var source=state.CreateWithId(PlainUnit,side,203,CardLocation.Discard,99);
                var result=engine.Api.InvokeByName("DamageMultipleCards",null,new object?[]{ordered.ToList(),1,source.CardId,null},
                    new EffectContext{Engine=engine,State=state,Self=source,Controller=side},out bool handled);
                if(!handled||result is not int[] destroyed||!destroyed.SequenceEqual(ordered.Select(v=>v.CardId)))
                    return "批量伤害未返回实际死亡目标名单";
                if(source.LocationNumber!=99)return "批量伤害致死不应重排既有弃牌中的伤害来源";
            }
            else if(single)engine.Destroy(ordered[0]);
            else engine.DestroyMultiple(ordered,null);
            if(callbacks!=(single?3:6)||victims.Any(v=>!Equals(v.BlueprintVariables.GetValueOrDefault("_auditBatchDestroyed"),true))||failure is not null)
                return $"{failure??"批量移动/亡语探针次数错误"}：{side}/{frontline}/{guardMode}/{hidden}/{reverse}, callbacks={callbacks}";
        }
        return null;
    }

    private static string? ForceMoveGuardedRefresh(CardDatabase db) => MovementGuardedRefresh(db,false);
    private static string? OrdinaryMoveGuardedRefresh(CardDatabase db) => MovementGuardedRefresh(db,true);

    private static string? MovementGuardedRefresh(CardDatabase db, bool ordinaryOnly)
    {
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(int route in ordinaryOnly?new[]{3}:Enumerable.Range(0,3)) // force / direct front / direct support / action
        foreach(int ownGuard in Enumerable.Range(0,3))
        foreach(bool hidden in new[]{false,true})
        foreach(bool residentGuard in new[]{false,true})
        foreach(int insertion in route is 0 or 3?new[]{-1}:new[]{-1,0})
        {
            var(engine,state)=EmptyBoard(db);state.FrontlineOwner=side;state.ActiveSide=side;state.SetKredits(side,20);
            var old=route is 0 or 3?side.HqOf():side.HandOf();
            var destination=route==2?side.HqOf():CardLocation.BoardFrontline;
            state.Hq(side).Keywords.Remove(Keyword.Guard);state.Hq(side.Opposite()).IsBeingGuarded=true;
            var oldA=state.CreateWithId(PlainUnit,side,50,old,route is 0 or 3?1:0);
            var oldB=state.CreateWithId(PlainUnit,side,51,old,route is 0 or 3?2:1);
            foreach(var card in new[]{oldA,oldB}){card.Keywords.Remove(Keyword.Guard);card.IsBeingGuarded=true;}
            var mover=state.CreateWithId(PlainUnit,side,60,old,3);
            mover.Definition=new CardDefinition{Name=mover.Name,Type="infantry",Attack=2,Defense=5};
            mover.Keywords.Remove(Keyword.Guard);mover.Keywords.Remove(Keyword.Covert);mover.Keywords.Remove(Keyword.Smokescreen);
            if(ownGuard==1)mover.Keywords.Add(Keyword.Guard);
            if(ownGuard==2)mover.ReceivedAbilitiesFromCards["guard"]=new List<int>{9};
            if(hidden){mover.Keywords.Add(Keyword.Covert);mover.IsRevealed=false;}
            else mover.IsRevealed=true;
            int offset=route==2?1:0;
            var residentA=state.CreateWithId(PlainUnit,side,70,destination,offset);
            var residentB=state.CreateWithId(PlainUnit,side,71,destination,offset+1);
            foreach(var card in new[]{residentA,residentB})
            {
                card.Keywords.Remove(Keyword.Guard);if(residentGuard)card.Keywords.Add(Keyword.Guard);
                card.IsBeingGuarded=true;
            }
            mover.EnteredPlayOnTurn=-99;mover.OperationCost=1;
            mover.IsBeingGuarded=true;int calls=0;string? failure=null;var prior=state.CardMoved;
            state.CardMoved=(card,from,to,changed,reason)=>{
                if(ReferenceEquals(card,mover)&&from==old&&to==destination)
                {
                    calls++;
                    bool Near(CardInstance left,CardInstance right)=>Math.Abs(left.LocationNumber-right.LocationNumber)==1;
                    bool expectedMover=(ownGuard==0||hidden)&&residentGuard&&(Near(mover,residentA)||Near(mover,residentB));
                    bool expectedA=!residentGuard&&ownGuard==1&&!hidden&&Near(mover,residentA);
                    bool expectedB=!residentGuard&&ownGuard==1&&!hidden&&Near(mover,residentB);
                    if(mover.IsBeingGuarded!=expectedMover||residentA.IsBeingGuarded!=expectedA||residentB.IsBeingGuarded!=expectedB
                        ||oldA.IsBeingGuarded!=(route is not (0 or 3))||oldB.IsBeingGuarded!=(route is not (0 or 3))||!state.Hq(side.Opposite()).IsBeingGuarded)
                        failure="强制移动回调读取了旧掩护缓存，或误刷新非棋盘/无关位置";
                    foreach(var zone in new[]{old,destination})
                    {
                        var numbers=state.AllCardsInBattleOrder.Where(x=>x.Location==zone).Select(x=>x.LocationNumber).OrderBy(x=>x).ToArray();
                        if(!numbers.SequenceEqual(Enumerable.Range(0,numbers.Length)))failure="移动回调前受影响物理位置未完成压紧";
                    }
                    var notifications=state.ActionLog.SelectMany(a=>a.SubActions).Where(a=>a.Name=="ZActionMoveCardToNewLocation").ToArray();
                    if(notifications.Length!=1||route!=3&&notifications[0].Values.First(v=>v.Name=="cardID").Value!=60)
                        failure="移动通知必须在完整位置刷新及回调前发出，且不重复";
                }
                prior?.Invoke(card,from,to,changed,reason);
            };
            bool ok=route==0?engine.MoveUnitFromSupportToFrontLine(mover,99,out _)
                :route==3?engine.MoveUnit(mover,2):engine.PlayCardDirectlyFromHand(mover,route==1,99,insertion);
            if(route==3&&(state.Kredits(side)!=19||!mover.HasMovedThisTurn))return "普通推进仍应支付实际行动费并消耗移动额度";
            if(!ok||calls!=1||failure is not null)return $"{failure??"强制移动未到达回调"}：{side}/{route}/{ownGuard}/{hidden}/{residentGuard}/{insertion}";
        }
        return null;
    }

    private static string? RefreshLocationGuardedContract(CardDatabase db)
    {
        foreach(CardLocation location in Enumerable.Range(0,10).Concat(new[]{10,255}).Select(x=>(CardLocation)x))
        foreach(bool initial in new[]{false,true})
        foreach(int guardMode in Enumerable.Range(0,4))
        foreach(bool dispatch in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);
            var last=state.CreateWithId(PlainUnit,Side.Right,90,location,100);
            var guard=state.CreateWithId(PlainUnit,Side.Left,30,location,10);
            var middle=state.CreateWithId(PlainUnit,Side.Right,70,location,50);
            foreach(var card in new[]{last,guard,middle}){card.Keywords.Remove(Keyword.Guard);card.IsBeingGuarded=initial;}
            if(guardMode is 1 or 3)guard.Keywords.Add(Keyword.Guard);
            if(guardMode==2)guard.ReceivedAbilitiesFromCards["guard"]=new List<int>{9};
            if(guardMode==3){guard.Keywords.Add(Keyword.Covert);guard.IsRevealed=false;}
            var untouched=state.CreateWithId(PlainUnit,Side.Right,91,location==CardLocation.BoardHqLeft?CardLocation.BoardHqRight:CardLocation.BoardHqLeft,200);
            untouched.IsBeingGuarded=true;
            int actions=state.ActionLog.Count;var trace=new List<string>();engine.Api.TriggerTrace=trace;
            // Use one set for the VM form and duplicated input for the typed API form.
            if(dispatch)
            {
                engine.Api.InvokeByName("RefreshLocationStatus",null,new object?[]{new HashSet<object?>{(int)location}},
                    new EffectContext{Engine=engine,State=state,Self=guard,Controller=Side.Left},out bool handled);
                if(!handled)return "RefreshLocationStatus未接入派发表";
            }
            else engine.Api.RefreshLocationStatus(new[]{location,location});
            bool compact=(int)location is >=3 and <=7;
            int start=location is CardLocation.BoardHqLeft or CardLocation.BoardHqRight?1:0;
            if(guard.LocationNumber!=(compact?start:10)||middle.LocationNumber!=(compact?start+1:50)||last.LocationNumber!=(compact?start+2:100))
                return "位置刷新只能压紧3至7，按物理位置排序且不按Owner拆分";
            bool middleCache=location.IsBoard()?guardMode==1:initial;
            if(middle.IsBeingGuarded!=middleCache||guard.IsBeingGuarded!=(location.IsBoard()?false:initial)
                ||last.IsBeingGuarded!=(location.IsBoard()?false:initial)||!untouched.IsBeingGuarded||untouched.LocationNumber!=200)
                return "位置刷新须在重排后计算掩护，其他位置/非棋盘缓存保持";
            if(state.ActionLog.Count!=actions||trace.Count!=0)return "位置刷新本身不应发动作或事件";
        }
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool frontline in new[]{false,true})
        foreach(bool full in new[]{false,true})
        foreach(bool movingGuard in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);var old=frontline?CardLocation.BoardFrontline:side.HqOf();
            var mover=state.CreateWithId("card_unit_typhoon_mk_ib",side,60,old,10);
            mover.Definition=new CardDefinition{Name=mover.Name,Type="infantry"};mover.Keywords.Remove(Keyword.Guard);
            if(movingGuard)mover.Keywords.Add(Keyword.Guard);
            var survivor=state.CreateWithId(PlainUnit,side,61,old,20);survivor.Keywords.Remove(Keyword.Guard);survivor.IsBeingGuarded=movingGuard;
            var last=state.CreateWithId(PlainUnit,side,62,old,30);last.Keywords.Remove(Keyword.Guard);
            if(!movingGuard)last.Keywords.Add(Keyword.Guard);
            if(full)for(int i=0;i<9;i++)state.CreateWithId(PlainUnit,side,100+i,side.HandOf(),i*3);
            var seen=new List<(int,bool,int)>();var prior=state.CardMoved;
            state.CardMoved=(card,from,to,changed,reason)=>{
                if(ReferenceEquals(card,mover)&&from==old)
                    seen.Add((survivor.LocationNumber,survivor.IsBeingGuarded,state.ActionLog.SelectMany(a=>a.SubActions).Count(a=>a.Name=="ZActionMoveCardToNewLocation")));
                prior?.Invoke(card,from,to,changed,reason);};
            engine.Api.InvokeByName("MoveCardFromBoardToOwnersHand",null,new object?[]{60,0,(int)old,(int)side.HandOf()},
                new EffectContext{Engine=engine,State=state,Self=mover,Controller=side},out _);
            if(!seen.SequenceEqual(new[]{(frontline?0:1,!movingGuard,1)}))
                return "回手移动通知后、移动回调前须重排旧位置并刷新掩护，满手弃置也一样";
        }
        return null;
    }

    private static string? RevealGuardedCacheTiming(CardDatabase db)
    {
        const string own="OnCardRevealed",other="OnOtherCardRevealed";
        var installed=new List<(IDictionary<string,IReadOnlyList<KismetStep>> Locals,string Trigger)>();
        using var cleanup=new AuditProbeCleanup(()=>{foreach(var entry in installed)entry.Locals.Remove(entry.Trigger);});
        foreach(var entry in new[]{("card_unit_typhoon_mk_ib",own),("card_event_honorifics",other)})
        {
            if(KismetLibrary.Default?.Find(entry.Item1)?.Locals is not IDictionary<string,IReadOnlyList<KismetStep>> locals
                ||KismetLibrary.Default.FindProgram(entry.Item1,entry.Item2) is not null)return "无法安全安装揭示缓存时序探针";
            locals.Add(entry.Item2,new[]{
                new KismetStep(0,"call","SpawnCardInDeckBySide",new[]{new KismetExpr{Int=(int)Side.Right},
                    new KismetExpr{Str="card_unit_routed_troops"},new KismetExpr{Int=30},new KismetExpr{Int=1}},
                    Array.Empty<int>(),null,null,-1,null,null),
                new KismetStep(1,"return",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),null,null,-1,null,null)});
            installed.Add((locals,entry.Item2));
        }
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(CardLocation location in new[]{side.HqOf(),CardLocation.BoardFrontline,side.DeckOf()})
        foreach(int ownGuard in Enumerable.Range(0,3))
        foreach(int neighborGuard in Enumerable.Range(0,3))
        foreach(bool suppressed in new[]{false,true})
        foreach(int giver in new[]{-3,0,9})
        foreach(bool revealed in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);var target=state.CreateWithId("card_unit_typhoon_mk_ib",side,60,location,10);
            target.Definition=new CardDefinition{Name=target.Name,Type="infantry",UsedTriggers=new[]{own}};
            target.Keywords.Remove(Keyword.Guard);if(ownGuard==1)target.Keywords.Add(Keyword.Guard);
            if(ownGuard==2)target.ReceivedAbilitiesFromCards["guard"]=new List<int>{9};
            target.Keywords.Add(Keyword.Covert);target.IsRevealed=revealed;
            if(suppressed)target.Keywords.Add(Keyword.Suppressed);
            var adjacent=state.CreateWithId(PlainUnit,side,61,location,9);adjacent.Keywords.Remove(Keyword.Guard);
            if(neighborGuard==1)adjacent.Keywords.Add(Keyword.Guard);
            if(neighborGuard==2)adjacent.ReceivedAbilitiesFromCards["guard"]=new List<int>{9};
            var observer=state.CreateWithId("card_event_honorifics",side,20,side.DeckOf(),0);
            observer.Definition=new CardDefinition{Name=observer.Name,UsedTriggers=new[]{other}};
            var untouched=state.CreateWithId(PlainUnit,side.Opposite(),62,side.Opposite().HqOf(),0);untouched.IsBeingGuarded=true;
            bool expectedTarget=location.IsBoard()?ownGuard==0&&neighborGuard==1:true;
            bool expectedAdjacent=location.IsBoard()?neighborGuard==0&&ownGuard==1:false;
            var seen=new List<(bool,bool,bool,bool,int)>();var created=state.CardCreated;
            state.CardCreated=made=>{created?.Invoke(made);if(made.Name=="card_unit_routed_troops")
                seen.Add((target.IsBeingGuarded,adjacent.IsBeingGuarded,target.IsRevealed,target.Keywords.Contains(Keyword.Covert),
                    state.ActionLog.SelectMany(a=>a.SubActions).Count(a=>a.Name=="ZActionRevealCard")));};
            var ctx=new EffectContext{Engine=engine,State=state,Self=observer,Controller=side};
            for(int repeat=0;repeat<2;repeat++)
            {
                target.IsBeingGuarded=true;adjacent.IsBeingGuarded=false;seen.Clear();
                var result=engine.Api.InvokeByName("RevealCard",null,new object?[]{60,giver},ctx,out bool handled);
                if(!handled||!Equals(result,0)||!target.IsRevealed||target.Keywords.Contains(Keyword.Covert)
                    ||target.IsBeingGuarded!=expectedTarget||adjacent.IsBeingGuarded!=expectedAdjacent||!untouched.IsBeingGuarded)
                    return $"揭示须先写标志并刷新当前物理位置缓存：{side}/{location}/{ownGuard}/{neighborGuard}/{suppressed}/{giver}/{revealed}/{repeat}";
                if(seen.Count!=(suppressed?1:2)||seen.Any(x=>x!=(expectedTarget,expectedAdjacent,true,false,repeat+1)))
                    return "揭示自身/T55回调必须观察到已刷缓存、清Covert与先发送的揭示通知";
                var notifications=state.ActionLog.SelectMany(a=>a.SubActions).Where(a=>a.Name=="ZActionRevealCard").ToArray();
                if(notifications.Length!=repeat+1||notifications.Any(a=>!a.Values.Select(v=>v.Name).SequenceEqual(new[]{"cardID","instigatorID"})
                    ||a.Values[0].Value!=60||a.Values[1].Value!=giver))return "揭示通知应重复发送且始终保留cardID和零/负instigatorID，牌库也通知";
            }
        }
        foreach(int id in new[]{0,-5,99999})
        {
            var(engine,state)=EmptyBoard(db);var target=state.CreateWithId(PlainUnit,Side.Left,60,CardLocation.BoardHqLeft,1);
            target.IsRevealed=false;target.Keywords.Add(Keyword.Covert);target.IsBeingGuarded=true;
            engine.Api.InvokeByName("RevealCard",target,new object?[]{id,0},new EffectContext{Engine=engine,State=state,Self=target,Target=target,Controller=Side.Left},out _);
            if(target.IsRevealed||!target.Keywords.Contains(Keyword.Covert)||!target.IsBeingGuarded
                ||state.ActionLog.SelectMany(a=>a.SubActions).Any(a=>a.Name=="ZActionRevealCard"))return "无效揭示目标ID不应回退到调用者或产生通知";
        }
        return null;
    }

    private static string? UpdateGuardedCacheContract(CardDatabase db)
    {
        foreach(CardLocation location in new[]{CardLocation.BoardHqLeft,CardLocation.BoardHqRight,CardLocation.BoardFrontline,
            CardLocation.HandLeft,CardLocation.DeckRight,CardLocation.NotAvailable})
        foreach(bool initial in new[]{false,true})
        foreach(bool ownRaw in new[]{false,true})
        foreach(bool ownSource in new[]{false,true})
        foreach(bool ownHidden in new[]{false,true})
        foreach(int neighbor in Enumerable.Range(0,5))
        foreach(bool enemyOwner in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);
            var card=state.CreateWithId(PlainUnit,Side.Left,60,location,10);card.IsBeingGuarded=initial;
            card.Keywords.Remove(Keyword.Guard);if(ownRaw)card.Keywords.Add(Keyword.Guard);
            if(ownSource)card.ReceivedAbilitiesFromCards["guard"]=new List<int>{0};
            if(ownHidden){card.Keywords.Add(Keyword.Covert);card.IsRevealed=false;}
            var adjacent=state.CreateWithId(PlainUnit,enemyOwner?Side.Right:Side.Left,61,location,9);
            adjacent.Keywords.Remove(Keyword.Guard);
            // none / raw / source-only / unrevealed raw / revealed Covert raw.
            if(neighbor is 1 or 3 or 4)adjacent.Keywords.Add(Keyword.Guard);
            if(neighbor==2)adjacent.ReceivedAbilitiesFromCards["guard"]=new List<int>{9};
            if(neighbor is 3 or 4){adjacent.Keywords.Add(Keyword.Covert);adjacent.IsRevealed=neighbor==4;}
            var untouched=state.CreateWithId(PlainUnit,Side.Left,62,location==CardLocation.BoardHqLeft?CardLocation.BoardHqRight:CardLocation.BoardHqLeft,0);
            untouched.IsBeingGuarded=true;
            int actions=state.ActionLog.Count;var trace=new List<string>();engine.Api.TriggerTrace=trace;
            engine.Api.InvokeByName("UpdateGuarded",null,new object?[]{(int)location},
                new EffectContext{Engine=engine,State=state,Self=card,Controller=Side.Left},out bool handled);
            bool expected=location.IsBoard()?(!((ownRaw||ownSource)&&!ownHidden)&&neighbor is 1 or 4):initial;
            if(!handled||card.IsBeingGuarded!=expected||!untouched.IsBeingGuarded)
                return $"UpdateGuarded缺失或缓存分支错误：{location}/{initial}/{ownRaw}/{ownSource}/{ownHidden}/{neighbor}/{enemyOwner}";
            if(card.Snapshot().IsBeingGuarded!=expected)return "掩护缓存未保留到快照";
            if(state.ActionLog.Count!=actions||trace.Count!=0)return "UpdateGuarded只能写缓存，不应发动作或事件";
            card.BlueprintVariables["isBeingGuarded"]=!expected;
            KismetStep Set(int i,string key,KismetExpr value,string scope)=>new(i,"set",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),value,null,-1,key,null){DestinationScope=scope};
            var program=new KismetProgram(new[]{
                Set(0,"before",new(){Var="isBeingGuarded",Scope="instance"},"local"),
                Set(1,"isBeingGuarded",new(){Bool=!expected},"instance"),
                Set(2,"after",new(){Var="isBeingGuarded",Scope="instance"},"local"),
                new KismetStep(3,"return",null,Array.Empty<KismetExpr>(),Array.Empty<int>(),null,null,-1,null,null)},0);
            var values=engine.Api.Vm.RunLocalProgramMulti(program,new EffectContext{Engine=engine,State=state,Self=card,Controller=Side.Left},null,"before","after");
            if(!Equals(values["before"],expected)||!Equals(values["after"],!expected)||card.IsBeingGuarded!=!expected
                ||card.BlueprintVariables.ContainsKey("isBeingGuarded"))return "VM掩护缓存原始字段不应被影子值覆盖或写入动作逻辑";
        }
        using var probe=InstallAbilitiesChangedProbes();
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool deck in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);var location=deck?side.DeckOf():side.HqOf();
            var target=state.CreateWithId(PlainUnit,side,60,location,10);target.IsBeingGuarded=true;
            target.Keywords.Remove(Keyword.Guard);target.Keywords.Remove(Keyword.Smokescreen);
            var adjacent=state.CreateWithId(PlainUnit,side,61,location,9);adjacent.Keywords.Remove(Keyword.Guard);
            var observer=state.CreateWithId("card_event_honorifics",side,20,side.DeckOf(),0);
            observer.Definition=new CardDefinition{Name=observer.Name,UsedTriggers=new[]{"OnOtherCardAbilitiesChanged"}};
            var seen=new List<(bool,bool)>();var created=state.CardCreated;
            state.CardCreated=made=>{created?.Invoke(made);if(made.Name=="card_unit_routed_troops")seen.Add((target.IsBeingGuarded,adjacent.IsBeingGuarded));};
            var ctx=new EffectContext{Engine=engine,State=state,Self=target,Controller=side};
            engine.Api.InvokeByName("GiveGuard",null,new object?[]{60,0},ctx,out _);
            engine.Api.InvokeByName("RemoveGuard",null,new object?[]{60,0,true,false},ctx,out _);
            if(!seen.SequenceEqual(deck?new[]{(true,false),(true,false)}:new[]{(false,true),(false,false)}))
                return "Guard授予/撤销必须在T29前更新棋盘缓存，牌库缓存保持";
            if(!deck)
            {
                adjacent.Keywords.Add(Keyword.Guard);
                if(target.IsBeingGuarded||target.Snapshot().IsBeingGuarded)return "raw变化不应隐式重新计算掩护缓存";
                engine.Api.UpdateGuarded(location);
                if(!target.IsBeingGuarded)return "显式刷新须消除raw变化后的旧缓存";
                target.Keywords.Add(Keyword.Guard);target.IsBeingGuarded=true;
                engine.Api.GiveGuard(target);
                if(!target.IsBeingGuarded)return "已有原始Guard的重复授予分支不得刷新缓存";
                target.ReceivedAbilitiesFromCards["guard"]=new List<int>{9,10};
                engine.Api.RemoveGuard(target,9,false,true);
                if(!target.IsBeingGuarded)return "原始Guard仍真时撤销尾链不得刷新缓存";
            }
        }
        foreach(int mode in Enumerable.Range(0,3))
        {
            var(engine,state)=EmptyBoard(db);var target=state.CreateWithId(PlainUnit,Side.Left,60,CardLocation.BoardHqLeft,10);
            target.Keywords.Remove(Keyword.Guard);
            for(int i=0;i<3;i++)
            {
                var other=state.CreateWithId(PlainUnit,Side.Left,61+i,CardLocation.BoardHqLeft,9);
                other.Keywords.Remove(Keyword.Guard);
                if(i==2||mode==2&&i==0)other.Keywords.Add(Keyword.Guard);
                if(mode==1&&i<2){other.Keywords.Add(Keyword.Covert);other.IsRevealed=false;}
            }
            engine.Api.UpdateGuarded(CardLocation.BoardHqLeft);
            if(target.IsBeingGuarded!=(mode==2))return "GetAdjacentCards(true)先取两张再检查Guard/Covert，不得跳过无效邻卡去取第三张";
        }
        return null;
    }

    private static string? RemoveGuardSources(CardDatabase db)
    {
        using var probe=InstallAbilitiesChangedProbes();
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool raw in new[]{false,true})
        foreach(int[]? initial in new int[]?[]{null,Array.Empty<int>(),new[]{9},new[]{9,10},new[]{9,9},new[]{10},new[]{99}})
        foreach(int giver in new[]{-3,0,9,99})
        foreach(bool all in new[]{false,true})
        foreach(bool skip in new[]{false,true})
        foreach(CardLocation location in new[]{side.HqOf(),side.DeckOf(),CardLocation.NotAvailable})
        {
            var(engine,state)=EmptyBoard(db);var target=state.CreateWithId("card_unit_typhoon_mk_ib",side,60,location,1);
            target.Definition=new CardDefinition{Name=target.Name,Type="infantry"};target.Keywords.Remove(Keyword.Guard);
            if(raw)target.Keywords.Add(Keyword.Guard);
            if(initial is not null)target.ReceivedAbilitiesFromCards["guard"]=initial.ToList();
            foreach(int id in new[]{9,10,99})
                target.BuffsBySource[(id,false)]=new CardBuff{SourceCardId=id,Attack=2,Guard=initial?.Count(x=>x==id)??0};
            var observer=state.CreateWithId("card_event_honorifics",side,20,side.DeckOf(),0);
            observer.Definition=new CardDefinition{Name=observer.Name,UsedTriggers=new[]{"OnOtherCardAbilitiesChanged"}};
            observer.BlueprintVariables["_auditT29Count"]=0;var seen=new List<(int,bool)>();var created=state.CardCreated;
            state.CardCreated=made=>{created?.Invoke(made);if(made.Name=="card_unit_routed_troops")
                seen.Add((state.ActionLog.SelectMany(a=>a.SubActions).Count(a=>a.Name=="ZActionRemoveGuard"),target.Keywords.Contains(Keyword.Guard)));};
            bool full=giver<=0||all;
            bool active=full?(raw||initial is {Length:>0}):(initial?.Contains(giver)??false);
            var expected=initial?.ToList();bool endRaw=raw;
            var deltas=new Dictionary<int,int>{{9,0},{10,0},{99,0}};
            if(active&&full)
            {
                if(giver>0&&!(initial?.Contains(giver)??false))deltas[giver]--;
                foreach(int id in initial??Array.Empty<int>())deltas[id]--;
                expected=null;endRaw=false;
            }
            else if(active)
            {
                expected!.RemoveAll(id=>id==giver);deltas[giver]--;
                if(expected.Count==0){expected=null;endRaw=false;}
            }
            engine.Api.InvokeByName("RemoveGuard",null,new object?[]{60,giver,all,skip},
                new EffectContext{Engine=engine,State=state,Self=target,Controller=side},out bool handled);
            bool key=target.ReceivedAbilitiesFromCards.TryGetValue("guard",out var actual);
            if(!handled||key!=(expected is not null)||(expected is not null&&!actual!.SequenceEqual(expected))
                ||target.Keywords.Contains(Keyword.Guard)!=endRaw)
                return $"Guard指定/全部撤销状态错误：{side}/{raw}/{giver}/{all}/{skip}/{location}";
            foreach(int id in new[]{9,10,99})
            {
                int amount=(initial?.Count(x=>x==id)??0)+deltas[id];var buff=target.BuffsBySource[(id,false)];
                if(buff.Guard!=amount||buff.Attack!=2||buff.Clone().Guard!=amount
                    ||target.Snapshot().GuardBuffsBySource.GetValueOrDefault($"{id}/False")!=amount)
                    return "Guard来源递减须保留重复数组计数和独立账本，不得删除同来源其他增益";
            }
            int queries=active&&!endRaw?1:0,notifies=active&&!skip?1:0;
            if(Convert.ToInt32(observer.BlueprintVariables.GetValueOrDefault("_auditT29Count")??0)!=queries
                ||seen.Count!=queries||seen.Any(x=>x!=(notifies,false)))
                return "Guard尾链按原始标志派发T29，且通知在回调之前，不能按有效Guard筛掉";
            var actions=state.ActionLog.SelectMany(a=>a.SubActions).Where(a=>a.Name=="ZActionRemoveGuard").ToArray();
            if(actions.Length!=notifies)return "Guard撤销通知仅遵守来源命中和skipAction，牌库也应通知";
            if(actions.Any(a=>!a.Values.Select(v=>v.Name).SequenceEqual(new[]{"cardID","instigatorID","RemoveAllGivers"})
                ||a.Values[0].Value!=60||a.Values[1].Value!=giver||a.Values[2].Value!=(all?1:0)))
                return "Guard撤销通知必须始终含instigatorID（包括0和负值）及原始RemoveAllGivers";
            var snapshot=target.Snapshot();bool effective=endRaw||expected is {Count:>0};
            if(target.HasGuard!=effective||snapshot.IntrinsicGuard!=endRaw||snapshot.Keywords.Contains(Keyword.Guard)!=effective)
                return "Guard撤销后的快照原始/有效状态混淆";
        }
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool selfSource in new[]{false,true})
        foreach(bool all in new[]{false,true})
        foreach(bool skip in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);var target=state.CreateWithId(PlainUnit,side,60,side.HqOf(),1);
            target.Keywords.Remove(Keyword.Guard);var external=state.CreateWithId(PlainUnit,side,9,side.DeckOf(),0);
            int source=selfSource?60:9;var ctx=new EffectContext{Engine=engine,State=state,Self=target,Controller=side};
            engine.Api.InvokeByName("GiveGuard",null,new object?[]{60,source},ctx,out _);
            engine.Api.InvokeByName("RemoveGuard",null,new object?[]{60,source,all,skip},ctx,out _);
            if(target.HasGuard||target.ReceivedAbilitiesFromCards.ContainsKey("guard")||target.BuffsBySource.ContainsKey((source,false))
                ||(selfSource?target:external).CardsBuffedByThisCard.Contains(60))return "真实Guard授予→撤销未清空来源链及零账本目标登记";
        }
        foreach(int id in new[]{0,-5,99999})
        {
            var(engine,state)=EmptyBoard(db);var target=state.CreateWithId(PlainUnit,Side.Left,60,CardLocation.BoardHqLeft,1);
            target.Keywords.Add(Keyword.Guard);
            engine.Api.InvokeByName("RemoveGuard",target,new object?[]{id,0,true,false},
                new EffectContext{Engine=engine,State=state,Self=target,Target=target,Controller=Side.Left},out _);
            if(!target.HasGuard)return "Guard撤销无效显式ID不得回退到self/target/receiver";
        }
        return null;
    }

    private static string? GiveGuardSources(CardDatabase db)
    {
        using var probe = InstallAbilitiesChangedProbes();
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool raw in new[] { false,true })
        foreach (int[]? initial in new int[]?[] { null,Array.Empty<int>(),new[]{9} })
        foreach (int giver in new[]{-3,0,9,99})
        foreach (CardLocation location in new[]{side.HqOf(),side.DeckOf(),CardLocation.NotAvailable})
        foreach (int smoke in Enumerable.Range(0,4))
        {
            var (engine,state)=EmptyBoard(db);
            var target=state.CreateWithId("card_unit_typhoon_mk_ib",side,60,location,1);
            target.Definition=new CardDefinition { Name=target.Name,Type="infantry" };
            target.Keywords.Remove(Keyword.Guard);if(raw)target.Keywords.Add(Keyword.Guard);
            target.Keywords.Remove(Keyword.Smokescreen);if((smoke&1)!=0)target.Keywords.Add(Keyword.Smokescreen);
            if((smoke&2)!=0)target.ReceivedAbilitiesFromCards["smokescreen"]=new List<int>{9};
            if(initial is not null)target.ReceivedAbilitiesFromCards["guard"]=initial.ToList();
            var source=state.CreateWithId(PlainUnit,side,9,side.DeckOf(),0);
            target.BuffsBySource[(9,false)]=new CardBuff {SourceCardId=9,Attack=2,Guard=initial?.Length??0,Smokescreen=(smoke&2)!=0?1:0};
            var observer=state.CreateWithId("card_event_honorifics",side,20,side.DeckOf(),0);
            observer.Definition=new CardDefinition {Name=observer.Name,UsedTriggers=new[]{"OnOtherCardAbilitiesChanged"}};
            observer.BlueprintVariables["_auditT29Count"]=0;
            var seen=new List<(int Gives,int Removes,bool RawGuard,bool Smoke)>();var created=state.CardCreated;
            state.CardCreated=made=>{created?.Invoke(made);if(made.Name=="card_unit_routed_troops")
                seen.Add((state.ActionLog.SelectMany(a=>a.SubActions).Count(a=>a.Name=="ZActionGiveGuard"),
                    state.ActionLog.SelectMany(a=>a.SubActions).Count(a=>a.Name=="ZActionRemoveSmokescreen"),
                    target.Keywords.Contains(Keyword.Guard),target.HasSmokescreen));};
            var ctx=new EffectContext {Engine=engine,State=state,Self=target,Controller=side};
            bool accepted=giver<=0 || !(initial?.Contains(giver)??false);
            bool changed=accepted&&!raw;
            for(int repeat=0;repeat<2;repeat++)
                engine.Api.InvokeByName("GiveGuard",null,new object?[]{60,giver},ctx,out _);
            var expected=initial?.ToList();if(giver>0&&accepted){expected??=new List<int>();expected.Add(giver);}
            bool key=target.ReceivedAbilitiesFromCards.TryGetValue("guard",out var actual);
            if(key!=(expected is not null)||(expected is not null&&!actual!.SequenceEqual(expected))
                ||target.Keywords.Contains(Keyword.Guard)!=(raw||changed))
                return $"Guard来源去重或授予后原始标志错误：{side}/{raw}/{giver}/{location}/{smoke}";
            foreach(int id in new[]{9,99})
            {
                int amount=(id==9?(initial?.Length??0):0)+(accepted&&giver==id?1:0);
                if((target.BuffsBySource.GetValueOrDefault((id,false))?.Guard??0)!=amount)
                    return "Guard授予必须只为新正来源加一次账本，重复来源不得叠加";
                int expectedSmoke=(id==9&&(smoke&2)!=0?1:0);
                if(changed&&smoke!=0)
                {
                    if((smoke&2)!=0){if(id==9)expectedSmoke--;}
                    else if(giver>0&&giver==id)expectedSmoke--;
                }
                if((target.BuffsBySource.GetValueOrDefault((id,false))?.Smokescreen??0)!=expectedSmoke)
                    return "Guard互斥应复用全部来源烟幕撤销并保留其他账本";
            }
            if(target.BuffsBySource[(9,false)].Attack!=2)return "授予Guard破坏同来源攻击增益";
            bool smokeEnd=!changed&&smoke!=0;
            if(target.HasSmokescreen!=smokeEnd || (changed&&target.ReceivedAbilitiesFromCards.ContainsKey("smokescreen")))
                return "原始Guard已真时不得移除烟幕；新增原始Guard时须撤销全部烟幕";
            int queries=changed?(smoke==0?1:2):0;
            if(Convert.ToInt32(observer.BlueprintVariables.GetValueOrDefault("_auditT29Count")??0)!=queries)
                return "GiveGuard仅首次原始变真派发T29，已有原始Guard只通知";
            int giveCount=location==side.DeckOf()||!accepted?0:(giver>0?1:2);
            int removeCount=location==side.DeckOf()||!changed||smoke==0?0:1;
            if(seen.Any(x=>x!=(location==side.DeckOf()?0:1,removeCount,true,false))||seen.Count!=queries)
                return "应在T29前完成Guard授予通知/烟幕撤销，牌库分支跳过通知";
            var actions=state.ActionLog.SelectMany(x=>x.SubActions).ToArray();
            var gives=actions.Where(x=>x.Name=="ZActionGiveGuard").ToArray();
            if(gives.Length!=giveCount||actions.Count(x=>x.Name=="ZActionRemoveSmokescreen")!=removeCount)
                return "Guard通知必须区分重复非正来源、正来源去重和牌库";
            if(gives.Any(a=>!a.Values.Select(x=>x.Name).SequenceEqual(giver==0?new[]{"cardID"}:new[]{"cardID","instigatorID"})
                ||a.Values[0].Value!=60||(giver!=0&&a.Values[1].Value!=giver)))
                return "Guard通知必须保留cardID和可选非零instigatorID，不能误用giverID";
            if(accepted&&giver==9&&!source.CardsBuffedByThisCard.Contains(60))return "Guard正来源未登记增益目标";
        }
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool selfSource in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);var target=state.CreateWithId("card_unit_typhoon_mk_ib",side,60,side.HqOf(),1);
            target.Definition=new CardDefinition{Name=target.Name,Type="infantry"};
            target.Keywords.Remove(Keyword.Guard);target.Keywords.Remove(Keyword.Smokescreen);
            var external=state.CreateWithId(PlainUnit,side,9,side.DeckOf(),0);
            int source=selfSource?60:9;var ctx=new EffectContext{Engine=engine,State=state,Self=target,Controller=side};
            engine.Api.InvokeByName("GiveGuard",null,new object?[]{60,source},ctx,out _);
            if(!target.Keywords.Contains(Keyword.Guard)||!target.ReceivedAbilitiesFromCards["guard"].SequenceEqual(new[]{source})
                ||target.BuffsBySource[(source,false)].Guard!=1)return "真实Guard授予未形成原始标志/来源/账本链";
            engine.Api.InvokeByName("GiveSmokescreen",null,new object?[]{60,99},ctx,out _);
            if(!target.HasSmokescreen||target.HasGuard==selfSource||target.Keywords.Contains(Keyword.Guard)==selfSource
                ||target.ReceivedAbilitiesFromCards.ContainsKey("guard")==selfSource
                ||(target.BuffsBySource.GetValueOrDefault((source,false))?.Guard??0)!=(selfSource?0:1))
                return "Guard后授予烟幕必须只撤销自身Guard来源，外部来源仍保留";
            if((selfSource?target:external).CardsBuffedByThisCard.Contains(60)==selfSource)
                return "Guard/烟幕连续授予的来源目标登记错误";
        }
        foreach(int priorAmount in new[]{-2,-1,0})
        {
            var(engine,state)=EmptyBoard(db);var target=state.CreateWithId(PlainUnit,Side.Left,60,CardLocation.BoardHqLeft,1);
            target.Keywords.Add(Keyword.Guard);var source=state.CreateWithId(PlainUnit,Side.Left,9,CardLocation.DeckLeft,0);
            target.BuffsBySource[(9,false)]=new CardBuff{SourceCardId=9,Guard=priorAmount};source.CardsBuffedByThisCard.Add(60);
            engine.Api.InvokeByName("GiveGuard",null,new object?[]{60,9},new EffectContext{Engine=engine,State=state,Self=target,Controller=Side.Left},out _);
            int expected=priorAmount+1;
            if((target.BuffsBySource.GetValueOrDefault((9,false))?.Guard??0)!=expected
                ||target.BuffsBySource.ContainsKey((9,false))!=(expected!=0)
                ||source.CardsBuffedByThisCard.Contains(60)!=(expected!=0)
                ||!target.ReceivedAbilitiesFromCards["guard"].SequenceEqual(new[]{9}))
                return "Guard账本须有符号累加、零清账，来源登记独立于数值";
        }
        foreach(int id in new[]{0,-5,99999})
        {
            var(engine,state)=EmptyBoard(db);var target=state.CreateWithId(PlainUnit,Side.Left,60,CardLocation.BoardHqLeft,1);
            target.Keywords.Remove(Keyword.Guard);
            engine.Api.InvokeByName("GiveGuard",target,new object?[]{id,9},new EffectContext{Engine=engine,State=state,Self=target,Target=target,Controller=Side.Left},out _);
            if(target.HasGuard||state.ActionLog.SelectMany(a=>a.SubActions).Any())return "Guard无效显式ID不得回退目标或发动作";
        }
        {
            var(engine,state)=EmptyBoard(db);var target=state.CreateWithId(PlainUnit,Side.Left,60,CardLocation.BoardHqLeft,1);
            target.Keywords.Remove(Keyword.Guard);target.Keywords.Add(Keyword.Covert);target.IsRevealed=false;
            engine.Api.InvokeByName("GiveGuard",null,new object?[]{60,9},new EffectContext{Engine=engine,State=state,Self=target,Controller=Side.Left},out _);
            if(target.HasGuard||target.ReceivedAbilitiesFromCards.ContainsKey("guard"))return "未揭示棋盘Covert应先拒绝Guard增益";
        }
        return null;
    }

    private static string? GiveSmokescreenSources(CardDatabase db)
    {
        using var probe = InstallAbilitiesChangedProbes();
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool raw in new[] { false,true })
        foreach (int[]? initial in new int[]?[] { null,Array.Empty<int>(),new[]{9} })
        foreach (int giver in new[]{-3,0,9,99})
        foreach (CardLocation location in new[]{side.HqOf(),side.DeckOf(),CardLocation.NotAvailable})
        {
            var (engine,state)=EmptyBoard(db);
            var target=state.CreateWithId("card_unit_typhoon_mk_ib",side,60,location,1);
            target.Definition=new CardDefinition { Name=target.Name,Type="infantry" };
            target.Keywords.Remove(Keyword.Smokescreen);if(raw)target.Keywords.Add(Keyword.Smokescreen);
            if(initial is not null)target.ReceivedAbilitiesFromCards["smokescreen"]=initial.ToList();
            var source=state.CreateWithId(PlainUnit,side,9,side.DeckOf(),0);
            target.BuffsBySource[(9,false)]=new CardBuff {SourceCardId=9,Attack=2,Smokescreen=initial?.Length??0};
            var observer=state.CreateWithId("card_event_honorifics",side,20,side.DeckOf(),0);
            observer.Definition=new CardDefinition {Name=observer.Name,UsedTriggers=new[]{"OnOtherCardAbilitiesChanged"}};
            observer.BlueprintVariables["_auditT29Count"]=0;
            var ctx=new EffectContext {Engine=engine,State=state,Self=target,Controller=side};
            bool accepted=giver>0 ? !(initial?.Contains(giver)??false) : !raw;
            // A second identical request must not notify, reapply a ledger entry or query T29.
            for(int repeat=0;repeat<2;repeat++)
                engine.Api.InvokeByName("GiveSmokescreen",null,new object?[]{60,giver},ctx,out _);
            var expected=initial?.ToList();if(giver>0 && accepted){expected??=new List<int>();expected.Add(giver);}
            bool key=target.ReceivedAbilitiesFromCards.TryGetValue("smokescreen",out var actual);
            if(key!=(expected is not null)||(expected is not null&&!actual!.SequenceEqual(expected))
                || target.Keywords.Contains(Keyword.Smokescreen)!=(raw||(accepted&&giver<=0)))
                return $"烟幕授予来源/原始分叉错误：{side}/{raw}/{giver}/{location}, accepted={accepted}, key={key}";
            foreach(int id in new[]{9,99})
            {
                int amount=(id==9?(initial?.Length??0):0)+(accepted&&giver==id?1:0);
                if((target.BuffsBySource.GetValueOrDefault((id,false))?.Smokescreen??0)!=amount)
                    return "烟幕授予账本不应漏记、重复叠加或改写其他来源";
            }
            if(target.BuffsBySource[(9,false)].Attack!=2) return "授予烟幕破坏同来源其他增益";
            int queries=Convert.ToInt32(observer.BlueprintVariables.GetValueOrDefault("_auditT29Count")??0);
            if(queries!=(accepted?1:0)) return "成功烟幕授予须执行一次最终T29，重复授予应直接返回";
            var actions=state.ActionLog.SelectMany(x=>x.SubActions).Where(x=>x.Name=="ZActionGiveSmokescreen").ToArray();
            bool notify=accepted && location!=side.DeckOf();
            if(actions.Length!=(notify?1:0)) return "烟幕授予通知应跳过牌库，重复授予不重发";
            if(notify && (!actions[0].Values.Select(x=>x.Name).SequenceEqual(giver==0?new[]{"cardID"}:new[]{"cardID","giverID"})
                ||actions[0].Values[0].Value!=60||(giver!=0&&actions[0].Values[1].Value!=giver))) return "烟幕授予通知目标或可选非零来源错误";
            if(accepted&&giver==9&&!source.CardsBuffedByThisCard.Contains(60))return "烟幕来源未登记目标";
        }
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool rawGuard in new[]{false,true})
        foreach(int[]? guards in new int[]?[]{null,Array.Empty<int>(),new[]{60},new[]{60,9},new[]{60,60}})
        foreach(CardLocation location in new[]{side.HqOf(),side.DeckOf()})
        {
            var(engine,state)=EmptyBoard(db);var target=state.CreateWithId("card_unit_typhoon_mk_ib",side,60,location,1);
            target.Definition=new CardDefinition{Name=target.Name,Type="infantry"};target.Keywords.Remove(Keyword.Smokescreen);
            target.Keywords.Remove(Keyword.Guard);if(rawGuard)target.Keywords.Add(Keyword.Guard);
            if(guards is not null)target.ReceivedAbilitiesFromCards["guard"]=guards.ToList();
            target.BuffsBySource[(60,false)]=new CardBuff{SourceCardId=60,Guard=guards?.Count(id=>id==60)??0,Attack=2};
            var observer=state.CreateWithId("card_event_honorifics",side,20,side.DeckOf(),0);
            observer.Definition=new CardDefinition{Name=observer.Name,UsedTriggers=new[]{"OnOtherCardAbilitiesChanged"}};
            observer.BlueprintVariables["_auditT29Count"]=0;var seen=new List<int>();var created=state.CardCreated;
            state.CardCreated=made=>{created?.Invoke(made);if(made.Name=="card_unit_routed_troops")
                seen.Add(state.ActionLog.SelectMany(a=>a.SubActions).Count(a=>a.Name=="ZActionGiveSmokescreen"));};
            engine.Api.InvokeByName("GiveSmokescreen",null,new object?[]{60,9},
                new EffectContext{Engine=engine,State=state,Self=target,Controller=side},out _);
            bool removes=guards?.Contains(60)??false;var remaining=guards?.Where(id=>id!=60).ToArray();
            bool endRaw=rawGuard && !(removes&&remaining!.Length==0);
            bool endKey=guards is not null && !(removes&&remaining!.Length==0);
            bool hasKey=target.ReceivedAbilitiesFromCards.TryGetValue("guard",out var actual);
            if(target.Keywords.Contains(Keyword.Guard)!=endRaw||hasKey!=endKey
                ||(endKey&&!actual!.SequenceEqual(removes?remaining!:guards!)))return "烟幕授予应只撤销自身Guard来源，非直接剥除全部Guard";
            int amount=(guards?.Count(id=>id==60)??0)-(removes?1:0);
            var buff=target.BuffsBySource[(60,false)];
            if(buff.Guard!=amount||buff.Attack!=2||buff.Clone().Guard!=amount
                ||target.Snapshot().GuardBuffsBySource.GetValueOrDefault("60/False")!=amount)return "自身Guard来源账本/克隆/快照错误";
            int queries=1+(removes&&!endRaw?1:0),notifies=location==side.DeckOf()?0:1;
            if(Convert.ToInt32(observer.BlueprintVariables.GetValueOrDefault("_auditT29Count")??0)!=queries
                ||!seen.SequenceEqual(Enumerable.Repeat(notifies,queries)))return "应先通知，再执行Guard依赖的T29，最后执行烟幕自身T29";
            if(state.ActionLog.SelectMany(a=>a.SubActions).Any(a=>a.Name=="ZActionRemoveGuard"))return "烟幕Guard依赖skipAction=true不应产生移除通知";
        }
        foreach(Side side in new[]{Side.Left,Side.Right})
        foreach(bool move in new[]{false,true})
        {
            var(engine,state)=EmptyBoard(db);state.ActiveSide=side;state.SetKredits(side,20);
            var target=state.CreateWithId("card_unit_typhoon_mk_ib",side,60,side.HqOf(),1);
            target.Definition=new CardDefinition{Name=target.Name,Type="infantry",Range=2,Attack=2,Defense=20};
            target.Attack=2;target.Defense=target.MaxDefense=20;target.OperationCost=0;target.EnteredPlayOnTurn=-99;
            target.Keywords.Remove(Keyword.Smokescreen);var giver=state.CreateWithId(PlainUnit,side,9,side.DeckOf(),0);
            engine.Api.InvokeByName("GiveSmokescreen",null,new object?[]{60,9},new EffectContext{Engine=engine,State=state,Self=target,Controller=side},out _);
            if(!target.HasSmokescreen||target.Keywords.Contains(Keyword.Smokescreen)
                ||target.BuffsBySource[(9,false)].Smokescreen!=1||!giver.CardsBuffedByThisCard.Contains(60))return "真实授予未形成独立来源链";
            bool ok=move?engine.MoveUnit(target,0):engine.Attack(target,state.Hq(side.Opposite()));
            if(!ok||target.HasSmokescreen||target.ReceivedAbilitiesFromCards.ContainsKey("smokescreen")
                ||target.BuffsBySource.ContainsKey((9,false))||giver.CardsBuffedByThisCard.Contains(60))return "授予后攻击/推进未完整撤销来源链";
        }
        foreach(int id in new[]{0,-5,99999})
        {
            var(engine,state)=EmptyBoard(db);var target=state.CreateWithId(PlainUnit,Side.Left,60,CardLocation.BoardHqLeft,1);
            target.Keywords.Remove(Keyword.Smokescreen);
            engine.Api.InvokeByName("GiveSmokescreen",target,new object?[]{id,9},new EffectContext{Engine=engine,State=state,Self=target,Target=target,Controller=Side.Left},out _);
            if(target.HasSmokescreen)return "烟幕授予无效显式ID不应回退到self/target/receiver";
        }
        {
            var(engine,state)=EmptyBoard(db);var target=state.CreateWithId(PlainUnit,Side.Left,60,CardLocation.BoardHqLeft,1);
            target.Keywords.Remove(Keyword.Smokescreen);target.Keywords.Add(Keyword.Covert);target.IsRevealed=false;
            engine.Api.InvokeByName("GiveSmokescreen",null,new object?[]{60,9},new EffectContext{Engine=engine,State=state,Self=target,Controller=Side.Left},out _);
            if(target.HasSmokescreen||target.ReceivedAbilitiesFromCards.ContainsKey("smokescreen"))return "烟幕授予须先通过CanCardBeBuffed";
        }
        if(new CardBuff{Guard=1}.IsEmpty)return "Guard详情独立来源记录不能被当作空增益";
        return null;
    }

    private static string? RemoveSmokescreenSources(CardDatabase db)
    {
        using var probe = InstallAbilitiesChangedProbes();
        // Raw, sources, giver, removeAll, final raw/sources, ledger deltas, notify, loss, static extra decrement.
        var cases = new (bool Raw, int[]? Ids, int Giver, bool All, bool EndRaw, int[]? EndIds,
            int D9, int D10, int D99, bool Notify, bool Loss, bool StaticExtra)[] {
            (false, new[]{9,10}, 9, false, false, new[]{10}, -1,0,0, true,false,false),
            (false, new[]{9}, 9, false, false, Array.Empty<int>(), -1,0,0, true,true,false),
            (true, new[]{9}, 9, false, true, Array.Empty<int>(), -1,0,0, true,false,false),
            (true, new[]{9,10}, 99, false, true, new[]{9,10}, 0,0,0, false,false,false),
            (false, null, 99, false, false, null, 0,0,0, false,false,false),
            (true, null, 99, true, false, null, 0,0,-1, true,true,false),
            (false, new[]{9,10}, 99, true, false, null, -1,-1,0, true,true,true),
            (true, new[]{9,10}, 99, true, false, null, -1,-1,0, true,true,true),
            (false, new[]{9,9}, 9, false, false, Array.Empty<int>(), -1,0,0, true,true,false),
            (false, new[]{9,9}, 0, false, false, null, -2,0,0, true,true,false),
            (false, Array.Empty<int>(), 99, true, false, Array.Empty<int>(), 0,0,0, false,false,false),
            (true, Array.Empty<int>(), 0, false, false, null, 0,0,0, true,true,false),
            (false, new[]{9}, -3, false, false, null, -1,0,0, true,true,false),
            (true, null, 9, false, true, null, 0,0,0, false,false,false),
            (true, new[]{9}, 9, true, false, null, -1,0,0, true,true,false),
            (true, null, 0, false, false, null, 0,0,0, true,true,false),
        };
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (string name in new[] { "card_unit_typhoon_mk_ib", "card_unit_85_pioneer_company" })
        foreach (bool skip in new[] { false, true })
        foreach (var test in cases)
        {
            var (engine, state) = EmptyBoard(db);
            var target = state.CreateWithId(name, side, 60, side.HqOf(), 1);
            target.Definition = new CardDefinition { Name = name, Type = "infantry" };
            target.Keywords.Remove(Keyword.Smokescreen);if (test.Raw) target.Keywords.Add(Keyword.Smokescreen);
            if (test.Ids is not null) target.ReceivedAbilitiesFromCards["smokescreen"] = test.Ids.ToList();
            foreach (int id in new[] { 9,10,99 })
            {
                state.CreateWithId(PlainUnit, side, id, side.DeckOf(), id);
                target.BuffsBySource[(id,false)] = new CardBuff { SourceCardId = id, Attack = 2,
                    Smokescreen = test.Ids?.Count(x => x == id) ?? 0 };
            }
            var observer = state.CreateWithId("card_event_honorifics", side, 20, side.DeckOf(), 0);
            observer.Definition = new CardDefinition { Name = observer.Name, UsedTriggers = new[]{"OnOtherCardAbilitiesChanged"} };
            observer.BlueprintVariables["_auditT29Count"] = 0;
            var ctx = new EffectContext { Engine = engine, State = state, Self = target, Controller = side };
            engine.Api.InvokeByName("RemoveSmokescreen", null,
                new object?[]{60,test.Giver,test.All,skip}, ctx, out bool handled);
            bool hasKey = target.ReceivedAbilitiesFromCards.TryGetValue("smokescreen", out var ids);
            if (!handled || target.Keywords.Contains(Keyword.Smokescreen) != test.EndRaw
                || hasKey != (test.EndIds is not null) || (test.EndIds is not null && !ids!.SequenceEqual(test.EndIds)))
                return $"烟幕指定/全部撤销状态错误：{side}/{name}/{skip}/{test.Giver}/{test.All}, raw={target.Keywords.Contains(Keyword.Smokescreen)}, key={hasKey}";
            int[] deltas = { test.D9, test.D10, test.D99 - (test.StaticExtra && db.Require(name).Keywords.Contains(Keyword.Smokescreen) ? 1 : 0) };
            int index = 0;
            foreach (int id in new[] {9,10,99})
            {
                var buff = target.BuffsBySource[(id,false)];int expected = (test.Ids?.Count(x => x == id) ?? 0) + deltas[index++];
                if (buff.Smokescreen != expected || buff.Attack != 2 || buff.Clone().Smokescreen != expected)
                    return "烟幕来源账本递减或克隆错误，不得撤销同来源其他增益";
                var snapshot = target.Snapshot();
                if (snapshot.SmokescreenBuffsBySource.GetValueOrDefault($"{id}/False") != expected
                    || snapshot.IntrinsicSmokescreen != test.EndRaw
                    || snapshot.Keywords.Contains(Keyword.Smokescreen) != target.HasSmokescreen)
                    return "快照须分别保留烟幕原始标志、有效关键词及来源账本";
            }
            int events = Convert.ToInt32(observer.BlueprintVariables.GetValueOrDefault("_auditT29Count") ?? 0);
            if (events != (test.Loss ? 1 : 0)) return "仍有原始/其他来源烟幕时不应发T48/T29尾链，完全失去时应发";
            var actions = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionRemoveSmokescreen").ToArray();
            if (actions.Length != (test.Notify && !skip ? 1 : 0)) return "烟幕通知未遵守无效来源或skipAction";
            if (actions.Length == 1)
            {
                var values = actions[0].Values;string[] names = test.Giver == 0 ? new[]{"cardID","RemoveAllGivers"} : new[]{"cardID","RemoveAllGivers","giverID"};
                if (!values.Select(x => x.Name).SequenceEqual(names) || values[0].Value != 60
                    || values[1].Value != (test.All ? 1 : 0) || (test.Giver != 0 && values[2].Value != test.Giver))
                    return "烟幕通知字段顺序、目标、原始RemoveAllGivers或可选来源错误";
            }
        }
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool move in new[] { false, true })
        foreach (bool raw in new[] { false, true })
        foreach (bool sourced in new[] { false, true })
        {
            var (engine,state) = EmptyBoard(db);var unit = MakeActionQuotaProbe(state,side,"infantry");
            unit.Keywords.Remove(Keyword.Smokescreen);if (raw) unit.Keywords.Add(Keyword.Smokescreen);
            var giver = state.CreateWithId(PlainUnit,side,9,side.DeckOf(),0);
            if (sourced)
            {
                unit.ReceivedAbilitiesFromCards["smokescreen"] = new List<int>{9};
                unit.BuffsBySource[(9,false)] = new CardBuff { SourceCardId=9,Smokescreen=1 };
                giver.CardsBuffedByThisCard.Add(unit.CardId);
            }
            bool ok = move ? engine.MoveUnit(unit,0) : engine.Attack(unit,state.Hq(side.Opposite()));
            if (!ok || unit.HasSmokescreen || unit.ReceivedAbilitiesFromCards.ContainsKey("smokescreen"))
                return "攻击/推进必须经有效烟幕判据清除全部来源";
            if (sourced && (unit.BuffsBySource.ContainsKey((9,false)) || giver.CardsBuffedByThisCard.Contains(unit.CardId)))
                return "烟幕唯一增益归零时须清理空账本和来源目标登记";
            var actions = state.ActionLog.SelectMany(x=>x.SubActions).Where(x=>x.Name=="ZActionRemoveSmokescreen").ToArray();
            if (actions.Length != (raw || sourced ? 1 : 0)) return "攻击/推进烟幕清除次数错误";
            if (actions.Length == 1 && (!actions[0].Values.Select(v=>v.Name).SequenceEqual(new[]{"cardID","RemoveAllGivers","giverID"})
                || actions[0].Values[0].Value!=60 || actions[0].Values[1].Value!=1 || actions[0].Values[2].Value!=60))
                return "攻击/推进应以自身ID、RemoveAllGivers=true发起烟幕移除";
        }
        // Invalid explicit IDs must not resolve to receiver, target or self.
        foreach (int id in new[]{0,-5,99999})
        {
            var (engine,state) = EmptyBoard(db);var target = state.CreateWithId(PlainUnit,Side.Left,60,CardLocation.BoardHqLeft,1);
            target.Keywords.Add(Keyword.Smokescreen);
            engine.Api.InvokeByName("RemoveSmokescreen", target, new object?[]{id,0,true,false},
                new EffectContext { Engine=engine,State=state,Self=target,Target=target,Controller=Side.Left },out _);
            if (!target.Keywords.Contains(Keyword.Smokescreen)) return "无效烟幕目标ID错误回退到调用者";
        }
        if (new CardBuff { Smokescreen=1 }.IsEmpty || new CardBuff { Smokescreen=-1 }.Clone().Smokescreen != -1)
            return "独立烟幕账本不能被空增益清理或克隆丢失";
        return null;
    }

    private static string? NativeGuardReadContract(CardDatabase db)
    {
        int[]?[] sources = { new[] { 9 }, null, Array.Empty<int>(), new[] { 0 }, new[] { -5 }, new[] { 9, 9 } };
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool raw in new[] { false, true })
        foreach (int[]? ids in sources)
        foreach (bool suppressed in new[] { false, true })
        foreach (CardLocation location in new[] { side.HqOf(), side.DeckOf(), CardLocation.NotAvailable })
        foreach (int ledger in new[] { 0, -7, 7 })
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId(PlainUnit, side, 60, location, 1);
            card.Keywords.Remove(Keyword.Guard);if (raw) card.Keywords.Add(Keyword.Guard);
            if (suppressed) card.Keywords.Add(Keyword.Suppressed);
            if (ids is not null) card.ReceivedAbilitiesFromCards["guard"] = ids.ToList();
            card.BuffsBySource[(99, false)] = new CardBuff { Guard = ledger };
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            object? Read() => engine.Api.InvokeByName("getHasGuard", card, new object?[] { null }, ctx, out _);
            bool nonempty = ids is { Length: > 0 };
            if (!Equals(Read(), raw || nonempty))
                return $"原生Guardgetter遗漏来源数组：{side}/{raw}/{(ids is null ? "absent" : string.Join(",", ids))}/{suppressed}/{location}, result={Read()}";
            var snapshot = card.Snapshot();var clone = card.BuffsBySource[(99, false)].Clone();
            if (snapshot.Keywords.Contains(Keyword.Guard) != (raw || nonempty)
                || snapshot.IntrinsicGuard != raw
                || clone.Guard != ledger)
                return "Guard快照须区分有效状态与原始状态，克隆保留独立账本";
            int actions = state.ActionLog.Count;var trace = new List<string>();engine.Api.TriggerTrace = trace;
            card.BlueprintVariables["hasGuard"] = !raw;
            KismetStep Set(int i, string key, KismetExpr value, string scope) => new(i, "set", null,
                Array.Empty<KismetExpr>(), Array.Empty<int>(), value, null, -1, key, null) { DestinationScope = scope };
            var program = new KismetProgram(new[] {
                Set(0, "beforeRaw", new() { Var = "hasGuard", Scope = "instance" }, "local"),
                Set(1, "hasGuard", new() { Bool = !raw }, "instance"),
                Set(2, "afterRaw", new() { Var = "hasGuard", Scope = "instance" }, "local"),
                new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null)
            }, 0);
            var result = engine.Api.Vm.RunLocalProgramMulti(program, ctx, null, "beforeRaw", "afterRaw");
            if (!Equals(result["beforeRaw"], raw) || !Equals(result["afterRaw"], !raw)
                || card.Keywords.Contains(Keyword.Guard) != !raw || card.BlueprintVariables.ContainsKey("hasGuard")
                || !Equals(Read(), !raw || nonempty)) return "VM原始Guard字段与有效来源读取混淆或存在影子字段";
            if (state.ActionLog.Count != actions || trace.Count != 0) return "原始Guard字段写入不应自动调用授予/移除或派发事件";
            if ((ids is null && card.ReceivedAbilitiesFromCards.ContainsKey("guard"))
                || (ids is not null && !card.ReceivedAbilitiesFromCards["guard"].SequenceEqual(ids))) return "只读/原始写入破坏独立Guard来源数组";
        }
        return null;
    }

    private static string? NativeSmokescreenReadContract(CardDatabase db)
    {
        int[]?[] sources = { new[] { 9 }, null, Array.Empty<int>(), new[] { 0 }, new[] { -5 }, new[] { 9, 9 } };
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool raw in new[] { false, true })
        foreach (int[]? ids in sources)
        foreach (bool suppressed in new[] { false, true })
        foreach (CardLocation location in new[] { side.HqOf(), side.DeckOf(), CardLocation.NotAvailable })
        {
            var (engine, state) = EmptyBoard(db);
            var card = state.CreateWithId(PlainUnit, side, 60, location, 1);
            card.Keywords.Remove(Keyword.Smokescreen);if (raw) card.Keywords.Add(Keyword.Smokescreen);
            if (suppressed) card.Keywords.Add(Keyword.Suppressed);
            if (ids is not null) card.ReceivedAbilitiesFromCards["smokescreen"] = ids.ToList();
            var ctx = new EffectContext { Engine = engine, State = state, Self = card, Controller = side };
            object? Read() => engine.Api.InvokeByName("getHasSmokescreen", card, new object?[] { null }, ctx, out _);
            bool nonempty = ids is { Length: > 0 };
            if (!Equals(Read(), raw || nonempty))
                return $"原生烟幕getter遗漏来源数组：{side}/{raw}/{(ids is null ? "absent" : string.Join(",", ids))}/{suppressed}/{location}, result={Read()}";
            int actions = state.ActionLog.Count;var trace = new List<string>();engine.Api.TriggerTrace = trace;
            card.BlueprintVariables["hasSmokescreen"] = !raw;
            KismetStep Set(int i, string key, KismetExpr value, string scope) => new(i, "set", null,
                Array.Empty<KismetExpr>(), Array.Empty<int>(), value, null, -1, key, null) { DestinationScope = scope };
            var program = new KismetProgram(new[] {
                Set(0, "beforeRaw", new() { Var = "hasSmokescreen", Scope = "instance" }, "local"),
                Set(1, "hasSmokescreen", new() { Bool = !raw }, "instance"),
                Set(2, "afterRaw", new() { Var = "hasSmokescreen", Scope = "instance" }, "local"),
                new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null)
            }, 0);
            var result = engine.Api.Vm.RunLocalProgramMulti(program, ctx, null, "beforeRaw", "afterRaw");
            if (!Equals(result["beforeRaw"], raw) || !Equals(result["afterRaw"], !raw)
                || card.Keywords.Contains(Keyword.Smokescreen) != !raw || card.BlueprintVariables.ContainsKey("hasSmokescreen")
