                if (mode == 10) last.SuppressionExceptionTriggers.Clear();
                if (mode == 11) AddLate(63);
                if (mode == 13) state.StopFurtherActions = true;
                if (mode == 14) { state.Remove(last);AddLate(62); }
            };
            bool includeLast = mode switch { 1 or 3 => suppressed, 2 or 4 => !suppressed, 8 or 9 => false, _ => true };
            var expected = new List<CardInstance> { first };if (includeLast) expected.Add(last);
            if (!engine.Attack(attacker, target, out string reason)) return $"攻击后快照布景失败：{side}/{suppressed}/{mode}, {reason}";
            if (mode == 12 && !suppressed) expected.Add(late!);
            if (ownCalled != !suppressed || !called.SequenceEqual(expected))
                return $"攻击后查询时机或快照错误：{side}/{suppressed}/{mode}, own={ownCalled}, expected={string.Join(",", expected.Select(c => c.CardId))}, actual={string.Join(",", called.Select(c => c.CardId))}";
            if (ownCalled && (!ReferenceEquals(attacker.BlueprintVariables.GetValueOrDefault("_auditAfterDefender"), target)
                || !Equals(attacker.BlueprintVariables.GetValueOrDefault("_auditAfterCost"), 3)
                || !Equals(attacker.BlueprintVariables.GetValueOrDefault("_auditAfterShock"), false)))
                return "攻击后自身defender/费用/冲击标志载荷错误";
            foreach (var card in called)
                if (!ReferenceEquals(card.BlueprintVariables.GetValueOrDefault("_auditAfterDefender"), target)
                    || !ReferenceEquals(card.BlueprintVariables.GetValueOrDefault("_auditAfterAttacker"), attacker)
                    || !Equals(card.BlueprintVariables.GetValueOrDefault("_auditAfterCost"), 3)
                    || !Equals(card.BlueprintVariables.GetValueOrDefault("_auditAfterDamage"), 2)) return "T4攻击者/防守者/费用/伤害载荷错误";
            if (mode == 15 && ownCalled && late?.BlueprintVariables.GetValueOrDefault("_auditAfterOther") is true)
                return "T4须按ID排除同ID新对象";
            if (state.Kredits(side) != 17 || state.OperationKreditsSpentThisTurn != 3 || attacker.AttacksThisTurn != 1)
                return "攻击后查询回调不应改变既定行动费和攻击消费";
        }
        return null;
    }

