            replacement.Defense = replacement.MaxDefense = 20;replacement.KreditsTaxAsEnemyTarget = 9;
            var cards = new[] {
                mode == 8 ? attacker : state.CreateWithId(name, side, 61, side.DeckOf(), 0),
                state.CreateWithId(name, side, 62, side.DeckOf(), 1),
                state.CreateWithId(name, side, 63, side.DeckOf(), 2) };
            foreach (var card in cards)
            {
                card.Definition = new CardDefinition { Name = name, Type = "infantry", Attack = 2, Defense = 20,
                    Range = 2, UsedTriggers = new[] { trigger } };
                card.BlueprintVariables["_auditReplacement"] = original;
            }
            if (winner != 0) cards[winner - 1].BlueprintVariables["_auditReplacement"] = replacement;
            if (mode is 4 or 6) cards[1].Keywords.Add(Keyword.Suppressed);
            if (mode == 6) cards[1].SuppressionExceptionTriggers.Add(trigger);
            if (mode == 5) cards[1].Definition = new CardDefinition { Name = name };
            var queried = mode is 4 or 5 ? new[] { cards[0], cards[2] } : cards;
            var expected = new List<CardInstance>();
            foreach (var card in queried) { expected.Add(card);if (winner != 0 && ReferenceEquals(card, cards[winner - 1])) break; }
            var called = new List<CardInstance>();var created = state.CardCreated;CardInstance? late = null;
            state.CardCreated = made => {
                created?.Invoke(made);if (made.Name != "card_unit_routed_troops") return;
                var current = cards.Single(c => !called.Contains(c) && Equals(c.BlueprintVariables.GetValueOrDefault("_auditT30Called"), true));
                called.Add(current);if (called.Count != 1) return;
                if (mode == 1) cards[1].Keywords.Add(Keyword.Suppressed);
                if (mode == 2) cards[1].Location = CardLocation.NotAvailable;
                if (mode == 3) cards[1].Definition = new CardDefinition { Name = name };
                if (mode == 4) cards[1].Keywords.Remove(Keyword.Suppressed);
                if (mode == 5) cards[1].Definition = new CardDefinition { Name = name, UsedTriggers = new[] { trigger } };
                if (mode == 6) cards[1].SuppressionExceptionTriggers.Clear();
                if (mode == 9) state.Remove(cards[1]);
                if (mode is 7 or 9)
                {
                    late = state.CreateWithId(name, side, mode == 9 ? 62 : 64, side.DeckOf(), 3);
                    late.Definition = new CardDefinition { Name = name, UsedTriggers = new[] { trigger } };
                    late.BlueprintVariables["_auditReplacement"] = replacement;
                }
            };
            int hp = original.Defense, replacementHp = replacement.Defense;
            if (!engine.Attack(attacker, original, out string reason) || !called.SequenceEqual(expected))
                return $"T30查询快照/首换停止错误：{side}/{mode}/{winner}, expected={string.Join(",", expected.Select(c => c.CardId))}, actual={string.Join(",", called.Select(c => c.CardId))}, reason={reason}";
            bool switched = winner != 0 && expected.Contains(cards[winner - 1]);
            if (original.Defense != hp - (switched ? 0 : 2) || replacement.Defense != replacementHp - (switched ? 2 : 0)
                || state.Kredits(side) != 15 || state.OperationKreditsSpentThisTurn != 5 || attacker.AttacksThisTurn != 1
                || late?.BlueprintVariables.GetValueOrDefault("_auditT30Called") is true)
                return $"T30保存对象身份/最终目标或原税费用错误：{side}/{mode}/{winner}";
        }
        return null;
    }

    private static string? AttackStopFlagContract(CardDatabase db)
    {
        const string name = "card_unit_typhoon_mk_ib", trigger = "OnOtherCardAttacks";
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(name, trigger) is not null) return "无法安全安装全局停止标志探针";
        KismetStep Set(int i, string output, string source) => new(i, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
            new KismetExpr { Var = source, Scope = "instance" }, null, -1, output, null) { DestinationScope = "local" };
        locals.Add(trigger, new[] {
            new KismetStep(0, "call", "SpawnCardInDeckBySide", new[] {
                new KismetExpr { Int = (int)Side.Left }, new KismetExpr { Str = "card_unit_routed_troops" },
                new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
            }, Array.Empty<int>(), null, null, -1, null, null),
            Set(1, "stopAttack", "_auditStop"), Set(2, "AttackedAndStopped", "_auditAttackedStop"),
            new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null) });
        using var cleanup = new AuditProbeCleanup(() => locals.Remove(trigger));
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool initial in new[] { false, true })
        foreach (int mode in Enumerable.Range(0, 9))
        {
            var (engine, state) = EmptyBoard(db);var attacker = MakeActionQuotaProbe(state, side, "infantry");
            attacker.OperationCost = 3;state.SetKredits(side, 20);
            var target = state.Hq(side.Opposite());int hp = target.Defense;
            var observers = Enumerable.Range(0, 3).Select(i => state.CreateWithId(name, side, 61 + i, side.DeckOf(), i)).ToArray();
            foreach (var card in observers)
            {
                card.Definition = new CardDefinition { Name = name, UsedTriggers = new[] { trigger } };
                card.BlueprintVariables["_auditStop"] = false;card.BlueprintVariables["_auditAttackedStop"] = false;
            }
            observers[0].BlueprintVariables["_auditStop"] = mode is 1 or 2 or 4 or 5 or 8;
            observers[1].BlueprintVariables["_auditStop"] = mode == 4;
            observers[1].BlueprintVariables["_auditAttackedStop"] = mode == 5;
            var ctx = new EffectContext { Engine = engine, State = state, Self = attacker, Controller = side };
            void Write(bool value) => engine.Api.InvokeByName("SetStopAttack", null, new object?[] { value }, ctx, out _);
            bool Read() => engine.Api.InvokeByName("GetStopAttack", null, new object?[] { null }, ctx, out _) is true;
            engine.Api.InvokeByName("SetStopAttack", null, new object?[] { initial }, ctx, out bool setter);
            object? first = engine.Api.InvokeByName("GetStopAttack", null, new object?[] { null }, ctx, out bool getter);
            if (!setter || !getter || !Equals(first, initial)) return "全局停止标志API未保持布尔值";
            CardInstance? nested = null;
            if (mode == 8)
            {
                nested = state.CreateWithId(PlainUnit, side, 64, side.HqOf(), 1);
                nested.Definition = attacker.Definition;nested.Attack = 2;nested.Defense = nested.MaxDefense = 20;
                nested.OperationCost = 1;nested.EnteredPlayOnTurn = -99;
            }
            bool insideNested = false, nestedOk = false;int nestedCalls = 0;
            int calls = 0;var seen = new List<bool>();var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);if (made.Name != "card_unit_routed_troops") return;
                if (insideNested) { nestedCalls++; return; }
                calls++;seen.Add(Read());
                if (calls == 2 && mode == 8)
                {
                    observers[0].BlueprintVariables["_auditStop"] = false;insideNested = true;
                    try { nestedOk = engine.Attack(nested!, target); }
                    finally { insideNested = false;observers[0].BlueprintVariables["_auditStop"] = true; }
                }
                if (calls == 1 && mode == 6) observers[2].Location = CardLocation.NotAvailable;
                if (calls == 1 && mode == 7) observers[2].Keywords.Add(Keyword.Suppressed);
                if (calls == 2 && mode is 2 or 4 or 5) Write(false);
                if (calls == 2 && mode == 3) Write(true);
            };
            bool cancelled = mode is 1 or 3 or 4;
            if (!engine.Attack(attacker, target, out string reason) || calls != 3)
                return $"T31全局标志布景/快照错误：{side}/{initial}/{mode}, calls={calls}, reason={reason}";
            bool beforeSecond = mode is 1 or 2 or 4 or 5 or 8;
            if (!seen.SequenceEqual(new[] { false, beforeSecond, cancelled }) || Read() != cancelled)
                return $"T31未按逐项回调更新全局状态：{side}/{initial}/{mode}, seen={string.Join(",", seen)}, final={Read()}";
            if (mode == 8 && (!nestedOk || nestedCalls != 3 || nested!.AttacksThisTurn != 1))
                return "T31嵌套攻击未完整执行且不应恢复外层旧停止标志";
            int cost = cancelled ? 0 : mode == 8 ? 4 : 3, attacks = cancelled ? 0 : 1;
            int damage = cancelled || mode == 5 ? 0 : mode == 8 ? 4 : 2;
            if (state.Kredits(side) != 20 - cost || state.OperationKreditsSpentThisTurn != cost
                || attacker.AttacksThisTurn != attacks || target.Defense != hp - damage)
                return $"T31最终全局标志未决定扣费/消耗：{side}/{initial}/{mode}";
        }
        return null;
    }

    private static string? AttackCostCaptureContract(CardDatabase db)
    {
        const string probeName = "card_unit_meteor", switchEvent = "OnOtherCardAttackSwitchTarget", attackEvent = "OnOtherCardAttacks";
        if (KismetLibrary.Default?.Find(probeName)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals)
            return "缺少攻击费用探针容器";
        foreach (string trigger in new[] { switchEvent, attackEvent })
            if (KismetLibrary.Default.FindProgram(probeName, trigger) is not null) return "不能覆盖已有攻击函数";
        KismetStep Set(int i, string output, string source) => new(i, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
            new KismetExpr { Var = source, Scope = "instance" }, null, -1, output, null) { DestinationScope = "local" };
        KismetStep Marker() => new(0, "call", "SpawnCardInDeckBySide", new[] {
            new KismetExpr { Int = (int)Side.Left }, new KismetExpr { Str = "card_unit_routed_troops" },
            new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 }
        }, Array.Empty<int>(), null, null, -1, null, null);
        KismetStep End(int i) => new(i, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null);
        locals.Add(switchEvent, new[] { Marker(), Set(1, "newDefender", "_auditReplacement"), End(2) });
        locals.Add(attackEvent, new[] { Marker(), Set(1, "stopAttack", "_auditStop"), Set(2, "AttackedAndStopped", "_auditAttackedStop"), End(3) });
        using var cleanup = new AuditProbeCleanup(() => { locals.Remove(switchEvent); locals.Remove(attackEvent); });
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (int tax in new[] { -2, 0, 3 })
        foreach (bool replace in new[] { false, true })
        foreach (int delta in new[] { -2, 5 })
        foreach (int stop in new[] { 0, 1, 2 })
        {
            var (engine, state) = EmptyBoard(db);
            var attacker = MakeActionQuotaProbe(state, side, "infantry");attacker.OperationCost = 3;
            var original = state.Hq(side.Opposite());original.KreditsTaxAsEnemyTarget = tax;
            var replacement = state.CreateWithId(PlainUnit, side.Opposite(), 61, side.Opposite().HqOf(), 1);
            replacement.Defense = replacement.MaxDefense = 20;replacement.KreditsTaxAsEnemyTarget = 12;
            var observer = state.CreateWithId(probeName, side, 62, side.DeckOf(), 0);
            observer.Definition = new CardDefinition { Name = probeName, UsedTriggers = new[] { switchEvent, attackEvent } };
            observer.BlueprintVariables["_auditReplacement"] = replace ? replacement : original;
            observer.BlueprintVariables["_auditStop"] = stop == 1;
            observer.BlueprintVariables["_auditAttackedStop"] = stop == 2;
            state.SetKredits(side, 20);int callbacks = 0;
            var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name != "card_unit_routed_troops") return;
                callbacks++;attacker.OperationCost = 3 + delta + callbacks - 1;
                original.KreditsTaxAsEnemyTarget = 8;replacement.KreditsTaxAsEnemyTarget = 14;
            };
            int originalHp = original.Defense, replacementHp = replacement.Defense;
            int expectedCost = stop == 1 ? 0 : 3 + Math.Max(0, tax);
            if (!engine.Attack(attacker, original, out string reason) || callbacks != 2)
                return $"攻击快照布景失败：{side}/{tax}/{replace}/{delta}/{stop}, calls={callbacks}, reason={reason}";
            if (state.Kredits(side) != 20 - expectedCost || state.OperationKreditsSpentThisTurn != expectedCost
                || attacker.OperationCost != 4 + delta || attacker.AttacksThisTurn != (stop == 1 ? 0 : 1))
                return $"攻击未沿用早期费用或中止扣费错误：{side}/{tax}/{replace}/{delta}/{stop}, funds={state.Kredits(side)}, spent={state.OperationKreditsSpentThisTurn}";
            int originalDamage = stop == 0 && !replace ? 2 : 0, replacementDamage = stop == 0 && replace ? 2 : 0;
            if (original.Defense != originalHp - originalDamage || replacement.Defense != replacementHp - replacementDamage)
                return "攻击替换或中止结果未与费用快照场景对应";
        }
        return null;
    }

    private static string? TotalOperationCostBounds(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (var pair in new[] { (int.MinValue, 0), (-10, 0), (-1, 0), (0, 0), (1, 1), (98, 98), (99, 99), (100, 100), (int.MaxValue, int.MaxValue) })
        {
            var (engine, state) = EmptyBoard(db);
            var source = MakeActionQuotaProbe(state, side, "infantry");source.OperationCost = pair.Item1;
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            var result = engine.Api.InvokeByName("getTotalOperationCost", source, new object?[] { null }, ctx, out bool handled);
            if (!handled || !Equals(result, pair.Item2) || source.OperationCost != pair.Item1)
                return $"总行动费边界或原值保留错误：{side}/{pair.Item1}, result={result}";
        }
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (var pair in new[] { (-5, 0), (0, 0), (99, 99), (100, 100) })
        foreach (int mode in new[] { 0, 1, 2 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = MakeActionQuotaProbe(state, side, "infantry");source.OperationCost = pair.Item1;
            var target = state.Hq(side.Opposite());target.KreditsTaxAsEnemyTarget = mode == 2 ? 2 : 0;
            int cost = pair.Item2 + (mode == 2 ? 2 : 0);
            if (mode != 0)
            {
                state.SetKredits(side, cost);
                if (!engine.Api.CanSelectAsTarget(source, target, false).Can)
                    return $"行动目标判据未读取总费用：{side}/{pair.Item1}/{mode}";
                if (cost > 0)
                {
                    state.SetKredits(side, cost - 1);
                    if (engine.Api.CanSelectAsTarget(source, target, false).Can)
                        return $"不足行动费/目标税却允许指定：{side}/{pair.Item1}/{mode}";
                }
            }
            state.SetKredits(side, cost);
            bool ok = mode == 0 ? engine.MoveUnit(source, 0, out _) : engine.Attack(source, target);
            if (!ok || state.Kredits(side) != 0)
                return $"行动扣费必须使用非负总费且不设99上限：{side}/{pair.Item1}/{mode}, remaining={state.Kredits(side)}";
        }
        {
            var (engine, state) = EmptyBoard(db);var source = MakeActionQuotaProbe(state, Side.Left, "infantry");
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Left };
            engine.Api.InvokeByName("ChangeOperationCost", source, new object?[] { source, 90, 200, 0, false, false, false }, ctx, out _);
            object? Total() => engine.Api.InvokeByName("getTotalOperationCost", source, new object?[] { null }, ctx, out _);
            if (!Equals(Total(), 200) || source.BuffsBySource[(90, true)].OperationCost != 200)
                return "行动总费用不得套用出牌99上限或裁剪来源账本";
            source.BuffsBySource[(90, true)].OperationCost = 10;source.RecalculateStats();
            if (!Equals(Total(), 200)) return "仅改账本不得重算原生行动费数值";
            source.TemporaryOperationCost = 10;
            if (!Equals(Total(), 10)) return "总费用未读取独立临时字段";
        }
        return null;
    }

    private static string? TotalKreditCostBounds(CardDatabase db)
    {
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (var pair in new[] { (int.MinValue, 0), (-10, 0), (-1, 0), (0, 0), (1, 1), (98, 98), (99, 99), (100, 99), (int.MaxValue, 99) })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 60, side.HandOf(), 1);
            source.KreditCost = pair.Item1;
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            var result = engine.Api.InvokeByName("getTotalKreditCost", source, new object?[] { null }, ctx, out bool handled);
            if (!handled || !Equals(result, pair.Item2) || source.KreditCost != pair.Item1)
                return $"总费用边界或原值保留错误：{side}/{pair.Item1}, result={result}";
        }
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (var pair in new[] { (-5, 0), (0, 0), (100, 99) })
        foreach (bool enemy in new[] { false, true })
        foreach (int tax in new[] { 0, 2 })
        {
            var (engine, state) = EmptyBoard(db);state.ActiveSide = side;
            var source = state.CreateWithId(PlainUnit, side, 60, side.HandOf(), 1);
            var target = state.CreateWithId(PlainUnit, enemy ? side.Opposite() : side, 61,
                (enemy ? side.Opposite() : side).HqOf(), 1);
            source.KreditCost = pair.Item1;target.KreditsTaxAsEnemyTarget = tax;
            int cost = pair.Item2 + (enemy ? tax : 0);
            state.SetKredits(side, cost);
            if (!engine.CanPlay(source, out _, target) || !engine.Api.CanSelectAsTarget(source, target, true).Can)
                return $"总费用边界未用于出牌/目标费用检查：{side}/{pair.Item1}/{enemy}/{tax}";
            if (!engine.PlayCard(source, target) || state.Kredits(side) != 0)
                return $"扣费未先限制基础总费用再加税：{side}/{pair.Item1}/{enemy}/{tax}, remaining={state.Kredits(side)}";
        }
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, Side.Left, 60, CardLocation.HandLeft, 1);
            source.BuffsBySource[(90, false)] = new CardBuff { KreditCost = 200 };
            source.BaseKreditCost = 200; source.TemporaryKreditCost = 0;
            source.RecalculateStats();
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Left };
            object? Total() => engine.Api.InvokeByName("getTotalKreditCost", source, new object?[] { null }, ctx, out _);
            if (!Equals(Total(), 99) || source.BuffsBySource[(90, false)].KreditCost != 200)
                return "总费用上限破坏了原始来源账本";
            source.BuffsBySource[(90, false)].KreditCost = 10; source.RecalculateStats();
            if (!Equals(Total(), 99) || source.BaseKreditCost != 200)
                return "修改来源账本或通用重算不应重建当前费用";
            source.BaseKreditCost = source.Definition.Kredits + 10;
            if (!Equals(Total(), source.Definition.Kredits + 10)) return "显式更新数值后总费用未恢复正确值";
        }
        return null;
    }

    private static string? PlayPreflightBlockOrder(CardDatabase db)
    {
        const string probe = "card_unit_meteor", function = "BlockCardFromBeingPlayedFromHand";
        if (KismetLibrary.Default?.Find(probe)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindLocalProgram(probe, function) is not null)
            return "无法安全安装出牌阻挡查询探针";
        var steps = new[] {
            new KismetStep(0, "call", "JSON_SetBool", new KismetExpr[] {
                new() { Int = 60 }, new() { Str = "_auditBlockQueried" }, new() { Bool = true }
            }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new() { Var = "auditBlocked", Scope = "instance" }, null, -1, "blocked", null),
            new KismetStep(2, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new() { Var = "auditBlockReason", Scope = "instance" }, null, -1, "reason", null),
            new KismetStep(3, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null)
        };
        locals.Add(function, steps);using var cleanup = new AuditProbeCleanup(() => locals.Remove(function));
        foreach (Side side in new[] { Side.Left, Side.Right })
        foreach (bool weather in new[] { false, true })
        foreach (bool alreadyPlayedWeather in new[] { false, true })
        foreach (bool affordable in new[] { false, true })
        foreach (bool blocked in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);state.ActiveSide = side;
            state.SetKredits(side, affordable ? 1 : 0);
            state.SetHasPlayedWeatherCardThisTurn(alreadyPlayedWeather);
            var source = state.CreateWithId(probe, side, 60, side.HandOf(), 1);
            source.KreditCost = 1;source.BlueprintVariables["auditBlocked"] = blocked;
            source.BlueprintVariables["auditBlockReason"] = blocked ? "_audit_blocked" : "";
            if (weather) engine.Api.AddCustomGameplayTag(source, "subtype.rain");
            var trace = new List<string>();engine.Api.TriggerTrace = trace;
            bool weatherBlocked = weather && alreadyPlayedWeather;
            bool shouldQuery = !weatherBlocked && affordable;
            bool expected = shouldQuery && !blocked;
            bool actual = engine.CanPlay(source, out string reason);
            int calls = trace.Count(x => x.StartsWith("BlockCardFromBeingPlayedFromHand(out ", StringComparison.Ordinal));
            string expectedReason = weatherBlocked ? "本回合已经打过天气牌" : !affordable ? "kredit 不足" : blocked ? "_audit_blocked" : "";
            if (actual != expected || calls != (shouldQuery ? 1 : 0)
                || source.CustomJson.ContainsKey("_auditBlockQueried") != shouldQuery
                || reason != expectedReason)
                return $"出牌前置门顺序错误：{side}/{weather}/{alreadyPlayedWeather}/{affordable}/{blocked}, can={actual}, calls={calls}, reason={reason}";
            if (!expected && engine.PlayCard(source)) return "前置门拒绝后执行入口仍成功";
            if (source.Location != side.HandOf() || state.Kredits(side) != (affordable ? 1 : 0))
                return "前置查询或拒绝执行产生费用/位置副作用";
        }
        return null;
    }

    private static string? OrderAvailabilityLiveReread(CardDatabase db)
