    private static string? GetDeckLocationBySide(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        var source = state.ById(1)!;
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = source, Controller = Side.Left,
        };

        object? leftRaw = engine.Api.InvokeByName(
            "GetDeckLocationBySide", source, new object?[] { (int)Side.Left, null }, ctx,
            out bool leftHandled);
        if (!leftHandled || leftRaw is not (int)CardLocation.DeckLeft)
        {
            return $"Left 应映射到 DeckLeft=1（handled={leftHandled}, result={leftRaw ?? "null"}）";
        }

        object? rightRaw = engine.Api.InvokeByName(
            "GetDeckLocationBySide", source, new object?[] { (int)Side.Right, null }, ctx,
            out bool rightHandled);
        if (!rightHandled || rightRaw is not (int)CardLocation.DeckRight)
        {
            return $"Right 应映射到 DeckRight=2（handled={rightHandled}, result={rightRaw ?? "null"}）";
        }

        return null;
    }

    private static string? GetHandLocationBySide(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        var source = state.ById(1)!;
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = source, Controller = Side.Left,
        };

        foreach (var (side, expected) in new[]
                 {
                     ((int)Side.Left, (int)CardLocation.HandLeft),
                     ((int)Side.Right, (int)CardLocation.HandRight),
                     ((int)Side.NotAvailable, (int)CardLocation.HandRight),
                 })
        {
            object? raw = engine.Api.InvokeByName(
                "GetHandLocationBySide", source, new object?[] { side, null }, ctx,
                out bool handled);
            if (!handled || raw is not int actual || actual != expected)
            {
                return $"side={side} 应映射到 handLocation={expected}（handled={handled}, result={raw ?? "null"}）";
            }
        }

        return null;
    }

    private static string? HandEdgeQueries(CardDatabase db)
    {
        const string sourceName = "card_unit_2nd_parachute";
        const string leftName = "card_unit_14th_guards_rifles";
        const string rightName = "card_unit_7th_brigade_anzac";
        if (db.Find(sourceName) is null || db.Find(leftName) is null || db.Find(rightName) is null)
        {
            return "手牌边界查询所需卡库条目缺失";
        }

        var (engine, state) = DeploymentBoard(db);
        var source = PutOnBoard(state, sourceName, Side.Left, 20, 1);
        state.CreateWithId(leftName, Side.Left, 90, CardLocation.HandLeft, 1);
        state.CreateWithId(rightName, Side.Left, 91, CardLocation.HandLeft, 4);
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = source, Controller = Side.Left,
        };

        object? leftRaw = engine.Api.InvokeByName(
            "GetLeftMostCardInHand", source, new object?[] { source, null, null }, ctx,
            out bool leftHandled);
        object? rightRaw = engine.Api.InvokeByName(
            "GetRightMostCardInHand", source, new object?[] { source, null, null }, ctx,
            out bool rightHandled);

        if (!leftHandled || !rightHandled || leftRaw is not object?[] left || rightRaw is not object?[] right)
        {
            return "手牌边界查询没有注册或未返回双出参";
        }

        if (left.Length < 2 || left[0] is not true || (left[1] as CardInstance)?.CardId != 90)
        {
            return "GetLeftMostCardInHand 未返回位置号最小的手牌";
        }

        if (right.Length < 2 || right[0] is not true || (right[1] as CardInstance)?.CardId != 91)
        {
            return "GetRightMostCardInHand 未返回位置号最大的手牌";
        }

        state.Move(state.ById(90)!, CardLocation.Discard, 0);
        state.Move(state.ById(91)!, CardLocation.Discard, 0);
        object? emptyRaw = engine.Api.InvokeByName(
            "GetLeftMostCardInHand", source, new object?[] { source, null, null }, ctx,
            out bool emptyHandled);
        if (!emptyHandled || emptyRaw is not object?[] empty || empty.Length < 2
            || empty[0] is not false || empty[1] is not null)
        {
            return "空手时 GetLeftMostCardInHand 应返回 found=false/card=null";
        }

        return null;
    }

    private static string? GoldCardPredicate(CardDatabase db)
    {
        const string name = "card_unit_2nd_parachute";
        if (db.Find(name) is null)
        {
            return $"卡库里缺 {name}";
        }

        var (engine, state) = DeploymentBoard(db);
        var regular = PutOnBoard(state, name, Side.Left, 20, 1);
        var gold = state.CreateWithId(name, Side.Left, 90, CardLocation.HandLeft, 2, isGold: true);
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = regular, Controller = Side.Left,
        };

        object? regularRaw = engine.Api.InvokeByName(
            "GetIsGoldCard", regular, new object?[] { null }, ctx, out bool regularHandled);
        ctx.Self = gold;
        object? goldRaw = engine.Api.InvokeByName(
            "GetIsGoldCard", gold, new object?[] { null }, ctx, out bool goldHandled);

        if (!regularHandled || !goldHandled || regularRaw is not false || goldRaw is not true)
        {
            return $"GetIsGoldCard 返回错误（普通={regularRaw ?? "null"}, 金卡={goldRaw ?? "null"}）";
        }

        return null;
    }

    /// <summary>
    /// `CustomName1*` / `CustomName2*` 三件套（合计 267 个调用点）。
    ///
    /// 语义出处：已安装客户端原生实现（RULE-097），分号分隔并保留重复添加。
    /// 这条同时关掉 `CardApi.cs:631` 里那条 TODO
    /// （「`StopDestructionEffect` 是 `CustomName1` 属性，而 `CustomName1*` 三件套内核里没有」）。
    /// </summary>
    private static string? CustomNameSuffixRoundTrip(CardDatabase db)
    {
        const string unit = "card_unit_2nd_parachute";
        if (db.Find(unit) is null)
        {
            return $"卡库里缺 {unit}";
        }

        var (engine, state) = DeploymentBoard(db);
        var card = PutOnBoard(state, unit, Side.Left, 20, 1);
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = card, Controller = Side.Left,
        };

        foreach (string prefix in new[] { "CustomName1", "CustomName2" })
        {
            // 存储键是**小写开头**的 `customName1` / `customName2`（原语名才是大写开头）
            string key = prefix == "CustomName1" ? "customName1" : "customName2";

            // Add
            engine.Api.InvokeByName(prefix + "Add", card, new object?[] { "StopDestructionEffect" }, ctx,
                out bool hAdd);
            if (!hAdd)
            {
                return $"派发表里没有 `{prefix}Add`（**修复前就是这个状态**）";
            }

            // HasAttribute（a[0]=标记串 a[1]=out）
            var has = engine.Api.InvokeByName(prefix + "HasAttribute", card,
                new object?[] { "StopDestructionEffect", null }, ctx, out bool hHas);
            if (!hHas)
            {
                return $"派发表里没有 `{prefix}HasAttribute`（**修复前就是这个状态**）";
            }

            if (has is not true)
            {
                return $"{prefix}Add 之后 HasAttribute 应当为真，实际 {has ?? "null"}";
            }

            // 别的标记不该命中
            var other = engine.Api.InvokeByName(prefix + "HasAttribute", card,
                new object?[] { "played", null }, ctx, out _);
            if (other is true)
            {
                return $"{prefix}HasAttribute(\"played\") 不该为真（后缀串被当成子串匹配了？）";
            }

            // 原生重复添加会追加，移除则一次移除全部同名项。
            engine.Api.InvokeByName(prefix + "Add", card, new object?[] { "StopDestructionEffect" }, ctx, out _);
            string stored = card.CustomJson.GetValueOrDefault(key, "");
            if (stored != "StopDestructionEffect;StopDestructionEffect")
            {
                return $"{prefix}Add 应保留重复标记并使用分号分隔，实际存的是 \"{stored}\"";
            }

            // Remove
            engine.Api.InvokeByName(prefix + "Remove", card, new object?[] { "StopDestructionEffect" }, ctx,
                out bool hRemove);
            if (!hRemove)
            {
                return $"派发表里没有 `{prefix}Remove`（**修复前就是这个状态**）";
            }

            var after = engine.Api.InvokeByName(prefix + "HasAttribute", card,
                new object?[] { "StopDestructionEffect", null }, ctx, out _);
            if (after is true)
            {
                return $"{prefix}Remove 之后 HasAttribute 应当为假，实际 {after}";
            }
        }

        // `GetCustomName2Attributes`（out = 标记数组）
        engine.Api.InvokeByName("CustomName2Add", card, new object?[] { "a" }, ctx, out _);
        engine.Api.InvokeByName("CustomName2Add", card, new object?[] { "b" }, ctx, out _);
        var list = engine.Api.InvokeByName("GetCustomName2Attributes", card, new object?[] { null }, ctx,
            out bool hList);
        if (!hList)
        {
            return "派发表里没有 `GetCustomName2Attributes`（**修复前就是这个状态**）";
        }

        var items = (list as System.Collections.IEnumerable)?.Cast<object?>().Select(x => x?.ToString()).ToList()
                    ?? new List<string?>();
        if (items.Count != 2 || items[0] != "a" || items[1] != "b")
        {
            return $"GetCustomName2Attributes 应当回 [a, b]，实际 [{string.Join(",", items)}]";
        }

        return null;
    }

    /// <summary>
    /// `GetCardsInSupportLineBySide(side, unitsOnly, includeCovertCards, out cards)`
    /// —— 41 调用点 / 34 张卡。
    ///
    /// 语义出处：直译产物 `_deps/BP_CardFunctions.g.cs` 同名函数体的四道过滤
    /// （side / location=半场 / covert / unitsOnly）。本内核的半场 = `side.HqOf()`。
    /// </summary>
    private static string? SupportLineQuery(CardDatabase db)
    {
        const string unit = "card_unit_2nd_parachute";
        if (db.Find(unit) is null)
        {
            return $"卡库里缺 {unit}";
        }

        var (engine, state) = DeploymentBoard(db);
        var own1 = PutOnBoard(state, unit, Side.Left, 20, 1);
        var own2 = PutOnBoard(state, unit, Side.Left, 21, 2);
        var front = state.CreateWithId(unit, Side.Left, 22, CardLocation.BoardFrontline, 0);
        var enemy = PutOnBoard(state, unit, Side.Right, 42, 1);
        var hqLeft = state.ById(1)!;

        var ctx = new EffectContext { Engine = engine, State = state, Self = own1, Controller = Side.Left };

        var result = engine.Api.InvokeByName("GetCardsInSupportLineBySide", null,
            new object?[] { 1, true, false, null }, ctx, out bool handled);
        if (!handled)
        {
            return "派发表里没有 `GetCardsInSupportLineBySide`（**修复前就是这个状态**）";
        }

        var cards = (result as System.Collections.IEnumerable)?.Cast<object?>().OfType<CardInstance>().ToList()
                    ?? new List<CardInstance>();

        foreach (var (card, want, why) in new (CardInstance Card, bool Want, string Why)[]
                 {
                     (own1, true, "本方半场单位"),
                     (own2, true, "本方半场单位"),
                     (front, false, "**前线**单位不属于半场"),
                     (enemy, false, "**敌方**半场单位"),
                     (hqLeft, false, "`unitsOnly=true` 时 HQ（location 卡）不该被算进来"),
                 })
        {
            bool got = cards.Contains(card);
            if (got != want)
            {
                return $"{why} {card.Name}#{card.CardId}@{card.Location}：应当 {(want ? "在" : "不在")}结果里，"
                     + $"实际 {(got ? "在" : "不在")}。结果 = [{string.Join(",", cards.Select(x => $"{x.Name}#{x.CardId}@{x.Location}"))}]";
            }
        }

        // `unitsOnly=false` 时 HQ 要保留（蓝图只按 location 过滤，不排除 HQ）
        var withHq = engine.Api.InvokeByName("GetCardsInSupportLineBySide", null,
            new object?[] { 1, false, false, null }, ctx, out _);
        var all = (withHq as System.Collections.IEnumerable)?.Cast<object?>().OfType<CardInstance>().ToList()
                  ?? new List<CardInstance>();
        if (!all.Contains(hqLeft))
        {
            return "`unitsOnly=false` 时 HQ 应当被保留（蓝图只按 location 过滤）"
                 + $"结果 = [{string.Join(",", all.Select(x => $"{x.Name}#{x.CardId}@{x.Location}"))}]";
        }

        return null;
    }

    /// <summary>
    /// `IsLocationFull(location, out isFull)` —— 20 调用点 / 17 张卡。
    ///
    /// 容量出处：`MatchEngine.HalfBoardFull` 的注释（半场 5、**含 HQ**）+ 前线
    /// `GameState.FrontlineCapacity`（默认 5）+ 手牌 `HandCapacity`（9）。
    /// `EmptyBoard` 里左半场已经有 HQ ⇒ 再放 4 个单位就满。
    /// </summary>
    private static string? LocationFullCapacity(CardDatabase db)
    {
        const string unit = "card_unit_2nd_parachute";
        if (db.Find(unit) is null)
        {
            return $"卡库里缺 {unit}";
        }

        var (engine, state) = DeploymentBoard(db);
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = state.ById(1), Controller = Side.Left,
        };

        bool Full(int loc)
        {
            var v = engine.Api.InvokeByName("IsLocationFull", null, new object?[] { loc, null }, ctx, out bool h);
            if (!h)
            {
                throw new InvalidOperationException("IsLocationFull 没进派发表");
            }

            return v is true;
        }

        if (Full((int)CardLocation.BoardHqLeft))
        {
            return "左半场只有 HQ（1 格 / 上限 5）时不该判满";
        }

        // 半场放 4 个单位（+ HQ = 5）⇒ 满
        for (int k = 0; k < 4; k++)
        {
            PutOnBoard(state, unit, Side.Left, 30 + k, 1 + k);
        }

        if (!Full((int)CardLocation.BoardHqLeft))
        {
            return "半场 HQ(1) + 4 个单位 = 5 格，必须判满（上限 `GameState.HalfBoardCapacity`=5，含 HQ）";
        }

        if (Full((int)CardLocation.BoardFrontline))
        {
            return "半场满了**不代表**前线满 —— 两个上限各自独立（`MatchEngine.HalfBoardFull` 的注释已定案）";
        }

        // 前线放 5 个 ⇒ 满
        for (int k = 0; k < GameState.DefaultFrontlineCapacity; k++)
        {
            state.CreateWithId(unit, Side.Left, 50 + k, CardLocation.BoardFrontline, k);
        }

        if (!Full((int)CardLocation.BoardFrontline))
        {
            return $"前线放满 {GameState.DefaultFrontlineCapacity} 个之后必须判满";
        }

        if (Full((int)CardLocation.DeckLeft))
        {
            return "牌库没有容量上限，不该判满";
        }

        return null;
    }

    /// <summary>
    /// `DestroyMultipleCards(cardsToDestroy, destroyerCardID, out)` —— 20 调用点 / 19 张卡。
    ///
    /// 数组元素**两种形状**（卡对象 / 整数 cardID）都要认 ——
    /// 与 `DiscardCardFromHand` 同一类坑（见 `AsCardOrId` 的注释，94 张卡用整数形状攒数组）。
    /// </summary>
    private static string? DestroyMultipleCardsBothShapes(CardDatabase db)
    {
        const string unit = "card_unit_2nd_parachute";
        const string self = "card_unit_10_5_cm_lefh";
        if (db.Find(unit) is null || db.Find(self) is null)
        {
            return $"卡库里缺 {unit} / {self}";
        }

        var (engine, state) = DeploymentBoard(db);
        var actor = PutOnBoard(state, self, Side.Left, 20, 1);
        var v1 = PutOnBoard(state, unit, Side.Left, 21, 2);        // 卡对象形状
        var v2 = PutOnBoard(state, unit, Side.Left, 22, 3);        // 整数 cardID 形状
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = actor, Controller = Side.Left,
        };

        var list = new List<object?> { v1, v2.CardId };
        var result = engine.Api.InvokeByName("DestroyMultipleCards", actor,
            new object?[] { list, actor.CardId, null }, ctx, out bool handled);
        if (!handled)
        {
            return "派发表里没有 `DestroyMultipleCards`（**修复前就是这个状态**）";
        }

        if (v1.Location != CardLocation.Discard)
        {
            return $"数组第 1 项（**卡对象**形状）必须被摧毁，实际 {v1.Location}";
        }

        if (v2.Location != CardLocation.Discard)
        {
            return $"数组第 2 项（**整数 cardID** 形状）必须被摧毁，实际 {v2.Location}"
                 + "（只认卡对象 ⇒ 整数 ID 被静默丢掉）";
        }

        if ((int)(result ?? -1) != 0)
        {
            return $"Blueprint 的 qqq 出参保持初值 0，实际 {result ?? "null"}";
        }

        return null;
    }

    /// <summary>
    /// `AddDefenseToMultipleCards(receiverIDs, amount, giverCardID, out qqq)`
    /// uses an integer ID array, applies each change once in input order, and
    /// sends targets that reach zero through the normal destruction path.
    /// </summary>
    private static string? AddDefenseToMultipleCards(CardDatabase db)
    {
        const string unit = "card_unit_2nd_parachute";
        const string actorName = "card_unit_10_5_cm_lefh";
        if (db.Find(unit) is null || db.Find(actorName) is null)
        {
            return $"卡库里缺 {unit} / {actorName}";
        }

        var (engine, state) = DeploymentBoard(db);
        var actor = PutOnBoard(state, actorName, Side.Left, 20, 1);
        var first = PutOnBoard(state, unit, Side.Left, 21, 2);
        var second = PutOnBoard(state, unit, Side.Left, 22, 3);
        first.Defense = first.MaxDefense = 3;
        second.Defense = second.MaxDefense = 4;
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = actor, Controller = Side.Left,
        };

        var result = engine.Api.InvokeByName(
            "AddDefenseToMultipleCards", actor,
            new object?[] { new List<int> { second.CardId, first.CardId, 999999 }, 2, actor.CardId, null },
            ctx, out bool handled);
        if (!handled)
        {
            return "派发表里没有 `AddDefenseToMultipleCards`";
        }

        if (first.Defense != 5 || first.MaxDefense != 5
            || second.Defense != 6 || second.MaxDefense != 6)
        {
            return $"正向批量防御应按 ID 逐项 +2 且同步 MaxDefense，实际 first={first.Defense}/{first.MaxDefense} "
                 + $"second={second.Defense}/{second.MaxDefense}";
        }

        if ((int)(result ?? -1) != 0)
        {
            return $"qqq 是 Int 出参，当前应返回 0，实际 {result ?? "null"}";
        }

        var doomed = PutOnBoard(state, unit, Side.Left, 23, 4);
        doomed.Defense = doomed.MaxDefense = 1;
        result = engine.Api.InvokeByName(
            "AddDefenseToMultipleCards", actor,
            new object?[] { new List<int> { doomed.CardId, 999999 }, -2, actor.CardId, null },
            ctx, out handled);
        if (!handled)
        {
            return "负值调用未进入 `AddDefenseToMultipleCards` 派发";
        }

        if (doomed.Location != CardLocation.Discard)
        {
            return $"防御 1 受 -2 后必须被摧毁，实际位置={doomed.Location} 防御={doomed.Defense}";
        }

        return null;
    }

    private static string? RemoveAlpine(CardDatabase db)
    {
        const string targetName = "card_unit_2nd_parachute";
        const string sourceName = "card_unit_10_5_cm_lefh";
        if (db.Find(targetName) is null || db.Find(sourceName) is null)
        {
            return $"卡库里缺 {targetName} / {sourceName}";
        }

        var (engine, state) = DeploymentBoard(db);
        var sourceA = PutOnBoard(state, sourceName, Side.Left, 20, 1);
        var sourceB = PutOnBoard(state, sourceName, Side.Left, 21, 2);
        var target = PutOnBoard(state, targetName, Side.Left, 22, 3);
        var ctx = new EffectContext
        {
            Engine = engine, State = state, Self = sourceA, Controller = Side.Left,
        };

        void Give(int giverId)
        {
            engine.Api.InvokeByName("GiveAlpine", sourceA,
                new object?[] { target.CardId, null, giverId }, ctx, out bool handled);
            if (!handled)
            {
                throw new InvalidOperationException("GiveAlpine 未进入派发表");
            }
        }

        void Remove(int giverId)
        {
            engine.Api.InvokeByName("RemoveAlpine", sourceA,
                new object?[] { target.CardId, null, false, giverId }, ctx, out bool handled);
            if (!handled)
            {
                throw new InvalidOperationException("RemoveAlpine 未进入派发表");
            }
        }

        Give(sourceA.CardId);
        Give(sourceB.CardId);
        if (!target.Keywords.Contains(Keyword.Alpine))
        {
            return "GiveAlpine 后目标必须拥有 Alpine";
        }

        Remove(sourceA.CardId);
        if (!target.Keywords.Contains(Keyword.Alpine))
        {
            return "移除一个来源后仍有另一来源，不能摘掉 Alpine";
        }

        Remove(sourceB.CardId);
        if (target.Keywords.Contains(Keyword.Alpine))
        {
            return "移除最后一个来源后必须摘掉动态 Alpine";
        }

        var innateDefinition = db.All.FirstOrDefault(d => d.Keywords.Contains(Keyword.Alpine));
        if (innateDefinition is not null)
        {
            var innate = state.CreateWithId(innateDefinition.Name, Side.Left, 23,
                CardLocation.BoardHqLeft, 4);
            Give(sourceA.CardId);
            // Reuse the target variable's call path for an innate card by invoking
            // the primitive directly with the new card ID.
            engine.Api.InvokeByName("GiveAlpine", sourceA,
                new object?[] { innate.CardId, null, sourceA.CardId }, ctx, out _);
            engine.Api.InvokeByName("RemoveAlpine", sourceA,
                new object?[] { innate.CardId, null, false, sourceA.CardId }, ctx, out _);
            if (!innate.Keywords.Contains(Keyword.Alpine))
            {
                return "卡面自带 Alpine 不应被 RemoveAlpine 摘掉";
            }
        }

        return null;
    }

    private static string? MobilizeEvents(CardDatabase db)
    {
        const string guardUnitName = "card_unit_48e_regiment";
        const string repairUnitName = "card_unit_43e_regiment_motorise";
        const string sourceName = "card_unit_10_5_cm_lefh";
        const string damagedName = "card_unit_2nd_parachute";
        foreach (string name in new[] { guardUnitName, repairUnitName, sourceName, damagedName })
        {
            if (db.Find(name) is null)
            {
                return $"卡库里缺 {name}";
            }
        }

        var (engine, state) = DeploymentBoard(db);
        var source = PutOnBoard(state, sourceName, Side.Left, 20, 1);
        var guardUnit = PutOnBoard(state, guardUnitName, Side.Left, 21, 2);
        var repairUnit = PutOnBoard(state, repairUnitName, Side.Left, 22, 3);
        var damaged = PutOnBoard(state, damagedName, Side.Left, 23, 4);
        damaged.Defense = Math.Max(1, damaged.MaxDefense - 2);

        var ctx = new EffectContext
        {
            Engine = engine,
            State = state,
            Self = source,
            Controller = Side.Left,
        };

        object? Invoke(string name, CardInstance target)
        {
            var result = engine.Api.InvokeByName(
                name,
                source,
                new object?[] { target.CardId, source.CardId, null },
                ctx,
                out bool handled);
            if (!handled)
            {
                throw new InvalidOperationException($"{name} 未进入派发表");
            }

            return result;
        }

        // Removing innate Mobilize must run OnLoseMobilize, which grants Guard
        // to the 48e regiment. Re-adding it runs OnGainMobilize and removes it.
        Invoke("RemoveMobilize", guardUnit);
        if (guardUnit.Keywords.Contains(Keyword.Mobilize)
            || !guardUnit.Keywords.Contains(Keyword.Guard))
        {
            return "48e Regiment 失去 Mobilize 后应获得 Guard";
        }

        Invoke("GiveMobilize", guardUnit);
        if (!guardUnit.Keywords.Contains(Keyword.Mobilize)
            || guardUnit.Keywords.Contains(Keyword.Guard))
        {
            return "48e Regiment 获得 Mobilize 后应移除 Guard";
        }

        Invoke("GiveMobilize", guardUnit);
        if (engine.Api.JsonGetIntArray(guardUnit, "mobilizeGivers").Count != 1)
        {
            return "同一来源重复 GiveMobilize 不应重复记录来源";
        }

        // 43e Regiment's OnLoseMobilize repairs every friendly unit.
        Invoke("RemoveMobilize", repairUnit);
        if (damaged.Defense != damaged.MaxDefense)
        {
            return $"43e Regiment 失去 Mobilize 后应修复友军，实际 {damaged.Defense}/{damaged.MaxDefense}";
        }

        return null;
    }

    private static string? MobilizeStartTurnBonus(CardDatabase db)
    {
        const string mobilizeName = "card_unit_2nd_parachute";
        const string plainName = "card_unit_10_5_cm_lefh";
        if (db.Find(mobilizeName) is null || db.Find(plainName) is null)
        {
            return $"卡库缺少测试卡 {mobilizeName} 或 {plainName}";
        }

        var (engine, state) = EmptyBoard(db);
        var active = state.CreateWithId(mobilizeName, Side.Left, 710, CardLocation.BoardHqLeft, 1);
        var activePlain = state.CreateWithId(plainName, Side.Left, 711, CardLocation.BoardHqLeft, 2);
        var activeHand = state.CreateWithId(mobilizeName, Side.Left, 712, CardLocation.HandLeft, 0);
        var inactive = state.CreateWithId(mobilizeName, Side.Right, 713, CardLocation.BoardHqRight, 1);

        int activeAttack = active.Attack;
        int activeDefense = active.Defense;
        int plainAttack = activePlain.Attack;
        int plainDefense = activePlain.Defense;
        int handAttack = activeHand.Attack;
        int handDefense = activeHand.Defense;
        int inactiveAttack = inactive.Attack;
        int inactiveDefense = inactive.Defense;

        engine.StartTurn(Side.Left, draw: false);

        if (active.Attack != activeAttack + 1 || active.Defense != activeDefense + 1
            || activePlain.Attack != plainAttack || activePlain.Defense != plainDefense
            || activeHand.Attack != handAttack || activeHand.Defense != handDefense
            || inactive.Attack != inactiveAttack || inactive.Defense != inactiveDefense)
        {
            return $"左方回合应只给左方在场 Mobilize +1/+1，实际 active={active.Attack}/{active.Defense}、"
                 + $"plain={activePlain.Attack}/{activePlain.Defense}、hand={activeHand.Attack}/{activeHand.Defense}、"
                 + $"inactive={inactive.Attack}/{inactive.Defense}";
        }

        if (!active.BuffsBySource.TryGetValue((active.CardId, false), out var buff)
            || buff.Attack != 1 || buff.Defense != 1)
        {
            return "Mobilize 回合增益应记录为该单位自身来源的永久 +1/+1";
        }

        engine.StartTurn(Side.Right, draw: false);
        if (inactive.Attack != inactiveAttack + 1 || inactive.Defense != inactiveDefense + 1)
        {
            return $"右方回合应给右方在场 Mobilize +1/+1，实际 {inactive.Attack}/{inactive.Defense}";
        }

        engine.StartTurn(Side.Left, draw: false);
        return active.Attack == activeAttack + 2 && active.Defense == activeDefense + 2
            ? null
            : $"同一单位第二次成为活动方时应再次获得 +1/+1，实际 {active.Attack}/{active.Defense}";
    }

    private static string? MobilizeLostOnDamage(CardDatabase db)
    {
        const string targetName = "card_unit_2nd_parachute";
        const string sourceName = "card_unit_10_5_cm_lefh";
        foreach (string name in new[] { targetName, sourceName })
        {
            if (db.Find(name) is null)
            {
                return $"卡库缺少测试卡 {name}";
            }
        }

        // Effect damage uses the same ApplyDamageToCard path as combat, but
        // bypasses Heavy Armor. Surviving positive hits remove Mobilize.
        {
            var (engine, state) = DeploymentBoard(db);
            var target = PutOnBoard(state, targetName, Side.Right, 720, 1);
            target.Defense = target.MaxDefense = 3;
            var source = PutOnBoard(state, sourceName, Side.Left, 721, 2);
            var context = new EffectContext
            {
                Engine = engine,
                State = state,
                Self = source,
                Controller = Side.Left,
            };

            engine.Api.InvokeByName("DamageCard", source,
                new object?[] { target, 1, source, false, false, false }, context, out bool handled);
            if (!handled || target.Keywords.Contains(Keyword.Mobilize))
            {
                return "受到 1 点效果伤害后应失去 Mobilize";
            }
        }

        // Combat damage reduced to zero by Heavy Armor is not a hit and must
        // preserve Mobilize; a later positive combat hit must remove it.
        {
            const string armoredName = "card_unit_maus";
            const string attackerName = "card_unit_panzer_ii_a";
            if (db.Find(armoredName) is null || db.Find(attackerName) is null)
            {
                return $"卡库缺少测试卡 {armoredName} 或 {attackerName}";
            }

            var (engine, attacker, target) = FightBoard(db, attackerName, armoredName, 3, 9, 0, 8);
            target.Keywords.Add(Keyword.Mobilize);
            if (!engine.Attack(attacker, target, out string reason))
            {
                return $"重甲零伤害前提下攻击失败：{reason}";
            }

            if (!target.Keywords.Contains(Keyword.Mobilize))
            {
                return "重甲完全吸收战斗伤害时应保留 Mobilize";
            }

            var (positiveEngine, positiveAttacker, positiveTarget) =
                FightBoard(db, attackerName, armoredName, 6, 9, 0, 8);
            positiveTarget.Keywords.Add(Keyword.Mobilize);
            if (!positiveEngine.Attack(positiveAttacker, positiveTarget, out reason))
            {
                return $"正值战斗伤害前提下攻击失败：{reason}";
            }

            if (positiveTarget.Keywords.Contains(Keyword.Mobilize))
            {
                return "重甲减伤后仍有正值战斗伤害时应失去 Mobilize";
            }
        }

        return null;
    }

    /// <summary>
    /// `MoveMultipleCardsToTopOfOwnersDeck` 的批量顺序回归。
    ///
    /// 蓝图逐项调用单卡移动，故 [leftA,leftB] 结算后应为 leftB、leftA、其余卡；
    /// 另一方牌库不应被触碰。空数组是成功的 no-op，无效 ID 则报告失败但不改变局面。
    /// </summary>
    private static string? MoveMultipleCardsToTopOfOwnersDeck(CardDatabase db)
    {
        const string cardName = "card_unit_2nd_parachute";
        const string actorName = "card_unit_10_5_cm_lefh";
        if (db.Find(cardName) is null || db.Find(actorName) is null)
        {
            return $"卡库里缺 {cardName} / {actorName}";
        }

        var (engine, state) = EmptyBoard(db);
        var actor = PutOnBoard(state, actorName, Side.Left, 20, 1);
        var leftA = state.CreateWithId(cardName, Side.Left, 21, CardLocation.DeckLeft, 2);
        var leftB = state.CreateWithId(cardName, Side.Left, 22, CardLocation.DeckLeft, 3);
        var leftRest = state.CreateWithId(cardName, Side.Left, 23, CardLocation.DeckLeft, 0);
        var right = state.CreateWithId(cardName, Side.Right, 31, CardLocation.DeckRight, 0);
        var ctx = new EffectContext
        {
            Engine = engine,
            State = state,
            Self = actor,
            Controller = Side.Left,
        };

        var result = engine.Api.InvokeByName(
            "MoveMultipleCardsToTopOfOwnersDeck",
            actor,
            new object?[] { new List<int> { leftA.CardId, leftB.CardId }, actor.CardId, 0, null },
            ctx,
            out bool handled);

        if (!handled)
        {
            return "派发表里没有 `MoveMultipleCardsToTopOfOwnersDeck`";
        }

        if (result is not true)
        {
            return $"两个有效 ID 批量移动应返回 true，实际 {result ?? "null"}";
        }

        var leftDeck = state.Deck(Side.Left).ToList();
        if (!leftDeck.SequenceEqual(new[] { leftB, leftA, leftRest }))
        {
            return "批量移动后的左侧牌库顺序不对：应为 [后输入卡, 先输入卡, 原有卡]";
        }

        if (right.Location != CardLocation.DeckRight || right.LocationNumber != 0)
        {
            return "批量移动不应改变另一拥有者的牌库";
        }

        var empty = engine.Api.InvokeByName(
            "MoveMultipleCardsToTopOfOwnersDeck",
            actor,
            new object?[] { new List<int>(), actor.CardId, 0, null },
            ctx,
            out _);
        if (empty is not true)
        {
            return $"空数组应是成功 no-op，实际 {empty ?? "null"}";
        }

        var invalid = engine.Api.InvokeByName(
            "MoveMultipleCardsToTopOfOwnersDeck",
            actor,
            new object?[] { new List<int> { 999999 }, actor.CardId, 0, null },
            ctx,
            out _);
        if (invalid is not false)
        {
            return $"无效 ID 应返回 false，实际 {invalid ?? "null"}";
        }

        if (!state.Deck(Side.Left).SequenceEqual(new[] { leftB, leftA, leftRest }))
        {
            return "无效 ID 不应改变已有牌库顺序";
        }

        return null;
    }

    /// <summary>
    /// `PlayCardDirectlyFromHand` 的最小端到端回归：
    /// 不扣 kredit、不要求当前行动方；单位可直接进前线；显式 locationNumber
    /// 参与目标位置排序；无效卡回写 false。
    /// </summary>
    private static string? PlayCardDirectlyFromHand(CardDatabase db)
    {
        var (engine, state) = EmptyBoard(db);
        var unitDef = db.Find("card_unit_arado_ar_196");
        var gotchaDef = db.Find("card_event_interception");
        if (unitDef is null || gotchaDef is null)
        {
            return "卡库里缺 card_unit_arado_ar_196 / card_event_interception";
        }

        state.SetKredits(Side.Left, 0);
        state.SetKredits(Side.Right, 0);
        var existing = state.CreateWithId(unitDef.Name, Side.Left, 2,
            CardLocation.BoardHqLeft, 2);
        var support = state.CreateWithId(unitDef.Name, Side.Left, 3,
            CardLocation.HandLeft, 0);
        var ctx = new EffectContext
        {
            Engine = engine,
            State = state,
            Self = state.Hq(Side.Left),
            Controller = Side.Left,
        };

        var result = engine.Api.InvokeByName(
            "PlayCardDirectlyFromHand", support,
            new object?[] { support, false, 9001, null, 1 },
            ctx, out bool handled);
        if (!handled || result is not true)
        {
            return $"免费从手牌直接打出应成功且 handled=true，实际 handled={handled}, result={result ?? "null"}";
        }

        if (support.Location != CardLocation.BoardHqLeft || support.LocationNumber != 1
            || existing.LocationNumber != 2)
        {
            return $"显式 locationNumber=1 未按槽位排序：support={support.Location}/{support.LocationNumber}, "
                 + $"existing={existing.LocationNumber}";
        }

        if (state.Kredits(Side.Left) != 0)
        {
            return "直接出牌不应扣除 kredit";
        }

        var frontExisting = state.CreateWithId(unitDef.Name, Side.Right, 43,
            CardLocation.BoardFrontline, 0);
        var frontline = state.CreateWithId(unitDef.Name, Side.Right, 42,
            CardLocation.HandRight, 0);
        var frontlineResult = engine.Api.InvokeByName(
            "PlayCardDirectlyFromHand", frontline,
            new object?[] { frontline, true, 9002, null, 1 },
            ctx, out bool frontlineHandled);
        if (!frontlineHandled || frontlineResult is not true
            || frontline.Location != CardLocation.BoardFrontline
            || frontline.LocationNumber != 1 || frontExisting.LocationNumber != 0)
        {
            return $"非当前行动方单位应能直接进前线：handled={frontlineHandled}, result={frontlineResult ?? "null"}, "
                 + $"location={frontline.Location}/{frontline.LocationNumber}, existing={frontExisting.LocationNumber}";
        }

        var invalid = engine.Api.InvokeByName(
            "PlayCardDirectlyFromHand", frontline,
            new object?[] { frontline, false, 9003, null, -1 },
            ctx, out bool invalidHandled);
        if (!invalidHandled || invalid is not false)
        {
            return $"不在手牌的卡应回写 qqq=false：handled={invalidHandled}, result={invalid ?? "null"}";
        }

        var gotcha = state.CreateWithId(gotchaDef.Name, Side.Left, 4,
            CardLocation.HandLeft, 1);
        var gotchaResult = engine.Api.InvokeByName(
            "PlayCardDirectlyFromHand", gotcha,
            new object?[] { gotcha, false, 9004, null, -1 },
            ctx, out bool gotchaHandled);
        if (!gotchaHandled || gotchaResult is not true || gotcha.GotchaActivated != 1)
        {
            return $"直接出牌必须接通 Gotcha 激活序号：handled={gotchaHandled}, result={gotchaResult ?? "null"}, "
                 + $"activated={gotcha.GotchaActivated}";
        }

        return null;
    }

    /// <summary>
    /// `MoveUnitFromSupportToFrontLine(card, instigatorID, out qqq)` 的效果位移回归：
    /// 不要求当前行动方、不扣油费，消费移动额度，也不受召唤失调/压制影响；
    /// `cantMove`、敌方占据前线和我方前线已满时必须拒绝并回写 false。
    /// </summary>
    private static string? MoveUnitFromSupportToFrontLine(CardDatabase db)
    {
        const string unitName = "card_unit_arado_ar_196";
        if (db.Find(unitName) is null)
        {
            return $"卡库里缺 {unitName}";
        }

        static EffectContext Context(MatchEngine engine, GameState state, CardInstance self) => new()
        {
            Engine = engine,
            State = state,
            Self = self,
            Controller = self.Owner,
        };

        // ① 免费效果位移：即使不是当前行动方、已移动/已攻击、本回合刚进场且被压制，
        //    也应当被送入前线；kredit保持，额度消费由专项矩阵验证。
        {
            var (engine, state) = EmptyBoard(db);
            state.ActiveSide = Side.Left;
            state.SetKredits(Side.Right, 0);
            var unit = state.CreateWithId(unitName, Side.Right, 42,
                CardLocation.BoardHqRight, 0);
            unit.HasMovedThisTurn = true;
            unit.HasAttackedThisTurn = true;
            unit.EnteredPlayOnTurn = state.Turn;
            unit.PinnedTurns = 2;
            var result = engine.Api.InvokeByName(
                "MoveUnitFromSupportToFrontLine", unit,
                new object?[] { unit, 9001 }, Context(engine, state, unit), out bool handled);

            if (!handled || result is not false)
            {
                return $"合法效果位移完成后qqq仍应为false且 handled=true，实际 handled={handled}, result={result ?? "null"}";
            }

            if (unit.Location != CardLocation.BoardFrontline
                || state.FrontlineOwner != Side.Right)
            {
                return $"效果位移应进入右侧前线，实际 location={unit.Location}, owner={state.FrontlineOwner}";
            }

            if (state.Kredits(Side.Right) != 0 || !unit.HasMovedThisTurn)
            {
                return $"效果位移不应扣油费或清除既有移动标记：kredit={state.Kredits(Side.Right)}, "
                     + $"hasMoved={unit.HasMovedThisTurn}";
            }
        }

        // ② cantMove 是这条蓝图路径唯一的单位能力拒绝门，失败不得改变位置。
        {
            var (engine, state) = EmptyBoard(db);
            var unit = state.CreateWithId(unitName, Side.Left, 2,
                CardLocation.BoardHqLeft, 0);
            unit.CustomAbility = "cantMove";
            var result = engine.Api.InvokeByName(
                "MoveUnitFromSupportToFrontLine", unit,
                new object?[] { unit, 9002 }, Context(engine, state, unit), out bool handled);
            if (!handled || result is not false || unit.Location != CardLocation.BoardHqLeft)
            {
                return $"cantMove 目标应被拒绝且 qqq=false：handled={handled}, result={result ?? "null"}, "
                     + $"location={unit.Location}";
            }
        }

        // ③ 敌方占据前线时，另一方不能借效果越过互斥门。
        {
            var (engine, state) = EmptyBoard(db);
            var enemy = state.CreateWithId(unitName, Side.Right, 42,
                CardLocation.BoardHqRight, 0);
            state.Move(enemy, CardLocation.BoardFrontline, 0);
            var unit = state.CreateWithId(unitName, Side.Left, 2,
                CardLocation.BoardHqLeft, 0);
            var result = engine.Api.InvokeByName(
                "MoveUnitFromSupportToFrontLine", unit,
                new object?[] { unit, 9003 }, Context(engine, state, unit), out bool handled);
            if (!handled || result is not false || unit.Location != CardLocation.BoardHqLeft)
            {
                return $"对方占据前线时应拒绝且 qqq=false：handled={handled}, result={result ?? "null"}, "
                     + $"location={unit.Location}";
            }
        }

        // ④ 我方前线达到容量后，第六个单位必须被拒绝。
        {
            var (engine, state) = EmptyBoard(db);
            for (int i = 0; i < GameState.DefaultFrontlineCapacity; i++)
            {
                var occupied = state.CreateWithId(unitName, Side.Left, 2 + i,
                    CardLocation.BoardHqLeft, i);
                state.Move(occupied, CardLocation.BoardFrontline, i);
            }

            var extra = state.CreateWithId(unitName, Side.Left, 20,
                CardLocation.BoardHqLeft, 0);
            var result = engine.Api.InvokeByName(
                "MoveUnitFromSupportToFrontLine", extra,
                new object?[] { extra, 9004 }, Context(engine, state, extra), out bool handled);
            if (!handled || result is not false
                || extra.Location != CardLocation.BoardHqLeft
                || state.Cards(Side.Left, CardLocation.BoardFrontline).Count
                    != GameState.DefaultFrontlineCapacity)
            {
                return $"我方前线已满时应拒绝且保持容量：handled={handled}, result={result ?? "null"}, "
                     + $"location={extra.Location}, count={state.Cards(Side.Left, CardLocation.BoardFrontline).Count}";
            }
        }

        return null;
    }

    private static string? ForceCardChangeLocation(CardDatabase db)
    {
        const string unitName = "card_unit_arado_ar_196";
        if (db.Find(unitName) is null)
        {
            return $"卡库里缺 {unitName}";
        }

        var (engine, state) = EmptyBoard(db);
        var source = state.CreateWithId("card_event_air_land_sea", Side.Left, 2,
            CardLocation.HandLeft, 0);
        var target = state.CreateWithId(unitName, Side.Right, 42,
            CardLocation.BoardHqRight, 1);
        var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = Side.Left };

        var result = engine.Api.InvokeByName("ForceCardChangeLocation", source,
            new object?[] { target.CardId, source.CardId, (int)CardLocation.BoardFrontline, 0, null, null, null },
            ctx, out bool handled);
        if (!handled || result is not object?[] outs || outs.Length < 3
            || outs[0] is not true || Convert.ToInt32(outs[1]) != (int)CardLocation.BoardHqRight
            || Convert.ToInt32(outs[2]) != 1
            || target.Location != CardLocation.BoardFrontline || target.LocationNumber != 0)
        {
            return $"移动应成功并回写旧位置：handled={handled}, result={result ?? "null"}, "
                 + $"target={target.Location}/{target.LocationNumber}";
        }

        var noOp = engine.Api.InvokeByName("ForceCardChangeLocation", source,
            new object?[] { target.CardId, source.CardId, (int)CardLocation.BoardFrontline, 0, null, null, null },
            ctx, out bool noOpHandled);
        if (!noOpHandled || noOp is not object?[] noOpOuts || noOpOuts.Length < 3
            || noOpOuts[0] is not false || target.Location != CardLocation.BoardFrontline)
        {
            return $"相同位置/槽位应 no-op：handled={noOpHandled}, result={noOp ?? "null"}, "
                 + $"target={target.Location}/{target.LocationNumber}";
        }

        target.CustomAbility = "cantMove";
        var blocked = engine.Api.InvokeByName("ForceCardChangeLocation", source,
            new object?[] { target.CardId, source.CardId, (int)CardLocation.BoardHqRight, 1, null, null, null },
            ctx, out bool blockedHandled);
        if (!blockedHandled || blocked is not object?[] blockedOuts || blockedOuts.Length < 3
            || blockedOuts[0] is not false || target.Location != CardLocation.BoardFrontline)
        {
            return $"cantMove 应拒绝且不改位置：handled={blockedHandled}, result={blocked ?? "null"}, "
                 + $"target={target.Location}/{target.LocationNumber}";
        }

        return null;
    }

    private static IDisposable InstallEntrySubjectObservers(bool includeSubject = true)
    {
        const string spawnedName = "card_unit_typhoon_mk_ib", trigger = "OnOtherCardEnterPlay";
        var installed = new List<IDictionary<string, IReadOnlyList<KismetStep>>>();
        foreach (string probe in includeSubject ? new[] { "card_unit_brewster_f2a", spawnedName } : new[] { "card_unit_brewster_f2a" })
        {
            if (KismetLibrary.Default?.Find(probe)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
                || KismetLibrary.Default.FindProgram(probe, trigger) is not null)
            {
                foreach (var previous in installed) previous.Remove(trigger);
                throw new InvalidOperationException("无法安全安装T43主体探针");
            }
            // Ignore marker cards so nested probe creation cannot recursively trigger itself.
            locals.Add(trigger, new[] {
                new KismetStep(0, "jumpIfNot", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null,
                    new KismetExpr { Math = "EqualEqual_NameName", Args = new[] {
                        new KismetExpr { Var = "name", Context = new KismetExpr { Var = "K2Node_Event_cardPlayed" } },
                        new KismetExpr { Name = spawnedName } } }, 6, null, null),
                new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "K2Node_Event_cardPlayed" }, null, -1, "_auditBatchEntrySnapshotSubject", null) { DestinationScope = "instance" },
                new KismetStep(2, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Var = "K2Node_Event_Method" }, null, -1, "_auditBatchEntrySnapshotMethod", null) { DestinationScope = "instance" },
                new KismetStep(3, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                    new KismetExpr { Math = "Add_IntInt", Args = new[] {
                        new KismetExpr { Var = "_auditBatchEntrySnapshotCount", Scope = "instance" }, new KismetExpr { Int = 1 } } },
                    null, -1, "_auditBatchEntrySnapshotCount", null) { DestinationScope = "instance" },
                new KismetStep(4, "call", "SpawnCardInDeckBySide", new[] {
                    new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                    new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 } }, Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(5, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
                new KismetStep(6, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
            });
            installed.Add(locals);
        }
        return new AuditProbeCleanup(() => { foreach (var locals in installed) locals.Remove(trigger); });
    }

    private static string? EntrySubjectSuppressionAndId(CardDatabase db)
    {
        using var entry = InstallEntryMethodProbe();
        using var observersProbe = InstallEntrySubjectObservers();
        const string name = "card_unit_typhoon_mk_ib", probe = "card_unit_brewster_f2a", trigger = "OnOtherCardEnterPlay";
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (var location in new[] { side.HqOf(), side.DeckOf(), CardLocation.Discard, CardLocation.NotAvailable })
        foreach (bool suppressed in new[] { false, true })
        foreach (bool exceptions in new[] { false, true })
        foreach (bool sameIdAlias in new[] { false, true })
        foreach (int observerState in new[] { 0, 1, 2 })
        {
            var (engine, state) = EmptyBoard(db);
            var first = state.CreateWithId(probe, side.Opposite(), 20, CardLocation.NotAvailable, 0);
            var second = state.CreateWithId(probe, side, 21, CardLocation.Discard, 17);
            foreach (var receiver in new[] { first, second })
            {
                receiver.Keywords.Clear();
                receiver.Definition = new CardDefinition { Name = probe, UsedTriggers = new[] { trigger } };
            }
            if (observerState > 0) second.Keywords.Add(Keyword.Suppressed);
            if (observerState == 2) second.SuppressionExceptionTriggers.Add(trigger);
            // Alias is an independently held object sharing receiver21's ID.
            // No map/index rewrite or claim about a real card creating aliases.
            var subject = sameIdAlias
                ? new CardInstance { CardId = 21, Name = name, Owner = side,
                    Definition = new CardDefinition { Name = name, UsedTriggers = new[] { trigger } }, Location = location }
                : state.CreateWithId(name, side, 60, location, 0);
            subject.Definition = new CardDefinition { Name = name, UsedTriggers = new[] { trigger } };
            subject.Keywords.Clear();
            if (suppressed) subject.Keywords.Add(Keyword.Suppressed);
            if (exceptions) { subject.SuppressionExceptionTriggers.Add("OnEnterPlay"); subject.SuppressionExceptionTriggers.Add(trigger); }
            var receivers = new[] { first, second, subject };
            var seen = new Dictionary<CardInstance, int>(); var calls = new List<int>(); int ownCalls = 0; string? failure = null;
            var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name != "card_unit_routed_troops") return;
                var hits = receivers.Where(x => Convert.ToInt32(x.BlueprintVariables.GetValueOrDefault("_auditBatchEntrySnapshotCount"))
                    > seen.GetValueOrDefault(x)).ToArray();
                if (hits.Length == 0)
                {
                    ownCalls++; calls.Add(0);
                    if (Convert.ToInt32(subject.BlueprintVariables.GetValueOrDefault("_auditEntryMethod")) != 3)
                        failure = "自身进场method丢失";
                    return;
                }
                if (hits.Length != 1) { failure = "旁观事件探针计数错误"; return; }
                var receiver = hits[0]; seen[receiver] = Convert.ToInt32(receiver.BlueprintVariables["_auditBatchEntrySnapshotCount"]);
                calls.Add(receiver.CardId);
                if (!ReferenceEquals(receiver.BlueprintVariables.GetValueOrDefault("_auditBatchEntrySnapshotSubject"), subject)
                    || Convert.ToInt32(receiver.BlueprintVariables.GetValueOrDefault("_auditBatchEntrySnapshotMethod")) != 3)
                    failure = "旁观者必须收到实际主体引用及method3";
            };
            engine.ExecuteOnEnterPlayEvents(subject, 3);
            var expected = new List<int>();
            if (!suppressed) expected.Add(0);
            expected.Add(20);
            if (!sameIdAlias && observerState != 1) expected.Add(21);
            if (failure is not null || ownCalls != (suppressed ? 0 : 1) || !calls.SequenceEqual(expected)
                || subject.BlueprintVariables.ContainsKey("_auditBatchEntrySnapshotCount"))
                return $"entry subject case={cases} {side}/{location}/{suppressed}/{exceptions}/{sameIdAlias}/{observerState}: {failure ?? "suppression/ID exclusion"}, got={string.Join(',', calls)}, expected={string.Join(',', expected)}";
            cases++;
        }
        return cases == 192 ? null : $"entry subject matrix count={cases}";
    }

    private static IDisposable InstallLimiterReceiptProbe(string name, string trigger, bool[] removals)
    {
        if (KismetLibrary.Default?.Find(name)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(name, trigger) is not null)
            throw new InvalidOperationException("无法安全安装限制者接收探针");
        // Synthetic programs isolate receipt timing; these are not real card effects.
        var steps = new List<KismetStep>();
        foreach (bool remove in removals)
            steps.Add(new KismetStep(steps.Count, "call", "ChangeFrontlineLimiter", new[] {
                new KismetExpr { Int = 777 }, new KismetExpr { Bool = remove }
            }, Array.Empty<int>(), null, null, -1, null, null));
        steps.Add(new KismetStep(steps.Count, "call", "SpawnCardInDeckBySide", new[] {
            new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
            new KismetExpr { Int = 20 }, new KismetExpr { Int = 1 }
        }, Array.Empty<int>(), null, null, -1, null, null));
        steps.Add(new KismetStep(steps.Count, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null));
        // These fixtures vary the program between cases. Evict only this local
        // cache entry and restore it on disposal, including prior audit probes.
        var cache = (Dictionary<string, Dictionary<string, KismetProgram>>)typeof(KismetLibrary)
            .GetField("_localCache", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance)!
            .GetValue(KismetLibrary.Default)!;
        KismetProgram? previous = null;
        if (cache.TryGetValue(name, out var programs)) programs.Remove(trigger, out previous);
        locals.Add(trigger, steps);
        return new AuditProbeCleanup(() => {
            locals.Remove(trigger);
            if (cache.TryGetValue(name, out var current))
            {
                current.Remove(trigger);
                if (previous is not null) current[trigger] = previous;
            }
        });
    }

    private static string? LimiterLocalReceiptIntegration(CardDatabase db)
    {
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int route in new[] { 0, 1, 2 })
        foreach (bool initiallyLimited in new[] { false, true })
        foreach (var removals in new[] { new[] { false }, new[] { true }, new[] { false, true }, new[] { true, false } })
        {
            string name = route == 0 ? "card_unit_typhoon_mk_ib" : route == 1 ? "card_unit_52_k" : "card_unit_m36_destroyer";
            using var probe = InstallLimiterReceiptProbe(name, route == 0 ? "OnEnterPlay" : route == 1 ? "OnHandTargetSelected" : "OnPlayedFromHand", removals);
            var (engine, state) = EmptyBoard(db);
            state.Turn = 7; state.ActiveSide = side;
            state.SetMaxKredits(side, 10); state.SetKredits(side, 10);
            if (initiallyLimited) state.FrontlineLimiters.Add(777);
            var source = state.CreateWithId(name, side, 20, route == 0 ? side.HandOf() : CardLocation.Discard, 0);
            if (route == 0)
            {
                source.Definition = new CardDefinition { Name = name, Type = "infantry", Attack = 2, Defense = 5 };
                source.Keywords.Clear(); source.Attack = 2; source.Defense = source.MaxDefense = 5; source.KreditCost = 0;
            }
            var target = state.CreateWithId("card_unit_432_infantry_regiment", side, 30, route == 2 ? side.DeckOf() : side.HandOf(), 0);
            var gotcha = state.CreateWithId("card_event_interception", side, 80, side.HandOf(), route == 0 ? 1 : 2);
            state.AddAutoPlayCards(gotcha.CardId);
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            int callbackCount = 0, admitted = 0; string? failure = null;
            var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name != "card_unit_routed_troops") return;
                callbackCount++;
                if (state.IsFrontlineLimited != initiallyLimited || gotcha.GotchaActivated != 0)
                    failure = "规则/选择回调看到尚未接收的更新";
                var result = engine.Api.InvokeByName("SpawnMultipleCardsOnBattlefield", source,
                    new object?[] { (int)side, true, Enumerable.Repeat(PlainUnit, 4).ToList(), source.CardId, false, null, false }, ctx, out _);
                admitted = result is List<int> ids ? ids.Count : -1;
                if (state.IsFrontlineLimited != initiallyLimited || gotcha.GotchaActivated != 0)
                    failure = "嵌套批量生成提前消费接收队列";
            };
            bool success;
            if (route == 0) success = engine.PlayCard(source);
            else if (route == 1)
            {
                engine.PickHandTargetId = (_, _) => target.CardId;
                engine.Api.InvokeByName("selectTargetFromHand", source, new object?[] { source.CardId }, ctx, out success);
            }
            else
            {
                source.ExtraPlayTriggers = 1;
                success = engine.Api.DrawChosenCardToHand(source, target) is not null;
            }
            bool expectedLimited = !removals[^1];
            var notices = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionUpdateFrontlineLimiter").ToArray();
            if (!success || failure is not null || callbackCount != 1 || admitted != (initiallyLimited ? 2 : 4)
                || state.IsFrontlineLimited != expectedLimited || gotcha.GotchaActivated != 1
                || state.GetAutoPlayCards().Length != 0 || notices.Length != removals.Length)
                return $"local receipt case={cases} {side}/{route}/{initiallyLimited}: {failure ?? "receipt/order/capacity"}, calls={callbackCount}, admitted={admitted}, limited={state.IsFrontlineLimited}, gotcha={gotcha.GotchaActivated}, notices={notices.Length}, values={string.Join(';', notices.Select(x => string.Join(',', x.Values)))}";
            int actionCount = state.ActionLog.Count;
            engine.ApplyPendingLocalRuleReceipts();
            if (state.IsFrontlineLimited != expectedLimited || gotcha.GotchaActivated != 1 || state.ActionLog.Count != actionCount)
                return "已消费的本地接收队列被重复应用";
            cases++;
        }
        return cases == 48 ? null : $"local receipt matrix count={cases}";
    }

    private static string? LimiterDeferredSelectionBoundary(CardDatabase db)
    {
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool firstRemove in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db);
            state.Turn = 2; state.ActiveSide = side;
            state.SetMaxKredits(side, 10); state.SetKredits(side, 10);
            if (firstRemove) state.FrontlineLimiters.Add(777);
            var source = state.CreateWithId("card_unit_gordon_highlanders", side, 20, side.HandOf(), 0);
            state.CreateWithId("card_unit_dornier_do_18g", side, 30, side.HqOf(), 1);
            var target = state.CreateWithId("card_event_convoy_175", side, 31, side.HandOf(), 1);
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            bool notified = false, answered = false, afterWait = false; string? failure = null;
            var moved = state.CardMoved;
            state.CardMoved = (card, oldLocation, newLocation, ownerChange, reason) => {
                if (card == source && oldLocation == side.HandOf() && newLocation == side.HqOf())
                {
                    notified = true;
                    engine.Api.InvokeByName("ChangeFrontlineLimiter", source, new object?[] { 777, firstRemove }, ctx, out _);
                    if (state.IsFrontlineLimited != firstRemove) failure = "最初出牌提前应用限制者";
                }
                if (card == source && newLocation == CardLocation.BoardFrontline)
                {
                    afterWait = true;
                    if (!answered || state.IsFrontlineLimited != !firstRemove) failure = "等待恢复前提前消费回复通知";
                }
                moved?.Invoke(card, oldLocation, newLocation, ownerChange, reason);
            };
            engine.PickHandTargetId = (_, _) => {
                answered = true;
                if (!notified || state.IsFrontlineLimited != !firstRemove) failure = "回复开始前尚未接收最初动作";
                engine.Api.InvokeByName("ChangeFrontlineLimiter", source, new object?[] { 777, !firstRemove }, ctx, out _);
                if (state.IsFrontlineLimited != !firstRemove) failure = "回复通知立即生效";
                return target.CardId;
            };
            bool success = engine.PlayCard(source);
            if (!success || !notified || !answered || !afterWait || failure is not null || state.IsFrontlineLimited != firstRemove)
                return $"deferred limiter {side}/{firstRemove}: {failure ?? "missing action/reply receipt"}, first={notified}, reply={answered}, wait={afterWait}, limited={state.IsFrontlineLimited}";
        }
        return null;
    }

    private static string? FrontlineLimiterContract(CardDatabase db)
    {
        int scenarios = 0, calls = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int argument in new[] { 0, -7, 777, 90 })
        foreach (int initial in new[] { 0, 1, 2 })
        {
            var (engine, state) = EmptyBoard(db);
            var source = state.CreateWithId(PlainUnit, side, 90, side.HandOf(), 0);
            var expected = new HashSet<int>();
            if (initial == 1) expected.Add(argument);
            if (initial == 2) expected.Add(888);
            state.FrontlineLimiters.UnionWith(expected);
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            foreach (bool remove in new[] { false, false, true, true })
            {
                int previous = state.ActionLog.SelectMany(x => x.SubActions).Count();
                engine.Api.InvokeByName("ChangeFrontlineLimiter", source,
                    new object?[] { argument == 90 ? source : argument, remove, null }, ctx, out bool handled);
                if (!state.FrontlineLimiters.SetEquals(expected))
                    return $"limiter changed during notification: id={argument}, remove={remove}";
                if (remove) expected.Remove(argument); else expected.Add(argument);
                var added = state.ActionLog.SelectMany(x => x.SubActions).Skip(previous).ToArray();
                var values = new[] { ActionValue2.Int("cardID", argument), ActionValue2.Int("instigatorID", argument), ActionValue2.Bool("remove", remove) };
                if (!handled || added.Length != 1 || added[0].Name != "ZActionUpdateFrontlineLimiter" || !added[0].Values.SequenceEqual(values))
                    return $"limiter contract scenario={scenarios}, id={argument}, remove={remove}, initial={initial}: set={string.Join(',', state.FrontlineLimiters)}, notifications={added.Length}";
                engine.ApplyPendingGotchaPlayReceipts();
                if (!state.FrontlineLimiters.SetEquals(expected) || state.FrontlineCapacity != (expected.Count > 0 ? 2 : 5))
                    return $"limiter receipt failed: id={argument}, remove={remove}";
                engine.ApplyPendingGotchaPlayReceipts();
                if (!state.FrontlineLimiters.SetEquals(expected) || state.ActionLog.SelectMany(x => x.SubActions).Count() != previous + 1)
                    return "second receipt drain changed state or emitted another notification";
                calls++;
            }
            scenarios++;
        }
        return scenarios == 24 && calls == 96 ? null : $"limiter matrix={scenarios}/{calls}";
    }

    private static string? DynamicBatchFrontlineLimit(CardDatabase db)
    {
        using var ownProbe = InstallEntryMethodProbe();
        const string name = "card_unit_typhoon_mk_ib";
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (int initial in new[] { 0, 1, 2 })
        foreach (int mutation in new[] { 0, 1, 2, 3 })
        foreach (bool duringCreation in new[] { false, true })
        foreach (int residents in new[] { 0, 1 })
        {
            var (engine, state) = EmptyBoard(db); state.Turn = 7;
            for (int i = 0; i < initial; i++) state.FrontlineLimiters.Add(101 + i);
            if (residents == 1) state.CreateWithId(PlainUnit, side, 70, CardLocation.BoardFrontline, 0);
            var source = state.CreateWithId(PlainUnit, side, 90, side.HandOf(), 0);
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            var initialSet = new HashSet<int>(state.FrontlineLimiters);
            var expectedSet = new HashSet<int>(state.FrontlineLimiters);
            if (mutation == 0) expectedSet.Add(101);
            if (mutation == 1) expectedSet.Add(103);
            if (mutation == 2) expectedSet.Remove(101);
            if (mutation == 3) { expectedSet.Remove(101); expectedSet.Remove(102); }
            int expectedCapacity = expectedSet.Count > 0 ? 2 : 5;
            int expectedCount = Math.Min(4, (initial > 0 ? 2 : 5) - residents);
            var spawned = new List<CardInstance>(); var entered = new HashSet<int>(); bool changed = false; string? failure = null;
            void Mutate()
            {
                changed = true;
                int batchNotices = state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionSpawnMultipleCards");
                if (batchNotices != (duringCreation ? 0 : 1)) failure = "限制变化相对批量通知的时机错误";
                if (mutation is 0 or 1)
                    engine.Api.InvokeByName("ChangeFrontlineLimiter", source, new object?[] { mutation == 0 ? 101 : 103, false, null }, ctx, out _);
                else
                {
                    engine.Api.InvokeByName("ChangeFrontlineLimiter", source, new object?[] { 101, true, null }, ctx, out _);
                    if (mutation == 3) engine.Api.InvokeByName("ChangeFrontlineLimiter", source, new object?[] { 102, true, null }, ctx, out _);
                }
                if (!state.FrontlineLimiters.SetEquals(initialSet)) failure = "生产通知时提前应用限制者";
            }
            var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name == name)
                {
                    if (!state.FrontlineLimiters.SetEquals(initialSet)) failure = "后续创建看到了尚未接收的限制者";
                    made.Definition = new CardDefinition { Name = name, Type = "infantry", Attack = 2, Defense = 5 };
                    made.Keywords.Clear(); made.Attack = 2; made.Defense = made.MaxDefense = 5; spawned.Add(made);
                    if (duringCreation && !changed) Mutate();
                }
                else if (made.Name == "card_unit_routed_troops")
                {
                    if (!state.FrontlineLimiters.SetEquals(initialSet)) failure = "进场时提前应用限制者";
                    var current = spawned.Where(x => !entered.Contains(x.CardId)
                        && Convert.ToInt32(x.BlueprintVariables.GetValueOrDefault("_auditEntryMethod")) == 3).ToArray();
                    if (current.Length != 1) { failure = "动态容量进场主体错误"; return; }
                    entered.Add(current[0].CardId);
                    if (!duringCreation && !changed) Mutate();
                }
            };
            var result = engine.Api.InvokeByName("SpawnMultipleCardsOnBattlefield", source,
                new object?[] { (int)side, true, Enumerable.Repeat(name, 4).ToList(), source.CardId, false, null, false }, ctx, out _);
            if (failure is not null || !changed || result is not List<int> ids || ids.Count != expectedCount
                || !ids.SequenceEqual(spawned.Select(x => x.CardId)) || entered.Count != expectedCount
                || !state.FrontlineLimiters.SetEquals(initialSet)
                || state.AllCards.Count(x => x.Location == CardLocation.BoardFrontline) != residents + expectedCount)
                return $"dynamic limiter case={cases} {side}/{initial}/{mutation}/{duringCreation}/{residents}: {failure ?? "capacity admission or retroactive truncation"}, spawned={spawned.Count}/{expectedCount}";
            engine.ApplyPendingGotchaPlayReceipts();
            if (!state.FrontlineLimiters.SetEquals(expectedSet) || state.FrontlineCapacity != expectedCapacity
                || state.AllCards.Count(x => x.Location == CardLocation.BoardFrontline) != residents + expectedCount)
                return $"limiter receipt altered admitted batch: case={cases}";
            cases++;
        }
        return cases == 96 ? null : $"dynamic limiter matrix count={cases}";
    }

    private static string? ReentrantObjectCreationBatch(CardDatabase db)
    {
        using var ownProbe = InstallEntryMethodProbe();
        const string name = "card_unit_typhoon_mk_ib";
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool outerFrontline in new[] { false, true })
        foreach (bool sameDestination in new[] { false, true })
        foreach (bool limited in new[] { false, true })
        foreach (int innerRequest in new[] { 1, 3 })
        foreach (bool changeSourceGold in new[] { false, true })
        foreach (bool blockOuterFrontline in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); state.Turn = 7;
            if (limited) state.FrontlineLimiters.Add(900001);
            var source = state.CreateWithId(PlainUnit, side, 90, side.HandOf(), 0, isGold: true);
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            bool innerFrontline = sameDestination ? outerFrontline : !outerFrontline;
            int frontCapacity = limited ? 2 : 5;
            int innerCapacity = innerFrontline ? frontCapacity : 5;
            int initialOuter = outerFrontline ? 0 : 1;
            int initialInner = sameDestination ? initialOuter + 1 : innerFrontline ? 0 : 1;
            int expectedInner = Math.Min(innerRequest, innerCapacity - initialInner);
            int expectedOuter = outerFrontline && blockOuterFrontline ? 1
                : Math.Min(3, (outerFrontline ? frontCapacity : 5) - initialOuter - (sameDestination ? expectedInner : 0));
            var outer = new List<CardInstance>(); var inner = new List<CardInstance>();
            var entered = new HashSet<CardInstance>(); var events = new List<(string Phase, int Id)>();
            bool inside = false, nested = false; List<int>? innerIds = null; string? failure = null;
            var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name == name)
                {
                    made.Definition = new CardDefinition { Name = name, Type = "infantry", Attack = 2, Defense = 5 };
                    made.Keywords.Clear(); made.Attack = 2; made.Defense = made.MaxDefense = 5;
                    (inside ? inner : outer).Add(made); events.Add(("create", made.CardId));
                    if (!nested)
                    {
                        nested = true;
                        if (outer.Count != 1 || made.EnteredPlayOnTurn != -1) failure = "创建回调重入应发生在首张进场回合设置之前";
                        if (changeSourceGold) source.IsGold = false;
                        inside = true;
                        var result = engine.Api.InvokeByName("SpawnMultipleCardsOnBattlefield", source,
                            new object?[] { (int)side, innerFrontline, Enumerable.Repeat(name, innerRequest).ToList(), source.CardId, false, null, false }, ctx, out _);
                        innerIds = result as List<int>; inside = false;
                        if (inner.Count != expectedInner || inner.Any(x => !entered.Contains(x))) failure = "创建阶段内层返回前未完成内层进场";
                        if (blockOuterFrontline && outerFrontline) state.FrontlineOwner = side.Opposite();
                    }
                }
                else if (made.Name == "card_unit_routed_troops")
                {
                    var hits = outer.Concat(inner).Where(x => !entered.Contains(x)
                        && Convert.ToInt32(x.BlueprintVariables.GetValueOrDefault("_auditEntryMethod")) == 3).ToArray();
                    if (hits.Length != 1) { failure = "创建重入进场主体不唯一"; return; }
                    var subject = hits[0]; entered.Add(subject); events.Add(("entry", subject.CardId));
                    int notices = state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionSpawnMultipleCards");
                    if (inside)
                    {
                        if (!inner.Contains(subject) || outer.Count != 1 || outer[0].EnteredPlayOnTurn != -1 || notices != 1)
                            failure = "内层进场前不应提前设置外层回合、发送外层通知或继续外层创建";
                    }
                    else if (!outer.Contains(subject) || notices != 2) failure = "外层进场应在内层返回和外层通知之后";
                }
            };
            var output = engine.Api.InvokeByName("SpawnMultipleCardsOnBattlefield", source,
                new object?[] { (int)side, outerFrontline, Enumerable.Repeat(name, 3).ToList(), source.CardId, false, null, false }, ctx, out _);
            var expectedEvents = new List<(string Phase, int Id)> { ("create", outer[0].CardId) };
            expectedEvents.AddRange(inner.Select(x => ("create", x.CardId)));
            expectedEvents.AddRange(inner.Select(x => ("entry", x.CardId)));
            expectedEvents.AddRange(outer.Skip(1).Select(x => ("create", x.CardId)));
            expectedEvents.AddRange(outer.Select(x => ("entry", x.CardId)));
            if (failure is not null || output is not List<int> ids || !ids.SequenceEqual(outer.Select(x => x.CardId))
                || innerIds is null || !innerIds.SequenceEqual(inner.Select(x => x.CardId))
                || outer.Count != expectedOuter || inner.Count != expectedInner || !events.SequenceEqual(expectedEvents)
                || entered.Count != expectedOuter + expectedInner || outer.Any(x => !x.IsGold || x.EnteredPlayOnTurn != 7)
                || inner.Any(x => x.IsGold == changeSourceGold || x.EnteredPlayOnTurn != 7))
                return $"OnCreate batch case={cases} {side}/{outerFrontline}/{sameDestination}/{limited}/{innerRequest}/{changeSourceGold}/{blockOuterFrontline}: {failure ?? "admission/gold snapshot/interleaving"}; outer={outer.Count}/{expectedOuter}, inner={inner.Count}/{expectedInner}";
            var notifications = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionSpawnMultipleCards").ToArray();
            if (notifications.Length != 2
                || notifications[0].Values.Single(x => x.Name == "cardIDs").Text != string.Join(";", innerIds)
                || notifications[1].Values.Single(x => x.Name == "cardIDs").Text != string.Join(";", ids)
                || notifications[0].Values.Single(x => x.Name == "cardTypes").Text != string.Join(";", Enumerable.Repeat(name, innerRequest))
                || notifications[1].Values.Single(x => x.Name == "cardTypes").Text != string.Join(";", Enumerable.Repeat(name, 3)))
                return $"OnCreate batch case={cases}: inner-first notification order or requested names/results mixed";
            cases++;
        }
        return cases == 128 ? null : $"OnCreate batch matrix count={cases}";
    }

    private static string? BatchCreationTurnLookup(CardDatabase db)
    {
        using var ownProbe = InstallEntryMethodProbe();
        const string name = "card_unit_typhoon_mk_ib";
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool frontline in new[] { false, true })
        foreach (int mutation in new[] { 0, 1, 2 })
        foreach (bool oppositeOwner in new[] { false, true })
        foreach (bool discard in new[] { false, true })
        foreach (int count in new[] { 2, 3 })
        {
            var (engine, state) = EmptyBoard(db); state.Turn = 7;
            var location = frontline ? CardLocation.BoardFrontline : side.HqOf();
            var source = state.CreateWithId(PlainUnit, side, 90, side.HandOf(), 0, isGold: true);
            var originals = new List<CardInstance>(); var replaced = new HashSet<int>(); var entered = new HashSet<int>();
            bool replacing = false; string? failure = null;
            var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name == name && !replacing)
                {
                    originals.Add(made); made.CardSeen = true;
                    made.Definition = new CardDefinition { Name = name, Type = "infantry", Attack = 2, Defense = 5 };
                    made.Keywords.Clear(); made.Attack = 2; made.Defense = made.MaxDefense = 5;
                    if (mutation == 2 || (mutation == 1 && originals.Count == 1))
                    {
                        int id = made.CardId; state.Remove(made); replacing = true;
                        var replacement = state.CreateWithId(name, oppositeOwner ? side.Opposite() : side, id,
                            discard ? CardLocation.Discard : location, 17);
                        replacing = false;
                        replacement.Definition = new CardDefinition { Name = name, Type = "infantry", Attack = 2, Defense = 5 };
                        replacement.Keywords.Clear(); replacement.Attack = 2; replacement.Defense = replacement.MaxDefense = 5;
                        replacement.EnteredPlayOnTurn = 41; replacement.CardSeen = true; replacement.IsGold = false;
                        replaced.Add(id);
                    }
                }
                else if (made.Name == "card_unit_routed_troops")
                {
                    var current = originals.Select(x => state.ById(x.CardId)!).Where(x => !entered.Contains(x.CardId)
                        && Convert.ToInt32(x.BlueprintVariables.GetValueOrDefault("_auditEntryMethod")) == 3).ToArray();
                    if (current.Length != 1) { failure = "进场回调主体计数错误"; return; }
                    var subject = current[0]; entered.Add(subject.CardId);
                    if (originals.Count != count || subject.EnteredPlayOnTurn != 7)
                        failure = $"创建后应重取映射对象设置进场回合，实际={subject.EnteredPlayOnTurn}";
                }
            };
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            var result = engine.Api.InvokeByName("SpawnMultipleCardsOnBattlefield", source,
                new object?[] { (int)side, frontline, Enumerable.Repeat(name, count).ToList(), source.CardId, false, null, false }, ctx, out _);
            if (failure is not null || result is not List<int> ids || !ids.SequenceEqual(originals.Select(x => x.CardId)) || entered.Count != count)
                return $"creation turn lookup case={cases} {side}/{frontline}/{mutation}/{oppositeOwner}/{discard}/{count}: {failure ?? "result/entry identity"}";
            foreach (var original in originals)
            {
                var current = state.ById(original.CardId)!; bool wasReplaced = replaced.Contains(original.CardId);
                if (current.EnteredPlayOnTurn != 7 || original.EnteredPlayOnTurn != (wasReplaced ? -1 : 7)
                    || original.CardSeen || current.CardSeen != wasReplaced || current.IsGold == wasReplaced)
                    return $"creation turn lookup case={cases}: mapped turn vs retained CreateCard cardSeen receiver incorrect";
                if (wasReplaced && (current.Owner != (oppositeOwner ? side.Opposite() : side)
                    || current.Location != (discard ? CardLocation.Discard : location)))
                    return $"creation turn lookup case={cases}: replacement owner/location overwritten";
            }
            cases++;
        }
        return cases == 96 ? null : $"creation turn lookup matrix count={cases}";
    }

