                else if (made.Name == "card_unit_routed_troops")
                {
                    int notifications = state.ActionLog.SelectMany(x => x.SubActions).Count(x => x.Name == "ZActionSpawnMultipleCards");
                    var hits = new[] { first, later }.Where(x => Convert.ToInt32(x.BlueprintVariables.GetValueOrDefault("_auditBatchSnapshotCount")) > seen.GetValueOrDefault(x)).ToArray();
                    if (hits.Length == 1)
                    {
                        var receiver = hits[0]; seen[receiver] = Convert.ToInt32(receiver.BlueprintVariables["_auditBatchSnapshotCount"]);
                        if (receiver.BlueprintVariables.GetValueOrDefault("_auditBatchSnapshotSubject") is not CardInstance subject
                            || Convert.ToInt32(receiver.BlueprintVariables.GetValueOrDefault("_auditBatchSnapshotMethod")) != 3)
                        { failure = "重入T35主体或method3错误"; return; }
                        events.Add(("T35", subject.CardId, receiver.CardId));
                        if (!nested)
                        {
                            nested = true;
                            if (receiver != first || outer.Count != outerCount || notifications != 1) failure = "重入前必须已创建全部外层卡并发一次外层通知";
                            if (mutation == 1) later.Keywords.Add(Keyword.Suppressed);
                            if (mutation == 2) later.Definition = new CardDefinition { Name = probe };
                            inside = true;
                            var result = engine.Api.InvokeByName("SpawnMultipleCardsOnBattlefield", source,
                                new object?[] { (int)side, innerFrontline, Enumerable.Repeat(name, innerRequest).ToList(), source.CardId, false, null, false }, ctx, out _);
                            innerIds = result as List<int>; inside = false;
                            if (inner.Count != innerExpected || inner.Any(x => !entered.Contains(x))) failure = "内层调用返回前应完成全部实际生成卡的进场";
                        }
                        else if (notifications != 2) failure = "内层及外层后续回调前应已有两条批量通知";
                    }
                    else if (hits.Length == 0)
                    {
                        var own = outer.Concat(inner).Where(x => !entered.Contains(x)
                            && Convert.ToInt32(x.BlueprintVariables.GetValueOrDefault("_auditEntryMethod")) == 3).ToArray();
                        if (own.Length != 1) { failure = "重入进场主体不唯一"; return; }
                        entered.Add(own[0]); events.Add(("entry", own[0].CardId, own[0].CardId));
                        if (notifications != 2) failure = "进场前缺少内外批量通知";
                    }
                    else failure = "重入观察计数无法分辨";
                }
            };
            var output = engine.Api.InvokeByName("SpawnMultipleCardsOnBattlefield", source,
                new object?[] { (int)side, outerFrontline, Enumerable.Repeat(name, outerCount).ToList(), source.CardId, false, null, false }, ctx, out _);
            bool eligibleLater = mutation == 0 || (mutation == 1 && exception);
            var expected = outer.Select(x => ("create", x.CardId, 0)).ToList();
            expected.Add(("T35", outer[0].CardId, 20));
            expected.AddRange(inner.Select(x => ("create", x.CardId, 0)));
            foreach (var card in inner)
            {
                expected.Add(("T35", card.CardId, 20));
                if (eligibleLater) expected.Add(("T35", card.CardId, 21));
                expected.Add(("entry", card.CardId, card.CardId));
            }
            expected.Add(("T35", outer[0].CardId, 21)); // retained outer snapshot
            expected.Add(("entry", outer[0].CardId, outer[0].CardId));
            foreach (var card in outer.Skip(1))
            {
                expected.Add(("T35", card.CardId, 20));
                if (eligibleLater) expected.Add(("T35", card.CardId, 21));
                expected.Add(("entry", card.CardId, card.CardId));
            }
            if (failure is not null || !nested || output is not List<int> ids || !ids.SequenceEqual(outer.Select(x => x.CardId))
                || innerIds is null || !innerIds.SequenceEqual(inner.Select(x => x.CardId)) || innerIds.Count != innerExpected
                || !events.SequenceEqual(expected) || entered.Count != outerCount + innerExpected
                || outer.Concat(inner).Any(x => !x.IsGold || x.EnteredPlayOnTurn != 7))
                return $"reentrant batch case={cases} {side}/{outerFrontline}/{sameDestination}/{outerCount}/{innerRequest}/{mutation}/{exception}: {failure ?? "interleaving/snapshot/result isolation"}; inner={inner.Count}/{innerExpected}";
            var notices = state.ActionLog.SelectMany(x => x.SubActions).Where(x => x.Name == "ZActionSpawnMultipleCards").ToArray();
            if (notices.Length != 2 || notices[0].Values.Single(x => x.Name == "cardIDs").Text != string.Join(";", ids)
                || notices[1].Values.Single(x => x.Name == "cardIDs").Text != string.Join(";", innerIds))
                return $"reentrant batch case={cases}: inner/outer notification IDs mixed";
            cases++;
        }
        return cases == 192 ? null : $"reentrant batch matrix count={cases}";
    }

    private static string? BatchCreationToEntryBoundary(CardDatabase db)
    {
        using var creationProbe = InstallBatchCreationSnapshotProbe();
        using var ownProbe = InstallEntryMethodProbe();
        using var entryProbe = InstallEntrySubjectObservers(includeSubject: false);
        const string name = "card_unit_typhoon_mk_ib", probe = "card_unit_brewster_f2a", t35 = "OnOtherCardCreatedAlterCard", t43 = "OnOtherCardEnterPlay";
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool frontline in new[] { false, true })
        foreach (int count in new[] { 2, 3 })
        foreach (int subjectMutation in new[] { 0, 1, 2 })
        foreach (int observerMutation in new[] { 0, 1, 2, 3 })
        foreach (bool observerException in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); state.Turn = 7;
            var creator = state.CreateWithId(probe, side, 20, side.DeckOf(), 0);
            creator.Keywords.Clear(); creator.Definition = new CardDefinition { Name = probe, UsedTriggers = new[] { t35 } };
            var observer = state.CreateWithId(probe, side.Opposite(), 21, CardLocation.NotAvailable, 0);
            observer.Keywords.Clear();
            observer.Definition = new CardDefinition { Name = probe, UsedTriggers = observerMutation == 3 ? Array.Empty<string>() : new[] { t43 } };
            if (observerException) observer.SuppressionExceptionTriggers.Add(t43);
            var source = state.CreateWithId(PlainUnit, side, 90, side.HandOf(), 0);
            int createdCount = 0, enteredCount = 0, ownCount = 0;
            var spawned = new List<CardInstance>(); var calls = new List<(int Phase, int Subject)>(); string? failure = null;
            var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name == name)
                {
                    made.Definition = new CardDefinition { Name = name, Type = "infantry", Attack = 2, Defense = 5 };
                    made.Keywords.Clear(); made.Attack = 2; made.Defense = made.MaxDefense = 5;
                    if (subjectMutation == 2) made.Keywords.Add(Keyword.Suppressed);
                    made.SuppressionExceptionTriggers.Add("OnEnterPlay"); spawned.Add(made);
                }
                else if (made.Name == "card_unit_routed_troops")
                {
                    int creationSerial = Convert.ToInt32(creator.BlueprintVariables.GetValueOrDefault("_auditBatchSnapshotCount"));
                    int entrySerial = Convert.ToInt32(observer.BlueprintVariables.GetValueOrDefault("_auditBatchEntrySnapshotCount"));
                    if (creationSerial > createdCount)
                    {
                        createdCount = creationSerial;
                        if (creator.BlueprintVariables.GetValueOrDefault("_auditBatchSnapshotSubject") is not CardInstance subject)
                        { failure = "T35主体丢失"; return; }
                        if (spawned.Count != count || Convert.ToInt32(creator.BlueprintVariables.GetValueOrDefault("_auditBatchSnapshotMethod")) != 3)
                            failure = "T35必须在完整批次之后，method3";
                        calls.Add((35, subject.CardId));
                        if (subjectMutation == 1) subject.Keywords.Add(Keyword.Suppressed);
                        if (subjectMutation == 2) subject.Keywords.Remove(Keyword.Suppressed);
                        if (observerMutation == 1) observer.Keywords.Add(Keyword.Suppressed);
                        if (observerMutation == 2) observer.Definition = new CardDefinition { Name = probe };
                        if (observerMutation == 3) observer.Definition = new CardDefinition { Name = probe, UsedTriggers = new[] { t43 } };
                    }
                    else if (entrySerial > enteredCount)
                    {
                        enteredCount = entrySerial;
                        if (observer.BlueprintVariables.GetValueOrDefault("_auditBatchEntrySnapshotSubject") is not CardInstance subject
                            || Convert.ToInt32(observer.BlueprintVariables.GetValueOrDefault("_auditBatchEntrySnapshotMethod")) != 3)
                        { failure = "T43主体或method丢失"; return; }
                        calls.Add((43, subject.CardId));
                    }
                    else
                    {
                        if (ownCount >= spawned.Count || Convert.ToInt32(spawned[ownCount].BlueprintVariables.GetValueOrDefault("_auditEntryMethod")) != 3)
                        { failure = "自身进场计数或method错误"; return; }
                        calls.Add((0, spawned[ownCount++].CardId));
                    }
                }
            };
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            var result = engine.Api.InvokeByName("SpawnMultipleCardsOnBattlefield", source,
                new object?[] { (int)side, frontline, Enumerable.Repeat(name, count).ToList(), source.CardId, false, null, false }, ctx, out _);
            var expected = new List<(int Phase, int Subject)>();
            bool receivesOther = observerMutation != 2 && (observerMutation != 1 || observerException);
            foreach (var subject in spawned)
            {
                expected.Add((35, subject.CardId));
                if (subjectMutation != 1) expected.Add((0, subject.CardId));
                if (receivesOther) expected.Add((43, subject.CardId));
            }
            if (failure is not null || result is not List<int> ids || ids.Count != count || createdCount != count
                || enteredCount != (receivesOther ? count : 0) || ownCount != (subjectMutation == 1 ? 0 : count)
                || !calls.SequenceEqual(expected))
                return $"T35 to entry case={cases} {side}/{frontline}/{count}/{subjectMutation}/{observerMutation}/{observerException}: {failure ?? "phase/query state"}; got={string.Join(',', calls)}, expected={string.Join(',', expected)}";
            cases++;
        }
        return cases == 192 ? null : $"T35 to entry matrix count={cases}";
    }

    private static string? BatchSpawnEntrySnapshots(CardDatabase db)
    {
        using var entry = InstallEntryMethodProbe();
        const string probe = "card_unit_brewster_f2a", spawnedName = "card_unit_typhoon_mk_ib", trigger = "OnOtherCardEnterPlay";
        using var observersProbe = InstallEntrySubjectObservers(includeSubject: false);
        int cases = 0;
        foreach (var side in new[] { Side.Left, Side.Right })
        foreach (bool frontline in new[] { false, true })
        foreach (int count in new[] { 2, 3 })
        foreach (int beforeQuery in Enumerable.Range(0, 3))
        foreach (int mutation in Enumerable.Range(0, 4))
        foreach (bool lateRegistration in new[] { false, true })
        {
            var (engine, state) = EmptyBoard(db); state.Turn = 7;
            CardDefinition Registered() => new() { Name = probe, Type = "fighter", UsedTriggers = new[] { trigger } };
            var first = state.CreateWithId(probe, side, 20, side.DeckOf(), 0);
            var later = state.CreateWithId(probe, side.Opposite(), 21, CardLocation.Discard, 17);
            foreach (var card in new[] { first, later }) { card.Definition = Registered(); card.Keywords.Clear(); }
            if (beforeQuery == 2) later.Keywords.Add(Keyword.Suppressed);
            var source = state.CreateWithId(PlainUnit, side, 90, side.HandOf(), 0);
            var observers = new List<CardInstance> { first, later };
            var seenCounts = new Dictionary<int, int>(); var calls = new List<(int Receiver, int Subject)>();
            var spawned = new List<CardInstance>(); bool changed = false; int ownCalls = 0; string? failure = null;
            var created = state.CardCreated;
            state.CardCreated = made => {
                created?.Invoke(made);
                if (made.Name == spawnedName)
                {
                    made.Definition = new CardDefinition { Name = spawnedName, Type = "infantry", Attack = 2, Defense = 5 };
                    made.Keywords.Clear(); made.Attack = 2; made.Defense = made.MaxDefense = 5; spawned.Add(made);
                }
                else if (made.Name == "card_unit_routed_troops")
                {
                    var hits = observers.Where(x => Convert.ToInt32(x.BlueprintVariables.GetValueOrDefault("_auditBatchEntrySnapshotCount"))
                        > seenCounts.GetValueOrDefault(x.CardId)).ToArray();
                    if (hits.Length == 0)
                    {
                        // Own OnEnterPlay marker runs before the T43 query.
                        if (ownCalls >= spawned.Count || Convert.ToInt32(spawned[ownCalls].BlueprintVariables.GetValueOrDefault("_auditEntryMethod")) != 3)
                        { failure = "进场自身探针主体或method错误"; return; }
                        calls.Add((0, spawned[ownCalls].CardId));
                        if (ownCalls == 0)
                        {
                            if (beforeQuery == 1) later.Keywords.Add(Keyword.Suppressed);
                            if (beforeQuery == 2) later.SuppressionExceptionTriggers.Add(trigger);
                        }
                        ownCalls++; return;
                    }
                    if (hits.Length != 1) { failure = "T43探针应每次只增加一个接收者计数"; return; }
                    var receiver = hits[0]; seenCounts[receiver.CardId] = Convert.ToInt32(receiver.BlueprintVariables["_auditBatchEntrySnapshotCount"]);
                    if (receiver.BlueprintVariables.GetValueOrDefault("_auditBatchEntrySnapshotSubject") is not CardInstance subject
                        || Convert.ToInt32(receiver.BlueprintVariables.GetValueOrDefault("_auditBatchEntrySnapshotMethod")) != 3)
                    { failure = "批量T43主体或method=3丢失"; return; }
                    calls.Add((receiver.CardId, subject.CardId));
                    if (!changed)
                    {
                        changed = true;
                        if (spawned.Count != count || receiver != first || subject != spawned[0]) failure = "首个T43必须在整个批次创建完成后运行";
                        if (mutation == 1) later.Keywords.Add(Keyword.Suppressed);
                        if (mutation == 2) later.Definition = new CardDefinition { Name = probe };
                        if (mutation == 3) state.Remove(later);
                        if (lateRegistration)
                        {
                            var late = state.CreateWithId(probe, side, 22, CardLocation.NotAvailable, 0);
                            late.Keywords.Clear(); late.Definition = Registered(); observers.Add(late);
                        }
                    }
                }
            };
            var ctx = new EffectContext { Engine = engine, State = state, Self = source, Controller = side };
            var result = engine.Api.InvokeByName("SpawnMultipleCardsOnBattlefield", source,
                new object?[] { (int)side, frontline, Enumerable.Repeat(spawnedName, count).ToList(), source.CardId, false, null, false }, ctx, out _);
            var expected = new List<(int Receiver, int Subject)>();
            for (int i = 0; i < spawned.Count; i++)
            {
                expected.Add((0, spawned[i].CardId));
                expected.Add((20, spawned[i].CardId));
                bool initiallyEligible = beforeQuery != 1;
                bool receivesLater = i == 0 ? initiallyEligible
                    : mutation == 0 ? initiallyEligible : mutation == 1 && beforeQuery == 2;
                if (receivesLater) expected.Add((21, spawned[i].CardId));
                if (i > 0 && lateRegistration) expected.Add((22, spawned[i].CardId));
            }
            if (failure is not null || !changed || ownCalls != count || result is not List<int> ids || ids.Count != count || !calls.SequenceEqual(expected))
                return $"batch T43 snapshot case={cases} {side}/{frontline}/{count}/{beforeQuery}/{mutation}/{lateRegistration}: {failure ?? "recipient/query boundary"}; got={string.Join(',', calls)}, expected={string.Join(',', expected)}";
            cases++;
        }
        return cases == 192 ? null : $"batch T43 snapshot matrix count={cases}";
    }

    private static IDisposable InstallBatchCreationSnapshotProbe()
    {
        const string probe = "card_unit_brewster_f2a", spawnedName = "card_unit_typhoon_mk_ib", trigger = "OnOtherCardCreatedAlterCard";
        if (KismetLibrary.Default?.Find(probe)?.Locals is not IDictionary<string, IReadOnlyList<KismetStep>> locals
            || KismetLibrary.Default.FindProgram(probe, trigger) is not null) throw new InvalidOperationException("无法安全安装批量T35快照探针");
        // Ignore marker cards so nested probe creation cannot recursively trigger itself.
        locals.Add(trigger, new[] {
            new KismetStep(0, "jumpIfNot", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null,
                new KismetExpr { Math = "EqualEqual_NameName", Args = new[] {
                    new KismetExpr { Var = "name", Context = new KismetExpr { Var = "K2Node_Event_cardPlayed" } },
                    new KismetExpr { Name = spawnedName } } }, 6, null, null),
            new KismetStep(1, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "K2Node_Event_cardPlayed" }, null, -1, "_auditBatchSnapshotSubject", null) { DestinationScope = "instance" },
            new KismetStep(2, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Var = "K2Node_Event_method" }, null, -1, "_auditBatchSnapshotMethod", null) { DestinationScope = "instance" },
            new KismetStep(3, "set", null, Array.Empty<KismetExpr>(), Array.Empty<int>(),
                new KismetExpr { Math = "Add_IntInt", Args = new[] {
                    new KismetExpr { Var = "_auditBatchSnapshotCount", Scope = "instance" }, new KismetExpr { Int = 1 } } },
                null, -1, "_auditBatchSnapshotCount", null) { DestinationScope = "instance" },
            new KismetStep(4, "call", "SpawnCardInDeckBySide", new[] {
                new KismetExpr { Int = (int)Side.Right }, new KismetExpr { Str = "card_unit_routed_troops" },
                new KismetExpr { Int = 30 }, new KismetExpr { Int = 1 } }, Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(5, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
            new KismetStep(6, "return", null, Array.Empty<KismetExpr>(), Array.Empty<int>(), null, null, -1, null, null),
        });
        return new AuditProbeCleanup(() => locals.Remove(trigger));
    }

